insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-c13af512fd', 'pharm-antiretroviral-i', 'mcq', 'Which antiretroviral drug can also be used in the management of hepatitis B?', '["Lamivudine", "Enfuvirtide", "Zidovudine", "Dolutegravir", "Abacavir"]'::jsonb, 'Lamivudine', '[]'::jsonb, 'Lamivudine inhibits the reverse transcriptase of HIV and the DNA polymerase of hepatitis B virus, so it treats both. Tenofovir and emtricitabine share this dual activity. Zidovudine and abacavir are also nucleoside analogues but have no useful activity against hepatitis B.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.004 Q1, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-f3a4268d26', 'pharm-antibody-preparations', 'mcq', 'Hyperimmune globulin (immunoglobulin) preparations are used in the treatment of the following conditions except:', '["Idiopathic thrombocytopenic purpura", "Asthma", "Guillain-Barré syndrome", "Rheumatic heart disease", "Systemic lupus erythematosus"]'::jsonb, 'Rheumatic heart disease', '[]'::jsonb, 'Intravenous immunoglobulin is an immunomodulator used in autoimmune and inflammatory disorders such as immune thrombocytopenic purpura, Guillain-Barré syndrome, refractory lupus and, in standard lecture lists, severe asthma. Rheumatic heart disease is managed with penicillin prophylaxis and cardiac care, not immunoglobulin.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.005 Q2, CAT 1 2022/2023. The stem says ''hyperimmune globulin'' but the options fit intravenous immunoglobulin (IVIG); asthma is in Katzung''s list of IVIG uses but is not an established indication, so the intended answer is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-immunomodulants-i-844944c207', 'pharm-immunomodulants-i', 'mcq', 'Which immunomodulant was also used as an anthelmintic drug?', '["Levamisole", "Praziquantel", "Anti-Rho(D) immunoglobulin", "Antithymocyte globulin", "BCG"]'::jsonb, 'Levamisole', '[]'::jsonb, 'Levamisole was introduced as an anthelmintic for roundworm (it paralyses the worm through nicotinic receptor stimulation) and was later found to restore depressed T-cell and macrophage function, hence its use as an immunostimulant. Praziquantel is an anthelmintic with no immunomodulant use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.006 Q3, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-81a02b9953', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which opioid is not appropriately matched with its chemical class?', '["Methadone: Diphenylheptane", "Levorphanol: Phenanthrene", "Pentazocine: Benzomorphan", "Nalbuphine: Phenylpropylamine", "Meperidine: Phenylpiperidine"]'::jsonb, 'Nalbuphine: Phenylpropylamine', '[]'::jsonb, 'Nalbuphine is a phenanthrene (morphine-like) derivative, structurally related to oxymorphone and naloxone. Methadone is a diphenylheptane (phenylheptylamine), pentazocine a benzomorphan and meperidine (pethidine) a phenylpiperidine. Levorphanol is a morphinan, which is a phenanthrene-type ring system, so that pairing is acceptable.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.007 Q4, CAT 1 2022/2023. Levorphanol is strictly a morphinan (a phenanthrene derivative); the nalbuphine pairing is the clearly wrong one.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-63b9d68d97', 'pharm-biologic-dmards', 'mcq', 'Which drug interrupts the JAK-STAT signalling pathway?', '["Abatacept", "Infliximab", "Tofacitinib", "Rituximab", "Methotrexate"]'::jsonb, 'Tofacitinib', '[]'::jsonb, 'Tofacitinib is an oral Janus kinase (JAK1/JAK3) inhibitor, so cytokine receptors can no longer phosphorylate STAT proteins and drive inflammatory gene transcription. Abatacept blocks T-cell co-stimulation, infliximab neutralises TNF-alpha and rituximab depletes CD20 B cells.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.008 Q5, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-3eee2e232e', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'The following increase renal excretion of uric acid except:', '["Sulfisoxazole", "Probenecid", "Benzbromarone", "High-dose aspirin", "Lesinurad"]'::jsonb, 'Sulfisoxazole', '[]'::jsonb, 'Sulfisoxazole is an antibacterial sulfonamide with no uricosuric action (do not confuse it with sulfinpyrazone). Probenecid, benzbromarone and lesinurad block URAT1-mediated urate reabsorption in the proximal tubule, and aspirin above about 4 g/day is also uricosuric, although low doses retain urate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.009 Q6, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-710df0e51c', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is the false statement about atovaquone?', '["Can be used as an alternative therapy for Pneumocystis pneumonia", "Used in chemoprophylaxis of malaria", "It disrupts the plasmodial mitochondrial electron transport system", "It is a hydroxynaphthoquinone molecule", "Eliminated unchanged in urine"]'::jsonb, 'Eliminated unchanged in urine', '[]'::jsonb, 'Atovaquone is highly protein bound, is not metabolised and is eliminated almost entirely unchanged in the faeces; less than 1% appears in urine. It is a hydroxynaphthoquinone that blocks the parasite cytochrome bc1 complex, and is used with proguanil for malaria and as an alternative for Pneumocystis pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.010 Q7, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-f4a9d3a935', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which statement regarding colchicine is false?', '["Inhibits production of interleukin-1β", "Absorption is affected by food", "Is a substrate of the P-glycoprotein pump", "Has a large volume of distribution", "Undergoes significant enterohepatic circulation"]'::jsonb, 'Absorption is affected by food', '[]'::jsonb, 'Colchicine is absorbed rapidly after an oral dose and food does not meaningfully change the amount absorbed. It is a P-glycoprotein and CYP3A4 substrate, distributes widely into tissues, and is recycled through bile, which explains its gut toxicity. By disrupting microtubules it blocks inflammasome activation and interleukin-1β release.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.011 Q8, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-68cb1d84ce', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'Which disease-modifying antirheumatic drug (DMARD) has not been proven to be effective in the treatment of rheumatoid arthritis?', '["Cyclophosphamide", "Sulfasalazine", "Mycophenolate mofetil", "Tacrolimus", "Leflunomide"]'::jsonb, 'Mycophenolate mofetil', '[]'::jsonb, 'Mycophenolate mofetil is valuable in lupus nephritis and vasculitis, but controlled trials have not established efficacy in rheumatoid arthritis, where it is only occasionally helpful. Sulfasalazine and leflunomide are standard DMARDs, and oral cyclophosphamide and tacrolimus have shown benefit in trials.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.012 Q9, CAT 1 2022/2023. Based on Katzung''s wording for mycophenolate (''no well-controlled data'' in RA); cyclophosphamide and tacrolimus are rarely used in RA, so the intended answer is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-8e1348ae9b', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which one of the following conventional synthetic DMARDs can safely be used in pregnancy?', '["Gold salts", "Cyclophosphamide", "Hydroxychloroquine", "Mycophenolate mofetil", "Methotrexate"]'::jsonb, 'Hydroxychloroquine', '[]'::jsonb, 'Hydroxychloroquine is not associated with fetal malformations at antirheumatic doses and is continued through pregnancy, particularly in lupus. Methotrexate, cyclophosphamide and mycophenolate are teratogenic and must be stopped before conception.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.013 Q10, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-544420cad3', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which one of the following DMARDs may cause retinopathy?', '["Azathioprine", "Hydroxychloroquine", "Penicillamine", "Leflunomide", "Cyclosporine"]'::jsonb, 'Hydroxychloroquine', '[]'::jsonb, 'Hydroxychloroquine and chloroquine bind melanin in the retinal pigment epithelium and with long-term use can cause irreversible ''bull''s eye'' maculopathy, so regular eye examinations are needed. The main toxicities of the others are marrow suppression (azathioprine), proteinuria (penicillamine), hepatotoxicity (leflunomide) and nephrotoxicity (cyclosporine).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.014 Q11, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-74d3fb77f4', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which drug does not prolong bleeding time?', '["Paracetamol", "Tolmetin", "Ketorolac", "Ibuprofen", "Aspirin"]'::jsonb, 'Paracetamol', '[]'::jsonb, 'Paracetamol is a weak inhibitor of peripheral cyclooxygenase and does not reduce platelet thromboxane A2 synthesis, so platelet aggregation and bleeding time are unchanged. Aspirin (irreversibly) and the other NSAIDs (reversibly) inhibit platelet COX-1 and prolong bleeding time.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.015 Q12, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-edd1073000', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'All of the following are true of sirolimus except:', '["Inhibits calcineurin", "Its bioavailability is altered by fatty meals", "Has anticancer effects", "Used to prevent organ transplant rejection", "Causes hypokalaemia"]'::jsonb, 'Inhibits calcineurin', '[]'::jsonb, 'Sirolimus binds FKBP-12 like tacrolimus, but the complex inhibits mTOR, blocking the T-cell response to interleukin-2; it does not inhibit calcineurin. mTOR inhibition also gives antiproliferative, anticancer activity. Hypokalaemia, hyperlipidaemia and myelosuppression are recognised adverse effects.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.016 Q13, CAT 1 2022/2023. Reworded option b: the paper says ''Peak concentration is increased by fatty meals'', which is itself inaccurate (a fatty meal lowers Cmax but raises AUC), so the original had two false statements.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-750eb4e851', 'pharm-biologic-dmards', 'mcq', 'The risk of infections and tumours is increased by:', '["Minocycline", "Infliximab", "Isoniazid", "Chloroquine", "Adefovir"]'::jsonb, 'Infliximab', '[]'::jsonb, 'Infliximab neutralises TNF-alpha, a cytokine needed for granuloma maintenance and tumour surveillance. Treatment therefore increases serious infections, notably reactivation of latent tuberculosis, and is linked with lymphoma and skin cancers. The other drugs are antimicrobials without significant immunosuppressive action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.017 Q14, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-8f716a7070', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Methotrexate is useful in the treatment of rheumatoid arthritis via the following mechanisms except:', '["Inhibition of AICAR transformylase", "Increasing levels of adenosine", "Inhibition of macrophage apoptosis", "Inhibition of dihydrofolate reductase", "Inhibition of neutrophil chemotaxis"]'::jsonb, 'Inhibition of macrophage apoptosis', '[]'::jsonb, 'Low-dose methotrexate inhibits AICAR transformylase, so AICAR accumulates and extracellular adenosine, a potent anti-inflammatory mediator, rises. This suppresses neutrophil chemotaxis and macrophage and lymphocyte function. It promotes, rather than inhibits, apoptosis of activated immune cells; dihydrofolate reductase inhibition contributes a little.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.018 Q15, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-7ae3e2a29d', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which one of the following is a causal prophylactic against malaria?', '["Chloroquine", "Mefloquine", "Proguanil", "Sulfadoxine-pyrimethamine (Fansidar)", "Doxycycline"]'::jsonb, 'Proguanil', '[]'::jsonb, 'Causal prophylactics kill the parasite in its primary liver stage, before blood infection. Proguanil (and primaquine and atovaquone) do this for Plasmodium falciparum. Chloroquine, mefloquine and doxycycline are suppressive prophylactics: they act on blood schizonts and must be continued for four weeks after leaving the endemic area.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.020 Q17, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-77b993973d', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'All of the following are true of methadone except:', '["Half-life is 8-12 hours", "Tolerance and dependence develop much more slowly than for morphine", "Can be given IM and SC", "Oral bioavailability is higher than that of morphine", "A potent μ receptor agonist"]'::jsonb, 'Half-life is 8-12 hours', '[]'::jsonb, 'Methadone has a long and variable half-life of about 24 to 36 hours (range 15 to 60), which permits once-daily dosing in maintenance programmes and gives a mild, prolonged withdrawal. It is a potent mu agonist with high oral bioavailability, and tolerance and physical dependence develop more slowly than with morphine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.021 Q18, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-e897a6939f', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'mcq', 'The following are components of the non-specific (innate) immune system except one. Which one?', '["Macrophages", "Complement system", "Interferons", "Lysozymes", "CD4 cells"]'::jsonb, 'CD4 cells', '[]'::jsonb, 'CD4 helper T lymphocytes belong to the adaptive (specific) immune system: they recognise a particular antigen presented on MHC class II and form memory. Macrophages, complement, interferons and lysozyme act immediately and without antigen specificity, so they are innate defences.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.022 Q19, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-d477093466', 'pharm-anti-fungals', 'mcq', 'Which antifungal drug is not used for systemic fungal infection?', '["Nystatin", "Flucytosine", "Amphotericin B", "Voriconazole", "Caspofungin"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is a polyene like amphotericin B but is too toxic for parenteral use and is not absorbed from the gut, so it is used only topically for skin, mouth, gut and vaginal candidiasis. The other four are given systemically for invasive mycoses.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.024 Q21, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-afb9bd420b', 'pharm-anti-fungals', 'mcq', 'Which is the false statement about amphotericin B?', '["Has the broadest spectrum of antifungal activity", "It is poorly absorbed from the gastrointestinal tract", "The most significant adverse effect is renal damage", "It is prepared as a colloidal suspension", "Given as a rapid intravenous bolus infusion"]'::jsonb, 'Given as a rapid intravenous bolus infusion', '[]'::jsonb, 'Amphotericin B must be infused slowly, over about 2 to 6 hours; rapid injection causes severe infusion reactions (fever, rigors, hypotension) and arrhythmias. It is insoluble in water, so the conventional form is a colloidal suspension with deoxycholate. Nephrotoxicity is the dose-limiting toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.025 Q22, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-572a021c64', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'The following except one are opioid partial agonists or mixed agonist-antagonists. Which is the exception?', '["Nalbuphine", "Pentazocine", "Butorphanol", "Tramadol", "Buprenorphine"]'::jsonb, 'Tramadol', '[]'::jsonb, 'Tramadol is a weak full mu agonist (through its O-desmethyl metabolite) that also blocks serotonin and noradrenaline reuptake. Buprenorphine is a partial mu agonist, while nalbuphine, pentazocine and butorphanol are kappa agonists with antagonist or partial agonist action at mu receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.026 Q23, CAT 1 2022/2023. Stem widened to ''partial agonists or mixed agonist-antagonists'' (paper says only ''partial agonists'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-d1d1027a0e', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which non-steroidal anti-inflammatory drug is ineffective in the treatment of gout?', '["Etoricoxib", "Sulindac", "Indomethacin", "Ibuprofen", "Tolmetin"]'::jsonb, 'Tolmetin', '[]'::jsonb, 'Tolmetin is the one NSAID that, for unknown reasons, does not relieve acute gout. Indomethacin is the traditional choice and other NSAIDs including etoricoxib, sulindac and ibuprofen work at full anti-inflammatory doses. Aspirin is also avoided because low doses retain urate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.027 Q24, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-9d5d0edbaf', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'mcq', 'All of the following are true of the immune system except:', '["TH2 T-lymphocytes suppress TH1 cell proliferation", "CD8 cells are responsible for recognition and attack of extracellular pathogens", "TH2 T-lymphocytes induce B-cell proliferation and differentiation to plasma cells", "TH1 T-lymphocytes induce cell-mediated immunity by activating macrophages, cytotoxic T-lymphocytes and natural killer cells", "TH1 T-lymphocytes suppress TH2 cell proliferation"]'::jsonb, 'CD8 cells are responsible for recognition and attack of extracellular pathogens', '[]'::jsonb, 'CD8 cytotoxic T cells recognise peptides on MHC class I and kill cells harbouring intracellular pathogens such as viruses, as well as tumour cells. Extracellular pathogens are dealt with by antibody, complement and phagocytes. TH1 and TH2 subsets cross-inhibit each other through interferon-gamma and interleukins 4 and 10.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.028 Q25, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-5143bf2085', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Clinical indications for methotrexate include the following except:', '["Systemic lupus erythematosus", "Dermatomyositis", "Vasculitis", "Dermatitis", "Psoriasis"]'::jsonb, 'Dermatitis', '[]'::jsonb, 'Besides rheumatoid arthritis, low-dose methotrexate is used in psoriasis and psoriatic arthritis, polymyositis and dermatomyositis, lupus and vasculitides such as granulomatosis with polyangiitis and giant cell arteritis. Ordinary dermatitis is treated with emollients and topical steroids and is not a listed indication.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.029 Q26, CAT 1 2022/2023. Methotrexate is sometimes used off-label in severe atopic dermatitis, so the option is debatable; answer follows Katzung''s list of indications.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-493fde9715', 'pharm-antihelminthics-i', 'mcq', 'Which is the false statement about benzimidazoles?', '["Thiabendazole is applied topically for the treatment of cutaneous larva migrans", "Albendazole is mainly excreted in bile", "They inhibit microtubule polymerisation by binding to β-tubulin", "They are broad-spectrum anthelmintic agents", "Albendazole is superior to mebendazole"]'::jsonb, 'Albendazole is mainly excreted in bile', '[]'::jsonb, 'According to Katzung, albendazole undergoes rapid first-pass conversion to the active sulfoxide, whose metabolites are excreted in the urine. The class binds parasite beta-tubulin, has a broad nematode (and for albendazole, cestode) spectrum, and topical thiabendazole is effective for cutaneous larva migrans.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.030 Q27, CAT 1 2022/2023. Sources disagree on albendazole excretion (Katzung: urine; product labelling: largely biliary, under 1% in urine). ''Superior to mebendazole'' is also an opinion statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-259641d0b8', 'pharm-anti-fungals', 'mcq', 'Which drug has no activity against Candida?', '["Nystatin", "Ketoconazole", "Tolnaftate", "Ciclopirox olamine", "Clotrimazole"]'::jsonb, 'Tolnaftate', '[]'::jsonb, 'Tolnaftate is a topical thiocarbamate that inhibits squalene epoxidase and is active only against dermatophytes (tinea) and Malassezia; it is useless in candidiasis. Nystatin, the azoles and ciclopirox all cover Candida.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.031 Q28, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-5f36c14f7a', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'N-acetylcysteine is the antidote for poisoning with:', '["Aciclovir", "Sulindac", "Ketorolac", "Erythromycin", "Paracetamol"]'::jsonb, 'Paracetamol', '[]'::jsonb, 'In paracetamol overdose the toxic metabolite NAPQI exhausts hepatic glutathione and then binds liver cell proteins, causing centrilobular necrosis. N-acetylcysteine supplies cysteine to regenerate glutathione and is most effective within 8 to 10 hours of ingestion.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.032 Q29, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-9f6d2ac3ed', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which statement is true regarding morphine and its congeners?', '["Tramadol''s analgesic effectiveness can be reduced by ondansetron", "Codeine undergoes a higher first-pass metabolism than morphine", "Naloxone fully reverses the analgesic effect of tramadol", "Codeine is active without any metabolic conversion", "The antitussive dose of codeine is higher than that required for analgesia"]'::jsonb, 'Tramadol''s analgesic effectiveness can be reduced by ondansetron', '[]'::jsonb, 'Part of tramadol''s analgesia comes from increased spinal serotonin acting on 5-HT3 receptors, so the 5-HT3 antagonist ondansetron reduces its effect. Codeine has less first-pass metabolism than morphine (hence its good oral efficacy), needs CYP2D6 conversion to morphine, and suppresses cough at doses below analgesic ones.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.033 Q30, CAT 1 2022/2023. Two original options were replaced: (c) ''degree of analgesia from a given morphine dose increases progressively with age'' and (d) ''naloxone reverses tramadol respiratory depression more effectively than its analgesia'', because (d) is also arguably true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-3bc02ce15d', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which is not an adverse effect of cyclosporine?', '["Hypotension", "Hirsutism", "Gum hyperplasia", "Nephrotoxicity", "Hyperuricaemia"]'::jsonb, 'Hypotension', '[]'::jsonb, 'Cyclosporine causes hypertension, not hypotension, through renal vasoconstriction and sodium retention. Nephrotoxicity is its main dose-limiting toxicity, and hirsutism, gingival hyperplasia, hyperuricaemia, hyperkalaemia, hyperlipidaemia and tremor are also typical.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.034 Q31, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-b7b495cf55', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which is not an adverse effect of morphine?', '["Urinary retention", "Prolongation of labour", "Tachycardia", "Bronchoconstriction", "Dysphoria"]'::jsonb, 'Tachycardia', '[]'::jsonb, 'Morphine tends to cause bradycardia through central vagal stimulation; tachycardia is characteristic of pethidine, which has antimuscarinic properties. Histamine release can cause bronchoconstriction, sphincter spasm causes urinary retention, uterine tone is reduced so labour is prolonged, and some patients feel dysphoria.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.035 Q32, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-18bdc33d6c', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is the false statement about halofantrine?', '["It can cause arrhythmias", "It is only effective against the erythrocytic stage", "It is used for malarial chemoprophylaxis", "Its absorption is enhanced with food", "Its use is contraindicated in pregnancy"]'::jsonb, 'It is used for malarial chemoprophylaxis', '[]'::jsonb, 'Halofantrine is never used for prophylaxis because it prolongs the QT interval and can cause fatal ventricular arrhythmias. Fatty food greatly increases its erratic absorption, and with it the cardiac risk, so it is taken on an empty stomach. It is a blood schizonticide only and is embryotoxic in animals.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.036 Q33, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-c6bd08f3fd', 'pharm-topical-antimicrobials', 'mcq', 'Which topical drug has no activity against Gram-positive organisms?', '["Polymyxin B", "Ozenoxacin", "Mupirocin", "Retapamulin", "Gentamicin"]'::jsonb, 'Polymyxin B', '[]'::jsonb, 'Polymyxin B is a cationic detergent that binds lipopolysaccharide in the outer membrane of Gram-negative bacilli, including Pseudomonas; Gram-positive bacteria lack this target. Mupirocin, retapamulin and ozenoxacin are used for staphylococcal and streptococcal impetigo, and gentamicin also covers staphylococci.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.037 Q34, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-cea1d672fc', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Alcohols as antiseptics are effective in killing the following except:', '["Spores", "Gram-positive organisms", "Lipophilic viruses", "Gram-negative organisms", "Acid-fast organisms"]'::jsonb, 'Spores', '[]'::jsonb, 'Ethanol and isopropanol at 60 to 90% rapidly denature proteins, killing vegetative bacteria, mycobacteria, many fungi and enveloped (lipophilic) viruses. They are not sporicidal, which is why alcohol hand rub is inadequate for Clostridioides difficile and alcohol is not a sterilant.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.038 Q35, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-0990a4afc5', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is the false statement about chloroquine?', '["It is a highly effective blood schizonticide", "It is a synthetic 4-aminoquinoline molecule", "Has a small apparent volume of distribution", "Chronic use can lead to retinopathy", "Prevents biocrystallisation of haem into haemozoin"]'::jsonb, 'Has a small apparent volume of distribution', '[]'::jsonb, 'Chloroquine is extensively bound in tissues such as liver, spleen and melanin-containing tissues, giving a very large apparent volume of distribution (100 to 1000 L/kg) and a need for a loading dose. It concentrates in the parasite food vacuole and blocks haem polymerisation.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.039 Q36, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-da04aa39bf', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Which one of the following antiseptics/disinfectants can be used as a sterilant?', '["Iodine", "Phenols", "Chlorhexidine", "Glutaraldehyde", "Quaternary ammonium compounds"]'::jsonb, 'Glutaraldehyde', '[]'::jsonb, 'Glutaraldehyde alkylates proteins and nucleic acids and, with prolonged contact (about 10 hours for 2% solution), kills bacterial spores, so it is used for cold sterilisation of endoscopes and heat-sensitive instruments. Chlorhexidine, phenols and quaternary ammonium compounds are not sporicidal.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.041 Q38, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-48650e84a8', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which corticosteroid has the highest anti-inflammatory potency?', '["Dexamethasone", "Prednisolone", "Triamcinolone", "Fludrocortisone", "Paramethasone"]'::jsonb, 'Dexamethasone', '[]'::jsonb, 'Relative to hydrocortisone (1), anti-inflammatory potency is roughly 4 to 5 for prednisolone, 5 for triamcinolone, 10 for paramethasone and fludrocortisone, and 25 to 30 for dexamethasone. Fludrocortisone is used for its enormous mineralocorticoid effect, not its anti-inflammatory action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.043 Q40, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-8032449d3d', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which ectoparasiticidal drug is given orally?', '["Ivermectin", "Permethrin", "Crotamiton", "Spinosad", "Lindane"]'::jsonb, 'Ivermectin', '[]'::jsonb, 'Oral ivermectin (about 200 micrograms/kg) is effective in scabies, including crusted scabies, and head lice; it opens glutamate-gated chloride channels and paralyses the parasite. Permethrin, crotamiton, spinosad and lindane are applied to the skin or scalp.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.044 Q41, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-4b31125d4a', 'pharm-biologic-dmards', 'mcq', 'Which biologic DMARD is incorrectly matched with its target molecule?', '["Infliximab: TNF-alpha", "Abatacept: T cells", "Anakinra: Interleukin-6", "Canakinumab: Interleukin-1", "Rituximab: CD20"]'::jsonb, 'Anakinra: Interleukin-6', '[]'::jsonb, 'Anakinra is a recombinant interleukin-1 receptor antagonist. The interleukin-6 receptor is blocked by tocilizumab and sarilumab. Abatacept (CTLA-4-Ig) binds CD80/86 and prevents T-cell co-stimulation, and canakinumab is an antibody against interleukin-1β.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.045 Q42, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-baf005514d', 'pharm-introduction-to-dmards', 'mcq', 'Identify the targeted synthetic disease-modifying antirheumatic drug:', '["Baricitinib", "Methotrexate", "Anakinra", "Adalimumab", "Leflunomide"]'::jsonb, 'Baricitinib', '[]'::jsonb, 'Targeted synthetic DMARDs are small molecules designed to hit a specific intracellular target; baricitinib and tofacitinib inhibit Janus kinases. Methotrexate and leflunomide are conventional synthetic DMARDs, while anakinra and adalimumab are biologic DMARDs made by recombinant technology.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.046 Q43, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-7625820402', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which is the false statement about praziquantel?', '["Can cause arthralgia", "Extensive first-pass metabolism limits bioavailability", "Drug of choice for ocular cysticercosis", "Useful activity against most cestodes and trematodes", "Causes helminth death by spastic paralysis"]'::jsonb, 'Drug of choice for ocular cysticercosis', '[]'::jsonb, 'Praziquantel is contraindicated in ocular cysticercosis because the inflammatory reaction to dying cysts can destroy the eye; such cysts are removed surgically. It increases calcium permeability of the worm tegument, causing spastic paralysis, and is the drug of choice for schistosomiasis and most tapeworm and fluke infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.047 Q44, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-16d5d22043', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'mcq', 'Which one of the following artemisinin compounds can be given intravenously?', '["Dihydroartemisinin", "Artemisinin", "Artesunate", "Artemether", "Arteether"]'::jsonb, 'Artesunate', '[]'::jsonb, 'Artesunate is the water-soluble hemisuccinate derivative, so it can be given intravenously and is the treatment of choice for severe malaria. Artemether and arteether are oil-soluble and are given intramuscularly (or artemether orally); artemisinin and dihydroartemisinin are given orally.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.048 Q45, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-a8e30bc92f', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is not an adverse effect of quinine?', '["Cinchonism", "Visual impairment", "Hyperglycaemia", "Blackwater fever", "Hypotension"]'::jsonb, 'Hyperglycaemia', '[]'::jsonb, 'Quinine stimulates insulin release from pancreatic beta cells and so causes hypoglycaemia, especially in pregnancy and severe malaria. Cinchonism (tinnitus, headache, visual disturbance), hypotension with rapid infusion and massive haemolysis with haemoglobinuria (blackwater fever) are recognised toxicities.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.049 Q46, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-f246c41c5c', 'pharm-intravenous-fluids', 'mcq', 'The following are isotonic intravenous fluids except:', '["Normal saline", "Hartmann''s solution", "Ringer''s solution", "5% dextrose", "5% dextrose with normal saline"]'::jsonb, '5% dextrose with normal saline', '[]'::jsonb, 'Five percent dextrose in 0.9% saline has an osmolarity of about 560 mOsm/L, roughly twice that of plasma, so it is hypertonic. Normal saline (308), Hartmann''s (about 278), Ringer''s (about 310) and 5% dextrose (278 mOsm/L in the bag) are all approximately isotonic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.050 Q47, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-24170f6513', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is the false statement about primaquine?', '["Causes acute haemolysis in patients with G6PD deficiency", "It is an 8-aminoquinoline molecule", "Acts against the latent hepatic stages of Plasmodium", "It is almost fully absorbed from the gastrointestinal tract", "Used for radical cure of Plasmodium falciparum infection"]'::jsonb, 'Used for radical cure of Plasmodium falciparum infection', '[]'::jsonb, 'Radical cure means eradicating dormant liver hypnozoites, which only Plasmodium vivax and ovale form; P. falciparum has none. In falciparum malaria primaquine is used only as a single low dose to kill gametocytes and block transmission. G6PD status should be checked because of oxidant haemolysis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.051 Q48, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-1929818f30', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which is untrue regarding the mechanism of action and effects of opioids?', '["A high degree of tolerance develops to opioid-induced constipation", "They close voltage-gated calcium channels on presynaptic nerve terminals", "Persistent administration of opioid analgesics can increase the sensation of pain", "They cause hyperpolarisation of postsynaptic neurons", "Opioid receptors are G protein-coupled"]'::jsonb, 'A high degree of tolerance develops to opioid-induced constipation', '[]'::jsonb, 'Tolerance develops readily to analgesia, euphoria, sedation and respiratory depression, but little or none to constipation and miosis, so regular laxatives are needed. Opioid receptors are Gi/o-coupled: they close presynaptic calcium channels and open postsynaptic potassium channels. Chronic use can cause opioid-induced hyperalgesia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.052 Q49, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-aaab0bb784', 'pharm-anti-tb-drugs', 'mcq', 'Which antituberculous drug causes peripheral neuropathy?', '["Ethambutol", "Pyrazinamide", "Streptomycin", "Isoniazid", "Rifampicin"]'::jsonb, 'Isoniazid', '[]'::jsonb, 'Isoniazid increases excretion of pyridoxine and inhibits pyridoxal kinase, causing a dose-related sensory neuropathy, especially in slow acetylators, alcoholics, diabetics and the malnourished; pyridoxine prevents it. Ethambutol causes optic neuritis and streptomycin damages the eighth cranial nerve.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.053 Q50, CAT 1 2022/2023') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-486066a10c', 'pharm-anti-tb-drugs', 'mcq', 'Which anti-TB agent is incorrectly matched with its adverse effect?', '["Capreomycin: Hepatitis", "Rifampicin: Orange discolouration of tears", "Pyrazinamide: Hyperuricaemia", "Cycloserine: Psychosis", "Isoniazid: Peripheral neuropathy"]'::jsonb, 'Capreomycin: Hepatitis', '[]'::jsonb, 'Capreomycin is an injectable polypeptide whose toxicities resemble those of aminoglycosides: nephrotoxicity and ototoxicity (tinnitus, deafness, vestibular damage). Drug-induced hepatitis is the hallmark of isoniazid, rifampicin and pyrazinamide instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.055 Q1, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-f967bd3a69', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'All of the following are true of β-lactamase inhibitors except:', '["They inhibit all β-lactamases", "The antibacterial spectrum is determined by the penicillin in the combination", "Combinations are indicated for mixed infections", "They are most active against Ambler class A β-lactamases", "They have weak antibacterial action"]'::jsonb, 'They inhibit all β-lactamases', '[]'::jsonb, 'Clavulanic acid, sulbactam and tazobactam protect the partner penicillin mainly from plasmid-encoded Ambler class A enzymes. They are poor inhibitors of chromosomal class C (AmpC) enzymes and do not inhibit metallo-β-lactamases, so they certainly do not cover all β-lactamases.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.055 Q2, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-7c0c47c40b', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'The following are true about quinine except:', '["Poorly absorbed from the gastrointestinal tract", "Achieves CSF levels that are 2-5% of plasma levels", "Readily reaches fetal tissues", "Can be given orally, intramuscularly or intravenously", "Metabolised extensively in the liver"]'::jsonb, 'Poorly absorbed from the gastrointestinal tract', '[]'::jsonb, 'Quinine is rapidly and almost completely absorbed after an oral dose, reaching peak levels in 1 to 3 hours. It is extensively metabolised in the liver, crosses the placenta, and penetrates the CSF poorly. In severe malaria it is given by slow intravenous infusion or deep intramuscular injection.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.055 Q3, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-2512ac9e5c', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All of the following are true about tramadol except:', '["Its analgesic effect is mainly through inhibition of serotonin reuptake", "Its primary metabolite is more potent than the parent drug", "Constipation is less than that seen after equivalent doses of codeine", "May worsen seizures in patients with epilepsy", "Its analgesic effectiveness is enhanced by co-administration with ondansetron"]'::jsonb, 'Its analgesic effectiveness is enhanced by co-administration with ondansetron', '[]'::jsonb, 'Ondansetron reduces tramadol''s analgesia because part of the effect depends on serotonin acting at spinal 5-HT3 receptors. Tramadol blocks serotonin and noradrenaline reuptake, its O-desmethyl metabolite is a much stronger mu agonist, and it lowers the seizure threshold.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.055-056 Q4, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--07da04988e', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Amoxicillin is ineffective against:', '["Streptococcus pneumoniae", "Helicobacter pylori", "Haemophilus influenzae", "Methicillin-resistant Staphylococcus aureus", "Escherichia coli"]'::jsonb, 'Methicillin-resistant Staphylococcus aureus', '[]'::jsonb, 'MRSA carries the mecA gene, which encodes an altered penicillin-binding protein (PBP2a) with low affinity for almost all beta-lactams, so amoxicillin, with or without clavulanate, fails. Vancomycin or linezolid is needed. Amoxicillin retains activity against sensitive strains of the other organisms listed.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.056 Q5, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-7a33435257', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Which of the following is most effective in neuropathic pain?', '["Carbamazepine", "Meloxicam", "Morphine", "Paracetamol", "Indomethacin"]'::jsonb, 'Carbamazepine', '[]'::jsonb, 'Neuropathic pain arises from abnormal firing of damaged nerves and responds to membrane stabilisers and adjuvants: carbamazepine (first choice in trigeminal neuralgia), gabapentinoids and tricyclic antidepressants. NSAIDs and paracetamol are ineffective and opioids are relatively poor.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.056 Q6, CAT 2 2021/2022. Stem changed from ''Which is effective'' to ''most effective'' since morphine has some effect.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-immunomodulants-i-d4687e63c9', 'pharm-immunomodulants-i', 'mcq', 'Which has no immunostimulant property?', '["Thalidomide", "Interferon", "Mycophenolate mofetil", "BCG", "Levamisole"]'::jsonb, 'Mycophenolate mofetil', '[]'::jsonb, 'Mycophenolate mofetil is a pure immunosuppressant: its active form inhibits inosine monophosphate dehydrogenase, starving T and B lymphocytes of guanine nucleotides. BCG, levamisole and interferons stimulate immune responses, and thalidomide is an immunomodulator that enhances T-cell and NK-cell activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.057 Q8, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-82199a5e49', 'pharm-disinfectants-and-antiseptics', 'mcq', 'All of the following are true of alcohols as antiseptics/disinfectants except:', '["They do not penetrate protein-containing organic materials", "They have a rapid killing effect", "They inactivate both hydrophilic and lipophilic viruses", "The most commonly used are ethanol and isopropyl alcohol", "Optimal bactericidal concentration is 60-90% by volume in water"]'::jsonb, 'They inactivate both hydrophilic and lipophilic viruses', '[]'::jsonb, 'Alcohols dissolve lipid envelopes, so they inactivate lipophilic (enveloped) viruses but are unreliable against hydrophilic, non-enveloped viruses. They act fast at 60 to 90% in water, are not sporicidal, and are inactivated by organic matter, so surfaces must be cleaned first.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.057 Q9, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-a5eb1c6ec2', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which opioid causes mydriasis at toxic doses?', '["Morphine", "Methadone", "Fentanyl", "Meperidine", "Nalbuphine"]'::jsonb, 'Meperidine', '[]'::jsonb, 'Meperidine (pethidine) has atropine-like antimuscarinic activity, so toxicity produces dilated pupils, tachycardia and dry mouth; its metabolite normeperidine adds tremor and seizures. Other mu agonists produce pinpoint pupils by stimulating the Edinger-Westphal nucleus.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.057-058 Q10, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-56f755b847', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which is a pure opioid antagonist?', '["Pentazocine", "Naloxone", "Buprenorphine", "Nalbuphine", "Nalorphine"]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone (like naltrexone and nalmefene) is a competitive antagonist at mu, kappa and delta receptors with no agonist activity. Nalorphine, pentazocine and nalbuphine are mixed agonist-antagonists with kappa agonism, and buprenorphine is a partial mu agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.058 Q11, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-66f5a517cc', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'All of the following are true about chloroquine and hydroxychloroquine as DMARDs except:', '["Response to treatment is usually seen by 2-3 weeks", "Loading doses increase response rates", "Blood elimination half-life is up to 45 days", "Ocular toxicity may occur at dosages greater than 250 mg/day for chloroquine", "They are rapidly absorbed orally"]'::jsonb, 'Response to treatment is usually seen by 2-3 weeks', '[]'::jsonb, 'The antimalarial DMARDs are slow acting: benefit in rheumatoid arthritis or lupus usually takes 3 to 6 months to appear. They are well absorbed, are heavily tissue bound with elimination half-lives of up to 45 days, and can cause retinal toxicity at higher doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.058 Q12, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-a0da8cfe63', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which statement is true of paracetamol?', '["Has a significant anti-inflammatory effect", "Is an alternative to aspirin in patients with peptic ulcers", "Causes metabolic acidosis at therapeutic doses", "There is no antidote for its hepatotoxicity", "Is a phenylacetic acid derivative"]'::jsonb, 'Is an alternative to aspirin in patients with peptic ulcers', '[]'::jsonb, 'Paracetamol is analgesic and antipyretic but has negligible peripheral COX inhibition, so it does not damage the gastric mucosa or affect platelets and is preferred in peptic ulcer disease. It is a para-aminophenol derivative, and N-acetylcysteine is the antidote for overdose.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.058 Q13, CAT 2 2021/2022. Added ''at therapeutic doses'' to the metabolic acidosis option (severe overdose can cause acidosis).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--8ac03a7e2c', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which statement is true of piperacillin?', '["Is not plasma protein bound", "Administered via the oral route", "Dose should be adjusted in renal failure", "Is completely metabolised before excretion", "Distributed only in renal tissue"]'::jsonb, 'Dose should be adjusted in renal failure', '[]'::jsonb, 'Piperacillin is an acid-labile ureidopenicillin given only parenterally, and is excreted largely unchanged by glomerular filtration and tubular secretion, so the dose is reduced in renal impairment. It distributes widely and is partly bound to plasma proteins.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.059 Q14, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-67d429aa75', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Which is an oral non-absorbable sulfonamide?', '["Mafenide acetate", "Sulfadiazine", "Sulfacetamide", "Sulfamethoxazole", "Sulfasalazine"]'::jsonb, 'Sulfasalazine', '[]'::jsonb, 'Sulfasalazine is poorly absorbed in the small bowel and reaches the colon, where bacteria split it into 5-aminosalicylic acid and sulfapyridine; hence its use in ulcerative colitis. Mafenide and sulfacetamide are topical, while sulfadiazine and sulfamethoxazole are well absorbed oral agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.059 Q16, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-30641acfd0', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which is not an adverse effect of tacrolimus?', '["Secondary malignancies", "Neurotoxicity", "Hirsutism", "Nephrotoxicity", "Hyperlipidaemia"]'::jsonb, 'Hirsutism', '[]'::jsonb, 'Hirsutism and gum hyperplasia are features of cyclosporine; tacrolimus tends to cause hair loss instead. Tacrolimus shares nephrotoxicity, hypertension and malignancy risk with cyclosporine and causes more neurotoxicity (tremor, seizures) and more post-transplant diabetes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.060 Q17, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-89a6adf50c', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'The drug of choice for treatment of Pneumocystis jirovecii (carinii) infection is:', '["Clindamycin and primaquine", "Trimethoprim and dapsone", "Pentamidine", "Atovaquone", "Trimethoprim and sulfamethoxazole"]'::jsonb, 'Trimethoprim and sulfamethoxazole', '[]'::jsonb, 'High-dose co-trimoxazole is first-line treatment and prophylaxis for Pneumocystis pneumonia; the two drugs block sequential steps in folate synthesis. Clindamycin-primaquine, trimethoprim-dapsone, atovaquone and intravenous pentamidine are alternatives for patients who cannot tolerate sulfonamides.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.060 Q18, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-b2df9ae6ec', 'pharm-macrolides', 'mcq', 'Which of the following macrolide antibiotics has the longest half-life?', '["Erythromycin", "Azithromycin", "Telithromycin", "Clarithromycin", "Clindamycin"]'::jsonb, 'Azithromycin', '[]'::jsonb, 'Azithromycin is extensively taken up into tissues and phagocytes and released slowly, giving a tissue half-life of 2 to 4 days and allowing once-daily dosing and short courses. Erythromycin lasts about 1.5 hours and clarithromycin about 6 hours. Clindamycin is a lincosamide, not a macrolide.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.060 Q19, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-2f1033742a', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which statement about linezolid is untrue?', '["It has cross-resistance with the streptogramin antibiotics", "Tedizolid is a newer-generation analogue with a longer half-life", "Prevents the initiation of protein synthesis", "Active against Gram-positive anaerobic cocci", "Is indicated for health care-associated pneumonia"]'::jsonb, 'It has cross-resistance with the streptogramin antibiotics', '[]'::jsonb, 'Linezolid binds a unique site on the 23S rRNA of the 50S subunit and prevents formation of the initiation complex, so there is no cross-resistance with other protein synthesis inhibitors, including streptogramins. It is used for MRSA and VRE infections, including hospital-acquired pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.061 Q20, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-16267ce7af', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'Which is the false statement about leflunomide?', '["Undergoes rapid conversion in the intestine and plasma to its active metabolite", "Inhibits T-cell proliferation", "Inhibits dihydroorotate dehydrogenase", "Reduces autoantibody production by B cells", "Increases ribonucleotide synthesis"]'::jsonb, 'Increases ribonucleotide synthesis', '[]'::jsonb, 'Leflunomide is a prodrug converted to teriflunomide (A77-1726), which inhibits dihydroorotate dehydrogenase and therefore decreases de novo pyrimidine ribonucleotide synthesis. Activated lymphocytes arrest in G1, reducing T-cell proliferation and B-cell autoantibody production.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.061 Q21, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-515b667734', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which is the incorrect statement?', '["Tuberculosis is treated with a combination of drugs", "Trimethoprim and sulfamethoxazole have synergistic effects when combined", "Plasmids transfer resistance between microbes", "All antimicrobials that inhibit protein synthesis act at the 50S ribosomal subunit except aminoglycosides", "Quinolones have concentration-dependent killing"]'::jsonb, 'All antimicrobials that inhibit protein synthesis act at the 50S ribosomal subunit except aminoglycosides', '[]'::jsonb, 'Tetracyclines, like aminoglycosides, bind the 30S ribosomal subunit, so aminoglycosides are not the only exception. Macrolides, clindamycin, chloramphenicol, linezolid and streptogramins act on the 50S subunit.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.061 Q22, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-4d86ecffde', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which is a fourth-generation cephalosporin?', '["Cefamandole", "Loracarbef", "Cefaclor", "Cefepime", "Cefotetan"]'::jsonb, 'Cefepime', '[]'::jsonb, 'Cefepime is fourth generation: it is more stable to chromosomal AmpC beta-lactamases and covers Pseudomonas and Enterobacter while keeping good Gram-positive activity. Cefamandole, cefaclor, loracarbef and cefotetan are all second-generation agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.061-062 Q23, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-bc903eed32', 'pharm-quinolones', 'mcq', 'All of the following are true of fluoroquinolones except:', '["Antacids inhibit absorption", "Moxifloxacin is effective against anaerobes", "Ciprofloxacin is the most active against Gram-negative bacteria", "They have no activity against the organisms of atypical pneumonia", "Levofloxacin has enhanced activity against Gram-positive bacteria"]'::jsonb, 'They have no activity against the organisms of atypical pneumonia', '[]'::jsonb, 'Fluoroquinolones penetrate cells well and are active against Mycoplasma, Chlamydophila and Legionella; the ''respiratory'' quinolones levofloxacin and moxifloxacin are used for atypical pneumonia. Divalent and trivalent cations in antacids chelate them and block absorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.062 Q24, CAT 2 2021/2022. Option e softened from ''Levofloxacin is the most active against gram positive bacteria'' (moxifloxacin and gemifloxacin are more active).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-e47bbaacd0', 'pharm-anti-fungals', 'mcq', 'Which antifungal drug is given topically for the treatment of mucocutaneous candidiasis?', '["Terbinafine", "Amphotericin B", "Nystatin", "Flucytosine", "Griseofulvin"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is a polyene that binds ergosterol; it is too toxic for systemic use and is not absorbed, so it is applied locally as suspension, pastilles, cream or pessaries for oral, cutaneous and vaginal candidiasis. Terbinafine and griseofulvin are for dermatophyte infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.062 Q25, CAT 2 2021/2022. Stem made specific (''mucocutaneous candidiasis''; paper says ''mucocutaneous infection'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-297097c8df', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which is not a glycopeptide antibiotic?', '["Daptomycin", "Teicoplanin", "Telavancin", "Dalbavancin", "Vancomycin"]'::jsonb, 'Daptomycin', '[]'::jsonb, 'Daptomycin is a cyclic lipopeptide that inserts into the Gram-positive cell membrane in a calcium-dependent way and depolarises it. Vancomycin and teicoplanin are glycopeptides, and telavancin and dalbavancin are lipoglycopeptide derivatives that bind the D-Ala-D-Ala terminus of peptidoglycan precursors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.062-063 Q26, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-d68722ccf9', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which cephalosporin is antipseudomonal?', '["Ceftriaxone", "Cefuroxime", "Cefazolin", "Cephalexin", "Ceftazidime"]'::jsonb, 'Ceftazidime', '[]'::jsonb, 'Ceftazidime (third generation), cefoperazone and cefepime (fourth generation) are the cephalosporins with reliable activity against Pseudomonas aeruginosa. Ceftriaxone, although third generation, does not cover Pseudomonas.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.063 Q27, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-b5d76ed8ba', 'pharm-quinolones', 'mcq', 'All of the following are true of quinolones except:', '["They are effective in killing both Gram-positive and Gram-negative bacteria", "They act by inhibiting protein synthesis at the 50S ribosomal subunit", "Norfloxacin is the least effective of the fluoroquinolones", "Nalidixic acid does not achieve therapeutic plasma levels", "Methicillin-resistant strains of staphylococci are often resistant to fluoroquinolones"]'::jsonb, 'They act by inhibiting protein synthesis at the 50S ribosomal subunit', '[]'::jsonb, 'Quinolones inhibit bacterial DNA synthesis by blocking DNA gyrase (topoisomerase II) and topoisomerase IV; they do not act on ribosomes. Nalidixic acid and norfloxacin reach useful concentrations only in urine, so they are limited to urinary tract infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.063 Q28, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-32971b7835', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which is a selective COX-2 inhibitor?', '["Celecoxib", "Diclofenac", "Ibuprofen", "Ketorolac", "Aspirin"]'::jsonb, 'Celecoxib', '[]'::jsonb, 'Celecoxib selectively inhibits the inducible COX-2 isoform, sparing COX-1 in the gastric mucosa and platelets, so it causes fewer ulcers and does not impair platelet function, at the cost of some cardiovascular risk. The others are non-selective inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.063-064 Q29, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-170571fb19', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which is not an adverse effect of chronic use of prednisone?', '["Osteoporosis", "Hypotension", "Hyperglycaemia", "Peptic ulcers", "Fat redistribution"]'::jsonb, 'Hypotension', '[]'::jsonb, 'Glucocorticoids cause sodium and water retention and increase vascular sensitivity to catecholamines, producing hypertension, not hypotension. Long-term use gives the iatrogenic Cushing picture: central fat redistribution, hyperglycaemia, osteoporosis, myopathy, skin thinning and peptic ulceration.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.064 Q30, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-7097f6b8f9', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which is a false statement?', '["Cyclophosphamide has no immunosuppressive effect", "Cyclosporine is a calcineurin inhibitor", "Thalidomide is teratogenic", "Tacrolimus is more potent than cyclosporine", "Proximal myopathy is a steroid adverse effect"]'::jsonb, 'Cyclophosphamide has no immunosuppressive effect', '[]'::jsonb, 'Cyclophosphamide is one of the most powerful immunosuppressants: by alkylating DNA it destroys proliferating lymphocytes, especially B cells, and is used in lupus nephritis and vasculitis. Tacrolimus is 10 to 100 times more potent than cyclosporine by weight.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.064 Q31, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-e621c365c2', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which is the false statement about fentanyl?', '["Its effect is rapidly terminated", "It is a synthetic opioid", "It is a strong mu receptor agonist", "Has a short time to peak analgesic effect", "Has maximal cardio-depressant activity"]'::jsonb, 'Has maximal cardio-depressant activity', '[]'::jsonb, 'Fentanyl causes minimal myocardial depression and little histamine release, which is why high-dose fentanyl is favoured in cardiac anaesthesia. It is a highly lipid-soluble synthetic phenylpiperidine, about 100 times as potent as morphine, with rapid onset and a short action after single doses because of redistribution.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.064 Q32, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-2bc43ff85a', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'All of the following are true about corticosteroids except:', '["Prednisone is frequently used to suppress acute rejection of solid organ allografts", "Prednisolone is the active metabolite of prednisone", "The synthetic corticosteroids are mainly bound to albumin", "They cause lympholysis", "Synthetic corticosteroids have more salt-retaining effect than cortisol"]'::jsonb, 'Synthetic corticosteroids have more salt-retaining effect than cortisol', '[]'::jsonb, 'Synthetic glucocorticoids such as prednisolone, triamcinolone and dexamethasone were designed to have greater anti-inflammatory and less mineralocorticoid (salt-retaining) activity than cortisol. Unlike cortisol, which binds transcortin, they are carried mainly on albumin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.065 Q33, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-8bc8e82055', 'pharm-acute-opioid-toxicity', 'mcq', 'Acute opioid toxicity is strongly suggested by the triad of:', '["Coma, pinpoint pupils and depressed respiration", "Hypothermia, coma and pinpoint pupils", "Coma, depressed respiration and hypotension", "Depressed respiration, bradycardia and pinpoint pupils", "Pinpoint pupils, bradycardia and coma"]'::jsonb, 'Coma, pinpoint pupils and depressed respiration', '[]'::jsonb, 'The classic triad of opioid overdose is coma, pinpoint pupils and respiratory depression, all mediated by mu receptors and reversed by naloxone. Hypotension, bradycardia and hypothermia may occur but are not part of the diagnostic triad.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.065 Q34, CAT 2 2021/2022. Same question also appears on p.079 (CAT 2 2020/2021 Q13).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-f2f9e1a750', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which statement is incorrect?', '["Metronidazole causes a disulfiram-like effect", "Iodoquinol is used with caution in patients with thyroid disease", "Metronidazole is a prodrug", "Emetine has no cardiovascular system adverse effects", "Diloxanide furoate has no activity against tissue trophozoites"]'::jsonb, 'Emetine has no cardiovascular system adverse effects', '[]'::jsonb, 'Emetine and dehydroemetine are cardiotoxic: they cause ECG changes, arrhythmias, hypotension and heart failure, which is why they are reserved for severe amoebiasis when metronidazole cannot be used. Metronidazole needs reduction of its nitro group inside anaerobes to become active.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.065 Q35, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-4af0d39edc', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is not a true statement about the mechanism of chloroquine?', '["Resistance is very common", "It is a synthetic 4-aminoquinoline antimalarial drug", "Enhances biocrystallisation of haem into haemozoin", "It is a highly effective blood schizonticide", "Has a large apparent volume of distribution"]'::jsonb, 'Enhances biocrystallisation of haem into haemozoin', '[]'::jsonb, 'Chloroquine accumulates in the acidic food vacuole of the parasite and inhibits polymerisation (biocrystallisation) of toxic haem into inert haemozoin; free haem then kills the parasite. Resistance in Plasmodium falciparum, through the PfCRT transporter, is now widespread.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.066 Q36, CAT 2 2021/2022. Stem in the paper: ''Which is not a true statement about chloroquine?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-ac176beabb', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which of the following drugs is not an ectoparasiticide?', '["Spinosad", "Diethylcarbamazine", "Ivermectin", "Lindane", "Permethrin"]'::jsonb, 'Diethylcarbamazine', '[]'::jsonb, 'Diethylcarbamazine is used for filarial infections (lymphatic filariasis, loiasis) and has no action on lice or scabies mites. Permethrin, lindane and spinosad are topical pediculicides or scabicides, and ivermectin works orally or topically against both.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.066 Q37, CAT 2 2021/2022. A near-identical question on p.077 (CAT 2 2020/2021 Q5) has levamisole as the odd one out.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-7714e21f51', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which drug cannot be used for long-term analgesia?', '["Paracetamol", "Ibuprofen", "Indomethacin", "Ketorolac", "Celecoxib"]'::jsonb, 'Ketorolac', '[]'::jsonb, 'Ketorolac is a potent analgesic NSAID used for short-term postoperative pain, but treatment is limited to 5 days because the risk of gastrointestinal bleeding and renal failure rises sharply with longer use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.066 Q38, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-baa9b128f5', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which drug is used for closure of a patent ductus arteriosus?', '["Aspirin", "Nimesulide", "Sulindac", "Indomethacin", "Diclofenac"]'::jsonb, 'Indomethacin', '[]'::jsonb, 'The ductus is kept open by prostaglandin E2. Intravenous indomethacin (or ibuprofen) inhibits cyclooxygenase, removes this vasodilator influence and closes the ductus in premature infants. Conversely, alprostadil (PGE1) keeps it open in duct-dependent heart disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.067 Q39, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-af43449dca', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which statement about the 8-aminoquinoline antimalarial primaquine is false?', '["Acts against primary and latent hepatic (exo-erythrocytic) stages of Plasmodium", "Prevents relapses in P. vivax and P. ovale infections", "Tafenoquine belongs to the same class", "Is highly active against asexual blood-stage parasites", "Has gametocytocidal activity"]'::jsonb, 'Is highly active against asexual blood-stage parasites', '[]'::jsonb, 'Primaquine is a tissue schizonticide and gametocytocide: it kills liver stages, including hypnozoites, and gametocytes of all species. Its activity against asexual erythrocytic parasites is too weak to be clinically useful, so it is always combined with a blood schizonticide.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.067 Q40, CAT 2 2021/2022. Reworded to refer to primaquine specifically (paper: ''False about 8 aminoquinoline antimalarial drug ... Active against asexual blood stage parasites''); tafenoquine does have some blood-stage activity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-4b306021df', 'pharm-antiretroviral-i', 'mcq', 'A hypersensitivity drug reaction in patients on treatment for HIV who express HLA-B*5701 is associated with which of these medicines?', '["Lopinavir", "Dolutegravir", "Enfuvirtide", "Abacavir", "Stavudine"]'::jsonb, 'Abacavir', '[]'::jsonb, 'About half of HLA-B*57:01 carriers given abacavir develop a multisystem hypersensitivity reaction (fever, rash, gastrointestinal and respiratory symptoms) within six weeks; rechallenge can be fatal. Patients are screened for the allele before starting the drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.067 Q41, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-2e804cf101', 'pharm-biologic-dmards', 'mcq', 'Premedication is used before intravenous infusion with:', '["Etanercept", "Tocilizumab", "Golimumab", "Abatacept", "Rituximab"]'::jsonb, 'Rituximab', '[]'::jsonb, 'Rituximab, a chimeric anti-CD20 antibody, commonly causes infusion reactions from cytokine release as B cells are lysed, so paracetamol, an antihistamine and intravenous methylprednisolone are given beforehand. Etanercept and golimumab are usually given subcutaneously.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.068 Q42, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-17825c622a', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Which statement is correct?', '["Misoprostol is used with NSAIDs to reduce the risk of gastrointestinal bleeding", "Paracetamol has strong anti-inflammatory activity", "Non-steroidal anti-inflammatory drugs are safe in renal failure", "Cyclooxygenase-1 is inducible", "Aspirin has no antiplatelet effects"]'::jsonb, 'Misoprostol is used with NSAIDs to reduce the risk of gastrointestinal bleeding', '[]'::jsonb, 'Misoprostol is a PGE1 analogue that replaces the protective prostaglandins lost when NSAIDs inhibit COX-1, reducing ulcers and bleeding. COX-1 is constitutive (COX-2 is inducible), NSAIDs can precipitate renal failure, and aspirin irreversibly blocks platelet thromboxane synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.068 Q43, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-53aabaf9bb', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Which drug is not appropriately matched with its clinical indication?', '["Mafenide: prevention of infection of burn wounds", "Sulfasalazine: rheumatoid arthritis", "Sulfacetamide: toxoplasmosis", "Sulfisoxazole: urinary tract infections", "Sulfadoxine: malaria"]'::jsonb, 'Sulfacetamide: toxoplasmosis', '[]'::jsonb, 'Sulfacetamide is a topical sulfonamide used as eye drops for bacterial conjunctivitis and trachoma. Toxoplasmosis is treated with sulfadiazine plus pyrimethamine (with folinic acid). The other pairings are correct.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.068 Q44, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-1a67838185', 'pharm-antibody-preparations', 'mcq', 'Which of the following is a polyclonal antibody?', '["Daclizumab", "Etanercept", "Antithymocyte globulin", "Anakinra", "Muromonab-CD3"]'::jsonb, 'Antithymocyte globulin', '[]'::jsonb, 'Antithymocyte globulin is made by immunising horses or rabbits with human thymocytes, so it contains many antibodies against different T-cell surface antigens. Daclizumab and muromonab-CD3 are monoclonal antibodies, etanercept is a receptor fusion protein and anakinra a recombinant receptor antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.069 Q47, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-73e59b0577', 'pharm-antiretroviral-i', 'mcq', 'The following drugs are non-nucleoside reverse transcriptase inhibitors except:', '["Etravirine", "Efavirenz", "Abacavir", "Doravirine", "Rilpivirine"]'::jsonb, 'Abacavir', '[]'::jsonb, 'Abacavir is a guanosine analogue nucleoside reverse transcriptase inhibitor: it needs intracellular phosphorylation and causes chain termination. NNRTIs (efavirenz, nevirapine, etravirine, rilpivirine, doravirine) bind an allosteric pocket on the enzyme and need no activation.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.070 Q48, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-8478e68065', 'pharm-antihelminthics-i', 'mcq', 'All of the following are true about benzimidazoles except:', '["Inhibit microtubule polymerisation by binding to β-tubulin", "Low systemic bioavailability", "Are teratogenic", "Are narrow-spectrum anthelmintic drugs", "Mebendazole is extensively metabolised"]'::jsonb, 'Are narrow-spectrum anthelmintic drugs', '[]'::jsonb, 'Albendazole and mebendazole are broad-spectrum anthelmintics active against roundworm, hookworm, whipworm, pinworm and, for albendazole, larval tapeworms. They are poorly absorbed with extensive first-pass metabolism and are embryotoxic in animals, so they are avoided in the first trimester.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.070 Q49, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-c21ead6226', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All the following may be adverse effects of opioids except:', '["Raised intracranial pressure", "Vomiting", "Urinary incontinence", "Constipation", "Respiratory depression"]'::jsonb, 'Urinary incontinence', '[]'::jsonb, 'Opioids cause urinary retention, not incontinence: they increase sphincter tone and inhibit the voiding reflex. Respiratory depression raises carbon dioxide, which dilates cerebral vessels and raises intracranial pressure. Vomiting comes from stimulation of the chemoreceptor trigger zone.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.070 Q50, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-51d0bd74d1', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'mcq', 'All of the following are true about artemisinins except:', '["Artemether is lipid soluble", "They are not metabolised in the body", "Artesunate is water soluble", "Artemisinin can only be given orally", "Artesunate and artemether can be given rectally"]'::jsonb, 'They are not metabolised in the body', '[]'::jsonb, 'Artesunate and artemether are rapidly metabolised to the active metabolite dihydroartemisinin, which is then glucuronidated; half-lives are only 1 to 3 hours. Water-soluble artesunate can be given intravenously, lipid-soluble artemether intramuscularly.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.071 Q51, CAT 2 2021/2022. Rectal use is established for artesunate; rectal artemether exists but is uncommon. The clearly false option is b.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-2a6fa00abd', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Morphine should be avoided in:', '["Diarrhoea", "Acute bronchial asthma", "Acute myocardial infarction", "Postoperative pain", "Acute left ventricular failure"]'::jsonb, 'Acute bronchial asthma', '[]'::jsonb, 'In an acute asthma attack morphine depresses the respiratory centre and cough reflex and releases histamine, which may worsen bronchoconstriction. It is useful in myocardial infarction and acute pulmonary oedema, where it relieves pain, anxiety and preload.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.071 Q52, CAT 2 2021/2022. Option d reads ''Prior surgery'' in the paper; replaced with ''Postoperative pain''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-7f19fa4d71', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which statement is true regarding carbapenems?', '["Enterococcus faecium is susceptible to imipenem", "Ertapenem has inferior activity against Pseudomonas aeruginosa", "Meropenem can cause seizures in up to 5% of patients", "Ertapenem is combined with cilastatin to prevent renal tubular degradation", "Imipenem can be administered via the oral route"]'::jsonb, 'Ertapenem has inferior activity against Pseudomonas aeruginosa', '[]'::jsonb, 'Ertapenem has a long half-life allowing once-daily dosing but lacks useful activity against Pseudomonas and Acinetobacter. Only imipenem is hydrolysed by renal dehydropeptidase and needs cilastatin; imipenem, rather than meropenem, is the carbapenem most associated with seizures. All are parenteral.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.071 Q53, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-307813f07e', 'pharm-antiretroviral-i', 'mcq', 'Which adverse effect of antiretroviral drugs is not due to mitochondrial toxicity?', '["Lipoatrophy", "Nephrolithiasis", "Peripheral neuropathy", "Hepatic steatosis", "Lactic acidosis"]'::jsonb, 'Nephrolithiasis', '[]'::jsonb, 'Nucleoside reverse transcriptase inhibitors inhibit mitochondrial DNA polymerase gamma, causing lactic acidosis, hepatic steatosis, peripheral neuropathy, pancreatitis, myopathy and lipoatrophy. Kidney stones are caused by crystallisation of protease inhibitors such as indinavir and atazanavir in urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.072 Q54, CAT 2 2021/2022. Paper says ''Lipodystrophy''; written as lipoatrophy, the mitochondrial form.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-ee42b5a19b', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which is not a strong phenanthrene opioid agonist?', '["Heroin", "Hydrocodone", "Oxymorphone", "Morphine", "Hydromorphone"]'::jsonb, 'Hydrocodone', '[]'::jsonb, 'In the standard classification, the strong phenanthrene agonists are morphine, hydromorphone, oxymorphone and heroin. Codeine, hydrocodone and oxycodone are phenanthrenes classed as mild to moderate agonists, used for moderate pain and often combined with paracetamol.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.072 Q55, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-1f2fca5ee4', 'pharm-aminoglycosides', 'mcq', 'All of the following statements about aminoglycosides are true except one. Which one?', '["Streptomycin can be used alone in the treatment of tuberculosis", "Amikacin has a broader spectrum of antibacterial activity than gentamicin", "Streptomycin can be given both IV and IM", "Streptomycin can cause deafness in the newborn if given in pregnancy", "Pseudomonas is resistant to neomycin"]'::jsonb, 'Streptomycin can be used alone in the treatment of tuberculosis', '[]'::jsonb, 'Tuberculosis is never treated with a single drug because resistant mutants are rapidly selected; streptomycin is always part of a combination. Amikacin resists many aminoglycoside-inactivating enzymes, so it covers organisms resistant to gentamicin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.073 Q57, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-6eab102299', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which statement regarding aspirin is false?', '["Increases the risk of myocardial infarction", "Useful in radiation-induced diarrhoea", "Associated with a reduced incidence of Alzheimer''s disease", "Associated with a reduced incidence of colon cancer", "Antipyretic"]'::jsonb, 'Increases the risk of myocardial infarction', '[]'::jsonb, 'Low-dose aspirin irreversibly acetylates platelet COX-1, blocking thromboxane A2 and so reducing the risk of myocardial infarction and stroke. Long-term use is linked with fewer colorectal cancers, and prostaglandin inhibition explains its antipyretic action and benefit in radiation-induced diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.073 Q58, CAT 2 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-eb70074712', 'pharm-anti-leprosy-drugs', 'mcq', 'Which statement is true about anti-leprosy drugs?', '["Dapsone acts by inhibiting dihydrofolate reductase", "The half-life of dapsone is 10-12 hours", "Rifampicin can be used alone in the treatment of leprosy as an alternative to dapsone", "Dapsone does not penetrate the skin", "Clofazimine has a half-life of about 2 months"]'::jsonb, 'Clofazimine has a half-life of about 2 months', '[]'::jsonb, 'Clofazimine is a lipophilic dye stored in fat and reticuloendothelial tissue and released very slowly, with a half-life of around 70 days. Dapsone inhibits dihydropteroate synthase (like sulfonamides) and has a half-life of 1 to 2 days. Leprosy is always treated with combinations.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.073 Q59, CAT 2 2021/2022. Option d replaced: paper says ''Skin concentration of dapsone is similar to that of plasma'', which is hard to verify.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-f573dd152b', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which of the following drugs is not classified as a morphinan?', '["Levorphanol", "Butorphanol", "Dextromethorphan", "Morphine", "Dextrorphan"]'::jsonb, 'Morphine', '[]'::jsonb, 'In Katzung''s classification morphine and its close relatives are phenanthrenes, while the morphinans, which lack the oxygen bridge of morphine, include levorphanol, butorphanol, dextromethorphan and its metabolite dextrorphan.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.074 Q60, CAT 2 2021/2022. Paper''s option c is nalbuphine, which Katzung classes as a phenanthrene (two defensible answers); it was replaced with dextromethorphan. Chemically, morphine is itself an epoxymorphinan, so the question rests on the textbook classification.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-e4c4c8e540', 'pharm-antibody-preparations', 'mcq', 'Which is not a biological agent used for immunosuppression?', '["Alemtuzumab", "Abatacept", "Basiliximab", "Muromonab-CD3", "Trastuzumab"]'::jsonb, 'Trastuzumab', '[]'::jsonb, 'Trastuzumab is an anti-HER2 monoclonal antibody used for HER2-positive breast and gastric cancer; it is not an immunosuppressant. Alemtuzumab (anti-CD52), basiliximab (anti-CD25), muromonab (anti-CD3) and the fusion protein abatacept all suppress lymphocyte function.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.078 Q8, CAT 2 2020/2021. Paper stem: ''Which is not a biological immunosuppression antibody?'' Abatacept is a fusion protein rather than an antibody, so it could also be argued; stem reworded.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-cc3df4677d', 'pharm-anti-fungals', 'mcq', 'All of the following are true about amphotericin B except:', '["It is a polyene macrolide antifungal drug", "Used for life-threatening fungal infections", "Inhibits fungal DNA and RNA synthesis", "Poorly absorbed from the gastrointestinal tract", "Causes hypokalaemia"]'::jsonb, 'Inhibits fungal DNA and RNA synthesis', '[]'::jsonb, 'Amphotericin B binds ergosterol in the fungal cell membrane and forms pores through which potassium and other ions leak out. Inhibition of nucleic acid synthesis is the mechanism of flucytosine. Renal tubular damage causes potassium and magnesium wasting.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.078 Q9, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-8256d5a04a', 'pharm-antihelminthics-i', 'mcq', 'Which is not a true statement about albendazole?', '["Used in the management of cystic hydatid disease caused by Echinococcus granulosus", "It has a broader spectrum than mebendazole", "Inhibits microtubule polymerisation", "Oral absorption is enhanced by fatty foods", "Is the drug of choice in helminthic infections in pregnancy"]'::jsonb, 'Is the drug of choice in helminthic infections in pregnancy', '[]'::jsonb, 'Albendazole is teratogenic and embryotoxic in animals and is avoided in pregnancy, particularly the first trimester. A fatty meal increases absorption up to five-fold, which is wanted for tissue infections such as hydatid disease and neurocysticercosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.080 Q23, CAT 2 2020/2021. Option b reworded from ''It is superior to mebendazole''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-0fe24631e1', 'pharm-antibody-preparations', 'mcq', 'Identify the anti-IgE monoclonal antibody:', '["Benralizumab", "Reslizumab", "Mepolizumab", "Dupilumab", "Omalizumab"]'::jsonb, 'Omalizumab', '[]'::jsonb, 'Omalizumab binds the Fc portion of free IgE, preventing it from attaching to mast cells and basophils; it is used in severe allergic asthma and chronic urticaria. Mepolizumab and reslizumab target interleukin-5, benralizumab its receptor, and dupilumab the interleukin-4 receptor alpha chain.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.081 Q27, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-3be2fe5b7c', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which statement about pentazocine is false?', '["High doses cause an increase in heart rate and blood pressure", "Antagonises respiratory depression produced by morphine", "Produces analgesia, sedation and respiratory depression", "Analgesic effect is due to agonistic actions at kappa receptors", "Acts as a weak antagonist or partial agonist at mu receptors"]'::jsonb, 'Antagonises respiratory depression produced by morphine', '[]'::jsonb, 'Pentazocine is a kappa agonist with only weak mu antagonist or partial agonist action. It can precipitate withdrawal in opioid-dependent patients but does not reverse morphine-induced respiratory depression. Unlike morphine, high doses raise blood pressure and heart rate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.081 Q28, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-0ca7109eba', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which statement is true regarding aspirin?', '["Undergoes ion trapping in acidic urine", "Antiplatelet effect lasts 2 days", "Long-term use increases the risk of colon cancer", "Reversibly inactivates platelet cyclooxygenase", "Is uricosuric at high doses"]'::jsonb, 'Is uricosuric at high doses', '[]'::jsonb, 'Above about 4 g/day salicylate blocks tubular reabsorption of urate and is uricosuric, whereas low doses block secretion and retain urate. Aspirin irreversibly acetylates platelet COX, so the effect lasts the platelet''s lifetime of 8 to 10 days; salicylate is trapped in alkaline urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.081 Q29, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-6c5bb5447e', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'All of the following are true of meperidine (pethidine) except:', '["Has significant antimuscarinic effects", "Has a negative inotropic action", "Fentanyl is a congener", "May cause seizures", "Its use is safe in atrial tachycardia"]'::jsonb, 'Its use is safe in atrial tachycardia', '[]'::jsonb, 'Pethidine''s atropine-like action increases heart rate, so it is avoided in patients with tachycardia. It also depresses myocardial contractility, and its metabolite normeperidine accumulates in renal failure and causes seizures. Fentanyl is a fellow phenylpiperidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.081 Q30, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-dbafd1c0f5', 'pharm-anti-tb-drugs', 'mcq', 'All of the following are true of rifampicin except:', '["Is effective against Chlamydia", "Is a semisynthetic derivative of rifamycin", "Kills both intracellular and extracellular TB organisms", "Has no cross-resistance with other antimicrobials except rifamycins", "Rifabutin is an alternative name"]'::jsonb, 'Rifabutin is an alternative name', '[]'::jsonb, 'Rifampicin is also called rifampin; rifabutin is a different rifamycin, preferred with protease inhibitors because it induces CYP3A4 less. Rifampicin inhibits DNA-dependent RNA polymerase, is bactericidal to intracellular and extracellular mycobacteria and also covers staphylococci, meningococci and Chlamydia.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.082 Q32, CAT 2 2020/2021. Paper''s option b is ''Is a natural product'', which is also false (semisynthetic), giving two exceptions; reworded to a true statement. Option c in the paper has a typo (''extracellular and extracellular'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-498e07bfd0', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which anthelmintic drug can be used for both cestode and trematode infections?', '["Praziquantel", "Albendazole", "Ivermectin", "Pyrantel pamoate", "Niclosamide"]'::jsonb, 'Praziquantel', '[]'::jsonb, 'Praziquantel is effective against all schistosomes and most other flukes (not Fasciola) as well as adult tapeworms and cysticercosis. Niclosamide acts only on tapeworms, while pyrantel and ivermectin are nematode drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.083 Q36, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-1d622efd47', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which is not used in malaria chemoprophylaxis?', '["Artesunate", "Atovaquone", "Proguanil", "Mefloquine", "Doxycycline"]'::jsonb, 'Artesunate', '[]'::jsonb, 'Artemisinins have half-lives of only a few hours, so they cannot provide sustained protection, and they are reserved for treatment to slow the spread of resistance. Atovaquone-proguanil, mefloquine and doxycycline are the standard prophylactic regimens.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.084 Q38, CAT 2 2020/2021. Paper''s option e is ''Tetracycline''; written as doxycycline, the tetracycline actually used for prophylaxis.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-ef98fe6a5b', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'Toxic amounts of the metabolite N-acetyl-p-benzoquinone imine (NAPQI) cause:', '["Bone marrow suppression", "Peptic ulcer disease", "Hepatotoxicity", "Contact dermatitis", "Ototoxicity"]'::jsonb, 'Hepatotoxicity', '[]'::jsonb, 'NAPQI is the reactive paracetamol metabolite formed by CYP2E1 and CYP3A4. Normally glutathione detoxifies it, but in overdose glutathione is depleted and NAPQI binds hepatocyte proteins, causing centrilobular liver necrosis. N-acetylcysteine replenishes glutathione.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.084 Q39, CAT 2 2020/2021. Replaced the option ''Metabolic acidosis'' (which can occur secondarily in severe poisoning) with ''Ototoxicity''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-adc2d33698', 'pharm-biologic-dmards', 'mcq', 'Which is a true statement?', '["Infliximab is a monoclonal antibody", "Tacrolimus is less potent than cyclosporine", "Cyclosporine is contraindicated after renal transplantation", "Corticosteroids stimulate the production of IL-2 and cause proliferation of T-helper cells", "Alopecia is a common adverse effect of cyclosporine"]'::jsonb, 'Infliximab is a monoclonal antibody', '[]'::jsonb, 'Infliximab is a chimeric (mouse-human) IgG1 monoclonal antibody against TNF-alpha. Tacrolimus is far more potent than cyclosporine, cyclosporine is a mainstay after renal transplantation, corticosteroids suppress interleukin-2 production, and cyclosporine causes hirsutism rather than hair loss.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.085 Q41, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-f92c66722b', 'pharm-anti-leprosy-drugs', 'mcq', 'All of the following are true about dapsone except:', '["Half-life is 1-2 days", "Resistance is most likely to develop in tuberculoid leprosy treated with low doses", "May cause erythema nodosum leprosum", "Is useful in the prevention of Pneumocystis jirovecii pneumonia in AIDS", "Acts by inhibiting folate synthesis"]'::jsonb, 'Resistance is most likely to develop in tuberculoid leprosy treated with low doses', '[]'::jsonb, 'Resistance to dapsone emerges in lepromatous (multibacillary) leprosy, where the huge bacterial load makes selection of resistant mutants likely, especially with low doses or monotherapy. Tuberculoid disease has few bacilli. Dapsone inhibits dihydropteroate synthase.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.085 Q42, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-5c52903d67', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'All of the following are true about fentanyl except:', '["Strong mu receptor agonist", "It has a minimal cardio-depressant effect", "It is a natural opioid", "Rapidly crosses the blood-brain barrier", "Is a potent analgesic"]'::jsonb, 'It is a natural opioid', '[]'::jsonb, 'Fentanyl is a fully synthetic phenylpiperidine, unrelated to the natural opium alkaloids morphine and codeine. Its high lipid solubility gives rapid entry into the brain and an onset within minutes, and it is about 100 times as potent as morphine with little cardiovascular depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.085 Q44, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-b9dfe76aa0', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'Which is the true statement about DMARDs?', '["Leflunomide has a half-life of 3 hours", "In the treatment of rheumatoid arthritis, the effects of glucocorticoids take six weeks", "Sulfasalazine is metabolised to sulfapyridine and 5-aminosalicylic acid", "Azathioprine stimulates the bone marrow", "Cyclophosphamide is contraindicated in patients with systemic lupus erythematosus"]'::jsonb, 'Sulfasalazine is metabolised to sulfapyridine and 5-aminosalicylic acid', '[]'::jsonb, 'Colonic bacteria cleave the azo bond of sulfasalazine to give sulfapyridine, thought to be the active moiety in rheumatoid arthritis, and 5-aminosalicylic acid, active in ulcerative colitis. Leflunomide''s active metabolite has a half-life of about 2 weeks and azathioprine suppresses the marrow.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.086 Q51, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-e7928a53f2', 'pharm-biologic-dmards', 'mcq', 'All of the following are true of infliximab except:', '["Anti-infliximab antibodies do not exist", "It is an IgG anti-tumour necrosis factor alpha monoclonal antibody", "Used in rheumatoid arthritis", "Administered as an intravenous infusion", "Associated with an increased risk of tuberculosis"]'::jsonb, 'Anti-infliximab antibodies do not exist', '[]'::jsonb, 'Because infliximab is chimeric, with mouse variable regions, patients often develop anti-infliximab (human anti-chimeric) antibodies that cause infusion reactions and loss of response; methotrexate is co-prescribed to reduce this. Latent tuberculosis must be screened for before treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.087 Q53, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-ef8ed06558', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All of the following are true about morphine except:', '["One of its metabolites is 6-monoacetylmorphine", "Contraindicated in individuals with severe head injury", "Less potent than hydromorphone", "Reduces sensitivity of the respiratory centre to carbon dioxide", "Undergoes significant first-pass metabolism"]'::jsonb, 'One of its metabolites is 6-monoacetylmorphine', '[]'::jsonb, '6-Monoacetylmorphine is the active metabolite of heroin (diacetylmorphine), not of morphine. Morphine is conjugated to morphine-3-glucuronide and the active morphine-6-glucuronide. In head injury the rise in carbon dioxide raises intracranial pressure and miosis masks pupillary signs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.088 Q59, CAT 2 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-7c7e20b472', 'pharm-macrolides', 'mcq', 'Which of the following drugs is approved for primary prophylaxis against Mycobacterium avium-intracellulare infection in AIDS patients with low CD4 counts?', '["Nafcillin", "Amoxicillin", "Doxycycline", "Ceftriaxone", "Clarithromycin"]'::jsonb, 'Clarithromycin', '[]'::jsonb, 'Macrolides (clarithromycin or weekly azithromycin) are active against Mycobacterium avium complex and are used for primary prophylaxis when the CD4 count falls below about 50 cells/µL. Beta-lactams such as ceftriaxone and tetracyclines such as doxycycline have no useful activity against this intracellular mycobacterium.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.090 Q6, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-84f02763aa', 'pharm-quinolones', 'mcq', 'Which of the following fluoroquinolones has the longest half-life?', '["Ciprofloxacin", "Norfloxacin", "Levofloxacin", "Moxifloxacin", "Ofloxacin"]'::jsonb, 'Moxifloxacin', '[]'::jsonb, 'Moxifloxacin has a half-life of about 9 to 12 hours, which allows once-daily dosing. Levofloxacin (5 to 7 hours) is also given once daily but is shorter, while ciprofloxacin, norfloxacin and ofloxacin have half-lives of roughly 3 to 5 hours and are usually given twice daily.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.091 Q9, MBChB EOY 2021/2022. Paper says ''quinolines''; corrected to fluoroquinolones.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-17dc31105c', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All of the following are true of morphine EXCEPT:', '["It is effective in the treatment of pulmonary oedema", "It is the most potent opioid analgesic", "It has anxiolytic properties", "Parenteral doses are more potent than oral doses", "Fixed dose intervals are more effective than on-demand dosing"]'::jsonb, 'It is the most potent opioid analgesic', '[]'::jsonb, 'Morphine is the reference opioid but far from the most potent: fentanyl is about 100 times and sufentanil about 1000 times more potent. The other statements hold: it relieves the dyspnoea and anxiety of acute left ventricular failure, extensive first-pass metabolism makes oral doses weaker than parenteral ones, and regular dosing controls chronic pain better than on-demand dosing.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.092 Q17, MBChB EOY 2021/2022. Same question repeated on p.112 (BDS EOY 2021/2022 Q28).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-4323ee2ea1', 'pharm-acute-opioid-toxicity', 'mcq', 'Acute opioid toxicity is suggested by the triad of:', '["Hypothermia, pinpoint pupils and respiratory depression", "Pinpoint pupils, bradycardia and coma", "Respiratory depression, pinpoint pupils and bradycardia", "Hypotension, coma and respiratory depression", "Coma, pinpoint pupils and respiratory depression"]'::jsonb, 'Coma, pinpoint pupils and respiratory depression', '[]'::jsonb, 'The classic triad of opioid overdose is coma, pinpoint pupils (miosis) and respiratory depression, all mediated by mu receptors and all reversed by naloxone. Bradycardia, hypotension and hypothermia can occur but are not part of the diagnostic triad.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.093 Q22, MBChB EOY 2021/2022. Same question repeated on p.127 (2020/2021 Q49) and p.156 (2019/2020 Q85).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-fe62f4a18c', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Although fentanyl or one of its congeners is usually administered in the early stages of a general anaesthesia procedure, the patient is likely to receive an injection of morphine during the last phase. The rationale for switching to morphine is that the drug has:', '["More of a \"ceiling effect\" and less tendency to cause respiratory failure", "The advantage of being more completely reversed by naloxone", "Greater analgesic efficacy", "A longer duration of action", "Opioid receptor agonist activity, whereas fentanyl is a selective kappa receptor agonist"]'::jsonb, 'A longer duration of action', '[]'::jsonb, 'Fentanyl acts for only about 30 to 60 minutes after a bolus because it redistributes rapidly, whereas morphine gives 4 to 5 hours of analgesia that carries into the post-operative period. Both are full mu agonists with similar maximal efficacy, no ceiling to respiratory depression and full reversal by naloxone, so the difference is duration, not efficacy.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.094 Q32, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-small-molecule-inhibitors-dc3b559acc', 'pharm-anticancer-small-molecule-inhibitors', 'mcq', 'Which drug is a tyrosine kinase inhibitor?', '["Cetuximab", "Ziv-aflibercept", "Carfilzomib", "Bevacizumab", "Ponatinib"]'::jsonb, 'Ponatinib', '[]'::jsonb, 'Ponatinib is a small-molecule BCR-ABL tyrosine kinase inhibitor (the ''-tinib'' suffix), active even against the T315I mutation in chronic myeloid leukaemia. Cetuximab and bevacizumab are monoclonal antibodies, ziv-aflibercept is a VEGF-trap fusion protein, and carfilzomib is a proteasome inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.095 Q34, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-ddc5854187', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which one of the following drugs is NOT indicated for malaria chemoprophylaxis?', '["Artesunate", "Proguanil", "Pyrimethamine", "Atovaquone", "Mefloquine"]'::jsonb, 'Artesunate', '[]'::jsonb, 'Artesunate has a very short half-life and is reserved for treatment, especially severe malaria; it cannot maintain protective levels for prophylaxis. Mefloquine and atovaquone-proguanil are standard prophylactic regimens, and pyrimethamine has been used as a causal prophylactic (now limited by resistance).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.097 Q40, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-f24d7d9604', 'pharm-antibody-preparations', 'mcq', 'Which of the following drugs is used to prevent the primary immune response of a Rh-negative mother to a Rh-positive newborn?', '["Cyclophosphamide", "Rho(D) immune globulin", "Cyclosporine", "Methotrexate", "Tacrolimus"]'::jsonb, 'Rho(D) immune globulin', '[]'::jsonb, 'Rho(D) immune globulin (anti-D) is human IgG against the D antigen; given within 72 hours of delivery it clears fetal Rh-positive red cells before the mother''s immune system is primed, preventing haemolytic disease in later pregnancies. The other options are general immunosuppressants and are not antigen-specific.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.098 Q41, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-132638245e', 'pharm-anti-tb-drugs', 'mcq', 'Which one of the following anti-TB agents works by inhibiting ATP synthase in mycobacteria?', '["Delamanid", "Bedaquiline", "Cycloserine", "Rifampicin", "Isoniazid"]'::jsonb, 'Bedaquiline', '[]'::jsonb, 'Bedaquiline, a diarylquinoline, blocks the proton pump of mycobacterial ATP synthase and so starves the bacillus of energy. Delamanid, the other new MDR-TB drug, instead inhibits mycolic acid synthesis; isoniazid also targets mycolic acids, rifampicin RNA polymerase and cycloserine cell-wall D-alanine incorporation.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.099 Q46, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-e789e420f5', 'pharm-anti-fungals', 'mcq', 'Which of the following, an inhibitor of fungal cell membrane synthesis, is effective intravenously in the management of disseminated infections due to Aspergillus or Candida species?', '["Nystatin", "Flucytosine", "Voriconazole", "Caspofungin", "Amphotericin B"]'::jsonb, 'Voriconazole', '[]'::jsonb, 'Voriconazole is a triazole that inhibits 14-alpha-demethylase and therefore ergosterol synthesis for the fungal membrane; it can be given intravenously and is the drug of choice for invasive aspergillosis. Amphotericin B binds existing ergosterol rather than blocking its synthesis, and caspofungin inhibits cell wall (beta-glucan) synthesis, not the membrane.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.100 Q49, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-4780d6e09b', 'pharm-anti-tb-drugs', 'mcq', 'Which drug is used in the treatment of multidrug-resistant tuberculosis?', '["Piperacillin", "Colistin", "Moxifloxacin", "Neomycin", "Ethambutol"]'::jsonb, 'Moxifloxacin', '[]'::jsonb, 'Later-generation fluoroquinolones (moxifloxacin, levofloxacin) are core WHO group A drugs for multidrug-resistant TB, alongside bedaquiline and linezolid. Ethambutol is a first-line drug for drug-susceptible disease, and piperacillin, colistin and neomycin are not used against Mycobacterium tuberculosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.101 Q57, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-c712b44611', 'pharm-anti-tb-drugs', 'mcq', 'Rifampicin significantly reduces the drug levels of:', '["Atazanavir", "Efavirenz", "Lamivudine", "Zidovudine", "Tenofovir"]'::jsonb, 'Atazanavir', '[]'::jsonb, 'Rifampicin is a powerful inducer of CYP3A4 and P-glycoprotein and lowers protease inhibitor concentrations by 75% or more, so atazanavir should not be combined with it. Efavirenz levels fall only modestly, which is why it remains usable with rifampicin, and the nucleoside/nucleotide inhibitors are not cleared by CYP enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.102 Q62, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-6597b8c32e', 'pharm-disinfectants-and-antiseptics', 'mcq', 'All of the following are true of alcohols as antiseptics EXCEPT:', '["They act by denaturation of proteins", "Optimal killing concentrations are 60-90% by volume in water", "They have a rapid killing effect", "They inactivate both lipophilic and hydrophilic viruses", "They kill Mycobacterium tuberculosis"]'::jsonb, 'They inactivate both lipophilic and hydrophilic viruses', '[]'::jsonb, 'Ethanol and isopropanol at 60 to 90% rapidly denature proteins, killing vegetative bacteria, M. tuberculosis and many fungi, and they inactivate lipophilic (enveloped) viruses. Hydrophilic non-enveloped viruses are much more resistant, and spores are not killed, so the claim of activity against both virus groups is the false one.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.103 Q70, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-8c88a56753', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'All of the following are true about opioid partial agonists and mixed agonist-antagonists EXCEPT:', '["Buprenorphine has equal oral and sublingual bioavailability", "They should not be administered with pure agonists", "Respiratory depression caused by nalbuphine is resistant to naloxone", "Dezocine has efficacy equivalent to that of morphine", "Pentazocine causes dysphoria at higher doses"]'::jsonb, 'Buprenorphine has equal oral and sublingual bioavailability', '[]'::jsonb, 'Buprenorphine undergoes extensive first-pass metabolism, so swallowed doses are poorly bioavailable; this is why it is given sublingually or by patch. The other statements follow Katzung: these drugs can precipitate withdrawal in patients on full agonists, nalbuphine-induced respiratory depression may resist naloxone, dezocine matches morphine in efficacy and pentazocine causes kappa-mediated dysphoria.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.104 Q73, MBChB EOY 2021/2022. Stem reads ''opioid partial agonists'' in the paper; widened to include mixed agonist-antagonists since nalbuphine, pentazocine and dezocine are listed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-580ebb19bc', 'pharm-anti-tb-drugs', 'mcq', 'Which drug causes optic neuritis?', '["Ethambutol", "Rifampicin", "Pyrazinamide", "Isoniazid", "Streptomycin"]'::jsonb, 'Ethambutol', '[]'::jsonb, 'Ethambutol causes dose-related retrobulbar optic neuritis with reduced visual acuity and red-green colour blindness, so vision is checked before and during treatment. Isoniazid is mainly associated with peripheral neuropathy and hepatitis, and streptomycin with ototoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.105 Q76, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-1a41308703', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which is a natural opium alkaloid?', '["Fentanyl", "Methadone", "Tramadol", "Pethidine", "Morphine"]'::jsonb, 'Morphine', '[]'::jsonb, 'Morphine, codeine, thebaine and papaverine occur naturally in the latex of the opium poppy, Papaver somniferum. Fentanyl, methadone, tramadol and pethidine are wholly synthetic opioids with different chemical skeletons.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.106 Q77, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-3f7a4c83fa', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which statement regarding agents used in the management of gout is FALSE?', '["Rasburicase is useful in prevention of tumour lysis syndrome", "Probenecid may cause nephrotic syndrome", "10% of patients develop antibodies against pegloticase", "Azathioprine blood levels increase when administered concurrently with febuxostat", "High dose aspirin is uricosuric"]'::jsonb, '10% of patients develop antibodies against pegloticase', '[]'::jsonb, 'Pegloticase is a foreign (recombinant mammalian) uricase and is highly immunogenic: close to 90% of patients develop anti-drug antibodies, which cause loss of response and infusion reactions. The other statements are true; febuxostat, like allopurinol, blocks xanthine oxidase and so raises azathioprine and mercaptopurine levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.107 Q78, MBChB EOY 2021/2022. Same question repeated on p.119 (2020/2021 Q94).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-3dd13146ef', 'pharm-introduction-to-dmards', 'mcq', 'Which of the following is a disease-modifying antirheumatic drug (DMARD)?', '["Leflunomide", "Naproxen", "Epoprostenol", "Zafirlukast", "Colchicine"]'::jsonb, 'Leflunomide', '[]'::jsonb, 'Leflunomide inhibits dihydroorotate dehydrogenase, blocking pyrimidine synthesis in activated lymphocytes, and slows joint destruction in rheumatoid arthritis. Naproxen is an NSAID that relieves symptoms without altering disease progression, and colchicine is used in gout.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.108 Q95, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-23858ef835', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'The following are indications of paromomycin EXCEPT:', '["Visceral leishmaniasis", "Pneumonia", "Giardiasis", "Trichomoniasis", "Amoebiasis"]'::jsonb, 'Pneumonia', '[]'::jsonb, 'Paromomycin is a poorly absorbed aminoglycoside used orally as a luminal amoebicide and for giardiasis, topically for resistant trichomoniasis and by injection for visceral leishmaniasis. It has no role in pneumonia because it is not absorbed from the gut and is not used as a systemic antibacterial.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.109 Q98, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-baacde4bf3', 'pharm-anti-fungals', 'mcq', 'Interactions between this drug and cell membrane components can result in the formation of pores lined by hydrophilic groups present in the drug molecule. Which drug is it?', '["Itraconazole", "Flucytosine", "Amphotericin B", "Griseofulvin", "Terbinafine"]'::jsonb, 'Amphotericin B', '[]'::jsonb, 'Amphotericin B is an amphipathic polyene: its lipophilic side binds ergosterol in the fungal membrane while its hydroxyl-rich side lines an aqueous pore through which ions leak. Azoles and terbinafine instead inhibit ergosterol synthesis, flucytosine inhibits nucleic acid synthesis and griseofulvin disrupts microtubules.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.110 Q99, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-9155b8e115', 'pharm-introduction-to-dmards', 'mcq', 'Which of the following is NOT a disease-modifying antirheumatic drug (DMARD)?', '["Methotrexate", "Penicillamine", "Chloroquine", "Mefenamic acid", "Organic gold compounds"]'::jsonb, 'Mefenamic acid', '[]'::jsonb, 'Mefenamic acid is a fenamate NSAID: it relieves pain and inflammation but does not slow joint damage. Methotrexate, penicillamine, chloroquine and gold salts are all conventional DMARDs that modify the course of rheumatoid arthritis over weeks to months.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.113 Q14, BDS EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-fdec5b57c1', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following is true of paracetamol?', '["It is metabolised to an active compound", "It is highly bound to plasma proteins", "It is an anti-inflammatory drug", "It is a potent cyclooxygenase (COX)-1 and COX-2 inhibitor in peripheral tissues", "It requires no dosage adjustment in renal failure"]'::jsonb, 'It is metabolised to an active compound', '[]'::jsonb, 'Paracetamol is deacetylated to p-aminophenol, which is converted in the brain to AM404, a metabolite that contributes to analgesia; a small fraction is also oxidised to the reactive NAPQI. It is only 10 to 25% protein bound, is a weak peripheral COX inhibitor with no useful anti-inflammatory effect, and the dosing interval is lengthened in severe renal impairment.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.114 Q12, BDS EOY 2021/2022. Two options are defensible: ''metabolised to an active compound'' (AM404/NAPQI) and ''no dosage adjustment in renal failure'' (often taught as true, though the BNF lengthens the interval when eGFR <30). A hand-written tick on the scan favours the first. Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-5131c4cde1', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following drugs used in the management of gout is a uricosuric agent?', '["Diclofenac", "Low dose aspirin", "Colchicine", "Allopurinol", "Probenecid"]'::jsonb, 'Probenecid', '[]'::jsonb, 'Probenecid blocks URAT1-mediated reabsorption of urate in the proximal tubule, increasing its excretion. Low-dose aspirin does the opposite, inhibiting tubular secretion and retaining urate; allopurinol lowers urate by inhibiting xanthine oxidase, not by excretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.115 Q10, BDS EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-d7cc03ac20', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug should be given to eradicate schizonts and latent hypnozoites in the patient''s liver?', '["Amodiaquine", "Sulfadoxine", "Primaquine", "Halofantrine", "Quinine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine, an 8-aminoquinoline, is the tissue schizonticide that kills liver schizonts and the dormant hypnozoites of Plasmodium vivax and P. ovale, giving radical cure. Amodiaquine, quinine and halofantrine act only on blood schizonts and cannot prevent relapse.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.116 Q2, BDS EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-612dc802cb', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Which non-steroidal anti-inflammatory drug (NSAID) is NOT appropriately matched with its chemical class?', '["Piroxicam; enolic acid derivative", "Tolmetin; pyrrolealkanoic acid derivative", "Flurbiprofen; indole derivative", "Aspirin; salicylate", "Mefenamic acid; fenamate"]'::jsonb, 'Flurbiprofen; indole derivative', '[]'::jsonb, 'Flurbiprofen is an arylpropionic acid derivative, like ibuprofen and naproxen (the ''-profen'' ending). The indole acetic acid derivative is indomethacin. The other pairs are correct: piroxicam is an oxicam (enolic acid), tolmetin a pyrrole acetic acid and mefenamic acid a fenamate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.117 Q1, BDS EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-7d79f56520', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which of the following most accurately describes the immunosuppressant action of cyclosporine?', '["Increased catabolism of IgG antibodies", "Blockade of tissue responses to inflammatory mediators", "Interference with MHC II-peptide activation of T cells", "Activation of NK cells", "Inhibition of the gene transcription of interleukins"]'::jsonb, 'Inhibition of the gene transcription of interleukins', '[]'::jsonb, 'Cyclosporine binds cyclophilin and the complex inhibits calcineurin, so the transcription factor NFAT cannot be dephosphorylated and enter the nucleus; transcription of interleukin-2 and other cytokine genes stops. It does not block antigen presentation by MHC II itself, which is the tempting distractor.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.120 Q92, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-095ee671b9', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Clinical indications for the use of aspirin include the following EXCEPT:', '["Post coronary artery bypass grafting", "Closure of patent ductus arteriosus", "Transient ischaemic attacks", "Myocardial infarction", "Pre-eclampsia"]'::jsonb, 'Closure of patent ductus arteriosus', '[]'::jsonb, 'A patent ductus arteriosus is closed with indomethacin or ibuprofen, not aspirin, which is avoided in neonates and children. Low-dose aspirin is used for its antiplatelet effect after bypass grafting, in transient ischaemic attacks and myocardial infarction, and to reduce the risk of pre-eclampsia in high-risk pregnancies.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.121 Q85, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-c8fe1b62cf', 'pharm-anti-tb-drugs', 'mcq', 'All of the following are true of isoniazid EXCEPT:', '["It inhibits synthesis of mycolic acids in cell walls", "Its peripheral neuropathy is treated with pyridoxine", "It is used for prophylaxis of tuberculosis", "It is bactericidal", "It is metabolised via glucuronidation"]'::jsonb, 'It is metabolised via glucuronidation', '[]'::jsonb, 'Isoniazid is metabolised in the liver by N-acetyltransferase 2 (acetylation), with genetically fast and slow acetylators; glucuronidation is not its pathway. It is a bactericidal inhibitor of mycolic acid synthesis, is used alone for preventive therapy, and its neuropathy is prevented or treated with pyridoxine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.122 Q82, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-f5cb25cbed', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'In which condition is methotrexate NOT indicated?', '["Steroid-resistant asthma", "Glomerulonephritis", "Rheumatoid arthritis", "Pulmonary fibrosis", "Psoriasis"]'::jsonb, 'Pulmonary fibrosis', '[]'::jsonb, 'Methotrexate itself causes pneumonitis and pulmonary fibrosis, so existing lung fibrosis is a reason to avoid it, not to give it. It is a first-line DMARD in rheumatoid arthritis, is widely used in psoriasis and has been used as a steroid-sparing agent in severe asthma.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.123 Q79, MBChB EOY 2020/2021. Glomerulonephritis is not a standard indication for methotrexate either (it is nephrotoxic at high dose), so two options could be defended; pulmonary fibrosis is the intended answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-757031f0b0', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which is the drug of choice for treatment of Taenia saginata infection?', '["Diethylcarbamazine", "Albendazole", "Niclosamide", "Ivermectin", "Praziquantel"]'::jsonb, 'Praziquantel', '[]'::jsonb, 'A single dose of praziquantel (5 to 10 mg/kg) cures beef tapeworm infection in nearly all patients and is listed as the drug of choice in Katzung. Niclosamide is an equally effective alternative where available; albendazole is less reliable against adult Taenia.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.125 Q72, MBChB EOY 2020/2021. Both praziquantel and niclosamide are accepted first-line drugs for Taenia saginata (Katzung lists ''praziquantel or niclosamide''); the examiner''s intended answer is unknown.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-2ca2282cb4', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which is true of opioids?', '["Morphine is more potent than fentanyl", "They cause mydriasis", "Morphine relieves somatic pain better than visceral pain", "They cross the placental barrier poorly", "Morphine relieves nociceptive pain better than neuropathic pain"]'::jsonb, 'Morphine relieves nociceptive pain better than neuropathic pain', '[]'::jsonb, 'Opioids work best for nociceptive pain; neuropathic pain responds poorly and usually needs adjuvants such as amitriptyline or gabapentin. Fentanyl is about 100 times more potent than morphine, opioids cause miosis, they relieve dull visceral pain better than sharp somatic pain, and they cross the placenta readily, causing neonatal respiratory depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.126 Q63, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-470218aff8', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which statement about chloroquine is FALSE?', '["Resistance is very common in P. falciparum", "It has maximal activity against hypnozoites", "It prevents biocrystallisation of haem into haemozoin", "It causes retinopathy", "It is a synthetic 4-aminoquinoline"]'::jsonb, 'It has maximal activity against hypnozoites', '[]'::jsonb, 'Chloroquine is a blood schizonticide only; it has no effect on liver hypnozoites, which need primaquine. It concentrates in the parasite food vacuole and stops haem polymerising into haemozoin, P. falciparum resistance is widespread, and long-term high-dose use causes retinopathy.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.128 Q46, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-a113bf03cc', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which is the false statement about azathioprine?', '["It requires dose reduction when given concurrently with allopurinol", "It is used in rheumatoid arthritis", "It causes bone marrow suppression", "It acts through its major metabolite, 6-thioguanine", "It is metabolised by the cytochrome P450 3A4 enzyme system"]'::jsonb, 'It is metabolised by the cytochrome P450 3A4 enzyme system', '[]'::jsonb, 'Azathioprine is converted non-enzymatically to 6-mercaptopurine, which is then handled by xanthine oxidase, thiopurine methyltransferase (TPMT) and HGPRT, not by CYP3A4. Because xanthine oxidase inactivates it, allopurinol raises its levels and the dose must be cut to about a quarter. The active products are 6-thioguanine nucleotides.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.129 Q45, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-tumor-antibiotics-anthracyclines-4321e9eecd', 'pharm-tumor-antibiotics-anthracyclines', 'mcq', 'Which drug has cardiotoxicity as its dose-limiting toxicity?', '["Bleomycin", "Cyclophosphamide", "Doxorubicin", "Topotecan", "Methotrexate"]'::jsonb, 'Doxorubicin', '[]'::jsonb, 'Doxorubicin causes cumulative, dose-dependent cardiomyopathy through free-radical damage to cardiac myocytes, so the lifetime dose is capped at about 450 to 550 mg/m2; dexrazoxane is protective. Bleomycin is limited by pulmonary fibrosis and cyclophosphamide by myelosuppression and haemorrhagic cystitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.130 Q44, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-7bb0d2c634', 'pharm-antihelminthics-i', 'mcq', 'Which is the false statement about albendazole?', '["It is used in the treatment of neurocysticercosis", "It is active against both larval and adult stages", "Albendazole is inferior to mebendazole", "It inhibits microtubule polymerisation", "Its oral absorption is enhanced by fatty food"]'::jsonb, 'Albendazole is inferior to mebendazole', '[]'::jsonb, 'Albendazole has a broader spectrum than mebendazole and, through its well-absorbed sulfoxide metabolite, reaches tissues, making it the preferred drug for neurocysticercosis and hydatid disease. Both drugs bind beta-tubulin and block microtubule polymerisation, and a fatty meal increases albendazole absorption several-fold.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.131 Q39, MBChB EOY 2020/2021. Option d in the paper reads ''Inhibit fungal microtubule polymerization'' (probably a slip for helminth); reworded to ''It inhibits microtubule polymerisation''. As printed, that option could also be argued false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-1eacb53121', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which statement about primaquine is FALSE?', '["It can be safely used in pregnancy", "It is primarily used for terminal chemoprophylaxis", "It causes methaemoglobinaemia", "It acts against latent hepatic stages of Plasmodium", "It has extensive tissue distribution"]'::jsonb, 'It can be safely used in pregnancy', '[]'::jsonb, 'Primaquine is contraindicated in pregnancy because the fetus''s G6PD status is unknown and the drug can cause fetal haemolysis. It is used for radical cure and terminal prophylaxis against the hypnozoites of P. vivax and P. ovale, and it causes haemolysis in G6PD deficiency and methaemoglobinaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.133 Q33, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-6e66d87978', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Which statement about triptans is UNTRUE?', '["They are contraindicated in patients with angina", "They are agonists at 5-HT1D/1B receptors on presynaptic trigeminal nerve endings", "They are used for prophylaxis of migraine headaches", "They cause vasoconstriction of cerebral and meningeal vessels", "Sumatriptan may be administered subcutaneously"]'::jsonb, 'They are used for prophylaxis of migraine headaches', '[]'::jsonb, 'Triptans abort an acute migraine attack; they are not used for prophylaxis, which relies on drugs such as propranolol, amitriptyline or topiramate. As 5-HT1B/1D agonists they constrict cranial vessels and inhibit trigeminal peptide release, and their coronary vasoconstriction makes them unsafe in angina.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.134 Q32, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-small-molecule-inhibitors-5007fab544', 'pharm-anticancer-small-molecule-inhibitors', 'mcq', 'Which of the following drugs is a tyrosine kinase inhibitor?', '["Imatinib", "Ziv-aflibercept", "Bortezomib", "Cetuximab", "Omalizumab"]'::jsonb, 'Imatinib', '[]'::jsonb, 'Imatinib is a small molecule that occupies the ATP-binding site of the BCR-ABL tyrosine kinase (also c-KIT and PDGFR), transforming the treatment of chronic myeloid leukaemia. Cetuximab is an antibody against EGFR rather than a kinase inhibitor, bortezomib is a proteasome inhibitor and omalizumab an anti-IgE antibody.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.135 Q29, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-6f863b3574', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'The least COX-2 selective non-steroidal anti-inflammatory drug is:', '["Ibuprofen", "Etodolac", "Etoricoxib", "Nimesulide", "Meloxicam"]'::jsonb, 'Ibuprofen', '[]'::jsonb, 'Ibuprofen is a non-selective inhibitor of COX-1 and COX-2. Etoricoxib is highly COX-2 selective, while etodolac, nimesulide and meloxicam are ''preferential'' COX-2 inhibitors that still spare COX-1 more than ibuprofen does.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.136 Q22, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-38b43d28f1', 'pharm-anti-retrovirals', 'mcq', 'Which statement regarding antiretroviral drugs is true?', '["Efavirenz is safe in patients with a history of suicidal tendencies", "Enfuvirtide is given subcutaneously", "Abacavir should be avoided in patients with chronic renal failure", "Darunavir is an integrase inhibitor", "Dolutegravir causes weight loss when used on long-term therapy"]'::jsonb, 'Enfuvirtide is given subcutaneously', '[]'::jsonb, 'Enfuvirtide is a 36-amino-acid peptide fusion inhibitor that would be digested if swallowed, so it is injected subcutaneously twice daily. Efavirenz causes neuropsychiatric effects including suicidality, abacavir is hepatically cleared and is the NRTI that needs no renal adjustment, darunavir is a protease inhibitor and dolutegravir causes weight gain.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.138 Q18, MBChB EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-98ccd9abe7', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which is an intermediate-acting glucocorticoid?', '["Triamcinolone", "Betamethasone", "Dexamethasone", "Methylprednisolone", "Prednisolone"]'::jsonb, 'Triamcinolone', '[]'::jsonb, 'In Katzung''s classification, hydrocortisone, prednisolone and methylprednisolone are short-to-medium acting, triamcinolone is intermediate acting, and betamethasone and dexamethasone are long acting (36 to 72 hours). Betamethasone and dexamethasone are therefore clearly wrong; the prednisolone group is separated from triamcinolone only in this scheme.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.139 Q12, MBChB EOY 2020/2021. Classification-dependent: many texts class prednisolone and methylprednisolone as intermediate-acting (12-36 h) together with triamcinolone. Answer follows Katzung''s table. Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-d4d5d33bb2', 'pharm-anti-fungals', 'mcq', 'Which statement about flucytosine is accurate?', '["It does not cross the blood-brain barrier", "It inhibits cytochrome P450", "It has a wide spectrum of antifungal activity", "It is useful in oesophageal candidiasis", "It is bioactivated by fungal cytosine deaminase"]'::jsonb, 'It is bioactivated by fungal cytosine deaminase', '[]'::jsonb, 'Flucytosine is taken up by fungal cytosine permease and converted by cytosine deaminase, an enzyme human cells lack, to 5-fluorouracil, which blocks DNA and RNA synthesis. It penetrates the CSF well and is used with amphotericin B for cryptococcal meningitis, but its spectrum is narrow and it does not inhibit CYP enzymes (the azoles do).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.141 Q1, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-302917d74d', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which of the following is true of praziquantel?', '["It is excreted mainly in bile", "It should be taken on an empty stomach", "It increases the cell membrane permeability of the helminth to calcium, leading to its paralysis", "It is effective against adult but not immature schistosomes", "It is effective for treatment of all trematodes"]'::jsonb, 'It increases the cell membrane permeability of the helminth to calcium, leading to its paralysis', '[]'::jsonb, 'Praziquantel increases the permeability of the worm''s tegument to calcium, producing spastic paralysis, tegument damage and dislodgement. It is taken with food, its metabolites are excreted mainly in urine, and it fails against the liver fluke Fasciola hepatica, which needs triclabendazole.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.142 Q6, MBChB EOY 2019/2020. The option ''effective against adult but not immature schistosomes'' is also defensible (praziquantel has poor activity against juvenile schistosomula, although Katzung describes activity against adult and immature stages). Mechanism option is the intended answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-8fbf63b66c', 'pharm-anti-tb-drugs', 'mcq', 'Which statement is FALSE?', '["Both ethambutol and isoniazid cause optic neuritis", "Patients on isoniazid excrete red coloured urine", "Isoniazid monotherapy is used for prophylaxis against tuberculosis", "Rifampicin has bactericidal activity", "Rifampicin inhibits DNA-dependent RNA polymerase"]'::jsonb, 'Patients on isoniazid excrete red coloured urine', '[]'::jsonb, 'It is rifampicin, not isoniazid, that colours urine, sweat and tears orange-red. Ethambutol is the classic cause of optic neuritis, but isoniazid can rarely cause it too, so that statement stands; the remaining statements about isoniazid preventive therapy and rifampicin are standard facts.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.143 Q8, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-5cc9634e0c', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is NOT indicated for the treatment of leishmaniasis?', '["Sodium stibogluconate", "Amphotericin B", "Miltefosine", "Suramin", "Paromomycin"]'::jsonb, 'Suramin', '[]'::jsonb, 'Suramin is used for the early haemolymphatic stage of East African trypanosomiasis (Trypanosoma brucei rhodesiense), not for leishmaniasis. Pentavalent antimonials such as sodium stibogluconate, liposomal amphotericin B, oral miltefosine and parenteral paromomycin are all established antileishmanial drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.144 Q22, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-01db4add3d', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which is NOT a property of paracetamol?', '["It has a potent anti-inflammatory effect", "It is a non-prescription drug", "It has a wide therapeutic index", "It can be administered as a suppository", "It may cause hepatotoxicity"]'::jsonb, 'It has a potent anti-inflammatory effect', '[]'::jsonb, 'Paracetamol is analgesic and antipyretic but has negligible anti-inflammatory action, because it inhibits COX poorly in the peroxide-rich environment of inflamed tissue. It is sold over the counter, is available as suppositories, and in overdose its metabolite NAPQI depletes glutathione and causes hepatic necrosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.145 Q31, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-91165e54ae', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which statement about halofantrine is FALSE?', '["It should be taken with meals", "It has a long half-life", "It is cardiotoxic", "It is effective in chloroquine-resistant malaria", "It is contraindicated in pregnancy"]'::jsonb, 'It should be taken with meals', '[]'::jsonb, 'Fatty food greatly increases halofantrine absorption and with it the risk of dose-related QT prolongation and fatal arrhythmias, so it must be taken on an empty stomach. It is active against chloroquine-resistant P. falciparum, is embryotoxic in animals and so avoided in pregnancy, and it and its active metabolite persist for days.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.148 Q53, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-0b413f7e39', 'pharm-antiretroviral-i', 'mcq', 'Which is NOT a non-nucleoside reverse transcriptase inhibitor?', '["Efavirenz", "Nevirapine", "Doravirine", "Etravirine", "Stavudine"]'::jsonb, 'Stavudine', '[]'::jsonb, 'Stavudine (d4T) is a thymidine analogue, a nucleoside reverse transcriptase inhibitor that needs intracellular phosphorylation and causes chain termination. Efavirenz, nevirapine, etravirine and doravirine are NNRTIs, which bind an allosteric pocket on reverse transcriptase without needing activation.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.149 Q58, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-bb12fdae77', 'pharm-anti-retrovirals', 'mcq', 'Which antiretroviral drug is NOT effective in the treatment of hepatitis B virus/HIV co-infection?', '["Tenofovir alafenamide", "Emtricitabine", "Tenofovir disoproxil fumarate", "Lamivudine", "Dolutegravir"]'::jsonb, 'Dolutegravir', '[]'::jsonb, 'Dolutegravir inhibits HIV integrase and has no activity against hepatitis B virus, which replicates through a polymerase with reverse transcriptase activity rather than HIV-type integration. Tenofovir (both prodrugs), lamivudine and emtricitabine inhibit that HBV polymerase, so co-infected patients should receive tenofovir plus lamivudine or emtricitabine in their regimen.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.150 Q64, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-9143f7442b', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which is NOT a calcineurin inhibitor?', '["Tacrolimus", "Cyclosporine", "Pimecrolimus", "Sirolimus", "Voclosporin"]'::jsonb, 'Sirolimus', '[]'::jsonb, 'Sirolimus (rapamycin) binds FKBP-12 just as tacrolimus does, but the complex inhibits mTOR, blocking the T-cell response to interleukin-2 rather than its production. Cyclosporine, voclosporin, tacrolimus and topical pimecrolimus all inhibit calcineurin and so prevent IL-2 gene transcription.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.151 Q70, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-e8510a165e', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which drug does NOT lower uric acid levels?', '["Probenecid", "Febuxostat", "Allopurinol", "Losartan", "Low dose aspirin"]'::jsonb, 'Low dose aspirin', '[]'::jsonb, 'Low-dose aspirin inhibits tubular secretion of urate and so raises serum uric acid; only high doses (over about 4 g/day) are uricosuric. Losartan is the one angiotensin receptor blocker with a useful uricosuric effect, probenecid is uricosuric, and allopurinol and febuxostat inhibit xanthine oxidase.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.152 Q71, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-dfbd3c27eb', 'pharm-disinfectants-and-antiseptics', 'mcq', 'All of the following are true of peroxygen disinfectants (hydrogen peroxide, peracetic acid) EXCEPT:', '["They are active against spores", "They are very effective disinfectants when used on inanimate objects or materials", "They are used as sterilants", "Their decomposition products are environmental pollutants", "They are safe for use in sterilising eating utensils"]'::jsonb, 'Their decomposition products are environmental pollutants', '[]'::jsonb, 'Hydrogen peroxide breaks down to water and oxygen, and peracetic acid to acetic acid, water and oxygen, so they leave no toxic or polluting residue. This is exactly why they are favoured for food-contact surfaces and utensils. At suitable concentrations they are sporicidal and are used as sterilants for instruments such as endoscopes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.153 Q72, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-cfcda3a534', 'pharm-antivirals', 'mcq', 'Which statement about the mechanisms of action of antiviral drugs is FALSE?', '["Interferons increase the activity of host phosphodiesterases that degrade tRNA", "The initial step in activation of famciclovir in HSV-infected cells is its phosphorylation by viral thymidine kinase", "Ganciclovir inhibits viral DNA polymerase but does not cause chain termination", "The reverse transcriptase of HIV is 30-50 times more sensitive to inhibition by indinavir than host cell DNA polymerases", "Foscarnet has no requirement for activation by phosphorylation"]'::jsonb, 'The reverse transcriptase of HIV is 30-50 times more sensitive to inhibition by indinavir than host cell DNA polymerases', '[]'::jsonb, 'Indinavir is a protease inhibitor: it blocks cleavage of the gag-pol polyprotein and does not inhibit reverse transcriptase at all. The selectivity statement would fit a nucleoside reverse transcriptase inhibitor. The others are accepted teaching (Katzung & Trevor), including that foscarnet, a pyrophosphate analogue, inhibits polymerase directly without phosphorylation.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.154 Q83, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-6ca3c38450', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which is the narcotic antagonist with the longest half-life?', '["Naloxone", "Nalbuphine", "Nalmefene", "Nalorphine", "Naltrexone"]'::jsonb, 'Naltrexone', '[]'::jsonb, 'Naltrexone has a half-life of about 10 hours, extended by its active metabolite 6-beta-naltrexol (about 13 hours), so a single oral dose blocks opioids for 24 to 48 hours. Naloxone lasts only 1 to 2 hours. Nalmefene is also long acting (8 to 11 hours), which makes it the tempting alternative.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.155 Q84, MBChB EOY 2019/2020. Naltrexone and nalmefene have similar quoted half-lives (Katzung: naltrexone 10 h, nalmefene 8-10 h; other sources give nalmefene about 11 h and parent naltrexone about 4 h). Either could be the examiner''s answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-16fd1ceb7c', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which statement regarding diloxanide furoate is INCORRECT?', '["It is effective against tissue trophozoites", "It is metabolised in the gastrointestinal tract", "It is a luminal amoebicide", "It causes flatulence", "Its mechanism of action is unknown"]'::jsonb, 'It is effective against tissue trophozoites', '[]'::jsonb, 'Diloxanide furoate is a luminal amoebicide only: it clears cysts and trophozoites from the bowel lumen but does not reach effective levels against trophozoites in the gut wall or liver, which need metronidazole. The ester is split in the gut to diloxanide and furoic acid, its mechanism is unknown, and flatulence is its commonest side effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.157 Q89, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-0ce1cb2b28', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which ectoparasiticide is used for the treatment of both pediculosis and scabies?', '["Malathion", "Benzyl alcohol", "Crotamiton", "Ivermectin", "Lindane"]'::jsonb, 'Lindane', '[]'::jsonb, 'Lindane (gamma benzene hexachloride) is licensed as a lotion for scabies and a shampoo for pediculosis, though neurotoxicity makes it second line. Crotamiton is a scabicide only and benzyl alcohol lotion is for head lice only. Permethrin, not listed here, is the preferred agent for both.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.158 Q91, MBChB EOY 2019/2020. More than one option is defensible: ivermectin (oral for scabies, topical/oral for lice) and malathion (BNF: head lice and scabies) are also used for both. Lindane is the classic textbook answer (Katzung). Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-99b75d32fb', 'pharm-anti-fungals', 'mcq', 'Which azole antifungal drug is used only topically?', '["Fluconazole", "Voriconazole", "Econazole", "Itraconazole", "Ketoconazole"]'::jsonb, 'Econazole', '[]'::jsonb, 'Econazole is an imidazole available only as creams, powders and pessaries for dermatophyte and candidal infections. Fluconazole, itraconazole and voriconazole are systemic triazoles, and ketoconazole, although now mostly used as cream or shampoo, also exists as an oral drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.159 Q96, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-7268d425f3', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which glucocorticoid is NOT appropriately matched with its clinical indication?', '["Budesonide; inhalation therapy in asthma", "Hydrocortisone; treatment of acute adrenal insufficiency", "Beclomethasone; suppression of immunologic reactions in chronic graft-versus-host disease following solid organ allografts", "Betamethasone; given to pregnant women in premature labour to hasten fetal lung maturation", "Dexamethasone; cortisol suppression test in the diagnosis of Cushing''s syndrome"]'::jsonb, 'Beclomethasone; suppression of immunologic reactions in chronic graft-versus-host disease following solid organ allografts', '[]'::jsonb, 'Beclomethasone is a topical steroid given by inhaler or nasal spray, with high first-pass metabolism limiting systemic effect, so it is not the drug for systemic immunosuppression; prednisolone or methylprednisolone is used for that. The other pairings are standard uses.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.160 Q97, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-66fe2194a0', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Mucositis is most commonly seen with which of the following drugs?', '["Celecoxib", "Leflunomide", "Methotrexate", "Hydroxychloroquine", "Azathioprine"]'::jsonb, 'Methotrexate', '[]'::jsonb, 'Methotrexate inhibits dihydrofolate reductase, starving rapidly dividing cells of thymidylate and purines, so the oral and gut mucosa suffer first: mouth ulcers and stomatitis are its commonest dose-limiting effects and are reduced by folic or folinic acid. Leflunomide mainly causes diarrhoea and raised liver enzymes, and azathioprine mainly bone marrow suppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.162, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-0cba1e6008', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Indicate a cholinesterase inhibitor which has an additional direct nicotinic agonist effect:', '["Carbachol", "Echothiophate", "Lobeline", "Neostigmine", "Edrophonium"]'::jsonb, 'Neostigmine', '[]'::jsonb, 'Neostigmine is a quaternary carbamate that, besides inhibiting acetylcholinesterase, directly stimulates nicotinic receptors at the neuromuscular junction, which adds to its usefulness in myasthenia gravis and in reversing non-depolarising block. Lobeline and carbachol are direct agonists but are not cholinesterase inhibitors, and echothiophate and edrophonium lack the direct action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.164 (also p.163), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-1d6858ba5a', 'pharm-antivirals', 'mcq', 'Which drug is used for prevention of influenza A?', '["Saquinavir", "Acyclovir", "Rimantadine", "Ribavirin", "Foscarnet"]'::jsonb, 'Rimantadine', '[]'::jsonb, 'Rimantadine and amantadine block the M2 proton channel of influenza A, preventing viral uncoating, and have been used for prophylaxis and early treatment of influenza A only (resistance is now widespread, so neuraminidase inhibitors are preferred). Ribavirin is used for RSV and hepatitis C, acyclovir for herpesviruses, foscarnet for CMV and saquinavir for HIV.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.165 (also p.176), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-207c4cc7b8', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Which drug is indicated for treatment of acute attacks of migraine?', '["Sumatriptan", "Verapamil", "Propranolol", "Valproic acid", "Amitriptyline"]'::jsonb, 'Sumatriptan', '[]'::jsonb, 'Sumatriptan is a 5-HT1B/1D agonist that constricts dilated cranial vessels and inhibits release of vasoactive peptides from trigeminal nerve endings, aborting an attack once it has started. Propranolol, verapamil, valproate and amitriptyline are all taken regularly to reduce the frequency of attacks; they do nothing for an acute attack.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.166, MBChB special/supplementary 2019/2020. Photograph is faint but all five options were legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-a01f0a9160', 'pharm-anti-fungals', 'mcq', 'Which antifungal is NOT used for systemic fungal infection?', '["Echinocandins", "Flucytosine", "Nystatin", "Fluconazole", "Amphotericin B"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is a polyene like amphotericin B but is too toxic for parenteral use and is not absorbed from the gut, skin or vagina, so it is confined to topical and oral (local) treatment of candidiasis. Amphotericin B, flucytosine, fluconazole and the echinocandins are all given systemically for deep mycoses.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.167 (also p.175), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-b03182657b', 'pharm-anti-tb-drugs', 'mcq', 'Which is a second line anti-TB drug?', '["Rifampicin", "Ethionamide", "Pyrazinamide", "Isoniazid", "Streptomycin"]'::jsonb, 'Ethionamide', '[]'::jsonb, 'Ethionamide, a relative of isoniazid that blocks mycolic acid synthesis, is reserved for drug-resistant TB because of poor gastrointestinal tolerance, hepatotoxicity and neurotoxicity. Rifampicin, isoniazid and pyrazinamide are core first-line drugs, and standard textbooks list streptomycin with the first-line agents.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.170, MBChB special/supplementary 2019/2020. Ethionamide is unambiguously second line, but current WHO grouping also treats streptomycin as a second-line injectable, so a student could defend it. Textbook (Katzung) classification keeps streptomycin first line.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-07c8ed7667', 'pharm-antiretroviral-i', 'mcq', 'All are non-nucleoside reverse transcriptase inhibitors EXCEPT:', '["Etravirine", "Efavirenz", "Nevirapine", "Delavirdine", "Stavudine"]'::jsonb, 'Stavudine', '[]'::jsonb, 'Stavudine is a thymidine analogue, a nucleoside reverse transcriptase inhibitor that must be phosphorylated and then terminates the DNA chain. Etravirine, efavirenz, nevirapine and delavirdine are NNRTIs: they bind an allosteric pocket on reverse transcriptase without needing phosphorylation.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.172, MBChB special/supplementary 2019/2020. The paper prints option d as ''Drotaverine'' (an antispasmodic, which would also not be an NNRTI and make two answers correct). It is almost certainly a typo for an NNRTI; replaced with ''Delavirdine''. Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-69375415f8', 'pharm-antiretroviral-i', 'mcq', 'All the antiretroviral drugs listed below are effective in the treatment of hepatitis B virus co-infection EXCEPT:', '["Dolutegravir", "Emtricitabine", "Tenofovir alafenamide", "Lamivudine", "Tenofovir disoproxil fumarate"]'::jsonb, 'Dolutegravir', '[]'::jsonb, 'Dolutegravir is an integrase strand transfer inhibitor; hepatitis B virus replicates through a reverse-transcribing polymerase and does not depend on HIV integrase, so it is unaffected. Lamivudine, emtricitabine and both tenofovir prodrugs inhibit the HBV polymerase as well as HIV reverse transcriptase, so co-infected patients should have tenofovir plus lamivudine or emtricitabine in their regimen.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.174, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-a127a40ad3', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which is NOT an ectoparasiticide?', '["Permethrin", "Ivermectin", "Spinosad", "Lindane", "Levamisole"]'::jsonb, 'Levamisole', '[]'::jsonb, 'Levamisole is a nicotinic agonist anthelmintic that paralyses roundworms such as Ascaris, and also an immunomodulator; it has no use against lice or mites. Permethrin, lindane and spinosad are applied topically for scabies or pediculosis, and ivermectin is used orally or topically for scabies and head lice.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.177, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-e0d3f06fe8', 'pharm-antivirals', 'mcq', 'The following antivirals are used in management of cytomegalovirus EXCEPT:', '["Valganciclovir", "Foscarnet", "Ganciclovir", "Cidofovir", "Penciclovir"]'::jsonb, 'Penciclovir', '[]'::jsonb, 'Penciclovir, like acyclovir, needs viral thymidine kinase for activation and is used topically for herpes labialis (famciclovir is its oral prodrug for HSV and VZV); it is not useful against CMV. Ganciclovir and its prodrug valganciclovir are activated by the CMV UL97 kinase, while foscarnet and cidofovir inhibit CMV DNA polymerase without needing viral kinases.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.180 Q9, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-814123224c', 'pharm-antivirals', 'mcq', 'Acyclovir is effective in the treatment of all the following viral infections EXCEPT:', '["Genital herpes", "CMV retinitis", "Herpes encephalitis", "Orolabial herpes", "Varicella zoster infection"]'::jsonb, 'CMV retinitis', '[]'::jsonb, 'Acyclovir must first be phosphorylated by a viral thymidine kinase, which herpes simplex and varicella zoster possess but cytomegalovirus lacks, so CMV is clinically resistant. CMV retinitis is treated with ganciclovir, valganciclovir, foscarnet or cidofovir.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.180 Q10, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-add7bf9153', 'pharm-anti-tb-drugs', 'mcq', 'Which is NOT a first line anti-TB drug?', '["Amikacin", "Ethambutol", "Streptomycin", "Pyrazinamide", "Rifampicin"]'::jsonb, 'Amikacin', '[]'::jsonb, 'Amikacin is an injectable aminoglycoside held in reserve for multidrug-resistant TB. Rifampicin, isoniazid, pyrazinamide and ethambutol make up the standard RHZE regimen, and textbooks list streptomycin as the fifth first-line agent.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.181 Q11, BDS EOY 2019/2020. Amikacin is clearly not first line, but under the current WHO grouping streptomycin is no longer first line either, so two options could be defended. Textbook classification assumed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-62281d76f0', 'pharm-antihelminthics-i', 'mcq', 'What is the mechanism of action of albendazole?', '["Inhibits 30S ribosomal subunit", "Inhibits integration of the virus into human chromosome", "Inhibits mycolic acid synthesis", "Inhibits conversion of haem to haemozoin", "Causes degeneration of cytoplasmic microtubules"]'::jsonb, 'Causes degeneration of cytoplasmic microtubules', '[]'::jsonb, 'Benzimidazoles such as albendazole bind parasite beta-tubulin and stop microtubule polymerisation, so the worm cannot take up glucose and slowly dies. Blocking haem polymerisation to haemozoin is how chloroquine acts on malaria parasites, and mycolic acid synthesis is the target of isoniazid.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.182 Q4, BDS EOY 2019/2020. Faint photograph; read from the image.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-3789ace422', 'pharm-biologic-dmards', 'mcq', 'Which of the following is a biologic disease modifying antirheumatic drug (DMARD)?', '["Mycophenolate mofetil", "Etanercept", "Methotrexate", "Cyclosporine", "Azathioprine"]'::jsonb, 'Etanercept', '[]'::jsonb, 'Etanercept is a recombinant fusion protein of the TNF receptor and the Fc part of IgG1 that mops up TNF-alpha; being a protein made in living cells, it is a biologic. Methotrexate, azathioprine, cyclosporine and mycophenolate are small synthetic molecules, so they are conventional (non-biologic) agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.183 Q25, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-c57ca3e633', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Clinical uses of opioids include the following EXCEPT:', '["Antitussive", "Treatment of acute pulmonary oedema", "Analgesic", "Treatment of pulmonary hypertension", "Treatment of diarrhoea"]'::jsonb, 'Treatment of pulmonary hypertension', '[]'::jsonb, 'Opioids have no place in treating pulmonary hypertension, which is managed with vasodilators such as sildenafil, bosentan and prostacyclin analogues. Morphine relieves the dyspnoea and anxiety of acute left ventricular failure and reduces preload, codeine and dextromethorphan suppress cough, and loperamide and diphenoxylate treat diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.183 Q26, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-34c3bd9c46', 'pharm-anti-tb-drugs', 'mcq', 'Which anti-TB drug cannot be used in children?', '["Ethambutol", "Isoniazid", "Streptomycin", "Rifampicin", "Pyrazinamide"]'::jsonb, 'Ethambutol', '[]'::jsonb, 'Ethambutol causes dose-related optic (retrobulbar) neuritis with loss of visual acuity and red-green colour discrimination. Young children cannot report these changes or be tested reliably, so it was traditionally avoided in those under about five or six years.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.184 Q41, BDS EOY 2019/2020. Guideline-dependent: this is the classical teaching the examiner expects, but current WHO and Kenya guidelines do give ethambutol to children at 15-25 mg/kg. Streptomycin is also discouraged in children.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-251c5c544e', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Identify an opioid antagonist:', '["Codeine", "Naloxone", "Methadone", "Buprenorphine", "Morphine"]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone is a pure competitive antagonist at mu, kappa and delta receptors, given intravenously to reverse opioid overdose within minutes. Buprenorphine is the tempting option: it is a partial mu agonist that can precipitate withdrawal in dependent patients, but it still has agonist (analgesic) activity of its own.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.185 Q33, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-608df83057', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which is the FALSE statement about clavulanic acid?', '["Administered orally", "Dose should be adjusted in renal failure", "Has excellent antimicrobial activity", "Irreversibly inhibits beta-lactamase enzyme", "Is combined with amoxicillin"]'::jsonb, 'Has excellent antimicrobial activity', '[]'::jsonb, 'Clavulanic acid has only negligible antibacterial activity of its own. Its value is as a ''suicide'' inhibitor that binds beta-lactamases irreversibly and so protects a partner penicillin such as amoxicillin from destruction. The combination is given orally (and intravenously) and is renally cleared.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.187 Q61, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-184152ce99', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which is incorrectly matched?', '["Morphine : phenanthrene", "Codeine : antitussive", "Diphenoxylate : antidiarrhoeal agent", "Naloxone : opioid antagonist", "Pentazocine : mild to moderate opioid agonist"]'::jsonb, 'Pentazocine : mild to moderate opioid agonist', '[]'::jsonb, 'Pentazocine is a mixed agonist-antagonist: an agonist at kappa receptors and a weak antagonist or partial agonist at mu receptors, so it can precipitate withdrawal in opioid-dependent patients. The mild-to-moderate pure agonists are drugs like codeine. The other four pairings are correct.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.188 Q4, Section 2: older CATs and exams. Pentazocine is the least correct pairing and the evident intended answer, but ''mild to moderate agonist'' is loosely defensible since it is used for moderate pain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-4a973a8441', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'All of the following are true of analgesics EXCEPT:', '["Gastric ulceration is caused by all NSAIDs", "Aspirin prevents platelet aggregation", "NSAIDs may cause nephrotoxicity", "Acetaminophen is hepatotoxic", "Angioneurotic oedema is a manifestation of hypersensitivity to NSAIDs"]'::jsonb, 'Gastric ulceration is caused by all NSAIDs', '[]'::jsonb, 'Ulcer risk depends on COX-1 inhibition in the gastric mucosa, so it is not uniform: selective COX-2 inhibitors such as celecoxib cause far less ulceration than non-selective drugs. The other statements hold: aspirin irreversibly acetylates platelet COX-1, NSAIDs reduce renal prostaglandin-dependent blood flow, and paracetamol overdose causes hepatic necrosis.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.189 Q12, Section 2: older CATs and exams. Intended answer by elimination; the statement is arguable because every NSAID carries some ulcer risk, only to different degrees.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-13a110f1b7', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'All of the following are true of ibuprofen EXCEPT:', '["Used in inflammatory conditions", "A propionic acid derivative", "Contraindicated in patent ductus arteriosus", "Administered via the oral route", "Causes toxic amblyopia"]'::jsonb, 'Contraindicated in patent ductus arteriosus', '[]'::jsonb, 'Far from being contraindicated, ibuprofen (like indometacin) is given to preterm infants to close a patent ductus arteriosus, because the duct is kept open by prostaglandin E2. Ibuprofen is an arylpropionic acid NSAID given orally, and toxic amblyopia is a rare but recognised adverse effect that calls for stopping the drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.189 Q13, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-1e4d6920b0', 'pharm-biologic-dmards', 'mcq', 'Which biologic disease modifying antirheumatic drug (DMARD) is incorrectly matched with its mechanism of action?', '["Anakinra : inhibition of interleukin", "Rituximab : B cell cytotoxic agent", "Tocilizumab : antibody against IL-6 receptor", "Rilonacept : TNF alpha blocking agent", "Abatacept : modulation of T cells"]'::jsonb, 'Rilonacept : TNF alpha blocking agent', '[]'::jsonb, 'Rilonacept is an interleukin-1 ''trap'', a fusion protein that binds IL-1; it does not touch TNF. The TNF-alpha blockers are infliximab, adalimumab, etanercept, golimumab and certolizumab. Anakinra blocks the IL-1 receptor, rituximab depletes CD20 B cells, tocilizumab blocks the IL-6 receptor and abatacept blocks T-cell co-stimulation.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.190 Q81, Section 2: older CATs and exams. Options c and e were amended by hand on the scan (printed ''Tocilizumab : modulation of T cells'' crossed out; ''Abatacept : modulation of T cells'' handwritten). The amended version is used; the original printed option e is not visible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-251b5ac9d8', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which is NOT a salicylic acid derivative?', '["Aspirin", "Diflunisal", "Sulfadoxine", "Sulfasalazine", "Methyl salicylate"]'::jsonb, 'Sulfadoxine', '[]'::jsonb, 'Sulfadoxine is a long-acting sulfonamide, used with pyrimethamine against malaria, and contains no salicylate. Sulfasalazine is the tempting choice because of its name, but it is 5-aminosalicylic acid joined to sulfapyridine by an azo bond, so it is a salicylate derivative. Aspirin, diflunisal and methyl salicylate are all salicylates.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.190 Q82, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-64f4415b93', 'pharm-antiretroviral-i', 'mcq', 'Which drug is a nucleoside reverse transcriptase inhibitor?', '["Abacavir", "Amprenavir", "Ritonavir", "Dolutegravir", "Lopinavir"]'::jsonb, 'Abacavir', '[]'::jsonb, 'Abacavir is a guanosine analogue NRTI, notable for a hypersensitivity reaction linked to HLA-B*5701. The ''-navir'' drugs (amprenavir, ritonavir, lopinavir) are protease inhibitors and dolutegravir (''-tegravir'') is an integrase inhibitor, so the ''-vir'' ending alone does not identify the class.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.191 Q63, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-ca5f6d5059', 'pharm-antiretroviral-i', 'mcq', 'All of the following are true of zidovudine EXCEPT:', '["Causes anaemia", "Inhibits reverse transcriptase", "Resistance is due to thymidine analogue mutations (TAMs)", "Has a synergistic effect with stavudine", "Active against both HIV-1 and HIV-2"]'::jsonb, 'Has a synergistic effect with stavudine', '[]'::jsonb, 'Zidovudine and stavudine are both thymidine analogues that compete for the same thymidine kinase for activation, so together they are antagonistic and must never be combined. Zidovudine is synergistic with lamivudine instead. Its main toxicity is bone marrow suppression with anaemia and neutropenia, and it is active against HIV-1 and HIV-2.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.192 Q64, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-8d442e2074', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'mcq', 'Which is the highest efficacy topical glucocorticoid?', '["Hydrocortisone", "Dexamethasone", "Clobetasol", "Prednisolone", "Methylprednisolone"]'::jsonb, 'Clobetasol', '[]'::jsonb, 'Clobetasol propionate is in the highest (super-potent) class of topical steroids, reserved for short courses on thick, resistant lesions. Dexamethasone is the tempting option because it is very potent systemically, but topical ranking depends on skin penetration and vasoconstrictor assay, and topical dexamethasone and hydrocortisone sit in the lowest-potency groups.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.193 Q94, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-9b5657fbe3', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Which is NOT a clinical indication of cotrimoxazole?', '["Treatment of shigellosis", "Topical application on burn wounds to prevent microbial colonization", "Treatment of recurrent urinary tract infection", "Prophylaxis against Pneumocystis jirovecii", "Treatment of respiratory tract infection by Haemophilus influenzae"]'::jsonb, 'Topical application on burn wounds to prevent microbial colonization', '[]'::jsonb, 'Cotrimoxazole (sulfamethoxazole with trimethoprim) is given orally or intravenously, never topically. The sulfonamides applied to burns are silver sulfadiazine and mafenide. Cotrimoxazole is used for urinary and respiratory infections, shigellosis, and treatment and prophylaxis of Pneumocystis jirovecii pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.194 Q70, Section 2: older CATs and exams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-4f53981533', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Which statement about chlorhexidine is FALSE?', '["It is used as a disinfectant", "It has residual activity on repeated use", "It is inhibited by blood and organic matter", "Its action is neutralised by soap", "It has low oral toxicity"]'::jsonb, 'It is inhibited by blood and organic matter', '[]'::jsonb, 'Chlorhexidine is a cationic biguanide that binds strongly to skin and mucosa, giving residual activity with repeated use, and it remains active in the presence of blood and organic material. Being cationic it is neutralised by anionic soaps and detergents, and it is poorly absorbed so oral toxicity is low.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.195 Q71, older CAT/exam (extracted CAT 1 questions). Follows Katzung (''resistant to inhibition by blood and organic materials''); some sources say organic matter reduces its activity somewhat. The same question appears on p.206 Q37 (kept this copy).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-0182c4179e', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following are true of quinine EXCEPT:', '["It is a quinoline methanol", "Haemolysis is a feature of blackwater fever", "It is a blood schizonticide", "It causes hyperglycaemia", "It is used in severe complicated malaria"]'::jsonb, 'It causes hyperglycaemia', '[]'::jsonb, 'Quinine stimulates insulin release from pancreatic beta cells, so it causes hypoglycaemia, a particular risk in pregnancy and severe malaria. It is a quinoline methanol and a rapidly acting blood schizonticide used parenterally in severe falciparum malaria; blackwater fever is the massive haemolysis with haemoglobinuria linked to its use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.196 Q43, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-0690e92075', 'pharm-transport-and-distribution', 'mcq', 'Acidic drugs bind mainly to which plasma protein?', '["Alpha-1 acid glycoprotein", "Thyroxine-binding globulin", "Lipoprotein", "Albumin", "Globulin"]'::jsonb, 'Albumin', '[]'::jsonb, 'Albumin is the most abundant plasma protein and carries most acidic drugs such as warfarin, phenytoin, salicylates and sulfonamides. Alpha-1 acid glycoprotein is the tempting wrong option: it is the main carrier of basic drugs such as lidocaine, propranolol and quinidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.196 Q44, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-a7d70f6d5f', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which disease is correctly matched with a drug used to treat it?', '["Early West African trypanosomiasis : melarsoprol", "CNS West African trypanosomiasis : eflornithine", "Amoebic colitis : kanamycin", "Visceral leishmaniasis : nifurtimox", "CNS East African trypanosomiasis : suramin"]'::jsonb, 'CNS West African trypanosomiasis : eflornithine', '[]'::jsonb, 'Eflornithine inhibits ornithine decarboxylase, crosses into the CSF and is used for late (CNS) stage Trypanosoma brucei gambiense infection. Suramin does not enter the CNS, so it is only for early East African disease; the late East African stage needs melarsoprol. Nifurtimox is for Chagas disease and kanamycin has no role in amoebiasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.197 Q83, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-b85085f1e0', 'pharm-introduction-to-dmards', 'mcq', 'Which statement is TRUE regarding disease-modifying antirheumatic drugs?', '["Their effect is evident after one week of therapy", "Chloroquine is safer than hydroxychloroquine", "Methotrexate is associated with dose-related hepatotoxicity", "Cyclosporine is the preferred agent in patients with renal injury", "Organic gold compounds are the safest disease-modifying agents"]'::jsonb, 'Methotrexate is associated with dose-related hepatotoxicity', '[]'::jsonb, 'Methotrexate causes dose-related liver enzyme elevation and, with long use, fibrosis, so liver function is monitored. DMARDs take 6 weeks to 6 months to work, hydroxychloroquine is the less toxic antimalarial, cyclosporine is nephrotoxic, and gold is among the most toxic DMARDs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.198 Q19, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-838b5ee532', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'There is minimal or no tolerance to which of the following effects of morphine?', '["Analgesia", "Convulsions", "Respiratory centre depression", "Constipation", "Euphoria"]'::jsonb, 'Constipation', '[]'::jsonb, 'Tolerance develops markedly to analgesia, euphoria, sedation and respiratory depression, but hardly at all to the constipating and miotic effects of opioids, so long-term patients need laxatives throughout. Respiratory depression is the tempting wrong option: tolerance to it does develop, although it is lost quickly after abstinence.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.199 Q15, older CAT/exam (extracted CAT 1 questions). Katzung lists minimal tolerance to miosis, constipation AND convulsions, so option ''Convulsions'' is also defensible. Constipation is the classic expected answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-34ff30555c', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which of the following drugs is INCORRECTLY matched with its mechanism of action?', '["Polymyxins : inhibition of cell wall synthesis", "Aminoglycosides : inhibition of protein synthesis at the 30S subunit", "Chloramphenicol : inhibition of protein synthesis at the 50S subunit", "Quinolones : inhibition of DNA gyrase", "Sulfonamides : inhibition of folate synthesis"]'::jsonb, 'Polymyxins : inhibition of cell wall synthesis', '[]'::jsonb, 'Polymyxins are cationic detergents that bind lipopolysaccharide and phospholipids and disrupt the bacterial cell membrane; they do not affect peptidoglycan synthesis. The other pairs are correct: aminoglycosides act on 30S, chloramphenicol on 50S, quinolones on DNA gyrase and sulfonamides on dihydropteroate synthase in the folate pathway.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.200 Q55, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-a29962991f', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which of the following is a long-acting tetracycline?', '["Methacycline", "Doxycycline", "Tetracycline", "Oxytetracycline", "Demeclocycline"]'::jsonb, 'Doxycycline', '[]'::jsonb, 'Doxycycline and minocycline are the long-acting tetracyclines, with half-lives of 16 to 18 hours that allow once or twice daily dosing. Tetracycline and oxytetracycline are short-acting (6 to 8 hours), while demeclocycline and methacycline are intermediate (about 12 hours).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.201 Q48, older CAT/exam (extracted CAT 1 questions). No tetracycline lecture in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-255a9a54ec', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which opioid antagonist has a duration of action of up to 48 hours?', '["Naloxone", "Naltrexone", "Nalmefene", "Flumazenil", "Benzomorphan"]'::jsonb, 'Naltrexone', '[]'::jsonb, 'Naltrexone is well absorbed orally and has a long-acting active metabolite, so a single oral dose blocks the effects of injected heroin for up to 48 hours; it is used for maintenance in opioid and alcohol dependence. Naloxone lasts only 1 to 2 hours, and flumazenil is a benzodiazepine antagonist, not an opioid antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.202 Q49, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-086d3bdd8d', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'The following drugs are used for preventing malaria EXCEPT:', '["Doxycycline", "Halofantrine", "Chloroquine", "Atovaquone-proguanil", "Mefloquine"]'::jsonb, 'Halofantrine', '[]'::jsonb, 'Halofantrine is used only for treatment because of its erratic absorption and dangerous QT prolongation; it has no place in prophylaxis. Doxycycline, atovaquone-proguanil and mefloquine are the standard chemoprophylactic agents, and chloroquine is still used where parasites remain sensitive.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.203 Q85, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-c6319f9896', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which is NOT an adverse effect of chronic glucocorticoid use?', '["Moon facies", "Hyperglycaemia", "Peptic ulcers", "Increased immunity", "Adrenal suppression"]'::jsonb, 'Increased immunity', '[]'::jsonb, 'Glucocorticoids suppress immunity, increasing the risk of infection and reactivation of latent tuberculosis. Long-term use produces iatrogenic Cushing''s syndrome (moon face, hyperglycaemia, osteoporosis), peptic ulceration, and suppression of the hypothalamic-pituitary-adrenal axis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.203 Q86, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-eddb60144c', 'pharm-antivirals', 'mcq', 'Which of the following is an anti-influenza drug?', '["Idoxuridine", "Trifluridine", "Vidarabine", "Amantadine", "Acyclovir"]'::jsonb, 'Amantadine', '[]'::jsonb, 'Amantadine blocks the M2 ion channel of influenza A virus and so prevents viral uncoating. Idoxuridine, trifluridine, vidarabine and acyclovir are all anti-herpes agents that interfere with viral DNA synthesis and have no activity against influenza.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.203 Q87, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-844723d4ed', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which corticosteroid has predominantly salt- and water-retaining properties?', '["Hydrocortisone", "Methylprednisolone", "Budesonide", "Fludrocortisone", "Dexamethasone"]'::jsonb, 'Fludrocortisone', '[]'::jsonb, 'Fludrocortisone has very high mineralocorticoid potency (about 125 times that of hydrocortisone) and is used for mineralocorticoid replacement in Addison''s disease. Hydrocortisone has some salt-retaining activity but equal glucocorticoid activity, while dexamethasone and methylprednisolone have almost none.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.204 Q27, older CAT/exam (extracted CAT 1 questions). Stem slightly reworded (''glucocorticoid'' -> ''corticosteroid'', ''water retention'' -> ''salt- and water-retaining'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-b0e7f13ff9', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following are true about primaquine EXCEPT:', '["It is well absorbed orally", "It is excreted unchanged in the urine", "It is effective against hypnozoites", "It is gametocidal to all Plasmodium species", "It is effective in the treatment of Pneumocystis jirovecii pneumonia"]'::jsonb, 'It is excreted unchanged in the urine', '[]'::jsonb, 'Primaquine is well absorbed and then rapidly and extensively metabolised (mainly to carboxyprimaquine); very little is excreted unchanged. It kills liver hypnozoites of P. vivax and P. ovale, is gametocidal against all four species, and with clindamycin is an alternative for mild to moderate Pneumocystis pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.205 Q36, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-3844da44e1', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which of the following immunosuppressants is a calcineurin inhibitor?', '["Prednisone", "Cyclosporine", "Azathioprine", "Cyclophosphamide", "Mycophenolate mofetil"]'::jsonb, 'Cyclosporine', '[]'::jsonb, 'Cyclosporine binds cyclophilin and the complex inhibits calcineurin, blocking NFAT activation and interleukin-2 transcription in T cells; tacrolimus does the same through FKBP. Azathioprine and mycophenolate are antiproliferative agents that block purine synthesis, and cyclophosphamide is an alkylating agent.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.206 Q38, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-24ccfb390e', 'pharm-antiretroviral-ii', 'mcq', 'Which antiretroviral agent acts as a chemokine co-receptor antagonist?', '["Bevirimat", "Zidovudine", "Maraviroc", "Lopinavir", "Efavirenz"]'::jsonb, 'Maraviroc', '[]'::jsonb, 'Maraviroc binds the host CCR5 co-receptor and prevents gp120 from engaging it, so CCR5-tropic HIV cannot enter the cell. Zidovudine is an NRTI, efavirenz an NNRTI, lopinavir a protease inhibitor and bevirimat an investigational maturation inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.207 Q43, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-902943bde7', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following are true of halofantrine EXCEPT:', '["It is well absorbed orally", "It has a half-life of about 4 days", "It is cardiotoxic", "It is contraindicated in pregnancy", "It causes elevation of liver enzymes"]'::jsonb, 'It is well absorbed orally', '[]'::jsonb, 'Oral absorption of halofantrine is erratic and variable and is increased several-fold by fatty food, which is dangerous because toxicity is dose related. Its main hazard is QT prolongation with fatal arrhythmias; it is embryotoxic in animals so avoided in pregnancy, and its terminal half-life is about 4 days.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.207 Q44, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-023604fb9e', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which statement is FALSE about antifolate drugs used for malaria?', '["Proguanil is a biguanide derivative", "Proguanil is a prodrug", "Proguanil is administered weekly for malaria chemoprophylaxis", "Sulfadoxine has a half-life of about 7 days", "They are effective against chloroquine-resistant malaria when used in combination therapy"]'::jsonb, 'Proguanil is administered weekly for malaria chemoprophylaxis', '[]'::jsonb, 'Proguanil has a half-life of only about 16 hours, so it must be taken daily for prophylaxis (alone or with atovaquone). It is a biguanide prodrug activated to cycloguanil, a DHFR inhibitor. Sulfadoxine is the long-acting sulfonamide (half-life about 170 hours) paired with pyrimethamine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.207 Q45, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-380f1ec7a3', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'All of the following are true of paracetamol EXCEPT:', '["It is a potent inhibitor of COX-1 and COX-2 in peripheral tissues", "It may be administered rectally", "It is converted to inactive metabolites", "It requires dosage adjustment in liver disease", "Acetylcysteine is the antidote in cases of poisoning"]'::jsonb, 'It is a potent inhibitor of COX-1 and COX-2 in peripheral tissues', '[]'::jsonb, 'Paracetamol is only a weak COX inhibitor in peripheral tissues, where high peroxide levels at inflamed sites blunt its action; that is why it is analgesic and antipyretic but not usefully anti-inflammatory. It is conjugated in the liver to inactive glucuronide and sulfate, and overdose is treated with acetylcysteine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.208 Q30, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-c1ad56f097', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Metronidazole has activity against the following organisms EXCEPT:', '["Bacteroides fragilis", "Staphylococcus aureus", "Giardia lamblia", "Helicobacter pylori", "Entamoeba histolytica"]'::jsonb, 'Staphylococcus aureus', '[]'::jsonb, 'Metronidazole must be reduced by the low-redox electron transport proteins found only in anaerobes and some protozoa to form its toxic nitro radical. Aerobes and facultative organisms such as Staphylococcus aureus cannot activate it. It covers anaerobic bacteria, the microaerophilic H. pylori, and Giardia, Entamoeba and Trichomonas.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.209 Q20, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-ec70617291', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'All of the following are true of sodium stibogluconate EXCEPT:', '["It is a prodrug", "Chemical pancreatitis is rare", "It is indicated in visceral leishmaniasis", "Electrocardiogram monitoring is recommended during therapy", "It is a pentavalent antimony derivative"]'::jsonb, 'Chemical pancreatitis is rare', '[]'::jsonb, 'Chemical pancreatitis, with raised amylase and lipase, occurs in most patients on pentavalent antimonials, though it is usually asymptomatic. The drug is a pentavalent antimonial thought to be reduced to the active trivalent form, is used for visceral and cutaneous leishmaniasis, and prolongs the QT interval, hence ECG monitoring.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.209 Q21, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-85d97969bd', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'All of the following are true of colchicine in the treatment of gout EXCEPT:', '["It is rapidly absorbed after oral administration", "It is mainly excreted in stool", "It prevents polymerisation of tubulin into microtubules", "It may be used for prophylaxis of recurrent episodes", "It should be given intravenously for terminating acute attacks"]'::jsonb, 'It should be given intravenously for terminating acute attacks', '[]'::jsonb, 'Colchicine is given orally in low doses; intravenous use caused fatal marrow suppression and tissue necrosis and has been abandoned. It binds tubulin, stopping leucocyte migration and phagocytosis, undergoes enterohepatic recycling with faecal excretion, and low doses prevent recurrent attacks.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.253 Q43, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-657f668b2e', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is NOT a feature of cinchonism?', '["Vertigo", "Hypertension", "Nausea", "Visual disturbance", "Tinnitus"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Cinchonism is the dose-related syndrome of quinine and quinidine: tinnitus, high-tone deafness, headache, nausea, dizziness or vertigo, flushing and visual disturbance. Quinine tends to lower blood pressure (hypotension, especially with rapid intravenous infusion); it does not cause hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.211 Q73, older CAT/exam (extracted CAT 1 questions). Photograph is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-1f6e969283', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which drug is NOT used for the treatment of trematode (fluke) infections?', '["Praziquantel", "Bithionol", "Ivermectin", "Niclosamide", "Metrifonate"]'::jsonb, 'Ivermectin', '[]'::jsonb, 'Ivermectin acts on glutamate-gated chloride channels of nematodes and arthropods and is used for onchocerciasis, strongyloidiasis and scabies; it has no activity against flukes. Praziquantel treats schistosomes and most flukes, bithionol treats fascioliasis, metrifonate treats Schistosoma haematobium, and niclosamide, mainly a tapeworm drug, is an alternative for intestinal flukes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.212 Q48, older CAT/exam (extracted CAT 1 questions). Niclosamide is chiefly a cestode drug, but Katzung lists it as an alternative for intestinal flukes, so ivermectin is the single best answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-2fff17fc33', 'pharm-antiarrhythmic-drugs', 'mcq', 'The following are true about quinidine EXCEPT:', '["It is administered both orally and parenterally", "It acts by blocking sodium channels in phase 0 of the action potential", "It lengthens action potential duration", "It acts directly on Purkinje fibres", "It stimulates adrenergic activity"]'::jsonb, 'It stimulates adrenergic activity', '[]'::jsonb, 'Quinidine has alpha-adrenoceptor blocking and antimuscarinic (vagolytic) actions; it does not stimulate adrenergic activity, and the alpha blockade explains hypotension after intravenous dosing. As a class IA agent it blocks sodium channels, slowing phase 0, and blocks potassium channels, prolonging the action potential and QT interval.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.213 Q42, older CAT/exam (extracted CAT 1 questions). Same question repeated on p.216.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-b8d9513373', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'The following are adverse effects of cyclosporine EXCEPT:', '["Alopecia", "Hypertension", "Gingival hyperplasia", "Hyperglycaemia", "Nephrotoxicity"]'::jsonb, 'Alopecia', '[]'::jsonb, 'Cyclosporine causes hirsutism (excess hair growth), not hair loss; alopecia is associated with tacrolimus instead. Its main toxicities are nephrotoxicity, hypertension, gum hyperplasia, hyperglycaemia, hyperlipidaemia, tremor and hyperkalaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.214 Q23, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-9a8a19ec7c', 'pharm-biologic-dmards', 'mcq', 'Which of the following is a tumour necrosis factor-alpha blocking agent?', '["Tofacitinib", "Rituximab", "Infliximab", "Abatacept", "Anakinra"]'::jsonb, 'Infliximab', '[]'::jsonb, 'Infliximab is a chimeric monoclonal antibody that binds TNF-alpha; adalimumab, etanercept, golimumab and certolizumab are the other TNF blockers. Tofacitinib inhibits Janus kinases, rituximab depletes CD20 B cells, abatacept blocks T-cell co-stimulation and anakinra is an IL-1 receptor antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.214 Q24, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-457b8ec0b0', 'pharm-antihelminthics-i', 'mcq', 'All of the following are true of albendazole EXCEPT:', '["It is a broad-spectrum anthelmintic", "It is the drug of choice for treatment of cysticercosis", "It inhibits microtubule synthesis", "It may cause pancytopenia", "It is well absorbed from the gastrointestinal tract"]'::jsonb, 'It is well absorbed from the gastrointestinal tract', '[]'::jsonb, 'Albendazole is poorly and erratically absorbed; a fatty meal is needed to increase uptake when treating tissue infections such as neurocysticercosis and hydatid disease, and it then undergoes first-pass conversion to active albendazole sulfoxide. It binds parasite beta-tubulin, and prolonged courses can cause marrow suppression and raised liver enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.215 Q47, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-f1878c0d50', 'pharm-topical-antimicrobials', 'mcq', 'Which is NOT a topical antimicrobial used in the treatment of acne?', '["Erythromycin", "Neomycin", "Benzoyl peroxide", "Clindamycin", "Metronidazole"]'::jsonb, 'Neomycin', '[]'::jsonb, 'Topical clindamycin, erythromycin and benzoyl peroxide act against Cutibacterium acnes and are standard for acne vulgaris, and topical metronidazole is used for acne rosacea. Neomycin is an aminoglycoside aimed at gram-negative skin organisms in wound and burn preparations; it is inactive against the anaerobic C. acnes.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.217 Q75, older CAT/exam (extracted CAT 1 questions). Metronidazole is used for rosacea rather than acne vulgaris, so it could also be defended; Katzung lists it under topical antibiotics in acne, making neomycin the best answer. The student on the scan chose metronidazole.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-3daeec00a5', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following is NOT an indication for glucocorticoids?', '["Management of gout", "Rheumatoid arthritis", "Ulcerative colitis", "Management of osteoporosis", "Prevention of organ transplant rejection"]'::jsonb, 'Management of osteoporosis', '[]'::jsonb, 'Glucocorticoids cause osteoporosis: they inhibit osteoblasts, reduce intestinal calcium absorption and increase renal calcium loss. They are useful in acute gout when NSAIDs and colchicine are unsuitable, in rheumatoid arthritis and ulcerative colitis flares, and in transplant immunosuppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.218 Q5, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-e50cebafce', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'Regarding drug interactions, azathioprine reduces the effect of which one of the following drugs?', '["Co-trimoxazole", "Ribavirin", "5-aminosalicylate", "Allopurinol", "Warfarin"]'::jsonb, 'Warfarin', '[]'::jsonb, 'Azathioprine reduces the anticoagulant effect of warfarin, so higher warfarin doses may be needed and the INR must be watched when azathioprine is started or stopped. Allopurinol is the tempting option, but that interaction runs the other way: allopurinol inhibits xanthine oxidase and raises azathioprine (6-mercaptopurine) toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.219 Q30, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-03dc10ac9c', 'pharm-anti-tb-drugs', 'mcq', 'Which of the following anti-TB drugs inhibits mycolic acid synthesis?', '["Ethionamide", "Para-aminosalicylic acid", "Rifampicin", "Pyrazinamide", "Ethambutol"]'::jsonb, 'Ethionamide', '[]'::jsonb, 'Ethionamide, like its relative isoniazid, is a prodrug that inhibits InhA and so blocks mycolic acid synthesis. Ethambutol is the tempting wrong option: it also acts on the cell wall, but by inhibiting arabinosyl transferases needed for arabinogalactan. Rifampicin blocks RNA polymerase and PAS blocks folate synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.220 Q18, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-e4357b4edd', 'pharm-topical-antimicrobials', 'mcq', 'Which of the following topical antimicrobials disrupts bacterial cell membranes and also binds and inactivates endotoxin?', '["Bacitracin", "Neomycin", "Polymyxin B sulphate", "Mupirocin", "Metronidazole"]'::jsonb, 'Polymyxin B sulphate', '[]'::jsonb, 'Polymyxin B is a cationic peptide that binds the lipid A portion of lipopolysaccharide in gram-negative outer membranes, disrupting the membrane and neutralising endotoxin. Bacitracin inhibits cell wall synthesis in gram-positive organisms, and neomycin and mupirocin inhibit protein synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.220 Q19, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-e328407971', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which drug is administered transdermally in the management of chronic pain?', '["Fentanyl", "Morphine", "Pethidine", "Heroin", "Naloxone"]'::jsonb, 'Fentanyl', '[]'::jsonb, 'Fentanyl is highly potent and very lipid soluble, so adequate doses cross the skin from a patch that gives steady analgesia for 72 hours in chronic and cancer pain. Morphine is too hydrophilic for transdermal delivery, and pethidine is unsuitable for chronic use because its metabolite norpethidine causes seizures.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.221 Q78, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-79190ab663', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which of the following antiprotozoals is used for treatment of trypanosomiasis with CNS involvement?', '["Quinine", "Suramin", "Eflornithine", "Sodium stibogluconate", "Clindamycin"]'::jsonb, 'Eflornithine', '[]'::jsonb, 'Eflornithine irreversibly inhibits ornithine decarboxylase and penetrates the CSF, making it effective in late-stage West African (T. b. gambiense) sleeping sickness. Suramin is the tempting wrong choice: it is used only for the early haemolymphatic stage because it does not cross the blood-brain barrier.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.222 Q1, older CAT/exam (extracted CAT 1 questions). Photograph is faint but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-ba720a4dbf', 'pharm-anti-fungals', 'mcq', 'Which is NOT a systemic antifungal agent?', '["Caspofungin", "Ketoconazole", "Itraconazole", "Griseofulvin", "Nystatin"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is too toxic for parenteral use and is not absorbed from the gut, skin or vagina, so it is used only topically for mucocutaneous candidiasis. Griseofulvin is the tempting wrong option: although it treats skin and nail infections, it is taken orally and reaches keratin through the bloodstream.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.223 Q30, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-f1b2d43bab', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Which is NOT an indication for NSAIDs?', '["Rheumatoid arthritis", "Patent ductus arteriosus", "Gout", "Interstitial nephritis", "Dysmenorrhoea"]'::jsonb, 'Interstitial nephritis', '[]'::jsonb, 'Interstitial nephritis is an adverse effect of NSAIDs, not a reason to give them. NSAIDs relieve inflammation in rheumatoid arthritis and acute gout, reduce prostaglandin-driven uterine cramps in dysmenorrhoea, and indomethacin or ibuprofen closes a patent ductus, which is kept open by prostaglandin E2.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.224 Q25, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-402ff48180', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which is NOT a bacteriostatic antibiotic?', '["Tetracycline", "Chloramphenicol", "Gentamicin", "Erythromycin", "Sulfamethoxazole"]'::jsonb, 'Gentamicin', '[]'::jsonb, 'Aminoglycosides such as gentamicin are the exception among protein synthesis inhibitors: they bind the 30S subunit irreversibly, cause misreading of mRNA and are rapidly bactericidal. Tetracyclines, chloramphenicol, macrolides and sulfonamides used alone only halt growth and are bacteriostatic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.224 Q26, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-7b207f8fd4', 'pharm-aminoglycosides', 'mcq', 'All of the following are true about aminoglycosides EXCEPT:', '["They inhibit protein synthesis", "They have a concentration-dependent effect", "They have a post-antibiotic effect", "They are well absorbed when administered orally", "They cause nephrotoxicity"]'::jsonb, 'They are well absorbed when administered orally', '[]'::jsonb, 'Aminoglycosides are highly polar polycations, so almost none of an oral dose is absorbed; they are given intravenously or intramuscularly (oral neomycin is used only for gut decontamination). Their concentration-dependent killing and post-antibiotic effect justify once-daily dosing, and they are nephrotoxic and ototoxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.224 Q27, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-171df2eb90', 'pharm-antivirals', 'mcq', 'Which of the following has activity against hepatitis C virus?', '["Lamivudine", "Tenofovir", "Ribavirin", "Adefovir", "Foscarnet"]'::jsonb, 'Ribavirin', '[]'::jsonb, 'Ribavirin is a guanosine analogue used in combination regimens (with interferon or direct-acting antivirals) for chronic hepatitis C. Lamivudine, tenofovir and adefovir inhibit the hepatitis B polymerase and have no effect on HCV, and foscarnet is used for resistant herpesvirus and CMV infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.225 Q28, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-b9c3b0bd23', 'pharm-antiretroviral-i', 'mcq', 'Peripheral neuropathy is most commonly associated with which antiretroviral drug?', '["Stavudine", "Indinavir", "Nevirapine", "Abacavir", "Dolutegravir"]'::jsonb, 'Stavudine', '[]'::jsonb, 'Stavudine, like didanosine and zalcitabine, inhibits mitochondrial DNA polymerase gamma, producing a dose-related painful peripheral sensory neuropathy as well as lipoatrophy and lactic acidosis. Abacavir is known for HLA-B*5701 hypersensitivity, nevirapine for rash and hepatotoxicity, and indinavir for kidney stones.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.225 Q29, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-5d8238670b', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which is NOT used for extraintestinal amoebiasis?', '["Metronidazole", "Chloroquine", "Dehydroemetine", "Emetine", "Paromomycin"]'::jsonb, 'Paromomycin', '[]'::jsonb, 'Paromomycin is an aminoglycoside that is not absorbed from the gut, so it acts only on amoebae in the bowel lumen. Tissue amoebicides are needed for liver abscess: metronidazole first, with chloroquine, emetine or dehydroemetine as alternatives, followed by a luminal agent to clear cysts.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.227 Q55, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-a0505bfac9', 'pharm-macrolides', 'mcq', 'Which is NOT a macrolide antibiotic?', '["Erythromycin", "Clarithromycin", "Azithromycin", "Clindamycin", "Telithromycin"]'::jsonb, 'Clindamycin', '[]'::jsonb, 'Clindamycin is a lincosamide: it binds the same 50S ribosomal site as macrolides but has no macrocyclic lactone ring. Telithromycin is the tempting option; it is a ketolide, a semisynthetic derivative of erythromycin that is classed with the macrolides.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.227 Q56, older CAT/exam (extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-10da3fc969', 'pharm-anti-leprosy-drugs', 'mcq', 'Which drug can be used in the treatment of both tuberculosis and leprosy?', '["Clofazimine", "Dapsone", "Rifampicin", "Pyrazinamide", "Streptomycin"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Rifampicin is bactericidal against both Mycobacterium tuberculosis and M. leprae, so it is a first-line drug in standard TB regimens and in WHO multidrug therapy for leprosy (given monthly with dapsone, plus clofazimine in multibacillary disease). Dapsone has no role in tuberculosis and pyrazinamide none in leprosy.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.228 Q57, older CAT/exam (extracted CAT 1 questions). Rifampicin is the expected answer, but clofazimine (a leprosy drug) is now also a WHO group B drug for multidrug-resistant TB, so that option is defensible too.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-2896a2fe80', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which of the following antimalarial drugs is also a disease-modifying antirheumatic drug (DMARD)?', '["Atovaquone", "Quinidine", "Chloroquine", "Primaquine", "Halofantrine"]'::jsonb, 'Chloroquine', '[]'::jsonb, 'Chloroquine and its analogue hydroxychloroquine are 4-aminoquinolines that accumulate in lysosomes, impair antigen processing and dampen T-cell responses, so they are used in rheumatoid arthritis and lupus. Primaquine is an 8-aminoquinoline used only against liver stages and gametocytes and has no antirheumatic role.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.229 Q42, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-c2118c449c', 'pharm-introduction-to-dmards', 'mcq', 'Which of the following statements is true regarding disease-modifying antirheumatic agents?', '["Effect is evident after one week of therapy", "Chloroquine is safer than hydroxychloroquine", "Methotrexate is associated with dose-related hepatotoxicity", "Cyclosporine is the preferred agent in patients with renal injury", "Organic gold compounds are the safest disease-modifying agents"]'::jsonb, 'Methotrexate is associated with dose-related hepatotoxicity', '[]'::jsonb, 'Methotrexate causes dose-related liver enzyme rises and, with long use, fibrosis, which is why liver function is monitored. DMARDs take weeks to months to work, not one week. Hydroxychloroquine is the safer 4-aminoquinoline, cyclosporine is nephrotoxic, and gold is among the most toxic DMARDs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.230 Q19, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-a011118d24', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which sulfonamide is used in combination therapy for malaria?', '["Sulfadoxine", "Sulfasalazine", "Sulfadiazine", "Silver sulfadiazine", "Sulfisoxazole"]'::jsonb, 'Sulfadoxine', '[]'::jsonb, 'Sulfadoxine is a long-acting sulfonamide given with pyrimethamine (SP, Fansidar); the pair blocks two sequential steps of folate synthesis in the parasite. Sulfadiazine is the tempting distractor, but it is paired with pyrimethamine for toxoplasmosis, not malaria.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.231 Q13, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antipruritic-agents-keratolytic-agents-b22c73b15e', 'pharm-antipruritic-agents-keratolytic-agents', 'mcq', 'Which of the following is not a keratolytic agent?', '["Fluorouracil", "Podofilox", "Lactic acid", "Doxepin", "Urea"]'::jsonb, 'Doxepin', '[]'::jsonb, 'Doxepin is a tricyclic compound with strong H1 and H2 blocking action used topically as an antipruritic. Katzung groups urea, lactic acid, podofilox and fluorouracil together as keratolytic and destructive agents, so fluorouracil, although cytotoxic, is not the odd one out.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.231 Q14, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-2fd96c011a', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which of the following agents is not scabicidal?', '["Permethrin cream", "Sulphur in petrolatum", "Whitfield''s ointment", "Oral ivermectin", "Crotamiton lotion"]'::jsonb, 'Whitfield''s ointment', '[]'::jsonb, 'Whitfield''s ointment is benzoic acid with salicylic acid, a keratolytic antifungal used for tinea; it does not kill Sarcoptes scabiei. Permethrin, sulphur ointment, crotamiton and oral ivermectin are all recognised treatments for scabies.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.231 Q15, older CAT/exam (Section 2, extracted CAT 1 questions). Option printed as ''Sulphur petroleum''; read as sulphur in petrolatum.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-ae48c5a738', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which of the following is a narrow-spectrum penicillin?', '["Piperacillin", "Carbenicillin", "Cloxacillin", "Ampicillin", "Penicillin V"]'::jsonb, 'Penicillin V', '[]'::jsonb, 'Penicillin V, like penicillin G, is a natural penicillin active mainly against Gram-positive cocci and a few other organisms, so it is the classic narrow-spectrum agent. Ampicillin, carbenicillin and piperacillin are extended-spectrum penicillins with added Gram-negative cover.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.232 Q10, older CAT/exam (Section 2, extracted CAT 1 questions). Cloxacillin is also a narrow-spectrum (antistaphylococcal) penicillin, so two options are defensible; Penicillin V is the likely intended answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-bf250832d0', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which of the following is not an adverse effect of glucocorticoids?', '["Weight loss", "Hyperglycaemia", "Easy bruisability", "Skin striae", "Myopathy"]'::jsonb, 'Weight loss', '[]'::jsonb, 'Glucocorticoids increase appetite and cause fluid retention and central fat redistribution, so weight gain, not loss, is expected. Hyperglycaemia comes from gluconeogenesis and insulin resistance, while bruising, striae and proximal myopathy all reflect protein catabolism.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.233 Q26, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-e6fdc36e10', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which of the following statements regarding monobactams is incorrect?', '["They are bacteriostatic", "Aztreonam is an example", "They are active against Gram-negative bacteria", "They require dose adjustment in renal impairment", "They may exhibit cross-sensitivity with ceftazidime"]'::jsonb, 'They are bacteriostatic', '[]'::jsonb, 'Monobactams are beta-lactams that inhibit cell wall synthesis and are therefore bactericidal. Aztreonam covers aerobic Gram-negative rods, is renally cleared, and shares a side chain with ceftazidime, which explains the one clinically relevant cross-allergy.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.234 Q13, older CAT/exam (Section 2, extracted CAT 1 questions). Question number partly obscured on the scan.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-a0f2da2db9', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which of the following is an inhibitor of renal tubular dehydropeptidase?', '["Pravastatin", "Atorvastatin", "Simvastatin", "Rosuvastatin", "Cilastatin"]'::jsonb, 'Cilastatin', '[]'::jsonb, 'Imipenem is hydrolysed by dehydropeptidase I in the renal brush border, giving low urinary levels and a nephrotoxic metabolite. Cilastatin blocks this enzyme and is co-formulated with imipenem. Despite the similar ending, the other options are HMG-CoA reductase inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.234 Q14, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-8649afde17', 'pharm-carbapenems-and-monobactams', 'mcq', 'Clinical indications for the use of carbapenems include the following EXCEPT:', '["Febrile neutropenia", "Complicated skin infections", "Bacterial meningitis", "Complicated intra-abdominal infections", "Infection with methicillin-resistant Staphylococcus aureus"]'::jsonb, 'Infection with methicillin-resistant Staphylococcus aureus', '[]'::jsonb, 'MRSA carries an altered penicillin-binding protein (PBP2a) with low affinity for nearly all beta-lactams, carbapenems included. Carbapenems are otherwise very broad and are used for febrile neutropenia, mixed skin and intra-abdominal infections, and meropenem for meningitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.234 Q15, older CAT/exam (Section 2, extracted CAT 1 questions). Question number cut off on the scan; assumed Q15.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-254fec34e0', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which of the following is a second-generation cephalosporin?', '["Cefadroxil", "Cefazolin", "Cephalexin", "Cephalothin", "Cefuroxime"]'::jsonb, 'Cefuroxime', '[]'::jsonb, 'Cefuroxime is second generation, with better activity against Haemophilus influenzae and some Enterobacteriaceae than first-generation drugs. Cefadroxil, cefazolin, cephalexin and cephalothin are all first-generation agents aimed mainly at Gram-positive cocci.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.235 Q3, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-5264c4a1a3', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'mcq', 'Which of the following is NOT used as an immunosuppressant after renal transplantation?', '["Cyclosporine", "Mycophenolate mofetil", "Levamisole", "Tacrolimus", "Methylprednisolone"]'::jsonb, 'Levamisole', '[]'::jsonb, 'Levamisole is an anthelmintic that acts as an immunostimulant, restoring depressed T-cell and macrophage function, so it would work against graft survival. Calcineurin inhibitors, mycophenolate and corticosteroids are the backbone of transplant immunosuppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.236 Q35, older CAT/exam (Section 2, extracted CAT 1 questions). Paper prints ''Methylprednisone''; corrected to methylprednisolone.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-fbcefe4b3e', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'The following are indications for opioid analgesics EXCEPT:', '["Analgesia", "Acute pulmonary oedema", "Constipation", "Shivering", "Cough"]'::jsonb, 'Constipation', '[]'::jsonb, 'Opioids reduce propulsive gut motility and increase sphincter tone, so they cause constipation and are used for diarrhoea instead. Morphine relieves the dyspnoea of acute pulmonary oedema, pethidine stops postoperative shivering, and codeine or dextromethorphan suppress cough.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.237 Q39, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-84ca2a5a8f', 'pharm-opioid-use-and-abuse', 'mcq', 'All of the following are signs of opioid withdrawal EXCEPT:', '["Rhinorrhoea", "Miosis", "Yawning", "Chills", "Gooseflesh"]'::jsonb, 'Miosis', '[]'::jsonb, 'Miosis is a sign of opioid effect or overdose; in withdrawal the pupils dilate. Withdrawal is a rebound of autonomic overactivity: rhinorrhoea, lacrimation, yawning, chills, piloerection (the origin of ''cold turkey''), diarrhoea and muscle aches.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.237 Q40, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-8b1a772ae2', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following NSAIDs is a selective COX-2 inhibitor?', '["Diclofenac", "Etoricoxib", "Acetylsalicylic acid", "Indomethacin", "Ketoprofen"]'::jsonb, 'Etoricoxib', '[]'::jsonb, 'Etoricoxib is a coxib, highly selective for COX-2, which spares gastric COX-1 but carries cardiovascular risk. Diclofenac shows some COX-2 preference yet is classed as a non-selective NSAID, and aspirin, indomethacin and ketoprofen inhibit both isoforms.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.238 Q23, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-b72ba20563', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'All of the following are true regarding the use of chloroquine or hydroxychloroquine in rheumatoid arthritis EXCEPT:', '["They are relatively safe in pregnancy", "They should be used for psoriatic lesions", "They need 12 to 24 weeks for their actions to be apparent", "They are extensively tissue bound with a long elimination half-life", "One of the proposed mechanisms of action involves stabilisation of lysosomal enzymes"]'::jsonb, 'They should be used for psoriatic lesions', '[]'::jsonb, 'Antimalarials can precipitate or worsen psoriasis, so they are avoided in psoriatic disease. They are otherwise slow-acting DMARDs (three to six months), heavily tissue bound with a very long half-life, considered relatively safe in pregnancy, and thought to act partly by stabilising lysosomes.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.238 Q24, older CAT/exam (Section 2, extracted CAT 1 questions). The paper prints option (d) as ''elimination half-life of up to 45 hours''; Katzung says up to 45 days, so the printed option is also wrong as written. Reworded to ''a long elimination half-life''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-2d8210df74', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'mcq', 'All of the following are true of artemisinins EXCEPT:', '["They are well absorbed orally", "Their half-lives are 1 to 3 hours", "They are effective only against Plasmodium falciparum", "They are effective against quinine-resistant strains", "They are not useful for chemoprophylaxis"]'::jsonb, 'They are effective only against Plasmodium falciparum', '[]'::jsonb, 'Artemisinins are rapid blood schizonticides active against all human Plasmodium species, not only P. falciparum. Their very short half-lives make them useless for prophylaxis and require a longer-acting partner drug, and they remain active against quinine- and multidrug-resistant strains.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.239 Q31, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-6c8711ff11', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Which of the following disinfectants is effective against bacterial spores and hydrophilic viruses?', '["Glutaraldehyde", "Alcohols", "Phenols", "Chlorhexidine", "Iodine"]'::jsonb, 'Glutaraldehyde', '[]'::jsonb, 'Aldehydes alkylate proteins and nucleic acids and are true sterilants: they kill spores and non-enveloped (hydrophilic) viruses as well as vegetative bacteria. Alcohols, phenols and chlorhexidine are not sporicidal and act poorly on hydrophilic viruses.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.239 Q32, older CAT/exam (Section 2, extracted CAT 1 questions). Iodine/iodophors are also virucidal and sporicidal with prolonged contact; glutaraldehyde is the best single answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-453962cc04', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Which of the following is NOT used as a preservative in pharmaceutical products?', '["Benzoic acid and its salts", "The parabens", "Sorbic acid and its salts", "Hydrogen peroxide", "Thimerosal"]'::jsonb, 'Hydrogen peroxide', '[]'::jsonb, 'Hydrogen peroxide is an unstable oxidising antiseptic and disinfectant that would break down and degrade the product. Benzoates, parabens, sorbates and the organic mercurial thimerosal are standard preservatives added to multi-dose medicines and vaccines.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.239 Q33, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-852bba13d2', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which of the following statements about opioids is false?', '["Meperidine has significant antimuscarinic effects", "Loperamide is a phenylpiperidine derivative used to control diarrhoea", "Butorphanol is a predominantly kappa agonist", "Dextromethorphan is free of addictive properties", "Remifentanil is metabolised in the liver"]'::jsonb, 'Remifentanil is metabolised in the liver', '[]'::jsonb, 'Remifentanil has an ester link that is rapidly hydrolysed by non-specific plasma and tissue esterases, giving a half-life of minutes regardless of liver function. Meperidine (pethidine) really does have atropine-like effects, which is why it can cause tachycardia and mydriasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.240 Q26, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-c5fc9058b7', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following statements about opioids is correct?', '["Methadone is a potent mu receptor antagonist", "Propoxyphene has potent analgesic activity", "Diphenoxylate is used for the treatment of constipation", "Methadone is used in the treatment of opioid abuse", "Meperidine is the opioid of choice in epilepsy"]'::jsonb, 'Methadone is used in the treatment of opioid abuse', '[]'::jsonb, 'Methadone is a long-acting oral mu agonist, so it prevents withdrawal and craving and is used for detoxification and maintenance. It is an agonist, not an antagonist. Meperidine''s metabolite normeperidine causes seizures, and diphenoxylate treats diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.240 Q27, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-9720728f94', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'All of the following are true about penicillin G EXCEPT:', '["It is effective mainly against Gram-positive and Gram-negative cocci", "It is susceptible to beta-lactamases", "It is ineffective against Treponema pallidum infections", "It is poorly absorbed orally", "It is a component of procaine penicillin"]'::jsonb, 'It is ineffective against Treponema pallidum infections', '[]'::jsonb, 'Penicillin G remains the drug of choice for syphilis; Treponema pallidum has not developed resistance. It is acid-labile, so little is absorbed orally, it is destroyed by beta-lactamases, and it is combined with procaine or benzathine for depot injection.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.241 Q34, older CAT/exam (Section 2, extracted CAT 1 questions). Paper prints option (d) as ''About 10% is absorbed orally'' (texts quote up to about a third); reworded to ''poorly absorbed orally''. ''Procrime'' corrected to procaine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-534dff7ddf', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following statements regarding uricosuric agents is false?', '["They are useful in uric acid under-excreters", "Patients on a uricosuric agent should be advised to increase their fluid intake", "Examples include high-dose aspirin", "They increase the risk of calcium oxalate nephrolithiasis", "Probenecid can cause heavy proteinuria"]'::jsonb, 'They increase the risk of calcium oxalate nephrolithiasis', '[]'::jsonb, 'By increasing urinary urate, uricosurics promote uric acid stones, not calcium oxalate stones; hence the advice to drink plenty and alkalinise the urine. High-dose aspirin is uricosuric (low doses retain urate), and probenecid can rarely cause nephrotic syndrome.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.242 Q11, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-e9483ccf32', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following antigout agents should be avoided in patients with glucose-6-phosphate dehydrogenase deficiency?', '["Probenecid", "Pegloticase", "Lesinurad", "Colchicine", "Febuxostat"]'::jsonb, 'Pegloticase', '[]'::jsonb, 'Pegloticase is a recombinant uricase that converts urate to allantoin and generates hydrogen peroxide in the process. G6PD-deficient red cells cannot cope with this oxidative stress, so haemolysis and methaemoglobinaemia occur. The other drugs do not act by producing an oxidant.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.242 Q12, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-a47ace3ffd', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which of the following drugs is not used for malaria chemoprophylaxis?', '["Primaquine", "Atovaquone", "Doxycycline", "Mefloquine", "Halofantrine"]'::jsonb, 'Halofantrine', '[]'::jsonb, 'Halofantrine has erratic absorption and causes dose-related QT prolongation with fatal arrhythmias, so it is reserved (if used at all) for treatment and never for prophylaxis. Atovaquone-proguanil, doxycycline, mefloquine and primaquine are all recognised prophylactic options.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.243 Q7, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-dfedab05ca', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which of the following non-steroidal anti-inflammatory agents is an enolic acid?', '["Nabumetone", "Antipyrine", "Piroxicam", "Etodolac", "Acetylsalicylic acid"]'::jsonb, 'Piroxicam', '[]'::jsonb, 'The oxicams (piroxicam, meloxicam, tenoxicam) are the enolic acid NSAIDs, noted for long half-lives allowing once-daily dosing. Nabumetone is a non-acidic naphthylalkanone prodrug, etodolac an acetic acid derivative, and aspirin a salicylate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.243 Q8, older CAT/exam (Section 2, extracted CAT 1 questions). Some classifications place pyrazolones (antipyrine) under enolic acids too; the course lists them separately, so piroxicam is the intended answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-9f0d8d47bb', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following statements regarding cyclooxygenase-2-selective non-steroidal anti-inflammatory agents is false?', '["Nimesulide is an example", "Chronic use of celecoxib may reduce bone mineral density", "They decrease production of PGI2", "They decrease production of thromboxane A2", "Etoricoxib requires dose adjustment in patients with hepatic impairment"]'::jsonb, 'They decrease production of thromboxane A2', '[]'::jsonb, 'Platelet thromboxane A2 is made by COX-1, which coxibs spare, while endothelial prostacyclin (PGI2) depends on COX-2 and falls. This unopposed thromboxane is the explanation given for their excess thrombotic risk.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.243 Q9, older CAT/exam (Section 2, extracted CAT 1 questions). Option (b) on bone mineral density is not well established and nimesulide is only COX-2 preferential; (d) is the clearest false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-cdb47b05cb', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following is not a feature of acute colchicine intoxication?', '["Burning throat pain", "Bloody diarrhoea", "Haematuria", "Reduced urine output", "Convulsions"]'::jsonb, 'Convulsions', '[]'::jsonb, 'Katzung describes acute colchicine overdose as burning throat pain, bloody diarrhoea, shock, haematuria and oliguria, followed by fatal ascending central nervous system depression rather than excitation. The picture reflects arrest of rapidly dividing gut and marrow cells, so gastrointestinal features dominate early.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.243 Q10, older CAT/exam (Section 2, extracted CAT 1 questions). Answer follows Katzung''s description; seizures are occasionally reported in severe colchicine poisoning, so the item is debatable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-293f4bf1db', 'pharm-antivirals', 'mcq', 'Which drug can be used for both hepatitis B and hepatitis C viral infection?', '["Adefovir", "Ribavirin", "Lamivudine", "Sofosbuvir", "Interferon"]'::jsonb, 'Interferon', '[]'::jsonb, 'Interferon alfa (usually pegylated) induces host antiviral proteins and is licensed for both chronic hepatitis B and C. Adefovir and lamivudine inhibit HBV polymerase only, while ribavirin and sofosbuvir are used for hepatitis C only.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.245 Q5, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-2bf2c0b354', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following are true about quinine EXCEPT:', '["It is obtained from the bark of the cinchona tree", "It is more potent than quinidine", "It has no significant effect on hepatic forms", "It antagonises the action of physostigmine", "It causes hypoglycaemia"]'::jsonb, 'It is more potent than quinidine', '[]'::jsonb, 'Quinidine, the dextrorotatory stereoisomer, is the more potent antimalarial and also the more cardiotoxic. Quinine is a blood schizonticide with no action on liver stages, stimulates insulin release causing hypoglycaemia, and has a curare-like effect on the motor end plate that opposes physostigmine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.245 Q6, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-a1ce365a77', 'pharm-macrolides', 'mcq', 'Which of the following is a macrolide antibiotic?', '["Clarithromycin", "Gentamicin", "Clindamycin", "Kanamycin", "Vancomycin"]'::jsonb, 'Clarithromycin', '[]'::jsonb, 'Clarithromycin has the macrocyclic lactone ring that defines macrolides and binds the 50S subunit. Clindamycin shares that binding site but is a lincosamide. Gentamicin and kanamycin are aminoglycosides despite the similar ending, and vancomycin is a glycopeptide.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.246 Q1, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-8b5442b15c', 'pharm-anti-fungals', 'mcq', 'Which statement about fluconazole is accurate?', '["It does not penetrate the blood-brain barrier", "It has the least effect of all the azoles on hepatic drug metabolism", "It is an inducer of hepatic drug-metabolising enzymes", "It is highly effective in the treatment of aspergillosis", "Its oral bioavailability is less than that of ketoconazole"]'::jsonb, 'It has the least effect of all the azoles on hepatic drug metabolism', '[]'::jsonb, 'Fluconazole is the weakest inhibitor of human cytochrome P450 among the azoles, giving it the widest therapeutic index. It is water soluble with excellent oral bioavailability and CSF penetration, but it has no useful activity against Aspergillus. Azoles inhibit, not induce, enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.246 Q2, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-e5e071dba3', 'pharm-anti-fungals', 'mcq', 'Interaction between which of these drugs and a cell membrane component can result in the formation of pores lined by hydrophilic groups present in the drug molecule?', '["Amphotericin B", "Flucytosine", "Griseofulvin", "Itraconazole", "Terbinafine"]'::jsonb, 'Amphotericin B', '[]'::jsonb, 'Amphotericin B is an amphipathic polyene: its lipophilic side binds ergosterol and several molecules assemble into a pore whose hydroxyl-lined channel leaks ions and kills the cell. Itraconazole and terbinafine reduce ergosterol synthesis but do not form pores.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.246 Q3, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-f0e2d3be47', 'pharm-antivirals', 'mcq', 'All of the following are true about acyclovir EXCEPT:', '["It is a guanosine analogue", "It is active against HSV-1, HSV-2 and VZV", "It is activated to acyclovir triphosphate", "It inhibits the neuraminidase enzyme", "It is cross-resistant with famciclovir"]'::jsonb, 'It inhibits the neuraminidase enzyme', '[]'::jsonb, 'Acyclovir triphosphate inhibits viral DNA polymerase and terminates the DNA chain; neuraminidase is the influenza target of oseltamivir and zanamivir. The first phosphorylation needs viral thymidine kinase, so kinase-deficient strains are also resistant to famciclovir and valacyclovir.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.246 Q4, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-4b329fbe47', 'pharm-anti-tb-drugs', 'mcq', 'Which anti-tuberculosis drug is NOT appropriately matched with its adverse effect?', '["Isoniazid: hepatotoxicity", "Rifampin: orange discolouration of urine", "Ethambutol: optic neuritis", "Capreomycin: ototoxicity", "Ethionamide: nephrotoxicity"]'::jsonb, 'Ethionamide: nephrotoxicity', '[]'::jsonb, 'Ethionamide is noted for intense gastric irritation, hepatotoxicity, neurological symptoms and hypothyroidism, not kidney damage. Capreomycin, an injectable peptide, is the drug that is both nephrotoxic and ototoxic, so its pairing with ototoxicity is correct.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.247 Q33, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-c34fcc247a', 'pharm-anti-fungals', 'mcq', 'Which antifungal drug inhibits fungal cell wall synthesis?', '["Fluconazole", "Terbinafine", "Amphotericin B", "Nystatin", "Caspofungin"]'::jsonb, 'Caspofungin', '[]'::jsonb, 'Echinocandins such as caspofungin inhibit beta-(1,3)-D-glucan synthase, weakening the fungal cell wall. All the other options target the cell membrane: azoles and terbinafine block ergosterol synthesis, and the polyenes amphotericin B and nystatin bind ergosterol.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.247 Q34, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-29ec514bb3', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'The following drugs have uricosuric effects EXCEPT:', '["Probenecid", "Sulfinpyrazone", "Fenofibrate", "Losartan", "Febuxostat"]'::jsonb, 'Febuxostat', '[]'::jsonb, 'Febuxostat is a non-purine xanthine oxidase inhibitor: it lowers urate by reducing its production, not by increasing excretion. Probenecid and sulfinpyrazone block tubular urate reabsorption, and fenofibrate and losartan have a useful secondary uricosuric action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.248 unnumbered question, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-0b55fb9df9', 'pharm-acute-opioid-toxicity', 'mcq', 'All of the following are true of opioid poisoning EXCEPT:', '["Respiratory rate increases", "A single dose of naloxone is inadequate", "Effects are reversed by naloxone", "Pinpoint pupils", "Needle marks on the patient may suggest addiction"]'::jsonb, 'Respiratory rate increases', '[]'::jsonb, 'Opioids depress the brainstem response to carbon dioxide, so breathing becomes slow and shallow; with coma and pinpoint pupils this forms the classic triad. Naloxone reverses it but lasts only about an hour, shorter than most opioids, so repeat doses or an infusion are needed.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.249 Q21, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-b7f2837f99', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'What is the mechanism of action of sulfonamides?', '["Inhibit topoisomerase II", "Bind to the 50S ribosomal subunit", "Bind to the 30S ribosomal subunit", "Inhibit penicillin-binding protein", "Inhibit dihydropteroate synthase"]'::jsonb, 'Inhibit dihydropteroate synthase', '[]'::jsonb, 'Sulfonamides are structural analogues of para-aminobenzoic acid and competitively inhibit dihydropteroate synthase, blocking bacterial folate synthesis. Humans use preformed folate, which gives selectivity. Topoisomerase II (DNA gyrase) is the quinolone target.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.250 Q44, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-08278d5883', 'pharm-aminoglycosides', 'mcq', 'Which of the following is not an adverse effect of aminoglycosides?', '["Ototoxicity", "Nephrotoxicity", "Hypersensitivity reactions", "Hepatotoxicity", "Muscle paralysis"]'::jsonb, 'Hepatotoxicity', '[]'::jsonb, 'Aminoglycosides are excreted unchanged by the kidney and are not metabolised by or toxic to the liver. Their hallmark toxicities are cochlear and vestibular damage, acute tubular injury and curare-like neuromuscular blockade; skin rashes and other allergic reactions occur occasionally.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.250 Q45, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-96820dd0be', 'pharm-quinolones', 'mcq', 'Which of the following is not a quinolone?', '["Levofloxacin", "Nalidixic acid", "Nitrofurantoin", "Ciprofloxacin", "Moxifloxacin"]'::jsonb, 'Nitrofurantoin', '[]'::jsonb, 'Nitrofurantoin is a nitrofuran urinary antiseptic that is reduced by bacteria to reactive intermediates damaging DNA and proteins. Nalidixic acid lacks the ''-floxacin'' ending but is the original, non-fluorinated quinolone, also used for urinary infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.250 Q46, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-4aa98b8502', 'pharm-antihelminthics-i', 'mcq', 'The following drugs cause paralysis of helminths EXCEPT:', '["Pyrantel pamoate", "Piperazine", "Ivermectin", "Niclosamide", "Diethylcarbamazine"]'::jsonb, 'Niclosamide', '[]'::jsonb, 'Niclosamide kills tapeworms by uncoupling oxidative phosphorylation and blocking glucose uptake, not by paralysis. Pyrantel causes spastic paralysis (depolarising block), piperazine and ivermectin flaccid paralysis via GABA and glutamate-gated chloride channels, and diethylcarbamazine immobilises microfilariae.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.251 Q42, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-5855f51dc8', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Choose the antimalarial agent with the longest half-life:', '["Mefloquine", "Chloroquine", "Artemether", "Quinine", "Tetracycline"]'::jsonb, 'Chloroquine', '[]'::jsonb, 'Chloroquine has an enormous volume of distribution and is released slowly from tissues, giving a terminal elimination half-life of one to two months. Mefloquine is the tempting choice at about 20 days. Quinine and tetracycline last hours, and artemether one to three hours.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.252 Q38, older CAT/exam (Section 2, extracted CAT 1 questions). Depends on which half-life is quoted: chloroquine''s initial half-life is 3-5 days, so some lecture tables rank mefloquine (about 20 days) longest. Scan blurred.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-ea402309f1', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which of the following is not used in malaria chemoprophylaxis?', '["Dapsone", "Artesunate", "Proguanil", "Doxycycline", "Pyrimethamine"]'::jsonb, 'Artesunate', '[]'::jsonb, 'Artesunate is cleared within hours, so it cannot maintain protective blood levels, and it is reserved for treatment to protect it from resistance. Proguanil, doxycycline and pyrimethamine (formerly with dapsone as Maloprim) have all been used for prophylaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.252 Q39, older CAT/exam (Section 2, extracted CAT 1 questions). Scan blurred; ''Proquanil'' read as proguanil.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-b3c430bbfc', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which antibiotic is useful for methicillin-resistant Staphylococcus aureus?', '["Amoxicillin", "Vancomycin", "Ceftriaxone", "Ciprofloxacin", "Norfloxacin"]'::jsonb, 'Vancomycin', '[]'::jsonb, 'Vancomycin binds the D-Ala-D-Ala end of peptidoglycan precursors, a target unaffected by the altered penicillin-binding protein PBP2a that makes MRSA resistant to amoxicillin, ceftriaxone and other standard beta-lactams. Fluoroquinolone resistance in MRSA is common.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.254 Q47, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-2d00c130c0', 'pharm-antivirals', 'mcq', 'Which antiviral is useful against influenza virus?', '["Oseltamivir", "Acyclovir", "Ribavirin", "Telbivudine", "Abacavir"]'::jsonb, 'Oseltamivir', '[]'::jsonb, 'Oseltamivir inhibits influenza A and B neuraminidase, preventing release of new virions from infected cells; it works best within 48 hours of symptoms. Acyclovir is for herpesviruses, telbivudine for hepatitis B and abacavir for HIV.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.254 Q48, older CAT/exam (Section 2, extracted CAT 1 questions). Ribavirin has some in-vitro anti-influenza activity but is not a standard treatment. Scan blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-d73e2bf05f', 'pharm-macrolides', 'mcq', 'Which of the following is not a macrolide antibiotic?', '["Azithromycin", "Telithromycin", "Clindamycin", "Clarithromycin", "Erythromycin"]'::jsonb, 'Clindamycin', '[]'::jsonb, 'Clindamycin is a lincosamide: it binds the same 50S site as macrolides but has no macrocyclic lactone ring. Telithromycin is a ketolide, a semisynthetic derivative of erythromycin, and is taught within the macrolide group.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.255 Q21, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-4791f3dfa5', 'pharm-biologic-dmards', 'mcq', 'Which of the following is a biologic DMARD?', '["Gold", "Penicillamine", "Rituximab", "Hydroxychloroquine", "Leflunomide"]'::jsonb, 'Rituximab', '[]'::jsonb, 'Rituximab is a chimeric monoclonal antibody against CD20 that depletes B cells; like all biologics it is a protein made in living cells. Gold, penicillamine, hydroxychloroquine and leflunomide are conventional synthetic small-molecule DMARDs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.256 Q15, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--c92d71771b', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'All of the following are true of amoxicillin EXCEPT:', '["It is administered via the oral route", "It is the standard choice for meningitis caused by Listeria monocytogenes", "Resistance occurs through production of beta-lactamases", "It causes less diarrhoea than ampicillin", "It is excreted through the kidneys"]'::jsonb, 'It is the standard choice for meningitis caused by Listeria monocytogenes', '[]'::jsonb, 'Listeria meningitis is treated with high-dose intravenous ampicillin (usually with gentamicin); amoxicillin is mainly the oral aminopenicillin. Because it is better absorbed than ampicillin, less drug reaches the colon and diarrhoea is less frequent.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.257 Q16, older CAT/exam (Section 2, extracted CAT 1 questions). Paper wording: ''Is indicated in meningitis caused by Listeria monocytogenes''. Guideline-dependent: the BNF does list intravenous amoxicillin for Listeria meningitis, so the intended answer is debatable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-2eabe5bb15', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following is an inhibitor of organic acid transport in the kidneys that is used for gout treatment?', '["Probenecid", "Chlorothiazide", "Acetazolamide", "Colchicine", "Indomethacin"]'::jsonb, 'Probenecid', '[]'::jsonb, 'Probenecid blocks organic anion transporters in the proximal tubule, including URAT1, so urate reabsorption falls and excretion rises. The same action slows secretion of penicillin. Thiazides compete for these transporters and actually raise serum urate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.258 Q59, older CAT/exam (Section 2, extracted CAT 1 questions). Paper wording ''an organic acid inhibitor in the kidneys'' clarified. ''Chlorthiazide'' read as chlorothiazide.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-5b1efff9e9', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following is NOT a COX-2 selective non-steroidal anti-inflammatory drug?', '["Meloxicam", "Piroxicam", "Celecoxib", "Etodolac", "Valdecoxib"]'::jsonb, 'Piroxicam', '[]'::jsonb, 'Piroxicam is a non-selective oxicam that inhibits COX-1 strongly and has one of the highest rates of gastrointestinal bleeding. Its relative meloxicam, together with etodolac, is preferentially COX-2 selective, while celecoxib and valdecoxib are true coxibs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.259 Q8, older CAT/exam (Section 2, extracted CAT 1 questions). Scan is blurred but legible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-273907e55e', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following statements regarding paracetamol is false?', '["It has a marked anti-inflammatory effect", "It is useful in providing an analgesic effect", "It is antipyretic", "Overdose may cause hepatic toxicity", "The antidote for paracetamol overdose is N-acetylcysteine"]'::jsonb, 'It has a marked anti-inflammatory effect', '[]'::jsonb, 'Paracetamol is a weak COX inhibitor in peripheral tissues, where high peroxide levels in inflamed sites block its action, so it is analgesic and antipyretic without useful anti-inflammatory effect. In overdose the toxic metabolite NAPQI depletes glutathione; N-acetylcysteine replenishes it.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.259 Q9, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-da9d9956eb', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Which of the following antibiotics may cause grey baby syndrome?', '["Penicillin G", "Gentamicin", "Clindamycin", "Meropenem", "Chloramphenicol"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Neonates have little glucuronyl transferase and immature renal excretion, so chloramphenicol accumulates and causes vomiting, flaccidity, hypothermia, grey colour and circulatory collapse. Gentamicin also needs neonatal dose adjustment, but its toxicity is to the ear and kidney.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.259 Q10, older CAT/exam (Section 2, extracted CAT 1 questions). No chloramphenicol lecture topic in the list; filed under paediatric clinical pharmacology as the closest fit.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-00ce0175e7', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which of the following is a luminal amoebicide?', '["Metronidazole", "Secnidazole", "Diloxanide furoate", "Dehydroemetine", "Emetine"]'::jsonb, 'Diloxanide furoate', '[]'::jsonb, 'Diloxanide furoate is hydrolysed in the gut and acts on trophozoites and cyst-passing forms within the bowel lumen, so it clears carriers. Nitroimidazoles are well absorbed and act in tissues, as do emetine and dehydroemetine, and must be followed by a luminal agent.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.259 Q11, older CAT/exam (Section 2, extracted CAT 1 questions). ''Sechidazole'' on the paper read as secnidazole.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-e3c8f23595', 'pharm-anti-leprosy-drugs', 'mcq', 'All of the following are true of dapsone EXCEPT:', '["It is a sulfone", "It is bactericidal against Mycobacterium leprae", "It is used for prevention of Pneumocystis jirovecii pneumonia in AIDS patients", "It may cause haemolysis in patients with glucose-6-phosphate dehydrogenase deficiency", "It has a shorter half-life than acedapsone"]'::jsonb, 'It is bactericidal against Mycobacterium leprae', '[]'::jsonb, 'Dapsone inhibits folate synthesis and is bacteriostatic against M. leprae; rifampicin is the bactericidal component of multidrug therapy. Acedapsone is a repository form releasing dapsone over months. Oxidative haemolysis is dose related and severe in G6PD deficiency.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.260 Q29, older CAT/exam (Section 2, extracted CAT 1 questions)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--fc727e6f3d', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is an antistaphylococcal penicillin?', '["Penicillin G", "Amoxicillin", "Cloxacillin", "Ticarcillin", "Piperacillin"]'::jsonb, 'Cloxacillin', '[]'::jsonb, 'Cloxacillin is an isoxazolyl penicillin whose bulky side chain shields the beta-lactam ring from staphylococcal penicillinase. Penicillin G and amoxicillin are destroyed by that enzyme, and ticarcillin and piperacillin are antipseudomonal penicillins.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.261 Q58, older CAT/exam (Section 2, extracted CAT 1 questions). ''Tircacillin'' on the paper corrected to ticarcillin.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-8f3d098e08', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which drug is used for both chemoprophylaxis and treatment of malaria?', '["Chloroquine", "Quinidine", "Quinine", "Sulfonamides", "Metronidazole"]'::jsonb, 'Chloroquine', '[]'::jsonb, 'Chloroquine is a blood schizonticide used both to treat and to prevent malaria caused by sensitive parasites. Quinine and quinidine are reserved for treatment because of their toxicity (cinchonism, arrhythmias), and sulfonamides are only used in combination with pyrimethamine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.264 Q1, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-0a452fd4d4', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used in the treatment of amoebiasis?', '["Nitrofurantoin", "Iodoquinol", "Pyrazinamide", "Mefloquine", "Praziquantel"]'::jsonb, 'Iodoquinol', '[]'::jsonb, 'Iodoquinol is a halogenated hydroxyquinoline that acts as a luminal amoebicide against Entamoeba histolytica trophozoites and cysts in the gut. Nitrofurantoin is a urinary antiseptic, pyrazinamide an antituberculous drug and mefloquine an antimalarial.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.264 Q2, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-9a982b8bde', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used in the treatment of trichomoniasis?', '["Metronidazole", "Suramin", "Pyrimethamine", "Tetracycline", "Chloroquine"]'::jsonb, 'Metronidazole', '[]'::jsonb, 'Metronidazole, a nitroimidazole, is reduced inside anaerobic organisms to reactive products that damage DNA; it is the drug of choice for Trichomonas vaginalis. Suramin is used for trypanosomiasis and pyrimethamine for toxoplasmosis and malaria.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.264 Q3, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-e442291d36', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which drug is used in the treatment of toxoplasmosis?', '["Chloroquine", "Tetracycline", "Suramin", "Pyrimethamine", "Metronidazole"]'::jsonb, 'Pyrimethamine', '[]'::jsonb, 'Pyrimethamine inhibits protozoal dihydrofolate reductase and, combined with sulfadiazine (plus folinic acid), is the standard treatment for toxoplasmosis. Chloroquine has no useful activity against Toxoplasma gondii, and suramin is a trypanocide.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.265 Q4, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-2f00ba778e', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used in the treatment of balantidiasis?', '["Azithromycin", "Tetracycline", "Quinine", "Trimethoprim", "Primaquine"]'::jsonb, 'Tetracycline', '[]'::jsonb, 'Tetracycline is the drug of choice for infection with the ciliate Balantidium coli; metronidazole and iodoquinol are alternatives. Quinine is an antimalarial and trimethoprim an antifolate antibacterial, neither of which is used for balantidiasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.265 Q5, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-540899a332', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used in the treatment of leishmaniasis?', '["Pyrimethamine", "Albendazole", "Sodium stibogluconate", "Tinidazole", "Mebendazole"]'::jsonb, 'Sodium stibogluconate', '[]'::jsonb, 'Sodium stibogluconate is a pentavalent antimonial and a classic first-line treatment for visceral and cutaneous leishmaniasis; amphotericin B and miltefosine are alternatives. Tinidazole treats amoebiasis, giardiasis and trichomoniasis, not leishmaniasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.265 Q6, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-4bb246990d', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug is an 8-aminoquinoline derivative?', '["Doxycycline", "Quinidine", "Primaquine", "Chloroquine", "Mefloquine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine (like tafenoquine) is an 8-aminoquinoline, used to eradicate liver hypnozoites and gametocytes. Chloroquine is a 4-aminoquinoline, quinidine is a cinchona alkaloid (quinoline methanol) and doxycycline is a tetracycline antibiotic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.265 Q7, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-fe6df2c5f7', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following antimalarial drugs are 4-substituted quinoline derivatives EXCEPT:', '["Chloroquine", "Mefloquine", "Primaquine", "Amodiaquine", "Quinine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine is an 8-aminoquinoline. Chloroquine and amodiaquine are 4-aminoquinolines, while mefloquine and quinine are 4-quinoline methanols, so all of these are substituted at position 4 of the quinoline ring.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.266 Q8, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-f930507a1e', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which antimalarial drug is a pyrimidine derivative?', '["Mefloquine", "Pyrimethamine", "Quinidine", "Chloroquine", "Primaquine"]'::jsonb, 'Pyrimethamine', '[]'::jsonb, 'Pyrimethamine is a 2,4-diaminopyrimidine that inhibits plasmodial dihydrofolate reductase, blocking folate-dependent DNA synthesis. Mefloquine, quinidine and chloroquine are all quinoline derivatives with a different mechanism (interference with haem detoxification).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.266 Q9, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-1822d4dbd5', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used in the treatment of trypanosomiasis?', '["Melarsoprol", "Metronidazole", "Tetracycline", "Quinidine", "Praziquantel"]'::jsonb, 'Melarsoprol', '[]'::jsonb, 'Melarsoprol is a trivalent arsenical that crosses the blood-brain barrier and is used for late (CNS) stage African trypanosomiasis. Metronidazole is active against anaerobic protozoa such as Entamoeba, Giardia and Trichomonas but not trypanosomes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.266 Q10, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-3d24616d84', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug has a gametocidal effect?', '["Mefloquine", "Primaquine", "Doxycycline", "Sulfonamides", "Clindamycin"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine kills the gametocytes of all human Plasmodium species, including P. falciparum, and so blocks transmission to mosquitoes; it also destroys liver hypnozoites. Mefloquine is a blood schizonticide with no useful gametocidal action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.267 Q11, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-2b0003d359', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following antimalarial drugs are clinically useful blood schizonticides EXCEPT:', '["Mefloquine", "Chloroquine", "Primaquine", "Quinidine", "Artemether"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine acts on liver stages (hypnozoites) and gametocytes; its activity against erythrocytic schizonts is too weak to be clinically useful, so it is never used alone for an acute attack. Mefloquine, chloroquine, quinidine and artemether all rapidly clear blood schizonts.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.267 Q12, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option. Stem reworded from ''influence blood schizonts'' to ''clinically useful blood schizonticides'' because primaquine has weak blood-stage activity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-7ebdb67173', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug acts on tissue (hepatic) schizonts?', '["Mefloquine", "Chloroquine", "Quinidine", "Primaquine", "Amodiaquine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine is a tissue schizonticide: it kills the liver stages, including dormant hypnozoites of P. vivax and P. ovale, giving radical cure. Chloroquine, quinidine, mefloquine and amodiaquine act only on the erythrocytic stages.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.267 Q13, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-13bb386503', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which group of antibiotics has an antimalarial effect?', '["Aminoglycosides", "Tetracyclines", "Carbapenems", "Penicillins", "Cephalosporins"]'::jsonb, 'Tetracyclines', '[]'::jsonb, 'Tetracyclines such as doxycycline are slow-acting blood schizonticides that inhibit protein synthesis in the parasite''s apicoplast; they are used with quinine for treatment and alone for prophylaxis. Beta-lactams and aminoglycosides have no antiplasmodial activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.267 Q14, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-610bea7368', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which amoebicide is used to treat the asymptomatic intestinal form of amoebiasis (cyst passers)?', '["Chloroquine", "Diloxanide", "Emetine", "Doxycycline", "Dehydroemetine"]'::jsonb, 'Diloxanide', '[]'::jsonb, 'Diloxanide furoate is a luminal amoebicide: it is poorly absorbed and kills trophozoites in the bowel lumen, which is all that is needed in asymptomatic cyst passers. Emetine and chloroquine act on tissue amoebae and do not clear luminal infection.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.268 Q15, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-b9839067d6', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which pair of drugs is used to treat the intestinal form of amoebiasis?', '["Metronidazole and diloxanide", "Diloxanide and streptomycin", "Diloxanide and iodoquinol", "Emetine and metronidazole", "Chloroquine and primaquine"]'::jsonb, 'Metronidazole and diloxanide', '[]'::jsonb, 'Symptomatic intestinal amoebiasis is treated with a tissue amoebicide (metronidazole) followed by a luminal agent (diloxanide) to eradicate cysts. Diloxanide and iodoquinol are both purely luminal agents, enough only for asymptomatic carriage.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.268 Q16, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option. The tutorial''s answer key gives ''Diloxanide and iodoquinol'' (both luminal amoebicides, taking ''intestinal form'' to mean luminal infection). Two options are defensible; needs human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-c76c962777', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drugs are used to treat the hepatic form of amoebiasis (amoebic liver abscess)?', '["Diloxanide or iodoquinol", "Tetracycline or doxycycline", "Metronidazole or emetine", "Erythromycin or azithromycin", "Paromomycin or diloxanide"]'::jsonb, 'Metronidazole or emetine', '[]'::jsonb, 'Amoebic liver abscess needs a tissue amoebicide that reaches high concentrations in the liver: metronidazole is first choice and emetine/dehydroemetine are older alternatives. Diloxanide and iodoquinol stay in the gut lumen and cannot treat hepatic disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.268 Q17, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-979936288e', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which is the drug of choice for extraluminal (tissue) amoebiasis?', '["Iodoquinol", "Metronidazole", "Diloxanide", "Tetracycline", "Paromomycin"]'::jsonb, 'Metronidazole', '[]'::jsonb, 'Metronidazole is well absorbed and kills trophozoites in the bowel wall, liver and other tissues, so it is the drug of choice for invasive amoebiasis. Iodoquinol, diloxanide and paromomycin are luminal agents given afterwards to clear cysts.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.269 Q19, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-4fc0fbb9ac', 'pharm-antihelminthics-i', 'mcq', 'What is the mechanism of action of niclosamide?', '["Increasing cell membrane permeability to calcium, causing paralysis, dislodgement and death of helminths", "Blocking acetylcholine transmission at the myoneural junction, causing paralysis of helminths", "Inhibiting microtubule synthesis in helminths with irreversible impairment of glucose uptake", "Inhibiting oxidative phosphorylation in some species of helminths", "Opening glutamate-gated chloride channels, causing hyperpolarisation and paralysis of helminths"]'::jsonb, 'Inhibiting oxidative phosphorylation in some species of helminths', '[]'::jsonb, 'Niclosamide uncouples/inhibits oxidative phosphorylation in the mitochondria of adult tapeworms, depriving them of ATP. Raising calcium permeability is how praziquantel works, and microtubule inhibition is the benzimidazole mechanism.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.269 Q21, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-a355f69f71', 'pharm-antihelminthics-i', 'mcq', 'What is the mechanism of action of praziquantel?', '["Increasing cell membrane permeability to calcium, causing paralysis, dislodgement and death of helminths", "Blocking acetylcholine transmission at the myoneural junction, causing paralysis of helminths", "Inhibiting microtubule synthesis in helminths with irreversible impairment of glucose uptake", "Inhibiting oxidative phosphorylation in some species of helminths", "Opening glutamate-gated chloride channels, causing hyperpolarisation and paralysis of helminths"]'::jsonb, 'Increasing cell membrane permeability to calcium, causing paralysis, dislodgement and death of helminths', '[]'::jsonb, 'Praziquantel increases the permeability of the worm''s tegument to calcium, producing spastic paralysis, tegumental damage and dislodgement of schistosomes and tapeworms. Flaccid paralysis by blocking the response to acetylcholine is the action of piperazine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.270 Q22, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-ab8df1b677', 'pharm-antihelminthics-i', 'mcq', 'What is the mechanism of action of piperazine?', '["Increasing cell membrane permeability to calcium, causing paralysis, dislodgement and death of helminths", "Blocking acetylcholine transmission at the myoneural junction, causing paralysis of helminths", "Inhibiting microtubule synthesis in helminths with irreversible impairment of glucose uptake", "Inhibiting oxidative phosphorylation in some species of helminths", "Opening glutamate-gated chloride channels, causing hyperpolarisation and paralysis of helminths"]'::jsonb, 'Blocking acetylcholine transmission at the myoneural junction, causing paralysis of helminths', '[]'::jsonb, 'Piperazine acts as a GABA agonist on Ascaris muscle, blocking the response to acetylcholine at the myoneural junction; the flaccidly paralysed worms are expelled alive by peristalsis. Opening glutamate-gated chloride channels is the mechanism of ivermectin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.270 Q23, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-76fa1ed4cf', 'pharm-antihelminthics-i', 'mcq', 'Which anthelmintic drug is a salicylamide derivative?', '["Praziquantel", "Piperazine", "Mebendazole", "Niclosamide", "Ivermectin"]'::jsonb, 'Niclosamide', '[]'::jsonb, 'Niclosamide is a chlorinated salicylamide used against adult tapeworms. Praziquantel is an isoquinoline-pyrazine derivative, mebendazole a benzimidazole, and ivermectin a macrocyclic lactone (avermectin). Its salicylamide structure underlies its action as an uncoupler of oxidative phosphorylation in the worm.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.271 Q24, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-df220ee46f', 'pharm-antihelminthics-i', 'mcq', 'What is the mechanism of action of mebendazole?', '["Increasing cell membrane permeability to calcium, causing paralysis, dislodgement and death of helminths", "Blocking acetylcholine transmission at the myoneural junction, causing paralysis of helminths", "Inhibiting microtubule synthesis in helminths with irreversible impairment of glucose uptake", "Inhibiting oxidative phosphorylation in some species of helminths", "Opening glutamate-gated chloride channels, causing hyperpolarisation and paralysis of helminths"]'::jsonb, 'Inhibiting microtubule synthesis in helminths with irreversible impairment of glucose uptake', '[]'::jsonb, 'Mebendazole and other benzimidazoles bind helminth beta-tubulin, preventing microtubule assembly; glucose uptake is irreversibly impaired and the worm slowly dies. Inhibition of oxidative phosphorylation is the mechanism of niclosamide.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.271 Q25, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-1d2b920f50', 'pharm-antihelminthics-i', 'mcq', 'Which drug is used in the treatment of neurocysticercosis?', '["Praziquantel", "Pyrantel", "Piperazine", "Bithionol", "Niclosamide"]'::jsonb, 'Praziquantel', '[]'::jsonb, 'Praziquantel penetrates tissues and the CNS and kills the larval cysts of Taenia solium (albendazole is the usual alternative, generally preferred). Niclosamide is not absorbed and only kills adult tapeworms in the gut, so it cannot treat cysticercosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.272 Q27, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-7901d6cac6', 'pharm-antihelminthics-i', 'mcq', 'Which drug is used to treat nematode (roundworm) infections?', '["Niclosamide", "Praziquantel", "Bithionol", "Pyrantel", "Triclabendazole"]'::jsonb, 'Pyrantel', '[]'::jsonb, 'Pyrantel pamoate is a depolarising neuromuscular blocker in nematodes, effective against Ascaris, hookworm and Enterobius. Niclosamide and praziquantel are active against cestodes and trematodes, and bithionol and triclabendazole against liver flukes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.272 Q28, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-bedaf748d4', 'pharm-antihelminthics-i', 'mcq', 'Which drug is used to treat trematode (fluke) infections?', '["Bithionol", "Ivermectin", "Pyrantel", "Metronidazole", "Niclosamide"]'::jsonb, 'Bithionol', '[]'::jsonb, 'Bithionol is an alternative drug for Fasciola hepatica (sheep liver fluke) and paragonimiasis; praziquantel and triclabendazole are the other antitrematodal drugs. Ivermectin and pyrantel act only on nematodes, and niclosamide on adult tapeworms.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.272 Q30, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-2d24c1de4f', 'pharm-antihelminthics-i', 'mcq', 'Which anthelmintic drug is a benzimidazole derivative?', '["Praziquantel", "Mebendazole", "Suramin", "Pyrantel", "Niclosamide"]'::jsonb, 'Mebendazole', '[]'::jsonb, 'Mebendazole, albendazole, thiabendazole and triclabendazole are benzimidazoles that inhibit microtubule assembly in worms. Pyrantel is a tetrahydropyrimidine, praziquantel an isoquinoline derivative and niclosamide a salicylamide. The ''-bendazole'' ending is a useful reminder of the class.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.273 Q31, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-0ceb4859a1', 'pharm-antihelminthics-i', 'mcq', 'Which broad-spectrum drug is used to treat cestode infections, trematode infections and cysticercosis?', '["Piperazine", "Ivermectin", "Praziquantel", "Pyrantel", "Diethylcarbamazine"]'::jsonb, 'Praziquantel', '[]'::jsonb, 'Praziquantel is effective against all schistosomes, most other flukes, adult tapeworms and the larval stage of Taenia solium. Piperazine, pyrantel and ivermectin act only on nematodes, and diethylcarbamazine on filarial worms.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.273 Q32, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-95bc34e064', 'pharm-antihelminthics-i', 'mcq', 'Which drug is used to treat ascariasis and enterobiasis?', '["Bithionol", "Pyrantel", "Praziquantel", "Suramin", "Niclosamide"]'::jsonb, 'Pyrantel', '[]'::jsonb, 'Pyrantel pamoate causes depolarising (spastic) paralysis of intestinal nematodes and is effective against Ascaris lumbricoides and Enterobius vermicularis; mebendazole and albendazole are alternatives. Praziquantel and bithionol act on flatworms.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.273 Q33, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-823cc31932', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which is the drug of choice for strongyloidiasis?', '["Niclosamide", "Praziquantel", "Bithionol", "Ivermectin", "Piperazine"]'::jsonb, 'Ivermectin', '[]'::jsonb, 'Ivermectin opens glutamate-gated chloride channels in nematodes, paralysing them; it is the drug of choice for Strongyloides stercoralis and for onchocerciasis. Niclosamide and praziquantel treat flatworm infections, and piperazine only ascariasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.273 Q34, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-435ce2b91b', 'pharm-antihelminthics-i', 'mcq', 'Which drugs are used in the treatment of echinococcosis (hydatid disease)?', '["Suramin", "Mebendazole or albendazole", "Piperazine", "Iodoquinol", "Pyrantel"]'::jsonb, 'Mebendazole or albendazole', '[]'::jsonb, 'Benzimidazoles, especially albendazole, are absorbed and penetrate hydatid cysts, so they are used as medical therapy and around surgery or PAIR. Piperazine and pyrantel remain in the gut and act only on intestinal nematodes.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.274 Q35, Tutorial: anti-protozoal and anti-helminthic revision quiz (MBChB 2015). added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-2a30158095', 'pharm-introduction-to-dmards', 'saq', 'Classify the disease-modifying antirheumatic drugs (DMARDs), giving examples.', '[]'::jsonb, '1. Conventional synthetic DMARDs: methotrexate, sulfasalazine, hydroxychloroquine/chloroquine, leflunomide, azathioprine, cyclosporine, cyclophosphamide, mycophenolate, gold, penicillamine. 2. Biologic DMARDs: TNF-alpha inhibitors (infliximab, adalimumab, etanercept, golimumab, certolizumab); IL-6 receptor blocker (tocilizumab); IL-1 antagonist (anakinra); T-cell co-stimulation blocker (abatacept); anti-CD20 B-cell depleter (rituximab). 3. Targeted synthetic DMARDs: JAK inhibitors (tofacitinib, baricitinib).', '[]'::jsonb, 'DMARDs are grouped by how they are made and what they target: older small-molecule (conventional synthetic) agents, protein biologics aimed at cytokines or lymphocytes, and newer oral targeted synthetic agents such as JAK inhibitors. All slow joint damage, unlike NSAIDs which only relieve symptoms.', 'admin', 'published', 4, true, '[["conventional", "synthetic", "non-biologic", "csdmard"], ["methotrexate", "sulfasalazine", "hydroxychloroquine", "leflunomide"], ["biologic", "biological"], ["tnf", "infliximab", "etanercept", "adalimumab"], ["rituximab", "abatacept", "tocilizumab", "anakinra"], ["jak", "tofacitinib", "targeted synthetic"]]'::jsonb, 'mcq p.276 Q1, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-73f88829fe', 'pharm-biologic-dmards', 'saq', 'Describe the mechanism of action of abatacept.', '[]'::jsonb, 'Fusion protein of CTLA-4 and the Fc portion of IgG1; binds CD80/CD86 on antigen-presenting cells, preventing their interaction with CD28 on T cells; blocks the co-stimulatory signal so T cells are not activated.', '[]'::jsonb, 'T cells need two signals to be activated: antigen on MHC and a co-stimulatory signal from CD80/86 binding CD28. Abatacept contains CTLA-4, which binds CD80/86 with higher affinity than CD28, so the second signal is blocked and T-cell activation fails.', 'admin', 'published', 2, true, '[["ctla-4", "ctla4", "fusion protein"], ["cd80", "cd86", "b7"], ["cd28", "co-stimulation", "costimulation", "t cell activation"]]'::jsonb, 'mcq p.276 Q2 i, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-0f83f8cb18', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'Describe the mechanism of action of azathioprine.', '[]'::jsonb, 'Prodrug converted to 6-mercaptopurine and then to 6-thioguanine nucleotides (6-thioinosinic acid); these inhibit de novo purine synthesis and are incorporated into DNA; suppresses proliferation of T and B lymphocytes.', '[]'::jsonb, 'Azathioprine is cleaved to 6-mercaptopurine, whose thioguanine nucleotide metabolites block de novo purine synthesis and are incorporated as false bases into DNA. Lymphocytes depend heavily on the de novo pathway, so their proliferation is selectively suppressed.', 'admin', 'published', 2, true, '[["6-mercaptopurine", "mercaptopurine", "6-mp", "prodrug"], ["purine synthesis", "purine", "thioguanine", "6-thioguanine"], ["lymphocyte", "t and b cells", "dna synthesis", "proliferation"]]'::jsonb, 'mcq p.276 Q2 ii, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-b37f9a925c', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'saq', 'Describe the mechanism of action of chloroquine/hydroxychloroquine as DMARDs.', '[]'::jsonb, 'Weak bases that accumulate in lysosomes and raise their pH: stabilise lysosomal membranes/enzymes and impair antigen processing and presentation; suppress T-lymphocyte responses to mitogens; inhibit leucocyte chemotaxis; inhibit Toll-like receptor signalling; inhibit DNA and RNA synthesis; trap free radicals.', '[]'::jsonb, 'The antimalarials concentrate in acidic lysosomes of antigen-presenting cells, where raising the pH interferes with antigen processing and Toll-like receptor signalling. They also dampen T-cell responses and leucocyte chemotaxis, giving a slow, mild disease-modifying effect.', 'admin', 'published', 2, true, '[["lysosome", "lysosomal", "raise ph"], ["antigen processing", "antigen presentation", "toll-like", "tlr"], ["t lymphocyte", "t cell", "mitogens"], ["chemotaxis"], ["dna and rna", "free radicals"]]'::jsonb, 'mcq p.276 Q2 iii, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-09ebe787dc', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'Describe the mechanism of action of cyclophosphamide.', '[]'::jsonb, 'Prodrug activated by hepatic cytochrome P450 to phosphoramide mustard (and acrolein); alkylating agent that cross-links DNA (at guanine N7), preventing cell replication; suppresses T- and B-lymphocyte function.', '[]'::jsonb, 'Cyclophosphamide is inactive until hepatic CYP enzymes convert it to phosphoramide mustard, which alkylates and cross-links DNA strands. Rapidly dividing lymphocytes are particularly affected, which explains its immunosuppressive use; acrolein, the other metabolite, causes haemorrhagic cystitis.', 'admin', 'published', 2, true, '[["prodrug", "cytochrome p450", "liver activation", "phosphoramide mustard"], ["alkylating", "alkylation", "cross-links dna", "cross-linking"], ["lymphocyte", "t and b cells", "cell replication"]]'::jsonb, 'mcq p.276 Q2 iv, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-08edd40cb1', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'Describe the mechanism of action of leflunomide.', '[]'::jsonb, 'Prodrug converted to the active metabolite teriflunomide (A77-1726); inhibits dihydroorotate dehydrogenase, blocking de novo pyrimidine synthesis; activated lymphocytes arrest in G1, so T-cell proliferation and B-cell autoantibody production fall.', '[]'::jsonb, 'Leflunomide''s active metabolite inhibits dihydroorotate dehydrogenase, a mitochondrial enzyme needed for de novo pyrimidine (UMP) synthesis. Activated lymphocytes cannot use salvage pathways sufficiently, so they arrest in G1 and the autoimmune response is damped.', 'admin', 'published', 2, true, '[["teriflunomide", "a77-1726", "active metabolite", "prodrug"], ["dihydroorotate dehydrogenase", "dhodh"], ["pyrimidine", "pyrimidine synthesis"], ["lymphocyte", "t cell", "g1 arrest"]]'::jsonb, 'mcq p.276 Q2 v, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-b58e58ebbd', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'Describe the adverse effects of azathioprine.', '[]'::jsonb, 'Bone marrow suppression (leucopenia, thrombocytopenia, anaemia), worse with TPMT deficiency or with allopurinol; gastrointestinal upset (nausea, vomiting, diarrhoea); hepatotoxicity; increased risk of infections; increased risk of malignancy (lymphoma, skin cancer); pancreatitis; hypersensitivity (fever, rash); alopecia.', '[]'::jsonb, 'Because azathioprine blocks purine synthesis in dividing cells, its main toxicity is dose-related bone marrow suppression, with gut and liver toxicity. Patients with low thiopurine methyltransferase activity, or taking allopurinol (xanthine oxidase inhibition), accumulate active metabolites and are at particular risk.', 'admin', 'published', 4, true, '[["bone marrow suppression", "myelosuppression", "leucopenia", "leukopenia"], ["nausea", "vomiting", "gi upset", "gastrointestinal"], ["hepatotoxicity", "liver toxicity", "hepatitis"], ["infection", "infections"], ["malignancy", "lymphoma", "cancer"], ["pancreatitis"], ["rash", "fever", "hypersensitivity"]]'::jsonb, 'mcq p.276 Q3, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-4b2e2e0494', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'saq', 'Differentiate between the mechanisms of action of methotrexate when used for rheumatoid arthritis and when used for cancer treatment.', '[]'::jsonb, 'Rheumatoid arthritis (low weekly dose): inhibits AICAR transformylase and thymidylate synthetase; AICAR accumulates and inhibits AMP deaminase, so adenosine accumulates extracellularly; adenosine is anti-inflammatory (suppresses neutrophils, macrophages, lymphocytes). Cancer (high dose): inhibits dihydrofolate reductase, depleting tetrahydrofolate; blocks thymidylate and purine synthesis, so DNA synthesis stops (S-phase specific cytotoxicity).', '[]'::jsonb, 'At the low weekly doses used in rheumatoid arthritis, methotrexate polyglutamates inhibit AICAR transformylase, raising extracellular adenosine, a potent anti-inflammatory mediator. At the much higher doses used in cancer, inhibition of dihydrofolate reductase starves dividing cells of the folate cofactors needed for DNA synthesis.', 'admin', 'published', 4, true, '[["aicar", "aicar transformylase", "aminoimidazolecarboxamide"], ["adenosine"], ["dihydrofolate reductase", "dhfr"], ["dna synthesis", "thymidylate", "purine synthesis", "tetrahydrofolate"], ["low dose", "high dose", "s phase"]]'::jsonb, 'mcq p.276 Q4, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-41805d611c', 'pharm-biologic-dmards', 'saq', 'Classify the TNF-alpha blocking agents, with examples.', '[]'::jsonb, '1. Monoclonal antibodies: chimeric (infliximab); fully human (adalimumab, golimumab). 2. Pegylated humanised Fab fragment: certolizumab pegol. 3. Soluble receptor fusion protein (TNF receptor p75 linked to IgG1 Fc): etanercept.', '[]'::jsonb, 'TNF blockers are either antibodies directed against TNF-alpha (chimeric infliximab, human adalimumab and golimumab, or the pegylated Fab fragment certolizumab) or a decoy receptor (etanercept, the p75 TNF receptor fused to Fc). All increase the risk of infections, especially reactivation of tuberculosis.', 'admin', 'published', 3, true, '[["monoclonal antibodies", "monoclonal antibody", "infliximab"], ["adalimumab", "golimumab", "human"], ["certolizumab", "fab fragment", "pegylated"], ["etanercept", "fusion protein", "soluble receptor"]]'::jsonb, 'mcq p.276 Q5, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-ae9cdf18d9', 'pharm-introduction-to-dmards', 'mcq', 'Which one of the following is NOT a prodrug?', '["Sulfasalazine", "Mycophenolate mofetil", "Methotrexate", "Leflunomide", "Azathioprine"]'::jsonb, 'Methotrexate', '[]'::jsonb, 'Methotrexate is active as given. Sulfasalazine is split by colonic bacteria into sulfapyridine and 5-aminosalicylic acid, mycophenolate mofetil is hydrolysed to mycophenolic acid, leflunomide is converted to teriflunomide, and azathioprine to 6-mercaptopurine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.276 MCQ 1, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-63edab76de', 'pharm-biologic-dmards', 'mcq', 'Which of the following biologic DMARDs is the odd one out?', '["Rituximab", "Certolizumab", "Infliximab", "Etanercept", "Golimumab"]'::jsonb, 'Rituximab', '[]'::jsonb, 'Rituximab is a chimeric monoclonal antibody against CD20 that depletes B lymphocytes, reducing antigen presentation and autoantibody production. Certolizumab, infliximab, etanercept and golimumab all work by neutralising TNF-alpha, so they form one class and share risks such as reactivation of tuberculosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.277 MCQ 2, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-37e02dad99', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which statement is NOT true about methotrexate?', '["It is a first-line DMARD for rheumatoid arthritis", "It can be given orally", "It is contraindicated in pregnancy", "Leucovorin or folic acid minimises its adverse effects", "Hydroxychloroquine increases its clearance by reducing its tubular reabsorption"]'::jsonb, 'Hydroxychloroquine increases its clearance by reducing its tubular reabsorption', '[]'::jsonb, 'Hydroxychloroquine does the opposite: it can reduce the clearance, or increase the tubular reabsorption, of methotrexate. Methotrexate is the oral, once-weekly first-choice DMARD; it is teratogenic, and folic or folinic acid reduces its mucosal, marrow and hepatic toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.277 MCQ 3, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-8a7346a310', 'pharm-biologic-dmards', 'mcq', 'Identify the FALSE statement.', '["Cyclosporine inhibits IL-1 and IL-2 receptor production", "Abatacept cannot be given orally", "Tocilizumab is a TNF-alpha blocking agent", "Rituximab targets CD20 B lymphocytes and decreases antigen presentation to T lymphocytes", "When sulfasalazine is used to treat inflammatory bowel disease, aminosalicylic acid is the active moiety"]'::jsonb, 'Tocilizumab is a TNF-alpha blocking agent', '[]'::jsonb, 'Tocilizumab is a humanised antibody against the interleukin-6 receptor, not a TNF blocker. Abatacept is a protein given by infusion or injection, and in inflammatory bowel disease the 5-aminosalicylic acid released from sulfasalazine acts locally, whereas sulfapyridine matters in rheumatoid arthritis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.277 MCQ 4, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-9c2d7d2c8f', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which statement is NOT true about chloroquine/hydroxychloroquine?', '["They suppress T-lymphocyte responses to mitogens", "They inhibit leucocyte chemotaxis", "They stabilise lysosomal enzymes", "They inhibit DNA and RNA synthesis", "They are acetylated in the liver"]'::jsonb, 'They are acetylated in the liver', '[]'::jsonb, 'The antimalarials are metabolised in the liver by deamination/N-dealkylation (cytochrome P450), not acetylation; acetylation is the route for drugs such as isoniazid, sulfonamides and hydralazine. The other four statements are the proposed anti-rheumatic actions described in Katzung.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.278 MCQ 5, Tutorial: DMARDs group discussion revision questions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-bcd358a7c2', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Narcotic analgesics should:', '["Relieve severe pain", "Induce loss of sensation", "Reduce anxiety and exert a calming effect", "Induce a stupor or somnolent state", "Reduce fever and inflammation"]'::jsonb, 'Relieve severe pain', '[]'::jsonb, 'The defining therapeutic property of narcotic (opioid) analgesics is relief of moderate to severe pain without loss of consciousness or of other sensations. Loss of all sensation describes anaesthetics, and calming without analgesia describes anxiolytic-sedatives.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.280 Q1, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-8b829a52e2', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Chemical mediators in the nociceptive (pain-transmitting) pathway include all of the following EXCEPT:', '["Enkephalins", "Kinins", "Prostaglandins", "Substance P", "Glutamate"]'::jsonb, 'Enkephalins', '[]'::jsonb, 'Enkephalins are endogenous opioid peptides that inhibit pain transmission, so they belong to the antinociceptive system. Bradykinin and prostaglandins activate or sensitise nociceptors peripherally, and substance P and glutamate are transmitters released by nociceptive afferents in the dorsal horn.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.280 Q2, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-3f5a71943d', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which statement is NOT true about pentazocine?', '["It has a ceiling effect", "It is a mild to moderate acting benzomorphan", "High doses produce euphoria via kappa receptors", "It exhibits psychotomimetic effects", "It does not antagonise the respiratory depression caused by morphine"]'::jsonb, 'High doses produce euphoria via kappa receptors', '[]'::jsonb, 'Pentazocine is a benzomorphan kappa agonist and weak mu antagonist/partial agonist. Kappa activation at high doses causes dysphoria, hallucinations and nightmares, not euphoria. Despite its weak mu antagonism it does not reverse morphine''s respiratory depression, though it can precipitate withdrawal.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.281 Q5, Tutorial: narcotic analgesics revision. Answer worked out from Lippincott''s description of pentazocine; no key on the scan. Statement B wording (''mild to moderate acting'') is loose.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-00175210a6', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Identify the opioid that has been wrongly classified.', '["Propoxyphene - phenylpiperidine", "Butorphanol - phenylheptylamine", "Meperidine - phenanthrene", "Tapentadol - morphinan", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Every pairing is wrong. Propoxyphene (like methadone) is a phenylheptylamine, butorphanol is a morphinan, meperidine (pethidine) is a phenylpiperidine like fentanyl, and tapentadol is a miscellaneous agent related to tramadol. Phenanthrenes are morphine, codeine and their semisynthetic derivatives.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.281 Q6, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-9522a0cdbc', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Mu opioid receptors are associated with:', '["Analgesia, euphoria, respiratory depression, physical dependence", "Spinal analgesia, mydriasis, sedation, physical dependence", "Dysphoria, hallucinations, respiratory and vasomotor stimulation", "Analgesia, euphoria, respiratory stimulation, physical dependence", "Diuresis, mydriasis, convulsions, hyperthermia"]'::jsonb, 'Analgesia, euphoria, respiratory depression, physical dependence', '[]'::jsonb, 'Mu receptors mediate most of morphine''s effects: supraspinal and spinal analgesia, euphoria, respiratory depression, miosis, constipation and physical dependence. Opioids depress rather than stimulate respiration and cause miosis, not mydriasis; dysphoria and hallucinations are kappa (and sigma) effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.281 Q7, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-0e7ac6e6bb', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which opioid receptor type is responsible for euphoria and respiratory depression?', '["Kappa receptors", "Delta receptors", "Mu receptors", "All of the above", "Nociceptin (ORL-1) receptors"]'::jsonb, 'Mu receptors', '[]'::jsonb, 'Euphoria, respiratory depression and physical dependence are chiefly mu-receptor effects, which is why mu agonists such as morphine and heroin are abused and are dangerous in overdose. Kappa agonists produce dysphoria rather than euphoria and little respiratory depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.281 Q8, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-dc62323cde', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which opioid receptor type is responsible for dysphoria and psychotomimetic effects?', '["Kappa receptors", "Delta receptors", "Mu receptors", "All of the above", "Nociceptin (ORL-1) receptors"]'::jsonb, 'Kappa receptors', '[]'::jsonb, 'Kappa-receptor activation produces spinal analgesia and sedation but also dysphoria, hallucinations and other psychotomimetic effects, as seen with pentazocine. Mu receptors mediate euphoria instead, which is the opposite mood change.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.282 Q9, Tutorial: narcotic analgesics revision. added a fifth option. Paper says ''dysphoria and vasomotor stimulation''; classically vasomotor stimulation was attributed to the sigma receptor, so the stem was reworded to ''dysphoria and psychotomimetic effects''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-785c0e3247', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Opioid agonists acting on kappa and delta receptors:', '["Inhibit postsynaptic neurons by opening K+ channels", "Close voltage-gated Ca2+ channels on presynaptic nerve terminals", "Inhibit arachidonate cyclooxygenase in the CNS", "Both open K+ channels postsynaptically and close presynaptic voltage-gated Ca2+ channels", "Stimulate adenylyl cyclase and raise cAMP"]'::jsonb, 'Both open K+ channels postsynaptically and close presynaptic voltage-gated Ca2+ channels', '[]'::jsonb, 'All opioid receptors are Gi/Go-coupled: they inhibit adenylyl cyclase, open potassium channels to hyperpolarise postsynaptic neurons, and close presynaptic voltage-gated calcium channels to reduce transmitter release. Cyclooxygenase inhibition is the mechanism of NSAIDs, not opioids.', 'admin', 'draft', 1, false, '[]'::jsonb, 'mcq p.282 Q10, Tutorial: narcotic analgesics revision. added a fifth option. Option d (''Both a and b'') written out in full. No key on the scan; older texts attributed K+ channel opening to mu/delta and Ca2+ channel closure to kappa, so the intended answer is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-77355df67b', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which of the following actions is NOT associated with strong opioid agonists?', '["Decreased gastrointestinal motility and increased smooth muscle tone", "Increase in CSF pressure, raising intracranial pressure", "Depression of the cough reflex", "Mydriasis", "Emesis"]'::jsonb, 'Mydriasis', '[]'::jsonb, 'Opioids stimulate the Edinger-Westphal nucleus, producing miosis (pinpoint pupils in overdose), not mydriasis. They do cause constipation, cough suppression, vomiting via the chemoreceptor trigger zone, and a rise in intracranial pressure secondary to CO2 retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.282 Q11, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-c798eeffed', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which statement is NOT true about meperidine (pethidine)?', '["It is a strong opioid receptor agonist", "It is classified as a phenylpiperidine", "It leads to a decrease in LH, FSH, ACTH and prolactin secretion", "It provokes release of histamine", "It can cross the placenta during pregnancy"]'::jsonb, 'It leads to a decrease in LH, FSH, ACTH and prolactin secretion', '[]'::jsonb, 'Opioids inhibit release of GnRH and CRH, lowering LH, FSH and ACTH, but they increase prolactin (and growth hormone) secretion, so the statement is wrong for prolactin. Pethidine is a phenylpiperidine full agonist that crosses the placenta and can depress the newborn.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.282 Q12, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-d9c5965a2a', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which of the following analgesics is a phenanthrene derivative?', '["Fentanyl", "Morphine", "Methadone", "Pentazocine", "Meperidine"]'::jsonb, 'Morphine', '[]'::jsonb, 'Morphine, codeine and their semisynthetic derivatives are phenanthrenes. Fentanyl and meperidine are phenylpiperidines, methadone is a phenylheptylamine and pentazocine is a benzomorphan. Chemical class matters clinically: allergy to one phenanthrene makes cross-reaction with another more likely than with a phenylpiperidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.283 Q13, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-a03e4f6fff', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which narcotic analgesic is a phenylpiperidine derivative?', '["Codeine", "Dezocine", "Fentanyl", "Buprenorphine", "Methadone"]'::jsonb, 'Fentanyl', '[]'::jsonb, 'Fentanyl and its congeners (alfentanil, sufentanil, remifentanil) and meperidine are phenylpiperidines. Codeine and buprenorphine are phenanthrenes, and methadone is a phenylheptylamine. Dezocine is an aminotetralin. Phenylpiperidines are fully synthetic and include the most potent opioids in use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.283 Q14, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-dba13f8a26', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which of the following opioids is a strong mu receptor agonist?', '["Naloxone", "Morphine", "Pentazocine", "Buprenorphine", "Nalbuphine"]'::jsonb, 'Morphine', '[]'::jsonb, 'Morphine is the prototype full (strong) mu agonist. Naloxone is a pure antagonist, buprenorphine a partial mu agonist with a ceiling effect, and pentazocine and nalbuphine are kappa agonists with weak mu antagonist activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.283 Q15, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-f4ae7c5756', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which narcotic analgesic is a natural (opium-derived) agonist?', '["Meperidine", "Fentanyl", "Morphine", "Naloxone", "Methadone"]'::jsonb, 'Morphine', '[]'::jsonb, 'Morphine and codeine are natural alkaloids obtained from the opium poppy, Papaver somniferum. Meperidine, fentanyl and methadone are fully synthetic agonists, and naloxone is a semisynthetic antagonist. Heroin is semisynthetic, made by acetylating morphine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.283 Q16, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-76a6d7bc1f', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which narcotic analgesic is an antagonist or partial agonist at the mu receptor?', '["Fentanyl", "Pentazocine", "Codeine", "Methadone", "Morphine"]'::jsonb, 'Pentazocine', '[]'::jsonb, 'Pentazocine is a mixed agonist-antagonist: an agonist at kappa receptors and a weak antagonist or partial agonist at mu receptors, so it can precipitate withdrawal in opioid-dependent patients. Fentanyl, codeine, methadone and morphine are all mu agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.284 Q17, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-dd87527dae', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'The principal central nervous system effect of opioid analgesics with affinity for the mu receptor is:', '["Analgesia", "Respiratory depression", "Euphoria", "All of the above", "Mydriasis"]'::jsonb, 'All of the above', '[]'::jsonb, 'Mu-receptor activation in the CNS produces analgesia, euphoria, sedation and dose-dependent respiratory depression (reduced brainstem sensitivity to CO2). The pupillary effect is miosis, never mydriasis, so analgesia alone is an incomplete answer.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.284 Q19, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-ee53880224', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following opioid analgesics can produce dysphoria, anxiety and hallucinations?', '["Morphine", "Fentanyl", "Pentazocine", "Methadone", "Codeine"]'::jsonb, 'Pentazocine', '[]'::jsonb, 'Pentazocine''s kappa agonism (and sigma activity) causes psychotomimetic effects: dysphoria, anxiety, nightmares and hallucinations, especially at higher doses. Pure mu agonists such as morphine, fentanyl, methadone and codeine typically produce euphoria and sedation instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.284 Q20, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-43d0ac86fa', 'pharm-opioid-use-and-abuse', 'mcq', 'A heroin addict has entered a rehabilitation programme that requires her to take methadone. Methadone is effective in this situation because it:', '["Is an antagonist at the morphine receptors", "Has less potent analgesic activity than heroin", "Is longer acting than heroin, so the withdrawal is milder than with heroin", "Does not cause constipation", "Is non-addictive"]'::jsonb, 'Is longer acting than heroin, so the withdrawal is milder than with heroin', '[]'::jsonb, 'Methadone is an orally active full mu agonist with a long half-life. It substitutes for heroin, prevents craving, and its own withdrawal syndrome is more protracted but much milder. It is still addictive and constipating, and it is an agonist, not an antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.285 Q22, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-292715a4c4', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which of the following statements about morphine is correct?', '["It is used therapeutically to relieve pain caused by severe head injury", "Its withdrawal symptoms can be relieved by naloxone", "It causes diarrhoea", "It is most effective by oral administration", "It rapidly enters all body tissues, including the fetus"]'::jsonb, 'It rapidly enters all body tissues, including the fetus', '[]'::jsonb, 'Morphine distributes to all tissues and crosses the placenta, so babies of dependent mothers may show withdrawal. It is avoided in head injury (raises intracranial pressure), causes constipation, has low oral bioavailability from first-pass metabolism, and naloxone precipitates rather than relieves withdrawal.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.285 Q23, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-836c73c803', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Most strong mu receptor agonists cause:', '["Hypertension", "An increase in pulmonary arterial pressure and myocardial work", "Cerebral vasodilatation, causing an increase in intracranial pressure", "All of the above", "Mydriasis and tachycardia"]'::jsonb, 'Cerebral vasodilatation, causing an increase in intracranial pressure', '[]'::jsonb, 'Respiratory depression from mu agonists raises arterial PCO2, which dilates cerebral vessels and increases intracranial pressure, hence caution in head injury. They tend to lower blood pressure (histamine release, vasodilatation); raised pulmonary arterial pressure and cardiac work is peculiar to pentazocine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.286 Q24, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-19de5e69f4', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following opioid analgesics can increase pulmonary arterial pressure and myocardial work?', '["Morphine", "Pentazocine", "Meperidine", "Methadone", "Fentanyl"]'::jsonb, 'Pentazocine', '[]'::jsonb, 'Pentazocine (like butorphanol) raises systemic and pulmonary arterial pressure and so increases cardiac work, which makes it unsuitable in myocardial infarction. Morphine does the reverse, reducing preload and myocardial oxygen demand, which is why it is used in acute infarction.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.286 Q25, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-15816e89b1', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Morphine causes all of the following effects EXCEPT:', '["Constipation", "Dilatation (relaxation) of the biliary tract and sphincter of Oddi", "Urinary retention", "Bronchiolar constriction", "Miosis"]'::jsonb, 'Dilatation (relaxation) of the biliary tract and sphincter of Oddi', '[]'::jsonb, 'Morphine contracts biliary smooth muscle and the sphincter of Oddi, raising intrabiliary pressure and potentially worsening biliary colic. It also causes constipation, urinary retention (increased sphincter tone), miosis, and bronchoconstriction through histamine release.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.286 Q26, Tutorial: narcotic analgesics revision. added a fifth option. Option b clarified from ''Dilatation of the biliary duct'' to make clear that relaxation of biliary smooth muscle is meant.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-b975df48aa', 'pharm-acute-opioid-toxicity', 'mcq', 'A young man is brought into the emergency room unconscious, with pupillary constriction and depressed respiration. You note needle marks on his legs. You administer naltrexone, and he awakens. This agent was effective because:', '["The patient was suffering from an overdose of a benzodiazepine", "Naltrexone antagonises opiates at the receptor site", "Naltrexone is a stimulant of the CNS", "Naltrexone binds to the opioid and inactivates it", "The man was suffering from an overdose of meperidine"]'::jsonb, 'Naltrexone antagonises opiates at the receptor site', '[]'::jsonb, 'Coma, pinpoint pupils and respiratory depression are the triad of opioid overdose. Naltrexone, like naloxone, is a competitive antagonist that displaces the opioid from mu receptors; it does not bind the drug itself. Meperidine overdose causes mydriasis and excitation, not miosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.286 Q27, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-eb9641d5d9', 'pharm-acute-opioid-toxicity', 'mcq', 'Which of the following opioid agents is used in the treatment of acute opioid overdose?', '["Pentazocine", "Methadone", "Naloxone", "Remifentanil", "Flumazenil"]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone is a pure competitive antagonist at mu, kappa and delta receptors; given intravenously it reverses coma and respiratory depression within minutes, but its short half-life means repeat doses are often needed. Flumazenil reverses benzodiazepines, not opioids.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.287 Q29, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-24dac4ae5b', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which pure opioid antagonist is effective orally and has a long duration of action, making it suitable for maintenance treatment of opioid and alcohol dependence?', '["Naloxone", "Naltrexone", "Tramadol", "Pentazocine", "Buprenorphine"]'::jsonb, 'Naltrexone', '[]'::jsonb, 'Naltrexone is well absorbed orally and, with its active metabolite, blocks opioid receptors for 24 hours or more, so it is used to prevent relapse in detoxified patients. Naloxone is a pure antagonist too, but is short acting and ineffective by mouth.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.287 Q30, Tutorial: narcotic analgesics revision. added a fifth option. Reworded: the paper asked for ''the pure opioid antagonist which has a half-life of 13 hours'' (texts quote about 4 h for naltrexone, 13 h for its metabolite, 10 h in Katzung).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-06bc6cd2ba', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'In contrast to morphine, methadone:', '["Causes tolerance and physical dependence more slowly", "Is more effective orally", "Has a withdrawal syndrome that is less severe, although more prolonged", "All of the above", "Has a much shorter duration of action"]'::jsonb, 'All of the above', '[]'::jsonb, 'Methadone has high oral bioavailability and a long half-life; tolerance and dependence develop more slowly, and its withdrawal syndrome is milder but lasts longer. These properties underlie its use in opioid substitution therapy. Its duration of action is longer, not shorter, than morphine''s.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.287 Q31, Tutorial: narcotic analgesics revision. added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-bc37830679', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following opioid analgesics is a partial mu receptor agonist?', '["Morphine", "Methadone", "Buprenorphine", "Sufentanil", "Naltrexone"]'::jsonb, 'Buprenorphine', '[]'::jsonb, 'Buprenorphine binds mu receptors with very high affinity but low intrinsic activity, giving a ceiling on respiratory depression and the ability to precipitate withdrawal in dependent patients. Morphine, methadone and sufentanil are full agonists; naltrexone is a pure antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.288 Q32, Tutorial: narcotic analgesics revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-6b1a198982', 'pharm-acute-opioid-toxicity', 'mcq', 'The main cause of death from an opioid overdose is:', '["Respiratory depression", "Seizures", "Constipation", "Hypertensive crisis", "Hypoglycaemia"]'::jsonb, 'Respiratory depression', '[]'::jsonb, 'Opioids reduce the sensitivity of brainstem respiratory centres to carbon dioxide, and in overdose breathing slows and stops; death is from respiratory arrest. Seizures are uncommon (seen with pethidine or tramadol) and opioids lower rather than raise blood pressure.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.290 Q8.1, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-2c8b7785dc', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All of the following are endogenous opioid peptides EXCEPT:', '["Met-enkephalin", "Leu-enkephalin", "Beta-endorphin", "Dynorphin A and B", "Phencyclidine"]'::jsonb, 'Phencyclidine', '[]'::jsonb, 'Phencyclidine is a synthetic dissociative drug of abuse that blocks NMDA receptor channels. The enkephalins, beta-endorphin and the dynorphins are the three families of endogenous opioid peptides, derived from proenkephalin, pro-opiomelanocortin and prodynorphin respectively.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.290 Q8.2, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-a7f41439c6', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'All of the following are naturally occurring opium alkaloids EXCEPT:', '["Morphine", "Codeine", "Meperidine", "Papaverine", "Narcotine (noscapine)"]'::jsonb, 'Meperidine', '[]'::jsonb, 'Meperidine (pethidine) is a fully synthetic phenylpiperidine. Opium contains phenanthrene alkaloids (morphine, codeine, thebaine) and benzylisoquinoline alkaloids (papaverine, noscapine), which lack analgesic activity. Papaverine is a smooth muscle relaxant and noscapine an antitussive.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.290 Q8.3, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-8693d1cb6b', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Effects of morphine on the CNS include all of the following EXCEPT:', '["Analgesia", "Miosis", "Respiratory depression", "Inhibition of ADH release", "Depression of the cough reflex"]'::jsonb, 'Inhibition of ADH release', '[]'::jsonb, 'Morphine (a mu agonist) stimulates rather than inhibits release of antidiuretic hormone, contributing to its antidiuretic effect and urinary retention. Analgesia, miosis, respiratory depression and cough suppression are all classic central actions.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.290 Q8.4, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-b9003b391c', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Effects of morphine on the gastrointestinal tract include all of the following EXCEPT:', '["Decreased biliary, pancreatic and intestinal secretions", "Decreased gastric motility", "Increased tone of the small intestine", "Increased propulsive peristaltic waves in the colon", "Increased intrabiliary pressure"]'::jsonb, 'Increased propulsive peristaltic waves in the colon', '[]'::jsonb, 'Morphine increases resting tone and non-propulsive segmenting contractions but markedly reduces propulsive peristalsis in the small bowel and colon, which, with reduced secretions and delayed gastric emptying, causes constipation. Spasm of the sphincter of Oddi raises biliary pressure.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.291 Q8.5, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-ef676c8e85', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Morphine causes:', '["Diarrhoea", "Vasoconstriction", "Bronchodilatation", "Decrease in intracranial pressure", "Reduced sensitivity of the respiratory centre to CO2"]'::jsonb, 'Reduced sensitivity of the respiratory centre to CO2', '[]'::jsonb, 'Morphine depresses the response of the brainstem respiratory centre to carbon dioxide, the basis of opioid respiratory depression. The retained CO2 dilates cerebral vessels and raises intracranial pressure; morphine also causes constipation, vasodilatation and bronchoconstriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.291 Q8.6, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-beeb316057', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Morphine produces all of the following actions EXCEPT:', '["Stimulation of the chemoreceptor trigger zone", "Stimulation of the Edinger-Westphal nucleus in the midbrain", "Cycloplegia", "Spasm of the sphincter of Oddi", "Histamine release"]'::jsonb, 'Cycloplegia', '[]'::jsonb, 'Cycloplegia (paralysis of accommodation) is produced by antimuscarinic drugs such as atropine. Morphine stimulates the parasympathetic Edinger-Westphal nucleus, causing miosis, and also causes vomiting via the chemoreceptor trigger zone, biliary spasm and histamine release.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.291 Q8.7, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-527ad9c71b', 'pharm-opioid-use-and-abuse', 'mcq', 'Which of the following will prevent the abstinence syndrome in a heavy heroin user?', '["Phenytoin", "Methadone", "Naloxone", "Diazepam", "Carbamazepine"]'::jsonb, 'Methadone', '[]'::jsonb, 'Methadone is a long-acting, orally effective mu agonist showing cross-tolerance with heroin, so it suppresses withdrawal and craving. Naloxone, an antagonist, would precipitate a severe abstinence syndrome, and diazepam only eases some symptoms without replacing the opioid.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.291 Q8.8, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-2d452e3524', 'pharm-opioid-use-and-abuse', 'mcq', 'Tolerance develops to all of the following morphine effects EXCEPT:', '["Miosis", "Analgesia", "Euphoria", "Respiratory depression", "Sedation"]'::jsonb, 'Miosis', '[]'::jsonb, 'Little or no tolerance develops to miosis and constipation (and convulsions), so pinpoint pupils remain a useful sign even in chronic users. Marked tolerance develops to analgesia, euphoria, sedation and respiratory depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.291 Q8.9, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-048b3982fc', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following is a pure opioid antagonist?', '["Methadone", "Nalbuphine", "Naloxone", "Buprenorphine", "Pentazocine"]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone blocks mu, kappa and delta receptors with no agonist activity. Nalbuphine and pentazocine are mixed agonist-antagonists (kappa agonists, mu antagonists), buprenorphine is a partial mu agonist, and methadone is a full agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.292 Q8.10, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-4ce7730953', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Clinical uses of morphine include all of the following EXCEPT:', '["Relief of pain from myocardial infarction", "Relief of cancer pain", "Relief of dyspnoea of acute left ventricular failure", "Treatment of acute bronchial asthma", "Preanaesthetic medication"]'::jsonb, 'Treatment of acute bronchial asthma', '[]'::jsonb, 'Morphine is contraindicated in acute asthma: it depresses respiration, suppresses cough and releases histamine, causing bronchoconstriction. It is valuable for severe pain, and in acute left ventricular failure it relieves dyspnoea by reducing anxiety and cardiac preload.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.292 Q8.11, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-51e2338a59', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'The use of morphine is contraindicated in:', '["Head injuries", "Bronchial asthma", "Myxoedema", "Biliary colic", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Morphine raises intracranial pressure and masks pupillary signs in head injury, causes bronchoconstriction and respiratory depression in asthma, has exaggerated and prolonged effects in myxoedema, and worsens biliary colic by contracting the sphincter of Oddi.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.292 Q8.12, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-91badeb915', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Adverse effects of morphine include all of the following EXCEPT:', '["Physical and psychological dependence", "Constipation", "Respiratory depression", "Bronchoconstriction", "Hyperthermia"]'::jsonb, 'Hyperthermia', '[]'::jsonb, 'Morphine tends to lower body temperature slightly; hyperthermia is not one of its adverse effects. Dependence, constipation, respiratory depression and histamine-mediated bronchoconstriction are all well recognised. In overdose the patient is typically hypothermic, with coma and pinpoint pupils.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.292 Q8.13, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-1b532471ce', 'pharm-acute-opioid-toxicity', 'mcq', 'Symptoms of acute morphine toxicity include:', '["Coma, pinpoint pupils and depressed respiration", "Abdominal cramps, diarrhoea and miosis", "Dry mouth, mydriasis and hyperthermia", "Hypertension and cardiac arrhythmia", "Delirium, hyperpyrexia and truncal rigidity"]'::jsonb, 'Coma, pinpoint pupils and depressed respiration', '[]'::jsonb, 'The classic triad of acute opioid poisoning is coma, pinpoint pupils and respiratory depression, reversed by naloxone. Dry mouth, mydriasis and hyperthermia indicate atropine-like poisoning, and cramps with diarrhoea suggest cholinergic excess or opioid withdrawal.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.292 Q8.14, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-aab314f013', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'True statements about codeine include all of the following EXCEPT that it:', '["Is partially biotransformed to morphine", "Has antitussive action", "Causes constipation", "Has less addiction liability than morphine", "Is a benzylisoquinoline alkaloid"]'::jsonb, 'Is a benzylisoquinoline alkaloid', '[]'::jsonb, 'Codeine (methylmorphine) is a phenanthrene alkaloid; the benzylisoquinolines of opium are papaverine and noscapine. About 10% of codeine is demethylated by CYP2D6 to morphine, which provides its analgesia; it is antitussive, constipating and less addictive than morphine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.293 Q8.16, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-936a622ee2', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Pharmacological actions of meperidine (pethidine) include all of the following EXCEPT:', '["Analgesia", "Potent antitussive action", "Atropine-like actions", "CNS stimulation in overdose", "Histamine release"]'::jsonb, 'Potent antitussive action', '[]'::jsonb, 'Pethidine has no useful antitussive action. It has atropine-like effects (dry mouth, tachycardia, little miosis), and its metabolite norpethidine causes tremors and convulsions in overdose or renal failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.293 Q8.17, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-6445eae423', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which of the following opioid analgesics is about 80 times more potent than morphine as an analgesic?', '["Fentanyl", "Methadone", "Meperidine", "Pentazocine", "Propoxyphene"]'::jsonb, 'Fentanyl', '[]'::jsonb, 'Fentanyl is a highly lipid-soluble phenylpiperidine roughly 80 to 100 times as potent as morphine, with rapid onset and short duration, hence its use in anaesthesia. Methadone is about equipotent with morphine; meperidine, pentazocine and propoxyphene are weaker.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.293 Q8.18, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-f6b2bf3dc6', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following opioid analgesics induces a withdrawal syndrome when given to a morphine addict?', '["Meperidine", "Methadone", "Nalbuphine", "Hydromorphone", "Fentanyl"]'::jsonb, 'Nalbuphine', '[]'::jsonb, 'Nalbuphine is a kappa agonist and mu antagonist, so in a person dependent on morphine it displaces the agonist from mu receptors and precipitates withdrawal. Meperidine, methadone, hydromorphone and fentanyl are full mu agonists that would instead suppress withdrawal.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.293 Q8.19, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-dfa113932c', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which of the following statements is INCORRECT?', '["Morphine depresses the cough centre", "Naloxone is a pure opioid antagonist", "Meperidine does not constrict the pupil", "Fentanyl is a mixed agonist-antagonist opioid", "Papaverine is a direct spasmolytic of smooth muscle"]'::jsonb, 'Fentanyl is a mixed agonist-antagonist opioid', '[]'::jsonb, 'Fentanyl is a potent full mu agonist; mixed agonist-antagonists are pentazocine, nalbuphine and butorphanol. Meperidine''s atropine-like action means it causes little or no miosis, and papaverine relaxes smooth muscle directly by phosphodiesterase inhibition.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.294 Q8.20, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-1e6d92ba60', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Mixed agonist-antagonist opioids include:', '["Butorphanol", "Buprenorphine", "Nalbuphine", "Pentazocine", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Butorphanol, nalbuphine and pentazocine are kappa agonists with mu antagonist or partial agonist activity, and buprenorphine is a partial mu agonist and kappa antagonist; all are grouped as mixed agonist-antagonists and all can precipitate withdrawal in patients dependent on full agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.294 Q8.21, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-450dd8df2f', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following analgesics is NOT an opioid?', '["Fentanyl", "Alfentanil", "Meperidine", "Codeine", "Celecoxib"]'::jsonb, 'Celecoxib', '[]'::jsonb, 'Celecoxib is a selective COX-2 inhibitor, an NSAID that relieves pain by reducing prostaglandin synthesis. Fentanyl, alfentanil, meperidine and codeine all act as agonists at mu opioid receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.294 Q8.22, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-655df78add', 'pharm-sedative-hypnotic-drugs', 'mcq', 'As hypnotics, benzodiazepines differ from barbiturates in that:', '["They have a low therapeutic index", "They are more addictive", "They are more potent respiratory depressants", "They are more liable to produce pharmacokinetic tolerance", "They produce less depression of REM sleep"]'::jsonb, 'They produce less depression of REM sleep', '[]'::jsonb, 'Benzodiazepines suppress REM sleep less than barbiturates, so rebound on withdrawal is milder. They also have a much higher therapeutic index, cause less respiratory depression and dependence, and do not induce hepatic enzymes, so pharmacokinetic tolerance is not a feature.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.294 Q8.23, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-ab3c91981e', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Benzodiazepines can produce all of the following effects on the CNS EXCEPT:', '["Anxiolytic", "Anticonvulsant", "Hypnotic", "Akathisia", "Muscle relaxant"]'::jsonb, 'Akathisia', '[]'::jsonb, 'Akathisia (motor restlessness) is an extrapyramidal adverse effect of dopamine-blocking antipsychotics; benzodiazepines are in fact used to relieve it. By enhancing GABA-A transmission, benzodiazepines are anxiolytic, sedative-hypnotic, anticonvulsant and centrally muscle relaxant.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.294 Q8.24, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-55bf87594f', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Pharmacological actions of acetylsalicylic acid include all of the following EXCEPT:', '["Analgesic", "Antipyretic", "Anti-inflammatory", "Promotion of platelet aggregation", "Inhibition of synthesis of prostaglandins"]'::jsonb, 'Promotion of platelet aggregation', '[]'::jsonb, 'Aspirin irreversibly acetylates platelet COX-1, blocking thromboxane A2 synthesis for the life of the platelet, so it inhibits rather than promotes aggregation. Its analgesic, antipyretic and anti-inflammatory effects all follow from reduced prostaglandin synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.296 Q9.1, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-b91d43f9f1', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Aspirin is used in the treatment of:', '["Vertigo", "Peptic ulcer", "Acute left ventricular failure", "Acute bronchial asthma", "Acute rheumatic fever"]'::jsonb, 'Acute rheumatic fever', '[]'::jsonb, 'High-dose aspirin relieves the fever and arthritis of acute rheumatic fever. It is contraindicated in peptic ulcer because it damages the gastric mucosa, and it can precipitate bronchospasm in aspirin-sensitive asthmatics.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.296 Q9.2, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-54dd4f2aad', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Aspirin is used prophylactically for which one of the following conditions?', '["Bronchial asthma", "Thromboembolism", "Paroxysmal atrial tachycardia", "Peptic ulcer", "Hypertension"]'::jsonb, 'Thromboembolism', '[]'::jsonb, 'Low-dose aspirin irreversibly inhibits platelet thromboxane A2 synthesis and is used to prevent arterial thrombosis such as myocardial infarction and ischaemic stroke. It worsens peptic ulcer and may provoke asthma, so neither is an indication.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.296 Q9.4, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-a26ff90502', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following is an action of paracetamol?', '["Antithrombotic", "Antipyretic", "Anti-inflammatory", "Uricosuric", "Gastric ulceration"]'::jsonb, 'Antipyretic', '[]'::jsonb, 'Paracetamol is analgesic and antipyretic through inhibition of prostaglandin synthesis mainly in the CNS. It is a weak peripheral COX inhibitor in the presence of peroxides at inflamed sites, so it has negligible anti-inflammatory and antiplatelet activity and spares the gastric mucosa.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.297 Q9.5, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-6395fd5f68', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following drugs could be used as an analgesic-antipyretic in a patient with peptic ulcer?', '["Aspirin", "Phenylbutazone", "Chloroquine", "Paracetamol", "Indomethacin"]'::jsonb, 'Paracetamol', '[]'::jsonb, 'Paracetamol does not inhibit gastric prostaglandin synthesis and so does not cause mucosal injury or bleeding. Aspirin, phenylbutazone and indomethacin are ulcerogenic NSAIDs, and chloroquine is not an analgesic-antipyretic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.297 Q9.6, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-6443b1ffbe', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'Toxic doses of paracetamol cause:', '["Gastrointestinal bleeding", "Cardiac arrhythmias", "Sharp rise in blood pressure", "Hepatic necrosis", "Extrapyramidal reactions"]'::jsonb, 'Hepatic necrosis', '[]'::jsonb, 'In overdose the glucuronide and sulphate pathways saturate and more paracetamol is oxidised by CYP2E1 to NAPQI. Once hepatic glutathione is depleted, NAPQI binds cell proteins and causes centrilobular hepatic necrosis, sometimes with renal tubular necrosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.297 Q9.7, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-4adc297eae', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'Which of the following drugs is used in the treatment of acute paracetamol poisoning?', '["Acetylcysteine", "Dimercaprol", "Penicillamine", "Pralidoxime", "Physostigmine"]'::jsonb, 'Acetylcysteine', '[]'::jsonb, 'N-acetylcysteine replenishes hepatic glutathione and supplies sulphydryl groups that detoxify NAPQI; it is most effective within 8 to 10 hours of ingestion. Dimercaprol and penicillamine chelate heavy metals, and pralidoxime reactivates cholinesterase in organophosphate poisoning.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.297 Q9.8, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-b8c99ac7da', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Indomethacin is contraindicated in all of the following conditions EXCEPT:', '["Pregnancy", "Epilepsy", "Parkinsonism", "Peptic ulcer", "Gout"]'::jsonb, 'Gout', '[]'::jsonb, 'Indomethacin is a potent NSAID commonly used to treat acute gouty arthritis. It is avoided in pregnancy (premature closure of the ductus arteriosus), peptic ulcer, and in epilepsy, parkinsonism and psychiatric illness because its CNS effects may aggravate them.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.297 Q9.9, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-e7fe820c62', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Pharmacological actions of indomethacin include all of the following EXCEPT:', '["Anti-inflammatory", "Analgesic", "Antipyretic", "Antiepileptic", "Inhibition of cyclooxygenase"]'::jsonb, 'Antiepileptic', '[]'::jsonb, 'Indomethacin is a potent non-selective cyclooxygenase inhibitor with anti-inflammatory, analgesic and antipyretic actions. It has no anticonvulsant activity; on the contrary, its CNS adverse effects (headache, dizziness, confusion) may aggravate epilepsy.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.298 Q9.10, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-615883d009', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following NSAIDs is used to treat patent ductus arteriosus in neonates?', '["Ketoprofen", "Mefenamic acid", "Nabumetone", "Phenylbutazone", "Indomethacin"]'::jsonb, 'Indomethacin', '[]'::jsonb, 'Patency of the ductus arteriosus is maintained by prostaglandin E2; intravenous indomethacin (or ibuprofen) inhibits its synthesis and promotes closure in premature infants. The other NSAIDs listed are not used for this indication.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.298 Q9.11, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-55ad056699', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'All of the following are NSAIDs EXCEPT:', '["Ibuprofen", "Naproxen", "Butorphanol", "Piroxicam", "Tiaprofenic acid"]'::jsonb, 'Butorphanol', '[]'::jsonb, 'Butorphanol is a mixed agonist-antagonist opioid (kappa agonist, weak mu antagonist). Ibuprofen, naproxen and tiaprofenic acid are propionic acid NSAIDs and piroxicam is an oxicam; all inhibit cyclooxygenase.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.298 Q9.12, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-686cee82cc', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Therapeutic uses of diclofenac include all of the following EXCEPT:', '["Rheumatoid arthritis", "Osteoarthritis", "Petit mal epilepsy", "Dysmenorrhoea", "Acute musculoskeletal pain"]'::jsonb, 'Petit mal epilepsy', '[]'::jsonb, 'Diclofenac is a cyclooxygenase inhibitor used for inflammatory and painful conditions, including arthritis, dysmenorrhoea and musculoskeletal injury. It has no anticonvulsant action; absence (petit mal) seizures are treated with ethosuximide or valproate.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.298 Q9.13, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-ce291375e6', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Side effects shared by NSAIDs include all of the following EXCEPT:', '["Physical and psychological dependence", "Gastrointestinal ulceration", "Hypersensitivity", "Nephropathy", "Prolongation of gestation"]'::jsonb, 'Physical and psychological dependence', '[]'::jsonb, 'NSAIDs do not cause dependence, which distinguishes them from opioid analgesics. Their shared adverse effects come from prostaglandin inhibition: gastric ulceration, renal impairment, delayed labour, bleeding, and hypersensitivity reactions such as bronchospasm.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.298 Q9.14, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-a06e6942a0', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which of the following NSAIDs is a prodrug?', '["Indomethacin", "Piroxicam", "Sulindac", "Diclofenac", "Ketoprofen"]'::jsonb, 'Sulindac', '[]'::jsonb, 'Sulindac is an inactive sulphoxide that is reduced in the body to an active sulphide metabolite, which undergoes enterohepatic recycling. Nabumetone is the other classic NSAID prodrug. Indomethacin, piroxicam, diclofenac and ketoprofen are active as given.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.299 Q9.15, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-d9a5a5366e', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'All of the following drugs can be used in gout EXCEPT:', '["Allopurinol", "Probenecid", "Rasburicase", "Hydrochlorothiazide", "Indomethacin"]'::jsonb, 'Hydrochlorothiazide', '[]'::jsonb, 'Thiazide diuretics compete with uric acid for tubular secretion and cause hyperuricaemia, so they can precipitate gout. Allopurinol lowers urate production, probenecid is uricosuric, rasburicase breaks down uric acid and indomethacin treats the acute attack.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.299 Q9.16, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-5c854e99cd', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following is an action of colchicine?', '["It produces uricosuria", "It produces constipation", "It produces polycythaemia", "It stimulates cell division", "It inhibits leucocyte migration and phagocytosis"]'::jsonb, 'It inhibits leucocyte migration and phagocytosis', '[]'::jsonb, 'Colchicine binds tubulin and prevents microtubule polymerisation, so neutrophils cannot migrate into the joint or phagocytose urate crystals. It arrests mitosis in metaphase, has no effect on uric acid levels, and typically causes diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.299 Q9.17, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-da97353da6', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Allopurinol is:', '["An NSAID", "A uricosuric agent", "An opioid analgesic", "An inhibitor of xanthine oxidase", "A synthetic adrenocorticosteroid"]'::jsonb, 'An inhibitor of xanthine oxidase', '[]'::jsonb, 'Allopurinol and its metabolite oxypurinol (alloxanthine) inhibit xanthine oxidase, reducing conversion of hypoxanthine and xanthine to uric acid. It lowers urate production rather than increasing excretion, so it is not a uricosuric like probenecid.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.299 Q9.18, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-43e9095a48', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'All of the following are effective in the treatment of acute attacks of gout EXCEPT:', '["Colchicine", "Indomethacin", "Allopurinol", "Phenylbutazone", "Naproxen"]'::jsonb, 'Allopurinol', '[]'::jsonb, 'Allopurinol has no anti-inflammatory or analgesic action and, by mobilising urate, may prolong or precipitate an acute attack; it is started only after the attack has settled. Acute attacks are treated with NSAIDs, colchicine or corticosteroids.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.299 Q9.19, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-6d627329d0', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which of the following is a uricosuric agent used in chronic gout?', '["Sulphasalazine", "Sulphinpyrazone", "Allopurinol", "Colchicine", "Chloroquine"]'::jsonb, 'Sulphinpyrazone', '[]'::jsonb, 'Sulphinpyrazone, like probenecid, inhibits reabsorption of uric acid in the proximal tubule (URAT1), increasing its excretion. Allopurinol also lowers serum urate but by inhibiting its synthesis, so it is not uricosuric.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.20, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-3b99a93523', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: Aspirin is uricosuric in large doses (more than 5 g/day).', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Salicylates have a dose-dependent effect on urate: low doses (1 to 2 g/day) inhibit tubular secretion and cause urate retention, whereas large doses (over 5 g/day) also block reabsorption and become uricosuric.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.21, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-36737a5a64', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'saq', 'True or false: The antipyretic effect of NSAIDs is due to inhibition of pyrogen-induced production of PGE2.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Pyrogens such as interleukin-1 raise the hypothalamic temperature set-point by inducing COX-2 and prostaglandin E2 synthesis. NSAIDs block this synthesis, resetting the thermostat; they do not lower a normal body temperature.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.22, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-3ebcd8d317', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: Aspirin produces reversible competitive inhibition of cyclooxygenase.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Aspirin irreversibly inhibits cyclooxygenase by acetylating a serine residue in its active site; platelets cannot make new enzyme, so the effect lasts their lifetime (7 to 10 days). Other NSAIDs are reversible competitive inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.23, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-529f41d07e', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: In low doses, elimination of salicylates follows first-order kinetics, but in high doses elimination follows zero-order kinetics.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'The conjugation pathways for salicylate (with glycine and glucuronic acid) are saturable. At analgesic doses elimination is first order with a half-life of about 3 hours; at anti-inflammatory or toxic doses it becomes zero order and the half-life lengthens to 15 hours or more.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.24, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-168b838f23', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: The use of salicylates in children or adolescents with chickenpox or influenza is contraindicated.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Aspirin given during viral illnesses such as influenza or varicella is associated with Reye''s syndrome, a rare but often fatal acute encephalopathy with fatty liver. Paracetamol is used instead for fever in children.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.25, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-ee973e0073', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'True or false: Paracetamol has no effect on the excretion of uric acid.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Unlike salicylates, paracetamol does not alter renal handling of uric acid and does not antagonise uricosuric drugs, so it can be used as an analgesic in patients with gout who are taking probenecid.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.26, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-35afa8147d', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'True or false: Paracetamol has potent anti-inflammatory activity.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Paracetamol is a weak inhibitor of cyclooxygenase in peripheral tissues, where the high peroxide levels of inflammation reduce its activity. It is analgesic and antipyretic but has no clinically useful anti-inflammatory effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.27, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-3a9451c02c', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'True or false: Ibuprofen is a potent inhibitor of the cyclooxygenase enzyme.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Ibuprofen is a propionic acid derivative that reversibly and non-selectively inhibits COX-1 and COX-2, giving analgesic, antipyretic and anti-inflammatory effects with a relatively low incidence of gastrointestinal adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.28, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-9e91cd68ed', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'True or false: Acute attacks of gouty arthritis may occur early in treatment with allopurinol.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'When allopurinol lowers serum urate, crystals are mobilised from tissue deposits and can trigger acute arthritis. For this reason colchicine or an NSAID is given as cover during the first months of urate-lowering therapy.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.29, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-72e015450c', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'True or false: Probenecid inhibits renal tubular secretion of penicillin G.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Probenecid competes for the organic anion transporter in the proximal tubule. It blocks secretion of penicillins (prolonging their plasma levels) as well as blocking reabsorption of uric acid, which is the basis of its uricosuric effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.30, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-b5d6bf2456', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'True or false: Colchicine is effective in preventing attacks of familial Mediterranean fever.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Regular low-dose colchicine prevents attacks of familial Mediterranean fever and the amyloidosis that complicates it, by inhibiting microtubule-dependent neutrophil activation and migration. It is the same mechanism that makes it useful in acute gout, and it is taken lifelong in this condition.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.31, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-e64dcc80cd', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'True or false: The uricosuric effect of probenecid is antagonised by small doses of salicylates.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Low doses of aspirin inhibit tubular secretion of uric acid and antagonise the uricosuric action of probenecid and sulphinpyrazone, so salicylates should be avoided in patients taking these drugs; paracetamol is preferred.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.300 Q9.32, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-3eda718e54', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which of the following statements concerning penicillin is FALSE?', '["Penicillin G is destroyed by gastric acid", "Probenecid blocks renal tubular secretion of penicillins", "Benzathine penicillin G is slowly absorbed from intramuscular sites", "Penicillin G penetrates easily into CSF when the meninges are acutely inflamed", "None of the above"]'::jsonb, 'None of the above', '[]'::jsonb, 'All four statements are true. Penicillin G is acid-labile and so is given parenterally; it is excreted mainly by tubular secretion, which probenecid blocks; the benzathine salt forms a depot lasting weeks; and inflamed meninges allow therapeutic CSF concentrations.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.302 Q14.1, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--5188c9e793', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following antibiotics is bactericidal and acts by inhibiting synthesis of the bacterial cell wall?', '["Gentamicin", "Oxytetracycline", "Chloramphenicol", "Erythromycin", "Ampicillin"]'::jsonb, 'Ampicillin', '[]'::jsonb, 'Ampicillin is a beta-lactam: it binds penicillin-binding proteins, blocks transpeptidation of peptidoglycan and is bactericidal. Gentamicin is also bactericidal but acts on the 30S ribosome; the tetracyclines, chloramphenicol and erythromycin are bacteriostatic protein synthesis inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.302 Q14.2, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--b04fff1570', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is effective in the treatment of infections caused by penicillinase-producing staphylococci?', '["Ampicillin", "Carbenicillin", "Nafcillin", "Procaine penicillin G", "Azlocillin"]'::jsonb, 'Nafcillin', '[]'::jsonb, 'Nafcillin, like methicillin, oxacillin and cloxacillin, has a bulky side chain that protects the beta-lactam ring from staphylococcal penicillinase. Ampicillin, carbenicillin, azlocillin and penicillin G are all hydrolysed by the enzyme.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.302 Q14.3, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--a7b7cd25b1', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'All of the following penicillins are resistant to penicillinase EXCEPT:', '["Nafcillin", "Ticarcillin", "Cloxacillin", "Dicloxacillin", "Flucloxacillin"]'::jsonb, 'Ticarcillin', '[]'::jsonb, 'Ticarcillin is an antipseudomonal carboxypenicillin that is destroyed by beta-lactamases, which is why it is combined with clavulanic acid. Nafcillin and the isoxazolyl penicillins (cloxacillin, dicloxacillin, flucloxacillin) are the penicillinase-resistant antistaphylococcal group.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.302 Q14.4, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--0e1e2b0e0f', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is used to treat infection caused by Pseudomonas aeruginosa?', '["Benzathine penicillin G", "Cloxacillin", "Phenoxymethylpenicillin", "Nafcillin", "Piperacillin"]'::jsonb, 'Piperacillin', '[]'::jsonb, 'Piperacillin is a ureidopenicillin with extended Gram-negative activity including Pseudomonas aeruginosa, usually given with tazobactam. Penicillin G, penicillin V and the antistaphylococcal penicillins have no activity against Pseudomonas.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.303 Q14.5, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--86e5d05bb8', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Concerning ampicillin, all of the following are true EXCEPT:', '["It is acid-stable", "It is beta-lactamase-susceptible", "It is bactericidal", "It is active against Gram-positive and Gram-negative bacteria", "It is effective against Mycobacterium tuberculosis"]'::jsonb, 'It is effective against Mycobacterium tuberculosis', '[]'::jsonb, 'Ampicillin has no useful activity against Mycobacterium tuberculosis, whose waxy mycolic acid cell wall and beta-lactamase make it resistant. Ampicillin is an acid-stable, orally active, broad-spectrum aminopenicillin that is destroyed by beta-lactamases.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.303 Q14.6, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--cb5b6750c1', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following penicillins is a prodrug?', '["Amoxycillin", "Carbenicillin", "Bacampicillin", "Cloxacillin", "Phenoxymethylpenicillin"]'::jsonb, 'Bacampicillin', '[]'::jsonb, 'Bacampicillin (like pivampicillin and talampicillin) is an ester of ampicillin that is better absorbed and is hydrolysed to ampicillin in the gut wall and blood. The other penicillins listed are active as given.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.303 Q14.7, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-029b20df3b', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which of the following penicillins is used in the prophylaxis of rheumatic fever?', '["Benzathine penicillin G", "Cloxacillin", "Amoxycillin", "Carbenicillin", "Ticarcillin"]'::jsonb, 'Benzathine penicillin G', '[]'::jsonb, 'A single intramuscular injection of benzathine penicillin G releases penicillin slowly, giving low but sustained levels for 3 to 4 weeks, enough to prevent group A streptococcal pharyngitis and so recurrences of rheumatic fever.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.303 Q14.8, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-74a8a66b63', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'The main unwanted effect of penicillin is:', '["Vestibular dysfunction", "Depression of bone growth", "Brown discoloration of teeth", "Hypersensitivity reactions", "Grey baby syndrome"]'::jsonb, 'Hypersensitivity reactions', '[]'::jsonb, 'Penicillins have very low direct toxicity; their most important adverse effects are allergic, ranging from rashes to anaphylaxis, with cross-reactivity between penicillins. Vestibular damage is typical of aminoglycosides, tooth and bone effects of tetracyclines, and grey baby syndrome of chloramphenicol.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.303 Q14.9, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-a5319d7346', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which of the following is a beta-lactamase inhibitor used in combination with amoxicillin to treat infections caused by beta-lactamase-producing bacteria?', '["Nalidixic acid", "Clavulanic acid", "Ticarcillin", "Mezlocillin", "Azlocillin"]'::jsonb, 'Clavulanic acid', '[]'::jsonb, 'Clavulanic acid is a beta-lactam with little antibacterial activity that irreversibly inactivates many beta-lactamases (a ''suicide'' inhibitor), protecting amoxicillin (co-amoxiclav). Ticarcillin, mezlocillin and azlocillin are themselves beta-lactamase-susceptible penicillins.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.304 Q14.10, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-05821689c9', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Cephalosporins inhibit bacterial:', '["Dihydrofolic acid reductase", "DNA gyrase", "Protein synthesis", "Cell membrane function", "Cell wall synthesis"]'::jsonb, 'Cell wall synthesis', '[]'::jsonb, 'Like penicillins, cephalosporins are beta-lactams that bind penicillin-binding proteins and inhibit the transpeptidation step of peptidoglycan synthesis. Dihydrofolate reductase is the target of trimethoprim and DNA gyrase of the fluoroquinolones.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.304 Q14.11, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-4f79674527', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Correct statements concerning cephalosporins include all of the following EXCEPT:', '["They have a beta-lactam ring", "They are bactericidal", "They inhibit cell wall synthesis", "They cause discoloration of teeth in children", "First-generation cephalosporins do not penetrate the blood-brain barrier"]'::jsonb, 'They cause discoloration of teeth in children', '[]'::jsonb, 'Tooth discoloration is caused by tetracyclines, which chelate calcium in developing teeth and bone. Cephalosporins are bactericidal beta-lactams; first- and most second-generation agents do not reach useful CSF levels, unlike third-generation drugs such as ceftriaxone.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.304 Q14.12, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-4585480157', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Penicillins have little or no antibacterial activity against:', '["Treponema pallidum", "Gonococci", "Meningococci", "Resting bacterial cells", "Streptococci"]'::jsonb, 'Resting bacterial cells', '[]'::jsonb, 'Penicillins kill only actively growing and dividing bacteria, because they act by blocking synthesis of new peptidoglycan and triggering autolysins. Non-dividing (resting) cells are not making cell wall and are therefore unaffected.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.304 Q14.13, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-74425e766a', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'All of the following inhibit bacterial cell wall synthesis EXCEPT:', '["Bacitracin", "Cycloserine", "Cefepime", "Vancomycin", "Polymyxin"]'::jsonb, 'Polymyxin', '[]'::jsonb, 'Polymyxins are cationic detergents that disrupt the outer and cytoplasmic membranes of Gram-negative bacteria. Bacitracin, cycloserine, vancomycin and beta-lactams such as cefepime all block different steps of peptidoglycan synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.304 Q14.14, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-78d1d5112e', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Side effects of penicillins include all of the following EXCEPT:', '["Hypersensitivity reactions", "Interstitial nephritis", "Impaired platelet function", "Seizures", "Disulfiram-like action"]'::jsonb, 'Disulfiram-like action', '[]'::jsonb, 'A disulfiram-like reaction with alcohol occurs with cephalosporins bearing a methylthiotetrazole side chain (such as cefoperazone) and with metronidazole, not with penicillins. Penicillins can cause allergy, interstitial nephritis (methicillin), platelet dysfunction (carbenicillin, ticarcillin) and seizures at very high doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.305 Q14.15, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-5ea3faa35f', 'pharm-anti-fungals', 'mcq', 'Amphotericin B has all of the following properties EXCEPT:', '["It may cause renal damage", "It is poorly absorbed orally", "It is used for systemic fungal infections", "It binds to ergosterol of the fungal membrane", "It is an enzyme activator (inducer)"]'::jsonb, 'It is an enzyme activator (inducer)', '[]'::jsonb, 'Amphotericin B is not a hepatic enzyme inducer. It is a polyene that binds ergosterol and forms pores in the fungal membrane; it is given intravenously for systemic mycoses because oral absorption is negligible, and nephrotoxicity is its main dose-limiting effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.305 Q14.16, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-bafa12d4b1', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which of the following is correct about vancomycin?', '["It inhibits cell wall synthesis", "It is primarily effective against Gram-negative organisms", "It is usually administered orally", "It can cause Fanconi syndrome", "It can cause grey baby syndrome"]'::jsonb, 'It inhibits cell wall synthesis', '[]'::jsonb, 'Vancomycin binds the D-Ala-D-Ala terminus of peptidoglycan precursors, blocking transglycosylation. It is active only against Gram-positive bacteria (including MRSA) and is given intravenously, orally only for Clostridioides difficile colitis because it is not absorbed.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.305 Q14.17, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-aeab154078', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Clindamycin is:', '["A broad-spectrum antibiotic", "An inhibitor of cell wall synthesis", "Effective against Salmonella typhi", "Liable to produce pseudomembranous colitis", "None of the above"]'::jsonb, 'Liable to produce pseudomembranous colitis', '[]'::jsonb, 'Clindamycin suppresses normal bowel flora and allows overgrowth of toxin-producing Clostridioides difficile, causing pseudomembranous colitis. It is a narrow-spectrum 50S protein synthesis inhibitor active against Gram-positive cocci and anaerobes, not enteric Gram-negative bacilli.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.305 Q14.18, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-6275dfe497', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'All of the following antibiotics act through inhibition of bacterial protein synthesis EXCEPT:', '["Cefadroxil", "Chloramphenicol", "Erythromycin", "Tetracycline", "Gentamicin"]'::jsonb, 'Cefadroxil', '[]'::jsonb, 'Cefadroxil is a first-generation cephalosporin that inhibits cell wall synthesis. Chloramphenicol and erythromycin bind the 50S ribosomal subunit, while tetracycline and gentamicin bind the 30S subunit, all inhibiting protein synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.305 Q14.19, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-d7114271b8', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'All of the following antimicrobials are bactericidal EXCEPT:', '["Ofloxacin", "Ampicillin", "Cefoperazone", "Doxycycline", "Tobramycin"]'::jsonb, 'Doxycycline', '[]'::jsonb, 'Doxycycline, a tetracycline, reversibly blocks binding of aminoacyl-tRNA to the 30S ribosome and is bacteriostatic. Fluoroquinolones, beta-lactams and aminoglycosides are bactericidal. Bacteriostatic drugs rely on host defences to clear the infection, which matters in immunocompromised patients and in endocarditis or meningitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.306 Q14.20, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-88fb481092', 'pharm-aminoglycosides', 'mcq', 'All of the following are aminoglycoside antibiotics EXCEPT:', '["Amikacin", "Neomycin", "Kanamycin", "Tobramycin", "Clindamycin"]'::jsonb, 'Clindamycin', '[]'::jsonb, 'Clindamycin is a lincosamide that binds the 50S ribosomal subunit. Amikacin, neomycin, kanamycin and tobramycin are aminoglycosides, bactericidal drugs that bind the 30S subunit and cause misreading of mRNA.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.306 Q14.21, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-11707e4c63', 'pharm-aminoglycosides', 'mcq', 'Concerning aminoglycosides, all of the following are true EXCEPT that:', '["They are bactericidal", "They are poorly absorbed from the intestine", "They are nephrotoxic", "They cannot cross the placental barrier", "They are excreted by glomerular filtration"]'::jsonb, 'They cannot cross the placental barrier', '[]'::jsonb, 'Aminoglycosides do cross the placenta and can cause fetal ototoxicity (congenital deafness, notably with streptomycin). They are polar polycations, so they are not absorbed orally, and are excreted unchanged by glomerular filtration, accumulating in renal failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.306 Q14.22, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-b5a63a82f2', 'pharm-aminoglycosides', 'mcq', 'Which of the following antibiotics is used orally to reduce ammonia-producing organisms in the gut of patients with hepatic encephalopathy?', '["Penicillin G", "Tetracycline", "Neomycin", "Chloramphenicol", "Cefotaxime"]'::jsonb, 'Neomycin', '[]'::jsonb, 'Neomycin is an aminoglycoside that is not absorbed from the gut, so an oral dose stays in the lumen and suppresses urease-producing bacteria, lowering ammonia production. It is too toxic for systemic use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.306 Q14.23, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-7cc8797cd3', 'pharm-aminoglycosides', 'mcq', 'Which of the following statements concerning gentamicin is FALSE?', '["It is bactericidal", "It is nephrotoxic", "It is well absorbed from the gastrointestinal tract", "It is excreted unchanged by glomerular filtration", "It is active against aerobic Gram-negative organisms"]'::jsonb, 'It is well absorbed from the gastrointestinal tract', '[]'::jsonb, 'Gentamicin is a highly polar polycation and is hardly absorbed from the gut, so it must be given parenterally for systemic infection. It is bactericidal against aerobic Gram-negative bacilli, eliminated unchanged by the kidney, and is nephrotoxic and ototoxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.306 Q14.24, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-a49683a76e', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which of the following inhibits bacterial protein synthesis by binding to the 50S ribosomal subunit?', '["Nystatin", "Penicillin G", "Chloramphenicol", "Cephradine", "Polymyxin B"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Chloramphenicol binds the 50S subunit and inhibits peptidyl transferase, blocking peptide bond formation. Nystatin and polymyxin B act on cell membranes, and penicillin G and cephradine inhibit cell wall synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.307 Q14.25, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-b5340b7a41', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which of the following antibiotics may cause grey baby syndrome in neonates, especially premature babies?', '["Ampicillin", "Chloramphenicol", "Gentamicin", "Cephalexin", "Clindamycin"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Neonates have immature glucuronyl transferase and poor renal excretion, so chloramphenicol accumulates, causing vomiting, abdominal distension, cyanosis, grey skin colour and circulatory collapse. The risk is avoided by using other drugs or reduced doses with plasma level monitoring in newborns.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.307 Q14.26, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-6c8eb84a4c', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'The most important adverse effect of chloramphenicol is:', '["Nephrotoxicity", "Ototoxicity", "Bone marrow depression", "Hepatitis", "Peripheral neuritis"]'::jsonb, 'Bone marrow depression', '[]'::jsonb, 'Chloramphenicol causes dose-related reversible marrow suppression (by inhibiting mitochondrial protein synthesis) and, rarely, idiosyncratic irreversible aplastic anaemia, which is often fatal. Nephrotoxicity and ototoxicity are characteristic of aminoglycosides.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.307 Q14.27, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-b4e3d5b63a', 'pharm-drug-interactions', 'mcq', 'Which of the following antibiotics inhibits hepatic microsomal cytochrome P450?', '["Rifampicin", "Ampicillin", "Cephalexin", "Chloramphenicol", "Tetracycline"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Chloramphenicol inhibits hepatic CYP enzymes, raising levels of drugs such as phenytoin, warfarin and sulfonylureas. Rifampicin does the opposite: it is a powerful enzyme inducer that lowers the levels of many drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.307 Q14.28, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-4e7e956c07', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Treatment of pregnant patients with tetracyclines may produce which adverse effect in their children?', '["Deafness", "Hypothyroidism and goitre", "Haemorrhage", "Discoloration of teeth", "Grey baby syndrome"]'::jsonb, 'Discoloration of teeth', '[]'::jsonb, 'Tetracyclines cross the placenta and chelate calcium in developing teeth and bones, causing permanent yellow-brown staining, enamel hypoplasia and reduced bone growth. They are therefore avoided in pregnancy and in children under 8 years.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.308 Q14.29, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-20bc6c43f5', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Which of the following tetracyclines does not require renal excretion and does not accumulate significantly in renal failure?', '["Doxycycline", "Tetracycline", "Oxytetracycline", "Demeclocycline", "Chlortetracycline"]'::jsonb, 'Doxycycline', '[]'::jsonb, 'Doxycycline is eliminated mainly by non-renal routes (in the faeces via bile and the gut wall), so no dose adjustment is needed in renal impairment. Other tetracyclines depend on renal excretion and accumulate, worsening uraemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.308 Q14.30, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-103612b163', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Fanconi syndrome may be caused by taking which of the following antibiotics after its expiry date?', '["Penicillin V", "Erythromycin", "Tetracycline", "Chloramphenicol", "Clindamycin"]'::jsonb, 'Tetracycline', '[]'::jsonb, 'Outdated tetracycline degrades to epianhydrotetracycline, which damages the proximal renal tubule and causes a Fanconi-like syndrome with loss of glucose, amino acids, phosphate and bicarbonate in the urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.308 Q14.31, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-f55402c5c1', 'pharm-anti-tb-drugs', 'mcq', 'Which of the following inhibits RNA synthesis in bacteria by binding to DNA-dependent RNA polymerase?', '["Rifampicin", "Cephalosporins", "Aminoglycosides", "Tetracyclines", "Quinolones"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Rifampicin binds the beta subunit of bacterial DNA-dependent RNA polymerase and blocks transcription. Quinolones are the tempting alternative because they also act on nucleic acids, but they inhibit DNA gyrase and topoisomerase IV, blocking DNA replication.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.308 Q14.32, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-4117be99c8', 'pharm-macrolides', 'mcq', 'Concerning erythromycin, all of the following are true EXCEPT that:', '["It is a macrolide", "It inhibits bacterial protein synthesis by binding to the 50S ribosomal subunit", "It is effective against Gram-positive bacteria", "It increases the clearance of theophylline", "Erythromycin estolate may cause cholestatic hepatitis"]'::jsonb, 'It increases the clearance of theophylline', '[]'::jsonb, 'Erythromycin inhibits CYP3A4 and so reduces the clearance of theophylline, warfarin and carbamazepine, risking toxicity. It is a macrolide binding the 50S subunit, mainly active against Gram-positive organisms, and the estolate salt can cause cholestatic hepatitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.309 Q14.33, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-612682e566', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'An inhibitor of bacterial dihydrofolic acid reductase is:', '["Sulfadiazine", "Trimethoprim", "Para-aminosalicylic acid", "Isoniazid", "Ciprofloxacin"]'::jsonb, 'Trimethoprim', '[]'::jsonb, 'Trimethoprim selectively inhibits bacterial dihydrofolate reductase, blocking formation of tetrahydrofolate. Sulfadiazine and para-aminosalicylic acid act one step earlier, competing with PABA at dihydropteroate synthase, which is why sulfonamide plus trimethoprim is synergistic.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.309 Q14.34, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-15300109aa', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Kernicterus in neonates, especially premature babies, caused by sulfonamides is due to:', '["Enhanced synthesis of bilirubin", "Inhibition of bilirubin degradation", "Inhibition of urinary excretion of bilirubin", "Displacement of bound bilirubin from albumin", "Impaired bilirubin excretion into the hepatic canaliculi"]'::jsonb, 'Displacement of bound bilirubin from albumin', '[]'::jsonb, 'Sulfonamides are highly protein bound and displace unconjugated bilirubin from albumin. In neonates, whose conjugating capacity and blood-brain barrier are immature, the free bilirubin enters the basal ganglia and causes kernicterus.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.309 Q14.35, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-1ad94dbc96', 'pharm-anti-tb-drugs', 'mcq', 'The following adverse effects are correctly paired with the antituberculous drug EXCEPT:', '["Peripheral neuropathy - isoniazid", "Ototoxicity - rifampicin", "Optic neuritis - ethambutol", "Hyperuricaemia - pyrazinamide", "Vestibular dysfunction - streptomycin"]'::jsonb, 'Ototoxicity - rifampicin', '[]'::jsonb, 'Rifampicin is not ototoxic; its main adverse effects are hepatitis, orange-red body fluids, a flu-like syndrome and enzyme induction. Ototoxicity belongs to streptomycin and other aminoglycosides. The other pairings are the classic toxicities of each drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.309 Q14.36, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-cb27703fbe', 'pharm-anti-tb-drugs', 'mcq', 'Concerning isoniazid, all of the following are true EXCEPT that:', '["It inhibits synthesis of mycolic acid", "It is readily absorbed from the gastrointestinal tract", "It is metabolised by acetylation", "It does not penetrate into caseous material", "It may cause haemolytic anaemia in individuals with G6PD deficiency"]'::jsonb, 'It does not penetrate into caseous material', '[]'::jsonb, 'Isoniazid is a small molecule that diffuses into all body fluids and tissues, including CSF and caseous lesions, and acts on intracellular and extracellular bacilli. It blocks mycolic acid synthesis and is acetylated by the genetically variable enzyme NAT2.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.309 Q14.37, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-0df5355be9', 'pharm-anti-tb-drugs', 'mcq', 'First-line drugs for the treatment of tuberculosis include all of the following EXCEPT:', '["Isoniazid", "Rifampicin", "Ethionamide", "Ethambutol", "Pyrazinamide"]'::jsonb, 'Ethionamide', '[]'::jsonb, 'Ethionamide is a second-line drug reserved for resistant tuberculosis because it is less effective and poorly tolerated (gastric irritation, hepatotoxicity, neurotoxicity). The first-line drugs are rifampicin, isoniazid, pyrazinamide and ethambutol (with streptomycin).', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.310 Q14.38, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-ebc20fb3dd', 'pharm-anti-tb-drugs', 'mcq', 'Toxic effects of isoniazid involving the peripheral and central nervous systems can be prevented by administration of:', '["Folic acid", "Thiamine", "Pyridoxine", "Cyanocobalamin", "Phytomenadione"]'::jsonb, 'Pyridoxine', '[]'::jsonb, 'Isoniazid forms a hydrazone with pyridoxal and inhibits pyridoxal kinase, increasing urinary loss of vitamin B6 and causing peripheral neuropathy and, in overdose, seizures. Prophylactic pyridoxine (10 to 50 mg daily) prevents this.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.310 Q14.39, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-8a91fd5990', 'pharm-anti-tb-drugs', 'mcq', 'Adverse effects of isoniazid include all of the following EXCEPT:', '["Hepatotoxicity", "Peripheral neuritis", "Skin rash", "Increased metabolism of phenytoin", "Vasculitis"]'::jsonb, 'Increased metabolism of phenytoin', '[]'::jsonb, 'Isoniazid inhibits cytochrome P450 enzymes, so it reduces the metabolism of phenytoin and carbamazepine and can cause toxicity, especially in slow acetylators. Enzyme induction with increased drug metabolism is the effect of rifampicin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.310 Q14.40, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-88b42e9d84', 'pharm-anti-tb-drugs', 'mcq', 'Clinical uses of rifampicin include all of the following EXCEPT:', '["Tuberculosis", "Leprosy", "Typhoid fever", "Prophylaxis of meningococcal disease", "Prophylaxis of Haemophilus influenzae meningitis"]'::jsonb, 'Typhoid fever', '[]'::jsonb, 'Rifampicin is not used for typhoid fever, which is treated with fluoroquinolones, ceftriaxone or azithromycin. Rifampicin is used in tuberculosis and leprosy, and to eradicate nasopharyngeal carriage in contacts of meningococcal and H. influenzae type b meningitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.310 Q14.41, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-d6b0ea8120', 'pharm-anti-tb-drugs', 'mcq', 'Unwanted effects of rifampicin include all of the following EXCEPT:', '["Orange colour of urine, tears and sweat", "Influenza-like syndrome", "Jaundice", "Thrombocytopenia", "Optic neuritis"]'::jsonb, 'Optic neuritis', '[]'::jsonb, 'Optic (retrobulbar) neuritis with reduced visual acuity and red-green colour blindness is the characteristic toxicity of ethambutol. Rifampicin causes harmless orange-red secretions, hepatitis with cholestatic jaundice, and, with intermittent dosing, a flu-like syndrome and thrombocytopenia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.310 Q14.42, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-133f666da9', 'pharm-anti-tb-drugs', 'mcq', 'Optic neuritis is a serious toxic effect of:', '["Rifampicin", "Isoniazid", "Ethionamide", "Ethambutol", "Pyrazinamide"]'::jsonb, 'Ethambutol', '[]'::jsonb, 'Ethambutol causes dose-related retrobulbar neuritis, first noticed as loss of visual acuity and red-green colour discrimination, so vision is checked before and during treatment. Isoniazid mainly causes peripheral neuropathy and hepatitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.311 Q14.43, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-5b73b6cb2d', 'pharm-anti-leprosy-drugs', 'mcq', 'Which of the following is useful in the treatment of both tuberculosis and leprosy?', '["Streptomycin", "Isoniazid", "Pyrazinamide", "Rifampicin", "Ethambutol"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Rifampicin is bactericidal against both Mycobacterium tuberculosis and Mycobacterium leprae; it is given monthly with dapsone (and clofazimine) in WHO multidrug therapy for leprosy. Isoniazid and pyrazinamide have no useful activity against M. leprae.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.311 Q14.44, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-1f0c7f2223', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Therapeutic uses of trimethoprim-sulphamethoxazole (co-trimoxazole) include all of the following EXCEPT:', '["Urinary tract infections", "Typhoid fever", "Tuberculosis", "Pneumocystis pneumonia", "Prostatitis"]'::jsonb, 'Tuberculosis', '[]'::jsonb, 'Co-trimoxazole is not used to treat tuberculosis. Sequential blockade of folate synthesis makes it useful for urinary and prostatic infections, susceptible Salmonella, and it is the drug of choice for treatment and prophylaxis of Pneumocystis jirovecii pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.311 Q14.45, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-a6248a5b26', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Ulcerative colitis is treated with:', '["Sulphisoxazole", "Sulphadiazine", "Sulphamethoxazole", "Sulphasalazine", "Sulphadoxine"]'::jsonb, 'Sulphasalazine', '[]'::jsonb, 'Sulphasalazine is poorly absorbed and is split by colonic bacteria into sulphapyridine and 5-aminosalicylic acid, which acts locally as an anti-inflammatory in the colon. The other sulfonamides are absorbed antibacterials with no such action.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.311 Q14.46, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-b72dff28c0', 'pharm-quinolones', 'mcq', 'Concerning fluoroquinolones, all of the following are true EXCEPT that:', '["They are bactericidal", "They inhibit bacterial DNA gyrase", "They are not recommended for use in prepubertal children", "Ciprofloxacin inhibits the metabolism of theophylline", "They are active against Treponema pallidum"]'::jsonb, 'They are active against Treponema pallidum', '[]'::jsonb, 'Fluoroquinolones have no reliable activity against Treponema pallidum; syphilis is treated with penicillin. They are bactericidal inhibitors of DNA gyrase and topoisomerase IV, damage growing cartilage in young animals, and ciprofloxacin inhibits CYP1A2, raising theophylline levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.311 Q14.47, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-9b1ad8b773', 'pharm-anti-fungals', 'mcq', 'Which of the following is useful for candidiasis?', '["Tetracycline", "Ampicillin", "Nystatin", "Metronidazole", "Clindamycin"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is a polyene antifungal that binds ergosterol in the fungal membrane; it is used topically for oral, vaginal and cutaneous candidiasis. Broad-spectrum antibacterials such as tetracycline and ampicillin actually predispose to candidiasis by suppressing normal flora.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.312 Q14.48, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-0477c7098d', 'pharm-antivirals', 'mcq', 'Which of the following is effective in the treatment of herpes simplex virus (HSV) infection?', '["Ampicillin", "Griseofulvin", "Diloxanide furoate", "Acyclovir", "Chloroquine"]'::jsonb, 'Acyclovir', '[]'::jsonb, 'Acyclovir is phosphorylated by the viral thymidine kinase and then by host kinases to acyclovir triphosphate, which inhibits herpes DNA polymerase and terminates the DNA chain. Griseofulvin is an antifungal and diloxanide an amoebicide.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.312 Q14.49, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-d5c302c985', 'pharm-antiretroviral-i', 'mcq', 'Which of the following is an antiretroviral drug used in the treatment of HIV infection?', '["Acyclovir", "Rifampin", "Zidovudine (AZT)", "Vidarabine", "Amantadine"]'::jsonb, 'Zidovudine (AZT)', '[]'::jsonb, 'Zidovudine is a thymidine analogue nucleoside reverse transcriptase inhibitor, the first drug licensed for HIV. Acyclovir and vidarabine act on herpesviruses and amantadine on influenza A; none inhibits HIV reverse transcriptase.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.312 Q14.50, Zarif & Sayed pharmacology MCQs. Reworded: the paper asks for ''the agent of choice in treatment of HIV infection (AIDS)'', which is outdated (modern first-line therapy is combination ART based on dolutegravir).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-6f78c3a207', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Metronidazole is effective in the treatment of all of the following EXCEPT:', '["Amoebiasis", "Trichomoniasis", "Candidiasis", "Giardiasis", "Anaerobic infections"]'::jsonb, 'Candidiasis', '[]'::jsonb, 'Metronidazole is activated only in anaerobic organisms, so it works against Entamoeba, Trichomonas, Giardia and anaerobic bacteria. It has no antifungal activity; indeed candidiasis may follow its use.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.312 Q14.51, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-6b3e5d8a4b', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which of the following is a fourth-generation cephalosporin?', '["Sulbactam", "Ceftriaxone", "Cefepime", "Talampicillin", "Dicloxacillin"]'::jsonb, 'Cefepime', '[]'::jsonb, 'Cefepime is a fourth-generation cephalosporin with good activity against both Gram-positive cocci and Gram-negative bacilli including Pseudomonas, and greater stability to chromosomal beta-lactamases. Ceftriaxone is third generation. Sulbactam is a beta-lactamase inhibitor and the remaining options are penicillins.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.52, Zarif & Sayed pharmacology MCQs. Built from a matching question with six options (Benzylpenicillin dropped).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--23a6d63f31', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is a beta-lactamase-resistant penicillin?', '["Sulbactam", "Ceftriaxone", "Talampicillin", "Dicloxacillin", "Benzylpenicillin"]'::jsonb, 'Dicloxacillin', '[]'::jsonb, 'Dicloxacillin is an isoxazolyl penicillin whose bulky side chain protects it from staphylococcal penicillinase. Benzylpenicillin and talampicillin (an ampicillin ester) are hydrolysed, and sulbactam is an enzyme inhibitor rather than a penicillin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.53, Zarif & Sayed pharmacology MCQs. Built from a matching question with six options (Cefepime dropped).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-f344ec7dca', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which of the following is a beta-lactamase enzyme inhibitor?', '["Sulbactam", "Ceftriaxone", "Cefepime", "Talampicillin", "Dicloxacillin"]'::jsonb, 'Sulbactam', '[]'::jsonb, 'Sulbactam, like clavulanic acid and tazobactam, irreversibly inhibits many beta-lactamases and is combined with ampicillin to extend its spectrum. Dicloxacillin resists staphylococcal penicillinase but does not inhibit the enzyme for other drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.54, Zarif & Sayed pharmacology MCQs. Built from a matching question with six options (Benzylpenicillin dropped).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--f2660a3250', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is a prodrug?', '["Sulbactam", "Ceftriaxone", "Cefepime", "Talampicillin", "Benzylpenicillin"]'::jsonb, 'Talampicillin', '[]'::jsonb, 'Talampicillin is an ester prodrug of ampicillin with better oral absorption; esterases in the gut wall and blood release the active ampicillin. The other drugs listed are active as administered.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.55, Zarif & Sayed pharmacology MCQs. Built from a matching question with six options (Dicloxacillin dropped).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--8d71d8a63f', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'saq', 'True or false: Ampicillin may cause diarrhoea.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Ampicillin is incompletely absorbed and has a broad spectrum, so it disturbs the normal bowel flora, commonly causing diarrhoea and occasionally Clostridioides difficile colitis. Amoxicillin is better absorbed and causes diarrhoea less often.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.56, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-bdd94ce7e9', 'pharm-cephalosporins-and-cephamycins', 'saq', 'True or false: Cephalosporins inhibit bacterial protein synthesis.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Cephalosporins are beta-lactams: they bind penicillin-binding proteins and inhibit peptidoglycan cross-linking, i.e. cell wall synthesis. Protein synthesis inhibitors include aminoglycosides, tetracyclines, macrolides and chloramphenicol. Confusing the two groups is a common error because both are large antibiotic families.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.57, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-9dd4a587b2', 'pharm-cephalosporins-and-cephamycins', 'saq', 'True or false: Probenecid blocks tubular secretion of cephalosporins.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Most cephalosporins, like penicillins, are actively secreted by the organic anion transporter of the proximal tubule. Probenecid competes for this transporter and so raises and prolongs their plasma concentrations.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.58, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-0116b1679c', 'pharm-aminoglycosides', 'saq', 'True or false: Aminoglycosides are effective against anaerobic microorganisms.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Uptake of aminoglycosides across the bacterial cytoplasmic membrane is an oxygen-dependent active process, so anaerobes are intrinsically resistant. Their main use is against aerobic Gram-negative bacilli. This is why they are combined with metronidazole or clindamycin in mixed abdominal infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.59, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-f7d97628f0', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'True or false: Doxycycline is useful in the treatment of brucellosis.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Tetracyclines penetrate cells and are active against intracellular organisms. Doxycycline combined with rifampicin or an aminoglycoside (streptomycin or gentamicin) is the standard treatment for brucellosis. Treatment is continued for about six weeks to prevent relapse.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.60, Zarif & Sayed pharmacology MCQs. No dedicated topic for this drug class in topics.txt; closest general antimicrobial topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-ec96d147ea', 'pharm-quinolones', 'saq', 'True or false: Ciprofloxacin is useful in the treatment of candidiasis.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Ciprofloxacin is an antibacterial fluoroquinolone that inhibits bacterial DNA gyrase; it has no antifungal activity. Candidiasis is treated with azoles such as fluconazole or polyenes such as nystatin.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.61, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-bb172c4dde', 'pharm-anti-tb-drugs', 'saq', 'True or false: Isoniazid is acetylated in the liver.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Isoniazid is metabolised by hepatic N-acetyltransferase 2. The rate is genetically determined: slow acetylators are more prone to peripheral neuropathy, while the acetylated metabolites contribute to hepatotoxicity. Acetyl-isoniazid is then excreted in the urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'mcq p.313 Q14.62, Zarif & Sayed pharmacology MCQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-e6ba20cacc', 'pharm-preanesthetic-agent', 'saq', 'List 4 aims of preanaesthetic medication and give an example of a drug used to fulfil each aim.', '[]'::jsonb, 'Any 4 of: relieve anxiety/produce sedation - diazepam, midazolam; amnesia - midazolam, lorazepam; analgesia - morphine, pethidine, fentanyl; reduce secretions and vagal reflexes - atropine, glycopyrrolate, hyoscine; reduce gastric acidity/volume (aspiration risk) - ranitidine, omeprazole, metoclopramide; prevent nausea and vomiting - ondansetron, metoclopramide.', '[]'::jsonb, 'Premedication makes induction smoother and safer. Benzodiazepines calm the patient and give anterograde amnesia, opioids provide analgesia and reduce the anaesthetic dose, antimuscarinics dry secretions and block vagal bradycardia, and H2 blockers, proton pump inhibitors or metoclopramide lower the risk of acid aspiration.', 'admin', 'published', 4, true, '[["anxiolysis", "sedation", "reduce anxiety", "relieve anxiety"], ["amnesia"], ["analgesia", "pain relief"], ["reduce secretions", "antisialagogue", "dry secretions", "vagal reflexes"], ["gastric acidity", "reduce aspiration", "gastric volume"], ["antiemetic", "nausea and vomiting", "prevent vomiting"], ["diazepam", "midazolam", "lorazepam"], ["morphine", "pethidine", "fentanyl"], ["atropine", "glycopyrrolate", "hyoscine"], ["ranitidine", "omeprazole", "metoclopramide", "ondansetron"]]'::jsonb, 'saq p.004 Q2, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-97968b4982', 'pharm-adverse-drug-reactions', 'saq', 'List 5 characteristics of Type B adverse drug reactions.', '[]'::jsonb, 'Any 5 of: unpredictable (bizarre); not dose-related; not related to the drug''s known pharmacological action; uncommon/rare; depend on host factors - immunological (allergy) or genetic (idiosyncrasy); high mortality; often not detected before marketing; managed by stopping the drug and avoiding it in future.', '[]'::jsonb, 'Type B (bizarre) reactions arise from the patient rather than the dose: allergy or a genetic idiosyncrasy. They cannot be predicted from the drug''s pharmacology, are rare but often serious, and the treatment is withdrawal and future avoidance. Type A reactions are the opposite: common, dose-related and predictable.', 'admin', 'published', 5, true, '[["unpredictable", "bizarre"], ["not dose related", "dose independent", "not dose dependent"], ["unrelated to pharmacology", "not pharmacological action"], ["uncommon", "rare"], ["immunological", "allergic", "hypersensitivity", "idiosyncratic", "genetic"], ["high mortality", "serious", "fatal"], ["stop the drug", "withdraw drug", "avoid in future"]]'::jsonb, 'saq p.006 Q3, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-a1100ab163', 'pharm-anti-fungals', 'saq', 'Classify antifungal drugs according to clinical use and give two examples in each class.', '[]'::jsonb, '1. Systemic drugs for systemic (deep) mycoses: amphotericin B, flucytosine, fluconazole, itraconazole, voriconazole, caspofungin. 2. Oral systemic drugs for mucocutaneous (superficial) infections: griseofulvin, terbinafine, ketoconazole, fluconazole. 3. Topical drugs for mucocutaneous infections: nystatin, clotrimazole, miconazole, topical terbinafine.', '[]'::jsonb, 'Antifungals are grouped by where the infection lies: life-threatening systemic mycoses need systemic agents such as amphotericin B, azoles or echinocandins; dermatophyte infections of skin, hair and nails respond to oral griseofulvin or terbinafine; and localised skin or mucosal infections are treated topically with nystatin or imidazoles.', 'admin', 'published', 6, true, '[["systemic mycoses", "systemic infections", "deep mycoses", "systemic drugs"], ["amphotericin b", "flucytosine", "fluconazole", "itraconazole", "voriconazole", "caspofungin"], ["oral for superficial", "oral for mucocutaneous", "systemic for superficial", "dermatophytosis"], ["griseofulvin", "terbinafine", "ketoconazole"], ["topical"], ["nystatin", "clotrimazole", "miconazole"]]'::jsonb, 'saq p.007 Q4, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-b5a5297107', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'saq', 'Give the pharmacological (chemical) classification of antimalarial drugs with an example in each class.', '[]'::jsonb, '4-aminoquinolines: chloroquine, amodiaquine, piperaquine; 8-aminoquinolines: primaquine, tafenoquine; quinoline methanols (cinchona alkaloids): quinine, quinidine, mefloquine; phenanthrene methanols/aryl amino alcohols: halofantrine, lumefantrine; artemisinins (sesquiterpene lactones): artemether, artesunate, dihydroartemisinin; biguanides: proguanil; diaminopyrimidines: pyrimethamine; sulfonamides and sulfones: sulfadoxine, dapsone; naphthoquinones: atovaquone; antibiotics: doxycycline, clindamycin.', '[]'::jsonb, 'Antimalarials fall into chemical families that also predict their action: quinoline derivatives interfere with haem detoxification, artemisinins generate free radicals, antifolates (proguanil, pyrimethamine, sulfadoxine) block folate synthesis, atovaquone blocks mitochondrial electron transport, and antibiotics such as doxycycline inhibit parasite protein synthesis.', 'admin', 'published', 10, true, '[["4-aminoquinoline", "4 aminoquinolines", "chloroquine", "amodiaquine"], ["8-aminoquinoline", "8 aminoquinolines", "primaquine", "tafenoquine"], ["quinoline methanol", "cinchona alkaloids", "quinine", "mefloquine"], ["phenanthrene methanol", "halofantrine", "lumefantrine"], ["artemisinin", "sesquiterpene lactone", "artemether", "artesunate"], ["biguanide", "proguanil"], ["diaminopyrimidine", "pyrimethamine"], ["sulfonamide", "sulfone", "sulfadoxine", "dapsone"], ["naphthoquinone", "atovaquone"], ["antibiotics", "doxycycline", "clindamycin", "tetracycline"]]'::jsonb, 'saq p.009 Q5, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-68346e4902', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List 5 adverse effects of chlorthalidone.', '[]'::jsonb, 'Any 5 of: hypokalaemia; hyponatraemia; hypomagnesaemia; hypercalcaemia; hyperuricaemia (gout); hyperglycaemia; hyperlipidaemia; hypochloraemic metabolic alkalosis; dehydration/postural hypotension; erectile dysfunction; hypersensitivity (sulfonamide), photosensitivity.', '[]'::jsonb, 'Chlorthalidone is a long-acting thiazide-like diuretic that blocks the Na-Cl cotransporter in the distal tubule. More sodium reaching the collecting duct causes potassium and hydrogen ion loss; urate and calcium are retained, and glucose and lipid levels rise. Its long half-life makes hypokalaemia and hyponatraemia more likely than with hydrochlorothiazide.', 'admin', 'published', 5, true, '[["hypokalaemia", "hypokalemia", "low potassium"], ["hyponatraemia", "hyponatremia", "low sodium"], ["hyperuricaemia", "hyperuricemia", "gout"], ["hyperglycaemia", "hyperglycemia", "glucose intolerance"], ["hyperlipidaemia", "hyperlipidemia", "raised cholesterol"], ["hypercalcaemia", "hypercalcemia"], ["hypomagnesaemia", "hypomagnesemia"], ["metabolic alkalosis", "alkalosis"], ["hypotension", "dehydration", "hypovolaemia"], ["erectile dysfunction", "impotence"], ["hypersensitivity", "photosensitivity", "rash"]]'::jsonb, 'saq p.010, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-90764b9420', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'saq', 'List three examples of drugs, other than adrenergic agonists, used in asthma prophylaxis.', '[]'::jsonb, 'Any 3 of: inhaled corticosteroids (beclometasone, budesonide, fluticasone); leukotriene receptor antagonists (montelukast, zafirlukast); mast cell stabilisers (sodium cromoglicate, nedocromil); theophylline; tiotropium; omalizumab; zileuton.', '[]'::jsonb, 'Prophylactic (controller) drugs reduce airway inflammation or prevent mediator release rather than relieve an attack. Inhaled corticosteroids are the mainstay; leukotriene antagonists, cromones, slow-release theophylline, tiotropium and anti-IgE antibody are add-ons or alternatives.', 'admin', 'published', 3, true, '[["beclometasone", "beclomethasone", "budesonide", "fluticasone", "inhaled corticosteroid"], ["montelukast", "zafirlukast", "zileuton"], ["cromoglicate", "cromolyn", "nedocromil"], ["theophylline", "aminophylline"], ["tiotropium", "ipratropium"], ["omalizumab"]]'::jsonb, 'saq p.011, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-d79bbe594d', 'pharm-intravenous-fluids', 'saq', 'Give two examples of plasma expanders other than normal saline.', '[]'::jsonb, 'Any 2 of: dextran (40 or 70); hydroxyethyl starch (hetastarch); gelatin solutions (polygeline/Haemaccel, succinylated gelatin/Gelofusine); human albumin; Ringer''s lactate (Hartmann''s solution).', '[]'::jsonb, 'Plasma expanders restore circulating volume. Colloids (dextrans, starches, gelatins, albumin) are large molecules that stay in the vessels and hold water by oncotic pressure, so they expand plasma more per litre than crystalloids such as Ringer''s lactate, which distribute through the whole extracellular space.', 'admin', 'published', 2, true, '[["dextran", "dextran 40", "dextran 70"], ["hydroxyethyl starch", "hetastarch", "starch"], ["gelatin", "haemaccel", "gelofusine", "polygeline"], ["albumin", "human albumin"], ["ringer''s lactate", "ringers lactate", "hartmann''s", "hartmanns"]]'::jsonb, 'saq p.012, MBChB EOY 2021/2022. Strictly, plasma expanders are colloids; Ringer''s lactate is accepted because the question itself counts normal saline.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-93105bcdf8', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Classify insulin preparations, giving one example in each class.', '[]'::jsonb, 'Rapid-acting: lispro, aspart, glulisine; short-acting: regular (soluble) insulin; intermediate-acting: NPH (isophane) insulin; long-acting: glargine, detemir, degludec. (Also premixed/biphasic, e.g. 70/30 NPH/regular.)', '[]'::jsonb, 'Insulins are classified by onset and duration. Rapid analogues stay monomeric and act within 15 minutes for meals; regular insulin forms hexamers and is slower; NPH is complexed with protamine for intermediate action; glargine, detemir and degludec give a flat basal level.', 'admin', 'published', 4, true, '[["rapid acting", "ultra short acting", "lispro", "aspart", "glulisine"], ["short acting", "regular", "soluble"], ["intermediate acting", "nph", "isophane"], ["long acting", "glargine", "detemir", "degludec"]]'::jsonb, 'saq p.013, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-a4364f1397', 'pharm-sedative-hypnotic-drugs', 'saq', 'List four clinical uses of benzodiazepines.', '[]'::jsonb, 'Any 4 of: anxiety and panic disorders; insomnia; seizures/status epilepticus; skeletal muscle spasm and spasticity; alcohol withdrawal; premedication and procedural sedation; induction of anaesthesia.', '[]'::jsonb, 'Benzodiazepines enhance GABA-A mediated inhibition, giving anxiolytic, hypnotic, anticonvulsant, muscle relaxant and amnesic effects, each of which has a clinical use. Their cross-tolerance with alcohol makes long-acting agents such as diazepam and chlordiazepoxide the standard treatment of alcohol withdrawal.', 'admin', 'published', 4, true, '[["anxiety", "anxiolytic", "panic"], ["insomnia", "hypnotic", "sleep"], ["seizures", "status epilepticus", "anticonvulsant", "epilepsy"], ["muscle spasm", "muscle relaxant", "spasticity"], ["alcohol withdrawal"], ["premedication", "sedation", "preanaesthetic"], ["anaesthesia induction", "induction"]]'::jsonb, 'saq p.014, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-cc43085245', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'saq', 'Give four examples of mesalamine (5-aminosalicylate) compounds useful in the management of inflammatory bowel disease.', '[]'::jsonb, 'Sulfasalazine; olsalazine; balsalazide; mesalazine (mesalamine) formulations, e.g. Pentasa, Asacol.', '[]'::jsonb, '5-aminosalicylic acid acts topically on the gut mucosa. The azo compounds sulfasalazine, olsalazine and balsalazide are split by colonic bacteria to release 5-ASA in the colon, while Pentasa and Asacol are delayed-release or pH-dependent mesalazine formulations.', 'admin', 'published', 4, true, '[["sulfasalazine", "sulphasalazine"], ["olsalazine"], ["balsalazide"], ["mesalazine", "mesalamine", "pentasa", "asacol"]]'::jsonb, 'saq p.015, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-b067c2d509', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'Give 5 adverse effects of opioids involving different systems of the body.', '[]'::jsonb, 'Any 5 of: respiratory - respiratory depression; GIT - constipation, nausea and vomiting, biliary spasm; CNS - sedation, euphoria/dysphoria, tolerance and dependence; eye - miosis; CVS - hypotension, bradycardia; urinary - urinary retention; skin - pruritus, flushing (histamine release).', '[]'::jsonb, 'Mu receptor activation depresses the brainstem response to carbon dioxide, slows gut motility, stimulates the chemoreceptor trigger zone and constricts the pupil. Histamine release causes itching and hypotension, and raised sphincter tone causes urinary retention and biliary spasm. Tolerance does not develop to miosis or constipation.', 'admin', 'published', 5, true, '[["respiratory depression"], ["constipation"], ["nausea", "vomiting"], ["sedation", "drowsiness", "dysphoria", "euphoria"], ["miosis", "pinpoint pupils"], ["hypotension", "bradycardia"], ["urinary retention"], ["pruritus", "itching", "histamine release"], ["dependence", "tolerance", "addiction"], ["biliary spasm"]]'::jsonb, 'saq p.016, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-031e25b53f', 'pharm-calcium-vitamin-d-and-analogues', 'saq', 'List three calcium preparations that can be administered by the intravenous route.', '[]'::jsonb, 'Calcium gluconate; calcium chloride; calcium gluceptate.', '[]'::jsonb, 'Calcium gluconate is preferred intravenously because it is least irritant to veins; calcium chloride contains about three times more elemental calcium per ml and is more irritant, so it is reserved for central lines and emergencies. Carbonate, citrate and lactate salts are oral only.', 'admin', 'published', 3, true, '[["calcium gluconate", "gluconate"], ["calcium chloride", "chloride"], ["calcium gluceptate", "gluceptate"]]'::jsonb, 'saq p.017, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-6c1677d327', 'pharm-antimetabolites', 'saq', 'List three mechanisms of resistance to methotrexate.', '[]'::jsonb, 'Any 3 of: decreased drug transport into the cell (reduced folate carrier); decreased polyglutamate formation; increased synthesis of dihydrofolate reductase through gene amplification; altered dihydrofolate reductase with reduced affinity for methotrexate; increased efflux by drug transporters (P-glycoprotein/MRP).', '[]'::jsonb, 'Methotrexate enters cells on the reduced folate carrier, is trapped as polyglutamates and inhibits dihydrofolate reductase. Tumour cells escape by taking up less drug, polyglutamating it less, amplifying the DHFR gene, producing a DHFR that binds the drug poorly, or pumping the drug out.', 'admin', 'published', 3, true, '[["decreased transport", "reduced uptake", "reduced folate carrier", "decreased entry"], ["decreased polyglutamation", "polyglutamate"], ["increased dhfr", "gene amplification", "more dihydrofolate reductase"], ["altered dhfr", "reduced affinity", "mutated dhfr"], ["increased efflux", "p-glycoprotein", "drug efflux"]]'::jsonb, 'saq p.018, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympatholytics-251c5dd290', 'pharm-sympatholytics', 'saq', 'Metyrosine reduces catecholamine synthesis by inhibiting which enzyme?', '[]'::jsonb, 'Tyrosine hydroxylase', '["tyrosine hydroxylase enzyme", "tyrosine 3-monooxygenase", "TH"]'::jsonb, 'Tyrosine hydroxylase converts tyrosine to DOPA and is the rate-limiting step in catecholamine synthesis. Metyrosine (alpha-methyltyrosine) competitively inhibits it, lowering noradrenaline and adrenaline production, which is why it is used in phaeochromocytoma.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.019 (i), MBChB EOY 2021/2022. Reworded from ''How does metyrosine affect the autonomic nervous system?'' so one answer fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-64c593697d', 'pharm-adrenergic-neurone-blocking-drugs', 'saq', 'Reserpine depletes noradrenaline stores in adrenergic nerve endings by blocking which transporter?', '[]'::jsonb, 'Vesicular monoamine transporter', '["VMAT", "VMAT2", "VMAT-2", "vesicular monoamine transporter 2", "vesicular amine transporter", "vesicular monoamine transporters"]'::jsonb, 'Reserpine irreversibly blocks the vesicular monoamine transporter, so noradrenaline, dopamine and serotonin cannot be stored in vesicles and are destroyed by monoamine oxidase in the cytoplasm. The resulting depletion lowers blood pressure and can cause depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.019 (ii), MBChB EOY 2021/2022. Reworded from ''How does reserpine affect the autonomic nervous system?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-a84914287e', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Hemicholinium reduces acetylcholine synthesis by blocking the uptake of which substance into the cholinergic nerve terminal?', '[]'::jsonb, 'Choline', '["choline uptake", "choline transport"]'::jsonb, 'Uptake of choline by the sodium-dependent high-affinity choline transporter is the rate-limiting step in acetylcholine synthesis. Hemicholinium blocks this transporter, so the terminal runs out of acetylcholine during sustained activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.019 (iii), MBChB EOY 2021/2022. Reworded from ''How does hemicholinium affect the autonomic nervous system?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-25b417bc2d', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Vesamicol blocks the transport of which neurotransmitter into its storage vesicles?', '[]'::jsonb, 'Acetylcholine', '["ACh", "acetyl choline"]'::jsonb, 'Vesamicol inhibits the vesicle-associated transporter (VAT) that loads newly synthesised acetylcholine into synaptic vesicles. Synthesis continues but release fails because the vesicles are empty. Compare botulinum toxin, which blocks release of filled vesicles.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.019 (iv), MBChB EOY 2021/2022. Reworded from ''How does vesamicol affect the autonomic nervous system?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-731d9b75f5', 'pharm-biotransformation', 'saq', 'List three factors that affect drug metabolism and briefly explain their effects.', '[]'::jsonb, 'Any 3 of: age - neonates and the elderly have reduced enzyme activity, so slower metabolism; genetic polymorphism - e.g. slow and fast acetylators, CYP2D6 poor metabolisers; enzyme induction (rifampicin, phenytoin, smoking) - faster metabolism and reduced effect; enzyme inhibition (cimetidine, erythromycin) - slower metabolism and toxicity; liver disease or reduced hepatic blood flow - reduced metabolism; diet/nutrition and sex/hormones also alter enzyme activity.', '[]'::jsonb, 'The rate of biotransformation depends on how much active enzyme the liver has and how much drug reaches it. Immature or ageing livers, inherited enzyme variants, other drugs that induce or inhibit cytochrome P450, and liver disease all change clearance and therefore the dose required.', 'admin', 'published', 3, true, '[["age", "neonates", "elderly"], ["genetic", "polymorphism", "acetylator", "pharmacogenetics"], ["enzyme induction", "inducers", "rifampicin"], ["enzyme inhibition", "inhibitors", "cimetidine"], ["liver disease", "hepatic disease", "liver blood flow"], ["diet", "nutrition", "smoking", "alcohol"], ["sex", "gender", "hormones", "pregnancy"]]'::jsonb, 'saq p.020, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-610eef16a1', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'Write down five advantages of antibacterial drug combination therapy.', '[]'::jsonb, '1. Synergism (greater killing, e.g. penicillin + aminoglycoside, co-trimoxazole); 2. broader spectrum for empirical treatment of severe infection of unknown cause; 3. treatment of mixed (polymicrobial) infections; 4. prevents or delays emergence of resistance (e.g. tuberculosis); 5. allows lower doses of each drug, reducing toxicity.', '[]'::jsonb, 'Combinations are justified when two drugs kill better together than apart, when the organism is unknown and the patient is critically ill, when several organisms are present, when resistance would otherwise emerge quickly as in tuberculosis, or when lower doses of each drug reduce toxicity.', 'admin', 'published', 5, true, '[["synergism", "synergy", "synergistic"], ["broad spectrum", "broaden spectrum", "empirical therapy", "unknown organism"], ["mixed infections", "polymicrobial"], ["prevent resistance", "delay resistance", "reduce resistance"], ["reduce toxicity", "lower doses", "reduce dose"]]'::jsonb, 'saq p.021 Q4, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-55d59f7c12', 'pharm-biologic-dmards', 'saq', 'List five classes of biologic disease-modifying antirheumatic drugs and give one example in each class.', '[]'::jsonb, 'TNF-alpha inhibitors: infliximab, etanercept, adalimumab, golimumab, certolizumab; IL-6 receptor antagonists: tocilizumab, sarilumab; IL-1 receptor antagonist: anakinra; T-cell costimulation blocker: abatacept; B-cell depleting anti-CD20 antibody: rituximab. (Also IL-17 inhibitors, e.g. secukinumab.)', '[]'::jsonb, 'Biologic DMARDs are proteins aimed at one cytokine or cell: TNF-alpha, the IL-6 receptor, the IL-1 receptor, the CD80/86 costimulatory signal to T cells, or CD20 on B cells. Tofacitinib and other JAK inhibitors are oral small molecules, so they are targeted synthetic rather than biologic DMARDs.', 'admin', 'published', 5, true, '[["tnf inhibitor", "anti-tnf", "infliximab", "etanercept", "adalimumab"], ["il-6", "tocilizumab", "sarilumab"], ["il-1", "anakinra"], ["t cell costimulation", "abatacept", "ctla-4"], ["anti-cd20", "b cell depletion", "rituximab"], ["il-17", "secukinumab"]]'::jsonb, 'saq p.022, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-d5967f73e2', 'pharm-lipid-lowering-agents', 'saq', 'Give 4 classes of lipid-lowering drugs with an example of a drug in each class.', '[]'::jsonb, 'Any 4 of: HMG-CoA reductase inhibitors (statins): atorvastatin, simvastatin, rosuvastatin; fibrates: gemfibrozil, fenofibrate; bile acid-binding resins: cholestyramine, colestipol; cholesterol absorption inhibitor: ezetimibe; nicotinic acid (niacin); PCSK9 inhibitors: evolocumab, alirocumab; omega-3 fatty acids.', '[]'::jsonb, 'Statins block cholesterol synthesis and upregulate LDL receptors; fibrates activate PPAR-alpha to lower triglycerides; resins bind bile acids in the gut; ezetimibe blocks the NPC1L1 cholesterol transporter; niacin reduces VLDL secretion and raises HDL; PCSK9 antibodies prevent LDL receptor degradation.', 'admin', 'published', 8, true, '[["statins", "hmg-coa reductase inhibitors"], ["atorvastatin", "simvastatin", "rosuvastatin", "lovastatin", "pravastatin"], ["fibrates", "fibric acid derivatives"], ["gemfibrozil", "fenofibrate", "bezafibrate"], ["bile acid resins", "bile acid sequestrants", "resins"], ["cholestyramine", "colestipol", "colesevelam"], ["cholesterol absorption inhibitor", "ezetimibe"], ["niacin", "nicotinic acid"], ["pcsk9 inhibitors", "evolocumab", "alirocumab"]]'::jsonb, 'saq p.023, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-hormonal-anticancer-drugs-199dbb8652', 'pharm-hormonal-anticancer-drugs', 'saq', 'List 4 hormonal anticancer drugs.', '[]'::jsonb, 'Any 4 of: tamoxifen; fulvestrant; anastrozole, letrozole, exemestane; flutamide, bicalutamide; leuprolide, goserelin; prednisone/dexamethasone; megestrol acetate; abiraterone; octreotide.', '[]'::jsonb, 'Hormone-dependent tumours are treated by removing the hormonal drive: oestrogen receptor blockers and aromatase inhibitors in breast cancer, antiandrogens and GnRH agonists in prostate cancer, progestins in endometrial cancer and glucocorticoids, which kill lymphoid cells, in leukaemia and lymphoma.', 'admin', 'published', 4, true, '[["tamoxifen", "raloxifene", "toremifene", "fulvestrant"], ["anastrozole", "letrozole", "exemestane", "aromatase inhibitor"], ["flutamide", "bicalutamide", "enzalutamide", "abiraterone"], ["leuprolide", "goserelin", "leuprorelin", "gnrh agonist"], ["prednisone", "prednisolone", "dexamethasone"], ["megestrol", "medroxyprogesterone"], ["octreotide"]]'::jsonb, 'saq p.024, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-b4941f2afe', 'pharm-serotonin-receptors-and-agonists', 'saq', 'List 4 adverse effects of sumatriptan.', '[]'::jsonb, 'Any 4 of: chest tightness/pressure or pain; coronary vasospasm (angina, myocardial infarction); tingling/paraesthesiae; flushing and sensation of warmth; dizziness; drowsiness/fatigue; transient rise in blood pressure; nausea; injection-site reaction.', '[]'::jsonb, 'Sumatriptan is a 5-HT1B/1D agonist that constricts cranial vessels. The same receptors on coronary arteries explain chest tightness and rare vasospasm, so it is contraindicated in ischaemic heart disease. Tingling, flushing, heaviness and dizziness are the common ''triptan sensations''.', 'admin', 'published', 4, true, '[["chest tightness", "chest pain", "chest pressure"], ["coronary vasospasm", "angina", "myocardial infarction"], ["paraesthesia", "tingling", "numbness"], ["flushing", "warmth", "heat sensation"], ["dizziness"], ["drowsiness", "fatigue", "weakness"], ["hypertension", "raised blood pressure"], ["nausea", "vomiting"], ["injection site reaction"]]'::jsonb, 'saq p.025, MBChB EOY 2021/2022') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-9be9b9ceca', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'saq', 'List 3 drugs of different chemical groups used for the treatment of neuropathic pain and indicate the group to which each belongs.', '[]'::jsonb, 'Any 3 of: amitriptyline (or nortriptyline) - tricyclic antidepressant; duloxetine (or venlafaxine) - serotonin-noradrenaline reuptake inhibitor; gabapentin or pregabalin - GABA analogue (gabapentinoid); carbamazepine - iminostilbene anticonvulsant; lidocaine - amide local anaesthetic; tramadol - opioid; capsaicin - vanilloid (TRPV1 agonist).', '[]'::jsonb, 'Neuropathic pain responds poorly to NSAIDs. First-line drugs damp abnormal neuronal firing: tricyclics and SNRIs strengthen descending noradrenergic inhibition, gabapentinoids bind the alpha-2-delta subunit of calcium channels, and carbamazepine blocks sodium channels (drug of choice in trigeminal neuralgia).', 'admin', 'published', 6, true, '[["amitriptyline", "nortriptyline", "imipramine"], ["tricyclic antidepressant", "tca", "tricyclic"], ["gabapentin", "pregabalin"], ["gaba analogue", "gabapentinoid", "anticonvulsant"], ["duloxetine", "venlafaxine"], ["snri"], ["carbamazepine", "iminostilbene"], ["lidocaine", "lignocaine", "local anaesthetic"], ["tramadol", "opioid"], ["capsaicin"]]'::jsonb, 'saq p.028 Q1a, BDS EOY 2021/2022 Paper 2. Parts (i) and (ii) merged because (ii) depends on (i). No dedicated neuropathic pain topic; closest used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-adaa71e151', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'saq', 'Give 3 agents used for the treatment of haemophilia A.', '[]'::jsonb, 'Any 3 of: factor VIII concentrate (recombinant or plasma-derived); cryoprecipitate; desmopressin (DDAVP) in mild disease; tranexamic acid (or aminocaproic acid) as adjunct; emicizumab; fresh frozen plasma if nothing else is available.', '[]'::jsonb, 'Haemophilia A is factor VIII deficiency. Replacement with factor VIII concentrate (or cryoprecipitate, which is rich in it) is the mainstay; desmopressin releases stored factor VIII and von Willebrand factor in mild cases; antifibrinolytics stabilise clots, especially for dental procedures.', 'admin', 'published', 3, true, '[["factor viii", "factor 8", "factor viii concentrate"], ["cryoprecipitate"], ["desmopressin", "ddavp"], ["tranexamic acid", "aminocaproic acid", "antifibrinolytic"], ["emicizumab"], ["fresh frozen plasma", "ffp"]]'::jsonb, 'saq p.028 Q1b, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-7e9be5e7ef', 'pharm-antihelminthics-ii-ectoparasites', 'saq', 'Explain the mechanism of action of praziquantel.', '[]'::jsonb, 'Praziquantel increases the permeability of the worm''s cell membranes to calcium; the calcium influx causes strong muscular contraction followed by spastic paralysis, so the worms lose their hold and are dislodged. It also causes vacuolisation and damage of the tegument, exposing parasite antigens to host immune attack, leading to death of the worm.', '[]'::jsonb, 'Praziquantel acts on schistosome and tapeworm calcium channels. Rapid calcium entry tetanically contracts the worm''s muscle and blisters its tegument; paralysed flukes are swept to the liver and the damaged surface lets host antibodies and phagocytes destroy them.', 'admin', 'published', 4, true, '[["calcium permeability", "calcium influx", "increases calcium", "calcium entry"], ["contraction", "spastic paralysis", "paralysis", "muscle contraction"], ["tegument damage", "vacuolisation", "vacuolization", "tegument"], ["dislodged", "detach", "lose grip"], ["immune attack", "antigens exposed", "host immune"]]'::jsonb, 'saq p.028 Q1c(i), BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-402b07ea67', 'pharm-antihelminthics-ii-ectoparasites', 'saq', 'Give 3 clinical indications of praziquantel.', '[]'::jsonb, 'Any 3 of: schistosomiasis (all species); taeniasis (Taenia saginata, T. solium); neurocysticercosis; diphyllobothriasis; Hymenolepis nana infection; clonorchiasis/opisthorchiasis (liver flukes); paragonimiasis (lung fluke).', '[]'::jsonb, 'Praziquantel is the drug of choice for all Schistosoma species and for most other trematodes and cestodes. The exception is Fasciola hepatica, which responds to triclabendazole. In neurocysticercosis it is given with corticosteroids to limit inflammation around dying cysts.', 'admin', 'published', 3, true, '[["schistosomiasis", "bilharzia", "schistosoma"], ["taeniasis", "tapeworm", "taenia"], ["neurocysticercosis", "cysticercosis"], ["diphyllobothriasis", "fish tapeworm", "diphyllobothrium"], ["hymenolepis", "dwarf tapeworm"], ["clonorchiasis", "liver fluke", "opisthorchiasis"], ["paragonimiasis", "lung fluke"]]'::jsonb, 'saq p.028 Q1c(ii), BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-6a339e9bf2', 'pharm-adrenoceptor-blockers', 'saq', 'Give 4 adverse effects of propranolol.', '[]'::jsonb, 'Any 4 of: bradycardia; heart block; hypotension; worsening of acute heart failure; bronchospasm; cold extremities; fatigue; masking of hypoglycaemia and delayed recovery from it; sleep disturbance/nightmares, depression; erectile dysfunction; rebound angina on sudden withdrawal.', '[]'::jsonb, 'Propranolol blocks beta-1 and beta-2 receptors. Beta-1 block slows the heart and AV conduction; beta-2 block narrows the bronchi and peripheral vessels and blunts the adrenergic warning signs of, and recovery from, hypoglycaemia. Being lipid soluble it enters the brain, causing vivid dreams and fatigue.', 'admin', 'published', 4, true, '[["bradycardia", "slow heart rate"], ["heart block", "av block"], ["hypotension", "low blood pressure"], ["bronchospasm", "bronchoconstriction", "asthma"], ["cold extremities", "cold hands"], ["fatigue", "tiredness", "weakness"], ["masks hypoglycaemia", "hypoglycemia", "hypoglycaemia"], ["nightmares", "sleep disturbance", "depression", "insomnia"], ["erectile dysfunction", "impotence"], ["heart failure"]]'::jsonb, 'saq p.028 Q1d, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-75585cbbfa', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List 3 signs or symptoms of hypoglycaemia.', '[]'::jsonb, 'Any 3 of: sweating; tremor; palpitations/tachycardia; hunger; anxiety; dizziness; headache; confusion or abnormal behaviour; blurred vision; weakness; convulsions; loss of consciousness/coma.', '[]'::jsonb, 'Falling glucose first triggers adrenergic symptoms (sweating, tremor, palpitations, hunger), then neuroglycopenic ones as the brain is starved (confusion, convulsions, coma). Beta-blockers hide the adrenergic warnings except sweating, which is cholinergic.', 'admin', 'published', 3, true, '[["sweating", "diaphoresis"], ["tremor", "shaking"], ["palpitations", "tachycardia"], ["hunger"], ["anxiety", "irritability"], ["dizziness", "headache"], ["confusion", "abnormal behaviour"], ["weakness", "fatigue"], ["convulsions", "seizures"], ["coma", "loss of consciousness", "unconsciousness"], ["blurred vision"]]'::jsonb, 'saq p.030 Q2a, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-a1ba2bbd08', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List 3 ways in which hypoglycaemia caused by antidiabetic agents can be treated.', '[]'::jsonb, '1. Oral glucose or a sugary drink/food if the patient is conscious and can swallow; 2. intravenous dextrose (e.g. 50 ml of 50% or 10% dextrose) if unconscious; 3. glucagon 1 mg intramuscularly or subcutaneously when there is no intravenous access. (Octreotide for sulfonylurea-induced hypoglycaemia; withhold or reduce the offending drug.)', '[]'::jsonb, 'Conscious patients take fast-acting carbohydrate by mouth; unconscious patients need intravenous dextrose, or glucagon, which mobilises liver glycogen. Sulfonylurea hypoglycaemia tends to recur because the drugs are long acting, so a dextrose infusion or octreotide (which blocks insulin release) may be needed.', 'admin', 'published', 3, true, '[["oral glucose", "sugary drink", "sugar", "sweets", "glucose tablets"], ["iv dextrose", "intravenous glucose", "dextrose", "50% dextrose"], ["glucagon"], ["octreotide"], ["stop the drug", "withhold drug", "reduce dose"]]'::jsonb, 'saq p.030 Q2b, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-98ff41dfc2', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'saq', 'Classify general anaesthetics and give 2 examples in each class.', '[]'::jsonb, '1. Inhalational anaesthetics: (a) gases - nitrous oxide, xenon; (b) volatile liquids - halothane, isoflurane, sevoflurane, desflurane, enflurane. 2. Intravenous anaesthetics: thiopental (barbiturate), propofol, ketamine, etomidate, midazolam (benzodiazepine), fentanyl (opioid).', '[]'::jsonb, 'General anaesthetics are divided by route. Inhalational agents (a gas such as nitrous oxide or halogenated volatile liquids) are mainly used for maintenance because depth is easily adjusted; intravenous agents such as propofol, thiopental, ketamine and etomidate give rapid induction.', 'admin', 'published', 6, true, '[["inhalational", "inhaled"], ["gases", "nitrous oxide", "xenon"], ["volatile liquids", "halothane", "isoflurane", "sevoflurane", "desflurane"], ["intravenous", "iv anaesthetics"], ["thiopental", "thiopentone", "propofol"], ["ketamine", "etomidate", "midazolam", "fentanyl"]]'::jsonb, 'saq p.030 Q2c, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-6cf19da3c1', 'pharm-drug-interactions', 'saq', 'Give 2 drugs that impair the absorption of tetracyclines.', '[]'::jsonb, 'Any 2 of: antacids containing aluminium, magnesium or calcium; iron salts (ferrous sulphate); calcium supplements; zinc salts; bismuth subsalicylate; sucralfate. (Milk and dairy products do the same.)', '[]'::jsonb, 'Tetracyclines chelate divalent and trivalent cations (calcium, magnesium, aluminium, iron, zinc, bismuth) to form insoluble complexes that are not absorbed. Doses should be separated by two to three hours from antacids, iron and dairy products.', 'admin', 'published', 2, true, '[["antacids", "aluminium hydroxide", "magnesium hydroxide", "magnesium trisilicate"], ["iron", "ferrous sulphate", "ferrous sulfate", "iron salts"], ["calcium", "calcium carbonate", "calcium supplements"], ["zinc"], ["bismuth"], ["sucralfate"]]'::jsonb, 'saq p.030 Q2d, BDS EOY 2021/2022 Paper 2. No tetracycline topic in the list; filed under drug interactions.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-a58085b6bb', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'Give 3 contraindications for the use of tetracyclines.', '[]'::jsonb, 'Any 3 of: pregnancy; breastfeeding; children under 8 years (BNF: under 12); renal impairment (except doxycycline); severe hepatic disease; known hypersensitivity to tetracyclines.', '[]'::jsonb, 'Tetracyclines bind calcium in growing bones and teeth, causing permanent tooth discolouration, enamel hypoplasia and slowed bone growth, so they are avoided in pregnancy, lactation and young children. Most accumulate in renal failure and high doses can cause fatty liver.', 'admin', 'published', 3, true, '[["pregnancy", "pregnant"], ["breastfeeding", "lactation"], ["children", "under 8", "under 12", "paediatric"], ["renal impairment", "renal failure", "kidney disease"], ["liver disease", "hepatic impairment", "hepatic disease"], ["hypersensitivity", "allergy"]]'::jsonb, 'saq p.030 Q2e, BDS EOY 2021/2022 Paper 2. No tetracycline topic in the list; closest used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-d9a94964aa', 'pharm-prostaglandins', 'saq', 'List 3 prostaglandin analogues used for the treatment of glaucoma.', '[]'::jsonb, 'Any 3 of: latanoprost; travoprost; bimatoprost; tafluprost; unoprostone.', '[]'::jsonb, 'These PGF2-alpha analogues lower intraocular pressure by increasing uveoscleral outflow of aqueous humour, and are first-line once-daily drops in open-angle glaucoma. Typical adverse effects are brown iris pigmentation and longer, darker eyelashes.', 'admin', 'published', 3, true, '[["latanoprost"], ["travoprost"], ["bimatoprost"], ["tafluprost"], ["unoprostone"]]'::jsonb, 'saq p.030 Q2f, BDS EOY 2021/2022 Paper 2. Paper says ''acute angle glaucoma''; these drugs are used in (chronic) open-angle glaucoma, so the text says ''glaucoma''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-7f166957fb', 'pharm-oestrogens-progestins-oral-contraceptives', 'saq', 'List three uses of synthetic oestrogens.', '[]'::jsonb, 'Any 3 of: contraception (combined oral contraceptive); hormone replacement therapy for menopausal symptoms; prevention of postmenopausal osteoporosis; primary hypogonadism/delayed puberty; dysfunctional uterine bleeding and dysmenorrhoea; acne and hirsutism; palliation of prostate cancer.', '[]'::jsonb, 'Synthetic oestrogens such as ethinylestradiol suppress FSH and ovulation in combined contraceptives, replace deficient hormone in hypogonadism and menopause (relieving vasomotor symptoms and slowing bone loss), and regulate abnormal uterine bleeding.', 'admin', 'published', 3, true, '[["contraception", "oral contraceptive", "contraceptive"], ["hormone replacement", "hrt", "menopausal symptoms", "menopause"], ["osteoporosis"], ["hypogonadism", "delayed puberty", "ovarian failure"], ["dysfunctional uterine bleeding", "dysmenorrhoea", "menstrual disorders"], ["acne", "hirsutism"], ["prostate cancer"]]'::jsonb, 'saq p.032 Q3a, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-47b2d0efe8', 'pharm-biotransformation', 'saq', 'Give four examples of phase II metabolic reactions.', '[]'::jsonb, 'Any 4 of: glucuronidation; sulphation; acetylation; methylation; glutathione conjugation; glycine (amino acid) conjugation.', '[]'::jsonb, 'Phase II reactions attach an endogenous group to the drug or its phase I metabolite, usually making it inactive, more water soluble and easier to excrete. Phase I reactions (oxidation, reduction, hydrolysis) instead introduce or unmask a functional group.', 'admin', 'published', 4, true, '[["glucuronidation", "glucuronide conjugation"], ["sulphation", "sulfation", "sulphate conjugation"], ["acetylation"], ["methylation"], ["glutathione conjugation", "glutathione"], ["glycine conjugation", "amino acid conjugation"]]'::jsonb, 'saq p.032 Q3b, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-15315afdd3', 'pharm-oestrogens-progestins-oral-contraceptives', 'saq', 'List three contraindications of oestrogen-containing oral contraceptives.', '[]'::jsonb, 'Any 3 of: history of venous thromboembolism or thrombophlebitis; cerebrovascular or coronary artery disease; breast cancer or other oestrogen-dependent tumour; undiagnosed vaginal bleeding; pregnancy; active liver disease or liver tumour; smoker aged over 35; migraine with aura; uncontrolled hypertension.', '[]'::jsonb, 'Oestrogen increases clotting factor synthesis, so anything that already raises the risk of venous or arterial thrombosis is a contraindication. It also stimulates oestrogen-dependent tumours and is cleared by the liver.', 'admin', 'published', 3, true, '[["thromboembolism", "dvt", "thrombosis", "thrombophlebitis"], ["stroke", "cerebrovascular disease", "coronary artery disease", "ischaemic heart disease"], ["breast cancer", "oestrogen dependent tumour", "estrogen dependent tumor"], ["undiagnosed vaginal bleeding", "vaginal bleeding"], ["pregnancy"], ["liver disease", "liver tumour"], ["smoker over 35", "smoking"], ["migraine with aura"], ["hypertension"]]'::jsonb, 'saq p.032 Q3c, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiamine-riboflavin-nicotinic-acid-1208a44158', 'pharm-thiamine-riboflavin-nicotinic-acid', 'saq', 'List four water-soluble and four fat-soluble vitamins.', '[]'::jsonb, 'Fat-soluble: vitamins A, D, E and K. Water-soluble (any 4): vitamin C (ascorbic acid), B1 (thiamine), B2 (riboflavin), B3 (niacin), B5 (pantothenic acid), B6 (pyridoxine), B7 (biotin), B9 (folic acid), B12 (cobalamin).', '[]'::jsonb, 'Vitamins A, D, E and K need bile and fat for absorption and are stored in liver and fat, so deficiency follows malabsorption and excess causes toxicity. The B group and vitamin C are water soluble, poorly stored (except B12) and excreted in urine.', 'admin', 'published', 4, true, '[["vitamin a", "retinol"], ["vitamin d", "calciferol"], ["vitamin e", "tocopherol"], ["vitamin k"], ["vitamin c", "ascorbic acid"], ["thiamine", "b1"], ["riboflavin", "b2"], ["niacin", "b3", "nicotinic acid"], ["pyridoxine", "b6"], ["cobalamin", "b12"], ["folic acid", "folate", "b9"], ["biotin", "pantothenic acid"]]'::jsonb, 'saq p.032 Q3d, BDS EOY 2021/2022 Paper 2. General vitamin question; closest vitamin topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-862cb40032', 'pharm-intravenous-anesthetic-agents', 'saq', 'Give two intravenous anaesthetics that are contraindicated in porphyria.', '[]'::jsonb, 'Thiopental (thiopentone) and methohexital, i.e. the barbiturates; etomidate is also regarded as unsafe.', '[]'::jsonb, 'Barbiturates induce ALA synthase, the rate-limiting enzyme of haem synthesis, increasing porphyrin precursors and precipitating an acute attack in acute intermittent or variegate porphyria. Propofol is considered safe and is the usual alternative.', 'admin', 'published', 2, true, '[["thiopental", "thiopentone", "barbiturates"], ["methohexital", "methohexitone"], ["etomidate"]]'::jsonb, 'saq p.032 Q3e, BDS EOY 2021/2022 Paper 2. Barbiturates are certain; etomidate is listed as unsafe/possibly porphyrinogenic by most sources.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-7a3ee9329d', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Name two drugs used for the treatment of trypanosomiasis with central nervous system involvement.', '[]'::jsonb, 'Any 2 of: melarsoprol; eflornithine (alone or with nifurtimox, NECT); fexinidazole.', '[]'::jsonb, 'Late-stage sleeping sickness needs drugs that cross the blood-brain barrier. Melarsoprol, an arsenical, works against both Trypanosoma brucei subspecies but can cause fatal encephalopathy; eflornithine (with nifurtimox) is safer but only for T. b. gambiense. Suramin and pentamidine do not enter the CNS and treat early disease only.', 'admin', 'published', 2, true, '[["melarsoprol"], ["eflornithine", "dfmo"], ["nifurtimox", "nect"], ["fexinidazole"]]'::jsonb, 'saq p.032 Q3e(2), BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiamine-riboflavin-nicotinic-acid-bf1d1f63e7', 'pharm-thiamine-riboflavin-nicotinic-acid', 'saq', 'What are the three cardinal signs of pellagra?', '[]'::jsonb, 'Dermatitis; diarrhoea; dementia (the three Ds).', '[]'::jsonb, 'Pellagra is niacin (vitamin B3) deficiency, seen with maize-based diets, alcoholism, isoniazid therapy and carcinoid syndrome. The photosensitive dermatitis affects sun-exposed skin (Casal''s necklace); untreated, the fourth D is death.', 'admin', 'published', 3, true, '[["dermatitis", "skin rash"], ["diarrhoea", "diarrhea"], ["dementia", "confusion"]]'::jsonb, 'saq p.035 Q4a, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-6574c00c16', 'pharm-anticoagulant-drugs', 'saq', 'Give 3 adverse effects of heparin.', '[]'::jsonb, 'Any 3 of: bleeding; heparin-induced thrombocytopenia (with thrombosis); osteoporosis with long-term use; hyperkalaemia (aldosterone suppression); hypersensitivity reactions; alopecia; raised liver transaminases.', '[]'::jsonb, 'Bleeding is the main risk and is reversed with protamine. Heparin-induced thrombocytopenia is immune: antibodies to the heparin-platelet factor 4 complex activate platelets, causing a falling platelet count with paradoxical thrombosis. Months of therapy cause osteoporosis.', 'admin', 'published', 3, true, '[["bleeding", "haemorrhage", "hemorrhage"], ["thrombocytopenia", "hit"], ["osteoporosis"], ["hyperkalaemia", "hyperkalemia"], ["hypersensitivity", "allergy"], ["alopecia", "hair loss"], ["raised transaminases", "elevated liver enzymes"]]'::jsonb, 'saq p.035 Q4b, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-d06e74f225', 'pharm-opioid-use-and-abuse', 'saq', 'List 4 signs of the opioid analgesic withdrawal syndrome.', '[]'::jsonb, 'Any 4 of: lacrimation; rhinorrhoea; yawning; sweating; piloerection (gooseflesh); dilated pupils; restlessness, anxiety and insomnia; muscle aches and cramps; abdominal cramps, vomiting and diarrhoea; tachycardia and raised blood pressure; drug craving.', '[]'::jsonb, 'Withdrawal is the mirror image of opioid effects: instead of miosis, constipation and sedation there is mydriasis, diarrhoea and agitation, with autonomic overactivity (lacrimation, rhinorrhoea, sweating, piloerection). It is very unpleasant but rarely life-threatening.', 'admin', 'published', 4, true, '[["lacrimation", "tearing"], ["rhinorrhoea", "rhinorrhea", "runny nose"], ["yawning"], ["sweating"], ["piloerection", "gooseflesh", "goose bumps"], ["mydriasis", "dilated pupils"], ["restlessness", "anxiety", "insomnia", "irritability"], ["muscle aches", "muscle cramps", "myalgia"], ["diarrhoea", "diarrhea", "vomiting", "abdominal cramps"], ["tachycardia", "hypertension"]]'::jsonb, 'saq p.035 Q4c, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-c685f39c0f', 'pharm-antihelminthics-i', 'saq', 'Give 4 clinical indications for albendazole.', '[]'::jsonb, 'Any 4 of: ascariasis; hookworm infection; trichuriasis; enterobiasis (pinworm); strongyloidiasis; neurocysticercosis; hydatid disease; lymphatic filariasis (with ivermectin or diethylcarbamazine); cutaneous larva migrans; giardiasis.', '[]'::jsonb, 'Albendazole is a broad-spectrum benzimidazole that binds parasite beta-tubulin, blocking microtubule formation and glucose uptake. A single dose treats common intestinal nematodes; prolonged courses, taken with a fatty meal to increase absorption, treat tissue cestodes such as hydatid cysts and neurocysticercosis.', 'admin', 'published', 4, true, '[["ascariasis", "roundworm", "ascaris"], ["hookworm", "ancylostoma", "necator"], ["trichuriasis", "whipworm", "trichuris"], ["enterobiasis", "pinworm", "threadworm"], ["strongyloidiasis", "strongyloides"], ["neurocysticercosis", "cysticercosis"], ["hydatid disease", "echinococcosis", "hydatid cyst"], ["filariasis", "lymphatic filariasis"], ["cutaneous larva migrans", "larva migrans"], ["giardiasis"]]'::jsonb, 'saq p.035 Q4d, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-f88af409e7', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Indicate 4 types of cholinergic receptors and where they are located.', '[]'::jsonb, 'Any 4 of: M1 - CNS, autonomic ganglia, gastric parietal cells; M2 - heart (SA and AV nodes, atria); M3 - smooth muscle, exocrine glands, vascular endothelium, eye; M4 and M5 - CNS; nicotinic Nn (neuronal) - autonomic ganglia, adrenal medulla, CNS; nicotinic Nm (muscle) - neuromuscular junction of skeletal muscle.', '[]'::jsonb, 'Muscarinic receptors are G-protein coupled (M1, M3, M5 via Gq; M2, M4 via Gi) and mediate parasympathetic effects on heart, smooth muscle and glands. Nicotinic receptors are ligand-gated sodium channels at ganglia (Nn) and the motor end plate (Nm).', 'admin', 'published', 4, true, '[["m1", "ganglia", "gastric parietal cells"], ["m2", "heart", "cardiac"], ["m3", "smooth muscle", "glands", "exocrine glands"], ["m4", "m5", "cns"], ["nn", "neuronal nicotinic", "autonomic ganglia", "adrenal medulla"], ["nm", "muscle nicotinic", "neuromuscular junction", "skeletal muscle"]]'::jsonb, 'saq p.035 Q4e, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-db023b0832', 'pharm-anticoagulant-drugs', 'saq', 'Briefly describe the mechanism of action of warfarin.', '[]'::jsonb, 'Warfarin inhibits vitamin K epoxide reductase (VKORC1), preventing regeneration of reduced vitamin K; this blocks gamma-carboxylation, and so activation, of clotting factors II, VII, IX and X (and proteins C and S).', '[]'::jsonb, 'Clotting factors II, VII, IX and X need gamma-carboxylation of glutamate residues, which consumes reduced vitamin K. Warfarin stops vitamin K recycling, so the liver releases inactive factors. The effect takes days to appear because existing factors must first be cleared.', 'admin', 'published', 2, true, '[["vitamin k epoxide reductase", "vkorc1", "epoxide reductase", "vitamin k antagonist"], ["gamma carboxylation", "carboxylation", "clotting factors 2,7,9,10", "vitamin k dependent factors", "clotting factors"]]'::jsonb, 'saq p.035 Q4f, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-b96c507e6f', 'pharm-antiseizure-barbiturates-hydantoin', 'saq', 'Give 4 adverse effects of phenytoin.', '[]'::jsonb, 'Any 4 of: gingival hyperplasia; hirsutism and coarsening of facial features; nystagmus, ataxia, diplopia; sedation; megaloblastic anaemia (folate deficiency); osteomalacia; skin rash, Stevens-Johnson syndrome; peripheral neuropathy; teratogenicity (fetal hydantoin syndrome); lymphadenopathy.', '[]'::jsonb, 'Dose-related toxicity is cerebellar and vestibular (nystagmus, ataxia, diplopia) and appears readily because phenytoin has saturable kinetics. Long-term use causes gum overgrowth, hirsutism, and, through enzyme induction, folate and vitamin D deficiency.', 'admin', 'published', 4, true, '[["gingival hyperplasia", "gum hypertrophy", "gum hyperplasia"], ["hirsutism", "coarse facies"], ["nystagmus", "ataxia", "diplopia"], ["megaloblastic anaemia", "megaloblastic anemia", "folate deficiency"], ["osteomalacia", "vitamin d deficiency"], ["rash", "stevens-johnson syndrome"], ["peripheral neuropathy"], ["teratogenic", "fetal hydantoin syndrome", "cleft palate"], ["sedation", "drowsiness"], ["lymphadenopathy"]]'::jsonb, 'saq p.037 Q5a, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-c3dfeb827b', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'Give 3 clinical indications of thiazide diuretics.', '[]'::jsonb, 'Any 3 of: hypertension; oedema of congestive heart failure (also hepatic and renal oedema); nephrogenic diabetes insipidus; idiopathic hypercalciuria/calcium kidney stones.', '[]'::jsonb, 'Thiazides lower blood pressure by natriuresis and a later fall in peripheral resistance. They reduce urinary calcium, preventing calcium stones, and paradoxically reduce urine volume in nephrogenic diabetes insipidus by causing mild volume depletion and greater proximal reabsorption.', 'admin', 'published', 3, true, '[["hypertension", "high blood pressure"], ["heart failure", "oedema", "edema", "congestive cardiac failure"], ["nephrogenic diabetes insipidus", "diabetes insipidus"], ["hypercalciuria", "kidney stones", "nephrolithiasis", "calcium stones"]]'::jsonb, 'saq p.037 Q5b, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-9cbef3d3f9', 'pharm-indirect-acting-cholinomimetics', 'saq', 'List 4 examples of indirect-acting cholinomimetics.', '[]'::jsonb, 'Any 4 of: neostigmine; physostigmine; pyridostigmine; edrophonium; donepezil; rivastigmine; galantamine; echothiophate; organophosphates such as malathion and parathion.', '[]'::jsonb, 'Indirect cholinomimetics inhibit acetylcholinesterase, so acetylcholine accumulates at all cholinergic synapses. They are alcohols (edrophonium, very short acting), carbamates (neostigmine, physostigmine; hours) or organophosphates (echothiophate, insecticides; effectively irreversible). Central ones such as donepezil are used in Alzheimer''s disease.', 'admin', 'published', 4, true, '[["neostigmine"], ["physostigmine"], ["pyridostigmine"], ["edrophonium"], ["donepezil", "rivastigmine", "galantamine", "tacrine"], ["echothiophate", "ecothiopate"], ["malathion", "parathion", "organophosphates"], ["ambenonium", "demecarium"]]'::jsonb, 'saq p.037 Q5c, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-69b9c16c41', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Give 5 classes of anticonvulsant drugs with an example of each class.', '[]'::jsonb, 'Any 5 of: hydantoins - phenytoin; barbiturates - phenobarbital; iminostilbenes - carbamazepine; succinimides - ethosuximide; benzodiazepines - diazepam, clonazepam; carboxylic acids - sodium valproate; GABA analogues - gabapentin, vigabatrin; phenyltriazines - lamotrigine; others - levetiracetam, topiramate.', '[]'::jsonb, 'The chemical classes map onto mechanisms: hydantoins, iminostilbenes and lamotrigine block sodium channels; barbiturates and benzodiazepines enhance GABA-A; succinimides block T-type calcium channels in absence seizures; valproate has several actions and the broadest spectrum.', 'admin', 'published', 5, true, '[["hydantoin", "phenytoin"], ["barbiturate", "phenobarbital", "phenobarbitone"], ["iminostilbene", "carbamazepine"], ["succinimide", "ethosuximide"], ["benzodiazepine", "diazepam", "clonazepam", "lorazepam"], ["valproate", "valproic acid", "carboxylic acid"], ["gaba analogue", "gabapentin", "vigabatrin"], ["lamotrigine", "phenyltriazine"], ["levetiracetam", "topiramate"]]'::jsonb, 'saq p.037 Q5d, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-4117ad1c56', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List 4 adverse effects of loop diuretics.', '[]'::jsonb, 'Any 4 of: hypokalaemia; hyponatraemia; hypomagnesaemia; hypocalcaemia; hypochloraemic metabolic alkalosis; dehydration/hypovolaemia and hypotension; ototoxicity; hyperuricaemia (gout); hyperglycaemia; allergic reactions (sulfonamide).', '[]'::jsonb, 'Loop diuretics block the Na-K-2Cl cotransporter in the thick ascending limb, abolishing the lumen-positive potential that drives calcium and magnesium reabsorption. So, unlike thiazides, they cause hypocalcaemia. Ototoxicity is dose related and worse with aminoglycosides.', 'admin', 'published', 4, true, '[["hypokalaemia", "hypokalemia"], ["hyponatraemia", "hyponatremia"], ["hypomagnesaemia", "hypomagnesemia"], ["hypocalcaemia", "hypocalcemia"], ["metabolic alkalosis", "alkalosis"], ["dehydration", "hypovolaemia", "hypotension"], ["ototoxicity", "deafness", "hearing loss"], ["hyperuricaemia", "hyperuricemia", "gout"], ["hyperglycaemia", "hyperglycemia"], ["allergy", "hypersensitivity", "rash"]]'::jsonb, 'saq p.037 Q5e, BDS EOY 2021/2022 Paper 2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-bb25f26e6f', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'List 3 examples of luminal amoebicides.', '[]'::jsonb, 'Diloxanide furoate; paromomycin; iodoquinol (diiodohydroxyquin).', '[]'::jsonb, 'Luminal amoebicides are poorly absorbed and act on trophozoites and cysts in the gut lumen. They are used for asymptomatic cyst passers and after metronidazole in invasive disease, because metronidazole is absorbed too well to clear the lumen.', 'admin', 'published', 3, true, '[["diloxanide", "diloxanide furoate"], ["paromomycin"], ["iodoquinol", "diiodohydroxyquin"]]'::jsonb, 'saq p.040 Q1a(i), MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-6879e62cb2', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'List 2 protozoa, other than Entamoeba histolytica, that are treated with metronidazole.', '[]'::jsonb, 'Trichomonas vaginalis; Giardia lamblia. (Also Balantidium coli, Blastocystis hominis.)', '[]'::jsonb, 'Metronidazole is a prodrug reduced to toxic nitro radicals by ferredoxin in anaerobic organisms, so it kills anaerobic protozoa (Trichomonas, Giardia, Entamoeba) and anaerobic bacteria but not aerobes. It is also the drug of choice for invasive amoebiasis, followed by a luminal agent.', 'admin', 'published', 2, true, '[["trichomonas vaginalis", "trichomonas", "trichomoniasis"], ["giardia lamblia", "giardia", "giardiasis"], ["balantidium coli", "balantidium"], ["blastocystis"]]'::jsonb, 'saq p.040 Q1a(ii), MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-e046e374b2', 'pharm-biologic-dmards', 'saq', 'List 3 examples of TNF-alpha blocking agents used in rheumatoid arthritis.', '[]'::jsonb, 'Any 3 of: infliximab; etanercept; adalimumab; golimumab; certolizumab pegol.', '[]'::jsonb, 'Infliximab (chimeric), adalimumab and golimumab (human) are monoclonal antibodies to TNF-alpha, certolizumab is a pegylated Fab fragment, and etanercept is a TNF receptor-Fc fusion protein. All increase the risk of reactivating latent tuberculosis, so patients are screened first.', 'admin', 'published', 3, true, '[["infliximab"], ["etanercept"], ["adalimumab"], ["golimumab"], ["certolizumab"]]'::jsonb, 'saq p.040 Q1b, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-24084a86f2', 'pharm-oral-antidiabetic-drugs', 'saq', 'List 3 contraindications to the use of metformin.', '[]'::jsonb, 'Any 3 of: renal impairment (eGFR below 30 ml/min); hepatic disease; alcoholism; conditions causing tissue hypoxia - heart failure, respiratory failure, shock, sepsis; previous lactic acidosis; diabetic ketoacidosis; (withheld around iodinated contrast).', '[]'::jsonb, 'Metformin''s serious toxicity is lactic acidosis. It is excreted unchanged by the kidney, so it accumulates in renal impairment, and any state that raises lactate production or lowers its clearance (hypoxia, liver disease, alcohol) increases the risk.', 'admin', 'published', 3, true, '[["renal impairment", "renal failure", "kidney disease"], ["hepatic disease", "liver disease", "liver failure"], ["alcoholism", "alcohol abuse"], ["hypoxia", "heart failure", "respiratory failure", "chronic lung disease", "shock", "sepsis"], ["lactic acidosis"], ["ketoacidosis", "dka"], ["contrast media", "iodinated contrast"]]'::jsonb, 'saq p.040 Q1c(ii), MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-f1c3cbe139', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'saq', 'Briefly explain the 3 main pharmacological actions of NSAIDs and their mechanisms.', '[]'::jsonb, 'All result from inhibition of cyclo-oxygenase (COX), reducing prostaglandin synthesis. 1. Anti-inflammatory: less PGE2 and PGI2, which cause vasodilation, oedema and erythema. 2. Analgesic: less PGE2/PGI2 sensitising nociceptors to bradykinin and histamine. 3. Antipyretic: less PGE2 in the hypothalamus, so the temperature set-point is reset. (Aspirin also has an antiplatelet action by reducing thromboxane A2.)', '[]'::jsonb, 'One mechanism, COX inhibition, explains all three effects because prostaglandins mediate inflammation, sensitise pain fibres and raise the hypothalamic set-point in fever. NSAIDs lower a raised temperature but not normal body temperature.', 'admin', 'published', 3, true, '[["anti-inflammatory", "antiinflammatory", "reduce inflammation"], ["analgesic", "pain relief", "analgesia"], ["antipyretic", "reduce fever", "lowers temperature"], ["cox inhibition", "cyclooxygenase", "inhibit cox", "prostaglandin synthesis"]]'::jsonb, 'saq p.040 Q1e, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-3254e38db9', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'saq', 'List six adverse effects of quinine.', '[]'::jsonb, 'Any 6 of: cinchonism (tinnitus, high-tone deafness, headache, nausea, dizziness, visual disturbance); hypoglycaemia; hypotension with rapid intravenous infusion; cardiac arrhythmias/QT prolongation; haemolysis (G6PD deficiency), blackwater fever; hypersensitivity - rash, thrombocytopenia; gastrointestinal upset; uterine contraction; blindness in overdose.', '[]'::jsonb, 'Quinine commonly causes cinchonism at therapeutic doses. It stimulates insulin release from beta cells, so hypoglycaemia is a particular danger in pregnancy and severe malaria, and like quinidine it blocks cardiac ion channels, prolonging the QT interval.', 'admin', 'published', 6, true, '[["cinchonism"], ["tinnitus", "deafness", "hearing loss"], ["hypoglycaemia", "hypoglycemia"], ["hypotension"], ["arrhythmias", "qt prolongation", "cardiac dysrhythmias"], ["haemolysis", "hemolysis", "blackwater fever"], ["visual disturbance", "blurred vision", "blindness"], ["nausea", "vomiting", "gi upset"], ["thrombocytopenia", "rash", "hypersensitivity"], ["headache", "dizziness", "vertigo"]]'::jsonb, 'saq p.042 Q2a, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-a02d5dfba4', 'pharm-sedative-hypnotic-drugs', 'saq', 'List five clinical uses of diazepam.', '[]'::jsonb, 'Any 5 of: anxiety disorders; status epilepticus and other acute seizures (including febrile convulsions); skeletal muscle spasm and spasticity (including tetanus); alcohol withdrawal; preoperative and procedural sedation; short-term treatment of insomnia.', '[]'::jsonb, 'Diazepam is a long-acting benzodiazepine with active metabolites. Its anxiolytic, anticonvulsant, muscle relaxant and sedative effects all come from enhancing GABA-A transmission; its long half-life gives smooth cover in alcohol withdrawal.', 'admin', 'published', 5, true, '[["anxiety", "anxiolytic"], ["status epilepticus", "seizures", "convulsions", "anticonvulsant"], ["muscle spasm", "muscle relaxant", "spasticity", "tetanus"], ["alcohol withdrawal"], ["premedication", "preoperative sedation", "sedation"], ["insomnia", "hypnotic"], ["febrile convulsions"]]'::jsonb, 'saq p.042 Q2b, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-5359485b94', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'saq', 'List four drugs that are used as prokinetic agents.', '[]'::jsonb, 'Any 4 of: metoclopramide; domperidone; erythromycin; cisapride; mosapride; prucalopride; tegaserod; bethanechol; neostigmine.', '[]'::jsonb, 'Prokinetics speed gastric emptying or gut transit. Metoclopramide and domperidone block D2 receptors, releasing cholinergic drive; cisapride and prucalopride are 5-HT4 agonists; erythromycin is a motilin receptor agonist. Cisapride was largely withdrawn because of QT prolongation.', 'admin', 'published', 4, true, '[["metoclopramide"], ["domperidone"], ["erythromycin"], ["cisapride", "mosapride"], ["prucalopride", "tegaserod"], ["bethanechol", "neostigmine"]]'::jsonb, 'saq p.042 Q2c, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcitonin-bisphosphonates-and-fluorid-3f310bf89f', 'pharm-calcitonin-bisphosphonates-and-fluorides', 'saq', 'Enumerate three clinical uses of bisphosphonates.', '[]'::jsonb, 'Any 3 of: osteoporosis (postmenopausal, glucocorticoid-induced); Paget''s disease of bone; hypercalcaemia of malignancy; bone metastases and multiple myeloma (to reduce skeletal events).', '[]'::jsonb, 'Bisphosphonates bind hydroxyapatite and are taken up by osteoclasts, where the nitrogen-containing ones inhibit farnesyl pyrophosphate synthase and cause osteoclast apoptosis. Reduced bone resorption helps wherever bone turnover or calcium release is excessive.', 'admin', 'published', 3, true, '[["osteoporosis"], ["paget''s disease", "pagets disease", "paget"], ["hypercalcaemia of malignancy", "hypercalcemia", "hypercalcaemia"], ["bone metastases", "metastatic bone disease", "multiple myeloma"]]'::jsonb, 'saq p.042 Q2d, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-5241daa7f2', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'A 55-year-old man is seen in casualty after loss of consciousness; his blood pressure is 120/80 mmHg and his blood sugar is raised at 20 mmol/l. Classify, with examples, the drugs that can be given parenterally to lower his blood sugar.', '[]'::jsonb, '1. Insulins: rapid-acting - lispro, aspart, glulisine; short-acting - regular (soluble) insulin, the one given intravenously in emergencies; intermediate-acting - NPH (isophane); long-acting - glargine, detemir, degludec. 2. GLP-1 receptor agonists (incretin mimetics): exenatide, liraglutide, semaglutide. 3. Amylin analogue: pramlintide.', '[]'::jsonb, 'Only three antidiabetic groups are injected: insulins, GLP-1 agonists and the amylin analogue pramlintide. In a hyperglycaemic emergency only intravenous regular insulin is appropriate; DPP-4 inhibitors such as saxagliptin are oral drugs and do not belong here.', 'admin', 'published', 8, true, '[["insulin"], ["rapid acting", "lispro", "aspart", "glulisine"], ["short acting", "regular insulin", "soluble insulin"], ["intermediate acting", "nph", "isophane"], ["long acting", "glargine", "detemir", "degludec"], ["glp-1 agonist", "incretin mimetic", "glp-1 receptor agonists"], ["exenatide", "liraglutide", "semaglutide"], ["amylin analogue", "pramlintide"]]'::jsonb, 'saq p.043 Q3a(i), MBChB III EOY 2020/2021. The compiled answer on the scan lists saxagliptin (an oral DPP-4 inhibitor); this is wrong and has been left out.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-67c419902b', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List three adverse effects associated with insulin and other parenteral antidiabetic agents.', '[]'::jsonb, 'Any 3 of: hypoglycaemia; weight gain; lipodystrophy at injection sites (lipohypertrophy or lipoatrophy); allergic reactions; hypokalaemia; with GLP-1 agonists - nausea and vomiting, pancreatitis.', '[]'::jsonb, 'Hypoglycaemia is the commonest and most dangerous effect of insulin. Insulin is anabolic, causing weight gain and local fat hypertrophy when the same site is used repeatedly, and it drives potassium into cells. GLP-1 agonists instead cause nausea and weight loss.', 'admin', 'published', 3, true, '[["hypoglycaemia", "hypoglycemia"], ["weight gain"], ["lipodystrophy", "lipohypertrophy", "lipoatrophy"], ["allergy", "hypersensitivity", "injection site reaction"], ["hypokalaemia", "hypokalemia"], ["nausea", "vomiting", "pancreatitis"]]'::jsonb, 'saq p.043 Q3a(ii), MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-c2bf0dccb2', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Name three devices that can be used to administer insulin.', '[]'::jsonb, 'Any 3 of: insulin syringe and needle (with vial); insulin pen (prefilled or reusable); insulin pump (continuous subcutaneous insulin infusion); jet injector; inhaler for inhaled insulin.', '[]'::jsonb, 'Syringes are cheapest; pens improve dosing accuracy and convenience; pumps deliver a continuous basal rate of rapid-acting insulin with meal boluses, the closest match to physiological secretion. Jet injectors push insulin through the skin without a needle.', 'admin', 'published', 3, true, '[["syringe", "insulin syringe", "needle and syringe"], ["pen", "insulin pen", "pen injector"], ["pump", "insulin pump", "infusion pump"], ["jet injector"], ["inhaler", "inhaled insulin"]]'::jsonb, 'saq p.043 Q3a(iii), MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-01bcc16e4c', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Briefly describe the mechanism of action of minoxidil.', '[]'::jsonb, 'Minoxidil is a prodrug converted to minoxidil sulphate, which opens ATP-sensitive potassium channels in vascular smooth muscle. Potassium efflux hyperpolarises the cell, closing voltage-gated calcium channels; reduced intracellular calcium relaxes arteriolar smooth muscle, causing vasodilation and a fall in blood pressure.', '[]'::jsonb, 'Hyperpolarised smooth muscle cannot open its voltage-gated calcium channels, so calcium-calmodulin activation of myosin light chain kinase falls and arterioles dilate. Reflex tachycardia and fluid retention follow, so minoxidil is given with a beta-blocker and a diuretic.', 'admin', 'published', 3, true, '[["opens potassium channels", "potassium channel opener", "k channel opener", "katp"], ["hyperpolarisation", "hyperpolarization"], ["reduced calcium influx", "closes calcium channels", "decreased intracellular calcium"], ["arteriolar vasodilation", "vasodilation", "smooth muscle relaxation"], ["minoxidil sulphate", "minoxidil sulfate", "prodrug"]]'::jsonb, 'saq p.043 Q3b, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-71f637a6dd', 'pharm-antimuscarinic-agents', 'saq', 'Name three long-acting antimuscarinic agents useful in the management of asthma and other obstructive airway disease.', '[]'::jsonb, 'Any 3 of: tiotropium; aclidinium; umeclidinium; glycopyrronium (glycopyrrolate).', '[]'::jsonb, 'Long-acting muscarinic antagonists block M3 receptors on bronchial smooth muscle and dissociate slowly, giving 12 to 24 hours of bronchodilation. Ipratropium is short acting. Only tiotropium is established as an add-on in asthma; the others are mainly used in COPD.', 'admin', 'published', 3, true, '[["tiotropium"], ["aclidinium"], ["umeclidinium"], ["glycopyrronium", "glycopyrrolate"]]'::jsonb, 'saq p.043 Q3c, MBChB III EOY 2020/2021. Text widened to ''asthma and other obstructive airway disease'' since aclidinium and umeclidinium are mainly COPD drugs.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-bff5e8a4d9', 'pharm-emergency-management-of-poisoning', 'saq', 'What are the indications and contraindications of induced emesis in drug poisoning?', '[]'::jsonb, 'Indications: a fully conscious, alert patient who has recently (within about 1 hour) swallowed a potentially toxic amount of a non-corrosive poison, where gastric lavage or charcoal is not available. Contraindications: reduced consciousness, coma or absent gag reflex; convulsions or ingestion of a CNS stimulant/convulsant; corrosive (acid or alkali) ingestion; petroleum distillates/hydrocarbons such as paraffin; infants under 6 months.', '[]'::jsonb, 'Vomiting is dangerous when the airway is unprotected (coma, seizures), when the poison burns again on the way up (corrosives) or when aspiration causes pneumonitis (hydrocarbons). Ipecac-induced emesis is no longer recommended routinely because it does not improve outcome.', 'admin', 'published', 6, true, '[["conscious", "alert", "awake"], ["within one hour", "within 1 hour", "recent ingestion", "within 60 minutes"], ["coma", "unconscious", "reduced consciousness", "no gag reflex"], ["corrosives", "acid", "alkali", "caustic"], ["hydrocarbons", "paraffin", "kerosene", "petroleum distillates"], ["convulsions", "seizures", "cns stimulant"], ["infants", "under 6 months"]]'::jsonb, 'saq p.044 Q4a, MBChB III EOY 2020/2021. Modern guidelines no longer recommend induced emesis; answer reflects the classical teaching the paper expects.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-b2aa9fef7e', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'saq', 'Mention two drugs used in the treatment of paracetamol poisoning.', '[]'::jsonb, 'N-acetylcysteine (intravenous or oral); methionine (oral). Activated charcoal if the patient presents within 1 hour.', '[]'::jsonb, 'In overdose the toxic metabolite NAPQI exhausts hepatic glutathione and causes centrilobular necrosis. Acetylcysteine and methionine are glutathione precursors that restore the ability to detoxify NAPQI; acetylcysteine is most effective within 8 hours of ingestion.', 'admin', 'published', 2, true, '[["n-acetylcysteine", "acetylcysteine", "nac"], ["methionine"], ["activated charcoal", "charcoal"]]'::jsonb, 'saq p.044 Q4b, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-16386f7b95', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'Give 3 adverse effects of carbimazole.', '[]'::jsonb, 'Any 3 of: skin rash and pruritus; agranulocytosis/neutropenia; arthralgia; fever; nausea and gastrointestinal upset; cholestatic jaundice/hepatitis; hypothyroidism and goitre with overtreatment; fetal aplasia cutis.', '[]'::jsonb, 'Carbimazole (converted to methimazole) blocks thyroid peroxidase. Rash is the commonest reaction; agranulocytosis is rare but dangerous, so patients must report a sore throat or fever immediately and have a white cell count checked.', 'admin', 'published', 3, true, '[["rash", "pruritus", "itching", "urticaria"], ["agranulocytosis", "neutropenia", "leucopenia"], ["arthralgia", "joint pain"], ["fever"], ["nausea", "gi upset", "vomiting"], ["jaundice", "hepatitis", "cholestatic jaundice"], ["hypothyroidism", "goitre"], ["aplasia cutis", "teratogenic"]]'::jsonb, 'saq p.044 Q4c, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-c97ac82b9f', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'saq', 'Mention 4 clinical features of vitamin B12 deficiency.', '[]'::jsonb, 'Any 4 of: megaloblastic (macrocytic) anaemia - pallor, fatigue, dyspnoea; glossitis (smooth, red, sore tongue); peripheral neuropathy - paraesthesiae and numbness; subacute combined degeneration of the spinal cord - loss of vibration and position sense, ataxia, weakness; memory loss/dementia, psychiatric changes; mild jaundice; anorexia, weight loss, diarrhoea.', '[]'::jsonb, 'B12 is needed for DNA synthesis (through methionine synthase and folate recycling) and for myelin maintenance (methylmalonyl-CoA mutase). Deficiency therefore gives megaloblastic anaemia plus neurological damage; folic acid corrects only the anaemia and may let the neuropathy progress.', 'admin', 'published', 4, true, '[["megaloblastic anaemia", "megaloblastic anemia", "macrocytic anaemia", "anaemia", "pallor"], ["glossitis", "sore tongue", "beefy tongue", "smooth tongue"], ["peripheral neuropathy", "paraesthesia", "numbness", "tingling"], ["subacute combined degeneration", "ataxia", "loss of vibration sense", "demyelination"], ["dementia", "memory loss", "psychosis", "confusion"], ["jaundice"], ["anorexia", "weight loss", "diarrhoea"]]'::jsonb, 'saq p.044 Q4d, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-067c2e1383', 'pharm-disinfectants-and-antiseptics', 'saq', 'Give 5 examples of sterilants.', '[]'::jsonb, 'Any 5 of: ethylene oxide; glutaraldehyde; formaldehyde; peracetic acid; hydrogen peroxide (including gas plasma); ortho-phthalaldehyde; chlorine dioxide; ozone; propylene oxide.', '[]'::jsonb, 'A sterilant kills all microbial life including bacterial spores, unlike a disinfectant or antiseptic. Chemical sterilants are alkylating agents (ethylene oxide, aldehydes) or strong oxidisers (peracetic acid, hydrogen peroxide) and are used for heat-sensitive equipment.', 'admin', 'published', 5, true, '[["ethylene oxide"], ["glutaraldehyde"], ["formaldehyde", "formalin"], ["peracetic acid"], ["hydrogen peroxide"], ["ortho-phthalaldehyde", "opa"], ["chlorine dioxide"], ["ozone"], ["propylene oxide"]]'::jsonb, 'saq p.044 Q4e, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-efa6e30f3f', 'pharm-lipid-lowering-agents', 'saq', 'List 3 drugs of different chemical classes that are most effective at lowering LDL cholesterol.', '[]'::jsonb, 'Any 3 of: a statin (atorvastatin, rosuvastatin, simvastatin); ezetimibe; a PCSK9 inhibitor (evolocumab, alirocumab); a bile acid-binding resin (cholestyramine, colestipol, colesevelam); niacin.', '[]'::jsonb, 'Statins and PCSK9 inhibitors lower LDL most (up to about 50 to 60%) by increasing hepatic LDL receptors; ezetimibe and resins add roughly 15 to 25%. Fibrates mainly lower triglycerides and are not chosen for LDL.', 'admin', 'published', 3, true, '[["atorvastatin", "rosuvastatin", "simvastatin", "statin"], ["ezetimibe"], ["evolocumab", "alirocumab", "pcsk9 inhibitor"], ["cholestyramine", "colestipol", "colesevelam", "resin"], ["niacin", "nicotinic acid"]]'::jsonb, 'saq p.045 Q5a, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-30c5c9be91', 'pharm-lipid-lowering-agents', 'saq', 'Give 4 drugs whose absorption may be impaired by cholestyramine.', '[]'::jsonb, 'Any 4 of: digoxin (digitalis glycosides); warfarin; thiazide diuretics; levothyroxine; tetracycline; iron salts; statins; folic acid; fat-soluble vitamins (A, D, E, K).', '[]'::jsonb, 'Cholestyramine is an anion-exchange resin that stays in the gut and binds bile acids, but it also binds many acidic drugs and impairs fat-soluble vitamin absorption. Other medicines should be taken one hour before or four hours after it.', 'admin', 'published', 4, true, '[["digoxin", "digitalis"], ["warfarin"], ["thiazides", "hydrochlorothiazide"], ["thyroxine", "levothyroxine"], ["tetracycline"], ["iron"], ["statins", "pravastatin", "fluvastatin"], ["folic acid"], ["fat soluble vitamins", "vitamin k", "vitamin a", "vitamin d"]]'::jsonb, 'saq p.045 Q5b, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-49fec0e84b', 'pharm-antidepressants-and-lithium', 'saq', 'Give 4 drugs of different chemical classes that can precipitate the serotonin syndrome.', '[]'::jsonb, 'Any 4 from different classes: SSRIs - fluoxetine, sertraline; SNRIs - venlafaxine; MAO inhibitors - phenelzine, moclobemide, selegiline, linezolid; tricyclics - clomipramine, imipramine; opioids - tramadol, pethidine; triptans - sumatriptan; amphetamines/MDMA; dextromethorphan; St John''s wort; lithium; tryptophan.', '[]'::jsonb, 'Serotonin syndrome (agitation, hyperthermia, clonus, autonomic instability) follows excess synaptic serotonin, usually when two serotonergic drugs are combined: one that blocks reuptake or releases serotonin and one that blocks its breakdown, classically an SSRI or pethidine with an MAO inhibitor.', 'admin', 'published', 4, true, '[["fluoxetine", "sertraline", "paroxetine", "citalopram", "ssri"], ["phenelzine", "moclobemide", "selegiline", "maoi", "linezolid"], ["clomipramine", "imipramine", "amitriptyline", "tricyclic"], ["tramadol", "pethidine", "meperidine", "fentanyl"], ["sumatriptan", "triptan"], ["venlafaxine", "duloxetine", "snri"], ["mdma", "ecstasy", "amphetamine", "cocaine"], ["dextromethorphan"], ["st john''s wort"], ["lithium", "tryptophan"]]'::jsonb, 'saq p.045 Q5c, MBChB III EOY 2020/2021. Also appears as ''List 4 drugs which can precipitate the serotonin syndrome'' on p.026 (MBChB EOY 2021/2022).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-f368efd68c', 'pharm-iminostilbenes-succinimides-lamotrigine', 'saq', 'Give 3 antiseizure drugs whose metabolism is induced by carbamazepine.', '[]'::jsonb, 'Any 3 of: phenytoin; valproic acid; ethosuximide; clonazepam; lamotrigine; primidone; topiramate; tiagabine; carbamazepine itself (autoinduction).', '[]'::jsonb, 'Carbamazepine is a strong inducer of CYP3A4 and glucuronyl transferases. It lowers the levels of co-prescribed antiepileptics and of itself (autoinduction over the first few weeks), as well as oral contraceptives and warfarin.', 'admin', 'published', 3, true, '[["phenytoin"], ["valproate", "valproic acid", "sodium valproate"], ["ethosuximide"], ["clonazepam"], ["lamotrigine"], ["primidone"], ["topiramate", "tiagabine"], ["carbamazepine", "autoinduction"]]'::jsonb, 'saq p.045 Q5d, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-9a0ad9baee', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Give 4 clinical indications of glucocorticoids in different systems of the body.', '[]'::jsonb, 'Any 4 from different systems: endocrine - adrenal insufficiency (Addison''s disease), congenital adrenal hyperplasia; respiratory - asthma, COPD exacerbation; musculoskeletal/connective tissue - rheumatoid arthritis, SLE; skin - eczema, psoriasis; GIT - inflammatory bowel disease; renal - nephrotic syndrome; CNS - cerebral oedema; haematology/oncology - leukaemia, lymphoma, immune thrombocytopenia; transplantation - prevention of rejection; allergy - anaphylaxis; chemotherapy-induced vomiting.', '[]'::jsonb, 'Glucocorticoids are used as physiological replacement in adrenal failure and, at higher doses, for their anti-inflammatory and immunosuppressive effects in almost every system. They also lyse lymphoid cells in leukaemia and reduce vasogenic brain oedema.', 'admin', 'published', 4, true, '[["adrenal insufficiency", "addison''s disease", "addisons", "replacement therapy"], ["asthma", "copd"], ["rheumatoid arthritis", "sle", "lupus"], ["eczema", "psoriasis", "dermatitis"], ["inflammatory bowel disease", "ulcerative colitis", "crohn''s"], ["nephrotic syndrome"], ["cerebral oedema", "cerebral edema"], ["leukaemia", "lymphoma", "leukemia"], ["transplant rejection", "organ transplant"], ["anaphylaxis", "allergy"], ["antiemetic", "chemotherapy vomiting"]]'::jsonb, 'saq p.045 Q5e, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-bdc0d938f8', 'pharm-drug-interactions', 'saq', 'Briefly explain the term synergism.', '[]'::jsonb, 'Synergism is a drug interaction in which the combined effect of two (or more) drugs given together is greater than the sum of their individual effects (1 + 1 > 2), e.g. sulfamethoxazole with trimethoprim, or a penicillin with an aminoglycoside.', '[]'::jsonb, 'Synergism (potentiation) differs from simple addition, where the combined effect equals the sum. It usually arises when drugs act at different steps of one pathway (co-trimoxazole) or one helps the other reach its target (penicillin letting aminoglycosides into bacteria).', 'admin', 'published', 2, true, '[["greater than sum", "more than additive", "greater than the sum", "1+1>2"], ["combined effect", "two drugs together", "drugs used together", "combination"]]'::jsonb, 'saq p.045 Q5f, MBChB III EOY 2020/2021') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-0b23a916c5', 'pharm-antidiarrheal-agents-laxatives', 'saq', 'What is the clinical indication for diphenoxylate?', '[]'::jsonb, 'Diarrhoea', '["diarrhea", "acute diarrhoea", "non-infective diarrhoea", "treatment of diarrhoea", "antidiarrhoeal", "antidiarrheal", "acute diarrhea"]'::jsonb, 'Diphenoxylate is a pethidine congener that activates mu opioid receptors in the gut wall, slowing peristalsis and increasing fluid absorption. It is used for symptomatic control of non-infective diarrhoea and has little analgesic action at usual doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.047 Q1a(i), MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-3daf25866b', 'pharm-antidiarrheal-agents-laxatives', 'saq', 'Why is diphenoxylate combined with atropine?', '[]'::jsonb, 'To discourage abuse and deliberate overdose: the small dose of atropine has no effect at therapeutic doses, but if large amounts are taken for the opioid effect it produces unpleasant anticholinergic effects (dry mouth, blurred vision, tachycardia, flushing).', '[]'::jsonb, 'At high doses diphenoxylate crosses into the brain and produces opioid euphoria and dependence. The subtherapeutic atropine in co-phenotrope (Lomotil) makes high doses unpleasant; it is not there for an antispasmodic effect.', 'admin', 'published', 1, true, '[["discourage abuse", "prevent abuse", "deter abuse", "reduce abuse", "prevent overdose", "abuse deterrent"], ["anticholinergic effects", "unpleasant effects", "dry mouth", "atropine side effects"]]'::jsonb, 'saq p.047 Q1a(ii), MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-73abbd931e', 'pharm-gh-prolactin-and-its-inhibitor', 'saq', 'List 2 indications of octreotide.', '[]'::jsonb, 'Any 2 of: acromegaly; carcinoid syndrome; VIPoma, glucagonoma and other secretory neuroendocrine tumours; bleeding oesophageal varices; secretory/refractory diarrhoea (e.g. HIV, chemotherapy), dumping syndrome; sulfonylurea-induced hypoglycaemia; pancreatic fistula.', '[]'::jsonb, 'Octreotide is a long-acting somatostatin analogue. It suppresses growth hormone and gut peptide secretion (acromegaly, carcinoid, VIPoma), reduces intestinal secretion, and lowers splanchnic blood flow and portal pressure in variceal bleeding.', 'admin', 'published', 2, true, '[["acromegaly"], ["carcinoid syndrome", "carcinoid"], ["vipoma", "glucagonoma", "gastrinoma", "neuroendocrine tumours"], ["oesophageal varices", "esophageal varices", "variceal bleeding"], ["diarrhoea", "diarrhea", "dumping syndrome"], ["sulfonylurea hypoglycaemia", "hypoglycaemia"], ["pancreatic fistula"]]'::jsonb, 'saq p.047 Q1b, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-bcbac3a6b4', 'pharm-anti-leprosy-drugs', 'saq', 'List 3 adverse effects of dapsone.', '[]'::jsonb, 'Any 3 of: haemolytic anaemia (dose related; severe in G6PD deficiency); methaemoglobinaemia; gastrointestinal intolerance (nausea, anorexia); skin rash/dapsone hypersensitivity syndrome (fever, rash, hepatitis); peripheral neuropathy; agranulocytosis; erythema nodosum leprosum during treatment of lepromatous leprosy.', '[]'::jsonb, 'Dapsone''s hydroxylamine metabolite oxidises haemoglobin and red cell membranes, so some haemolysis and methaemoglobinaemia occur in most patients and are severe in G6PD deficiency. The dapsone syndrome is an idiosyncratic hypersensitivity appearing in the first weeks.', 'admin', 'published', 3, true, '[["haemolysis", "hemolysis", "haemolytic anaemia", "hemolytic anemia"], ["methaemoglobinaemia", "methemoglobinemia"], ["nausea", "gi intolerance", "anorexia", "vomiting"], ["rash", "dapsone syndrome", "hypersensitivity", "fever"], ["peripheral neuropathy"], ["agranulocytosis"], ["erythema nodosum leprosum"], ["hepatitis"]]'::jsonb, 'saq p.047 Q1c, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-534294904c', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'saq', 'Give 3 examples of beta-lactamase inhibitors.', '[]'::jsonb, 'Any 3 of: clavulanic acid; sulbactam; tazobactam; avibactam; vaborbactam.', '[]'::jsonb, 'These drugs have little antibacterial action themselves but bind and inactivate beta-lactamases, protecting the partner penicillin or cephalosporin: amoxicillin-clavulanate, ampicillin-sulbactam, piperacillin-tazobactam, ceftazidime-avibactam. They are ''suicide'' inhibitors and work best against plasmid-mediated enzymes of staphylococci, Haemophilus and many Gram-negative rods.', 'admin', 'published', 3, true, '[["clavulanic acid", "clavulanate"], ["sulbactam"], ["tazobactam"], ["avibactam"], ["vaborbactam", "relebactam"]]'::jsonb, 'saq p.047 Q1d, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-69ed1c108b', 'pharm-disinfectants-and-antiseptics', 'saq', 'Give 4 disadvantages of antiseptics and disinfectants.', '[]'::jsonb, 'Any 4 of: irritant or toxic to tissues and may delay wound healing; cause hypersensitivity/contact dermatitis; inactivated by organic matter (blood, pus), soaps or hard water; limited spectrum - many do not kill spores, mycobacteria or some viruses; corrosive to instruments and surfaces or stain skin and fabrics; solutions can become contaminated and organisms may develop resistance; systemic toxicity if absorbed.', '[]'::jsonb, 'Unlike antibiotics, antiseptics and disinfectants are non-selective protoplasmic poisons, which is why they injure host tissue, cannot be given systemically and can sensitise skin. Their activity also falls sharply in the presence of pus, blood or dilution.', 'admin', 'draft', 4, true, '[["tissue irritation", "irritant", "tissue toxicity", "delay wound healing"], ["hypersensitivity", "contact dermatitis", "allergy"], ["inactivated by organic matter", "inactivated by pus", "inactivated by blood"], ["not sporicidal", "limited spectrum", "do not kill spores"], ["corrosive", "staining", "damage instruments"], ["contamination", "resistance"], ["systemic toxicity", "toxic if absorbed"]]'::jsonb, 'saq p.047 Q1e, MBChB EOY 2019/2020. Open-ended question with no standard list; model answer is a reasonable set from standard texts.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-6cb4d548d0', 'pharm-major-tranquilizer', 'saq', 'List 3 adverse effects of chlorpromazine.', '[]'::jsonb, 'Any 3 of: sedation; extrapyramidal effects (acute dystonia, parkinsonism, akathisia, tardive dyskinesia); postural hypotension; antimuscarinic effects (dry mouth, blurred vision, constipation, urinary retention); hyperprolactinaemia (galactorrhoea, amenorrhoea, gynaecomastia); weight gain; cholestatic jaundice; photosensitivity and skin pigmentation; corneal and lens deposits; neuroleptic malignant syndrome; lowered seizure threshold.', '[]'::jsonb, 'Chlorpromazine blocks many receptors: D2 (extrapyramidal effects, raised prolactin), H1 (sedation, weight gain), alpha-1 (postural hypotension) and muscarinic (dry mouth, constipation). Cholestatic jaundice and photosensitivity are idiosyncratic reactions typical of phenothiazines.', 'admin', 'published', 3, true, '[["sedation", "drowsiness"], ["extrapyramidal", "parkinsonism", "dystonia", "tardive dyskinesia", "akathisia"], ["postural hypotension", "orthostatic hypotension", "hypotension"], ["dry mouth", "anticholinergic", "constipation", "urinary retention", "blurred vision"], ["hyperprolactinaemia", "galactorrhoea", "gynaecomastia", "amenorrhoea"], ["weight gain"], ["jaundice", "cholestatic jaundice"], ["photosensitivity", "skin pigmentation"], ["neuroleptic malignant syndrome"], ["seizures", "lowered seizure threshold"]]'::jsonb, 'saq p.047 Q1f, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-999942d6b8', 'pharm-anticancer-agents-general-principles-classification', 'saq', 'List 5 unrelated adverse effects of cytotoxic agents.', '[]'::jsonb, 'Any 5 of: bone marrow suppression (neutropenia, anaemia, thrombocytopenia); nausea and vomiting; alopecia; mucositis/oral ulceration and diarrhoea; infertility/sterility; teratogenicity; secondary malignancies; hyperuricaemia (tumour lysis); impaired wound healing; tissue necrosis on extravasation.', '[]'::jsonb, 'Cytotoxic drugs kill dividing cells without distinguishing tumour from normal tissue, so the rapidly renewing tissues suffer: marrow, gut epithelium, hair follicles and gonads. DNA damage in surviving cells explains teratogenicity and later second cancers.', 'admin', 'published', 5, true, '[["myelosuppression", "bone marrow suppression", "neutropenia", "pancytopenia"], ["nausea", "vomiting"], ["alopecia", "hair loss"], ["mucositis", "mouth ulcers", "stomatitis", "diarrhoea"], ["infertility", "sterility"], ["teratogenicity", "teratogenic"], ["secondary malignancy", "carcinogenic", "second cancers"], ["hyperuricaemia", "tumour lysis", "tumor lysis"], ["impaired wound healing"], ["extravasation", "tissue necrosis"]]'::jsonb, 'saq p.048 Q2a, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-91c6150b6f', 'pharm-antimetabolites', 'saq', 'Give 3 indications of methotrexate.', '[]'::jsonb, 'Any 3 of: acute lymphoblastic leukaemia; choriocarcinoma/gestational trophoblastic disease; non-Hodgkin lymphoma; osteosarcoma; breast cancer; rheumatoid arthritis; psoriasis; ectopic pregnancy/medical abortion; Crohn''s disease.', '[]'::jsonb, 'Methotrexate inhibits dihydrofolate reductase, blocking thymidylate and purine synthesis. High doses treat leukaemia, lymphoma, choriocarcinoma and osteosarcoma; low weekly doses are anti-inflammatory (through adenosine accumulation) in rheumatoid arthritis and psoriasis.', 'admin', 'published', 3, true, '[["acute lymphoblastic leukaemia", "all", "leukaemia", "leukemia"], ["choriocarcinoma", "trophoblastic disease"], ["lymphoma", "non-hodgkin lymphoma"], ["osteosarcoma"], ["breast cancer"], ["rheumatoid arthritis"], ["psoriasis"], ["ectopic pregnancy", "abortion"], ["crohn''s disease", "crohns"]]'::jsonb, 'saq p.048 Q2b, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-af556cb7b1', 'pharm-antiseizure-barbiturates-hydantoin', 'saq', 'Give 5 indications for phenytoin.', '[]'::jsonb, 'Generalised tonic-clonic seizures; focal (partial) seizures; status epilepticus (intravenous phenytoin or fosphenytoin); prevention of seizures after neurosurgery or head injury; trigeminal neuralgia; digoxin-induced arrhythmias (class IB antiarrhythmic).', '[]'::jsonb, 'Phenytoin blocks voltage-gated sodium channels in a use-dependent manner, stopping the spread of seizure discharges and suppressing ectopic firing in nerve and heart. It is ineffective in, and may worsen, absence and myoclonic seizures.', 'admin', 'published', 5, true, '[["tonic-clonic seizures", "generalised tonic clonic", "grand mal"], ["focal seizures", "partial seizures"], ["status epilepticus"], ["neurosurgery", "head injury", "seizure prophylaxis"], ["trigeminal neuralgia", "neuropathic pain"], ["arrhythmias", "digoxin toxicity", "digitalis arrhythmias", "antiarrhythmic"]]'::jsonb, 'saq p.048 Q2d, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-49b16177cb', 'pharm-drug-level-monitoring-and-interpretation', 'saq', 'Write down 4 drugs that require plasma level monitoring.', '[]'::jsonb, 'Any 4 of: digoxin; lithium; phenytoin; carbamazepine; aminoglycosides (gentamicin, amikacin); vancomycin; theophylline; ciclosporin; tacrolimus; methotrexate (high dose); phenobarbital; valproate.', '[]'::jsonb, 'Monitoring is worthwhile when a drug has a narrow therapeutic index, variable kinetics between patients, a good correlation between plasma level and effect, and no simple clinical measure of response. Warfarin is not on the list because it is monitored by its effect (INR).', 'admin', 'published', 2, true, '[["digoxin"], ["lithium"], ["phenytoin", "carbamazepine", "phenobarbital", "valproate"], ["gentamicin", "amikacin", "aminoglycosides"], ["vancomycin"], ["theophylline", "aminophylline"], ["ciclosporin", "cyclosporine", "tacrolimus"], ["methotrexate"]]'::jsonb, 'saq p.048 Q2e, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-8abd0753bf', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'saq', 'What is the mechanism of action of tacrolimus?', '[]'::jsonb, 'Tacrolimus binds the intracellular immunophilin FKBP-12; the complex inhibits calcineurin, so NFAT is not dephosphorylated and cannot enter the nucleus; transcription of interleukin-2 (and other cytokines) is blocked and T-cell activation and proliferation are suppressed.', '[]'::jsonb, 'Calcineurin is the phosphatase that activates the transcription factor NFAT after T-cell receptor stimulation. Tacrolimus and ciclosporin both inhibit it but through different binding proteins: FKBP-12 for tacrolimus, cyclophilin for ciclosporin.', 'admin', 'published', 2, true, '[["fkbp", "fk-binding protein", "fkbp-12", "immunophilin"], ["calcineurin inhibitor", "inhibits calcineurin", "calcineurin"], ["il-2", "interleukin-2", "nfat", "t-cell activation"]]'::jsonb, 'saq p.049 Q3a, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-ce17ffe609', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'saq', 'List four factors that determine the response to drugs applied topically on the skin.', '[]'::jsonb, '1. Regional variation in drug penetration (thin skin of face, scrotum and flexures absorbs more than palms and soles); 2. concentration gradient (higher drug concentration increases transfer); 3. dosing schedule (frequency and duration of application - the skin acts as a reservoir); 4. vehicle and occlusion (ointments and occlusive dressings increase penetration). Also the state of the skin (inflamed or broken skin, hydration) and age.', '[]'::jsonb, 'The stratum corneum is the main barrier. Absorption rises where it is thin or damaged, when it is hydrated by an ointment base or occlusion, and with a steeper concentration gradient. This is why potent steroids are avoided on the face and under nappies.', 'admin', 'published', 4, true, '[["regional variation", "site of application", "skin thickness", "body site"], ["concentration", "concentration gradient"], ["dosing schedule", "frequency of application", "duration of application"], ["vehicle", "formulation", "ointment"], ["occlusion", "occlusive dressing"], ["hydration", "skin condition", "broken skin", "inflammation"]]'::jsonb, 'saq p.049 Q3d, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-fae7b212cf', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'saq', 'Give 3 adverse effects of prolonged use of linezolid.', '[]'::jsonb, 'Any 3 of: bone marrow suppression - thrombocytopenia, anaemia, leucopenia; peripheral neuropathy; optic neuropathy (visual loss); lactic acidosis; serotonin syndrome with serotonergic drugs.', '[]'::jsonb, 'Linezolid inhibits bacterial protein synthesis at the 50S subunit but also inhibits mitochondrial ribosomes in human cells; after more than about two weeks this causes marrow suppression, neuropathies and lactic acidosis. It is also a weak MAO inhibitor.', 'admin', 'published', 3, true, '[["thrombocytopenia", "myelosuppression", "bone marrow suppression", "anaemia", "pancytopenia"], ["peripheral neuropathy"], ["optic neuropathy", "optic neuritis", "visual loss"], ["lactic acidosis"], ["serotonin syndrome"]]'::jsonb, 'saq p.049 Q3f, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-173b1845db', 'pharm-calcium-channel-blocker', 'saq', 'Which two calcium channel blocking drugs cause bradycardia?', '[]'::jsonb, 'Verapamil and diltiazem.', '[]'::jsonb, 'Verapamil (a phenylalkylamine) and diltiazem (a benzothiazepine) block L-type calcium channels in the SA and AV nodes as well as in vessels, slowing heart rate and conduction. Dihydropyridines such as nifedipine are vascular selective and cause reflex tachycardia instead.', 'admin', 'published', 2, true, '[["verapamil"], ["diltiazem"]]'::jsonb, 'saq p.050 Q4a, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-bdb57d9ce4', 'pharm-adrenoceptor-blockers', 'saq', 'Indicate one beta-adrenoceptor blocking drug that has each of the following properties: (i) dual alpha and beta antagonist; (ii) intrinsic vasodilator property; (iii) intrinsic sympathomimetic activity; (iv) selective beta-1 antagonist; (v) preferred in the treatment of heart failure.', '[]'::jsonb, '(i) Labetalol or carvedilol; (ii) nebivolol (nitric oxide release), or carvedilol/labetalol; (iii) pindolol or acebutolol; (iv) atenolol, metoprolol or bisoprolol; (v) carvedilol, bisoprolol or metoprolol succinate.', '[]'::jsonb, 'Beta-blockers differ in selectivity and extra properties. Partial agonists (pindolol, acebutolol) cause less resting bradycardia; third-generation agents vasodilate through alpha-1 block (carvedilol, labetalol) or nitric oxide release (nebivolol); only carvedilol, bisoprolol and metoprolol succinate have proven mortality benefit in heart failure.', 'admin', 'published', 5, true, '[["labetalol", "carvedilol"], ["nebivolol", "carvedilol", "celiprolol"], ["pindolol", "acebutolol", "oxprenolol"], ["atenolol", "metoprolol", "bisoprolol", "esmolol"], ["carvedilol", "bisoprolol", "metoprolol", "nebivolol"]]'::jsonb, 'saq p.050 Q4b, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-246f06a90e', 'pharm-anticoagulant-drugs', 'saq', 'List two fractionated (low molecular weight) heparins.', '[]'::jsonb, 'Any 2 of: enoxaparin; dalteparin; tinzaparin; nadroparin.', '[]'::jsonb, 'Low molecular weight heparins are short heparin chains that, with antithrombin, inhibit factor Xa much more than thrombin. They have predictable subcutaneous absorption, longer half-lives and need no routine aPTT monitoring; they are cleared by the kidney.', 'admin', 'published', 2, true, '[["enoxaparin"], ["dalteparin"], ["tinzaparin"], ["nadroparin", "certoparin", "reviparin"]]'::jsonb, 'saq p.050 Q4c, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-f7529f19e6', 'pharm-drug-interactions', 'saq', 'A patient stabilised on warfarin starts taking rifampicin. Would the warfarin dose most likely need to be increased or reduced?', '[]'::jsonb, 'Increased', '["increase", "increase the dose", "increased dose", "higher dose", "raise", "raised"]'::jsonb, 'Rifampicin is a powerful inducer of hepatic cytochrome P450 enzymes (CYP2C9, CYP3A4), so warfarin is metabolised faster and the INR falls. A higher dose is needed, and the dose must be cut back when rifampicin stops or bleeding may follow.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.050 Q4d(ii), MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-f7fe4edc1d', 'pharm-anticoagulant-drugs', 'saq', 'A patient on warfarin has an INR of 5. Would you increase or reduce the dose of warfarin?', '[]'::jsonb, 'Reduce', '["reduced", "reduce the dose", "decrease", "decreased", "lower", "withhold", "omit", "stop"]'::jsonb, 'The usual target INR is 2 to 3; a value of 5 means excessive anticoagulation and a high bleeding risk. One or two doses are withheld and the maintenance dose reduced; vitamin K is added if the INR is very high or there is bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.050 Q4d(iii), MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-b95910bdd1', 'pharm-effects-of-disease-on-drug-disposition', 'saq', 'A patient who needs warfarin has a low serum albumin. Would you likely increase or reduce the dose of warfarin?', '[]'::jsonb, 'Reduce', '["reduced", "reduce the dose", "decrease", "decreased", "lower", "lower dose"]'::jsonb, 'Warfarin is about 99% bound to albumin. With low albumin a larger fraction is free and active, and hypoalbuminaemia often reflects liver disease or malnutrition with reduced clotting factor synthesis, so such patients are more sensitive and need lower doses.', 'admin', 'draft', 1, false, '[]'::jsonb, 'saq p.050 Q4d(i), MBChB EOY 2019/2020. Expected exam answer is ''reduce''. Strictly, the free concentration at steady state depends on clearance rather than binding, so the pharmacokinetic argument is debated; clinically low albumin does predict over-anticoagulation.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-8d307ca17e', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'List four drugs used in the treatment of congestive heart failure, each from a different class of drugs, and name the class.', '[]'::jsonb, 'Any 4 of: ACE inhibitor - enalapril, lisinopril, captopril; angiotensin receptor blocker - losartan, valsartan; beta-blocker - carvedilol, bisoprolol, metoprolol; loop diuretic - furosemide; aldosterone antagonist - spironolactone, eplerenone; cardiac glycoside - digoxin; vasodilators - hydralazine with isosorbide dinitrate; angiotensin receptor-neprilysin inhibitor - sacubitril/valsartan; SGLT2 inhibitor - dapagliflozin, empagliflozin; ivabradine; thiazide diuretic.', '[]'::jsonb, 'Chronic heart failure treatment blocks harmful neurohormonal activation: ACE inhibitors or ARBs, beta-blockers, aldosterone antagonists and SGLT2 inhibitors all prolong life. Diuretics and digoxin relieve symptoms without improving survival. Doses of ACE inhibitors and beta-blockers are started low and increased slowly.', 'admin', 'published', 8, true, '[["ace inhibitor", "acei"], ["enalapril", "lisinopril", "captopril", "ramipril"], ["beta blocker", "beta-blocker"], ["carvedilol", "bisoprolol", "metoprolol"], ["loop diuretic", "diuretic", "thiazide"], ["furosemide", "frusemide", "bumetanide", "torsemide"], ["aldosterone antagonist", "spironolactone", "eplerenone"], ["cardiac glycoside", "digoxin"], ["arb", "losartan", "valsartan", "candesartan"], ["hydralazine", "isosorbide dinitrate", "nitrates", "vasodilator"], ["sacubitril", "arni"], ["sglt2 inhibitor", "dapagliflozin", "empagliflozin"], ["ivabradine"]]'::jsonb, 'saq p.050 Q4e, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-f2462f26e4', 'pharm-sedative-hypnotic-drugs', 'saq', 'Classify the drugs used as sedative-hypnotics, giving an example in each class.', '[]'::jsonb, 'Benzodiazepines - diazepam, lorazepam, midazolam, nitrazepam; barbiturates - phenobarbital, thiopental; non-benzodiazepine benzodiazepine-receptor agonists (Z-drugs) - zolpidem, zaleplon, zopiclone/eszopiclone; melatonin receptor agonists - ramelteon, melatonin; 5-HT1A partial agonist - buspirone (anxiolytic); orexin antagonists - suvorexant; miscellaneous - chloral hydrate, sedating antihistamines (promethazine), meprobamate.', '[]'::jsonb, 'Benzodiazepines, barbiturates and Z-drugs all enhance GABA-A receptor function but at different sites; Z-drugs are selective for alpha-1 containing receptors, so they are hypnotic with little anxiolytic or muscle relaxant effect. Ramelteon, buspirone and suvorexant act on entirely different receptors.', 'admin', 'published', 5, true, '[["benzodiazepines", "diazepam", "lorazepam", "midazolam", "nitrazepam"], ["barbiturates", "phenobarbital", "phenobarbitone", "thiopental"], ["z-drugs", "zolpidem", "zaleplon", "zopiclone", "eszopiclone"], ["melatonin agonists", "ramelteon", "melatonin"], ["buspirone", "5-ht1a agonist"], ["orexin antagonist", "suvorexant"], ["chloral hydrate", "antihistamines", "promethazine", "meprobamate"]]'::jsonb, 'saq p.051 Q5a, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-f83df16071', 'pharm-anti-fungals', 'saq', 'What is the mechanism of action of amphotericin B?', '[]'::jsonb, 'Amphotericin B binds to ergosterol in the fungal cell membrane and forms pores (channels), which increase membrane permeability so that potassium and other ions and small molecules leak out, killing the cell.', '[]'::jsonb, 'Amphotericin B is an amphipathic polyene: its lipophilic side binds ergosterol and its hydrophilic side lines an aqueous pore. Selectivity is incomplete because it also binds human cholesterol, which explains its nephrotoxicity. Azoles instead inhibit ergosterol synthesis.', 'admin', 'published', 2, true, '[["binds ergosterol", "ergosterol"], ["pores", "channels", "pore formation"], ["leakage", "increased permeability", "ion leakage", "potassium loss", "cell death"]]'::jsonb, 'saq p.051 Q5b, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-16e7889397', 'pharm-sympathomimetics-methylxanthines', 'saq', 'Give 3 examples of methylxanthines.', '[]'::jsonb, 'Any 3 of: theophylline; aminophylline (theophylline ethylenediamine); caffeine; theobromine; doxofylline; pentoxifylline.', '[]'::jsonb, 'Methylxanthines occur in tea (theophylline), coffee (caffeine) and cocoa (theobromine). They inhibit phosphodiesterase, raising cAMP, and block adenosine receptors, producing bronchodilation, CNS and cardiac stimulation and mild diuresis. Theophylline has a narrow therapeutic index: toxicity causes vomiting, arrhythmias and convulsions.', 'admin', 'published', 3, true, '[["theophylline"], ["aminophylline"], ["caffeine"], ["theobromine"], ["doxofylline", "pentoxifylline"]]'::jsonb, 'saq p.051 Q5c, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-6fe313d854', 'pharm-vinca-alkaloids-platinum-agents', 'saq', 'Give 3 adverse effects of cisplatin.', '[]'::jsonb, 'Any 3 of: nephrotoxicity; ototoxicity (tinnitus, high-frequency hearing loss); severe nausea and vomiting; peripheral neuropathy; electrolyte loss - hypomagnesaemia, hypokalaemia; mild myelosuppression.', '[]'::jsonb, 'Cisplatin is among the most emetogenic drugs and its dose-limiting toxicity is renal tubular damage, reduced by vigorous saline hydration (and amifostine). Carboplatin is less nephrotoxic, ototoxic and emetogenic but causes more myelosuppression.', 'admin', 'published', 3, true, '[["nephrotoxicity", "renal toxicity", "kidney damage"], ["ototoxicity", "hearing loss", "tinnitus", "deafness"], ["nausea", "vomiting", "emesis"], ["peripheral neuropathy", "neurotoxicity"], ["hypomagnesaemia", "hypomagnesemia", "electrolyte disturbance", "hypokalaemia"], ["myelosuppression"]]'::jsonb, 'saq p.051 Q5d, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-ccf21a77c3', 'pharm-macrolides', 'saq', 'Give 4 adverse effects of macrolide antibiotics.', '[]'::jsonb, 'Any 4 of: gastrointestinal upset - nausea, vomiting, abdominal cramps, diarrhoea; cholestatic hepatitis/jaundice (especially erythromycin estolate); QT prolongation and arrhythmias; drug interactions through CYP3A4 inhibition (erythromycin, clarithromycin); reversible ototoxicity at high doses; hypersensitivity rash; thrombophlebitis with intravenous use; infantile hypertrophic pyloric stenosis.', '[]'::jsonb, 'Erythromycin stimulates motilin receptors, causing cramps and diarrhoea. Macrolides block cardiac potassium channels (QT prolongation), and erythromycin and clarithromycin inhibit CYP3A4, raising levels of theophylline, warfarin, carbamazepine and statins. Azithromycin has few such interactions.', 'admin', 'published', 4, true, '[["nausea", "vomiting", "gi upset", "abdominal cramps", "diarrhoea", "epigastric distress"], ["cholestatic jaundice", "hepatitis", "hepatotoxicity", "cholestatic hepatitis"], ["qt prolongation", "arrhythmias", "torsades"], ["enzyme inhibition", "cyp3a4 inhibition", "drug interactions"], ["ototoxicity", "deafness", "hearing loss", "tinnitus"], ["rash", "hypersensitivity", "allergy"], ["thrombophlebitis"], ["pyloric stenosis"]]'::jsonb, 'saq p.051 Q5e, MBChB EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-d0a3c5172d', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'saq', 'Write down 3 indications for ergot alkaloids and give an example of a drug for each indication.', '[]'::jsonb, 'Any 3 of: acute migraine - ergotamine, dihydroergotamine; postpartum haemorrhage - ergometrine (ergonovine), methylergometrine; hyperprolactinaemia - bromocriptine, cabergoline; Parkinson''s disease - bromocriptine, pergolide; acromegaly - bromocriptine, cabergoline; (migraine prophylaxis - methysergide).', '[]'::jsonb, 'Ergot alkaloids act on alpha-adrenergic, serotonin and dopamine receptors in different proportions. Ergotamine is mainly a vasoconstrictor (migraine), ergometrine is selective for uterine muscle (postpartum haemorrhage), and bromocriptine and cabergoline are dopamine D2 agonists (hyperprolactinaemia, Parkinson''s disease).', 'admin', 'published', 3, true, '[["migraine", "ergotamine", "dihydroergotamine"], ["postpartum haemorrhage", "postpartum hemorrhage", "pph", "ergometrine", "ergonovine", "methylergometrine"], ["hyperprolactinaemia", "hyperprolactinemia", "prolactinoma", "cabergoline"], ["parkinson''s disease", "parkinsonism", "bromocriptine", "pergolide"], ["acromegaly"], ["methysergide"]]'::jsonb, 'saq p.051 Q5f, MBChB EOY 2019/2020. p.040 Q1d (MBChB 2020/2021) asks the same in reverse (ergot alkaloid for PPH, parkinsonism, hyperprolactinaemia); kept as one question.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-650585c37f', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'List four differences between hormones and autacoids.', '[]'::jsonb, '1. Site of production: hormones are made by specialised endocrine glands; autacoids are made by many different tissues and cells. 2. Site of action: hormones are carried in the blood to distant target organs; autacoids act locally at or near their site of synthesis (local hormones, paracrine). 3. Duration: hormones act for longer; autacoids are short-lived and rapidly destroyed locally. 4. Release: hormones are secreted to regulate normal physiological functions under feedback control; autacoids are formed or released on demand in response to stimuli such as injury, inflammation or allergy.', '[]'::jsonb, 'Autacoids (histamine, serotonin, prostaglandins, kinins) are ''self-remedies'': made on the spot, acting on neighbouring cells and destroyed within seconds to minutes. Classical hormones are released by a gland into the circulation to act on distant tissues.', 'admin', 'published', 4, true, '[["endocrine glands", "specific glands", "many tissues", "produced by various cells"], ["distant target", "carried in blood", "act locally", "local hormones", "paracrine", "site of synthesis"], ["short duration", "rapidly degraded", "short half-life", "long duration"], ["feedback control", "released on demand", "injury", "inflammation", "released on stimulation"], ["circulate", "systemic effects", "do not circulate"]]'::jsonb, 'saq p.053 Q1a, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-b404ee3467', 'pharm-sedative-hypnotic-drugs', 'saq', 'What is the mechanism of action of diazepam?', '[]'::jsonb, 'Diazepam binds to the benzodiazepine site on the GABA-A receptor (a positive allosteric modulator) and enhances the effect of GABA by increasing the frequency of chloride channel opening; chloride influx hyperpolarises the neurone and reduces its excitability.', '[]'::jsonb, 'Benzodiazepines need GABA to be present: they make the channel open more often but cannot open it themselves, which makes them safer in overdose. Barbiturates prolong the duration of opening and at high doses open the channel directly.', 'admin', 'published', 2, true, '[["gaba-a receptor", "gabaa", "benzodiazepine site", "gaba receptor", "potentiates gaba", "enhances gaba"], ["frequency of opening", "chloride channel", "chloride influx", "hyperpolarisation", "hyperpolarization"]]'::jsonb, 'saq p.053 Q1b, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-be2b9ca52e', 'pharm-eicosanoids', 'saq', 'List 4 products of arachidonic acid produced by enzymatic action following damage of membrane phospholipids.', '[]'::jsonb, 'Any 4 of: prostaglandins (PGE2, PGD2, PGF2-alpha); prostacyclin (PGI2); thromboxane A2; leukotrienes (LTB4, LTC4, LTD4); lipoxins; HETEs and epoxyeicosatrienoic acids (EETs).', '[]'::jsonb, 'Phospholipase A2 frees arachidonic acid from membrane phospholipids. Cyclo-oxygenase converts it to prostaglandins, prostacyclin and thromboxane; lipoxygenases produce leukotrienes and lipoxins; cytochrome P450 produces epoxides. Corticosteroids act upstream by inhibiting phospholipase A2.', 'admin', 'published', 4, true, '[["prostaglandins", "pge2", "pgd2", "pgf2 alpha"], ["prostacyclin", "pgi2"], ["thromboxane", "thromboxane a2", "txa2"], ["leukotrienes", "ltb4", "ltc4", "ltd4"], ["lipoxins"], ["hetes", "eets", "epoxyeicosatrienoic acids"]]'::jsonb, 'saq p.053 Q1e, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-c9c2bd9aeb', 'pharm-prostaglandins', 'saq', 'List 3 prostaglandins used in clinical practice and indicate one clinical use of each drug.', '[]'::jsonb, 'Any 3 of: misoprostol (PGE1 analogue) - prevention of NSAID-induced peptic ulcer, medical abortion, postpartum haemorrhage, cervical ripening; alprostadil (PGE1) - keeping the ductus arteriosus patent, erectile dysfunction; dinoprostone (PGE2) - cervical ripening and induction of labour; carboprost (15-methyl PGF2-alpha) - postpartum haemorrhage, abortion; latanoprost/travoprost/bimatoprost (PGF2-alpha analogues) - open-angle glaucoma; epoprostenol/iloprost (PGI2) - pulmonary arterial hypertension.', '[]'::jsonb, 'Each use follows from the natural action: PGE protects gastric mucosa, relaxes the ductus and softens the cervix; PGF2-alpha contracts the uterus and increases aqueous outflow; prostacyclin dilates pulmonary vessels and inhibits platelets.', 'admin', 'published', 6, true, '[["misoprostol"], ["peptic ulcer", "nsaid ulcer", "abortion", "postpartum haemorrhage"], ["alprostadil"], ["patent ductus arteriosus", "ductus patency", "erectile dysfunction"], ["dinoprostone", "induction of labour", "cervical ripening"], ["carboprost"], ["latanoprost", "travoprost", "bimatoprost", "glaucoma"], ["epoprostenol", "iloprost", "pulmonary hypertension"]]'::jsonb, 'saq p.053 Q1f, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-8afb374300', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'saq', 'List 4 classes of beta-lactam antibiotics.', '[]'::jsonb, 'Penicillins; cephalosporins (and cephamycins); carbapenems; monobactams.', '[]'::jsonb, 'All four share the beta-lactam ring, which binds penicillin-binding proteins and blocks peptidoglycan cross-linking. Examples: amoxicillin, ceftriaxone, meropenem and aztreonam. Beta-lactamase inhibitors also contain the ring but are not antibiotics in their own right.', 'admin', 'published', 4, true, '[["penicillins", "penicillin"], ["cephalosporins", "cephalosporin", "cephamycins"], ["carbapenems", "carbapenem"], ["monobactams", "monobactam", "aztreonam"]]'::jsonb, 'saq p.054 Q2a, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-04613d7a0e', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'Indicate 4 mechanisms of antibiotic resistance.', '[]'::jsonb, '1. Enzymatic inactivation or modification of the drug (e.g. beta-lactamases, aminoglycoside-modifying enzymes); 2. alteration of the drug target (altered penicillin-binding proteins in MRSA, ribosomal methylation, mutated DNA gyrase); 3. reduced permeability/decreased uptake (loss of porins); 4. active efflux of the drug (tetracycline efflux pumps); 5. development of an alternative metabolic pathway or overproduction of target (sulfonamide resistance).', '[]'::jsonb, 'Bacteria resist antibiotics by destroying the drug, changing its target, keeping it out or pumping it out, or bypassing the blocked step. The genes arise by mutation or are acquired on plasmids and transposons by conjugation, transduction or transformation.', 'admin', 'published', 4, true, '[["enzymatic inactivation", "beta-lactamase", "drug inactivation", "inactivating enzymes"], ["altered target", "target modification", "altered pbp", "target site alteration"], ["reduced permeability", "decreased uptake", "porin loss", "decreased entry"], ["efflux", "efflux pumps", "active efflux"], ["bypass pathway", "alternative pathway", "target overproduction"]]'::jsonb, 'saq p.054 Q2b, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-801e7d1a36', 'pharm-drug-interactions', 'saq', 'Give 4 distinct pharmacokinetic drug-drug interactions and 2 pharmacodynamic drug-drug interactions.', '[]'::jsonb, 'Pharmacokinetic: absorption - antacids or iron chelate tetracyclines and reduce their absorption; distribution - sulfonamides or aspirin displace warfarin (or bilirubin) from plasma albumin; metabolism - rifampicin induces enzymes and reduces the effect of oral contraceptives and warfarin, while cimetidine, erythromycin or ketoconazole inhibit enzymes and raise warfarin or theophylline levels; excretion - probenecid blocks tubular secretion of penicillin, thiazides reduce lithium clearance. Pharmacodynamic: additive/synergistic - alcohol with benzodiazepines (CNS depression), aspirin with warfarin (bleeding); antagonistic - naloxone with morphine, beta-blockers with salbutamol.', '[]'::jsonb, 'Pharmacokinetic interactions change how much of a drug reaches its site of action, at any of the four steps of absorption, distribution, metabolism and excretion. Pharmacodynamic interactions leave concentrations unchanged but add to or oppose the drug''s effect at the receptor or physiological level.', 'admin', 'published', 6, true, '[["absorption", "chelation", "antacids and tetracycline"], ["distribution", "protein binding displacement", "displacement"], ["metabolism", "enzyme induction", "enzyme inhibition", "rifampicin", "cimetidine"], ["excretion", "probenecid and penicillin", "renal excretion", "lithium and thiazides"], ["additive", "synergism", "alcohol and benzodiazepines", "aspirin and warfarin"], ["antagonism", "naloxone and morphine", "beta blocker and salbutamol"]]'::jsonb, 'saq p.054 Q2c, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-57f7b6a994', 'pharm-aldosterone-oxytocin-vasopressin', 'saq', 'List three clinical uses of oxytocin.', '[]'::jsonb, 'Induction of labour; augmentation of slow labour; prevention and control of postpartum haemorrhage (active management of the third stage). Also incomplete or inevitable abortion and, as a nasal spray, promotion of milk ejection.', '[]'::jsonb, 'Oxytocin acts on Gq-coupled receptors in the myometrium, which increase in number near term, producing rhythmic contractions that resemble normal labour. After delivery, sustained contraction compresses uterine vessels and stops bleeding.', 'admin', 'published', 3, true, '[["induction of labour", "induce labour", "induction of labor"], ["augmentation of labour", "augment labour", "slow labour"], ["postpartum haemorrhage", "postpartum hemorrhage", "pph", "third stage of labour"], ["milk ejection", "milk let-down", "lactation"], ["abortion", "incomplete abortion"]]'::jsonb, 'saq p.054 Q2d, MBChB special/supplementary 2019/2020. Also asked as ''Give two clinical uses of oxytocin'' on p.042 (MBChB 2020/2021).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-5c662e5103', 'pharm-aldosterone-oxytocin-vasopressin', 'saq', 'List three clinical uses of vasopressin or desmopressin.', '[]'::jsonb, 'Any 3 of: central (pituitary) diabetes insipidus; primary nocturnal enuresis; mild haemophilia A and von Willebrand disease (desmopressin raises factor VIII and von Willebrand factor); bleeding oesophageal varices (vasopressin/terlipressin); vasodilatory (septic) shock and cardiac arrest (vasopressin).', '[]'::jsonb, 'V2 receptor effects (water reabsorption in the collecting duct, release of factor VIII and von Willebrand factor) are obtained with the selective analogue desmopressin. V1 effects (vasoconstriction, especially splanchnic) are used in variceal bleeding and shock.', 'admin', 'published', 3, true, '[["diabetes insipidus", "central diabetes insipidus"], ["nocturnal enuresis", "bedwetting", "enuresis"], ["haemophilia a", "hemophilia", "von willebrand disease"], ["oesophageal varices", "esophageal varices", "variceal bleeding"], ["septic shock", "vasodilatory shock", "cardiac arrest"]]'::jsonb, 'saq p.054 Q2e, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-36a354033b', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'Give three adverse effects of spironolactone.', '[]'::jsonb, 'Any 3 of: hyperkalaemia; gynaecomastia; impotence and reduced libido in men; menstrual irregularities and breast tenderness in women; hyperchloraemic metabolic acidosis; gastrointestinal upset; hyponatraemia.', '[]'::jsonb, 'Spironolactone blocks aldosterone receptors in the collecting duct, so potassium and hydrogen ions are retained. It also blocks androgen receptors and has progestogenic activity, causing the endocrine effects; eplerenone is more selective and avoids these.', 'admin', 'published', 3, true, '[["hyperkalaemia", "hyperkalemia"], ["gynaecomastia", "gynecomastia"], ["impotence", "erectile dysfunction", "decreased libido"], ["menstrual irregularities", "menstrual disturbance", "breast tenderness"], ["metabolic acidosis"], ["gi upset", "nausea", "peptic ulcer"], ["hyponatraemia"]]'::jsonb, 'saq p.055 Q3a, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-69331d229a', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'saq', 'A farmer is brought in unconscious with miosis, profuse sweating and excessive bronchial secretions. Which class of poison is most likely responsible?', '[]'::jsonb, 'Organophosphate', '["organophosphates", "organophosphorus", "organophosphorus compound", "organophosphate insecticide", "organophosphate pesticide", "organophosphorus insecticide", "OP", "organophosphate poisoning"]'::jsonb, 'Pinpoint pupils, sweating, salivation and bronchorrhoea are muscarinic signs of acetylcholine excess. In a farmer the usual cause is an organophosphate insecticide, which inhibits acetylcholinesterase. Opioids also cause miosis and coma but with dry skin and slow breathing.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.055 Q3b(i), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-fbd409fed1', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'saq', 'A farmer is brought in unconscious with miosis, profuse sweating and bronchial secretions; organophosphate poisoning is suspected. Give two examples of organophosphates and explain the mechanism of action of the poison.', '[]'::jsonb, 'Examples (any 2): malathion, parathion, diazinon, chlorpyrifos, dichlorvos, dimethoate. Mechanism: organophosphates phosphorylate the serine at the active site of acetylcholinesterase, inhibiting it irreversibly (the bond ''ages''); acetylcholine accumulates at muscarinic and nicotinic synapses and in the CNS, causing a cholinergic crisis.', '[]'::jsonb, 'With acetylcholinesterase blocked, acetylcholine overstimulates muscarinic receptors (miosis, secretions, bradycardia, bronchospasm), nicotinic receptors (fasciculation, then paralysis) and the brain (coma, convulsions). Death is from respiratory failure. Carbamate insecticides act similarly but the inhibition reverses spontaneously.', 'admin', 'published', 4, true, '[["malathion", "parathion", "diazinon", "chlorpyrifos", "dichlorvos", "dimethoate"], ["inhibit acetylcholinesterase", "cholinesterase inhibition", "anticholinesterase", "inhibits ache"], ["irreversible", "phosphorylation", "ageing", "aging"], ["acetylcholine accumulates", "accumulation of acetylcholine", "excess acetylcholine", "cholinergic crisis"]]'::jsonb, 'saq p.055 Q3b(i), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-3893ae79af', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'saq', 'A farmer has organophosphate poisoning. List two drugs you would use to reduce the effects of the poison and give the mechanism of action of each.', '[]'::jsonb, '1. Atropine - competitive antagonist at muscarinic receptors; blocks the muscarinic effects of excess acetylcholine (secretions, bronchospasm, bradycardia); given in repeated large doses until secretions dry. 2. Pralidoxime (or obidoxime) - cholinesterase reactivator; removes the phosphate group from acetylcholinesterase, restoring enzyme activity, provided it is given before ageing; reverses nicotinic effects as well. (Diazepam for convulsions.)', '[]'::jsonb, 'Atropine treats only muscarinic signs; it does nothing for muscle weakness because that is nicotinic. Oximes regenerate the enzyme itself but must be given early, before the phosphorylated enzyme ages into a form that cannot be reactivated.', 'admin', 'published', 4, true, '[["atropine"], ["muscarinic antagonist", "blocks muscarinic receptors", "antimuscarinic", "anticholinergic"], ["pralidoxime", "obidoxime", "oxime", "2-pam"], ["reactivates cholinesterase", "cholinesterase reactivator", "regenerates acetylcholinesterase", "reactivates ache"], ["diazepam"]]'::jsonb, 'saq p.055 Q3b(ii), MBChB special/supplementary 2019/2020. p.032 Q3f (BDS 2021/2022) asks only for the two drug names; kept as this fuller version.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-536cbdcf4f', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'Enumerate 5 clinical uses of opioids.', '[]'::jsonb, 'Any 5 of: relief of severe acute pain (postoperative, trauma, myocardial infarction) and cancer pain; acute pulmonary oedema/left ventricular failure (morphine); cough suppression (codeine, dextromethorphan); treatment of diarrhoea (loperamide, diphenoxylate); preanaesthetic medication and as an adjunct in anaesthesia (fentanyl); maintenance treatment of opioid dependence (methadone, buprenorphine); obstetric analgesia (pethidine).', '[]'::jsonb, 'Besides analgesia, opioid actions used clinically are suppression of the cough reflex, slowing of gut motility, and, in acute pulmonary oedema, venodilation with relief of anxiety and breathlessness. Long-acting agonists substitute for heroin in dependence.', 'admin', 'published', 5, true, '[["analgesia", "severe pain", "pain relief", "cancer pain", "postoperative pain"], ["pulmonary oedema", "pulmonary edema", "left ventricular failure"], ["cough suppression", "antitussive", "cough"], ["diarrhoea", "diarrhea", "antidiarrhoeal"], ["anaesthesia", "premedication", "anesthesia adjunct"], ["opioid dependence", "methadone maintenance", "addiction treatment"], ["myocardial infarction"], ["labour pain", "obstetric analgesia"]]'::jsonb, 'saq p.055 Q3c, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-bb9c3f43a9', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'saq', 'Name three opioid antagonists.', '[]'::jsonb, 'Any 3 of: naloxone; naltrexone; nalmefene; methylnaltrexone; alvimopan; naloxegol.', '[]'::jsonb, 'Naloxone is short acting and given parenterally to reverse overdose; naltrexone is oral and long acting, used to maintain abstinence in opioid and alcohol dependence. Methylnaltrexone and alvimopan do not enter the brain and treat opioid-induced constipation.', 'admin', 'published', 3, true, '[["naloxone"], ["naltrexone"], ["nalmefene"], ["methylnaltrexone", "alvimopan", "naloxegol"]]'::jsonb, 'saq p.055 Q3d, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-a4707ad381', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'saq', 'Classify drugs used in the treatment of asthma, giving one example in each class.', '[]'::jsonb, 'Bronchodilators: beta-2 agonists - salbutamol (short acting), salmeterol, formoterol (long acting); methylxanthines - theophylline, aminophylline; antimuscarinics - ipratropium, tiotropium. Anti-inflammatory/controllers: corticosteroids - beclometasone, budesonide, fluticasone (inhaled), prednisolone (oral); leukotriene modifiers - montelukast, zafirlukast, zileuton; mast cell stabilisers - sodium cromoglicate, nedocromil; anti-IgE antibody - omalizumab.', '[]'::jsonb, 'Asthma drugs are either relievers that relax bronchial smooth muscle (beta-2 agonists, antimuscarinics, methylxanthines) or controllers that reduce airway inflammation (corticosteroids, leukotriene modifiers, cromones, anti-IgE). Inhaled corticosteroids are the foundation of long-term control.', 'admin', 'published', 5, true, '[["beta-2 agonists", "beta agonists", "salbutamol", "albuterol", "salmeterol", "formoterol"], ["methylxanthines", "theophylline", "aminophylline"], ["antimuscarinics", "anticholinergics", "ipratropium", "tiotropium"], ["corticosteroids", "beclometasone", "budesonide", "fluticasone", "prednisolone"], ["leukotriene antagonists", "leukotriene modifiers", "montelukast", "zafirlukast", "zileuton"], ["mast cell stabilisers", "cromoglicate", "cromolyn", "nedocromil"], ["anti-ige", "omalizumab"]]'::jsonb, 'saq p.056 Q4a, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-f0024d7856', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'What is the mechanism of action of aspirin?', '[]'::jsonb, 'Aspirin irreversibly inhibits cyclo-oxygenase (COX-1 and COX-2) by acetylating a serine residue at the active site, reducing synthesis of prostaglandins and thromboxane A2 (hence its anti-inflammatory, analgesic, antipyretic and antiplatelet effects).', '[]'::jsonb, 'Other NSAIDs inhibit COX reversibly; aspirin''s covalent acetylation is permanent. Platelets have no nucleus and cannot make new enzyme, so a single low dose suppresses thromboxane for the platelet''s 7 to 10 day lifespan, while endothelium resynthesises COX and prostacyclin.', 'admin', 'published', 2, true, '[["irreversible", "acetylation", "acetylates"], ["cyclooxygenase", "cox", "cox-1", "inhibits cox"], ["prostaglandin synthesis", "thromboxane", "thromboxane a2", "reduced prostaglandins"]]'::jsonb, 'saq p.056 Q4b, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-88b6924039', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'List 4 distinct indications of aspirin therapy.', '[]'::jsonb, 'Any 4 of: mild to moderate pain (headache, dental pain, dysmenorrhoea); fever; inflammatory conditions - rheumatic fever, rheumatoid arthritis; antiplatelet therapy - acute myocardial infarction, secondary prevention of myocardial infarction and ischaemic stroke/TIA; Kawasaki disease; prevention of pre-eclampsia; reduction of colorectal cancer risk.', '[]'::jsonb, 'Low doses (75 to 150 mg) are antiplatelet, intermediate doses analgesic and antipyretic, and high doses anti-inflammatory. Aspirin is avoided in children with viral illness because of Reye''s syndrome, Kawasaki disease being the exception.', 'admin', 'published', 4, true, '[["analgesic", "pain", "headache"], ["antipyretic", "fever"], ["anti-inflammatory", "rheumatic fever", "rheumatoid arthritis"], ["antiplatelet", "myocardial infarction", "stroke prevention", "thrombosis prevention", "tia"], ["kawasaki disease"], ["pre-eclampsia", "preeclampsia"], ["colorectal cancer"]]'::jsonb, 'saq p.056 Q4c, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-9b1bb0c5e6', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Indicate 3 adverse effects associated with prednisolone.', '[]'::jsonb, 'Any 3 of: Cushingoid features (moon face, central obesity, striae) and weight gain; hyperglycaemia/diabetes; osteoporosis and fractures; increased susceptibility to infection; peptic ulceration; hypertension and fluid retention, hypokalaemia; adrenal suppression; proximal myopathy; cataracts and glaucoma; mood change/psychosis; poor wound healing and skin thinning; growth retardation in children.', '[]'::jsonb, 'Long-term glucocorticoid toxicity is an exaggeration of physiological actions: gluconeogenesis, protein catabolism in muscle, skin and bone, fat redistribution, mineralocorticoid sodium retention, immunosuppression and feedback suppression of the hypothalamic-pituitary-adrenal axis.', 'admin', 'published', 3, true, '[["cushingoid", "cushing''s syndrome", "moon face", "weight gain"], ["hyperglycaemia", "hyperglycemia", "diabetes"], ["osteoporosis", "fractures"], ["infection", "immunosuppression"], ["peptic ulcer"], ["hypertension", "fluid retention", "hypokalaemia"], ["adrenal suppression", "hpa suppression"], ["myopathy", "muscle wasting"], ["cataracts", "glaucoma"], ["psychosis", "mood changes", "euphoria"], ["poor wound healing", "skin thinning", "striae"], ["growth retardation"]]'::jsonb, 'saq p.056 Q4d(ii), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-d8e01252d5', 'pharm-aminoglycosides', 'saq', 'Indicate 3 adverse effects associated with gentamicin.', '[]'::jsonb, 'Nephrotoxicity (acute tubular necrosis, usually reversible); ototoxicity - vestibular (vertigo, ataxia) and cochlear (tinnitus, deafness), often irreversible; neuromuscular blockade (respiratory paralysis at high doses, worsens myasthenia gravis). Also hypersensitivity rash.', '[]'::jsonb, 'Aminoglycosides accumulate in renal proximal tubule cells and in inner ear hair cells, damaging both in relation to dose and duration, which is why trough levels are monitored. They also inhibit presynaptic acetylcholine release, producing curare-like paralysis.', 'admin', 'published', 3, true, '[["nephrotoxicity", "renal toxicity", "kidney damage", "acute tubular necrosis"], ["ototoxicity", "deafness", "hearing loss", "vestibular toxicity", "vertigo", "tinnitus"], ["neuromuscular blockade", "muscle paralysis", "respiratory paralysis"], ["rash", "hypersensitivity"]]'::jsonb, 'saq p.056 Q4d(iii), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-52bd92ddcb', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'saq', 'Classify drugs used in the treatment of peptic ulcer disease, giving 2 examples in each class.', '[]'::jsonb, '1. Drugs that reduce acid secretion: proton pump inhibitors - omeprazole, esomeprazole, lansoprazole, pantoprazole; H2-receptor antagonists - ranitidine, cimetidine, famotidine; antimuscarinics - pirenzepine. 2. Antacids (neutralise acid): aluminium hydroxide, magnesium hydroxide, calcium carbonate, sodium bicarbonate. 3. Mucosal protective (cytoprotective) agents: sucralfate, bismuth compounds, misoprostol (prostaglandin analogue). 4. Anti-Helicobacter pylori antimicrobials: clarithromycin, amoxicillin, metronidazole, tetracycline.', '[]'::jsonb, 'Ulcer treatment either reduces acid (proton pump inhibitors are most effective, blocking the final step of secretion), neutralises it, strengthens mucosal defence, or removes the cause by eradicating Helicobacter pylori with triple therapy: a PPI plus two antibiotics.', 'admin', 'published', 6, true, '[["proton pump inhibitors", "ppi", "omeprazole", "esomeprazole", "lansoprazole", "pantoprazole"], ["h2 antagonists", "h2 blockers", "ranitidine", "cimetidine", "famotidine"], ["antacids", "aluminium hydroxide", "magnesium hydroxide", "calcium carbonate", "sodium bicarbonate"], ["cytoprotective", "mucosal protective", "sucralfate", "bismuth"], ["prostaglandin analogue", "misoprostol"], ["h. pylori eradication", "antibiotics", "clarithromycin", "amoxicillin", "metronidazole"], ["antimuscarinic", "pirenzepine"]]'::jsonb, 'saq p.057 Q5a, MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-c1e45ed47c', 'pharm-biotransformation', 'saq', 'List 2 drugs that are hepatic microsomal enzyme inducers.', '[]'::jsonb, 'Any 2 of: rifampicin; phenytoin; carbamazepine; phenobarbital (barbiturates); griseofulvin; St John''s wort; efavirenz, nevirapine; chronic alcohol use; cigarette smoke.', '[]'::jsonb, 'Inducers increase the synthesis of cytochrome P450 enzymes over days to weeks, speeding the metabolism of other drugs such as warfarin and oral contraceptives and causing treatment failure. Rifampicin is the most potent in clinical use.', 'admin', 'published', 2, true, '[["rifampicin", "rifampin"], ["phenytoin"], ["carbamazepine"], ["phenobarbital", "phenobarbitone", "barbiturates"], ["griseofulvin"], ["st john''s wort"], ["efavirenz", "nevirapine"], ["alcohol", "ethanol", "smoking"]]'::jsonb, 'saq p.057 Q5c(i), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-790cb3861c', 'pharm-biotransformation', 'saq', 'List 2 drugs that are hepatic microsomal enzyme inhibitors.', '[]'::jsonb, 'Any 2 of: cimetidine; erythromycin, clarithromycin; ketoconazole, fluconazole, itraconazole; ciprofloxacin; isoniazid; ritonavir; chloramphenicol; sodium valproate; omeprazole; metronidazole; amiodarone; fluoxetine; grapefruit juice.', '[]'::jsonb, 'Enzyme inhibition begins within hours, as soon as the inhibitor reaches the liver, and raises the concentration of co-administered drugs: for example warfarin, theophylline or phenytoin toxicity after starting erythromycin or cimetidine.', 'admin', 'published', 2, true, '[["cimetidine"], ["erythromycin", "clarithromycin"], ["ketoconazole", "fluconazole", "itraconazole"], ["ciprofloxacin"], ["isoniazid"], ["ritonavir"], ["chloramphenicol"], ["valproate", "valproic acid"], ["omeprazole"], ["metronidazole", "amiodarone", "fluoxetine", "grapefruit juice", "allopurinol", "disulfiram"]]'::jsonb, 'saq p.057 Q5c(ii), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-ad8955e366', 'pharm-genetic-medicine', 'saq', 'List 2 drugs that cause haemolysis in G6PD-deficient patients.', '[]'::jsonb, 'Any 2 of: primaquine; dapsone; sulfonamides (sulfamethoxazole/co-trimoxazole); nitrofurantoin; rasburicase; methylene blue; quinine/chloroquine (higher risk variants); nalidixic acid.', '[]'::jsonb, 'G6PD supplies the NADPH that keeps glutathione reduced. Without it red cells cannot detoxify the peroxides generated by oxidant drugs, so haemoglobin precipitates as Heinz bodies and the cells lyse. G6PD status is checked before giving primaquine.', 'admin', 'published', 2, true, '[["primaquine", "tafenoquine"], ["dapsone"], ["sulfonamides", "sulfamethoxazole", "co-trimoxazole", "sulphonamides"], ["nitrofurantoin"], ["rasburicase"], ["methylene blue"], ["quinine", "chloroquine", "nalidixic acid"]]'::jsonb, 'saq p.057 Q5c(iii), MBChB special/supplementary 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-1d0d344c6c', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'saq', 'List four antimalarial drugs used in chemoprophylaxis.', '[]'::jsonb, 'Any 4 of: atovaquone-proguanil (Malarone); doxycycline; mefloquine; chloroquine (areas without resistance); proguanil; primaquine; tafenoquine; (sulfadoxine-pyrimethamine as intermittent preventive treatment in pregnancy).', '[]'::jsonb, 'For travellers to areas with chloroquine-resistant Plasmodium falciparum, including Kenya, the choices are atovaquone-proguanil, doxycycline or mefloquine. Atovaquone-proguanil and primaquine kill liver stages, so they can be stopped one week after leaving; the others must continue for four weeks.', 'admin', 'published', 4, true, '[["atovaquone-proguanil", "malarone", "atovaquone"], ["doxycycline"], ["mefloquine"], ["chloroquine"], ["proguanil"], ["primaquine", "tafenoquine"], ["sulfadoxine-pyrimethamine", "sp", "fansidar"]]'::jsonb, 'saq p.057 Q5d, MBChB special/supplementary 2019/2020. Also asked as ''Indicate 3 drugs used in Plasmodium falciparum malaria chemoprophylaxis'' on p.047 (MBChB EOY 2019/2020).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-0856dfa865', 'pharm-sulfonamides-and-related-compounds', 'saq', 'List 3 oral absorbable sulphonamides.', '[]'::jsonb, 'Any 3 of: sulfamethoxazole; sulfadiazine; sulfisoxazole (sulfafurazole); sulfadoxine; sulfamethizole; sulfadimidine.', '[]'::jsonb, 'Oral absorbable sulfonamides are grouped by half-life: short (sulfisoxazole), intermediate (sulfamethoxazole, sulfadiazine) and long (sulfadoxine). Sulfasalazine is oral but poorly absorbed and acts in the gut; silver sulfadiazine and sulfacetamide are topical.', 'admin', 'published', 3, true, '[["sulfamethoxazole", "sulphamethoxazole"], ["sulfadiazine", "sulphadiazine"], ["sulfisoxazole", "sulfafurazole", "sulphafurazole"], ["sulfadoxine", "sulphadoxine"], ["sulfamethizole", "sulfadimidine", "sulphadimidine"]]'::jsonb, 'saq p.059 Q1a, BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-be56873f04', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Write down the name of an aminoglycoside used for the treatment of amoebiasis.', '[]'::jsonb, 'Paromomycin', '["paromomycin sulfate", "paromomycin sulphate", "aminosidine", "Humatin"]'::jsonb, 'Paromomycin is not absorbed from the gut, so it reaches high concentrations in the lumen, where it kills Entamoeba histolytica trophozoites and cysts. It is a luminal amoebicide, used alone for cyst passers or after metronidazole in invasive disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.059 Q1b(i), BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-fa404d2407', 'pharm-aminoglycosides', 'saq', 'Which aminoglycoside is classically given by mouth in hepatic coma to reduce ammonia-producing gut bacteria?', '[]'::jsonb, 'Neomycin', '["neomycin sulfate", "neomycin sulphate", "oral neomycin", "paromomycin"]'::jsonb, 'Oral neomycin is hardly absorbed and suppresses the urease-producing colonic bacteria that generate ammonia, lowering the nitrogen load in hepatic encephalopathy. Lactulose and rifaximin are now preferred because some neomycin is absorbed and can cause oto- and nephrotoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.059 Q1b(ii), BDS III EOY 2019/2020. Reworded from ''aminoglycoside used for hepatic coma''. Paromomycin (and kanamycin) can be used the same way; neomycin is the standard answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-cec1b5e9a4', 'pharm-quinolones', 'saq', 'Give 1 example of a respiratory fluoroquinolone.', '[]'::jsonb, 'Any one of: levofloxacin; moxifloxacin; gemifloxacin; gatifloxacin.', '[]'::jsonb, 'Respiratory fluoroquinolones have enhanced activity against Streptococcus pneumoniae and atypical organisms, so they can treat community-acquired pneumonia. Ciprofloxacin is not one: its pneumococcal activity is poor, though it is the best quinolone against Pseudomonas.', 'admin', 'published', 1, true, '[["levofloxacin", "moxifloxacin", "gemifloxacin", "gatifloxacin", "sparfloxacin"]]'::jsonb, 'saq p.059 Q1c, BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-4b6800e5ed', 'pharm-adverse-drug-reactions', 'saq', 'List 2 points that describe type A adverse drug reactions.', '[]'::jsonb, 'Any 2 of: dose-dependent (augmented); predictable from the known pharmacology of the drug; common; usually low mortality; reversible on reducing the dose or withdrawing the drug.', '[]'::jsonb, 'Type A (augmented) reactions are exaggerations of the drug''s normal pharmacological action, so they are predictable, dose related and account for most adverse reactions. They are managed by lowering the dose, unlike type B reactions, which require stopping the drug.', 'admin', 'published', 2, true, '[["dose dependent", "dose related", "augmented"], ["predictable", "related to pharmacology", "extension of pharmacological effect"], ["common"], ["low mortality", "rarely fatal"], ["reversible", "dose reduction", "managed by reducing dose"]]'::jsonb, 'saq p.059 Q1d(i), BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-5d66f4e029', 'pharm-adverse-drug-reactions', 'saq', 'Give an example of a type A adverse drug reaction together with the associated drug.', '[]'::jsonb, 'Any one, e.g.: hypoglycaemia with insulin or sulfonylureas; bleeding with warfarin or heparin; respiratory depression with morphine; bradycardia with propranolol; postural hypotension with antihypertensives; dry mouth with atropine or tricyclic antidepressants.', '[]'::jsonb, 'A type A reaction is simply too much of the drug''s expected effect: too much glucose lowering, too much anticoagulation. Anaphylaxis to penicillin or halothane hepatitis are type B and would not earn the mark.', 'admin', 'published', 1, true, '[["hypoglycaemia", "hypoglycemia", "insulin", "bleeding", "warfarin", "heparin", "respiratory depression", "morphine", "bradycardia", "hypotension", "dry mouth"]]'::jsonb, 'saq p.059 Q1d(ii), BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-a16cf51300', 'pharm-g-proteins-and-second-messengers', 'saq', 'Give 3 examples of second messengers.', '[]'::jsonb, 'Any 3 of: cyclic AMP (cAMP); cyclic GMP (cGMP); inositol trisphosphate (IP3); diacylglycerol (DAG); calcium ions (Ca2+).', '[]'::jsonb, 'The drug or hormone is the first messenger; second messengers are small intracellular molecules generated when the receptor is activated. Gs and Gi raise or lower cAMP through adenylyl cyclase, while Gq activates phospholipase C to produce IP3 (which releases calcium) and DAG.', 'admin', 'published', 3, true, '[["camp", "cyclic amp"], ["cgmp", "cyclic gmp"], ["ip3", "inositol trisphosphate", "inositol triphosphate"], ["dag", "diacylglycerol"], ["calcium", "ca2+", "calcium ions"]]'::jsonb, 'saq p.059 Q1e, BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-c3998a33fb', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'saq', 'What term describes the study of what a drug does to the body, that is, its effects and mechanism of action?', '[]'::jsonb, 'Pharmacodynamics', '["pharmacodynamic", "pharmaco-dynamics", "PD"]'::jsonb, 'Pharmacodynamics covers the biochemical and physiological effects of drugs and how they are produced (receptors, dose-response). Pharmacokinetics is the reverse: what the body does to the drug through absorption, distribution, metabolism and excretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.059 Q1f, BDS III EOY 2019/2020. Reworded from ''Define pharmacodynamics (1 mark)'' so that it has a single short answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-66d4006f45', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'saq', 'List 3 disadvantages of the rectal route of drug administration.', '[]'::jsonb, 'Any 3 of: absorption is erratic, incomplete and unpredictable; inconvenient, embarrassing and poorly accepted by patients; irritation or inflammation of the rectal mucosa; unsuitable in diarrhoea or painful anorectal conditions (haemorrhoids, fissures); small absorbing surface area; the suppository may be expelled.', '[]'::jsonb, 'The rectum has a small surface without villi and the drug may be mixed with faeces, so absorption is variable. Its advantages are use in vomiting or unconscious patients and partial avoidance of first-pass metabolism, since the lower rectal veins drain to the systemic circulation.', 'admin', 'published', 3, true, '[["erratic absorption", "unpredictable absorption", "incomplete absorption", "variable absorption"], ["inconvenient", "embarrassing", "poor acceptability", "not acceptable"], ["irritation", "rectal irritation", "proctitis"], ["diarrhoea", "haemorrhoids", "anal fissures"], ["small surface area"], ["expelled", "leakage"]]'::jsonb, 'saq p.059 Q1g, BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-92ae12a8be', 'pharm-absorption', 'saq', 'List 2 factors that affect drug absorption and briefly explain the effect of each.', '[]'::jsonb, 'Any 2, each explained: lipid solubility and ionisation (pKa and pH) - non-ionised, lipid-soluble drugs cross membranes more readily; surface area of the absorbing site - larger area (small intestine) gives faster absorption; blood flow to the site - greater flow maintains the concentration gradient and increases absorption; drug concentration at the site - higher concentration increases passive diffusion; dosage form/formulation - solutions are absorbed faster than tablets, and disintegration and dissolution are rate limiting; gastric emptying and gut motility; presence of food or other drugs; molecular size.', '[]'::jsonb, 'Most drugs are absorbed by passive diffusion, which follows Fick''s law: the rate rises with the concentration gradient, surface area and membrane permeability (lipid solubility, non-ionised form). Blood flow keeps the gradient steep by carrying absorbed drug away.', 'admin', 'published', 4, true, '[["lipid solubility", "ionisation", "ionization", "ph", "pka", "physicochemical properties"], ["surface area"], ["blood flow", "perfusion"], ["concentration", "concentration gradient"], ["dosage form", "formulation", "dissolution"], ["gastric emptying", "gut motility"], ["food", "other drugs", "chelation"], ["molecular size", "particle size"]]'::jsonb, 'saq p.059 Q1h, BDS III EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-ff0e8cf3b8', 'pharm-antiarrhythmic-drugs', 'saq', 'List 2 examples of Vaughan-Williams class IV anti-arrhythmic drugs.', '[]'::jsonb, 'Verapamil; diltiazem.', '[]'::jsonb, 'Class IV agents are the non-dihydropyridine calcium channel blockers. They slow conduction and prolong refractoriness in the SA and AV nodes, which depend on calcium currents. Dihydropyridines such as nifedipine act mainly on vessels and have no useful anti-arrhythmic effect.', 'admin', 'published', 2, true, '[["verapamil"], ["diltiazem"]]'::jsonb, 'saq p.061 Q2a, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-06f8249865', 'pharm-antiarrhythmic-drugs', 'saq', 'Give 3 adverse effects of amiodarone.', '[]'::jsonb, 'Any 3 of: pulmonary fibrosis; hypothyroidism or hyperthyroidism; corneal microdeposits; photosensitivity and blue-grey skin discolouration; hepatotoxicity; peripheral neuropathy; bradycardia and heart block; QT prolongation.', '[]'::jsonb, 'Amiodarone is highly lipophilic, iodine-rich and has a half-life of weeks, so it accumulates in lung, liver, skin, cornea and thyroid. Its iodine content and inhibition of T4 to T3 conversion explain the thyroid disturbances; pulmonary fibrosis is the most feared toxicity.', 'admin', 'published', 3, true, '[["pulmonary fibrosis", "lung fibrosis", "pneumonitis"], ["hypothyroidism", "hyperthyroidism", "thyroid"], ["corneal deposits", "corneal microdeposits", "optic neuritis"], ["photosensitivity", "skin discolouration", "blue-grey skin", "skin pigmentation"], ["hepatotoxicity", "liver", "hepatitis"], ["neuropathy", "tremor", "ataxia"], ["bradycardia", "heart block", "qt prolongation"]]'::jsonb, 'saq p.061 Q2b, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-2ffa9b4565', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'Mention 3 contraindications of furosemide (frusemide).', '[]'::jsonb, 'Any 3 of: anuria or renal failure not responding to the drug; severe hypokalaemia or hyponatraemia; hypovolaemia or dehydration; hypersensitivity to sulphonamides; hepatic coma or precoma (cirrhosis with encephalopathy).', '[]'::jsonb, 'Furosemide causes brisk loss of sodium, potassium and water, so it worsens existing volume or electrolyte depletion and, through hypokalaemic alkalosis, can precipitate hepatic encephalopathy. It is a sulphonamide derivative, hence cross-allergy, and it is useless once the kidney makes no urine.', 'admin', 'published', 3, true, '[["anuria", "anuric renal failure"], ["hypokalaemia", "hypokalemia", "hyponatraemia", "electrolyte depletion"], ["hypovolaemia", "dehydration", "hypotension"], ["sulphonamide allergy", "sulfa allergy", "sulfonamide hypersensitivity", "hypersensitivity"], ["hepatic coma", "hepatic encephalopathy", "liver cirrhosis"]]'::jsonb, 'saq p.061 Q2c, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-7d97eafbb1', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List 3 examples of potassium-sparing diuretics.', '[]'::jsonb, 'Any 3 of: spironolactone; eplerenone; amiloride; triamterene.', '[]'::jsonb, 'Spironolactone and eplerenone block the aldosterone (mineralocorticoid) receptor in the collecting duct, while amiloride and triamterene directly block the epithelial sodium channel (ENaC). Both mechanisms reduce sodium reabsorption and therefore the potassium and hydrogen ion secretion that depends on it.', 'admin', 'published', 3, true, '[["spironolactone"], ["eplerenone"], ["amiloride"], ["triamterene"]]'::jsonb, 'saq p.061 Q2d(i), BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-f8222199fd', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'Give 3 adverse effects of potassium-sparing diuretics.', '[]'::jsonb, 'Any 3 of: hyperkalaemia; hyperchloraemic metabolic acidosis; gynaecomastia, impotence and menstrual irregularity (spironolactone); gastrointestinal upset; kidney stones (triamterene); acute renal failure (triamterene with indomethacin).', '[]'::jsonb, 'Reduced sodium entry in the collecting duct removes the driving force for potassium and hydrogen ion secretion, giving hyperkalaemia and acidosis. Spironolactone also blocks androgen receptors, causing gynaecomastia; eplerenone is more selective and avoids this.', 'admin', 'published', 3, true, '[["hyperkalaemia", "hyperkalemia", "high potassium"], ["metabolic acidosis", "acidosis"], ["gynaecomastia", "gynecomastia", "impotence", "menstrual irregularities"], ["gi upset", "nausea", "vomiting"], ["kidney stones", "renal stones"], ["renal failure"]]'::jsonb, 'saq p.061 Q2d(ii), BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-82a68d5c9a', 'pharm-antihelminthics-i', 'saq', 'List 4 commonly used drugs in the treatment of Ascaris lumbricoides infection.', '[]'::jsonb, 'Any 4 of: albendazole; mebendazole; pyrantel pamoate; levamisole; piperazine; ivermectin.', '[]'::jsonb, 'Benzimidazoles (albendazole, mebendazole) bind parasite beta-tubulin and block glucose uptake; a single dose cures most roundworm infections. Pyrantel and levamisole cause spastic paralysis through nicotinic receptors, piperazine causes flaccid paralysis through GABA receptors, and the worms are then expelled by peristalsis.', 'admin', 'published', 4, true, '[["albendazole"], ["mebendazole"], ["pyrantel", "pyrantel pamoate"], ["levamisole"], ["piperazine"], ["ivermectin"]]'::jsonb, 'saq p.061 Q2e, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-aa1425cc95', 'pharm-antiplatelet-drugs', 'saq', 'Give 2 contraindications to the use of aspirin as an antiplatelet agent.', '[]'::jsonb, 'Any 2 of: active peptic ulcer or gastrointestinal bleeding; bleeding disorders such as haemophilia; aspirin hypersensitivity including aspirin-sensitive asthma; children under 16 years (Reye''s syndrome); severe hepatic or renal impairment.', '[]'::jsonb, 'Aspirin irreversibly acetylates platelet COX-1 and removes protective gastric prostaglandins, so it is dangerous where bleeding is already likely. In aspirin-sensitive asthmatics it diverts arachidonic acid to leukotrienes, and in children with viral illness it is linked to Reye''s syndrome.', 'admin', 'published', 2, true, '[["peptic ulcer", "gi bleeding", "gastrointestinal bleeding"], ["haemophilia", "hemophilia", "bleeding disorder", "thrombocytopenia"], ["asthma", "hypersensitivity", "aspirin allergy"], ["children", "reye''s syndrome", "reye syndrome"], ["severe liver disease", "renal impairment"]]'::jsonb, 'saq p.061 Q2f, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-c4fb0a85f1', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'List three cardiac glycosides.', '[]'::jsonb, 'Digoxin; digitoxin; ouabain (others: deslanoside, lanatoside C).', '[]'::jsonb, 'Cardiac glycosides come from Digitalis (foxglove) and Strophanthus species. All inhibit the membrane Na+/K+-ATPase; digoxin is the only one in routine clinical use, digitoxin is longer acting and ouabain is mainly an experimental tool.', 'admin', 'published', 3, true, '[["digoxin"], ["digitoxin"], ["ouabain", "strophanthin", "deslanoside", "lanatoside c"]]'::jsonb, 'saq p.063 Q3a, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-2308e85c08', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'Which cardiac glycoside would you use in a patient with liver disease?', '[]'::jsonb, 'Digoxin', '["digoxin tablets", "lanoxin"]'::jsonb, 'Digoxin is excreted largely unchanged by the kidneys, so its clearance is not affected by hepatic impairment. Digitoxin is extensively metabolised by the liver and would accumulate; it is the one preferred in renal failure instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.063 Q3b, BDS EOY 2019/2020. The typed answer on the scan says digoxin is ''metabolised in the kidney''; more precisely it is excreted unchanged by the kidney.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-83dd96a96e', 'pharm-anti-retrovirals', 'saq', 'Indicate one major adverse effect of each of the following antiretroviral drugs: zidovudine, tenofovir, abacavir, atazanavir, efavirenz.', '[]'::jsonb, 'Zidovudine: bone marrow suppression (anaemia, neutropenia). Tenofovir: nephrotoxicity (proximal tubulopathy, Fanconi syndrome) or loss of bone density. Abacavir: hypersensitivity reaction. Atazanavir: unconjugated hyperbilirubinaemia with jaundice. Efavirenz: neuropsychiatric effects (vivid dreams, dizziness, depression).', '[]'::jsonb, 'Each drug has a signature toxicity: zidovudine suppresses marrow, tenofovir disoproxil damages the proximal tubule, abacavir hypersensitivity is linked to HLA-B*57:01, atazanavir inhibits UGT1A1 causing benign jaundice, and efavirenz causes CNS disturbance, worst in the first weeks.', 'admin', 'published', 5, true, '[["anaemia", "anemia", "bone marrow suppression", "neutropenia"], ["nephrotoxicity", "renal toxicity", "fanconi syndrome", "bone loss", "kidney"], ["hypersensitivity", "hypersensitivity reaction"], ["hyperbilirubinaemia", "hyperbilirubinemia", "jaundice"], ["cns effects", "vivid dreams", "nightmares", "neuropsychiatric", "dizziness", "depression"]]'::jsonb, 'saq p.063 Q3c, BDS EOY 2019/2020. The typed answer on the scan gives GI upset for tenofovir; renal toxicity is the major adverse effect.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-aadbd549f7', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Which direct-acting arteriolar vasodilator used in hypertension characteristically causes a drug-induced lupus erythematosus-like syndrome?', '[]'::jsonb, 'Hydralazine', '["hydrallazine", "apresoline"]'::jsonb, 'Hydralazine is metabolised by N-acetylation; slow acetylators on high doses develop antinuclear antibodies and a reversible lupus-like syndrome with arthralgia, fever and rash. Procainamide and isoniazid do the same, and methyldopa more rarely.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.063 Q3d(i), BDS EOY 2019/2020. Reworded so only one drug fits (paper: ''indicate one antihypertensive characterised by systemic lupus erythematosus'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-30653a9632', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Which antihypertensive drug characteristically causes hypertrichosis?', '[]'::jsonb, 'Minoxidil', '["minoxidil sulphate", "minoxidil sulfate"]'::jsonb, 'Minoxidil opens ATP-sensitive potassium channels in arteriolar smooth muscle; the same action on hair follicles causes excessive hair growth, an effect exploited topically for baldness. It also causes marked fluid retention and reflex tachycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.063 Q3d(ii), BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-050711d008', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'saq', 'Indicate one antihypertensive drug (or class) characterised by each of these adverse effects: hyperuricaemia, depression, bradycardia.', '[]'::jsonb, 'Hyperuricaemia: thiazide diuretics (e.g. hydrochlorothiazide) or loop diuretics. Depression: reserpine, methyldopa (also clonidine, propranolol). Bradycardia: beta-blockers such as propranolol or atenolol (also clonidine, verapamil, diltiazem).', '[]'::jsonb, 'Thiazides and loop diuretics compete with urate for tubular secretion and increase its proximal reabsorption. Centrally acting sympatholytics and reserpine deplete or reduce brain monoamine activity, giving depression. Beta-blockers, clonidine and rate-limiting calcium blockers slow the sinus node.', 'admin', 'published', 3, true, '[["thiazide", "hydrochlorothiazide", "loop diuretic", "furosemide", "bendroflumethiazide"], ["reserpine", "methyldopa", "clonidine", "propranolol"], ["beta blocker", "propranolol", "atenolol", "clonidine", "verapamil", "diltiazem"]]'::jsonb, 'saq p.063 Q3d(iii-v), BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-6de3d507df', 'pharm-introduction-to-pharmacokinetics', 'saq', 'Give four factors that may affect the pharmacokinetics of drugs.', '[]'::jsonb, 'Any 4 of: age (neonates, elderly); genetic factors (e.g. acetylator status); disease states (renal, hepatic, cardiac failure); pregnancy; body weight and composition; drug interactions (enzyme induction or inhibition); diet and food; route and dosage form; physicochemical properties of the drug (lipid solubility, ionisation).', '[]'::jsonb, 'Pharmacokinetics covers absorption, distribution, metabolism and excretion. Each step varies with patient factors (age, genes, organ function, pregnancy, body composition), with drug factors (solubility, formulation, route) and with other drugs or food that alter enzymes and transporters.', 'admin', 'published', 4, true, '[["age", "elderly", "neonates"], ["genetics", "genetic factors", "acetylator status", "pharmacogenetics"], ["disease", "renal failure", "liver disease", "hepatic disease"], ["pregnancy"], ["body weight", "obesity", "body composition"], ["drug interactions", "enzyme induction", "enzyme inhibition"], ["diet", "food"], ["route", "dosage form", "formulation"], ["lipid solubility", "ionisation", "physicochemical properties"]]'::jsonb, 'saq p.065 Q4b, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-a54f69cf7d', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'List 4 antibacterial drugs of different chemical classes that inhibit bacterial cell wall synthesis.', '[]'::jsonb, 'Any 4 from different classes: a penicillin (e.g. benzylpenicillin, amoxicillin); a cephalosporin (ceftriaxone); a carbapenem (imipenem, meropenem); a monobactam (aztreonam); a glycopeptide (vancomycin); bacitracin; fosfomycin; cycloserine.', '[]'::jsonb, 'Beta-lactams (penicillins, cephalosporins, carbapenems, monobactams) block the transpeptidases that cross-link peptidoglycan. Vancomycin binds the D-Ala-D-Ala end of the precursor, bacitracin blocks recycling of the lipid carrier, and fosfomycin and cycloserine block earlier cytoplasmic steps.', 'admin', 'published', 4, true, '[["penicillin", "amoxicillin", "benzylpenicillin", "ampicillin"], ["cephalosporin", "ceftriaxone", "cefuroxime", "cephalexin"], ["carbapenem", "imipenem", "meropenem"], ["aztreonam", "monobactam"], ["vancomycin", "teicoplanin", "glycopeptide"], ["bacitracin"], ["fosfomycin"], ["cycloserine"]]'::jsonb, 'saq p.067 Q5a, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-6d9edaafee', 'pharm-topical-antimicrobials', 'saq', 'List 2 antibacterial drugs that are only used topically.', '[]'::jsonb, 'Any 2 of: mupirocin; bacitracin; neomycin (skin and eye preparations); polymyxin B; gramicidin; retapamulin; silver sulfadiazine; mafenide.', '[]'::jsonb, 'These agents are too toxic systemically (bacitracin and neomycin are nephrotoxic, polymyxin nephro- and neurotoxic) or are inactivated too quickly (mupirocin) to be given by injection, so they are kept for skin, eye, ear or burn infections.', 'admin', 'published', 2, true, '[["mupirocin"], ["bacitracin"], ["neomycin"], ["polymyxin b", "polymyxin"], ["gramicidin"], ["retapamulin"], ["silver sulfadiazine", "silver sulphadiazine", "mafenide"]]'::jsonb, 'saq p.067 Q5b, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-d0c2569c25', 'pharm-h1-receptor-antagonists', 'saq', 'Give the mechanism of action of loratadine.', '[]'::jsonb, 'Loratadine is a second-generation H1 antihistamine. It is a competitive antagonist (inverse agonist) at peripheral histamine H1 receptors, blocking histamine-induced vasodilatation, increased capillary permeability, itching and bronchial and gut smooth-muscle contraction. It penetrates the blood-brain barrier poorly, so it is non-sedating, and it has little antimuscarinic action.', '[]'::jsonb, 'Second-generation antihistamines are selective for peripheral H1 receptors and are substrates of P-glycoprotein at the blood-brain barrier, so they cause little sedation. Loratadine is converted to the active metabolite desloratadine and is given once daily for allergic rhinitis and urticaria.', 'admin', 'published', 4, true, '[["h1 receptor", "h1 antagonist", "h1 blocker", "antihistamine"], ["competitive antagonist", "inverse agonist", "reversible"], ["second generation", "non-sedating", "does not cross bbb", "poor cns penetration"], ["blocks histamine effects", "reduces itching", "reduces vasodilation", "capillary permeability"], ["peripheral"]]'::jsonb, 'saq p.067 Q5c, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-00c8896a26', 'pharm-drug-interactions', 'saq', 'Define a drug interaction.', '[]'::jsonb, 'A drug interaction is the modification of the effect (intensity or duration) of one drug by the prior or concurrent administration of another drug, food, herb or chemical. The result may be an increased effect or toxicity, a reduced effect, or a new effect. Interactions are pharmacokinetic (altered absorption, distribution, metabolism or excretion), pharmacodynamic or pharmaceutical. Example: rifampicin induces the metabolism of warfarin and reduces its anticoagulant effect.', '[]'::jsonb, 'The key idea is that the response to a drug changes because something else was given with it. Note that rifampicin is an enzyme inducer: it lowers warfarin levels and risks clotting, whereas inhibitors such as erythromycin raise them and risk bleeding.', 'admin', 'published', 4, true, '[["effect of one drug altered", "modification of effect", "alters the effect"], ["another drug", "concurrent administration", "food", "second drug"], ["increased or decreased", "toxicity", "reduced effect", "enhanced effect"], ["pharmacokinetic", "pharmacodynamic"], ["example", "rifampicin", "warfarin"]]'::jsonb, 'saq p.067 Q5d, BDS EOY 2019/2020. The typed answer on the scan says rifampicin increases bleeding with warfarin; it does the opposite.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-18f379d11d', 'pharm-prostaglandins', 'saq', 'Give 2 adverse effects of misoprostol.', '[]'::jsonb, 'Any 2 of: diarrhoea; abdominal cramps or pain; nausea and vomiting; uterine contractions with abortion (contraindicated in pregnancy); vaginal bleeding; fever and shivering.', '[]'::jsonb, 'Misoprostol is a PGE1 analogue. Stimulating intestinal secretion and motility it causes dose-related diarrhoea and cramps, and by contracting the uterus it can cause abortion, which is why it is contraindicated in pregnancy when used for ulcer prophylaxis.', 'admin', 'published', 2, true, '[["diarrhoea", "diarrhea"], ["abdominal cramps", "abdominal pain", "colic"], ["uterine contraction", "abortion", "miscarriage", "vaginal bleeding"], ["nausea", "vomiting"], ["fever", "shivering", "chills"]]'::jsonb, 'saq p.067 Q5e, BDS EOY 2019/2020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-ca312898cd', 'pharm-adrenoceptor-blockers', 'saq', 'Give 4 clinical uses of propranolol.', '[]'::jsonb, 'Any 4 of: hypertension; angina pectoris; supraventricular and other arrhythmias; secondary prevention after myocardial infarction; thyrotoxicosis (symptom control); migraine prophylaxis; essential tremor; anxiety with somatic symptoms; portal hypertension (prevention of variceal bleeding); phaeochromocytoma (with an alpha-blocker); hypertrophic obstructive cardiomyopathy.', '[]'::jsonb, 'Propranolol is a lipid-soluble, non-selective beta-blocker. Blocking cardiac beta-1 receptors lowers heart rate, contractility and oxygen demand; blocking beta-2 and central receptors accounts for its use in tremor, anxiety, migraine and portal hypertension. Propranolol, not benztropine, is first line for essential tremor.', 'admin', 'published', 4, true, '[["hypertension"], ["angina", "ischaemic heart disease"], ["arrhythmias", "atrial fibrillation", "tachycardia"], ["myocardial infarction", "post mi"], ["thyrotoxicosis", "hyperthyroidism"], ["migraine prophylaxis", "migraine"], ["essential tremor", "tremor"], ["anxiety", "performance anxiety"], ["portal hypertension", "oesophageal varices", "variceal bleeding"], ["phaeochromocytoma", "pheochromocytoma"], ["hypertrophic cardiomyopathy"]]'::jsonb, 'saq p.067 Q5f, BDS EOY 2019/2020. The typed answer on the scan claims benztropine is first line for essential tremor, which is wrong.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-15bd183ec8', 'pharm-g-proteins-and-second-messengers', 'saq', 'List three second messengers.', '[]'::jsonb, 'Any 3 of: cyclic AMP (cAMP); cyclic GMP (cGMP); inositol trisphosphate (IP3); diacylglycerol (DAG); calcium ions.', '[]'::jsonb, 'Second messengers are small intracellular molecules produced when a receptor is activated. Gs and Gi regulate adenylyl cyclase and so cAMP; Gq activates phospholipase C to produce IP3 (which releases calcium) and DAG (which activates protein kinase C); nitric oxide and natriuretic peptides raise cGMP.', 'admin', 'published', 3, true, '[["camp", "cyclic amp"], ["cgmp", "cyclic gmp"], ["ip3", "inositol trisphosphate", "inositol triphosphate"], ["dag", "diacylglycerol"], ["calcium", "ca2+"]]'::jsonb, 'saq p.071 Q1a, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-8d0fe70f93', 'pharm-receptors-and-signal-transduction-mechanisms', 'saq', 'Give two examples of drugs that act via each of the following targets: ion channels, enzymes, receptors, DNA.', '[]'::jsonb, 'Ion channels: lidocaine, nifedipine (also verapamil, amiodarone, glibenclamide, phenytoin). Enzymes: aspirin, captopril (also neostigmine, allopurinol, omeprazole). Receptors: salbutamol, atropine (also propranolol, morphine, cimetidine). DNA: cyclophosphamide, cisplatin (also doxorubicin, metronidazole).', '[]'::jsonb, 'Most drugs act on four kinds of protein target: receptors, ion channels, enzymes and carrier molecules. A few, mainly anticancer drugs, bind DNA directly by alkylation, cross-linking or intercalation. Recognising the target class predicts both the mechanism and the likely adverse effects.', 'admin', 'published', 4, true, '[["lidocaine", "lignocaine", "nifedipine", "verapamil", "amlodipine", "amiodarone", "phenytoin", "glibenclamide"], ["aspirin", "captopril", "enalapril", "neostigmine", "allopurinol", "omeprazole", "methotrexate"], ["salbutamol", "atropine", "propranolol", "morphine", "cimetidine", "adrenaline"], ["cyclophosphamide", "cisplatin", "doxorubicin", "metronidazole", "mitomycin"]]'::jsonb, 'saq p.071 Q1b, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-b13961202a', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'saq', 'List four advantages of the intravenous route of drug administration.', '[]'::jsonb, 'Any 4 of: 100% bioavailability (no first-pass metabolism); rapid onset, useful in emergencies; dose can be titrated accurately to response; large volumes and irritant drugs can be given; suitable for unconscious, vomiting or uncooperative patients; suitable for drugs not absorbed or destroyed in the gut.', '[]'::jsonb, 'Injecting directly into the circulation bypasses absorption altogether, so the whole dose is available at once and plasma levels can be controlled minute by minute. This is why it is the route for emergencies, anaesthesia and drugs such as heparin or aminoglycosides that are not absorbed orally.', 'admin', 'published', 4, true, '[["100% bioavailability", "complete bioavailability", "no first pass", "avoids first pass metabolism"], ["rapid onset", "immediate effect", "emergency"], ["titration", "accurate dose", "precise control"], ["large volumes", "irritant drugs"], ["unconscious", "vomiting", "uncooperative"], ["not absorbed orally", "destroyed in gut"]]'::jsonb, 'saq p.071 Q1c(i), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-a72ea081c9', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'saq', 'List four disadvantages of the intravenous route of drug administration.', '[]'::jsonb, 'Any 4 of: once given the drug cannot be recalled (high risk of toxicity and overdose); risk of infection and need for sterile technique; needs trained personnel; painful and inconvenient; thrombophlebitis and extravasation with tissue necrosis; anaphylaxis is more rapid and severe; air or particle embolism; more expensive; unsuitable for oily or insoluble drugs.', '[]'::jsonb, 'Because the drug reaches high concentrations immediately and cannot be withdrawn, errors are dangerous. The route also breaches the skin (infection, phlebitis, embolism), needs sterile preparations and skilled staff, and suspensions or oily solutions can never be given this way.', 'admin', 'published', 4, true, '[["cannot be recalled", "irreversible", "overdose", "risk of toxicity"], ["infection", "sepsis", "sterile technique", "aseptic"], ["trained personnel", "skilled staff", "not self administered"], ["pain", "painful"], ["thrombophlebitis", "phlebitis", "extravasation"], ["anaphylaxis"], ["embolism", "air embolism"], ["expensive", "cost"], ["not for oily", "insoluble"]]'::jsonb, 'saq p.071 Q1c(ii), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-791255d8f3', 'pharm-oral-antidiabetic-drugs', 'saq', 'Give two examples of sulphonylurea oral hypoglycaemic agents.', '[]'::jsonb, 'Any 2 of: glibenclamide (glyburide); gliclazide; glipizide; glimepiride; tolbutamide; chlorpropamide.', '[]'::jsonb, 'Tolbutamide and chlorpropamide are first-generation sulphonylureas; glibenclamide, gliclazide, glipizide and glimepiride are more potent second-generation drugs. All stimulate insulin secretion and so can cause hypoglycaemia and weight gain. Gliclazide and glipizide are shorter acting and safer in the elderly than glibenclamide.', 'admin', 'published', 2, true, '[["glibenclamide", "glyburide"], ["gliclazide"], ["glipizide"], ["glimepiride"], ["tolbutamide"], ["chlorpropamide"]]'::jsonb, 'saq p.071 Q1d(i), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-ada97c56fd', 'pharm-oral-antidiabetic-drugs', 'saq', 'What is the mechanism of action of the sulphonylurea oral hypoglycaemic agents?', '[]'::jsonb, 'They bind the SUR1 subunit of the ATP-sensitive potassium channel on pancreatic beta cells and close the channel; the membrane depolarises, voltage-gated calcium channels open, calcium enters and insulin is released by exocytosis. They need functioning beta cells.', '[]'::jsonb, 'Sulphonylureas mimic the effect of a raised ATP/ADP ratio on the beta-cell K-ATP channel, so they release insulin whatever the glucose level. That explains hypoglycaemia as the main adverse effect and why they do not work in type 1 diabetes.', 'admin', 'published', 3, true, '[["sur1", "sulphonylurea receptor", "sulfonylurea receptor", "beta cells"], ["close k-atp", "block potassium channels", "atp-sensitive potassium channel", "katp"], ["depolarisation", "depolarization"], ["calcium influx", "calcium channels open"], ["insulin release", "insulin secretion"]]'::jsonb, 'saq p.071 Q1d(ii), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-556bacd41a', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'saq', 'Classify antihypertensive drugs and give two examples in each class.', '[]'::jsonb, '1. Diuretics: hydrochlorothiazide, furosemide, spironolactone. 2. ACE inhibitors: enalapril, captopril. 3. Angiotensin receptor blockers: losartan, valsartan. 4. Calcium channel blockers: nifedipine, amlodipine, verapamil. 5. Beta-blockers: atenolol, propranolol. 6. Alpha-1 blockers: prazosin, doxazosin. 7. Centrally acting sympatholytics: methyldopa, clonidine. 8. Direct vasodilators: hydralazine, minoxidil, sodium nitroprusside. 9. Adrenergic neurone blockers: reserpine, guanethidine. 10. Renin inhibitor: aliskiren.', '[]'::jsonb, 'Blood pressure is cardiac output times peripheral resistance, and each class lowers one or both: diuretics reduce volume, sympatholytics reduce output and tone, RAAS inhibitors and calcium blockers reduce resistance. First-line choices today are thiazides, ACE inhibitors or ARBs and calcium channel blockers.', 'admin', 'published', 5, true, '[["diuretics", "thiazide", "hydrochlorothiazide", "furosemide"], ["ace inhibitors", "enalapril", "captopril", "lisinopril"], ["arb", "angiotensin receptor blockers", "losartan", "valsartan"], ["calcium channel blockers", "nifedipine", "amlodipine"], ["beta blockers", "atenolol", "propranolol"], ["alpha blockers", "prazosin", "doxazosin"], ["centrally acting", "methyldopa", "clonidine"], ["vasodilators", "hydralazine", "minoxidil", "nitroprusside"], ["reserpine", "guanethidine", "adrenergic neurone blockers"]]'::jsonb, 'saq p.071 Q2a, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-89848d00ec', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'What is the mechanism of action of digoxin?', '[]'::jsonb, 'Digoxin inhibits the Na+/K+-ATPase of the cardiac myocyte membrane. Intracellular sodium rises, which reduces calcium extrusion by the Na+/Ca2+ exchanger; more calcium is stored in the sarcoplasmic reticulum and released with each beat, increasing contractility (positive inotropy). It also increases vagal tone, slowing the sinus rate and AV conduction.', '[]'::jsonb, 'The inotropic effect follows from pump inhibition, and the rate-slowing effect from increased vagal activity at the AV node, which is why digoxin controls ventricular rate in atrial fibrillation. Hypokalaemia increases digoxin binding to the pump and so precipitates toxicity.', 'admin', 'published', 3, true, '[["na+/k+ atpase", "sodium potassium atpase", "sodium pump", "na k atpase"], ["increased intracellular sodium", "sodium rises"], ["sodium calcium exchanger", "na/ca exchanger", "reduced calcium extrusion"], ["increased intracellular calcium", "calcium"], ["positive inotropy", "increased contractility"], ["vagal", "slows av conduction", "parasympathetic"]]'::jsonb, 'saq p.071 Q2b, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-936aabf01d', 'pharm-anticoagulant-drugs', 'saq', 'Give two adverse effects of warfarin.', '[]'::jsonb, 'Any 2 of: bleeding (haemorrhage); skin necrosis; teratogenicity (fetal warfarin syndrome); purple toe syndrome; alopecia; hypersensitivity rash.', '[]'::jsonb, 'Bleeding is the predictable extension of anticoagulation. Skin necrosis occurs early because protein C, a natural anticoagulant with a short half-life, falls before the clotting factors. Warfarin crosses the placenta and causes nasal hypoplasia and stippled epiphyses in the first trimester.', 'admin', 'published', 2, true, '[["bleeding", "haemorrhage", "hemorrhage"], ["skin necrosis"], ["teratogenicity", "teratogenic", "fetal warfarin syndrome", "birth defects"], ["purple toe syndrome", "purple toes"], ["alopecia", "hair loss"]]'::jsonb, 'saq p.071 Q2c(i), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-4e23b93593', 'pharm-anticoagulant-drugs', 'saq', 'Which laboratory test is used to monitor warfarin therapy?', '[]'::jsonb, 'INR', '["international normalised ratio", "international normalized ratio", "prothrombin time", "PT", "PT/INR", "PT INR"]'::jsonb, 'Warfarin lowers the vitamin K-dependent factors II, VII, IX and X, which prolongs the prothrombin time. Reporting it as the international normalised ratio corrects for differences between laboratory reagents; the usual target is 2 to 3. The aPTT is used for unfractionated heparin.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.071 Q2c(ii), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-021761fe44', 'pharm-anticholinergics-and-ganglion-blockers', 'saq', 'List four indications of atropine.', '[]'::jsonb, 'Any 4 of: organophosphate or carbamate poisoning; symptomatic bradycardia and heart block; premedication to reduce salivary and bronchial secretions; with neostigmine to reverse neuromuscular blockade (blocks muscarinic effects); mydriasis and cycloplegia for eye examination and uveitis; antispasmodic in intestinal or renal colic; muscarine mushroom poisoning.', '[]'::jsonb, 'Atropine competitively blocks muscarinic receptors, removing vagal slowing of the heart, drying secretions, relaxing smooth muscle and paralysing the pupillary sphincter and ciliary muscle. In organophosphate poisoning large repeated doses are needed to counter the excess acetylcholine.', 'admin', 'published', 4, true, '[["organophosphate poisoning", "organophosphate", "carbamate poisoning"], ["bradycardia", "heart block"], ["premedication", "preanaesthetic", "reduce secretions", "antisialagogue"], ["with neostigmine", "reversal of neuromuscular block"], ["mydriasis", "cycloplegia", "eye examination", "uveitis", "mydriatic"], ["antispasmodic", "colic"], ["mushroom poisoning"]]'::jsonb, 'saq p.071 Q2d, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-99dee2e4ab', 'pharm-sedative-hypnotic-drugs', 'saq', 'What is the antidote for diazepam (benzodiazepine) overdose?', '[]'::jsonb, 'Flumazenil', '["flumazenil injection", "anexate"]'::jsonb, 'Flumazenil is a competitive antagonist at the benzodiazepine binding site of the GABA-A receptor and rapidly reverses sedation. It is short acting, so re-sedation can occur, and it may provoke seizures in benzodiazepine-dependent patients or mixed tricyclic overdose.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.071 Q2e(i), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-heavy-metal-poisoning-69c7c71eb9', 'pharm-heavy-metal-poisoning', 'saq', 'What is the antidote for iron poisoning?', '[]'::jsonb, 'Desferrioxamine', '["deferoxamine", "desferoxamine", "desferal", "deferoxamine mesylate"]'::jsonb, 'Desferrioxamine chelates ferric iron to form water-soluble ferrioxamine, which is excreted in the urine (turning it orange-red). It is given parenterally in acute iron poisoning; deferiprone and deferasirox are oral chelators used for chronic iron overload.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.071 Q2e(ii), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-63aedc08a8', 'pharm-anticoagulant-drugs', 'saq', 'What is the antidote for heparin overdose?', '[]'::jsonb, 'Protamine sulphate', '["protamine", "protamine sulfate"]'::jsonb, 'Protamine is a strongly basic protein that binds the strongly acidic heparin molecule to form a stable inactive complex; about 1 mg neutralises 100 units of heparin. It reverses low molecular weight heparins only partially. Vitamin K is the antidote for warfarin, not heparin.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.071 Q2e(iii), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-02632892ea', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'What is the specific antidote for severe digoxin toxicity?', '[]'::jsonb, 'Digoxin-specific antibody fragments', '["digoxin immune fab", "digibind", "digifab", "digoxin antibodies", "digoxin specific fab", "fab fragments", "digoxin-specific antibodies"]'::jsonb, 'Fab fragments of sheep anti-digoxin antibodies bind free digoxin with higher affinity than the Na+/K+-ATPase; the complex is excreted by the kidneys. They are used for life-threatening arrhythmias or hyperkalaemia, alongside correction of potassium and magnesium.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.071 Q2e(iv), MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-d5f2efe726', 'pharm-anti-tb-drugs', 'saq', 'List five first-line antituberculosis drugs.', '[]'::jsonb, 'Rifampicin; isoniazid; pyrazinamide; ethambutol; streptomycin.', '[]'::jsonb, 'The first-line drugs combine the greatest efficacy with acceptable toxicity. Standard treatment is two months of rifampicin, isoniazid, pyrazinamide and ethambutol followed by four months of rifampicin and isoniazid; streptomycin is the injectable first-line agent.', 'admin', 'published', 5, true, '[["rifampicin", "rifampin"], ["isoniazid", "inh"], ["pyrazinamide"], ["ethambutol"], ["streptomycin"]]'::jsonb, 'saq p.071 Q3a, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-992a912936', 'pharm-anti-tb-drugs', 'saq', 'Indicate one significant adverse effect of each first-line antituberculosis drug: rifampicin, isoniazid, pyrazinamide, ethambutol, streptomycin.', '[]'::jsonb, 'Rifampicin: hepatotoxicity (also orange-red body fluids, enzyme induction with drug interactions). Isoniazid: peripheral neuropathy (also hepatitis). Pyrazinamide: hepatotoxicity or hyperuricaemia with gout. Ethambutol: optic (retrobulbar) neuritis with red-green colour blindness. Streptomycin: ototoxicity (vestibular) or nephrotoxicity.', '[]'::jsonb, 'Isoniazid depletes pyridoxine, so neuropathy is prevented with vitamin B6. Rifampicin, isoniazid and pyrazinamide are all hepatotoxic. Pyrazinamide blocks urate excretion, ethambutol damages the optic nerve (dose related) and streptomycin, an aminoglycoside, damages the eighth nerve and kidney.', 'admin', 'published', 5, true, '[["hepatotoxicity", "hepatitis", "orange urine", "red urine", "enzyme induction"], ["peripheral neuropathy", "neuropathy", "hepatitis"], ["hyperuricaemia", "hyperuricemia", "gout", "arthralgia", "hepatotoxicity"], ["optic neuritis", "colour blindness", "color blindness", "visual disturbance"], ["ototoxicity", "deafness", "vestibular", "nephrotoxicity"]]'::jsonb, 'saq p.071 Q3b, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-2e5b08744e', 'pharm-antiretroviral-i', 'saq', 'Enumerate five mitochondrial toxic effects of nucleoside reverse transcriptase inhibitors used in HIV therapy.', '[]'::jsonb, 'Any 5 of: lactic acidosis; hepatic steatosis (hepatomegaly); peripheral neuropathy; pancreatitis; myopathy; cardiomyopathy; lipoatrophy; bone marrow suppression (anaemia).', '[]'::jsonb, 'NRTIs also inhibit human mitochondrial DNA polymerase gamma, depleting mitochondrial DNA and impairing oxidative phosphorylation. Tissues that depend on it suffer: nerve, muscle, pancreas, liver and fat. Stavudine, didanosine and zidovudine are the worst offenders; lamivudine, abacavir and tenofovir are much safer.', 'admin', 'published', 5, true, '[["lactic acidosis"], ["hepatic steatosis", "fatty liver", "hepatomegaly"], ["peripheral neuropathy", "neuropathy"], ["pancreatitis"], ["myopathy", "myalgia"], ["cardiomyopathy"], ["lipoatrophy", "lipodystrophy"], ["anaemia", "bone marrow suppression"]]'::jsonb, 'saq p.071 Q3c, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-0f8453e2f5', 'pharm-cephalosporins-and-cephamycins', 'saq', 'Classify cephalosporins and give one example in each class.', '[]'::jsonb, 'First generation: cephalexin, cefazolin, cefadroxil. Second generation: cefuroxime, cefaclor, cefoxitin. Third generation: ceftriaxone, cefotaxime, ceftazidime, cefixime. Fourth generation: cefepime. Fifth generation: ceftaroline, ceftobiprole.', '[]'::jsonb, 'Generations reflect the antibacterial spectrum: first-generation drugs are best against Gram-positive cocci; activity against Gram-negative bacilli and beta-lactamase stability increase through the second and third; cefepime adds Pseudomonas with good Gram-positive cover, and ceftaroline is active against MRSA.', 'admin', 'published', 5, true, '[["first generation", "cephalexin", "cefazolin", "cefadroxil", "cephalothin"], ["second generation", "cefuroxime", "cefaclor", "cefoxitin"], ["third generation", "ceftriaxone", "cefotaxime", "ceftazidime", "cefixime"], ["fourth generation", "cefepime"], ["fifth generation", "ceftaroline", "ceftobiprole"]]'::jsonb, 'saq p.071 Q3d, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-2f098dc007', 'pharm-aminoglycosides', 'saq', 'List four adverse effects of gentamicin.', '[]'::jsonb, 'Any 4 of: nephrotoxicity (acute tubular necrosis); ototoxicity (cochlear: deafness, tinnitus); vestibular toxicity (vertigo, ataxia); neuromuscular blockade; hypersensitivity (rash); teratogenicity (fetal eighth nerve damage).', '[]'::jsonb, 'Aminoglycosides accumulate in renal proximal tubular cells and in the perilymph of the inner ear, causing usually reversible nephrotoxicity and often irreversible ototoxicity. They also inhibit presynaptic acetylcholine release, so they can worsen myasthenia or prolong neuromuscular block.', 'admin', 'published', 4, true, '[["nephrotoxicity", "renal toxicity", "kidney damage", "acute tubular necrosis"], ["ototoxicity", "deafness", "hearing loss", "tinnitus"], ["vestibular toxicity", "vertigo", "ataxia"], ["neuromuscular blockade", "muscle paralysis", "nm blockade"], ["hypersensitivity", "rash", "allergy"], ["teratogenic"]]'::jsonb, 'saq p.071 Q3e, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-a1fc84418a', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'saq', 'Peter, a 25-year-old man, is admitted with upper gastrointestinal bleeding following ingestion of aspirin. He also has bilateral rhonchi due to asthma. Which drugs would you use if endoscopy shows a bleeding peptic ulcer?', '[]'::jsonb, 'A proton pump inhibitor, given intravenously at high dose (omeprazole, esomeprazole or pantoprazole) then orally; alternatives or adjuncts are H2-receptor antagonists (ranitidine, cimetidine), sucralfate, bismuth compounds, antacids and misoprostol. Aspirin is stopped, and Helicobacter pylori is eradicated if present.', '[]'::jsonb, 'A clot is stable only when gastric pH is above about 6, so profound acid suppression with an intravenous proton pump inhibitor after endoscopic haemostasis reduces rebleeding. H2 blockers are weaker. Misoprostol replaces the prostaglandins that aspirin removes and helps prevent NSAID ulcers.', 'admin', 'published', 3, true, '[["proton pump inhibitor", "ppi", "omeprazole", "pantoprazole", "esomeprazole"], ["h2 antagonist", "h2 blocker", "ranitidine", "cimetidine", "famotidine"], ["sucralfate", "bismuth", "misoprostol", "antacids"], ["stop aspirin", "h. pylori eradication", "eradication therapy"]]'::jsonb, 'saq p.071 Q4a, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-f9654760b2', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'Peter, a 25-year-old man, is admitted with upper gastrointestinal bleeding following ingestion of aspirin. He also has bilateral rhonchi due to asthma. How does aspirin precipitate asthma?', '[]'::jsonb, 'Aspirin inhibits cyclo-oxygenase, so arachidonic acid is diverted (shunted) into the 5-lipoxygenase pathway. This increases production of cysteinyl leukotrienes (LTC4, LTD4, LTE4), which are potent bronchoconstrictors and increase mucus secretion and mucosal oedema. Loss of bronchodilator and anti-inflammatory PGE2 contributes.', '[]'::jsonb, 'Aspirin-exacerbated respiratory disease is a pharmacological, not an allergic, reaction, which is why all non-selective NSAIDs cross-react. PGE2 normally restrains 5-lipoxygenase and mast cells; removing it unleashes leukotriene production. Leukotriene antagonists such as montelukast are useful.', 'admin', 'published', 3, true, '[["inhibits cox", "cyclooxygenase inhibition", "cox inhibition", "cyclo-oxygenase"], ["shunting", "diverted", "arachidonic acid"], ["lipoxygenase", "5-lipoxygenase"], ["leukotrienes", "ltc4", "ltd4"], ["bronchoconstriction", "bronchospasm"], ["reduced pge2", "loss of prostaglandin e2"]]'::jsonb, 'saq p.071 Q4b, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-a3c8a23553', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'saq', 'Peter, a 25-year-old man, is admitted with upper gastrointestinal bleeding following ingestion of aspirin. He also has bilateral rhonchi due to asthma. Which drugs will cause immediate relief of his asthma symptoms?', '[]'::jsonb, 'Inhaled or nebulised short-acting beta-2 agonists: salbutamol (albuterol) or terbutaline. Inhaled ipratropium bromide can be added. (Intravenous aminophylline or magnesium sulphate in severe attacks.)', '[]'::jsonb, 'Short-acting beta-2 agonists relax bronchial smooth muscle within minutes by raising cAMP and are the relievers of choice. Ipratropium adds bronchodilatation by blocking vagal tone. Corticosteroids are essential in an attack but take hours to act, so they do not give immediate relief.', 'admin', 'published', 2, true, '[["salbutamol", "albuterol", "short acting beta 2 agonist", "saba", "terbutaline"], ["ipratropium", "ipratropium bromide", "aminophylline", "terbutaline", "magnesium sulphate"]]'::jsonb, 'saq p.072 Q4c, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-2d80c648c7', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'List four COX-2 selective non-steroidal anti-inflammatory agents that would be safer than aspirin in a patient who has bled from a peptic ulcer.', '[]'::jsonb, 'Any 4 of: celecoxib; etoricoxib; parecoxib; valdecoxib; rofecoxib; lumiracoxib (the last three withdrawn). Preferentially COX-2 selective: meloxicam, nimesulide, etodolac.', '[]'::jsonb, 'Gastric mucosal protection depends on COX-1-derived prostaglandins, so drugs that spare COX-1 cause fewer ulcers and do not impair platelet function. The price is an increased risk of thrombotic cardiovascular events, which led to the withdrawal of rofecoxib and valdecoxib.', 'admin', 'published', 4, true, '[["celecoxib"], ["etoricoxib"], ["parecoxib"], ["valdecoxib"], ["rofecoxib"], ["lumiracoxib"], ["meloxicam", "nimesulide", "etodolac"]]'::jsonb, 'saq p.072 Q4d, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-epipodophyllotoxins-camptothecins-anal-9d99d347c5', 'pharm-epipodophyllotoxins-camptothecins-analogues', 'saq', 'Give two examples of camptothecin analogues.', '[]'::jsonb, 'Irinotecan; topotecan.', '[]'::jsonb, 'Camptothecins come from the tree Camptotheca acuminata and inhibit topoisomerase I, stabilising the enzyme-DNA complex so that single-strand breaks cannot be resealed. Irinotecan (prodrug of SN-38) is used in colorectal cancer and causes severe diarrhoea; topotecan is used in ovarian and small-cell lung cancer.', 'admin', 'published', 2, true, '[["irinotecan"], ["topotecan"]]'::jsonb, 'saq p.072 Q5a, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-f77735ef88', 'pharm-sedative-hypnotic-drugs', 'saq', 'List four clinical indications of diazepam.', '[]'::jsonb, 'Any 4 of: anxiety disorders (short term); status epilepticus and febrile convulsions; alcohol withdrawal; muscle spasm and spasticity (e.g. tetanus); premedication and sedation for procedures; insomnia (short term); induction of anaesthesia.', '[]'::jsonb, 'Diazepam enhances GABA action at the GABA-A receptor by increasing the frequency of chloride channel opening, giving anxiolytic, sedative, anticonvulsant and central muscle relaxant effects. Its long half-life and active metabolite make it useful for alcohol withdrawal but prone to accumulation.', 'admin', 'published', 4, true, '[["anxiety"], ["status epilepticus", "seizures", "convulsions", "febrile convulsions"], ["alcohol withdrawal"], ["muscle spasm", "spasticity", "tetanus", "muscle relaxant"], ["premedication", "sedation"], ["insomnia"], ["induction of anaesthesia"]]'::jsonb, 'saq p.072 Q5b, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-70c62c932e', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'saq', 'List two catechol-O-methyltransferase (COMT) inhibitors used in Parkinsonism.', '[]'::jsonb, 'Entacapone; tolcapone (also opicapone).', '[]'::jsonb, 'COMT inhibitors block the peripheral conversion of levodopa to 3-O-methyldopa, prolonging its half-life and reducing end-of-dose wearing off. Entacapone acts only peripherally; tolcapone also acts centrally but can cause fatal hepatotoxicity, so liver function must be monitored.', 'admin', 'published', 2, true, '[["entacapone"], ["tolcapone", "opicapone"]]'::jsonb, 'saq p.072 Q5c, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-83e940f9de', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Giving examples, briefly describe the mechanisms of action of anticonvulsant drugs.', '[]'::jsonb, '1. Blockade of voltage-gated sodium channels (prolonging inactivation): phenytoin, carbamazepine, lamotrigine, valproate. 2. Enhancement of GABA-ergic inhibition: benzodiazepines and phenobarbital (GABA-A receptor), vigabatrin (inhibits GABA transaminase), tiagabine (inhibits GABA reuptake). 3. Blockade of T-type calcium channels: ethosuximide, valproate. 4. Reduction of glutamate excitation: topiramate (AMPA), felbamate (NMDA), perampanel. 5. Binding to synaptic vesicle protein SV2A: levetiracetam. 6. Binding the alpha-2-delta subunit of calcium channels: gabapentin, pregabalin.', '[]'::jsonb, 'Seizures reflect excessive synchronous neuronal firing, so drugs either limit repetitive firing (sodium channel block), strengthen inhibition (GABA) or weaken excitation (glutamate, calcium channels). The T-type calcium current in thalamic neurons drives absence seizures, hence ethosuximide.', 'admin', 'published', 5, true, '[["sodium channel", "na channel", "phenytoin", "carbamazepine", "lamotrigine"], ["gaba", "benzodiazepines", "phenobarbital", "vigabatrin", "tiagabine", "diazepam"], ["t-type calcium", "calcium channel", "ethosuximide"], ["glutamate", "nmda", "ampa", "topiramate", "felbamate"], ["sv2a", "levetiracetam"], ["alpha-2-delta", "gabapentin", "pregabalin"]]'::jsonb, 'saq p.072 Q5d, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-df8c0a4e54', 'pharm-anticancer-agents-general-principles-classification', 'saq', 'List two cell cycle-specific and two cell cycle non-specific cancer chemotherapeutic drugs.', '[]'::jsonb, 'Cell cycle-specific (any 2): methotrexate, 5-fluorouracil, cytarabine, 6-mercaptopurine (S phase); vincristine, vinblastine, paclitaxel (M phase); etoposide, bleomycin (G2). Cell cycle non-specific (any 2): cyclophosphamide and other alkylating agents, cisplatin, doxorubicin, dactinomycin, nitrosoureas.', '[]'::jsonb, 'Cell cycle-specific drugs kill only cells passing through a particular phase (antimetabolites in S phase, spindle poisons in M phase), so they are schedule dependent and best against rapidly dividing tumours. Non-specific drugs damage DNA in any phase, including resting cells, and are dose dependent.', 'admin', 'published', 4, true, '[["methotrexate", "5-fluorouracil", "fluorouracil", "cytarabine", "6-mercaptopurine", "mercaptopurine", "hydroxyurea"], ["vincristine", "vinblastine", "paclitaxel", "etoposide", "bleomycin"], ["cyclophosphamide", "chlorambucil", "melphalan", "busulfan", "alkylating agents"], ["cisplatin", "doxorubicin", "dactinomycin", "carmustine", "mitomycin"]]'::jsonb, 'saq p.072 Q5e, MBChB EOY 2015/2016') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-e247c35978', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'saq', 'Andrew is a 70-year-old man with worsening cognitive decline, muscle rigidity, bradykinesia and tremor, diagnosed with Parkinson''s disease. Classify the agents that can be used for the management of Parkinson''s disease, giving an example in each class.', '[]'::jsonb, '1. Dopamine precursor: levodopa (with a peripheral dopa-decarboxylase inhibitor, carbidopa or benserazide). 2. Dopamine agonists: ergot (bromocriptine, pergolide) and non-ergot (pramipexole, ropinirole, apomorphine). 3. MAO-B inhibitors: selegiline, rasagiline. 4. COMT inhibitors: entacapone, tolcapone. 5. Dopamine releaser/NMDA antagonist: amantadine. 6. Central antimuscarinics: benzhexol (trihexyphenidyl), benztropine, procyclidine.', '[]'::jsonb, 'Parkinson''s disease is a loss of nigrostriatal dopamine with relative cholinergic overactivity, so treatment either restores dopaminergic activity (precursor, agonists, blocking breakdown by MAO-B or COMT, amantadine) or reduces cholinergic activity. Antimuscarinics worsen confusion and are avoided in the elderly with cognitive decline.', 'admin', 'published', 8, true, '[["levodopa", "l-dopa", "dopamine precursor"], ["carbidopa", "benserazide", "decarboxylase inhibitor"], ["dopamine agonists", "bromocriptine", "pramipexole", "ropinirole", "apomorphine", "pergolide"], ["mao-b inhibitors", "selegiline", "rasagiline"], ["comt inhibitors", "entacapone", "tolcapone"], ["amantadine"], ["anticholinergics", "antimuscarinics", "benzhexol", "trihexyphenidyl", "benztropine", "procyclidine"], ["nmda antagonist", "dopamine releaser", "antiviral"]]'::jsonb, 'saq p.074 Q1a, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-2f210623f0', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'saq', 'List four dermatologic vehicles used to facilitate cutaneous application of drugs.', '[]'::jsonb, 'Any 4 of: ointments; creams; lotions; gels; pastes; powders; solutions and tinctures; foams and sprays.', '[]'::jsonb, 'The vehicle affects drug penetration and suits different lesions: greasy ointments occlude and hydrate dry, thickened skin and give the greatest absorption; creams suit moist or weeping lesions; lotions and gels suit hairy areas; powders dry intertriginous areas.', 'admin', 'published', 4, true, '[["ointment", "ointments"], ["cream", "creams"], ["lotion", "lotions"], ["gel", "gels"], ["paste", "pastes"], ["powder", "powders"], ["solution", "tincture", "foam", "spray"]]'::jsonb, 'saq p.074 Q1b(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-a9c35063b3', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'saq', 'Give three first-generation retinoids useful in the management of acne.', '[]'::jsonb, 'Tretinoin (all-trans retinoic acid, topical); isotretinoin (13-cis retinoic acid, oral or topical); retinol or retinaldehyde (topical). (Adapalene and tazarotene are third-generation.)', '[]'::jsonb, 'First-generation retinoids are the non-aromatic natural compounds: retinol, tretinoin, isotretinoin and alitretinoin. They normalise follicular keratinisation, and oral isotretinoin also shrinks sebaceous glands. Isotretinoin is highly teratogenic, so strict contraception is required.', 'admin', 'draft', 3, true, '[["tretinoin", "all-trans retinoic acid", "retinoic acid"], ["isotretinoin", "13-cis retinoic acid"], ["retinol", "retinaldehyde", "alitretinoin"]]'::jsonb, 'saq p.074 Q1b(ii), MBChB 2012/2013. Only tretinoin and isotretinoin are established first-generation acne drugs; the third expected answer is uncertain (retinol/retinaldehyde or alitretinoin).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-d76cfc105d', 'pharm-oral-antidiabetic-drugs', 'saq', 'Name three classes of oral hypoglycaemic agents that act as insulin secretagogues.', '[]'::jsonb, 'Sulphonylureas (e.g. glibenclamide); meglitinides (glinides, e.g. repaglinide, nateglinide); DPP-4 inhibitors (gliptins, e.g. sitagliptin). (Oral GLP-1 receptor agonist: semaglutide.)', '[]'::jsonb, 'Sulphonylureas and meglitinides close the beta-cell K-ATP channel and release insulin irrespective of glucose, so they cause hypoglycaemia. DPP-4 inhibitors prolong the action of the incretins GLP-1 and GIP, which increase insulin secretion only when glucose is raised.', 'admin', 'published', 3, true, '[["sulphonylureas", "sulfonylureas", "glibenclamide", "gliclazide"], ["meglitinides", "glinides", "repaglinide", "nateglinide"], ["dpp-4 inhibitors", "gliptins", "sitagliptin", "vildagliptin", "glp-1 agonists"]]'::jsonb, 'saq p.074 Q1c(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-2947d64e55', 'pharm-log-dose-responses', 'saq', 'Briefly define therapeutic index.', '[]'::jsonb, 'The therapeutic index is the ratio of the dose that produces toxicity in 50% of the population (TD50; in animals the lethal dose, LD50) to the dose that produces the desired effect in 50% of the population (ED50): TI = TD50/ED50. It is a measure of a drug''s safety margin.', '[]'::jsonb, 'Both values come from quantal dose-response curves. A large ratio means the toxic dose is far above the effective dose (penicillin); a small ratio means the two are close and small changes in dose or clearance cause toxicity (digoxin, lithium, warfarin, theophylline).', 'admin', 'published', 3, true, '[["ratio"], ["td50", "ld50", "toxic dose", "lethal dose"], ["ed50", "effective dose"], ["safety", "margin of safety", "safety margin"]]'::jsonb, 'saq p.074 Q2a(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-475fa19240', 'pharm-log-dose-responses', 'saq', 'Briefly discuss the clinical usefulness of the therapeutic index.', '[]'::jsonb, 'It indicates the relative safety of a drug. Drugs with a narrow (low) therapeutic index, e.g. digoxin, lithium, phenytoin, warfarin, theophylline and aminoglycosides, need careful dose individualisation, plasma level or effect monitoring, and attention to interactions and organ impairment. Drugs with a wide index, e.g. penicillins, can be given in standard doses without monitoring.', '[]'::jsonb, 'The index guides how cautiously a drug must be used: a narrow index is one of the main reasons for therapeutic drug monitoring and for worrying about interactions and renal or hepatic impairment. It is a population measure and does not predict idiosyncratic reactions.', 'admin', 'published', 2, true, '[["safety", "measure of safety", "relative safety"], ["narrow therapeutic index", "low therapeutic index", "digoxin", "lithium", "warfarin", "phenytoin", "theophylline"], ["monitoring", "therapeutic drug monitoring", "dose adjustment", "plasma levels"], ["wide therapeutic index", "penicillin"]]'::jsonb, 'saq p.074 Q2a(ii), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-5240187fa5', 'pharm-biotransformation', 'saq', 'List 4 phase I metabolic reactions.', '[]'::jsonb, 'Oxidation (e.g. hydroxylation, N- and O-dealkylation, deamination, sulphoxidation); reduction (nitro- and azo-reduction); hydrolysis (of esters and amides); cyclisation or decyclisation.', '[]'::jsonb, 'Phase I (functionalisation) reactions introduce or unmask a polar group such as -OH, -NH2 or -COOH, mostly through the cytochrome P450 mixed-function oxidases. The product may be inactive, active or toxic and is often then conjugated in phase II (glucuronidation, sulphation, acetylation).', 'admin', 'published', 2, true, '[["oxidation", "hydroxylation"], ["reduction"], ["hydrolysis"], ["dealkylation", "deamination", "sulphoxidation", "sulfoxidation", "cyclisation", "decyclisation"]]'::jsonb, 'saq p.074 Q2b, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-387e5cd80f', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'Give 4 clinical indications of opioids and an example of an opioid drug recommended for each.', '[]'::jsonb, 'Any 4 of: severe acute or cancer pain - morphine (also pethidine, fentanyl); cough suppression - codeine, dextromethorphan; diarrhoea - loperamide, diphenoxylate; acute left ventricular failure (pulmonary oedema) - morphine; anaesthesia (premedication, intraoperative analgesia) - fentanyl; opioid dependence (substitution) - methadone, buprenorphine.', '[]'::jsonb, 'Mu-receptor activation gives analgesia, suppresses the cough centre and slows gut transit. Loperamide does not enter the brain, so it treats diarrhoea without central effects. Morphine relieves the dyspnoea and anxiety of acute pulmonary oedema and reduces preload by venodilatation.', 'admin', 'published', 4, true, '[["pain", "analgesia", "morphine", "pethidine"], ["cough", "antitussive", "codeine", "dextromethorphan"], ["diarrhoea", "diarrhea", "loperamide", "diphenoxylate"], ["pulmonary oedema", "left ventricular failure", "pulmonary edema"], ["anaesthesia", "premedication", "fentanyl"], ["opioid dependence", "methadone", "buprenorphine"]]'::jsonb, 'saq p.074 Q2c, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-8cebaf8944', 'pharm-anticoagulant-drugs', 'saq', 'Give 4 adverse effects of heparin.', '[]'::jsonb, 'Any 4 of: bleeding; heparin-induced thrombocytopenia (with thrombosis); osteoporosis on prolonged use; hyperkalaemia (hypoaldosteronism); hypersensitivity reactions; alopecia; raised transaminases.', '[]'::jsonb, 'Bleeding is dose related. Heparin-induced thrombocytopenia type II is immune: IgG against heparin-platelet factor 4 complexes activates platelets, causing a falling count with paradoxical thrombosis 5 to 10 days into therapy. Heparin also inhibits aldosterone synthesis.', 'admin', 'published', 4, true, '[["bleeding", "haemorrhage", "hemorrhage"], ["thrombocytopenia", "hit"], ["osteoporosis"], ["hyperkalaemia", "hyperkalemia", "hypoaldosteronism"], ["hypersensitivity", "allergy"], ["alopecia", "hair loss"], ["raised transaminases"]]'::jsonb, 'saq p.074 Q2d, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-c5ba7d05fd', 'pharm-antihelminthics-ii-ectoparasites', 'saq', 'Briefly discuss the mechanism of action of praziquantel.', '[]'::jsonb, 'Praziquantel increases the permeability of the schistosome (and tapeworm) cell membrane to calcium. The calcium influx causes sustained muscle contraction and spastic paralysis, so the worms lose their grip on the vessel wall and are swept to the liver. It also causes vacuolisation and damage of the tegument, exposing parasite antigens to host immune attack.', '[]'::jsonb, 'The drug is effective against all schistosome species and most cestodes and trematodes (not Fasciola). It acts on adult worms far better than on immature schistosomula, which is why treatment is sometimes repeated after a few weeks.', 'admin', 'published', 3, true, '[["calcium permeability", "calcium influx", "increases permeability to calcium"], ["contraction", "spastic paralysis", "paralysis", "tetanic contraction"], ["tegument damage", "vacuolisation", "tegument"], ["host immune", "immune attack", "exposes antigens"]]'::jsonb, 'saq p.074 Q2e, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-5aa419b8fb', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'List five effects of angiotensin II.', '[]'::jsonb, 'Any 5 of: vasoconstriction (arteriolar), raising blood pressure; stimulates aldosterone secretion from the adrenal cortex (sodium and water retention); increases proximal tubular sodium reabsorption; stimulates ADH release and thirst; enhances sympathetic activity (noradrenaline release); constricts the efferent glomerular arteriole; promotes cardiac and vascular hypertrophy and remodelling; inhibits renin release (negative feedback).', '[]'::jsonb, 'Angiotensin II acts through AT1 receptors (Gq) to raise pressure quickly by vasoconstriction and slowly by sodium and water retention. Its trophic effects on heart and vessels explain why ACE inhibitors and ARBs improve survival in heart failure and after infarction.', 'admin', 'published', 5, true, '[["vasoconstriction", "raises blood pressure"], ["aldosterone", "aldosterone secretion"], ["sodium reabsorption", "sodium retention", "water retention"], ["adh", "vasopressin", "thirst"], ["sympathetic", "noradrenaline release"], ["efferent arteriole", "efferent constriction"], ["hypertrophy", "remodelling", "remodeling", "fibrosis"], ["inhibits renin"]]'::jsonb, 'saq p.074 Q3b, MBChB 2012/2013. The paper prints ''angiotensin I''; angiotensin I is essentially inactive, so angiotensin II is meant (a later paper asks for tissue effects of angiotensin II).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-14638fe71b', 'pharm-prostaglandins', 'saq', 'Give five clinical indications of prostaglandins, naming the prostaglandin analogue used for each.', '[]'::jsonb, 'Any 5 of: prevention of NSAID-induced peptic ulcer - misoprostol (PGE1); induction of labour and cervical ripening - dinoprostone (PGE2), misoprostol; medical abortion - misoprostol, gemeprost; postpartum haemorrhage - carboprost (15-methyl PGF2-alpha), misoprostol; open-angle glaucoma - latanoprost, travoprost, bimatoprost (PGF2-alpha); maintaining a patent ductus arteriosus - alprostadil (PGE1); erectile dysfunction - alprostadil; pulmonary hypertension - epoprostenol (PGI2), iloprost.', '[]'::jsonb, 'The uses follow the physiological actions: PGE analogues protect gastric mucosa, ripen the cervix and contract the uterus; PGF2-alpha analogues contract the uterus and increase uveoscleral outflow of aqueous humour; PGE1 keeps the ductus open; prostacyclin dilates pulmonary vessels and inhibits platelets.', 'admin', 'published', 5, true, '[["peptic ulcer", "nsaid ulcer", "misoprostol"], ["induction of labour", "cervical ripening", "dinoprostone"], ["abortion", "termination of pregnancy", "gemeprost"], ["postpartum haemorrhage", "pph", "carboprost"], ["glaucoma", "latanoprost", "travoprost", "bimatoprost"], ["patent ductus arteriosus", "alprostadil"], ["erectile dysfunction"], ["pulmonary hypertension", "epoprostenol", "iloprost", "prostacyclin"]]'::jsonb, 'saq p.074 Q3d, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-f5acf0755c', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List two insulin analogues.', '[]'::jsonb, 'Any 2 of: rapid-acting - insulin lispro, insulin aspart, insulin glulisine; long-acting - insulin glargine, insulin detemir, insulin degludec.', '[]'::jsonb, 'Analogues are human insulin with altered amino acids. Lispro, aspart and glulisine dissociate quickly into monomers and act within 15 minutes; glargine precipitates at tissue pH and detemir binds albumin, giving a flat, prolonged basal profile with less nocturnal hypoglycaemia.', 'admin', 'published', 2, true, '[["lispro"], ["aspart"], ["glulisine"], ["glargine"], ["detemir"], ["degludec"]]'::jsonb, 'saq p.074 Q3e(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-416c97d3a0', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List three key adverse effects of insulin therapy.', '[]'::jsonb, 'Any 3 of: hypoglycaemia; weight gain; lipodystrophy at injection sites (lipohypertrophy or lipoatrophy); local or systemic allergic reactions; hypokalaemia; insulin oedema; insulin resistance from antibodies.', '[]'::jsonb, 'Hypoglycaemia is the commonest and most dangerous effect, from excess dose, a missed meal or exercise. Insulin is anabolic, so weight rises, and repeated injection at one site causes local fat hypertrophy, which makes absorption erratic; sites should be rotated.', 'admin', 'published', 3, true, '[["hypoglycaemia", "hypoglycemia"], ["weight gain"], ["lipodystrophy", "lipohypertrophy", "lipoatrophy"], ["allergy", "hypersensitivity", "allergic reactions"], ["hypokalaemia", "hypokalemia"], ["oedema", "edema"], ["insulin resistance", "antibodies"]]'::jsonb, 'saq p.074 Q3e(ii), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-1fa353c830', 'pharm-indirect-acting-cholinomimetics', 'saq', 'Classify cholinesterase inhibitors, giving one example in each class.', '[]'::jsonb, '1. Reversible, short-acting (simple alcohol, binds electrostatically): edrophonium. 2. Reversible, intermediate-acting carbamates: neostigmine, physostigmine, pyridostigmine, rivastigmine (insecticide: carbaryl). 3. Irreversible organophosphates: echothiophate, malathion, parathion, nerve agents (sarin). (Centrally acting reversible agents for dementia: donepezil, galantamine.)', '[]'::jsonb, 'Classification follows how long the enzyme stays inhibited: edrophonium binds for minutes, carbamates carbamylate the active-site serine for hours, and organophosphates phosphorylate it with a bond that ''ages'' and becomes permanent, so recovery needs new enzyme unless an oxime is given early.', 'admin', 'published', 4, true, '[["reversible"], ["edrophonium", "short acting", "alcohol"], ["carbamates", "neostigmine", "physostigmine", "pyridostigmine", "rivastigmine"], ["irreversible"], ["organophosphates", "echothiophate", "malathion", "parathion", "sarin", "ecothiopate"], ["donepezil", "galantamine", "tacrine"]]'::jsonb, 'saq p.074 Q4a, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-9ea5c279d7', 'pharm-vinca-alkaloids-platinum-agents', 'saq', 'What is the mechanism of action of vincristine?', '[]'::jsonb, 'Vincristine binds beta-tubulin and inhibits its polymerisation into microtubules. The mitotic spindle cannot form, so dividing cells arrest in metaphase (M phase-specific) and die.', '[]'::jsonb, 'Vinca alkaloids prevent microtubule assembly, whereas taxanes stabilise microtubules and prevent their disassembly; both block mitosis. Because microtubules are also needed for axonal transport, vincristine''s dose-limiting toxicity is peripheral neuropathy rather than myelosuppression.', 'admin', 'published', 2, true, '[["tubulin", "binds tubulin", "beta-tubulin"], ["inhibits polymerisation", "inhibits microtubule formation", "prevents microtubule assembly", "microtubules"], ["mitotic spindle", "spindle"], ["metaphase arrest", "m phase", "mitosis"]]'::jsonb, 'saq p.075 Q4c(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-7915c35981', 'pharm-antivirals', 'saq', 'What is the mechanism of action of zanamivir?', '[]'::jsonb, 'Zanamivir is a sialic acid analogue that competitively inhibits the neuraminidase of influenza A and B viruses. New virions cannot cleave sialic acid residues, so they stay attached to the host cell and to each other and cannot be released to spread through the respiratory tract.', '[]'::jsonb, 'Neuraminidase inhibitors (zanamivir inhaled, oseltamivir oral) act at the last step of the viral cycle and must be started within 48 hours of symptoms. Amantadine instead blocks the M2 proton channel needed for uncoating and works only against influenza A.', 'admin', 'published', 2, true, '[["neuraminidase inhibitor", "inhibits neuraminidase", "neuraminidase"], ["sialic acid", "sialic acid analogue"], ["prevents release", "blocks viral release", "virions not released", "prevents spread"], ["influenza a and b", "influenza"]]'::jsonb, 'saq p.075 Q4c(ii), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-f6f27697c5', 'pharm-anti-fungals', 'saq', 'What is the mechanism of action of amphotericin B, and how does resistance to it develop?', '[]'::jsonb, 'Amphotericin B is a polyene that binds ergosterol in the fungal cell membrane and forms pores (channels). Potassium, magnesium and other cell contents leak out and the cell dies (fungicidal). Resistance, which is uncommon, arises from reduced ergosterol content or a modified sterol in the membrane with lower affinity for the drug.', '[]'::jsonb, 'Selectivity depends on the drug''s higher affinity for fungal ergosterol than for human cholesterol; residual binding to cholesterol explains nephrotoxicity and infusion reactions. Azoles act differently, by blocking ergosterol synthesis.', 'admin', 'published', 3, true, '[["binds ergosterol", "ergosterol"], ["pores", "channels", "pore formation"], ["leakage", "loss of potassium", "leak of ions", "increased permeability"], ["fungicidal", "cell death"], ["reduced ergosterol", "altered ergosterol", "decreased ergosterol", "modified sterol"]]'::jsonb, 'saq p.075 Q4c(iii), MBChB 2012/2013. Merged with JB revision Q9 (mechanism of action and mechanism of development of resistance).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-b44f44782d', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'What is the mechanism of action of sulfasalazine?', '[]'::jsonb, 'Sulfasalazine is a prodrug: colonic bacteria (azoreductases) split it into 5-aminosalicylic acid (mesalazine) and sulfapyridine. 5-ASA acts locally in the colon, inhibiting prostaglandin and leukotriene synthesis, scavenging free radicals and reducing cytokine production (NF-kB inhibition); it is the active part in inflammatory bowel disease. Sulfapyridine is absorbed and is thought to give the disease-modifying effect in rheumatoid arthritis.', '[]'::jsonb, 'The azo bond delivers 5-ASA to the colon, which is why sulfasalazine works in ulcerative colitis. Most of its adverse effects (nausea, rash, haemolysis, reversible oligospermia) come from the sulfapyridine part, so mesalazine alone is better tolerated in bowel disease.', 'admin', 'published', 2, true, '[["prodrug", "split by colonic bacteria", "azoreductase", "bacterial cleavage"], ["5-aminosalicylic acid", "5-asa", "mesalazine", "mesalamine"], ["sulfapyridine", "sulphapyridine"], ["inhibits prostaglandin", "leukotriene", "anti-inflammatory", "free radical scavenger", "cytokines"]]'::jsonb, 'saq p.075 Q4c(iv), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-99d5268c16', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'saq', 'Classify drugs used in the treatment of peptic ulcer disease, with one example in each class and its mechanism.', '[]'::jsonb, '1. Proton pump inhibitors (omeprazole, esomeprazole, pantoprazole): irreversibly inhibit H+/K+-ATPase. 2. H2-receptor antagonists (ranitidine, cimetidine, famotidine): block histamine H2 receptors on parietal cells. 3. Antacids (magnesium hydroxide, aluminium hydroxide, calcium carbonate): neutralise acid. 4. Mucosal protective agents (sucralfate, bismuth subcitrate): coat the ulcer base. 5. Prostaglandin analogues (misoprostol): reduce acid, increase mucus and bicarbonate. 6. Antimuscarinics (pirenzepine): M1 block. 7. Anti-Helicobacter pylori antibiotics (clarithromycin, amoxicillin, metronidazole).', '[]'::jsonb, 'Ulcers form when acid and pepsin overcome mucosal defence, usually because of H. pylori or NSAIDs. Treatment therefore reduces acid (PPIs most effectively, as the proton pump is the final common step), neutralises it, strengthens the mucosal barrier or eradicates the organism with triple therapy.', 'admin', 'published', 5, true, '[["proton pump inhibitors", "ppi", "omeprazole", "esomeprazole", "pantoprazole"], ["h2 antagonists", "h2 blockers", "ranitidine", "cimetidine", "famotidine"], ["antacids", "magnesium hydroxide", "aluminium hydroxide", "calcium carbonate"], ["sucralfate", "bismuth", "cytoprotective", "mucosal protective"], ["misoprostol", "prostaglandin analogue"], ["pirenzepine", "antimuscarinic"], ["h. pylori eradication", "clarithromycin", "amoxicillin", "metronidazole", "antibiotics"]]'::jsonb, 'saq p.075 Q5b, MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-fb68a31845', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'saq', 'List 5 adverse effects of quinine in different body systems.', '[]'::jsonb, 'Any 5 in different systems: special senses - cinchonism (tinnitus, deafness, blurred vision, vertigo); metabolic - hypoglycaemia; cardiovascular - hypotension, QT prolongation, arrhythmias; gastrointestinal - nausea, vomiting; blood - haemolysis in G6PD deficiency, blackwater fever, thrombocytopenia; CNS - headache, confusion; skin - rash, flushing; uterus - contractions.', '[]'::jsonb, 'Cinchonism is common at therapeutic doses. Quinine stimulates insulin release from beta cells, so hypoglycaemia is a particular danger in pregnancy and severe malaria, and it has quinidine-like cardiac depressant effects, which is why it must never be given as an intravenous bolus.', 'admin', 'published', 5, true, '[["cinchonism", "tinnitus", "deafness", "hearing loss", "blurred vision"], ["hypoglycaemia", "hypoglycemia"], ["hypotension", "arrhythmia", "qt prolongation"], ["nausea", "vomiting"], ["haemolysis", "hemolysis", "blackwater fever", "thrombocytopenia"], ["headache", "confusion", "vertigo"], ["rash", "flushing"], ["uterine contractions"]]'::jsonb, 'saq p.075 Q5c(i), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-c78df221e1', 'pharm-emergency-management-of-poisoning', 'saq', 'List 2 contraindications to the use of emetics (induced vomiting) in poisoned patients.', '[]'::jsonb, 'Any 2 of: ingestion of corrosives (strong acids or alkalis); ingestion of petroleum distillates or hydrocarbons such as paraffin (kerosene); unconscious, drowsy or convulsing patient (unprotected airway); poisons likely to cause rapid coma or convulsions; infants under 6 months.', '[]'::jsonb, 'Vomiting re-exposes the oesophagus to corrosives and can cause perforation; volatile hydrocarbons are easily aspirated and cause chemical pneumonitis; and a patient who cannot protect the airway will aspirate. Ipecacuanha-induced emesis is in any case no longer recommended.', 'admin', 'draft', 2, true, '[["corrosive", "corrosives", "acid", "alkali"], ["paraffin", "kerosene", "hydrocarbons", "petroleum"], ["unconscious", "coma", "reduced consciousness", "drowsy"], ["convulsions", "seizures"], ["unprotected airway", "aspiration"]]'::jsonb, 'saq p.075 Q5d(i), MBChB 2012/2013. The paper prints ''antiemetics''; the question only makes sense as ''emetics'', so the wording was corrected.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-59d938c9c8', 'pharm-anti-fungals', 'saq', 'List 2 organisms that are sensitive to amphotericin B.', '[]'::jsonb, 'Any 2 of: Candida albicans (and most Candida species); Cryptococcus neoformans; Aspergillus fumigatus; Histoplasma capsulatum; Blastomyces dermatitidis; Coccidioides immitis; Mucor and Rhizopus (mucormycosis); Leishmania species.', '[]'::jsonb, 'Amphotericin B has the broadest spectrum of any antifungal and is the drug of choice for life-threatening systemic mycoses such as cryptococcal meningitis (with flucytosine) and mucormycosis. Liposomal amphotericin is also first line for visceral leishmaniasis.', 'admin', 'published', 2, true, '[["candida", "candida albicans"], ["cryptococcus", "cryptococcus neoformans"], ["aspergillus"], ["histoplasma"], ["blastomyces", "coccidioides"], ["mucor", "rhizopus", "mucormycosis"], ["leishmania"]]'::jsonb, 'saq p.075 Q5d(ii), MBChB 2012/2013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-b4d3a8f3d9', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Discuss the mechanisms of noradrenaline (norepinephrine) production, storage, release and recycling.', '[]'::jsonb, 'Synthesis: tyrosine is taken up into the nerve terminal and converted by tyrosine hydroxylase (rate-limiting step) to DOPA, then by DOPA decarboxylase to dopamine. Storage: dopamine enters vesicles through the vesicular monoamine transporter (VMAT, blocked by reserpine) and is converted there to noradrenaline by dopamine beta-hydroxylase. Release: an action potential opens calcium channels and calcium triggers exocytosis (blocked by guanethidine; inhibited by presynaptic alpha-2 receptors). Termination and recycling: most noradrenaline is taken back into the neurone by the noradrenaline transporter (uptake 1, blocked by cocaine and tricyclic antidepressants) and re-stored in vesicles or broken down by MAO; the rest is taken up by non-neuronal cells (uptake 2) and metabolised by COMT, giving VMA in urine.', '[]'::jsonb, 'Each step is a drug target: metyrosine blocks tyrosine hydroxylase, reserpine empties the vesicles, guanethidine blocks release, cocaine and tricyclics block neuronal reuptake, and MAO inhibitors prevent breakdown. Reuptake, not enzymatic breakdown, is the main way the action of noradrenaline is ended.', 'admin', 'published', 5, true, '[["tyrosine"], ["tyrosine hydroxylase", "rate limiting"], ["dopa", "dopamine", "dopa decarboxylase"], ["dopamine beta-hydroxylase", "dopamine beta hydroxylase"], ["vesicles", "vmat", "reserpine"], ["calcium", "exocytosis"], ["reuptake", "uptake 1", "net", "noradrenaline transporter", "cocaine"], ["mao", "comt", "vma"]]'::jsonb, 'saq p.078 Q1b, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-2306315ef4', 'pharm-sympathomimetics', 'saq', 'Classify sympathomimetic agents by chemical structure, with examples.', '[]'::jsonb, 'Catecholamines (have the 3,4-dihydroxybenzene catechol ring): adrenaline, noradrenaline, dopamine (endogenous); isoprenaline, dobutamine (synthetic). Non-catecholamines: ephedrine, amphetamine, phenylephrine, salbutamol, terbutaline, pseudoephedrine.', '[]'::jsonb, 'The catechol group gives high potency at adrenoceptors but makes the drug a substrate for COMT and MAO, so catecholamines are inactive orally, short acting and do not enter the brain. Non-catecholamines are orally active, longer acting and often have central effects.', 'admin', 'published', 3, true, '[["catecholamines", "catechol"], ["adrenaline", "noradrenaline", "dopamine", "isoprenaline", "dobutamine", "epinephrine", "norepinephrine"], ["non-catecholamines", "noncatecholamines"], ["ephedrine", "amphetamine", "phenylephrine", "salbutamol", "terbutaline"]]'::jsonb, 'saq p.078 Q2a(i), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-b450b57bb1', 'pharm-sympathomimetics', 'saq', 'Classify sympathomimetic agents by mode of action, with examples.', '[]'::jsonb, 'Direct-acting (activate adrenoceptors): adrenaline, noradrenaline, isoprenaline, phenylephrine, salbutamol, dobutamine. Indirect-acting (release noradrenaline or block its reuptake): amphetamine, tyramine (releasers); cocaine, tricyclic antidepressants (reuptake blockers). Mixed-acting (both): ephedrine, pseudoephedrine.', '[]'::jsonb, 'Indirect agents depend on stored noradrenaline, so their effect is lost after reserpine or denervation and shows tachyphylaxis; direct agents still work and may even be potentiated. Tyramine in food causes the ''cheese reaction'' in patients on MAO inhibitors by this indirect mechanism.', 'admin', 'published', 3, true, '[["direct", "direct acting"], ["adrenaline", "noradrenaline", "phenylephrine", "salbutamol", "isoprenaline", "dobutamine"], ["indirect", "indirect acting"], ["amphetamine", "tyramine", "cocaine"], ["mixed", "mixed acting"], ["ephedrine", "pseudoephedrine"]]'::jsonb, 'saq p.078 Q2a(ii), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-aec0c2dba5', 'pharm-sympathomimetics', 'saq', 'Classify sympathomimetic agents by receptor selectivity, with examples.', '[]'::jsonb, 'Alpha-1 selective: phenylephrine, methoxamine. Alpha-2 selective: clonidine, methyldopa (via its metabolite). Beta-1 selective: dobutamine. Beta-2 selective: salbutamol, terbutaline, salmeterol. Non-selective beta (beta-1 and beta-2): isoprenaline. Mixed alpha and beta: adrenaline (alpha-1, alpha-2, beta-1, beta-2), noradrenaline (alpha-1, alpha-2, beta-1). Dopamine: D1, beta-1 and alpha with rising dose.', '[]'::jsonb, 'Selectivity determines the clinical use: alpha-1 agonists constrict vessels (decongestant, pressor), alpha-2 agonists reduce central sympathetic outflow, beta-1 agonists stimulate the heart and beta-2 agonists relax bronchial and uterine smooth muscle. Selectivity is relative and is lost at high doses.', 'admin', 'published', 4, true, '[["alpha-1", "phenylephrine", "methoxamine"], ["alpha-2", "clonidine", "methyldopa"], ["beta-1", "dobutamine"], ["beta-2", "salbutamol", "terbutaline", "salmeterol"], ["isoprenaline", "non-selective beta"], ["adrenaline", "noradrenaline", "mixed"], ["dopamine"]]'::jsonb, 'saq p.078 Q2a(iii), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-f39e2af14b', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'What are the organ effects of sympathetic nervous system activation? Name the specific adrenoceptor through which each effect occurs.', '[]'::jsonb, 'Heart: increased rate, contractility and conduction (beta-1). Blood vessels: constriction in skin, mucosa and viscera (alpha-1); dilatation in skeletal muscle (beta-2). Bronchi: relaxation (beta-2). Eye: mydriasis by contraction of the radial muscle (alpha-1). Gut: reduced motility (alpha-2, beta-2), sphincter contraction (alpha-1). Bladder: detrusor relaxation (beta-2, beta-3), sphincter contraction (alpha-1). Uterus: relaxation (beta-2). Liver: glycogenolysis and gluconeogenesis (beta-2, alpha-1). Fat: lipolysis (beta-3). Kidney: renin release (beta-1). Pancreas: reduced insulin secretion (alpha-2).', '[]'::jsonb, 'The pattern is the ''fight or flight'' response: more cardiac output, blood diverted to muscle, open airways and mobilised fuel. Alpha-1 receptors (Gq) contract smooth muscle, beta receptors (Gs, cAMP) stimulate the heart and relax smooth muscle, and alpha-2 receptors (Gi) are mainly inhibitory.', 'admin', 'published', 5, true, '[["heart rate", "contractility", "beta-1", "tachycardia"], ["vasoconstriction", "alpha-1"], ["vasodilation", "skeletal muscle vessels", "beta-2"], ["bronchodilation", "bronchial relaxation"], ["mydriasis", "pupil dilation"], ["reduced gut motility", "sphincter contraction"], ["glycogenolysis", "lipolysis", "beta-3"], ["renin release"], ["uterine relaxation", "bladder relaxation"]]'::jsonb, 'saq p.078 Q2b, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-7c606a7692', 'pharm-sympathomimetics', 'saq', 'Give the clinical indications for the use of sympathomimetic agents.', '[]'::jsonb, 'Any 5 of: anaphylactic shock and cardiac arrest (adrenaline); septic and other hypotensive shock (noradrenaline); cardiogenic shock and acute heart failure (dobutamine, dopamine); bronchial asthma (salbutamol, salmeterol); nasal decongestion (phenylephrine, pseudoephedrine, oxymetazoline); with local anaesthetics to prolong their action and for local haemostasis (adrenaline); mydriasis for fundoscopy (phenylephrine); premature labour (salbutamol, terbutaline, ritodrine); heart block (isoprenaline); attention deficit hyperactivity disorder and narcolepsy (methylphenidate, amphetamine); hypertension (clonidine, methyldopa); glaucoma (brimonidine, apraclonidine).', '[]'::jsonb, 'Uses map onto receptors: alpha-1 for vasoconstriction (decongestant, pressor, prolonging local anaesthesia), beta-1 for cardiac stimulation, beta-2 for bronchodilatation and uterine relaxation, alpha-2 for lowering blood pressure and aqueous humour. Adrenaline''s combined alpha and beta actions make it the drug of anaphylaxis.', 'admin', 'published', 5, true, '[["anaphylaxis", "anaphylactic shock"], ["cardiac arrest"], ["shock", "hypotension", "septic shock"], ["cardiogenic shock", "heart failure", "dobutamine", "dopamine"], ["asthma", "bronchodilator", "salbutamol"], ["nasal decongestant", "decongestion"], ["local anaesthetic", "haemostasis"], ["mydriasis", "mydriatic"], ["premature labour", "tocolysis"], ["adhd", "narcolepsy"], ["glaucoma", "hypertension", "clonidine"]]'::jsonb, 'saq p.078 Q2c, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympatholytics-74c4667d3c', 'pharm-sympatholytics', 'saq', 'Define a sympatholytic agent.', '[]'::jsonb, 'A drug that opposes or reduces the effects of sympathetic nervous system activity, either by blocking adrenoceptors (alpha- and beta-blockers), by reducing central sympathetic outflow (clonidine, methyldopa), or by preventing the synthesis, storage or release of noradrenaline at the adrenergic nerve ending (reserpine, guanethidine, metyrosine).', '[]'::jsonb, 'The term covers more than receptor antagonists: anything that lowers sympathetic drive counts, from the vasomotor centre (clonidine) through the nerve terminal (reserpine, guanethidine) to the receptor (prazosin, propranolol). Their main uses are in hypertension and other cardiovascular disease.', 'admin', 'published', 2, true, '[["opposes sympathetic", "reduces sympathetic activity", "inhibits sympathetic", "blocks sympathetic"], ["adrenoceptor blockers", "alpha blockers", "beta blockers", "receptor antagonists"], ["adrenergic neurone blockers", "reserpine", "guanethidine", "clonidine", "methyldopa", "centrally acting"]]'::jsonb, 'saq p.078 Q3a, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-070029c95a', 'pharm-anti-retrovirals', 'saq', 'Describe the steps of the HIV life cycle.', '[]'::jsonb, '1. Attachment: gp120 binds CD4 and a co-receptor (CCR5 or CXCR4). 2. Fusion of viral and cell membranes (gp41) and entry/uncoating. 3. Reverse transcription of viral RNA into double-stranded DNA by reverse transcriptase. 4. Integration of proviral DNA into the host genome by integrase. 5. Transcription and translation into viral RNA and polyproteins. 6. Assembly and budding of immature virions. 7. Maturation: protease cleaves the gag-pol polyproteins to give infectious virus.', '[]'::jsonb, 'Each step is a drug target: CCR5 antagonists (maraviroc) and fusion inhibitors (enfuvirtide) block entry, NRTIs and NNRTIs block reverse transcription, integrase inhibitors (dolutegravir) block integration and protease inhibitors block maturation.', 'admin', 'published', 5, true, '[["attachment", "binding", "gp120", "cd4", "ccr5"], ["fusion", "entry", "gp41"], ["reverse transcription", "reverse transcriptase"], ["integration", "integrase"], ["transcription", "translation"], ["assembly", "budding"], ["maturation", "protease"]]'::jsonb, 'saq p.119 Q1, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-b5b5889905', 'pharm-anti-retrovirals', 'saq', 'Classify the antiretroviral drugs, with 2 examples in each class.', '[]'::jsonb, '1. Nucleoside/nucleotide reverse transcriptase inhibitors (NRTIs): zidovudine, lamivudine, abacavir, tenofovir, emtricitabine. 2. Non-nucleoside reverse transcriptase inhibitors (NNRTIs): efavirenz, nevirapine, etravirine, rilpivirine. 3. Protease inhibitors: lopinavir, atazanavir, darunavir, ritonavir. 4. Integrase strand transfer inhibitors: dolutegravir, raltegravir. 5. Entry inhibitors: fusion inhibitor enfuvirtide; CCR5 antagonist maraviroc.', '[]'::jsonb, 'Classes are defined by the step of the viral life cycle they block. Combination therapy uses at least three drugs from two classes, typically two NRTIs plus an integrase inhibitor, an NNRTI or a boosted protease inhibitor, to suppress the virus and prevent resistance.', 'admin', 'published', 5, true, '[["nrti", "nucleoside reverse transcriptase inhibitors", "zidovudine", "lamivudine", "tenofovir", "abacavir"], ["nnrti", "non-nucleoside", "efavirenz", "nevirapine", "etravirine", "rilpivirine"], ["protease inhibitors", "lopinavir", "atazanavir", "darunavir", "ritonavir"], ["integrase inhibitors", "dolutegravir", "raltegravir"], ["fusion inhibitor", "enfuvirtide"], ["ccr5 antagonist", "maraviroc", "entry inhibitors"]]'::jsonb, 'saq p.119 Q2, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-c4dcc50deb', 'pharm-anti-retrovirals', 'saq', 'Which classes of antiretroviral drugs have no activity against HIV-2?', '[]'::jsonb, 'Non-nucleoside reverse transcriptase inhibitors (NNRTIs, e.g. efavirenz, nevirapine) and the fusion inhibitor enfuvirtide.', '[]'::jsonb, 'HIV-2 reverse transcriptase has a naturally different NNRTI binding pocket, and its gp41 differs from the HIV-1 sequence that enfuvirtide mimics, so both are intrinsically resistant. HIV-2 is treated with NRTIs plus an integrase inhibitor or a boosted protease inhibitor such as lopinavir or darunavir.', 'admin', 'published', 2, true, '[["nnrti", "nnrtis", "non-nucleoside reverse transcriptase inhibitors", "efavirenz", "nevirapine"], ["fusion inhibitor", "enfuvirtide"]]'::jsonb, 'saq p.119 Q3, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-1d805f365b', 'pharm-anti-retrovirals', 'saq', 'What is the mechanism of action of each class of antiretroviral drugs?', '[]'::jsonb, 'NRTIs: phosphorylated by host kinases to triphosphates that compete with natural nucleotides for reverse transcriptase and, lacking a 3''-OH group, terminate the DNA chain. NNRTIs: bind an allosteric pocket on HIV-1 reverse transcriptase (non-competitive, no activation needed). Protease inhibitors: inhibit HIV protease so gag-pol polyproteins are not cleaved, giving immature non-infectious virions. Integrase inhibitors: block strand transfer of viral DNA into host DNA. Fusion inhibitor (enfuvirtide): binds gp41 and prevents membrane fusion. CCR5 antagonist (maraviroc): blocks the host CCR5 co-receptor so gp120 cannot bind.', '[]'::jsonb, 'NRTIs are prodrugs needing intracellular phosphorylation, which is why they also affect host polymerases; NNRTIs are active as given but resistance needs only one mutation. Maraviroc is unusual in targeting a host protein and works only against CCR5-tropic virus.', 'admin', 'published', 5, true, '[["chain termination", "chain terminators", "competitive inhibition of reverse transcriptase", "triphosphate"], ["allosteric", "non-competitive", "binds reverse transcriptase directly"], ["protease", "polyprotein cleavage", "immature virions"], ["integrase", "strand transfer", "integration"], ["gp41", "fusion"], ["ccr5", "co-receptor"]]'::jsonb, 'saq p.119 Q4, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-47cd8f44e1', 'pharm-antiretroviral-i', 'saq', 'What is the mechanism of resistance to the thymidine analogues zidovudine (AZT) and stavudine (d4T)?', '[]'::jsonb, 'Thymidine analogue mutations (TAMs) in the reverse transcriptase gene (e.g. M41L, D67N, K70R, L210W, T215Y/F, K219Q/E). The mutant enzyme removes (excises) the chain-terminating drug from the end of the DNA chain by ATP-dependent pyrophosphorolysis, so synthesis continues. TAMs accumulate stepwise and give cross-resistance to other NRTIs.', '[]'::jsonb, 'There are two ways reverse transcriptase escapes NRTIs: discrimination, where the enzyme no longer incorporates the drug (M184V for lamivudine, K65R for tenofovir), and excision, where an incorporated drug is cut out again; TAMs act by excision.', 'admin', 'published', 2, true, '[["thymidine analogue mutations", "tams", "mutations in reverse transcriptase", "rt mutations"], ["excision", "removal of drug", "pyrophosphorolysis", "primer unblocking"], ["cross-resistance", "t215y", "m41l", "k70r"]]'::jsonb, 'saq p.119 Q5a, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-c29b4e2f7a', 'pharm-antiretroviral-ii', 'saq', 'What are the mechanisms of resistance to maraviroc?', '[]'::jsonb, '1. Tropism shift: outgrowth of virus that uses the CXCR4 co-receptor (X4 or dual-tropic virus), which maraviroc does not block. 2. Mutations in the V3 loop of gp120 that allow the virus to bind CCR5 even when maraviroc is bound to it.', '[]'::jsonb, 'Because maraviroc blocks only the CCR5 co-receptor, a tropism test must show purely R5 virus before it is used. Failure usually reflects pre-existing minority CXCR4-using virus being selected rather than new mutations.', 'admin', 'published', 2, true, '[["cxcr4", "x4 virus", "tropism switch", "tropism shift", "dual tropic"], ["v3 loop", "gp120 mutations", "binds drug-bound ccr5", "mutations in gp120"]]'::jsonb, 'saq p.119 Q5b, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-38e1ed83e6', 'pharm-anti-retrovirals', 'saq', 'Write notes on the pharmacokinetics of the first-line antiretroviral drugs in adults: tenofovir (TDF), lamivudine (3TC) and efavirenz (EFV).', '[]'::jsonb, 'Tenofovir disoproxil: ester prodrug, oral bioavailability about 25% (higher with a fatty meal); converted to tenofovir then the active diphosphate, whose long intracellular half-life allows once-daily dosing; low protein binding; excreted unchanged by the kidney (filtration and tubular secretion), so the dose is reduced in renal impairment. Lamivudine: bioavailability over 80%, not affected by food; low protein binding; long intracellular triphosphate half-life; excreted mostly unchanged in urine. Efavirenz: well absorbed (fatty meals increase levels and CNS effects, so taken at bedtime on an empty stomach); over 99% protein bound; half-life 40 to 55 hours (once daily); metabolised by CYP2B6 and CYP3A4; induces CYP3A4 and its own metabolism.', '[]'::jsonb, 'All three have long effective half-lives, which is why they can be combined in one tablet taken once daily. The two NRTIs are cleared by the kidney and have few metabolic interactions; efavirenz is cleared by the liver and, as an enzyme inducer, is the source of most interactions.', 'admin', 'published', 5, true, '[["prodrug", "tenofovir disoproxil"], ["once daily", "long intracellular half-life"], ["renal excretion", "excreted unchanged", "kidney"], ["dose adjustment in renal impairment", "renal impairment"], ["bioavailability"], ["highly protein bound", "99% protein bound"], ["cyp2b6", "cyp3a4", "hepatic metabolism"], ["enzyme inducer", "autoinduction", "induces cyp3a4"], ["long half-life", "40-55 hours"]]'::jsonb, 'saq p.119 Q6, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-da96d3f05c', 'pharm-anti-retrovirals', 'saq', 'What are the common (class) adverse effects of each class of antiretroviral drugs?', '[]'::jsonb, 'NRTIs: mitochondrial toxicity - lactic acidosis with hepatic steatosis, peripheral neuropathy, pancreatitis, lipoatrophy, myopathy. NNRTIs: rash (including Stevens-Johnson syndrome), hepatotoxicity, drug interactions through CYP enzymes. Protease inhibitors: nausea and diarrhoea, dyslipidaemia, insulin resistance and hyperglycaemia, lipodystrophy (fat redistribution), raised transaminases, CYP3A4 inhibition. Integrase inhibitors: insomnia, headache, weight gain, raised creatine kinase. Fusion inhibitor: injection-site reactions.', '[]'::jsonb, 'Class effects follow the mechanism: NRTIs inhibit mitochondrial DNA polymerase gamma; NNRTIs are immunogenic and metabolised by the liver; protease inhibitors disturb lipid and glucose metabolism. Knowing the class effect lets you anticipate toxicity with any member.', 'admin', 'published', 5, true, '[["lactic acidosis", "mitochondrial toxicity", "hepatic steatosis", "peripheral neuropathy", "lipoatrophy"], ["rash", "stevens-johnson"], ["hepatotoxicity", "hepatitis"], ["gi intolerance", "diarrhoea", "nausea"], ["dyslipidaemia", "hyperlipidaemia", "hyperglycaemia", "insulin resistance", "lipodystrophy"], ["insomnia", "headache", "weight gain"], ["injection site reactions"]]'::jsonb, 'saq p.119 Q7, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-d66c7e6a31', 'pharm-anti-retrovirals', 'saq', 'What are the unique (characteristic) adverse effects of tenofovir (TDF), abacavir (ABC), enfuvirtide, zidovudine (AZT) and efavirenz (EFV)?', '[]'::jsonb, 'TDF: nephrotoxicity (proximal tubular damage, Fanconi syndrome) and reduced bone mineral density. ABC: hypersensitivity reaction associated with HLA-B*57:01 (fever, rash, GI and respiratory symptoms; fatal on rechallenge). Enfuvirtide: painful injection-site reactions (nodules). AZT: bone marrow suppression with macrocytic anaemia and neutropenia; also myopathy, nail pigmentation. EFV: neuropsychiatric effects (vivid dreams, dizziness, insomnia, depression), rash, gynaecomastia.', '[]'::jsonb, 'These signature toxicities drive monitoring: creatinine for tenofovir, HLA-B*57:01 testing before abacavir, haemoglobin for zidovudine, and counselling to take efavirenz at bedtime. Abacavir must never be restarted after a hypersensitivity reaction.', 'admin', 'published', 5, true, '[["nephrotoxicity", "fanconi syndrome", "renal toxicity", "bone density", "osteoporosis"], ["hypersensitivity", "hla-b*5701", "hla-b5701"], ["injection site reactions", "injection site nodules"], ["anaemia", "anemia", "bone marrow suppression", "neutropenia", "myopathy"], ["vivid dreams", "nightmares", "neuropsychiatric", "cns effects", "dizziness", "depression"]]'::jsonb, 'saq p.119 Q8, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-e4c3b2b078', 'pharm-drug-interactions', 'saq', 'Give 2 examples of drugs that are enzyme inducers and 2 examples of drugs that are enzyme inhibitors.', '[]'::jsonb, 'Enzyme inducers (any 2): rifampicin, phenytoin, carbamazepine, phenobarbital, efavirenz, nevirapine, griseofulvin, St John''s wort, chronic alcohol. Enzyme inhibitors (any 2): ritonavir (and cobicistat), ketoconazole, fluconazole, erythromycin, clarithromycin, cimetidine, isoniazid, ciprofloxacin, sodium valproate, grapefruit juice.', '[]'::jsonb, 'Inducers increase synthesis of cytochrome P450 enzymes over days to weeks, lowering levels of co-administered drugs (failed contraception, failed antiretroviral therapy). Inhibitors act within hours and raise levels, causing toxicity; ritonavir''s potent CYP3A4 inhibition is exploited to boost other protease inhibitors.', 'admin', 'published', 4, true, '[["rifampicin", "rifampin"], ["phenytoin", "carbamazepine", "phenobarbital", "phenobarbitone", "efavirenz", "nevirapine", "griseofulvin", "st john''s wort"], ["ritonavir", "cobicistat", "ketoconazole", "fluconazole", "itraconazole"], ["erythromycin", "clarithromycin", "cimetidine", "isoniazid", "ciprofloxacin", "valproate", "grapefruit juice"]]'::jsonb, 'saq p.119 Q9, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-b832f80e72', 'pharm-biotransformation', 'saq', 'What is autoinduction?', '[]'::jsonb, 'The process by which a drug induces the enzymes responsible for its own metabolism, so that with repeated dosing its clearance rises, its half-life shortens and its plasma concentration falls, and the dose may need to be increased. Examples: carbamazepine, efavirenz, nevirapine, rifampicin.', '[]'::jsonb, 'Carbamazepine is the classic example: its half-life falls from about 36 hours to 15 to 20 hours over the first weeks. Nevirapine''s autoinduction is the reason for its two-week lead-in at half dose.', 'admin', 'published', 2, true, '[["induces its own metabolism", "own metabolism", "induces own enzymes"], ["clearance increases", "half-life shortens", "plasma levels fall", "reduced concentration"], ["carbamazepine", "nevirapine", "efavirenz", "rifampicin"]]'::jsonb, 'saq p.119 Q10, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-3791caf5e2', 'pharm-anti-retrovirals', 'saq', 'What are the indications of antiretroviral drugs?', '[]'::jsonb, '1. Treatment of established HIV infection (all people living with HIV, regardless of CD4 count). 2. Prevention of mother-to-child transmission (PMTCT), including infant prophylaxis. 3. Post-exposure prophylaxis (PEP) after occupational or sexual exposure. 4. Pre-exposure prophylaxis (PrEP) in people at high risk. 5. Treatment of chronic hepatitis B (tenofovir, lamivudine).', '[]'::jsonb, 'Because viral suppression prevents both disease progression and onward transmission, treatment is offered to everyone with HIV (''test and treat''). The same drugs given before or shortly after exposure, or to mother and baby, prevent infection being established.', 'admin', 'published', 3, true, '[["treatment of hiv", "hiv infection", "hiv/aids"], ["pmtct", "mother-to-child", "mother to child transmission"], ["post-exposure prophylaxis", "pep"], ["pre-exposure prophylaxis", "prep"], ["hepatitis b"]]'::jsonb, 'saq p.119 Q11, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-59846402c0', 'pharm-antiretroviral-i', 'saq', 'Describe the drug interaction between zidovudine (AZT) and stavudine (d4T).', '[]'::jsonb, 'They are antagonistic and must not be combined. Both are thymidine analogues activated by the same enzyme, thymidine kinase; zidovudine has the higher affinity and inhibits the intracellular phosphorylation of stavudine to its active triphosphate.', '[]'::jsonb, 'Two analogues of the same nucleoside compete for the same activating kinase and the same site on reverse transcriptase, so they are never paired (the same applies to lamivudine with emtricitabine, both cytidine analogues). An NRTI backbone pairs analogues of different bases.', 'admin', 'published', 2, true, '[["antagonism", "antagonistic", "should not be combined", "avoid combination"], ["thymidine analogues", "both thymidine analogues"], ["thymidine kinase", "compete for phosphorylation", "same activation pathway", "reduced phosphorylation"]]'::jsonb, 'saq p.119 Q13a, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-6a00548620', 'pharm-drug-interactions', 'saq', 'Describe the drug interaction between nevirapine and rifampicin.', '[]'::jsonb, 'Rifampicin induces CYP3A4 and CYP2B6, the enzymes that metabolise nevirapine, lowering nevirapine plasma concentrations by 20 to 55% with a risk of virological failure and resistance. Both drugs are hepatotoxic, so the risk of hepatitis is additive. Efavirenz (or dolutegravir at double dose) is preferred during rifampicin-based tuberculosis treatment.', '[]'::jsonb, 'Rifampicin is the most potent clinical enzyme inducer and lowers levels of NNRTIs, protease inhibitors and integrase inhibitors. Efavirenz is least affected, which is why it became the NNRTI of choice in patients with HIV and tuberculosis.', 'admin', 'published', 2, true, '[["enzyme induction", "rifampicin induces", "cyp3a4", "cyp2b6"], ["reduced nevirapine levels", "lower nevirapine", "decreased concentration"], ["treatment failure", "resistance", "virological failure"], ["hepatotoxicity", "additive liver toxicity"], ["efavirenz preferred", "use efavirenz"]]'::jsonb, 'saq p.119 Q13b, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-d754a9d7ec', 'pharm-antiretroviral-ii', 'saq', 'Describe the drug interaction between lopinavir and ritonavir.', '[]'::jsonb, 'A beneficial pharmacokinetic interaction (boosting). Low-dose ritonavir potently inhibits CYP3A4 in the gut wall and liver (and P-glycoprotein), reducing the first-pass metabolism of lopinavir. Lopinavir''s bioavailability, plasma concentration and half-life rise, allowing twice-daily dosing with a lower pill burden and a higher barrier to resistance.', '[]'::jsonb, 'Lopinavir alone has very poor bioavailability because of extensive CYP3A4 metabolism. Ritonavir at 100 mg has no useful antiviral effect of its own in this role; it is used purely as an enzyme inhibitor, as cobicistat is.', 'admin', 'published', 2, true, '[["boosting", "pharmacokinetic enhancement", "booster", "beneficial"], ["inhibits cyp3a4", "cyp3a4 inhibition", "enzyme inhibition"], ["increased lopinavir levels", "raises lopinavir", "increased bioavailability", "longer half-life"]]'::jsonb, 'saq p.119 Q13c, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-8e7e068e6f', 'pharm-drug-interactions', 'saq', 'Describe the drug interaction between ritonavir-boosted lopinavir (LPV/r) and rifampicin.', '[]'::jsonb, 'Rifampicin strongly induces CYP3A4 and P-glycoprotein and reduces lopinavir concentrations by about 75%, even with standard ritonavir boosting, risking treatment failure. Options: avoid the combination by using rifabutin instead of rifampicin, or overcome it by doubling the LPV/r dose or adding extra ritonavir (''super-boosting''), with close monitoring for hepatotoxicity.', '[]'::jsonb, 'Induction by rifampicin overwhelms the inhibition produced by low-dose ritonavir. Rifabutin is a much weaker inducer, so it is the preferred rifamycin with protease inhibitors, although its own dose must be reduced because the protease inhibitor raises rifabutin levels.', 'admin', 'published', 2, true, '[["rifampicin induces cyp3a4", "enzyme induction", "induction"], ["reduced lopinavir levels", "lower lopinavir", "decreased concentration", "75%"], ["double dose", "super-boosting", "superboosting", "extra ritonavir", "rifabutin"], ["hepatotoxicity", "treatment failure"]]'::jsonb, 'saq p.119 Q13d, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-77fb93f379', 'pharm-antivirals', 'saq', 'Classify antiviral agents (non-retroviral) by their major sites of action on the viral life cycle.', '[]'::jsonb, '1. Attachment/entry: immunoglobulins, docosanol (also enfuvirtide, maraviroc for HIV). 2. Uncoating: amantadine, rimantadine (M2 channel of influenza A). 3. Nucleic acid synthesis - DNA polymerase inhibitors: acyclovir, valacyclovir, ganciclovir, foscarnet, cidofovir; RNA polymerase inhibitors: ribavirin, sofosbuvir; reverse transcriptase of HBV: lamivudine, tenofovir, entecavir. 4. Protein synthesis and processing: interferons; protease inhibitors (e.g. for hepatitis C). 5. Release of virions: neuraminidase inhibitors oseltamivir, zanamivir.', '[]'::jsonb, 'Viruses use host machinery, so drugs target the few virus-specific steps: entry, uncoating, genome replication by viral polymerases, protein processing and release. Most antivirals inhibit nucleic acid synthesis and are virustatic, acting only on replicating virus.', 'admin', 'published', 5, true, '[["entry", "attachment", "docosanol", "immunoglobulin"], ["uncoating", "amantadine", "rimantadine"], ["dna polymerase", "nucleic acid synthesis", "acyclovir", "ganciclovir", "foscarnet", "cidofovir"], ["ribavirin", "sofosbuvir", "rna polymerase"], ["interferon", "protein synthesis", "protease inhibitors"], ["release", "neuraminidase inhibitors", "oseltamivir", "zanamivir"]]'::jsonb, 'saq p.118 Q1, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-9bce6cf682', 'pharm-antivirals', 'saq', 'Describe the mechanism of activation and the mechanism of action of acyclovir.', '[]'::jsonb, 'Acyclovir is a guanosine analogue prodrug. It is converted to acyclovir monophosphate by viral thymidine kinase (only in infected cells), then to the di- and triphosphate by host cell kinases. Acyclovir triphosphate competitively inhibits viral DNA polymerase and is incorporated into viral DNA, where it causes chain termination because it lacks a 3''-hydroxyl group.', '[]'::jsonb, 'Selectivity is double: the first phosphorylation happens only in infected cells, and the triphosphate inhibits viral DNA polymerase far more than the host enzyme. This explains its low toxicity and why thymidine kinase-deficient herpes viruses are resistant.', 'admin', 'published', 3, true, '[["guanosine analogue", "guanine analogue", "prodrug"], ["viral thymidine kinase", "thymidine kinase", "monophosphate"], ["host kinases", "cellular kinases", "triphosphate"], ["inhibits viral dna polymerase", "dna polymerase"], ["chain termination", "chain terminator"]]'::jsonb, 'saq p.118 Q3a, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-54d68809c5', 'pharm-antivirals', 'saq', 'By which routes is acyclovir administered?', '[]'::jsonb, 'Oral (bioavailability only 15 to 30%); intravenous infusion (for encephalitis, neonatal and severe infection); topical cream for skin and lips, and ophthalmic ointment for herpes keratitis.', '[]'::jsonb, 'Poor oral absorption is why acyclovir is taken five times daily and why serious infections need the intravenous route. Valacyclovir, its valine ester prodrug, has three to five times better bioavailability and is given less often.', 'admin', 'published', 3, true, '[["oral"], ["intravenous", "iv", "infusion"], ["topical", "cream", "ophthalmic", "eye ointment"]]'::jsonb, 'saq p.118 Q3b, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-d72ee7ec4b', 'pharm-antivirals', 'saq', 'What are the mechanisms of resistance to acyclovir?', '[]'::jsonb, '1. Absent or reduced production of viral thymidine kinase (the commonest). 2. Altered thymidine kinase substrate specificity, so the enzyme no longer phosphorylates acyclovir. 3. Altered viral DNA polymerase with reduced affinity for acyclovir triphosphate.', '[]'::jsonb, 'Resistance appears mainly in immunocompromised patients on long courses. Because most resistant strains lack thymidine kinase, they are also resistant to other drugs needing that enzyme, but remain sensitive to foscarnet and cidofovir, which do not.', 'admin', 'published', 2, true, '[["absent thymidine kinase", "deficient thymidine kinase", "thymidine kinase deficiency", "reduced thymidine kinase"], ["altered thymidine kinase", "altered substrate specificity"], ["altered dna polymerase", "mutated dna polymerase", "dna polymerase mutation"]]'::jsonb, 'saq p.118 Q3c, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-222c34809d', 'pharm-antivirals', 'saq', 'List drugs which show cross-resistance with acyclovir.', '[]'::jsonb, 'Valacyclovir; famciclovir and penciclovir; ganciclovir (in thymidine kinase-deficient herpes simplex strains).', '[]'::jsonb, 'All of these depend on viral thymidine kinase for their first phosphorylation, so a thymidine kinase-deficient virus is resistant to the whole group. Foscarnet needs no activation and cidofovir is already a monophosphate analogue, so they keep their activity.', 'admin', 'published', 2, true, '[["valacyclovir", "valaciclovir"], ["famciclovir", "penciclovir"], ["ganciclovir"]]'::jsonb, 'saq p.118 Q3d, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-bf5cf46277', 'pharm-antivirals', 'saq', 'What drugs can be used to treat acyclovir-resistant herpes simplex?', '[]'::jsonb, 'Foscarnet (intravenous, drug of choice); cidofovir (intravenous or topical); topical trifluridine.', '[]'::jsonb, 'Foscarnet is a pyrophosphate analogue that inhibits viral DNA polymerase directly without phosphorylation, and cidofovir is activated by host kinases only, so neither depends on the viral thymidine kinase that resistant strains lack. Both are nephrotoxic.', 'admin', 'published', 2, true, '[["foscarnet"], ["cidofovir", "trifluridine"]]'::jsonb, 'saq p.118 Q3e, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-277fc1f5d9', 'pharm-antivirals', 'saq', 'Give the important drug interactions of acyclovir.', '[]'::jsonb, 'Probenecid and cimetidine reduce its renal tubular secretion and raise its levels; other nephrotoxic drugs (aminoglycosides, amphotericin B, ciclosporin, NSAIDs) increase the risk of renal impairment; zidovudine with acyclovir can cause severe drowsiness and lethargy; mycophenolate levels of both drugs rise (competition for tubular secretion); raised theophylline levels.', '[]'::jsonb, 'Acyclovir is eliminated unchanged by glomerular filtration and tubular secretion and can crystallise in the tubules, so interactions involve drugs that compete for secretion or add to renal damage. Good hydration during intravenous therapy prevents crystal nephropathy.', 'admin', 'published', 2, true, '[["probenecid", "cimetidine", "reduced renal clearance"], ["nephrotoxic drugs", "aminoglycosides", "amphotericin", "ciclosporin", "cyclosporine", "nsaids"], ["zidovudine", "drowsiness", "lethargy", "somnolence"], ["mycophenolate", "theophylline"]]'::jsonb, 'saq p.118 Q3f, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-21c34bcf6f', 'pharm-antivirals', 'saq', 'For how long is herpes simplex encephalitis treated with intravenous acyclovir?', '[]'::jsonb, '14 to 21 days', '["14-21 days", "2-3 weeks", "2 to 3 weeks", "14 days", "21 days", "three weeks", "14–21 days"]'::jsonb, 'Herpes encephalitis is treated with intravenous acyclovir 10 mg/kg every 8 hours for 14 to 21 days. Shorter courses, as used for mucocutaneous herpes, are followed by relapse; treatment is started on suspicion because delay greatly increases mortality.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.118 Q3g, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-9129aae88c', 'pharm-antivirals', 'saq', 'List topical antivirals with activity against herpes simplex virus.', '[]'::jsonb, 'Any 3 of: acyclovir (cream, eye ointment); penciclovir cream; docosanol cream; trifluridine eye drops; idoxuridine; ganciclovir eye gel; vidarabine eye ointment.', '[]'::jsonb, 'Topical agents are used for herpes labialis and herpes keratitis. Trifluridine and idoxuridine are too toxic for systemic use because they are incorporated into host DNA as well, so they are restricted to the eye. Docosanol blocks fusion of the viral envelope with the cell.', 'admin', 'published', 3, true, '[["acyclovir", "aciclovir"], ["penciclovir"], ["docosanol"], ["trifluridine", "trifluorothymidine"], ["idoxuridine"], ["ganciclovir"], ["vidarabine"]]'::jsonb, 'saq p.118 Q4, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-4d783ac1d6', 'pharm-antivirals', 'saq', 'List antiviral agents with activity against hepatitis B virus (HBV).', '[]'::jsonb, 'Any 4 of: tenofovir (disoproxil or alafenamide); entecavir; lamivudine; emtricitabine; adefovir; telbivudine; interferon alfa and peginterferon alfa.', '[]'::jsonb, 'HBV replicates through an RNA intermediate using a viral polymerase with reverse transcriptase activity, so nucleoside and nucleotide analogues suppress it. Tenofovir and entecavir are preferred because resistance is rare; lamivudine resistance (YMDD mutation) develops in most patients within a few years.', 'admin', 'published', 4, true, '[["tenofovir"], ["entecavir"], ["lamivudine"], ["emtricitabine"], ["adefovir"], ["telbivudine"], ["interferon", "interferon alfa", "peginterferon"]]'::jsonb, 'saq p.118 Q5, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-1f3e68f1ce', 'pharm-antiretroviral-i', 'saq', 'Which antiviral drugs are active against both hepatitis B virus and HIV?', '[]'::jsonb, 'Lamivudine; tenofovir; emtricitabine. (Entecavir and adefovir have weak anti-HIV activity and can select HIV resistance, so they are not used as HIV drugs.)', '[]'::jsonb, 'These NRTIs inhibit both HIV reverse transcriptase and the HBV polymerase. In HIV/HBV co-infection the regimen must therefore contain tenofovir with lamivudine or emtricitabine; using lamivudine as the only HBV-active drug quickly selects resistant HBV.', 'admin', 'published', 3, true, '[["lamivudine", "3tc"], ["tenofovir", "tdf", "taf"], ["emtricitabine", "ftc"]]'::jsonb, 'saq p.118 Q6, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-2aceb1d9f0', 'pharm-antivirals', 'saq', 'What happens if hepatitis B treatment with nucleoside analogues is stopped?', '[]'::jsonb, 'Viral replication rebounds (HBV DNA rises again) and there may be a hepatitis flare: an acute exacerbation with raised transaminases that can progress to hepatic decompensation and liver failure, especially in cirrhosis. Liver function must be monitored for months after stopping.', '[]'::jsonb, 'Nucleoside analogues suppress replication but do not clear the covalently closed circular DNA in hepatocyte nuclei, so the virus returns when they are withdrawn and the immune response to it damages the liver. The same flare occurs if an HIV regimen containing tenofovir or lamivudine is stopped in a co-infected patient.', 'admin', 'published', 2, true, '[["viral rebound", "relapse", "hbv dna rises", "reactivation"], ["hepatitis flare", "acute exacerbation", "raised transaminases", "flare"], ["liver failure", "hepatic decompensation", "decompensation"]]'::jsonb, 'saq p.118 Q7, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-45b9b4b511', 'pharm-antivirals', 'saq', 'List the adverse effects of foscarnet.', '[]'::jsonb, 'Any 4 of: nephrotoxicity (acute tubular necrosis); electrolyte disturbances - hypocalcaemia, hypomagnesaemia, hypokalaemia, hypo- or hyperphosphataemia; seizures and other CNS effects (headache, hallucinations); genital ulceration; anaemia; nausea and vomiting; infusion-site phlebitis.', '[]'::jsonb, 'Foscarnet chelates divalent cations, so ionised calcium and magnesium fall and may cause paraesthesiae, arrhythmias and seizures. High concentrations of the drug in urine cause both renal damage and genital ulcers; saline hydration reduces both.', 'admin', 'published', 4, true, '[["nephrotoxicity", "renal toxicity", "renal impairment"], ["hypocalcaemia", "hypocalcemia", "hypomagnesaemia", "hypokalaemia", "electrolyte disturbance"], ["seizures", "convulsions", "headache", "hallucinations"], ["genital ulceration", "genital ulcers", "penile ulcers"], ["anaemia", "anemia"], ["nausea", "vomiting"]]'::jsonb, 'saq p.118 Q8, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-1c7dae82c9', 'pharm-antivirals', 'saq', 'Intravenous cidofovir must be co-administered with which drug to reduce its nephrotoxicity?', '[]'::jsonb, 'Probenecid', '["oral probenecid", "probenecid tablets"]'::jsonb, 'Cidofovir is concentrated in proximal tubular cells by the organic anion transporter, which is the cause of its dose-limiting nephrotoxicity. Probenecid blocks this uptake, and with saline pre-hydration it is mandatory with every dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.118 Q9, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-9751deb0dd', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'Give examples of drug interactions of probenecid.', '[]'::jsonb, 'Probenecid inhibits renal tubular secretion of organic acids and so raises the levels and prolongs the action of: penicillins and cephalosporins (used deliberately), methotrexate, zidovudine, acyclovir and ganciclovir, NSAIDs such as indomethacin, and furosemide. Aspirin (salicylates) antagonises its uricosuric effect.', '[]'::jsonb, 'Probenecid competes for the organic anion transporters of the proximal tubule. That blocks urate reabsorption (its uricosuric use in gout) and blocks secretion of many acidic drugs, which is useful with penicillin but dangerous with methotrexate.', 'admin', 'published', 2, true, '[["penicillin", "penicillins", "cephalosporins"], ["methotrexate"], ["zidovudine", "acyclovir", "ganciclovir"], ["nsaids", "indomethacin", "furosemide"], ["aspirin", "salicylates"], ["inhibits tubular secretion", "reduced renal excretion"]]'::jsonb, 'saq p.118 Q9a, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-7c9477f81f', 'pharm-antivirals', 'saq', 'Describe the manifestations of nephrotoxicity caused by cidofovir.', '[]'::jsonb, 'Dose-dependent proximal tubular damage: proteinuria (earliest sign); rising serum creatinine (azotaemia); Fanconi-type syndrome with glycosuria, phosphaturia (hypophosphataemia), bicarbonate wasting and metabolic acidosis; may progress to acute renal failure.', '[]'::jsonb, 'Urine protein and serum creatinine are checked before every dose, and the drug is withheld if they rise. The damage reflects accumulation of cidofovir in proximal tubular cells, which is why probenecid and hydration are protective.', 'admin', 'published', 3, true, '[["proteinuria"], ["raised creatinine", "azotaemia", "azotemia", "renal failure"], ["fanconi syndrome", "proximal tubular dysfunction", "tubular damage"], ["glycosuria", "phosphaturia", "bicarbonate wasting", "metabolic acidosis"]]'::jsonb, 'saq p.118 Q10, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-0c8cd6ea73', 'pharm-antivirals', 'saq', 'List 6 nephrotoxic drugs that should not be used concurrently with cidofovir.', '[]'::jsonb, 'Any 6 of: aminoglycosides (gentamicin, amikacin); amphotericin B; foscarnet; intravenous pentamidine; vancomycin; NSAIDs; cisplatin; tenofovir; ciclosporin or tacrolimus; radiocontrast media.', '[]'::jsonb, 'Additive tubular injury is the concern, so other nephrotoxic agents should be stopped at least a week before cidofovir. Several of these drugs are, like cidofovir, used in the same immunocompromised patients, which makes the combination an easy mistake.', 'admin', 'published', 6, true, '[["aminoglycosides", "gentamicin", "amikacin"], ["amphotericin b", "amphotericin"], ["foscarnet"], ["pentamidine"], ["vancomycin"], ["nsaids", "ibuprofen", "diclofenac"], ["cisplatin"], ["tenofovir"], ["ciclosporin", "cyclosporine", "tacrolimus"], ["contrast media"]]'::jsonb, 'saq p.118 Q10a, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-e0058c33a7', 'pharm-antivirals', 'saq', 'List anti-influenza drugs.', '[]'::jsonb, 'Neuraminidase inhibitors: oseltamivir (oral), zanamivir (inhaled), peramivir (intravenous). M2 ion channel blockers (influenza A only): amantadine, rimantadine. Cap-dependent endonuclease inhibitor: baloxavir marboxil.', '[]'::jsonb, 'Neuraminidase inhibitors are active against influenza A and B and are the drugs of choice. The adamantanes block the M2 proton channel needed for uncoating, act only on influenza A and are now of little use because of widespread resistance.', 'admin', 'published', 4, true, '[["oseltamivir"], ["zanamivir"], ["peramivir"], ["amantadine"], ["rimantadine"], ["baloxavir"]]'::jsonb, 'saq p.118 Q11, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-dce029e8dc', 'pharm-antivirals', 'saq', 'List the mechanisms of antiviral activity of interferons.', '[]'::jsonb, 'Interferons bind cell-surface receptors and activate the JAK-STAT pathway, inducing antiviral proteins: 1. 2''-5''-oligoadenylate synthetase, which activates RNase L to degrade viral (and cellular) mRNA; 2. protein kinase R, which phosphorylates eIF-2 and blocks protein synthesis; 3. Mx proteins, which block viral transcription and assembly. They also increase MHC class I expression and activate NK cells, cytotoxic T cells and macrophages (immunomodulation).', '[]'::jsonb, 'Interferons do not attack the virus directly; they put cells into an antiviral state that blocks viral protein synthesis and they enhance immune clearance of infected cells. This explains their broad spectrum (hepatitis B and C, papillomavirus) and their flu-like and marrow-suppressing adverse effects.', 'admin', 'published', 3, true, '[["jak-stat", "receptor binding", "induce antiviral proteins"], ["oligoadenylate synthetase", "rnase l", "degrade viral mrna", "mrna degradation"], ["protein kinase r", "pkr", "eif-2", "inhibit protein synthesis", "inhibit translation"], ["mx proteins"], ["mhc", "nk cells", "immunomodulation", "activate macrophages"]]'::jsonb, 'saq p.118 Q12, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-2c98e778e9', 'pharm-antivirals', 'saq', 'Which antiviral agents are administered through the inhalation route?', '[]'::jsonb, 'Zanamivir (dry powder inhaler, for influenza A and B); ribavirin (aerosol, for severe respiratory syncytial virus infection in infants). (Laninamivir is also inhaled.)', '[]'::jsonb, 'Zanamivir is poorly absorbed orally, so it is delivered directly to the respiratory tract; it can cause bronchospasm and is avoided in asthma. Aerosolised ribavirin reaches high concentrations in the lungs while limiting the haemolytic anaemia seen with systemic use.', 'admin', 'published', 2, true, '[["zanamivir"], ["ribavirin", "laninamivir"]]'::jsonb, 'saq p.118 Q13, Antivirals SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-7f2dd7bb64', 'pharm-antiretroviral-i', 'saq', 'Inhibition of which human enzyme underlies the class adverse effects (mitochondrial toxicity) of the nucleoside reverse transcriptase inhibitors?', '[]'::jsonb, 'DNA polymerase gamma', '["mitochondrial DNA polymerase gamma", "polymerase gamma", "pol gamma", "mitochondrial DNA polymerase", "DNA polymerase γ", "POLG"]'::jsonb, 'NRTI triphosphates are also accepted by mitochondrial DNA polymerase gamma, the enzyme that replicates mitochondrial DNA. Depletion of mitochondrial DNA impairs oxidative phosphorylation, producing lactic acidosis with hepatic steatosis, neuropathy, pancreatitis, myopathy and lipoatrophy.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.082 Dr Ezzi Q2, MBChB 3 Pharmacology tutorial 01. Reworded from ''Regarding NRTIs, which are the class side effects and what is the mechanism of their side effects?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-4e3a0d11a4', 'pharm-antiretroviral-i', 'saq', 'Regarding zidovudine, what are its mechanism of action, indications for use and unique side effects?', '[]'::jsonb, 'Mechanism: thymidine analogue NRTI; phosphorylated by host kinases to the triphosphate, which competitively inhibits HIV reverse transcriptase and terminates the DNA chain. Indications: treatment of HIV infection in combination regimens (now mainly second line), prevention of mother-to-child transmission (including infant prophylaxis), post-exposure prophylaxis. Unique side effects: bone marrow suppression with macrocytic anaemia and neutropenia; myopathy; nail and skin hyperpigmentation; headache, nausea and insomnia.', '[]'::jsonb, 'Zidovudine was the first antiretroviral. Its marrow toxicity is dose related and worse with other marrow-suppressing drugs such as ganciclovir or co-trimoxazole; the macrocytosis it causes is so regular that it can be used as a marker of adherence.', 'admin', 'published', 4, true, '[["thymidine analogue", "nrti"], ["triphosphate", "phosphorylated"], ["inhibits reverse transcriptase", "chain termination"], ["hiv treatment", "pmtct", "mother-to-child", "post-exposure prophylaxis"], ["anaemia", "anemia", "bone marrow suppression", "neutropenia"], ["myopathy", "nail pigmentation"]]'::jsonb, 'saq p.083 Dr Ezzi Q3, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-e4bb53c523', 'pharm-antiretroviral-i', 'saq', 'Compare and contrast abacavir and tenofovir disoproxil fumarate (TDF).', '[]'::jsonb, 'Similarities: both are NRTIs that need intracellular phosphorylation, cause chain termination, are given once daily and have low mitochondrial toxicity. Differences: abacavir is a guanosine nucleoside analogue, tenofovir an adenosine nucleotide (monophosphate) analogue given as a prodrug; abacavir is metabolised in the liver (alcohol dehydrogenase, glucuronidation), tenofovir is excreted unchanged by the kidney; abacavir causes HLA-B*57:01-linked hypersensitivity and possibly increased cardiovascular risk, tenofovir causes nephrotoxicity and bone mineral loss; tenofovir is active against hepatitis B, abacavir is not; resistance mutation K65R for tenofovir, L74V (and M184V, K65R) for abacavir.', '[]'::jsonb, 'The choice between them is practical: tenofovir is avoided in renal disease, abacavir in HLA-B*57:01-positive patients and in hepatitis B co-infection (where tenofovir is needed). Abacavir is the usual NRTI for children.', 'admin', 'published', 4, true, '[["both nrtis", "chain termination", "nrti"], ["guanosine analogue", "nucleoside"], ["adenosine", "nucleotide analogue", "prodrug"], ["hepatic metabolism", "alcohol dehydrogenase"], ["renal excretion", "excreted by kidney"], ["hypersensitivity", "hla-b*5701"], ["nephrotoxicity", "bone density", "renal toxicity"], ["hepatitis b"]]'::jsonb, 'saq p.083 Dr Ezzi Q5, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-b208908d7a', 'pharm-antiretroviral-ii', 'saq', 'What is cross-resistance? Give an example using non-nucleoside reverse transcriptase inhibitors (NNRTIs).', '[]'::jsonb, 'Cross-resistance is resistance to a drug that the organism has not been exposed to, arising because a mutation selected by one drug also reduces susceptibility to other drugs, usually of the same class with the same target. Example: the K103N mutation in reverse transcriptase, selected by nevirapine or efavirenz, confers high-level resistance to both; Y181C similarly. The second-generation NNRTI etravirine retains activity against K103N virus.', '[]'::jsonb, 'First-generation NNRTIs have a low genetic barrier: one point mutation abolishes binding to the allosteric pocket for the whole generation. This is why a single dose of nevirapine in labour could compromise later efavirenz-based therapy.', 'admin', 'published', 2, true, '[["resistance to other drugs", "resistance to related drugs", "same class"], ["same mutation", "single mutation", "shared target"], ["k103n", "y181c"], ["nevirapine", "efavirenz"], ["etravirine"]]'::jsonb, 'saq p.083 Dr Ezzi Q6, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-a639b78b93', 'pharm-antiretroviral-ii', 'saq', 'Compare and contrast efavirenz and etravirine.', '[]'::jsonb, 'Both are NNRTIs that bind the allosteric pocket of HIV-1 reverse transcriptase, are inactive against HIV-2, cause rash, and are metabolised by and interact through CYP enzymes. Efavirenz is first generation: once daily (long half-life), low genetic barrier (K103N gives resistance), prominent neuropsychiatric effects, used in first-line regimens. Etravirine is second generation: a flexible molecule active against virus with K103N and other first-generation NNRTI mutations (higher genetic barrier), given twice daily after food, few CNS effects, reserved for treatment-experienced patients.', '[]'::jsonb, 'Etravirine''s flexible structure lets it bind the pocket in several conformations, so several mutations are needed for resistance. That makes it useful after efavirenz or nevirapine failure, where the first-generation drugs are fully cross-resistant.', 'admin', 'published', 3, true, '[["both nnrtis", "nnrti", "allosteric"], ["first generation", "second generation"], ["k103n", "active against resistant virus", "higher genetic barrier"], ["cns effects", "neuropsychiatric", "vivid dreams"], ["once daily", "twice daily"], ["treatment-experienced", "salvage", "first line"], ["rash", "cyp"]]'::jsonb, 'saq p.083 Dr Ezzi Q7, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-b4cb95455e', 'pharm-antiretroviral-ii', 'saq', 'What are the class side effects of the HIV protease inhibitors?', '[]'::jsonb, 'Any 3 of: gastrointestinal intolerance (nausea, vomiting, diarrhoea); dyslipidaemia (raised triglycerides and cholesterol); insulin resistance and hyperglycaemia; lipodystrophy (central fat accumulation, buffalo hump); hepatotoxicity; increased bleeding in haemophiliacs; many drug interactions through CYP3A4 inhibition.', '[]'::jsonb, 'Protease inhibitors disturb lipid and glucose handling, producing a metabolic syndrome that increases cardiovascular risk on long-term therapy. Atazanavir and darunavir are the least troublesome metabolically. All are CYP3A4 substrates and inhibitors.', 'admin', 'published', 3, true, '[["nausea", "diarrhoea", "diarrhea", "gi intolerance"], ["dyslipidaemia", "hyperlipidaemia", "hypertriglyceridaemia", "hyperlipidemia"], ["hyperglycaemia", "insulin resistance", "diabetes"], ["lipodystrophy", "fat redistribution", "buffalo hump"], ["hepatotoxicity"], ["drug interactions", "cyp3a4 inhibition"], ["bleeding in haemophiliacs"]]'::jsonb, 'saq p.083 Dr Ezzi Q8a, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-26fba0ad80', 'pharm-antiretroviral-ii', 'saq', 'What is meant by a ''boosted'' protease inhibitor?', '[]'::jsonb, 'A protease inhibitor given together with a low, sub-therapeutic dose of ritonavir (or cobicistat), which inhibits CYP3A4 (and P-glycoprotein) and so reduces the metabolism of the main protease inhibitor. Its plasma levels and half-life increase, allowing lower and less frequent doses, fewer pills, more reliable levels and a higher barrier to resistance. Examples: lopinavir/ritonavir, atazanavir/ritonavir, darunavir/ritonavir.', '[]'::jsonb, 'Boosting turns a nuisance interaction into a tool. Ritonavir is the most potent CYP3A4 inhibitor in clinical use; at 100 mg it has little antiviral effect but greatly raises trough levels of the partner drug. Nelfinavir is the one protease inhibitor that is not boosted.', 'admin', 'published', 2, true, '[["ritonavir", "cobicistat", "low dose ritonavir"], ["cyp3a4 inhibition", "inhibits cyp3a4", "enzyme inhibitor"], ["increased levels", "higher plasma concentration", "longer half-life"], ["lopinavir/ritonavir", "atazanavir/ritonavir", "darunavir/ritonavir", "reduced dosing frequency"]]'::jsonb, 'saq p.083 Dr Ezzi Q8b, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-b66750b48c', 'pharm-antiretroviral-ii', 'saq', 'What unique features does each of the following protease inhibitors have: indinavir, fosamprenavir, darunavir, saquinavir?', '[]'::jsonb, 'Indinavir: nephrolithiasis and crystalluria (needs high fluid intake), indirect hyperbilirubinaemia. Fosamprenavir: phosphate ester prodrug of amprenavir with better absorption; a sulphonamide, so rash. Darunavir: active against virus resistant to other protease inhibitors (high genetic barrier); contains a sulphonamide group (rash); always boosted. Saquinavir: the first protease inhibitor; very low oral bioavailability unless boosted; QT and PR prolongation.', '[]'::jsonb, 'Indinavir is poorly soluble and crystallises in urine, hence the stones. Darunavir binds the protease very tightly, so several mutations are needed for resistance, which makes it the preferred protease inhibitor after other regimens have failed.', 'admin', 'published', 4, true, '[["kidney stones", "nephrolithiasis", "crystalluria"], ["prodrug of amprenavir", "prodrug"], ["rash", "sulphonamide", "sulfonamide"], ["active against resistant virus", "high genetic barrier", "salvage"], ["first protease inhibitor", "poor bioavailability", "low bioavailability"], ["qt prolongation"]]'::jsonb, 'saq p.083 Dr Ezzi Q8c, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-71648182fa', 'pharm-anti-retrovirals', 'saq', 'What is HAART? Which drugs are used as first-line HAART and which as second-line therapy?', '[]'::jsonb, 'HAART (highly active antiretroviral therapy) is a combination of at least three antiretroviral drugs from at least two classes, given to suppress viral replication maximally and prevent resistance. First line (Kenya/WHO): two NRTIs, tenofovir + lamivudine, with dolutegravir (previously efavirenz); abacavir or zidovudine replace tenofovir in children or renal disease. Second line: a change of NRTI backbone (zidovudine + lamivudine) plus a ritonavir-boosted protease inhibitor (atazanavir/r or lopinavir/r), or dolutegravir if it was not used first line.', '[]'::jsonb, 'Three active drugs are needed because HIV mutates so rapidly that resistance to one or two drugs is inevitable. Second-line regimens change the class of the third drug and the NRTI backbone so that the new regimen has fully active components.', 'admin', 'draft', 3, true, '[["three drugs", "combination", "at least three", "two classes"], ["tenofovir"], ["lamivudine", "emtricitabine"], ["dolutegravir", "efavirenz"], ["zidovudine", "abacavir"], ["boosted protease inhibitor", "lopinavir", "atazanavir", "ritonavir"]]'::jsonb, 'saq p.083 Dr Ezzi Q9, MBChB 3 Pharmacology tutorial 01. Guideline-dependent: at the time of the tutorial (2014) first line was TDF/3TC/EFV; current Kenyan and WHO guidelines use TDF/3TC/DTG.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-b9a75b0827', 'pharm-drug-interactions', 'saq', 'Give examples of harmful drug interactions.', '[]'::jsonb, 'Any 3 of: warfarin + aspirin or NSAIDs (bleeding); warfarin + enzyme inhibitors such as erythromycin, metronidazole or cimetidine (bleeding); rifampicin + oral contraceptives (contraceptive failure); ACE inhibitors + spironolactone or potassium (hyperkalaemia); digoxin + diuretic-induced hypokalaemia (digoxin toxicity); MAO inhibitors + tyramine or pethidine (hypertensive crisis, serotonin syndrome); nitrates + sildenafil (severe hypotension); aminoglycosides + furosemide (ototoxicity); alcohol + benzodiazepines (CNS depression); statins + clarithromycin (rhabdomyolysis).', '[]'::jsonb, 'Harmful interactions either increase toxicity (additive effects or raised drug levels from enzyme inhibition or reduced excretion) or cause therapeutic failure (enzyme induction, reduced absorption). They matter most for drugs with a narrow therapeutic index such as warfarin, digoxin, lithium and phenytoin.', 'admin', 'published', 3, true, '[["warfarin", "bleeding"], ["rifampicin", "oral contraceptives", "contraceptive failure"], ["hyperkalaemia", "ace inhibitors", "spironolactone"], ["digoxin", "hypokalaemia"], ["mao inhibitors", "maoi", "tyramine", "serotonin syndrome"], ["sildenafil", "nitrates"], ["aminoglycosides", "furosemide"], ["alcohol", "benzodiazepines"], ["statins", "rhabdomyolysis"]]'::jsonb, 'saq p.083 DI Q2, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-223f7497b4', 'pharm-drug-interactions', 'saq', 'Give examples of beneficial drug interactions.', '[]'::jsonb, 'Any 3 of: sulfamethoxazole + trimethoprim (sequential blockade, synergy); amoxicillin + clavulanic acid (beta-lactamase inhibition); levodopa + carbidopa (blocks peripheral decarboxylation); lopinavir + ritonavir (boosting); penicillin + probenecid (reduced excretion); thiazide + potassium-sparing diuretic or ACE inhibitor (offsets hypokalaemia); naloxone for opioid overdose and other antidotes; adrenaline with local anaesthetics (prolonged action); combination therapy in TB, HIV and hypertension; imipenem + cilastatin.', '[]'::jsonb, 'A beneficial interaction is one used deliberately to increase efficacy, prolong action, reduce toxicity or prevent resistance. The mechanisms are the same as for harmful ones: enzyme inhibition, blocked excretion, or additive and antagonistic pharmacodynamic effects.', 'admin', 'published', 3, true, '[["co-trimoxazole", "sulfamethoxazole", "trimethoprim"], ["clavulanic acid", "amoxicillin"], ["carbidopa", "levodopa"], ["ritonavir", "lopinavir", "boosting"], ["probenecid", "penicillin"], ["thiazide", "potassium-sparing", "ace inhibitor"], ["naloxone", "antidote"], ["adrenaline", "local anaesthetic"], ["combination therapy", "imipenem", "cilastatin"]]'::jsonb, 'saq p.083 DI Q3, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-e9380bdef1', 'pharm-drug-interactions', 'saq', 'What are the different types of drug interactions?', '[]'::jsonb, '1. Pharmaceutical (physicochemical incompatibility outside the body, e.g. drugs mixed in an infusion). 2. Pharmacokinetic: one drug alters the absorption, distribution, metabolism or excretion of another. 3. Pharmacodynamic: drugs act on the same or related receptors or physiological systems, giving additive, synergistic or antagonistic effects. (They may also be grouped as drug-drug, drug-food, drug-herb and drug-disease interactions.)', '[]'::jsonb, 'Pharmacokinetic interactions change the concentration of a drug at its site of action; pharmacodynamic interactions change the response to a given concentration. Separating the two tells you whether measuring a plasma level would help.', 'admin', 'published', 3, true, '[["pharmaceutical", "incompatibility"], ["pharmacokinetic", "absorption", "distribution", "metabolism", "excretion"], ["pharmacodynamic", "synergism", "antagonism", "additive"], ["drug-food", "drug-drug", "drug-disease"]]'::jsonb, 'saq p.083 DI Q4, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-984e1200a8', 'pharm-drug-interactions', 'saq', 'What are the various drug interactions that occur at the site of absorption, and how would you avoid them?', '[]'::jsonb, 'Mechanisms: 1. Chelation or adsorption - antacids, iron, calcium and milk bind tetracyclines and fluoroquinolones; cholestyramine binds digoxin, warfarin and thyroxine; activated charcoal adsorbs many drugs. 2. Altered gastric pH - antacids, H2 blockers and proton pump inhibitors reduce absorption of ketoconazole, itraconazole, atazanavir and iron. 3. Altered gut motility - metoclopramide speeds, and antimuscarinics and opioids delay, gastric emptying. 4. Altered gut flora - broad-spectrum antibiotics reduce enterohepatic recycling of oestrogens and bacterial inactivation of digoxin. 5. Inhibition of gut wall CYP3A4 or P-glycoprotein (grapefruit juice). Avoidance: separate the doses by 2 to 4 hours, take the drug on an empty stomach, or use another route or drug.', '[]'::jsonb, 'Most absorption interactions reduce the amount or rate of drug absorbed and can be avoided simply by spacing the doses, because they require the two drugs to be in the gut together. Changes in rate matter only for drugs needing a quick peak, such as analgesics.', 'admin', 'published', 4, true, '[["chelation", "adsorption", "binding", "complex formation"], ["antacids", "iron", "calcium", "tetracycline", "fluoroquinolones", "cholestyramine"], ["gastric ph", "ph change", "ketoconazole"], ["motility", "gastric emptying", "metoclopramide"], ["gut flora", "p-glycoprotein", "grapefruit"], ["separate doses", "space doses", "2 hours apart", "dose separation"]]'::jsonb, 'saq p.083 DI Q5, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-3a6628e121', 'pharm-drug-interactions', 'saq', 'Give examples of drug interactions that occur at the level of distribution.', '[]'::jsonb, 'Displacement from plasma protein binding sites by highly bound drugs: sulphonamides, aspirin (salicylates), phenylbutazone and other NSAIDs displace warfarin (bleeding), sulphonylureas such as tolbutamide (hypoglycaemia), methotrexate and phenytoin; valproate displaces phenytoin; sulphonamides and ceftriaxone displace bilirubin in neonates (kernicterus). Displacement from tissue binding: quinidine and amiodarone displace digoxin.', '[]'::jsonb, 'Displacement raises the free fraction, but the extra free drug is usually cleared, so the effect is brief. It becomes clinically important when the displacing drug also inhibits metabolism (phenylbutazone or co-trimoxazole with warfarin) or when the displaced substance is bilirubin in a newborn.', 'admin', 'published', 2, true, '[["protein binding displacement", "displacement", "plasma protein binding", "albumin"], ["warfarin"], ["sulphonamides", "sulfonamides", "aspirin", "salicylates", "nsaids", "phenylbutazone"], ["phenytoin", "valproate", "tolbutamide", "methotrexate"], ["bilirubin", "kernicterus"], ["digoxin", "quinidine"]]'::jsonb, 'saq p.083 DI Q6, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-c3ee88e840', 'pharm-drug-interactions', 'saq', 'Write short notes on drug interactions that occur at the site of excretion.', '[]'::jsonb, '1. Competition for active tubular secretion: probenecid reduces secretion of penicillin and methotrexate; NSAIDs reduce methotrexate secretion; quinidine, verapamil and amiodarone reduce digoxin secretion (P-glycoprotein). 2. Changes in urinary pH: alkalinising the urine with sodium bicarbonate increases excretion of weak acids (aspirin, phenobarbital); acidification increases excretion of weak bases (amphetamine). 3. Changes in renal blood flow or sodium handling: NSAIDs, thiazides and ACE inhibitors reduce lithium clearance, causing toxicity. 4. Biliary excretion and enterohepatic recycling: antibiotics may reduce recycling of oral contraceptive oestrogens.', '[]'::jsonb, 'Renal interactions involve the three processes of excretion: filtration, active secretion and passive reabsorption. Ion trapping is used therapeutically in salicylate poisoning, and reduced lithium clearance by diuretics and NSAIDs is one of the most dangerous everyday interactions.', 'admin', 'published', 3, true, '[["tubular secretion", "competition for secretion", "probenecid", "penicillin", "methotrexate"], ["urinary ph", "alkalinisation", "sodium bicarbonate", "ion trapping", "aspirin"], ["lithium", "nsaids", "thiazides", "renal blood flow"], ["digoxin", "quinidine", "p-glycoprotein"], ["enterohepatic", "biliary"]]'::jsonb, 'saq p.083 DI Q8, MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-1fb3ba03c5', 'pharm-anticholinergics-and-ganglion-blockers', 'saq', 'Discuss the mechanism of action of atropine and the differences in sensitivity of different tissues to its effects.', '[]'::jsonb, 'Atropine is a competitive (reversible, surmountable) antagonist of acetylcholine at all muscarinic receptor subtypes (M1 to M5), with little effect at nicotinic receptors. It prevents the receptor-mediated rise in IP3/DAG (M1, M3, M5) and the inhibition of adenylyl cyclase (M2, M4). Tissue sensitivity (most to least): salivary, bronchial and sweat glands; then the eye (mydriasis, cycloplegia) and heart (tachycardia); then the gut and bladder smooth muscle; gastric acid secretion is the least sensitive.', '[]'::jsonb, 'Because sensitivity differs, small doses dry the mouth and reduce sweating without other effects, and the doses needed to reduce gastric acid always cause dry mouth, blurred vision and tachycardia. That is why atropine was never a useful anti-ulcer drug.', 'admin', 'published', 4, true, '[["competitive antagonist", "competitive", "reversible"], ["muscarinic receptors", "muscarinic"], ["non-selective", "m1 to m5", "all subtypes"], ["salivary", "bronchial secretions", "sweat glands", "most sensitive"], ["heart", "eye", "mydriasis", "tachycardia"], ["gastric acid", "least sensitive", "gut", "bladder"]]'::jsonb, 'saq p.087 Q1 (Dr Muasya), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-b9d1e31468', 'pharm-anticholinergics-and-ganglion-blockers', 'saq', 'Discuss the selectivity of antimuscarinic drugs other than atropine for different muscarinic receptor subtypes.', '[]'::jsonb, 'Most antimuscarinics (atropine, hyoscine, ipratropium) are non-selective. M1-selective: pirenzepine and telenzepine (reduce gastric acid secretion). M3-selective: darifenacin and solifenacin (overactive bladder). Tiotropium dissociates slowly from M1 and M3 but quickly from M2 receptors (functional or kinetic selectivity), giving prolonged bronchodilatation. M2-selective (experimental): gallamine, methoctramine.', '[]'::jsonb, 'Subtype selectivity aims to keep the wanted effect and lose the rest: M3 block relaxes the detrusor with less tachycardia (M2) and central effects (M1). In practice selectivity is modest, and dry mouth, also M3 mediated, remains common.', 'admin', 'published', 3, true, '[["pirenzepine", "telenzepine", "m1 selective"], ["darifenacin", "solifenacin", "m3 selective"], ["tiotropium", "kinetic selectivity"], ["non-selective", "atropine", "hyoscine", "ipratropium"], ["overactive bladder", "gastric acid"]]'::jsonb, 'saq p.087 Q2 (Dr Muasya), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-56de6b89d7', 'pharm-anticholinergics-and-ganglion-blockers', 'saq', 'Describe the adverse effects of atropine according to organ system.', '[]'::jsonb, 'Eye: blurred vision, photophobia (mydriasis, cycloplegia), raised intraocular pressure in narrow-angle glaucoma. Glands: dry mouth, dry skin with hyperthermia (''atropine fever'', especially in children). Heart: tachycardia, palpitations. Gut: constipation. Urinary tract: urinary retention (especially with prostatic enlargement). CNS: restlessness, confusion, hallucinations, delirium. Skin: flushing.', '[]'::jsonb, 'The picture of atropine poisoning is summarised as ''dry as a bone, blind as a bat, red as a beet, hot as a hare, mad as a hatter''. Children are especially vulnerable to hyperthermia. The antidote is physostigmine, which crosses into the brain.', 'admin', 'published', 5, true, '[["blurred vision", "mydriasis", "photophobia", "glaucoma"], ["dry mouth", "xerostomia"], ["hyperthermia", "dry skin", "fever", "flushing"], ["tachycardia", "palpitations"], ["constipation"], ["urinary retention"], ["confusion", "hallucinations", "delirium", "restlessness"]]'::jsonb, 'saq p.088 (Dr Muasya), MBChB 3 Pharmacology tutorial 01') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-d069ccc3ed', 'pharm-sympathomimetics', 'saq', 'Why is dopamine preferred to adrenaline in cardiogenic shock?', '[]'::jsonb, 'At low to moderate doses dopamine stimulates D1 receptors, dilating renal and mesenteric vessels and so maintaining renal blood flow and urine output, and beta-1 receptors, increasing contractility and cardiac output with relatively little tachycardia. Adrenaline causes marked tachycardia and arrhythmias, raises myocardial oxygen demand and, through alpha-1 vasoconstriction, reduces renal and tissue perfusion and increases afterload.', '[]'::jsonb, 'This is the classical teaching based on dopamine''s dose-dependent receptor profile (D1, then beta-1, then alpha-1 at high doses). Modern trials have not shown a renal-protective benefit, and noradrenaline or dobutamine are now usually preferred in cardiogenic shock.', 'admin', 'draft', 3, true, '[["d1 receptors", "dopamine receptors", "renal vasodilation", "renal blood flow", "preserves renal perfusion"], ["beta-1", "increases contractility", "inotropic", "cardiac output"], ["less tachycardia", "fewer arrhythmias", "less oxygen demand"], ["adrenaline vasoconstriction", "increases afterload", "reduces renal perfusion"]]'::jsonb, 'saq p.089 Q2 (Dr Ezzi), MBChB 3 Pharmacology tutorial 01. Classical textbook answer; current evidence (e.g. SOAP II trial) favours noradrenaline over dopamine in cardiogenic shock, so the premise is dated.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-7dedbb672c', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'Define autacoids.', '[]'::jsonb, 'Autacoids (''self-remedy'', local hormones) are biologically active substances that are synthesised and released locally by many tissues, act briefly at or near their site of release (autocrine or paracrine action), and are rapidly inactivated. They include histamine, serotonin, eicosanoids and vasoactive peptides.', '[]'::jsonb, 'The word comes from the Greek autos (self) and akos (remedy). Unlike classical hormones, autacoids are not made by a specialised gland or carried in blood to distant targets, and unlike neurotransmitters they are not confined to synapses.', 'admin', 'published', 2, true, '[["local hormones", "locally acting", "act locally", "act near site of release"], ["formed in tissues", "synthesised locally", "produced by many tissues"], ["short duration", "rapidly inactivated", "brief"], ["histamine", "serotonin", "prostaglandins", "bradykinin"]]'::jsonb, 'saq p.108 A1, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-344d299646', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'Compare and contrast autacoids and endocrine hormones under: source, mode of action, and duration of action.', '[]'::jsonb, 'Source: autacoids are produced by many different cells and tissues throughout the body; hormones are produced by specialised endocrine glands. Mode of action: autacoids act locally on the cell that produced them or on neighbouring cells (autocrine, paracrine); hormones are carried in the bloodstream to distant target organs (endocrine). Duration: autacoids act briefly because they are rapidly destroyed locally; hormones generally act for longer.', '[]'::jsonb, 'Both groups are chemical messengers acting on specific receptors. The difference is one of distance and time: a local, short-lived signal for autacoids against a circulating, sustained signal for hormones.', 'admin', 'published', 3, true, '[["many tissues", "various cells", "widespread"], ["endocrine glands", "specialised glands"], ["local", "paracrine", "autocrine", "site of release"], ["blood", "circulation", "distant targets"], ["short duration", "brief", "rapidly inactivated"], ["longer duration"]]'::jsonb, 'saq p.108 A2, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-90e8731e9a', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'Define and differentiate the terms autocrine, paracrine and endocrine mediators.', '[]'::jsonb, 'Autocrine: the mediator acts on the same cell that secreted it. Paracrine: the mediator diffuses through the interstitial fluid to act on neighbouring cells. Endocrine: the mediator (hormone) is secreted into the bloodstream and acts on distant target cells.', '[]'::jsonb, 'The three terms describe how far a signal travels. Prostaglandins and cytokines typically act in autocrine and paracrine fashion; insulin and thyroxine are endocrine. The same substance can act in more than one way, as noradrenaline does as a transmitter and a hormone.', 'admin', 'published', 3, true, '[["same cell", "cell that secreted it", "own receptors"], ["neighbouring cells", "adjacent cells", "nearby cells", "diffuses locally"], ["bloodstream", "blood", "distant", "circulation"]]'::jsonb, 'saq p.108 A2b, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-793ac51748', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'List the autacoids.', '[]'::jsonb, 'Amines: histamine, serotonin (5-HT). Lipid-derived: eicosanoids (prostaglandins, thromboxanes, leukotrienes) and platelet-activating factor. Peptides: bradykinin and kallidin (kinins), angiotensin, natriuretic peptides, endothelins, substance P, vasoactive intestinal peptide. Others: nitric oxide, cytokines.', '[]'::jsonb, 'Autacoids are grouped by chemistry: decarboxylated amino acids (amines), fatty-acid derivatives (eicosanoids, PAF) and peptides. Drugs that mimic or block them include antihistamines, triptans, NSAIDs, ACE inhibitors and leukotriene antagonists.', 'admin', 'published', 4, true, '[["histamine"], ["serotonin", "5-ht", "5-hydroxytryptamine"], ["prostaglandins", "eicosanoids", "leukotrienes", "thromboxane"], ["platelet activating factor", "paf"], ["bradykinin", "kinins", "kallidin"], ["angiotensin", "endothelin", "substance p", "vip", "natriuretic peptides"], ["nitric oxide", "cytokines"]]'::jsonb, 'saq p.108 A3, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-692c5a1e96', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'saq', 'List the things that histamine and serotonin have in common.', '[]'::jsonb, 'Any 5 of: both are biogenic amine autacoids; both are formed by decarboxylation of an amino acid (histidine, tryptophan); both are stored in granules and released on stimulation (mast cells and basophils; enterochromaffin cells and platelets); both are found in the gut, in the brain as neurotransmitters, and in plants and venoms; both act on several receptor subtypes, mostly G-protein-coupled; both affect vascular tone and increase capillary permeability; both contract non-vascular smooth muscle (bronchi, gut); both stimulate sensory nerve endings (pain, itch); both are involved in inflammation and allergy; both are inactivated by enzymes including monoamine oxidase; neither is useful as a drug itself, whereas their antagonists are.', '[]'::jsonb, 'The two amine autacoids share origin (amino acid decarboxylation), storage, wide distribution and broad actions on vessels, smooth muscle and nerves. They are released together in some species during allergic reactions, and both are found in insect venoms and stinging plants.', 'admin', 'draft', 5, true, '[["biogenic amines", "amines", "autacoids"], ["decarboxylation", "amino acid", "histidine", "tryptophan"], ["stored in granules", "mast cells", "platelets", "enterochromaffin"], ["neurotransmitters", "brain", "cns"], ["multiple receptor subtypes", "g-protein-coupled"], ["vascular effects", "capillary permeability", "vasodilation"], ["smooth muscle contraction", "bronchoconstriction"], ["pain", "itch", "sensory nerves"], ["inflammation", "allergy"], ["antagonists used clinically", "venoms", "plants"]]'::jsonb, 'saq p.108 A4, Autacoids SAQs tutorial. The tutorial asks for ''9 things''; the lecturer''s own list is not available, so this is a reasonable reconstruction.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-48ad26a027', 'pharm-eicosanoids', 'saq', 'Give 5 general properties of eicosanoids.', '[]'::jsonb, 'Any 5 of: derived from 20-carbon polyunsaturated fatty acids, mainly arachidonic acid released from membrane phospholipids by phospholipase A2; synthesised on demand and not stored; produced by almost all cells; very short half-lives (seconds to minutes) with rapid local inactivation; act locally as autocrine and paracrine mediators; act on specific G-protein-coupled receptors; very potent with a wide range of, often opposing, actions in different tissues; synthesis is blocked by NSAIDs (cyclo-oxygenase) and corticosteroids (phospholipase A2).', '[]'::jsonb, 'The name comes from the Greek eikosi, twenty. Because they are made when needed and destroyed in one passage through the lungs, their effects are local; this is why inhibiting their synthesis, rather than blocking a store, is the pharmacological strategy.', 'admin', 'published', 5, true, '[["20-carbon", "arachidonic acid", "polyunsaturated fatty acids"], ["phospholipase a2", "membrane phospholipids"], ["not stored", "synthesised on demand", "made on demand"], ["short half-life", "rapidly inactivated"], ["act locally", "autocrine", "paracrine", "local hormones"], ["g-protein-coupled receptors", "specific receptors"], ["potent", "wide range of effects", "all tissues"], ["nsaids", "cyclooxygenase", "corticosteroids"]]'::jsonb, 'saq p.108 A5, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-6770adf5ee', 'pharm-the-polypeptides', 'saq', 'List the vasoconstrictor and the vasodilator endogenous vasoactive peptides.', '[]'::jsonb, 'Vasoconstrictors: angiotensin II, vasopressin (ADH), endothelins, neuropeptide Y, urotensin II. Vasodilators: bradykinin and kallidin, natriuretic peptides (ANP, BNP, CNP), vasoactive intestinal peptide, substance P, calcitonin gene-related peptide (CGRP), adrenomedullin, neurotensin.', '[]'::jsonb, 'These peptides regulate vascular tone and are important drug targets: ACE inhibitors reduce angiotensin II and raise bradykinin, bosentan blocks endothelin receptors in pulmonary hypertension, sacubitril raises natriuretic peptides, and CGRP antagonists treat migraine.', 'admin', 'published', 4, true, '[["angiotensin ii", "angiotensin"], ["vasopressin", "adh"], ["endothelin", "endothelins", "neuropeptide y", "urotensin"], ["bradykinin", "kinins", "kallidin"], ["natriuretic peptides", "anp", "bnp"], ["vip", "vasoactive intestinal peptide", "substance p"], ["cgrp", "calcitonin gene-related peptide", "adrenomedullin", "neurotensin"]]'::jsonb, 'saq p.108 A6, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-a5dd47f86f', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Where is serotonin found in nature?', '[]'::jsonb, 'In animals: enterochromaffin cells of the gastrointestinal mucosa (about 90%), platelets, and serotonergic neurones of the brain (raphe nuclei). In plants: fruits and nuts such as bananas, pineapples, tomatoes, plums and walnuts, and stinging nettles. In venoms: wasp and scorpion stings.', '[]'::jsonb, 'Serotonin is widespread in nature. Dietary sources matter clinically: serotonin-rich foods such as bananas and walnuts raise urinary 5-HIAA and can give a false-positive test for carcinoid tumour. In the body it is synthesised from dietary tryptophan, not absorbed as such in useful amounts.', 'admin', 'published', 3, true, '[["enterochromaffin cells", "gut", "git", "intestine"], ["platelets"], ["brain", "cns", "raphe nuclei", "neurons"], ["plants", "fruits", "bananas", "pineapple", "nuts", "tomatoes"], ["venoms", "wasp", "scorpion", "nettle"]]'::jsonb, 'saq p.108 B1, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-3044ab8d62', 'pharm-serotonin-receptors-and-agonists', 'saq', 'What are the functions of 5-HT (serotonin) in the human body?', '[]'::jsonb, 'Any 4 of: neurotransmitter in the CNS regulating mood, anxiety, sleep, appetite, temperature, pain perception and vomiting; precursor of melatonin in the pineal gland; in the gut, increases motility (peristalsis) and secretion; promotes platelet aggregation and haemostasis; vascular effects - constriction of most large vessels (including cranial and renal), dilatation in skeletal muscle and heart; stimulates sensory nerve endings (pain, itch) and triggers emesis via vagal afferents.', '[]'::jsonb, 'The breadth of these functions explains the breadth of serotonergic drugs: SSRIs for depression, buspirone for anxiety, triptans for migraine, ondansetron for vomiting, prucalopride for constipation and atypical antipsychotics for schizophrenia.', 'admin', 'published', 4, true, '[["neurotransmitter", "mood", "sleep", "appetite", "anxiety", "temperature"], ["melatonin precursor", "melatonin"], ["gut motility", "peristalsis", "gi motility"], ["platelet aggregation", "haemostasis"], ["vasoconstriction", "vasodilation", "vascular tone"], ["vomiting", "emesis", "pain", "nociception"]]'::jsonb, 'saq p.108 B2, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-fe36151d3c', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Name 3 sites in the body where 5-HT occurs in the highest concentrations.', '[]'::jsonb, '1. Gastrointestinal tract - enterochromaffin cells of the mucosa (about 90% of body serotonin). 2. Blood platelets (taken up from plasma and stored in dense granules). 3. Brain - raphe nuclei of the brainstem (also the pineal gland).', '[]'::jsonb, 'Platelets cannot synthesise serotonin; they take it up through the serotonin transporter as they pass through the gut circulation. Brain serotonin, though only 1 to 2% of the total, is made locally because the amine does not cross the blood-brain barrier.', 'admin', 'published', 3, true, '[["enterochromaffin cells", "gastrointestinal tract", "git", "gut", "intestine"], ["platelets", "blood"], ["brain", "cns", "raphe nuclei", "pineal gland"]]'::jsonb, 'saq p.108 B3, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-f026cfacae', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Discuss the synthesis, storage, release, reuptake, degradation and excretion of 5-HT.', '[]'::jsonb, 'Synthesis: dietary L-tryptophan is hydroxylated by tryptophan hydroxylase (rate-limiting) to 5-hydroxytryptophan, which is decarboxylated by aromatic L-amino acid decarboxylase to 5-HT. Storage: in vesicles (via the vesicular monoamine transporter VMAT, blocked by reserpine) in neurones and enterochromaffin cells, and in platelet dense granules. Release: calcium-dependent exocytosis. Reuptake: by the serotonin transporter SERT into nerve terminals and platelets (blocked by SSRIs, tricyclics and cocaine). Degradation: oxidative deamination by monoamine oxidase (mainly MAO-A) then aldehyde dehydrogenase to 5-hydroxyindoleacetic acid (5-HIAA). Excretion: 5-HIAA in the urine.', '[]'::jsonb, 'The pathway parallels that of noradrenaline. Urinary 5-HIAA is the diagnostic test for carcinoid syndrome, SERT is the target of the SSRI antidepressants, and combining MAO inhibitors with reuptake blockers causes serotonin syndrome.', 'admin', 'published', 5, true, '[["tryptophan"], ["tryptophan hydroxylase", "rate limiting"], ["5-hydroxytryptophan", "5-htp", "decarboxylase"], ["vesicles", "vmat", "granules", "reserpine"], ["exocytosis", "calcium"], ["sert", "reuptake", "serotonin transporter", "ssri"], ["mao", "monoamine oxidase", "mao-a"], ["5-hiaa", "5-hydroxyindoleacetic acid", "urine"]]'::jsonb, 'saq p.108 B4, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-63de79c517', 'pharm-serotonin-receptors-and-agonists', 'saq', 'How many classes (families) of 5-HT receptors are there?', '[]'::jsonb, 'Seven', '["7", "seven families", "seven classes", "7 families", "7 classes"]'::jsonb, 'Serotonin receptors are grouped into seven families, 5-HT1 to 5-HT7, on the basis of structure, signal transduction and pharmacology. Six are G-protein-coupled; the 5-HT3 receptor alone is a ligand-gated ion channel.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.109 B5b, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-6daab42403', 'pharm-serotonin-receptors-and-agonists', 'saq', 'How many 5-HT receptor subtypes are recognised in total across the seven receptor families?', '[]'::jsonb, '14', '["fourteen", "14 subtypes", "fourteen subtypes"]'::jsonb, 'The fourteen subtypes are 5-HT1A, 1B, 1D, 1E, 1F; 5-HT2A, 2B, 2C; 5-HT3; 5-HT4; 5-HT5A, 5B; 5-HT6 and 5-HT7. Clinically the important ones are 1A (buspirone), 1B/1D (triptans), 2A (atypical antipsychotics), 3 (ondansetron) and 4 (prokinetics).', 'admin', 'draft', 1, false, '[]'::jsonb, 'saq p.109 B5a, Autacoids SAQs tutorial. The count depends on convention (14 is the figure in Rang & Dale and Katzung; 5-ht5B is not functional in humans).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-2aee441e54', 'pharm-serotonin-receptors-and-agonists', 'saq', 'What type of receptors are the 5-HT receptors, and which second messengers are involved in their signal transduction?', '[]'::jsonb, 'All are G-protein-coupled receptors except 5-HT3, which is a ligand-gated cation channel (fast depolarisation by sodium and potassium flux, no second messenger). 5-HT1 (and 5-HT5): Gi/Go - inhibit adenylyl cyclase, reduce cAMP, open potassium channels. 5-HT2: Gq - activate phospholipase C, increasing IP3, DAG and intracellular calcium. 5-HT4, 5-HT6 and 5-HT7: Gs - stimulate adenylyl cyclase and increase cAMP.', '[]'::jsonb, 'The coupling predicts the effect: Gi-linked 5-HT1 receptors are inhibitory (autoreceptors, reduced transmitter release), Gq-linked 5-HT2 receptors contract smooth muscle and aggregate platelets, and Gs-linked 5-HT4 receptors enhance acetylcholine release in the gut.', 'admin', 'published', 4, true, '[["g-protein-coupled", "gpcr", "metabotropic"], ["5-ht3", "ligand-gated ion channel", "ion channel"], ["gi", "decrease camp", "inhibit adenylyl cyclase", "5-ht1"], ["gq", "ip3", "dag", "phospholipase c", "5-ht2"], ["gs", "increase camp", "5-ht4"]]'::jsonb, 'saq p.109 B5c-e, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-e49d737ac9', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Unlike all the other 5-HT receptors, which are G-protein-coupled, the 5-HT3 receptor is what type of receptor?', '[]'::jsonb, 'Ligand-gated ion channel', '["ion channel", "ligand gated ion channel", "ionotropic receptor", "ionotropic", "ligand-gated cation channel", "cation channel"]'::jsonb, 'The 5-HT3 receptor belongs to the same pentameric family as the nicotinic receptor: serotonin binding opens a sodium and potassium channel directly, giving fast depolarisation without a second messenger. It mediates vomiting, which ondansetron blocks.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.112 Q8b, Autacoids SAQs tutorial. Reworded from ''What is exceptional about the 5-HT3 post-receptor mechanism when compared to other 5-HT receptors?''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-67029092b9', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Regarding 5-HT1 receptors: how are they subdivided, where are the subtypes mainly found, and what post-receptor mechanism follows their activation?', '[]'::jsonb, 'Subtypes: 5-HT1A, 1B, 1D, 1E and 1F. Location: 1A - raphe nuclei (somatodendritic autoreceptors), hippocampus and cortex; 1B - cranial blood vessels and presynaptic nerve terminals; 1D - presynaptic trigeminal and other nerve terminals; 1E and 1F - brain (1F also trigeminal system). Function: mainly inhibitory, many acting as presynaptic autoreceptors that reduce transmitter release. Mechanism: coupled to Gi/Go - inhibit adenylyl cyclase and lower cAMP, open potassium channels (hyperpolarisation) and close calcium channels.', '[]'::jsonb, '5-HT1 receptors are the brakes of the serotonin system. Partial agonists at 1A receptors (buspirone) are anxiolytic, and agonists at 1B/1D receptors (triptans) constrict cranial vessels and block neuropeptide release in migraine.', 'admin', 'published', 4, true, '[["1a", "1b", "1d", "1e", "1f", "five subtypes"], ["raphe nuclei", "hippocampus", "brain", "cns"], ["cranial blood vessels", "cranial vessels", "trigeminal"], ["autoreceptors", "inhibitory", "presynaptic"], ["gi", "inhibit adenylyl cyclase", "decrease camp", "potassium channels", "hyperpolarisation"]]'::jsonb, 'saq p.110 Q6a-d, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-00a451c439', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Which important brain functions are controlled by the 5-HT1A receptor subtype?', '[]'::jsonb, 'Mood and anxiety (anxiolytic and antidepressant effects); also regulation of the firing of raphe serotonergic neurones (autoreceptor), body temperature (hypothermia), feeding, sleep, sexual behaviour, and learning and memory.', '[]'::jsonb, '5-HT1A receptors are somatodendritic autoreceptors on raphe neurones and postsynaptic receptors in the limbic system. Their slow desensitisation is thought to explain why SSRIs and buspirone take weeks to work.', 'admin', 'published', 2, true, '[["anxiety", "mood", "depression"], ["thermoregulation", "temperature", "feeding", "sleep", "autoreceptor", "memory", "sexual behaviour"]]'::jsonb, 'saq p.110 Q6e, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-9d115804a9', 'pharm-serotonin-receptors-and-agonists', 'saq', 'List two 5-HT1A partial agonists of clinical importance and indicate the clinical indication of each.', '[]'::jsonb, 'Buspirone - generalised anxiety disorder. Others: gepirone, ipsapirone and tandospirone - anxiety and depression; vilazodone (SSRI plus 5-HT1A partial agonist) - major depression.', '[]'::jsonb, 'Buspirone is anxiolytic without sedation, muscle relaxation, anticonvulsant effect or dependence, which distinguishes it from benzodiazepines. Its effect takes one to two weeks to appear, so it is useless for acute anxiety or benzodiazepine withdrawal.', 'admin', 'published', 2, true, '[["buspirone"], ["anxiety", "generalised anxiety disorder", "gad"], ["gepirone", "ipsapirone", "tandospirone", "vilazodone"], ["depression"]]'::jsonb, 'saq p.110 Q6f, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-2e42ef813c', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Where are the 5-HT1B and 5-HT1D receptors found, and how do 5-HT1B/1D agonists (triptans) work in the treatment of migraine?', '[]'::jsonb, '5-HT1B receptors are on the smooth muscle of cranial (meningeal, intracranial extracerebral) blood vessels; 5-HT1D (and 1B) receptors are on presynaptic trigeminal nerve terminals. Triptans: 1. constrict the dilated cranial vessels (1B); 2. inhibit release of vasoactive and inflammatory neuropeptides (CGRP, substance P) from perivascular trigeminal nerve endings, reducing neurogenic inflammation (1D); 3. inhibit pain transmission in the trigeminal nucleus of the brainstem.', '[]'::jsonb, 'Migraine pain is linked to activation of the trigeminovascular system with release of CGRP. Triptans act on all three components (vessel, nerve ending, brainstem relay) and are most effective when taken early in the headache phase.', 'admin', 'published', 3, true, '[["cranial blood vessels", "cranial vessels", "meningeal vessels"], ["trigeminal nerve", "presynaptic", "nerve terminals"], ["vasoconstriction", "constrict cranial vessels"], ["inhibit neuropeptide release", "cgrp", "substance p", "neurogenic inflammation"], ["inhibit pain transmission", "trigeminal nucleus"]]'::jsonb, 'saq p.110 Q6g,i, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-156aeba86d', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Briefly discuss the adverse effects of triptans.', '[]'::jsonb, 'Any 3 of: sensations of tingling, warmth, heaviness, pressure or tightness in the chest, neck and throat (''triptan sensations''); dizziness, drowsiness and fatigue; flushing; nausea; coronary vasospasm with angina, myocardial infarction or arrhythmia (rare); rise in blood pressure; injection-site reactions (sumatriptan); serotonin syndrome with SSRIs or MAO inhibitors; medication-overuse headache.', '[]'::jsonb, '5-HT1B receptors are also present on coronary arteries, so triptans can cause coronary vasospasm; this is the basis of their main contraindications. The common chest and throat tightness is usually not cardiac in origin.', 'admin', 'published', 3, true, '[["chest tightness", "chest pressure", "chest pain", "heaviness"], ["tingling", "paraesthesia", "warmth", "flushing"], ["dizziness", "drowsiness", "fatigue"], ["coronary vasospasm", "angina", "myocardial infarction"], ["hypertension"], ["serotonin syndrome", "injection site reaction", "nausea"]]'::jsonb, 'saq p.110 Q6j, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-44ef1039bb', 'pharm-serotonin-receptors-and-agonists', 'saq', 'What are the contraindications and cautions with the use of triptans?', '[]'::jsonb, 'Contraindications: ischaemic heart disease, previous myocardial infarction or coronary vasospasm (Prinzmetal''s angina); previous stroke or transient ischaemic attack; peripheral vascular disease; uncontrolled or severe hypertension; hemiplegic or basilar migraine; use within 24 hours of ergot alkaloids or another triptan; MAO inhibitors (sumatriptan, rizatriptan, zolmitriptan). Cautions: SSRIs/SNRIs (serotonin syndrome), hepatic or renal impairment, pregnancy, elderly patients and those with cardiovascular risk factors.', '[]'::jsonb, 'All the absolute contraindications follow from vasoconstriction: any vascular bed already compromised could become ischaemic. Combining triptans with ergots adds vasoconstrictor effects, and MAO inhibitors block the metabolism of several triptans.', 'admin', 'published', 3, true, '[["ischaemic heart disease", "coronary artery disease", "angina", "myocardial infarction", "prinzmetal"], ["stroke", "tia", "cerebrovascular disease"], ["hypertension", "uncontrolled hypertension"], ["peripheral vascular disease"], ["hemiplegic migraine", "basilar migraine"], ["ergot", "ergotamine", "maoi", "mao inhibitors"], ["ssri", "serotonin syndrome", "hepatic impairment", "pregnancy"]]'::jsonb, 'saq p.110 Q6l, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-4d3e041b50', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Briefly discuss the challenges encountered with the use of triptans.', '[]'::jsonb, 'Any 3 of: headache recurrence within 24 hours because of short half-lives (e.g. sumatriptan about 2 hours); low and variable oral bioavailability of sumatriptan (about 15%) and poor absorption during an attack (gastric stasis, vomiting); they are not effective in all patients and work best only if taken early; cardiovascular contraindications limit use; medication-overuse headache if taken on more than about 10 days a month; cost; no role in prophylaxis; interactions (ergots, MAO inhibitors, SSRIs).', '[]'::jsonb, 'Newer triptans address some of these problems: naratriptan and frovatriptan have long half-lives and less recurrence; nasal, subcutaneous and orally disintegrating forms bypass gastric stasis. Limiting use to fewer than 10 days a month prevents overuse headache.', 'admin', 'draft', 3, true, '[["recurrence", "headache recurrence", "short half-life", "short duration"], ["low bioavailability", "poor oral absorption", "gastric stasis"], ["not effective in all", "non-responders", "must be taken early"], ["cardiovascular contraindications", "coronary disease"], ["medication overuse headache", "overuse"], ["cost", "expensive"], ["not for prophylaxis", "interactions"]]'::jsonb, 'saq p.110 Q6k, Autacoids SAQs tutorial. Open-ended tutorial question; the answer is a reasonable synthesis, not a fixed list.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-43de643a9f', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'saq', 'List other drugs (apart from triptans) used for the treatment of migraine.', '[]'::jsonb, 'Acute attack: simple analgesics and NSAIDs (paracetamol, aspirin, ibuprofen, naproxen, diclofenac); ergot alkaloids (ergotamine, dihydroergotamine); antiemetics (metoclopramide, domperidone, prochlorperazine); gepants (rimegepant, ubrogepant). Prophylaxis: beta-blockers (propranolol, metoprolol); tricyclic antidepressants (amitriptyline); antiepileptics (topiramate, sodium valproate); calcium channel blocker flunarizine; 5-HT2 antagonists (pizotifen, methysergide, cyproheptadine); CGRP monoclonal antibodies (erenumab); botulinum toxin.', '[]'::jsonb, 'Treatment is divided into drugs that abort an attack and drugs taken daily to reduce attack frequency. Metoclopramide helps twice over, relieving nausea and reversing the gastric stasis that delays absorption of oral analgesics.', 'admin', 'published', 4, true, '[["paracetamol", "aspirin", "nsaids", "ibuprofen", "naproxen"], ["ergotamine", "dihydroergotamine", "ergot alkaloids"], ["metoclopramide", "domperidone", "antiemetics"], ["propranolol", "beta blockers", "metoprolol"], ["amitriptyline"], ["topiramate", "valproate"], ["flunarizine", "pizotifen", "methysergide", "cyproheptadine"], ["erenumab", "cgrp antagonists", "gepants", "botulinum toxin"]]'::jsonb, 'saq p.110 Q6m, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-fd61856ff9', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Regarding 5-HT2 receptors: how are they subdivided, where are the subtypes mainly found, and what post-receptor mechanism follows their activation?', '[]'::jsonb, 'Subtypes: 5-HT2A, 5-HT2B and 5-HT2C. Location: 2A - vascular, bronchial, gut and uterine smooth muscle, platelets, and cerebral cortex; 2B - stomach fundus, heart valves and vascular endothelium; 2C - choroid plexus, hypothalamus and limbic system. Mechanism: all couple to Gq/11 and activate phospholipase C, producing IP3 (releasing intracellular calcium) and DAG (activating protein kinase C).', '[]'::jsonb, '5-HT2 receptors are excitatory. 2A receptors mediate smooth-muscle contraction, platelet aggregation and the hallucinogenic effect of LSD; 2B activation by fenfluramine and ergot-derived drugs causes cardiac valve fibrosis; 2C receptors reduce appetite.', 'admin', 'published', 4, true, '[["2a", "2b", "2c", "three subtypes"], ["smooth muscle", "platelets", "cortex"], ["stomach fundus", "heart valves"], ["choroid plexus", "hypothalamus"], ["gq", "phospholipase c", "ip3", "dag", "calcium"]]'::jsonb, 'saq p.112 Q7a-c, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-0679546de6', 'pharm-serotonin-receptors-and-agonists', 'saq', 'List several 5-HT2A receptor agonists and state their clinical significance.', '[]'::jsonb, 'Lysergic acid diethylamide (LSD), psilocybin, mescaline and DOM/DOI: hallucinogens (psychedelics), important as drugs of abuse and not used therapeutically. Their psychedelic effects are mediated by 5-HT2A (partial) agonism in the cerebral cortex.', '[]'::jsonb, 'Hallucinogenic potency correlates with affinity for the 5-HT2A receptor, and the effects are blocked by 5-HT2A antagonists such as ketanserin and the atypical antipsychotics. This link is part of the rationale for 5-HT2A blockade in schizophrenia.', 'admin', 'published', 2, true, '[["lsd", "lysergic acid diethylamide"], ["psilocybin", "mescaline", "dom"], ["hallucinogens", "hallucinogenic", "psychedelics", "drugs of abuse"]]'::jsonb, 'saq p.112 Q7f, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-ddc38c6be0', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'saq', 'List 5-HT2 receptor antagonists and indicate their clinical significance.', '[]'::jsonb, 'Any 4 of: ketanserin (5-HT2A and alpha-1 blocker) - antihypertensive; cyproheptadine (5-HT2 and H1 blocker) - allergic conditions, carcinoid and serotonin syndrome, appetite stimulant; atypical antipsychotics (clozapine, risperidone, olanzapine, quetiapine) - schizophrenia, with fewer extrapyramidal effects; methysergide and pizotifen - migraine prophylaxis (methysergide also carcinoid; causes retroperitoneal fibrosis); ritanserin - experimental; trazodone and mirtazapine - antidepressants.', '[]'::jsonb, 'Blocking 5-HT2A receptors relaxes vascular smooth muscle and reduces platelet aggregation, and in the brain it improves negative symptoms of schizophrenia while lessening the extrapyramidal effects of D2 blockade. Few of these drugs are selective, which explains their side effects.', 'admin', 'published', 4, true, '[["ketanserin", "hypertension"], ["cyproheptadine", "carcinoid", "serotonin syndrome", "appetite stimulant"], ["clozapine", "risperidone", "olanzapine", "quetiapine", "atypical antipsychotics", "schizophrenia"], ["methysergide", "pizotifen", "migraine prophylaxis"], ["ritanserin", "trazodone", "mirtazapine"]]'::jsonb, 'saq p.112 Q7g-h, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-460e9ad01e', 'pharm-serotonin-receptors-and-agonists', 'saq', 'What functions do 5-HT2C receptors mediate?', '[]'::jsonb, 'Control of appetite and feeding (activation causes satiety and reduced food intake); regulation of mood and anxiety; regulation of cerebrospinal fluid production by the choroid plexus; inhibition of dopamine and noradrenaline release.', '[]'::jsonb, 'Because 5-HT2C activation produces satiety, the agonist lorcaserin was marketed for obesity, and antagonism of 5-HT2C (with H1 block) contributes to the weight gain caused by olanzapine, clozapine and mirtazapine.', 'admin', 'published', 2, true, '[["appetite", "satiety", "feeding", "food intake"], ["mood", "anxiety", "csf production", "cerebrospinal fluid", "dopamine release"]]'::jsonb, 'saq p.112 Q7i, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-35f3e0dbe5', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Where are 5-HT3 receptors found and what do they mediate?', '[]'::jsonb, 'Location: peripheral - vagal and other visceral afferent nerve endings in the gut, enteric neurones, nociceptive sensory nerve endings; central - area postrema (chemoreceptor trigger zone) and nucleus tractus solitarius. They mediate: the vomiting reflex (nausea and emesis, e.g. after cytotoxic drugs release 5-HT from enterochromaffin cells); pain (excitation of nociceptors); gut motility and secretion; bradycardia and hypotension reflexes.', '[]'::jsonb, 'Cytotoxic drugs and radiation release serotonin from enterochromaffin cells, which stimulates 5-HT3 receptors on vagal afferents and in the area postrema to trigger vomiting. That single pathway is why 5-HT3 antagonists transformed chemotherapy.', 'admin', 'published', 3, true, '[["vagal afferents", "gut", "enteric neurons", "peripheral nerve endings"], ["area postrema", "chemoreceptor trigger zone", "ctz", "nucleus tractus solitarius"], ["vomiting", "emesis", "nausea"], ["pain", "nociception", "gut motility"]]'::jsonb, 'saq p.112 Q8a, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-6eecd11d93', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'saq', 'List five selective 5-HT3 receptor antagonists.', '[]'::jsonb, 'Any 5 of: ondansetron; granisetron; tropisetron; dolasetron; palonosetron; ramosetron; alosetron.', '[]'::jsonb, 'The ''setrons'' differ mainly in half-life: palonosetron is the longest acting (about 40 hours) and is effective against delayed emesis. Alosetron is used for diarrhoea-predominant irritable bowel syndrome rather than vomiting.', 'admin', 'published', 5, true, '[["ondansetron"], ["granisetron"], ["tropisetron"], ["dolasetron"], ["palonosetron"], ["ramosetron"], ["alosetron"]]'::jsonb, 'saq p.113 Q8c, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-5d4899b236', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'saq', 'Indicate the clinical uses of selective 5-HT3 antagonists.', '[]'::jsonb, 'Prevention and treatment of chemotherapy-induced nausea and vomiting (especially acute emesis with cisplatin); radiotherapy-induced nausea and vomiting; postoperative nausea and vomiting; hyperemesis and other severe vomiting; alosetron for severe diarrhoea-predominant irritable bowel syndrome in women.', '[]'::jsonb, 'They are most effective against acute chemotherapy-induced emesis, usually combined with dexamethasone and an NK1 antagonist (aprepitant). They are ineffective in motion sickness, which is mediated by muscarinic and H1 receptors. Adverse effects are headache, constipation and QT prolongation.', 'admin', 'published', 3, true, '[["chemotherapy-induced", "chemotherapy", "cytotoxic"], ["radiotherapy", "radiation"], ["postoperative", "ponv"], ["irritable bowel syndrome", "ibs", "alosetron", "hyperemesis"]]'::jsonb, 'saq p.113 Q8d, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-004d27d447', 'pharm-serotonin-receptors-and-agonists', 'saq', 'Where are 5-HT4 receptors found, and what is their main physiological role?', '[]'::jsonb, 'Location: enteric neurones (myenteric plexus), smooth muscle and secretory cells of the gastrointestinal tract; also the atria of the heart, the bladder and the CNS (hippocampus, basal ganglia). Main role: in the gut they are presynaptic, Gs-coupled receptors that increase acetylcholine release, stimulating peristalsis, gastric emptying and intestinal secretion (prokinetic effect).', '[]'::jsonb, '5-HT4 receptors drive the peristaltic reflex by enhancing cholinergic transmission. Atrial 5-HT4 receptors explain the arrhythmia risk of the older agonists, and cisapride was withdrawn because it also blocked hERG potassium channels and prolonged the QT interval.', 'admin', 'published', 3, true, '[["enteric neurons", "myenteric plexus", "gut", "gastrointestinal tract"], ["heart", "atria", "cns", "hippocampus"], ["acetylcholine release", "increase ach"], ["peristalsis", "prokinetic", "gut motility", "gastric emptying", "secretion"]]'::jsonb, 'saq p.113 Q9a-b, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-335823466b', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'saq', 'List three 5-HT4 receptor agonists and indicate their clinical use.', '[]'::jsonb, 'Any 3 of: cisapride - gastro-oesophageal reflux and gastroparesis (withdrawn or restricted because of QT prolongation); metoclopramide (also a D2 antagonist) - gastroparesis, reflux, antiemetic; tegaserod - constipation-predominant irritable bowel syndrome; prucalopride - chronic constipation; mosapride - reflux and dyspepsia.', '[]'::jsonb, 'All are prokinetics. Prucalopride is highly selective and free of the cardiac effects that removed cisapride (hERG block) and restricted tegaserod (cardiovascular ischaemic events) from the market. Metoclopramide owes its prokinetic effect partly to 5-HT4 agonism and its antiemetic effect to D2 blockade.', 'admin', 'published', 3, true, '[["cisapride"], ["metoclopramide"], ["tegaserod"], ["prucalopride"], ["mosapride"], ["constipation", "irritable bowel syndrome", "gastroparesis", "reflux", "prokinetic"]]'::jsonb, 'saq p.113 Q9c, Autacoids SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-cb6a8fade6', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Benznidazole and nifurtimox are the drugs of choice for which protozoal disease?', '[]'::jsonb, 'Chagas disease', '["American trypanosomiasis", "Trypanosoma cruzi infection", "Chagas'' disease", "Chagas", "T. cruzi infection", "South American trypanosomiasis"]'::jsonb, 'Both are nitro-heterocyclic drugs that generate free radicals toxic to Trypanosoma cruzi and are most effective in the acute phase of Chagas disease. Nifurtimox is also combined with eflornithine (NECT) for late-stage West African sleeping sickness.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q1a, JB revision SAQs. Reworded from ''List the indication for benznidazole, nifurtimox...''') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-56e4752410', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Sodium stibogluconate is indicated for the treatment of which disease?', '[]'::jsonb, 'Leishmaniasis', '["visceral leishmaniasis", "kala-azar", "kala azar", "cutaneous leishmaniasis", "leishmania infection"]'::jsonb, 'Sodium stibogluconate is a pentavalent antimonial given by injection for visceral (kala-azar) and cutaneous leishmaniasis. It is reduced to trivalent antimony, which inhibits parasite glycolysis and trypanothione reductase. Cardiotoxicity (QT prolongation) and pancreatitis limit its use.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q1b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-580f33dcf9', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Diloxanide furoate is indicated for the treatment of which infection?', '[]'::jsonb, 'Asymptomatic intestinal amoebiasis', '["amoebiasis", "amebiasis", "intestinal amoebiasis", "luminal amoebiasis", "asymptomatic amoebiasis", "Entamoeba histolytica cyst carriage", "asymptomatic cyst passers", "amoebic cyst carriers"]'::jsonb, 'Diloxanide is a luminal amoebicide: it is poorly absorbed and kills Entamoeba histolytica trophozoites and cysts in the bowel lumen. It is the drug of choice for asymptomatic cyst passers and is given after metronidazole in invasive disease to eradicate remaining luminal organisms.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q1c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-f145a53841', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'saq', 'Describe the two essential biochemical (pharmacodynamic) reactions that require vitamin B12.', '[]'::jsonb, '1. Methylcobalamin is the cofactor for methionine synthase, which transfers a methyl group from 5-methyltetrahydrofolate to homocysteine, forming methionine and regenerating tetrahydrofolate (needed for DNA synthesis). 2. Deoxyadenosylcobalamin is the cofactor for methylmalonyl-CoA mutase, which converts methylmalonyl-CoA to succinyl-CoA.', '[]'::jsonb, 'Failure of the first reaction traps folate as methyltetrahydrofolate and causes megaloblastic anaemia with raised homocysteine; failure of the second causes methylmalonic acid to accumulate and is linked to the neurological damage, which folic acid cannot correct.', 'admin', 'published', 2, true, '[["methionine synthase", "homocysteine to methionine", "methylcobalamin", "methyl transfer"], ["tetrahydrofolate", "folate trap", "dna synthesis"], ["methylmalonyl-coa mutase", "methylmalonyl coa to succinyl coa", "succinyl-coa", "deoxyadenosylcobalamin"]]'::jsonb, 'saq p.094 Q2, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-908dc27569', 'pharm-iminostilbenes-succinimides-lamotrigine', 'saq', 'Briefly describe the pharmacokinetics of carbamazepine and its adverse effects.', '[]'::jsonb, 'Pharmacokinetics: slow and erratic but nearly complete oral absorption; about 75% protein bound; metabolised in the liver by CYP3A4 to the active 10,11-epoxide; potent enzyme inducer that induces its own metabolism (autoinduction), so the half-life falls from about 36 hours to 15-20 hours over the first weeks; metabolites excreted in urine. Adverse effects: diplopia, ataxia, dizziness, drowsiness; nausea; hyponatraemia (SIADH); rash, including Stevens-Johnson syndrome (HLA-B*15:02); leucopenia, agranulocytosis and aplastic anaemia; hepatotoxicity; teratogenicity (neural tube defects); many drug interactions.', '[]'::jsonb, 'Autoinduction means the dose must be built up over weeks, and induction of other enzymes causes failure of oral contraceptives and warfarin. The dose-related neurological effects are the commonest; the idiosyncratic skin and marrow reactions are the most dangerous.', 'admin', 'published', 5, true, '[["slow absorption", "erratic absorption"], ["cyp3a4", "hepatic metabolism", "epoxide", "active metabolite"], ["autoinduction", "enzyme inducer", "induces own metabolism"], ["diplopia", "ataxia", "dizziness", "drowsiness"], ["hyponatraemia", "hyponatremia", "siadh"], ["rash", "stevens-johnson"], ["agranulocytosis", "aplastic anaemia", "leucopenia"], ["teratogenic", "neural tube defects", "hepatotoxicity"]]'::jsonb, 'saq p.094 Q4, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-b8fc5d958a', 'pharm-receptors-and-signal-transduction-mechanisms', 'saq', 'Concisely describe the 4 recognised mechanisms of transmembrane signal transduction, giving one example for each.', '[]'::jsonb, '1. Ligand-gated ion channels (ionotropic receptors): the ligand opens a channel within milliseconds, e.g. nicotinic acetylcholine receptor, GABA-A receptor. 2. G-protein-coupled receptors: activate G proteins that regulate enzymes or channels and second messengers (cAMP, IP3/DAG) within seconds, e.g. adrenoceptors, muscarinic receptors. 3. Enzyme-linked (kinase-linked) receptors: ligand binding activates intrinsic or associated tyrosine kinase, e.g. insulin and growth factor receptors, cytokine receptors (JAK-STAT). 4. Intracellular (nuclear) receptors: lipid-soluble ligands cross the membrane and regulate gene transcription over hours, e.g. steroid, thyroid hormone and vitamin D receptors.', '[]'::jsonb, 'The four families differ in speed: milliseconds for ion channels, seconds for G-protein-coupled receptors, minutes to hours for kinase-linked receptors and hours for nuclear receptors, which explains for example why steroids act slowly and suxamethonium at once.', 'admin', 'published', 4, true, '[["ligand-gated ion channels", "ion channels", "ionotropic", "nicotinic", "gaba-a"], ["g-protein-coupled", "gpcr", "second messengers", "adrenoceptors", "muscarinic"], ["tyrosine kinase", "enzyme-linked", "kinase-linked", "insulin receptor", "cytokine"], ["intracellular receptors", "nuclear receptors", "steroid", "thyroid", "gene transcription"]]'::jsonb, 'saq p.097 PP3 Q1, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-180d13518e', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'Classify antithyroid drugs, give examples in each class, and state the mechanism of action of each class.', '[]'::jsonb, '1. Thioamides (carbimazole, methimazole, propylthiouracil): inhibit thyroid peroxidase, blocking iodide oxidation, organification and coupling of iodotyrosines; propylthiouracil also inhibits peripheral conversion of T4 to T3. 2. Iodides (Lugol''s iodine, potassium iodide): inhibit hormone release and organification (Wolff-Chaikoff effect) and reduce gland vascularity. 3. Radioactive iodine (I-131): concentrated in the gland, where beta-emission destroys follicular cells. 4. Anion inhibitors (potassium perchlorate, thiocyanate): competitively block iodide uptake by the sodium-iodide symporter. 5. Beta-blockers (propranolol): control sympathetic symptoms and reduce T4 to T3 conversion. (Iodinated contrast media, e.g. ipodate, inhibit T4 to T3 conversion.)', '[]'::jsonb, 'The classes act at successive steps of thyroid hormone production: uptake of iodide, its organification and coupling, release of stored hormone and peripheral activation. Thioamides do not affect stored hormone, so their clinical effect takes three to four weeks.', 'admin', 'published', 5, true, '[["thioamides", "carbimazole", "methimazole", "propylthiouracil"], ["thyroid peroxidase", "organification", "coupling"], ["iodides", "lugol''s iodine", "potassium iodide", "inhibit hormone release"], ["radioactive iodine", "i-131", "radioiodine"], ["perchlorate", "thiocyanate", "iodide uptake"], ["propranolol", "beta blockers"]]'::jsonb, 'saq p.094 Q6, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-2b7d63c1a8', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'List 10 unrelated organ system effects of morphine.', '[]'::jsonb, 'Any 10 of: analgesia; euphoria (or dysphoria); sedation; respiratory depression; cough suppression; miosis (pinpoint pupils); nausea and vomiting (chemoreceptor trigger zone); constipation (reduced gut motility); spasm of the sphincter of Oddi with raised biliary pressure; urinary retention; histamine release with itching, urticaria and bronchoconstriction; vasodilatation and postural hypotension; bradycardia; truncal muscle rigidity; reduced uterine tone and prolonged labour; increased ADH and prolactin release, reduced LH; immunosuppression; tolerance and dependence.', '[]'::jsonb, 'Most effects are mediated by mu receptors in the brain, spinal cord and gut. Tolerance develops to nearly all of them except miosis and constipation, which is why a laxative is prescribed with regular morphine and pinpoint pupils remain a sign of overdose.', 'admin', 'published', 5, true, '[["analgesia"], ["euphoria", "dysphoria"], ["sedation", "drowsiness"], ["respiratory depression"], ["cough suppression", "antitussive"], ["miosis", "pinpoint pupils"], ["nausea", "vomiting"], ["constipation"], ["biliary spasm", "sphincter of oddi"], ["urinary retention"], ["histamine release", "pruritus", "itching"], ["hypotension", "vasodilation", "bradycardia"], ["dependence", "tolerance"], ["prolonged labour", "adh release"]]'::jsonb, 'saq p.094 Q7, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-fee821f5b5', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'Give 5 precautions (conditions needing caution) in the use of opioid analgesics.', '[]'::jsonb, 'Any 5 of: respiratory disease with reduced reserve (asthma, COPD, cor pulmonale); head injury and raised intracranial pressure; hepatic impairment; renal impairment (accumulation of morphine-6-glucuronide); pregnancy, labour and breastfeeding (neonatal respiratory depression); the elderly, neonates and infants; biliary colic and pancreatitis; hypothyroidism and adrenal insufficiency; prostatic hypertrophy; hypotension or shock; concurrent CNS depressants (alcohol, benzodiazepines) and MAO inhibitors; history of drug dependence; undiagnosed acute abdomen.', '[]'::jsonb, 'Each caution follows from an opioid action: respiratory depression raises PaCO2 and so intracranial pressure and masks pupillary signs in head injury; reduced clearance prolongs effects in liver and renal disease; and smooth-muscle spasm worsens biliary colic and urinary retention.', 'admin', 'published', 5, true, '[["asthma", "copd", "respiratory disease", "respiratory depression"], ["head injury", "raised intracranial pressure"], ["liver disease", "hepatic impairment"], ["renal impairment", "renal failure"], ["pregnancy", "labour", "breastfeeding", "neonates"], ["elderly", "infants"], ["biliary colic", "pancreatitis"], ["hypothyroidism", "addison''s"], ["cns depressants", "alcohol", "benzodiazepines", "mao inhibitors"], ["dependence", "addiction"], ["prostatic hypertrophy", "hypotension"]]'::jsonb, 'saq p.094 Q8, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-5d922f0c42', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List five unrelated effects of hydrochlorothiazide.', '[]'::jsonb, 'Any 5 of: natriuresis and diuresis; fall in blood pressure (reduced volume, later vasodilatation); hypokalaemia; hyponatraemia; hypomagnesaemia; hypochloraemic metabolic alkalosis; hypercalcaemia (reduced urinary calcium excretion); hyperuricaemia (gout); hyperglycaemia (impaired glucose tolerance); hyperlipidaemia (raised LDL and triglycerides); paradoxical reduction of urine volume in diabetes insipidus; erectile dysfunction; photosensitivity and rash.', '[]'::jsonb, 'Thiazides block the Na+/Cl- cotransporter in the distal convoluted tubule. More sodium reaching the collecting duct is exchanged for potassium and hydrogen ions, and enhanced calcium reabsorption makes thiazides useful in hypercalciuria and osteoporosis.', 'admin', 'published', 5, true, '[["diuresis", "natriuresis"], ["antihypertensive", "lowers blood pressure"], ["hypokalaemia", "hypokalemia"], ["hyponatraemia", "hyponatremia"], ["hypercalcaemia", "hypercalcemia", "reduced calcium excretion"], ["hyperuricaemia", "hyperuricemia", "gout"], ["hyperglycaemia", "hyperglycemia"], ["hyperlipidaemia", "hyperlipidemia"], ["metabolic alkalosis"], ["diabetes insipidus", "erectile dysfunction"]]'::jsonb, 'saq p.094 Q9, JB revision SAQs. The number is misprinted on the page (''List % unrelated effects''); taken as five.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-080514ed5d', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Write short notes on the mechanism of insulin secretion from pancreatic beta cells.', '[]'::jsonb, 'Glucose enters the beta cell through the GLUT2 transporter and is phosphorylated by glucokinase (the glucose sensor). Its metabolism raises the ATP/ADP ratio, which closes ATP-sensitive potassium channels. The membrane depolarises, voltage-gated (L-type) calcium channels open, calcium enters, and insulin-containing granules are released by exocytosis (with C-peptide). Secretion is biphasic and is amplified by incretins (GLP-1, GIP), amino acids and vagal stimulation, and inhibited by alpha-2 stimulation and somatostatin.', '[]'::jsonb, 'The K-ATP channel is where drugs act: sulphonylureas and meglitinides close it, releasing insulin whatever the glucose level, whereas diazoxide and thiazides open it and inhibit secretion. Incretin-based drugs amplify only glucose-dependent release.', 'admin', 'published', 4, true, '[["glut2", "glucose uptake"], ["glucokinase", "glucose metabolism"], ["atp", "atp/adp ratio"], ["atp-sensitive potassium channels", "k-atp channels close", "katp"], ["depolarisation", "depolarization"], ["calcium channels", "calcium influx"], ["exocytosis", "insulin release"], ["incretins", "glp-1", "biphasic"]]'::jsonb, 'saq p.094 Q10, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-68a287682f', 'pharm-oral-antidiabetic-drugs', 'saq', 'Describe the mechanisms by which thiazide diuretics and sulphonylurea drugs affect blood sugar.', '[]'::jsonb, 'Thiazides raise blood glucose: they open ATP-sensitive potassium channels and cause hypokalaemia, both of which hyperpolarise the beta cell and reduce insulin secretion; they also reduce peripheral insulin sensitivity. Sulphonylureas lower blood glucose: they bind the SUR1 subunit and close ATP-sensitive potassium channels, depolarising the beta cell, opening calcium channels and stimulating insulin release.', '[]'::jsonb, 'The two drug groups act in opposite directions on the same channel. Thiazide-induced hyperglycaemia is partly prevented by correcting hypokalaemia, and the thiazide-related drug diazoxide is used to treat insulinoma for exactly this reason.', 'admin', 'published', 4, true, '[["thiazides hyperglycaemia", "hyperglycaemia", "raise blood glucose", "hyperglycemia"], ["hypokalaemia", "open k-atp channels", "hyperpolarisation", "reduced insulin secretion"], ["insulin resistance", "reduced insulin sensitivity"], ["sulphonylureas hypoglycaemia", "lower blood glucose", "hypoglycemia"], ["close k-atp channels", "sur1", "depolarisation"], ["insulin release", "insulin secretion"]]'::jsonb, 'saq p.094 Q11, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-92e4e205bb', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Classify insulins, giving 2 examples in each group, and indicate the onset, peak and duration of action of each class.', '[]'::jsonb, '1. Rapid-acting analogues (lispro, aspart, glulisine): onset 10-20 minutes, peak 1-2 hours, duration 3-5 hours. 2. Short-acting (regular/soluble insulin, e.g. Actrapid, Humulin R): onset 30-60 minutes, peak 2-4 hours, duration 6-8 hours. 3. Intermediate-acting (NPH/isophane, lente): onset 1-2 hours, peak 4-10 hours, duration 12-18 hours. 4. Long-acting (glargine, detemir, degludec; older: ultralente, protamine zinc): onset 1-4 hours, no pronounced peak, duration about 24 hours or more. 5. Premixed (biphasic) insulins, e.g. 30% soluble with 70% isophane (Mixtard).', '[]'::jsonb, 'Classification is by time-course after subcutaneous injection, which depends on how quickly the preparation dissociates into absorbable monomers. Rapid and short-acting insulins cover meals; intermediate and long-acting insulins give basal cover. Only soluble insulin is routinely given intravenously.', 'admin', 'published', 5, true, '[["rapid-acting", "lispro", "aspart", "glulisine"], ["short-acting", "regular insulin", "soluble insulin", "actrapid"], ["intermediate-acting", "nph", "isophane", "lente"], ["long-acting", "glargine", "detemir", "degludec", "ultralente"], ["premixed", "biphasic", "mixtard"], ["onset", "peak", "duration", "peakless"]]'::jsonb, 'saq p.094 Q12, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-1576f55f73', 'pharm-gh-prolactin-and-its-inhibitor', 'saq', 'List 2 types of recombinant human growth hormone used in clinical practice.', '[]'::jsonb, 'Somatropin (identical to the 191-amino-acid native hormone); somatrem (methionyl human growth hormone, with an extra N-terminal methionine).', '[]'::jsonb, 'Recombinant hormone replaced pituitary-derived growth hormone, which had transmitted Creutzfeldt-Jakob disease. It is used for growth hormone deficiency, Turner syndrome, chronic renal failure in children and AIDS wasting. Mecasermin is recombinant IGF-1, not growth hormone.', 'admin', 'published', 2, true, '[["somatropin"], ["somatrem", "methionyl growth hormone"]]'::jsonb, 'saq p.094 Q13, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-4f4654dbbb', 'pharm-gh-prolactin-and-its-inhibitor', 'saq', 'What are the clinical uses of octreotide?', '[]'::jsonb, 'Any 4 of: acromegaly; carcinoid syndrome (flushing and diarrhoea); other secretory neuroendocrine tumours (VIPoma, glucagonoma, gastrinoma, insulinoma); bleeding oesophageal varices; secretory diarrhoea (AIDS-related, chemotherapy-induced); pancreatic and enterocutaneous fistulae and after pancreatic surgery; dumping syndrome; sulphonylurea-induced hypoglycaemia; TSH-secreting adenoma.', '[]'::jsonb, 'Octreotide is a long-acting somatostatin analogue. It inhibits secretion of growth hormone and of most gut and pancreatic hormones and reduces splanchnic blood flow, which explains its uses in acromegaly, hormone-secreting tumours and variceal bleeding. Gallstones are a long-term adverse effect.', 'admin', 'published', 4, true, '[["acromegaly"], ["carcinoid syndrome", "carcinoid"], ["vipoma", "glucagonoma", "gastrinoma", "neuroendocrine tumours", "insulinoma"], ["variceal bleeding", "oesophageal varices", "esophageal varices"], ["secretory diarrhoea", "diarrhea"], ["pancreatic fistula", "dumping syndrome"], ["sulphonylurea hypoglycaemia"]]'::jsonb, 'saq p.094 Q14, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-6a840b0346', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'saq', 'Classify drugs used in the treatment of asthma according to their mechanism of action, giving examples in each class.', '[]'::jsonb, 'Bronchodilators: 1. beta-2 agonists - short-acting (salbutamol, terbutaline), long-acting (salmeterol, formoterol): raise cAMP; 2. methylxanthines (theophylline, aminophylline): phosphodiesterase inhibition and adenosine antagonism; 3. antimuscarinics (ipratropium, tiotropium): block M3 receptors. Anti-inflammatory agents: 4. corticosteroids - inhaled (beclometasone, budesonide, fluticasone), systemic (prednisolone, hydrocortisone); 5. leukotriene modifiers - receptor antagonists (montelukast, zafirlukast), 5-lipoxygenase inhibitor (zileuton); 6. mast cell stabilisers (sodium cromoglicate, nedocromil); 7. biologics - anti-IgE (omalizumab), anti-IL-5 (mepolizumab). Also magnesium sulphate in acute severe asthma.', '[]'::jsonb, 'Asthma combines bronchoconstriction with airway inflammation, so drugs are grouped as relievers (bronchodilators) and controllers (anti-inflammatory). Inhaled corticosteroids are the foundation of control; relying on bronchodilators alone leaves the inflammation untreated.', 'admin', 'published', 5, true, '[["beta-2 agonists", "salbutamol", "terbutaline", "salmeterol", "formoterol"], ["methylxanthines", "theophylline", "aminophylline"], ["antimuscarinics", "ipratropium", "tiotropium", "anticholinergics"], ["corticosteroids", "beclometasone", "budesonide", "fluticasone", "prednisolone"], ["leukotriene antagonists", "montelukast", "zafirlukast", "zileuton"], ["mast cell stabilisers", "cromoglicate", "cromolyn", "nedocromil"], ["omalizumab", "anti-ige", "mepolizumab"]]'::jsonb, 'saq p.094 Q15, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-f1dc302384', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'saq', 'List four uses of immune modulator (immunomodulating) drugs.', '[]'::jsonb, 'Any 4 of: prevention and treatment of organ transplant rejection and graft-versus-host disease (ciclosporin, tacrolimus, mycophenolate); autoimmune and inflammatory diseases such as rheumatoid arthritis, SLE, inflammatory bowel disease, psoriasis and multiple sclerosis (methotrexate, azathioprine, biologics, interferon beta); prevention of Rhesus haemolytic disease of the newborn (anti-D immunoglobulin); cancer immunotherapy (BCG for bladder cancer, interferon alfa, interleukin-2, checkpoint inhibitors); chronic viral infections (interferon alfa in hepatitis B and C; imiquimod for warts); immunodeficiency states (immunoglobulins, colony-stimulating factors).', '[]'::jsonb, 'Immunomodulators either suppress an unwanted immune response (rejection, autoimmunity, Rhesus sensitisation) or stimulate a deficient one (cancer, chronic infection, immunodeficiency). The main risks of suppression are infection and malignancy. Anti-D immunoglobulin is a simple example: it clears fetal red cells before the mother can be sensitised.', 'admin', 'draft', 4, true, '[["transplant rejection", "organ transplantation", "graft rejection", "graft versus host"], ["autoimmune diseases", "rheumatoid arthritis", "sle", "inflammatory bowel disease", "psoriasis", "multiple sclerosis"], ["rhesus", "anti-d", "haemolytic disease of newborn"], ["cancer", "bcg", "bladder cancer", "immunotherapy"], ["hepatitis", "viral infections", "interferon", "warts"], ["immunodeficiency", "immunoglobulin"]]'::jsonb, 'saq p.094 Q16, JB revision SAQs. Vague question; answer covers both immunosuppressant and immunostimulant uses.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-immunomodulants-i-70007ff42b', 'pharm-immunomodulants-i', 'saq', 'List 4 immunostimulants.', '[]'::jsonb, 'Any 4 of: BCG vaccine; levamisole; interferons (alfa, beta, gamma); interleukin-2 (aldesleukin); colony-stimulating factors (filgrastim); thalidomide and lenalidomide; imiquimod; inosine pranobex (isoprinosine); thymosin; vaccines.', '[]'::jsonb, 'Immunostimulants enhance host defence in immunodeficiency, chronic infection and cancer. BCG instilled into the bladder provokes a local immune reaction against superficial bladder cancer; levamisole, an anthelmintic, restores depressed T-cell function.', 'admin', 'published', 4, true, '[["bcg"], ["levamisole"], ["interferon", "interferons"], ["interleukin-2", "aldesleukin", "il-2"], ["filgrastim", "g-csf", "colony stimulating factors"], ["thalidomide", "lenalidomide"], ["imiquimod"], ["isoprinosine", "inosine pranobex", "thymosin"]]'::jsonb, 'saq p.097 PP2 Q6, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-ead7acae11', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'saq', 'What is the mechanism of action of ciclosporin (cyclosporine)?', '[]'::jsonb, 'Ciclosporin enters T lymphocytes and binds the cytoplasmic protein cyclophilin. The complex inhibits calcineurin, a calcium/calmodulin-dependent phosphatase, so the transcription factor NFAT is not dephosphorylated and cannot enter the nucleus. Transcription of interleukin-2 (and other cytokines) is blocked, preventing T-cell activation and proliferation.', '[]'::jsonb, 'Because it selectively blocks T-helper cell activation without suppressing the bone marrow, ciclosporin transformed transplantation. Tacrolimus inhibits calcineurin in the same way but binds FKBP-12 instead of cyclophilin. Nephrotoxicity and hypertension are the main adverse effects of both drugs.', 'admin', 'published', 3, true, '[["cyclophilin"], ["calcineurin", "calcineurin inhibitor"], ["nfat", "nfat transcription factor"], ["interleukin-2", "il-2", "cytokine transcription"], ["t-cell activation", "t lymphocytes", "t cells"]]'::jsonb, 'saq p.094 Q18, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-17ade7463b', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'saq', 'List 3 calcineurin inhibitors.', '[]'::jsonb, 'Ciclosporin (cyclosporine); tacrolimus (FK506); pimecrolimus (topical). Also voclosporin.', '[]'::jsonb, 'Ciclosporin binds cyclophilin and tacrolimus and pimecrolimus bind FKBP-12; each complex inhibits calcineurin and so interleukin-2 production. Sirolimus also binds FKBP-12 but inhibits mTOR, not calcineurin, so it is not a member of this group.', 'admin', 'published', 3, true, '[["ciclosporin", "cyclosporine", "cyclosporin"], ["tacrolimus", "fk506"], ["pimecrolimus", "voclosporin"]]'::jsonb, 'saq p.097 PP2 Q7, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-8272738ec3', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'saq', 'Write brief notes on the pharmacology of ciclosporin under: pharmacokinetics, adverse effects and indications.', '[]'::jsonb, 'Pharmacokinetics: oral absorption is incomplete and variable (20-50%; better with the microemulsion); highly lipid soluble, widely distributed and bound to red cells and lipoproteins; metabolised by hepatic CYP3A4 and excreted in bile, so levels rise with inhibitors (ketoconazole, erythromycin, grapefruit juice) and fall with inducers (rifampicin, phenytoin); narrow therapeutic index needing blood level monitoring. Adverse effects: nephrotoxicity (commonest), hypertension, hyperkalaemia, tremor and neurotoxicity, hirsutism, gum hyperplasia, hyperlipidaemia, hyperglycaemia, hepatotoxicity, infections and lymphoma. Indications: prevention of rejection in kidney, liver, heart and bone marrow transplantation; graft-versus-host disease; severe psoriasis, atopic dermatitis, rheumatoid arthritis, nephrotic syndrome, uveitis.', '[]'::jsonb, 'Nephrotoxicity, from afferent arteriolar constriction, is the dose-limiting effect and is hard to tell from kidney graft rejection. Unlike cytotoxic immunosuppressants, ciclosporin does not depress the bone marrow. CYP3A4 interactions are frequent and clinically important.', 'admin', 'published', 5, true, '[["variable absorption", "incomplete absorption"], ["cyp3a4", "hepatic metabolism", "biliary excretion"], ["drug interactions", "therapeutic drug monitoring", "blood levels"], ["nephrotoxicity"], ["hypertension", "hyperkalaemia"], ["hirsutism", "gum hyperplasia", "gingival hyperplasia", "tremor"], ["transplant rejection", "organ transplantation"], ["psoriasis", "rheumatoid arthritis", "nephrotic syndrome", "graft versus host"]]'::jsonb, 'saq p.098 PP3 Q7, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-a5d02733fd', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'saq', 'List 5 immunosuppressive agents.', '[]'::jsonb, 'Any 5 of: corticosteroids (prednisolone); ciclosporin; tacrolimus; sirolimus (rapamycin), everolimus; azathioprine; mycophenolate mofetil; methotrexate; cyclophosphamide; antilymphocyte or antithymocyte globulin; monoclonal antibodies (basiliximab, rituximab, infliximab); leflunomide.', '[]'::jsonb, 'They fall into groups: glucocorticoids, calcineurin inhibitors, mTOR inhibitors, antiproliferative antimetabolites and cytotoxics, and antibodies. Transplant regimens combine drugs from different groups so that lower, less toxic doses of each can be used.', 'admin', 'published', 5, true, '[["prednisolone", "corticosteroids", "glucocorticoids"], ["ciclosporin", "cyclosporine"], ["tacrolimus"], ["sirolimus", "everolimus", "rapamycin"], ["azathioprine"], ["mycophenolate", "mycophenolate mofetil"], ["methotrexate", "cyclophosphamide", "leflunomide"], ["antithymocyte globulin", "basiliximab", "rituximab", "monoclonal antibodies"]]'::jsonb, 'saq p.098 PP3 Q7a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-7c5022beb6', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'List 5 adverse effects of azathioprine.', '[]'::jsonb, 'Any 5 of: bone marrow suppression (leucopenia, thrombocytopenia, anaemia); increased susceptibility to infections; nausea, vomiting and diarrhoea; hepatotoxicity (cholestatic hepatitis); pancreatitis; hypersensitivity reactions (fever, rash, arthralgia); increased risk of malignancy (lymphoma, skin cancer); alopecia.', '[]'::jsonb, 'Azathioprine is converted to 6-mercaptopurine, which blocks purine synthesis in dividing cells, so the marrow is its main target. Toxicity is severe in people with low thiopurine methyltransferase (TPMT) activity and when allopurinol is co-prescribed, since xanthine oxidase inactivates 6-mercaptopurine.', 'admin', 'published', 5, true, '[["bone marrow suppression", "leucopenia", "leukopenia", "myelosuppression", "thrombocytopenia"], ["infections", "infection"], ["nausea", "vomiting", "gi upset"], ["hepatotoxicity", "hepatitis", "cholestasis"], ["pancreatitis"], ["hypersensitivity", "rash", "fever"], ["malignancy", "lymphoma", "skin cancer"], ["alopecia"]]'::jsonb, 'saq p.094 Q19, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-42e9f78d69', 'pharm-anticoagulant-drugs', 'saq', 'Compare and contrast low molecular weight heparin and standard (unfractionated) heparin.', '[]'::jsonb, 'Similarities: both act by binding antithrombin, are given parenterally, do not cross the placenta, and can cause bleeding. Differences: molecular weight - UFH 5,000-30,000 (mean 15,000), LMWH about 4,500; action - UFH inactivates thrombin (IIa) and factor Xa equally, LMWH mainly factor Xa; route - UFH intravenous or subcutaneous, LMWH subcutaneous; bioavailability and half-life - UFH low and variable with a short half-life, LMWH over 90% with a longer half-life allowing once or twice daily fixed dosing; monitoring - UFH needs aPTT, LMWH usually none (anti-Xa in renal failure, pregnancy, obesity); elimination - UFH reticuloendothelial, LMWH renal; protamine fully reverses UFH but only partly reverses LMWH; LMWH causes less heparin-induced thrombocytopenia and osteoporosis.', '[]'::jsonb, 'Shorter heparin chains still bind antithrombin through the pentasaccharide but are too short to bridge antithrombin to thrombin, so LMWH is selective for factor Xa. Its predictable kinetics allow weight-based dosing without monitoring, which is why it has largely replaced UFH.', 'admin', 'published', 5, true, '[["antithrombin"], ["molecular weight", "smaller molecule"], ["factor xa", "anti-xa", "thrombin", "iia"], ["subcutaneous", "intravenous"], ["bioavailability", "longer half-life", "once daily"], ["aptt", "monitoring", "no monitoring"], ["renal excretion", "renal failure"], ["protamine", "reversal"], ["thrombocytopenia", "hit", "osteoporosis"], ["enoxaparin", "dalteparin"]]'::jsonb, 'saq p.094 Q20, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-309994e9a2', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'List the 3 main protozoal infections for which metronidazole is indicated.', '[]'::jsonb, 'Amoebiasis (invasive intestinal disease and amoebic liver abscess due to Entamoeba histolytica); giardiasis (Giardia lamblia); trichomoniasis (Trichomonas vaginalis).', '[]'::jsonb, 'These protozoa are anaerobic or microaerophilic and reduce the nitro group of metronidazole to reactive intermediates that damage DNA. Metronidazole kills tissue trophozoites but not luminal cysts, so a luminal amoebicide is added in amoebiasis.', 'admin', 'published', 3, true, '[["amoebiasis", "amebiasis", "entamoeba histolytica", "amoebic liver abscess"], ["giardiasis", "giardia"], ["trichomoniasis", "trichomonas"]]'::jsonb, 'saq p.094 Q21, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-08d8a5aeb0', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Name 2 drugs used in the early (haemolymphatic) stage of African trypanosomiasis and 2 drugs effective in the CNS (late) stage of the disease.', '[]'::jsonb, 'Early stage: suramin (Trypanosoma brucei rhodesiense) and pentamidine (T. b. gambiense). CNS stage: melarsoprol (both subspecies, especially rhodesiense) and eflornithine, usually with nifurtimox (gambiense). Fexinidazole is a newer oral drug for both stages of gambiense disease.', '[]'::jsonb, 'Suramin and pentamidine do not cross the blood-brain barrier, so they work only before CNS invasion. Melarsoprol, an arsenical, does cross it but causes a reactive encephalopathy in up to 10% of patients; eflornithine is safer but is active only against T. b. gambiense.', 'admin', 'published', 4, true, '[["suramin"], ["pentamidine"], ["melarsoprol"], ["eflornithine", "nifurtimox", "fexinidazole"]]'::jsonb, 'saq p.094 Q22, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-cdcd6aaf5b', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'Eflornithine acts by irreversibly inhibiting which enzyme?', '[]'::jsonb, 'Ornithine decarboxylase', '["ODC", "ornithine decarboxylase enzyme"]'::jsonb, 'Eflornithine is a suicide inhibitor of ornithine decarboxylase, the first enzyme of polyamine synthesis; without polyamines trypanosomes cannot divide. Trypanosoma brucei gambiense turns the enzyme over slowly and so is susceptible. Topically the same action slows facial hair growth.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q23, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-ef8b93dbb4', 'pharm-anti-fungals', 'saq', 'Fluconazole inhibits which fungal enzyme?', '[]'::jsonb, 'Lanosterol 14-alpha-demethylase', '["14-alpha-demethylase", "14α-demethylase", "lanosterol demethylase", "CYP51", "fungal cytochrome P450", "14 alpha demethylase", "lanosterol 14α-demethylase", "cytochrome P450 14-alpha-demethylase"]'::jsonb, 'Azoles inhibit the fungal cytochrome P450 enzyme that converts lanosterol to ergosterol. Ergosterol is depleted and toxic methylated sterols accumulate, disrupting membrane function (fungistatic). Partial inhibition of human P450 enzymes explains azole drug interactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q24b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-942dc9d706', 'pharm-anti-fungals', 'saq', 'Terbinafine inhibits which fungal enzyme?', '[]'::jsonb, 'Squalene epoxidase', '["squalene monooxygenase", "squalene 2,3-epoxidase"]'::jsonb, 'Terbinafine, an allylamine, blocks squalene epoxidase, an early step in ergosterol synthesis. Squalene accumulates to toxic levels, making the drug fungicidal. It concentrates in keratin, so it is the drug of choice for dermatophyte infections of nails and skin.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.094 Q24c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-6b441c6db8', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'saq', 'Briefly and concisely describe the mechanism of action of halothane.', '[]'::jsonb, 'Halothane is a volatile general anaesthetic. It potentiates inhibitory GABA-A (and glycine) receptor chloride channels, activates two-pore-domain potassium channels (hyperpolarising neurones) and inhibits excitatory NMDA and nicotinic receptors, depressing synaptic transmission in the brain and spinal cord. Potency correlates with lipid solubility (Meyer-Overton rule).', '[]'::jsonb, 'No single receptor explains general anaesthesia. The older lipid theory, based on the correlation of potency with oil solubility, has given way to the view that anaesthetics bind hydrophobic pockets on ion-channel proteins, chiefly enhancing GABA-A and potassium channel function.', 'admin', 'draft', 2, true, '[["gaba-a", "gaba", "potentiates gaba"], ["glycine", "potassium channels", "k2p", "hyperpolarisation"], ["nmda", "nicotinic", "inhibits excitatory"], ["lipid solubility", "meyer-overton"]]'::jsonb, 'saq p.094 Q24e, JB revision SAQs. The mechanism of inhalational anaesthetics is incompletely understood; markers may expect either the lipid (Meyer-Overton) theory or the ion-channel (GABA-A) theory.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-12438ad900', 'pharm-aldosterone-oxytocin-vasopressin', 'saq', 'List 3 groups of drugs that stimulate uterine contraction, with an example of each.', '[]'::jsonb, '1. Posterior pituitary hormone and analogues: oxytocin, carbetocin. 2. Ergot alkaloids: ergometrine (ergonovine), methylergometrine. 3. Prostaglandins: misoprostol (PGE1), dinoprostone (PGE2), carboprost (15-methyl PGF2-alpha).', '[]'::jsonb, 'Oxytocin gives rhythmic contractions with relaxation between them, so it is used to induce and augment labour. Ergometrine causes sustained (tonic) contraction and is used only after delivery, for postpartum haemorrhage. Prostaglandins also ripen the cervix.', 'admin', 'published', 3, true, '[["oxytocin", "carbetocin"], ["ergot alkaloids", "ergometrine", "ergonovine", "methylergometrine"], ["prostaglandins", "misoprostol", "dinoprostone", "carboprost"]]'::jsonb, 'saq p.094 Q25, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-renal-pharmacology-dru-12de3d6f1d', 'pharm-introduction-to-renal-pharmacology-drugs-affecting-renal-water-c', 'saq', 'Give three antidiuretic peptides.', '[]'::jsonb, 'Any 3 of: vasopressin (arginine vasopressin, ADH); desmopressin (DDAVP); lypressin (lysine vasopressin); terlipressin; felypressin. (Oxytocin has weak antidiuretic activity.)', '[]'::jsonb, 'These peptides act on V2 receptors in the collecting duct, raising cAMP and inserting aquaporin-2 water channels. Desmopressin is V2 selective and long acting, so it treats cranial diabetes insipidus and enuresis without the V1-mediated vasoconstriction of vasopressin.', 'admin', 'published', 3, true, '[["vasopressin", "adh", "arginine vasopressin", "antidiuretic hormone"], ["desmopressin", "ddavp"], ["lypressin", "terlipressin", "felypressin", "oxytocin"]]'::jsonb, 'saq p.094 Q26, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-5629eda02f', 'pharm-sympathomimetics-methylxanthines', 'saq', 'Describe two mechanisms of action of methylxanthines as bronchodilators.', '[]'::jsonb, '1. Non-selective inhibition of phosphodiesterase (PDE3, PDE4), which raises intracellular cAMP (and cGMP) and relaxes bronchial smooth muscle. 2. Competitive antagonism of adenosine receptors (A1, A2B), preventing adenosine-induced bronchoconstriction and mediator release. (Also: activation of histone deacetylase with anti-inflammatory effect; improved diaphragmatic contractility.)', '[]'::jsonb, 'At therapeutic concentrations phosphodiesterase inhibition is modest, so adenosine antagonism probably contributes. Adenosine antagonism also explains the adverse effects of theophylline: tachycardia, diuresis, CNS stimulation and seizures. The narrow therapeutic range (10-20 mg/L) means plasma levels should be monitored.', 'admin', 'published', 2, true, '[["phosphodiesterase inhibition", "pde inhibition", "inhibit phosphodiesterase", "increase camp"], ["adenosine receptor antagonism", "adenosine antagonist", "block adenosine receptors"], ["histone deacetylase", "diaphragm contractility"]]'::jsonb, 'saq p.094 Q27, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-28b0442a49', 'pharm-emergency-management-of-poisoning', 'saq', 'Describe two modes of treatment of methanol poisoning.', '[]'::jsonb, 'Any 2 of: 1. inhibition of alcohol dehydrogenase to prevent formation of toxic formic acid - ethanol (competitive substrate) or fomepizole (4-methylpyrazole); 2. haemodialysis to remove methanol and formate and correct acidosis; 3. intravenous sodium bicarbonate to correct metabolic acidosis; 4. folinic acid (or folic acid) to enhance metabolism of formate to carbon dioxide and water.', '[]'::jsonb, 'Methanol itself is not very toxic; alcohol dehydrogenase converts it to formaldehyde and then formic acid, which causes metabolic acidosis and optic nerve damage. Ethanol has a much higher affinity for the enzyme and so blocks this lethal synthesis.', 'admin', 'published', 2, true, '[["ethanol", "fomepizole", "inhibit alcohol dehydrogenase", "alcohol dehydrogenase"], ["haemodialysis", "hemodialysis", "dialysis"], ["sodium bicarbonate", "correct acidosis"], ["folinic acid", "folic acid", "folate"]]'::jsonb, 'saq p.094 Q28, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-46c0ce032b', 'pharm-antidepressants-and-lithium', 'saq', 'List four indications of amitriptyline.', '[]'::jsonb, 'Any 4 of: major depression; neuropathic pain (diabetic neuropathy, post-herpetic neuralgia); migraine prophylaxis; chronic tension-type headache; nocturnal enuresis in children; fibromyalgia and other chronic pain; irritable bowel syndrome; insomnia associated with depression.', '[]'::jsonb, 'Amitriptyline blocks noradrenaline and serotonin reuptake, which enhances descending pain-inhibitory pathways, so low doses relieve neuropathic pain and prevent migraine independently of mood. Its antimuscarinic action underlies its use in enuresis.', 'admin', 'published', 4, true, '[["depression"], ["neuropathic pain", "post-herpetic neuralgia", "diabetic neuropathy", "chronic pain"], ["migraine prophylaxis", "migraine"], ["nocturnal enuresis", "enuresis", "bedwetting"], ["tension headache", "fibromyalgia", "irritable bowel syndrome", "insomnia"]]'::jsonb, 'saq p.094 Q30, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-72b484cf46', 'pharm-anti-retrovirals', 'saq', 'Explain the mechanism of the following toxic effects: zidovudine and anaemia; stavudine and peripheral neuropathy; nevirapine-induced hepatitis; abacavir-induced rash.', '[]'::jsonb, 'Zidovudine anaemia: inhibition of DNA synthesis and of mitochondrial DNA polymerase gamma in erythroid precursors causes bone marrow suppression with macrocytic anaemia. Stavudine neuropathy: mitochondrial toxicity - inhibition of mitochondrial DNA polymerase gamma depletes mitochondrial DNA in neurones, causing axonal degeneration. Nevirapine hepatitis: immune-mediated hypersensitivity reaction (often with rash, fever and eosinophilia) in the first weeks, commoner in women and with higher CD4 counts. Abacavir rash: T-cell-mediated hypersensitivity in carriers of HLA-B*57:01, in whom abacavir alters peptide presentation and activates CD8 T cells.', '[]'::jsonb, 'Two mechanisms run through antiretroviral toxicity: off-target inhibition of host DNA polymerases by NRTIs, and immune hypersensitivity to NNRTIs and abacavir. The immune reactions occur early, are genetically determined and are dangerous on rechallenge.', 'admin', 'published', 4, true, '[["bone marrow suppression", "erythroid precursors", "inhibits dna synthesis", "marrow toxicity"], ["mitochondrial toxicity", "polymerase gamma", "mitochondrial dna"], ["hypersensitivity", "immune-mediated", "immune mediated"], ["high cd4", "women"], ["hla-b*5701", "hla-b*57:01", "hla b5701"]]'::jsonb, 'saq p.094 Q31, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-6f8280a881', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'saq', 'Indicate the mechanism of action of alpha-methyldopa in the treatment of hypertension.', '[]'::jsonb, 'Methyldopa is a prodrug taken up by central adrenergic neurones and converted to alpha-methylnoradrenaline, a false transmitter that stimulates alpha-2 adrenoceptors in the brainstem (nucleus tractus solitarius/vasomotor centre). This reduces sympathetic outflow, lowering peripheral vascular resistance and blood pressure.', '[]'::jsonb, 'It was once thought to work by inhibiting DOPA decarboxylase, but the central alpha-2 agonist action of its metabolite is what matters. It remains a drug of choice for hypertension in pregnancy; adverse effects include sedation, a positive Coombs test and hepatitis.', 'admin', 'published', 2, true, '[["alpha-methylnoradrenaline", "alpha-methylnorepinephrine", "false transmitter", "prodrug"], ["alpha-2 agonist", "central alpha-2 receptors", "alpha 2"], ["reduces sympathetic outflow", "decreased sympathetic outflow", "central"], ["reduced peripheral resistance", "lowers blood pressure"]]'::jsonb, 'saq p.095 Q32, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-aa774682c2', 'pharm-calcium-channel-blocker', 'saq', 'What are the adverse effects of nifedipine?', '[]'::jsonb, 'Any 4 of: headache; flushing; dizziness and hypotension; reflex tachycardia and palpitations (may worsen angina with short-acting forms); ankle (peripheral) oedema; gingival hyperplasia; constipation; fatigue.', '[]'::jsonb, 'Dihydropyridines dilate arterioles, so their adverse effects are those of vasodilatation. Ankle oedema results from precapillary dilatation raising capillary pressure, not from fluid retention, so it does not respond to diuretics. Short-acting nifedipine is avoided in acute coronary syndromes.', 'admin', 'published', 4, true, '[["headache"], ["flushing"], ["hypotension", "dizziness"], ["reflex tachycardia", "palpitations", "tachycardia"], ["ankle oedema", "peripheral oedema", "ankle edema", "pedal oedema"], ["gingival hyperplasia", "gum hypertrophy"], ["constipation"]]'::jsonb, 'saq p.095 Q33, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-fe843fd728', 'pharm-time-course-of-drug-action', 'saq', 'Write short notes on the half-life of a drug.', '[]'::jsonb, 'The (elimination) half-life is the time taken for the plasma concentration, or the amount of drug in the body, to fall by half. For first-order kinetics it is constant and equals 0.693 x Vd / clearance. It determines the dosing interval, the time to reach steady state (4 to 5 half-lives) and the time for a drug to be eliminated after stopping.', '[]'::jsonb, 'Half-life is a derived value that rises if the volume of distribution increases or clearance falls. With zero-order (saturation) kinetics, as with phenytoin or alcohol, a constant amount rather than a constant fraction is removed, so no single half-life applies.', 'admin', 'published', 2, true, '[["concentration falls by half", "plasma concentration halves", "50%", "fall by half"], ["0.693", "volume of distribution", "clearance"], ["steady state", "4 to 5 half-lives", "dosing interval"]]'::jsonb, 'saq p.095 Q34a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-2017a5a676', 'pharm-transport-and-distribution', 'saq', 'Write short notes on the volume of distribution of a drug.', '[]'::jsonb, 'The apparent volume of distribution (Vd) is the theoretical volume of fluid that would be needed to contain the total amount of drug in the body at the same concentration as in plasma: Vd = amount of drug in body / plasma concentration. A small Vd means the drug is confined to plasma (highly protein bound or large, e.g. heparin, warfarin); a large Vd means extensive tissue binding (e.g. digoxin, chloroquine). It is used to calculate the loading dose (loading dose = Vd x target concentration).', '[]'::jsonb, 'Vd is not a real space and can greatly exceed body water. Drugs with a large Vd are not removed effectively by haemodialysis and need a loading dose to reach therapeutic levels quickly.', 'admin', 'published', 2, true, '[["apparent volume", "theoretical volume", "hypothetical volume"], ["amount divided by concentration", "dose/concentration", "amount/concentration"], ["tissue binding", "protein binding", "plasma"], ["loading dose"]]'::jsonb, 'saq p.095 Q34b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-91e6bad1c9', 'pharm-absorption', 'saq', 'List 5 factors affecting drug absorption.', '[]'::jsonb, 'Any 5 of: lipid solubility of the drug; degree of ionisation (pKa of the drug and pH at the site); molecular size; dosage form and formulation (disintegration and dissolution rate); route of administration; surface area of the absorbing surface; blood flow to the site; gastric emptying and gut motility; presence of food or other drugs (chelation, pH changes); first-pass metabolism and efflux transporters (P-glycoprotein); gut disease (malabsorption); concentration of the drug.', '[]'::jsonb, 'Most drugs cross membranes by passive diffusion of the un-ionised, lipid-soluble form, so drug properties and local pH matter; the small intestine dominates absorption because of its huge surface area and blood flow, which is why gastric emptying controls the rate.', 'admin', 'published', 5, true, '[["lipid solubility", "lipophilicity"], ["ionisation", "pka", "ph"], ["molecular size", "molecular weight"], ["formulation", "dosage form", "dissolution"], ["route of administration"], ["surface area"], ["blood flow"], ["gastric emptying", "gut motility"], ["food", "other drugs"], ["first-pass metabolism", "p-glycoprotein"], ["disease", "malabsorption"], ["concentration"]]'::jsonb, 'saq p.095 Q34c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-d253fbe1e7', 'pharm-anticoagulant-drugs', 'saq', 'A patient presents with deep venous thrombosis. Give 2 anticoagulants indicated in the initial management.', '[]'::jsonb, 'A heparin - low molecular weight heparin (e.g. enoxaparin) or unfractionated heparin - started immediately, together with warfarin (overlapped for at least 5 days until the INR is 2 to 3). Alternatives: fondaparinux, or a direct oral anticoagulant such as rivaroxaban or apixaban.', '[]'::jsonb, 'Heparin acts at once, whereas warfarin takes several days because existing clotting factors must first decay, and it initially lowers protein C, creating a brief prothrombotic state. Hence the overlap. Rivaroxaban and apixaban act quickly enough to be used alone.', 'admin', 'published', 2, true, '[["heparin", "unfractionated heparin", "low molecular weight heparin", "enoxaparin", "dalteparin", "fondaparinux"], ["warfarin", "rivaroxaban", "apixaban", "dabigatran"]]'::jsonb, 'saq p.095 Q35(i), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-456c7bd326', 'pharm-anticoagulant-drugs', 'saq', 'Describe the mechanisms of action of heparin and of warfarin.', '[]'::jsonb, 'Heparin: binds antithrombin (III) through a specific pentasaccharide sequence and accelerates about 1000-fold its inactivation of thrombin (IIa) and factor Xa (also IXa, XIa, XIIa); low molecular weight heparins mainly inhibit factor Xa; action is immediate, in vivo and in vitro. Warfarin: inhibits vitamin K epoxide reductase (VKORC1), preventing regeneration of reduced vitamin K, so the gamma-carboxylation of clotting factors II, VII, IX and X (and proteins C and S) fails; action is delayed 2 to 3 days and occurs only in vivo.', '[]'::jsonb, 'Heparin is an indirect inhibitor that needs antithrombin as a cofactor and acts on circulating active factors; warfarin stops the liver making functional factors, so its effect appears only as existing ones are cleared, with factor VII (half-life 6 hours) falling first.', 'admin', 'published', 4, true, '[["antithrombin", "antithrombin iii"], ["thrombin", "factor xa", "iia"], ["vitamin k epoxide reductase", "vkorc1", "vitamin k antagonist"], ["ii, vii, ix, x", "clotting factors", "gamma-carboxylation", "vitamin k dependent factors"], ["delayed onset", "immediate onset"]]'::jsonb, 'saq p.095 Q35(ii), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-digestants-and-drugs-used-to-dissolve--d7b3ea9ab5', 'pharm-digestants-and-drugs-used-to-dissolve-gallstones-bile-acids', 'saq', 'Give the proposed mechanism of action of ursodiol (ursodeoxycholic acid).', '[]'::jsonb, 'Ursodiol is a hydrophilic bile acid that reduces hepatic secretion of cholesterol into bile (and its intestinal absorption), so bile becomes unsaturated with cholesterol and small cholesterol gallstones gradually dissolve. It also replaces toxic hydrophobic bile acids in the bile acid pool, stimulates bile flow, and has cytoprotective and immunomodulatory effects on hepatocytes and cholangiocytes (used in primary biliary cholangitis).', '[]'::jsonb, 'Only small, radiolucent cholesterol stones in a functioning gallbladder dissolve, and treatment takes months with frequent recurrence. In primary biliary cholangitis ursodiol slows progression by displacing detergent bile acids that damage bile-duct cells.', 'admin', 'published', 2, true, '[["reduces cholesterol secretion", "decreases cholesterol in bile", "reduces cholesterol saturation", "desaturates bile"], ["dissolves cholesterol gallstones", "gallstone dissolution"], ["replaces toxic bile acids", "hydrophilic bile acid", "cytoprotective", "increases bile flow", "choleretic"]]'::jsonb, 'saq p.095 Q36, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-fd834366a3', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'saq', 'Describe the mechanism of action of proton pump inhibitors.', '[]'::jsonb, 'Proton pump inhibitors (e.g. omeprazole) are weak-base prodrugs. After absorption they diffuse into the parietal cell and are trapped and activated in the acidic secretory canaliculus to a sulphenamide, which binds covalently (disulphide bond with cysteine residues) to the H+/K+-ATPase. This irreversibly inhibits the proton pump, the final common step of acid secretion, suppressing basal and stimulated acid secretion until new pumps are synthesised (about 24 hours or more).', '[]'::jsonb, 'Because the pump is the last step, these drugs block secretion however it is stimulated (histamine, gastrin or acetylcholine), making them more effective than H2 blockers. Irreversible binding explains why a drug with a one-hour half-life works for a day; they are given before a meal, when pumps are active.', 'admin', 'published', 3, true, '[["prodrug", "activated in acid", "sulphenamide", "sulfenamide"], ["h+/k+ atpase", "proton pump", "hydrogen potassium atpase"], ["irreversible", "covalent", "disulphide bond"], ["parietal cell", "canaliculus"], ["final common step", "final step", "suppress acid secretion"]]'::jsonb, 'saq p.095 Q37, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-7ab4bc08bb', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'saq', 'Name two types of pancreatic enzyme supplements and give 2 of their adverse effects.', '[]'::jsonb, 'Supplements: pancreatin and pancrelipase (lipase, amylase and protease from pig pancreas; available as enteric-coated microspheres, e.g. Creon). Adverse effects (any 2): nausea, abdominal discomfort and diarrhoea; hyperuricaemia and hyperuricosuria (high purine content); fibrosing colonopathy with high doses in children with cystic fibrosis; perioral and perianal irritation; hypersensitivity reactions.', '[]'::jsonb, 'The enzymes are destroyed by gastric acid, hence enteric coating or co-prescription of acid suppression. They are taken with meals in chronic pancreatitis and cystic fibrosis. Very high lipase doses have caused colonic strictures in children.', 'admin', 'published', 4, true, '[["pancreatin"], ["pancrelipase", "creon"], ["nausea", "diarrhoea", "abdominal discomfort", "abdominal pain"], ["hyperuricaemia", "hyperuricosuria", "hyperuricemia"], ["fibrosing colonopathy"], ["perianal irritation", "mouth irritation", "hypersensitivity", "allergy"]]'::jsonb, 'saq p.095 Q39, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-e95cb80965', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'saq', 'List 4 mechanisms of resistance to antibacterial drugs and give examples of antibacterial drugs affected by each mechanism.', '[]'::jsonb, '1. Enzymatic inactivation of the drug: beta-lactamases (penicillins, cephalosporins), aminoglycoside-modifying enzymes, chloramphenicol acetyltransferase. 2. Alteration of the drug target: altered penicillin-binding proteins (MRSA, pneumococci), ribosomal methylation (macrolides), mutant DNA gyrase (fluoroquinolones), altered RNA polymerase (rifampicin), D-Ala-D-Lac (vancomycin). 3. Reduced permeability: loss of porins (carbapenems, aminoglycosides in Gram-negatives). 4. Active efflux pumps: tetracyclines, macrolides, fluoroquinolones. 5. Bypass or alternative metabolic pathway: sulphonamides and trimethoprim (resistant dihydropteroate synthase or dihydrofolate reductase).', '[]'::jsonb, 'Resistance genes arise by mutation or are acquired on plasmids and transposons by conjugation, transduction or transformation. One organism often combines several mechanisms, and a single efflux pump or porin change can affect several antibiotic classes at once.', 'admin', 'published', 4, true, '[["enzymatic inactivation", "beta-lactamase", "drug inactivation", "modifying enzymes"], ["altered target", "target modification", "altered penicillin-binding proteins", "mrsa", "dna gyrase"], ["reduced permeability", "porins", "decreased uptake"], ["efflux pumps", "efflux", "tetracyclines"], ["bypass pathway", "alternative pathway", "sulphonamides", "trimethoprim"]]'::jsonb, 'saq p.095 Q40, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-2bc0e4366e', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'List 3 cardiac, 3 gastrointestinal and 3 CNS manifestations of digitalis toxicity.', '[]'::jsonb, 'Cardiac: ventricular ectopics and bigeminy; ventricular tachycardia or fibrillation; AV block and bradycardia; paroxysmal atrial tachycardia with block. Gastrointestinal: anorexia; nausea and vomiting; diarrhoea; abdominal pain. CNS: confusion, delirium; headache, fatigue and drowsiness; visual disturbances - blurred vision, yellow-green vision (xanthopsia), haloes.', '[]'::jsonb, 'Toxicity combines increased automaticity (delayed after-depolarisations from calcium overload) with vagal slowing of AV conduction, so almost any arrhythmia can occur. Hypokalaemia, hypomagnesaemia, hypercalcaemia, renal impairment and old age all predispose.', 'admin', 'published', 6, true, '[["ventricular ectopics", "bigeminy", "extrasystoles"], ["ventricular tachycardia", "ventricular fibrillation", "arrhythmias"], ["heart block", "av block", "bradycardia"], ["anorexia"], ["nausea", "vomiting"], ["diarrhoea", "abdominal pain"], ["confusion", "delirium"], ["headache", "fatigue", "drowsiness"], ["xanthopsia", "yellow vision", "visual disturbance", "blurred vision"]]'::jsonb, 'saq p.095 Q41, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-771fa27a4a', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'Discuss the pharmacodynamics of milrinone.', '[]'::jsonb, 'Milrinone is a bipyridine that selectively inhibits phosphodiesterase type 3 in cardiac and vascular smooth muscle, raising cAMP. In the heart this increases calcium entry and contractility (positive inotropy) and speeds relaxation (lusitropy); in vessels it causes arterial and venous dilatation, reducing preload and afterload (''inodilator''). Cardiac output rises without much increase in oxygen demand. It is used intravenously, short term, in acute or refractory heart failure; adverse effects are arrhythmias, hypotension and (less than amrinone) thrombocytopenia; long-term use increases mortality.', '[]'::jsonb, 'Because it acts beyond the beta receptor, milrinone still works in patients on beta-blockers or with down-regulated receptors. The rise in cAMP is also arrhythmogenic, which explains the excess mortality seen with long-term oral treatment.', 'admin', 'published', 3, true, '[["phosphodiesterase 3", "pde3 inhibitor", "pde-3", "phosphodiesterase inhibitor"], ["increases camp", "camp"], ["positive inotropy", "increased contractility", "inotropic"], ["vasodilation", "vasodilatation", "inodilator", "reduces afterload"], ["acute heart failure", "short-term"], ["arrhythmias", "hypotension"]]'::jsonb, 'saq p.095 Q42, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-af82a5b755', 'pharm-alkylating-agents', 'saq', 'Classify alkylating agents and give examples of drugs in each class.', '[]'::jsonb, '1. Nitrogen mustards: cyclophosphamide, ifosfamide, chlorambucil, melphalan, mechlorethamine (mustine). 2. Nitrosoureas: carmustine (BCNU), lomustine (CCNU), streptozocin. 3. Alkyl sulphonates: busulfan. 4. Triazenes and related: dacarbazine, temozolomide, procarbazine. 5. Ethylenimines (aziridines): thiotepa. 6. Platinum compounds (alkylating-like): cisplatin, carboplatin, oxaliplatin.', '[]'::jsonb, 'All form reactive intermediates that alkylate DNA, chiefly at the N7 of guanine, cross-linking strands and blocking replication; they are cell cycle non-specific. Nitrosoureas are lipid soluble and cross the blood-brain barrier, hence their use in brain tumours.', 'admin', 'published', 5, true, '[["nitrogen mustards", "cyclophosphamide", "ifosfamide", "chlorambucil", "melphalan", "mechlorethamine"], ["nitrosoureas", "carmustine", "lomustine", "streptozocin"], ["alkyl sulphonates", "alkyl sulfonates", "busulfan", "busulphan"], ["triazenes", "dacarbazine", "temozolomide", "procarbazine"], ["ethylenimines", "thiotepa"], ["platinum", "cisplatin", "carboplatin"]]'::jsonb, 'saq p.095 Q43, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-0832a39474', 'pharm-oral-antidiabetic-drugs', 'saq', 'Classify oral hypoglycaemic agents, giving 2 examples and the mechanism of action for each class.', '[]'::jsonb, '1. Sulphonylureas (glibenclamide, gliclazide, glimepiride): close beta-cell K-ATP channels, stimulating insulin secretion. 2. Meglitinides (repaglinide, nateglinide): same mechanism, rapid and short acting. 3. Biguanides (metformin): activate AMP-kinase, reduce hepatic gluconeogenesis and increase peripheral glucose uptake. 4. Thiazolidinediones (pioglitazone, rosiglitazone): PPAR-gamma agonists that increase insulin sensitivity in fat and muscle. 5. Alpha-glucosidase inhibitors (acarbose, miglitol): delay intestinal carbohydrate digestion and absorption. 6. DPP-4 inhibitors (sitagliptin, vildagliptin): prevent breakdown of the incretins GLP-1 and GIP. 7. SGLT2 inhibitors (dapagliflozin, empagliflozin): block renal glucose reabsorption, causing glycosuria.', '[]'::jsonb, 'The classes can be grouped as insulin secretagogues (sulphonylureas, meglitinides, gliptins), insulin sensitisers (metformin, glitazones) and drugs that limit glucose entry or increase its loss (acarbose, SGLT2 inhibitors). Only the first two classes commonly cause hypoglycaemia.', 'admin', 'published', 5, true, '[["sulphonylureas", "sulfonylureas", "glibenclamide", "gliclazide", "glimepiride"], ["meglitinides", "repaglinide", "nateglinide"], ["biguanides", "metformin"], ["thiazolidinediones", "pioglitazone", "rosiglitazone", "ppar-gamma"], ["alpha-glucosidase inhibitors", "acarbose", "miglitol"], ["dpp-4 inhibitors", "sitagliptin", "vildagliptin", "gliptins"], ["sglt2 inhibitors", "dapagliflozin", "empagliflozin"]]'::jsonb, 'saq p.095 Q44, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-a1f141a89c', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'saq', 'List the advantages and disadvantages of the oral route of drug administration.', '[]'::jsonb, 'Advantages: safe, convenient and painless; self-administered; cheap; needs no sterile preparation; absorption can be prolonged with modified-release forms; overdose may be retrieved (lavage, charcoal). Disadvantages: slow onset, unsuitable for emergencies; variable and incomplete absorption (food, other drugs, gut disease); first-pass metabolism; destruction of some drugs by acid or enzymes (insulin, benzylpenicillin); gastric irritation, nausea and vomiting; needs a conscious, cooperative patient who can swallow; unsuitable in vomiting or diarrhoea.', '[]'::jsonb, 'The oral route is the commonest because it is the easiest and safest, but the drug must survive gastric acid, gut enzymes and the liver before reaching the circulation, so bioavailability is the main limitation and varies between patients.', 'admin', 'published', 4, true, '[["convenient", "safe", "painless"], ["self-administration", "cheap", "economical", "no sterility needed"], ["slow onset", "not for emergencies"], ["first-pass metabolism", "variable absorption", "incomplete absorption"], ["destroyed by acid", "destroyed by enzymes", "gastric irritation"], ["unconscious", "vomiting", "uncooperative patient", "cooperation"]]'::jsonb, 'saq p.095 Q46, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-ecd57801ce', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'Write down the pharmacokinetics of aspirin.', '[]'::jsonb, 'Absorption: a weak acid (pKa 3.5) absorbed rapidly from the stomach and mainly the upper small intestine. Metabolism: rapidly hydrolysed by esterases in the gut wall, plasma and liver to salicylic acid (aspirin half-life about 15-20 minutes). Distribution: salicylate is 80-90% bound to albumin and crosses the placenta and blood-brain barrier. Elimination: salicylate is conjugated in the liver with glycine (salicyluric acid) and glucuronic acid; these pathways saturate, so at high doses elimination becomes zero order and the half-life lengthens from 2-4 hours to 15-30 hours. Excretion is renal and is increased by alkalinising the urine.', '[]'::jsonb, 'Saturation of conjugation means that small dose increases at anti-inflammatory doses cause disproportionate rises in salicylate. In overdose, urinary alkalinisation traps the ionised salicylate in the tubule and greatly speeds its excretion.', 'admin', 'published', 4, true, '[["weak acid", "absorbed in stomach", "rapid absorption", "small intestine"], ["hydrolysed to salicylate", "esterases", "salicylic acid"], ["protein bound", "albumin"], ["glycine conjugation", "glucuronidation", "salicyluric acid", "hepatic conjugation"], ["saturable", "zero-order kinetics", "dose-dependent half-life"], ["renal excretion", "alkaline urine", "urinary alkalinisation"]]'::jsonb, 'saq p.095 Q47, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-fe972d6e11', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Give 5 drugs used in the treatment of myoclonic seizures.', '[]'::jsonb, 'Any 5 of: sodium valproate (first choice); clonazepam; levetiracetam; topiramate; zonisamide; lamotrigine (may occasionally worsen myoclonus); piracetam; phenobarbital or primidone.', '[]'::jsonb, 'Broad-spectrum antiepileptics are needed for myoclonic seizures. Narrow-spectrum sodium channel blockers and GABA-ergic drugs such as carbamazepine, phenytoin, vigabatrin and gabapentin can make myoclonic and absence seizures worse and are avoided.', 'admin', 'published', 5, true, '[["valproate", "sodium valproate", "valproic acid"], ["clonazepam"], ["levetiracetam"], ["topiramate"], ["zonisamide"], ["lamotrigine"], ["piracetam", "phenobarbital", "primidone"]]'::jsonb, 'saq p.095 Q49, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-e75cdb1108', 'pharm-sympathomimetics-methylxanthines', 'saq', 'Give 3 examples of drug interactions of theophylline.', '[]'::jsonb, 'Any 3 of: enzyme inhibitors raise theophylline levels and cause toxicity - erythromycin, clarithromycin, ciprofloxacin, cimetidine, allopurinol, fluvoxamine, oral contraceptives; enzyme inducers lower its levels - rifampicin, phenytoin, carbamazepine, phenobarbital, tobacco smoking; beta-2 agonists, corticosteroids and diuretics add to hypokalaemia; it antagonises adenosine and reduces the effect of benzodiazepines; increased risk of seizures with quinolones.', '[]'::jsonb, 'Theophylline is metabolised by CYP1A2 and has a narrow therapeutic range (10-20 mg/L), so modest changes in clearance cause arrhythmias and seizures or loss of effect. Smokers need higher doses, and doses must be reduced when a macrolide or ciprofloxacin is started.', 'admin', 'published', 3, true, '[["erythromycin", "clarithromycin", "macrolides"], ["ciprofloxacin", "quinolones"], ["cimetidine", "allopurinol", "fluvoxamine", "oral contraceptives"], ["rifampicin", "phenytoin", "carbamazepine", "phenobarbital", "smoking"], ["hypokalaemia", "beta-2 agonists"], ["adenosine", "benzodiazepines"]]'::jsonb, 'saq p.095 Q50, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-c0fc2022f0', 'pharm-intravenous-fluids', 'saq', 'Give 3 adverse effects (complications) of parenteral nutrition.', '[]'::jsonb, 'Any 3 of: catheter-related sepsis; catheter insertion complications (pneumothorax, thrombosis, air embolism); hyperglycaemia (or rebound hypoglycaemia on stopping); electrolyte disturbances and refeeding syndrome (hypophosphataemia, hypokalaemia, hypomagnesaemia); fluid overload; hypertriglyceridaemia; liver dysfunction (fatty liver, cholestasis); thrombophlebitis with peripheral infusion; trace element and vitamin deficiencies; gut mucosal atrophy.', '[]'::jsonb, 'Complications are mechanical (the central line), infective and metabolic. Hypertonic glucose solutions favour hyperglycaemia and line infection, and refeeding a starved patient drives phosphate, potassium and magnesium into cells, which can be fatal.', 'admin', 'published', 3, true, '[["sepsis", "infection", "catheter infection"], ["hyperglycaemia", "hyperglycemia", "hypoglycaemia"], ["refeeding syndrome", "hypophosphataemia", "electrolyte imbalance", "electrolyte disturbance"], ["fluid overload"], ["liver dysfunction", "cholestasis", "fatty liver", "hepatic steatosis"], ["thrombophlebitis", "thrombosis", "pneumothorax"], ["hypertriglyceridaemia", "hyperlipidaemia"]]'::jsonb, 'saq p.095 Q51, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-d3e35ec8d3', 'pharm-oral-antidiabetic-drugs', 'saq', 'Classify the sulphonylureas, giving 2 examples in each category.', '[]'::jsonb, 'First generation: tolbutamide, chlorpropamide (also tolazamide, acetohexamide). Second generation: glibenclamide (glyburide), gliclazide, glipizide, glimepiride (sometimes called third generation).', '[]'::jsonb, 'Second-generation drugs are about 100 times more potent and have fewer drug interactions. Chlorpropamide has a very long half-life, causing prolonged hypoglycaemia in the elderly, alcohol-induced flushing and hyponatraemia; tolbutamide is the shortest acting.', 'admin', 'published', 4, true, '[["first generation"], ["tolbutamide", "chlorpropamide", "tolazamide", "acetohexamide"], ["second generation"], ["glibenclamide", "glyburide", "gliclazide", "glipizide", "glimepiride"]]'::jsonb, 'saq p.095 Q52a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-fbdff447d9', 'pharm-oral-antidiabetic-drugs', 'saq', 'List the contraindications of the sulphonylureas.', '[]'::jsonb, 'Any 3 of: type 1 diabetes mellitus and diabetic ketoacidosis; pregnancy and breastfeeding; severe hepatic impairment; severe renal impairment; known hypersensitivity to sulphonylureas or sulphonamides; major surgery, severe infection or trauma (insulin needed); acute porphyria.', '[]'::jsonb, 'Sulphonylureas need working beta cells, so they are useless in type 1 diabetes. They are cleared by the liver and kidneys, and accumulation in organ failure or old age causes prolonged hypoglycaemia; insulin is used instead in pregnancy and during severe stress.', 'admin', 'published', 3, true, '[["type 1 diabetes", "ketoacidosis", "dka"], ["pregnancy", "breastfeeding", "lactation"], ["hepatic impairment", "liver disease"], ["renal impairment", "renal failure"], ["sulphonamide allergy", "sulfa allergy", "hypersensitivity"], ["surgery", "severe infection", "porphyria"]]'::jsonb, 'saq p.095 Q52b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-1fd85cc67a', 'pharm-oral-antidiabetic-drugs', 'saq', 'What is the definitive treatment of sulphonylurea-induced hypoglycaemia?', '[]'::jsonb, 'Glucose: orally (sugary drink or glucose) if the patient is conscious and able to swallow; intravenous dextrose (e.g. 25-50 ml of 50%, or 10-20% solution) if unconscious, followed by a glucose infusion and monitoring for 24-48 hours because the hypoglycaemia recurs. Intramuscular glucagon if there is no venous access; octreotide for refractory cases (inhibits insulin release).', '[]'::jsonb, 'Sulphonylurea hypoglycaemia is prolonged and relapsing because the drug goes on releasing insulin, and a glucose bolus itself stimulates further insulin release. Hence admission and infusion, and the use of octreotide, which blocks insulin secretion.', 'admin', 'published', 2, true, '[["glucose", "dextrose", "oral glucose", "sugar"], ["intravenous dextrose", "iv glucose", "50% dextrose", "10% dextrose"], ["glucagon", "octreotide"], ["prolonged monitoring", "infusion", "recurrence"]]'::jsonb, 'saq p.095 Q52c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-05c060b94e', 'pharm-oral-antidiabetic-drugs', 'saq', 'Define secondary failure of sulphonylurea therapy and give 2 reasons why it occurs.', '[]'::jsonb, 'Secondary failure is the loss of glycaemic control in a patient who initially responded well to a sulphonylurea (usually for at least 6 months) despite continued treatment at full dose. Reasons (any 2): progressive decline in beta-cell function (natural history of type 2 diabetes); poor adherence to diet or drugs; weight gain and increasing insulin resistance; intercurrent illness or stress; drugs that raise glucose (corticosteroids, thiazides); desensitisation of the beta cell to the drug. (Primary failure is no response from the start.)', '[]'::jsonb, 'Type 2 diabetes is progressive: beta-cell mass and function decline year by year, so about 5 to 10% of patients per year stop responding to secretagogues and need added drugs or insulin.', 'admin', 'published', 3, true, '[["initial response then failure", "loss of glycaemic control", "previously responded"], ["beta-cell failure", "progressive beta cell failure", "beta cell exhaustion"], ["non-compliance", "poor adherence", "diet"], ["weight gain", "insulin resistance"], ["intercurrent illness", "stress", "drugs", "corticosteroids"]]'::jsonb, 'saq p.095 Q52d, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-5006d2f5d5', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'Regarding thioamides in hyperthyroidism: briefly describe the titration regimen, how treatment is monitored, and when the euthyroid state is expected in most patients.', '[]'::jsonb, 'Titration regimen: start at a high dose (carbimazole 20-40 mg daily, or methimazole 15-40 mg, or propylthiouracil 300-450 mg daily in divided doses); once euthyroid, reduce stepwise to the lowest maintenance dose that keeps the patient euthyroid (carbimazole 5-15 mg daily) and continue for 12-18 months. (Alternative: block-and-replace with added levothyroxine.) Monitoring: clinical response (pulse, weight, symptoms) and free T4 (and T3) every 4-6 weeks, then every 2-3 months; TSH stays suppressed for weeks to months and is useful later; white cell count if sore throat or fever (agranulocytosis); liver function. Euthyroid state: usually within 4-8 weeks.', '[]'::jsonb, 'Thioamides stop new hormone synthesis but do not affect hormone already stored in the gland, so improvement waits until stores are used up, usually four to eight weeks. A beta-blocker covers the symptoms in the meantime.', 'admin', 'draft', 4, true, '[["high initial dose", "carbimazole 20-40 mg", "start high"], ["reduce dose", "maintenance dose", "titrate down", "block and replace"], ["12-18 months"], ["free t4", "thyroid function tests", "t3", "tsh"], ["clinical", "pulse", "weight"], ["white cell count", "agranulocytosis", "sore throat"], ["4-8 weeks", "6-8 weeks", "4 to 8 weeks"]]'::jsonb, 'saq p.095 Q54, JB revision SAQs. Doses and intervals vary between guidelines and textbooks.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-179844edaa', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'Discuss the differences between the pharmacokinetics of methimazole and propylthiouracil.', '[]'::jsonb, 'Propylthiouracil: rapidly absorbed, bioavailability 50-80%; about 80-90% protein bound; short plasma half-life (about 1.5 hours), so given every 6-8 hours; crosses the placenta and enters breast milk less; also inhibits peripheral conversion of T4 to T3. Methimazole (active metabolite of carbimazole): completely absorbed; hardly protein bound; half-life about 6 hours, and it accumulates in the thyroid with a long duration of action, so it is given once daily; about ten times more potent; crosses the placenta and enters breast milk more readily; does not inhibit peripheral conversion.', '[]'::jsonb, 'High protein binding limits placental transfer of propylthiouracil, so it is preferred in the first trimester (methimazole is associated with aplasia cutis and embryopathy); otherwise methimazole or carbimazole is preferred because of once-daily dosing and less hepatotoxicity.', 'admin', 'published', 3, true, '[["half-life", "1.5 hours", "6 hours"], ["once daily", "every 6-8 hours", "dosing frequency"], ["protein binding", "protein bound"], ["placenta", "breast milk"], ["potency", "ten times more potent"], ["peripheral conversion", "t4 to t3"]]'::jsonb, 'saq p.098 PP3 Q9, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-464df100ed', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'saq', 'List 4 drugs used in chemoprophylaxis of malaria and the groups of people who should use prophylaxis.', '[]'::jsonb, 'Drugs (any 4): mefloquine (weekly); atovaquone-proguanil (daily); doxycycline (daily); proguanil; chloroquine (only where parasites are sensitive); primaquine or tafenoquine; sulfadoxine-pyrimethamine (intermittent preventive treatment in pregnancy). People: non-immune travellers to endemic areas; pregnant women in endemic areas (IPTp); people with sickle cell disease (proguanil); children in areas of seasonal transmission; splenectomised or immunosuppressed people.', '[]'::jsonb, 'Prophylactic drugs act either on the liver stage (causal: atovaquone-proguanil, primaquine) or on blood stages (suppressive: mefloquine, doxycycline, chloroquine), which is why suppressive drugs must be continued for four weeks after leaving a malarious area.', 'admin', 'published', 4, true, '[["mefloquine"], ["atovaquone-proguanil", "malarone", "atovaquone"], ["doxycycline"], ["proguanil"], ["chloroquine"], ["primaquine", "tafenoquine"], ["sulfadoxine-pyrimethamine", "fansidar", "sp"], ["travellers", "non-immune"], ["pregnant women", "pregnancy"], ["sickle cell disease", "children"]]'::jsonb, 'saq p.102 2012/13 Q1d, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-8df88cc3b1', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'saq', 'Classify antimalarial drugs by chemical class, with examples.', '[]'::jsonb, '1. 4-Aminoquinolines: chloroquine, amodiaquine, piperaquine. 2. 8-Aminoquinolines: primaquine, tafenoquine. 3. Quinoline methanols (cinchona alkaloids and related): quinine, quinidine, mefloquine. 4. Phenanthrene methanol and related aryl alcohols: halofantrine, lumefantrine. 5. Artemisinin derivatives (sesquiterpene lactones): artemether, artesunate, dihydroartemisinin. 6. Antifolates: pyrimethamine, proguanil (dihydrofolate reductase inhibitors); sulfadoxine, dapsone (dihydropteroate synthase inhibitors). 7. Naphthoquinone: atovaquone. 8. Antibiotics: doxycycline, tetracycline, clindamycin.', '[]'::jsonb, 'Chemical class predicts mechanism and cross-resistance: quinolines interfere with haem detoxification in the parasite food vacuole, antifolates block folate synthesis, artemisinins generate free radicals from their endoperoxide bridge, and atovaquone blocks mitochondrial electron transport.', 'admin', 'published', 5, true, '[["4-aminoquinolines", "chloroquine", "amodiaquine", "piperaquine"], ["8-aminoquinolines", "primaquine", "tafenoquine"], ["quinine", "mefloquine", "quinoline methanols"], ["halofantrine", "lumefantrine", "phenanthrene methanol"], ["artemisinins", "artemether", "artesunate", "dihydroartemisinin"], ["antifolates", "pyrimethamine", "proguanil", "sulfadoxine"], ["atovaquone"], ["doxycycline", "clindamycin", "antibiotics"]]'::jsonb, 'saq p.095 Q55, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-3eb781b993', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'saq', 'Classify antimalarial drugs according to the stage of the Plasmodium life cycle on which they act.', '[]'::jsonb, '1. Tissue (liver) schizonticides: causal prophylactics acting on primary liver stages - primaquine, atovaquone-proguanil; anti-relapse drugs acting on hypnozoites of P. vivax and P. ovale - primaquine, tafenoquine. 2. Blood schizonticides (clinical cure, suppression): chloroquine, quinine, mefloquine, artemisinins, lumefantrine, sulfadoxine-pyrimethamine, atovaquone, doxycycline. 3. Gametocytocides (prevent transmission): primaquine (all species), artemisinins; chloroquine and quinine for P. vivax and P. malariae only. 4. Sporontocides (block development in the mosquito): proguanil, pyrimethamine, primaquine.', '[]'::jsonb, 'The symptoms of malaria come only from the erythrocytic cycle, so blood schizonticides treat the attack. Radical cure of vivax and ovale malaria needs primaquine to kill dormant liver hypnozoites; primaquine also kills falciparum gametocytes and so reduces transmission.', 'admin', 'published', 4, true, '[["tissue schizonticides", "liver stage", "hepatic stage", "causal prophylaxis"], ["hypnozoites", "primaquine", "radical cure", "tafenoquine"], ["blood schizonticides", "erythrocytic stage", "chloroquine", "quinine", "artemisinin", "mefloquine"], ["gametocytocides", "gametocytes"], ["sporontocides", "proguanil", "pyrimethamine"]]'::jsonb, 'saq p.098 PP3 Q11, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-440909ae74', 'pharm-anticancer-agents-general-principles-classification', 'saq', 'Which cancers are considered curable with chemotherapy?', '[]'::jsonb, 'Any 4 of: Hodgkin lymphoma; childhood acute lymphoblastic leukaemia; testicular germ cell tumours; gestational choriocarcinoma; Burkitt lymphoma and diffuse large B-cell lymphoma; Wilms tumour; acute promyelocytic and some other acute myeloid leukaemias; Ewing sarcoma, rhabdomyosarcoma and retinoblastoma in children.', '[]'::jsonb, 'These tumours have a high growth fraction, so most cells are cycling and vulnerable to cytotoxic drugs. Common adult solid tumours (lung, colon, pancreas) have low growth fractions; in them chemotherapy is adjuvant or palliative rather than curative.', 'admin', 'published', 4, true, '[["hodgkin lymphoma", "hodgkin''s disease", "hodgkin"], ["acute lymphoblastic leukaemia", "all", "childhood leukaemia"], ["testicular cancer", "testicular", "germ cell tumours"], ["choriocarcinoma"], ["burkitt lymphoma", "burkitt''s", "large cell lymphoma", "non-hodgkin lymphoma"], ["wilms tumour", "wilms"], ["ewing sarcoma", "rhabdomyosarcoma", "acute myeloid leukaemia"]]'::jsonb, 'saq p.095 Q56a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-a99eb933e7', 'pharm-anticancer-agents-general-principles-classification', 'saq', 'Classify cytotoxic (anticancer) drugs, with examples.', '[]'::jsonb, '1. Alkylating agents: cyclophosphamide, chlorambucil, busulfan, cisplatin (platinum). 2. Antimetabolites: methotrexate (folate antagonist), 5-fluorouracil and cytarabine (pyrimidine analogues), 6-mercaptopurine (purine analogue). 3. Cytotoxic antibiotics: doxorubicin, daunorubicin, bleomycin, dactinomycin, mitomycin. 4. Plant alkaloids/mitotic inhibitors: vincristine, vinblastine (vinca alkaloids), paclitaxel (taxane); topoisomerase inhibitors - etoposide, irinotecan, topotecan. 5. Hormones and antagonists: tamoxifen, prednisolone, flutamide, anastrozole. 6. Miscellaneous: hydroxyurea, L-asparaginase, procarbazine. 7. Targeted agents: imatinib (tyrosine kinase inhibitor), trastuzumab and rituximab (monoclonal antibodies).', '[]'::jsonb, 'The classical groups damage DNA or block its synthesis or mitosis and are toxic to all dividing cells (marrow, gut, hair). Hormonal and targeted agents exploit features particular to the tumour, so they are more selective and less myelosuppressive.', 'admin', 'published', 5, true, '[["alkylating agents", "cyclophosphamide", "chlorambucil", "busulfan", "cisplatin"], ["antimetabolites", "methotrexate", "5-fluorouracil", "cytarabine", "6-mercaptopurine"], ["cytotoxic antibiotics", "doxorubicin", "bleomycin", "dactinomycin", "anthracyclines"], ["vinca alkaloids", "vincristine", "paclitaxel", "taxanes", "etoposide", "plant alkaloids"], ["hormones", "tamoxifen", "prednisolone", "flutamide"], ["hydroxyurea", "asparaginase", "miscellaneous"], ["imatinib", "trastuzumab", "rituximab", "targeted therapy"]]'::jsonb, 'saq p.095 Q56b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-7c03507ea1', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Give 10 indications of glucocorticoids.', '[]'::jsonb, 'Any 10 of: replacement therapy in adrenal insufficiency (Addison''s disease, congenital adrenal hyperplasia); asthma and COPD exacerbations; anaphylaxis and severe allergic reactions; rheumatoid arthritis; SLE and vasculitis; inflammatory bowel disease; nephrotic syndrome; skin diseases (eczema, pemphigus, psoriasis); prevention of transplant rejection; leukaemias and lymphomas; cerebral oedema from tumours; fetal lung maturation in preterm labour; bacterial and tuberculous meningitis; chemotherapy-induced vomiting; autoimmune haemolytic anaemia and ITP; inflammatory eye disease; hypercalcaemia; sarcoidosis; croup; thyroid storm.', '[]'::jsonb, 'Apart from physiological replacement, glucocorticoids are used at pharmacological doses for their anti-inflammatory and immunosuppressive effects, and for their lympholytic effect in haematological cancers. They suppress disease rather than cure it.', 'admin', 'published', 5, true, '[["adrenal insufficiency", "addison''s disease", "replacement therapy", "congenital adrenal hyperplasia"], ["asthma", "copd"], ["anaphylaxis", "allergic reactions"], ["rheumatoid arthritis"], ["sle", "lupus", "vasculitis"], ["inflammatory bowel disease", "ulcerative colitis", "crohn''s"], ["nephrotic syndrome"], ["eczema", "skin diseases", "pemphigus"], ["transplant rejection", "transplantation"], ["leukaemia", "lymphoma"], ["cerebral oedema"], ["fetal lung maturation", "preterm labour"], ["meningitis"], ["haemolytic anaemia", "itp", "sarcoidosis", "hypercalcaemia", "antiemetic"]]'::jsonb, 'saq p.095 Q57, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-78d918940d', 'pharm-oral-antidiabetic-drugs', 'saq', 'Describe 4 mechanisms of action and 3 adverse effects of biguanides (metformin).', '[]'::jsonb, 'Mechanisms (via activation of AMP-activated protein kinase): 1. reduced hepatic gluconeogenesis and glucose output (main effect); 2. increased insulin sensitivity with greater glucose uptake and utilisation in muscle and fat; 3. reduced intestinal absorption of glucose; 4. reduced plasma glucagon, increased GLP-1; also lowers LDL and triglycerides and reduces appetite. Insulin secretion is not stimulated. Adverse effects: gastrointestinal upset (anorexia, nausea, metallic taste, diarrhoea); lactic acidosis (rare; in renal, hepatic or cardiac failure); vitamin B12 malabsorption.', '[]'::jsonb, 'Because it does not release insulin, metformin does not cause hypoglycaemia or weight gain, which with its cardiovascular benefit makes it first line in type 2 diabetes. It is excreted unchanged by the kidney, so it accumulates and risks lactic acidosis in renal impairment.', 'admin', 'published', 5, true, '[["ampk", "amp-activated protein kinase"], ["reduces hepatic gluconeogenesis", "decreased hepatic glucose output", "gluconeogenesis"], ["increases insulin sensitivity", "peripheral glucose uptake", "glucose uptake in muscle"], ["reduces intestinal glucose absorption", "delays glucose absorption"], ["gi upset", "diarrhoea", "nausea", "metallic taste"], ["lactic acidosis"], ["vitamin b12 deficiency", "b12 malabsorption"]]'::jsonb, 'saq p.095 Q59, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-ec8f4db77e', 'pharm-antiretroviral-i', 'saq', 'Give reasons why first-line antiretroviral treatment was changed from stavudine-based to tenofovir-based regimens.', '[]'::jsonb, 'Any 3 of: stavudine causes serious, cumulative and often irreversible mitochondrial toxicity - peripheral neuropathy, lipoatrophy (disfiguring, stigmatising), lactic acidosis with hepatic steatosis, and pancreatitis; tenofovir is better tolerated with far less mitochondrial toxicity; tenofovir is given once daily and is available in a one-pill fixed-dose combination (with lamivudine and efavirenz), improving adherence; tenofovir is also active against hepatitis B; a more favourable resistance profile that preserves zidovudine for second-line therapy.', '[]'::jsonb, 'Stavudine was cheap and effective but is the NRTI that most strongly inhibits mitochondrial DNA polymerase gamma. WHO recommended phasing it out from 2009 because its long-term toxicity undermined adherence and quality of life.', 'admin', 'published', 3, true, '[["peripheral neuropathy"], ["lipoatrophy", "lipodystrophy"], ["lactic acidosis", "pancreatitis", "mitochondrial toxicity"], ["once daily", "fixed-dose combination", "better adherence"], ["hepatitis b"], ["better tolerated", "less toxic", "safer"], ["resistance profile", "preserves zidovudine"]]'::jsonb, 'saq p.096 Q61, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-b3b63e0a4d', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'A 50-year-old patient is on treatment for heart failure. Enumerate the drugs used in the treatment of heart failure.', '[]'::jsonb, 'Any 5 groups: diuretics - loop (furosemide) and thiazides; ACE inhibitors (enalapril, captopril) or angiotensin receptor blockers (losartan), or sacubitril-valsartan; beta-blockers (carvedilol, bisoprolol, metoprolol succinate); mineralocorticoid receptor antagonists (spironolactone, eplerenone); SGLT2 inhibitors (dapagliflozin, empagliflozin); cardiac glycosides (digoxin); vasodilators (hydralazine with isosorbide dinitrate); ivabradine; inotropes for acute failure (dobutamine, dopamine, milrinone).', '[]'::jsonb, 'Diuretics and digoxin relieve symptoms; the drugs that prolong life are those that block the harmful neurohormonal responses to a failing heart: ACE inhibitors or ARBs, beta-blockers, aldosterone antagonists and, more recently, SGLT2 inhibitors.', 'admin', 'published', 5, true, '[["diuretics", "furosemide", "thiazides"], ["ace inhibitors", "enalapril", "captopril", "arb", "losartan", "sacubitril"], ["beta blockers", "carvedilol", "bisoprolol", "metoprolol"], ["spironolactone", "eplerenone", "aldosterone antagonists"], ["digoxin", "cardiac glycosides"], ["hydralazine", "nitrates", "isosorbide dinitrate"], ["sglt2 inhibitors", "dapagliflozin", "ivabradine"], ["dobutamine", "dopamine", "milrinone"]]'::jsonb, 'saq p.096 Q62(i), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-e28758c8a3', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'A 50-year-old patient on treatment for heart failure develops nausea, vomiting and visual changes. Which drug is most likely to be responsible for these toxic effects?', '[]'::jsonb, 'Digoxin', '["digitalis", "digitoxin", "cardiac glycoside", "lanoxin"]'::jsonb, 'Anorexia, nausea and vomiting are the earliest symptoms of digoxin toxicity, and blurred or yellow-green vision (xanthopsia) is characteristic. Diuretic-induced hypokalaemia, common in heart failure, increases digoxin binding to the sodium pump and precipitates toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.096 Q62(ii), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-816e0b1d69', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'What are the adverse effects of furosemide?', '[]'::jsonb, 'Any 4 of: hypokalaemia; hyponatraemia; hypomagnesaemia; hypocalcaemia; hypovolaemia with hypotension and prerenal uraemia; hypochloraemic metabolic alkalosis; hyperuricaemia and gout; ototoxicity (deafness, tinnitus; with high intravenous doses or aminoglycosides); hyperglycaemia; hypersensitivity (rash, interstitial nephritis).', '[]'::jsonb, 'Loop diuretics block the Na+/K+/2Cl- cotransporter in the thick ascending limb, abolishing the lumen-positive potential that drives calcium and magnesium reabsorption, so both are lost (thiazides, in contrast, retain calcium). A similar transporter in the inner ear explains ototoxicity.', 'admin', 'published', 4, true, '[["hypokalaemia", "hypokalemia"], ["hyponatraemia", "hyponatremia"], ["hypomagnesaemia", "hypocalcaemia"], ["hypovolaemia", "dehydration", "hypotension"], ["metabolic alkalosis"], ["hyperuricaemia", "hyperuricemia", "gout"], ["ototoxicity", "deafness", "tinnitus"], ["hyperglycaemia"], ["rash", "hypersensitivity", "interstitial nephritis"]]'::jsonb, 'saq p.096 Q62(iii), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-8177c2844f', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'A 50-year-old patient on treatment for heart failure develops a persistent dry cough. Which class of drug is most likely to be responsible?', '[]'::jsonb, 'ACE inhibitors', '["ACE inhibitor", "angiotensin-converting enzyme inhibitors", "angiotensin converting enzyme inhibitor", "ACEI", "enalapril", "captopril", "lisinopril", "ramipril"]'::jsonb, 'ACE also breaks down bradykinin; when it is inhibited, bradykinin and substance P accumulate in the airways and cause a dry cough in 10 to 20% of patients. Angiotensin receptor blockers do not affect bradykinin and are the usual substitute.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.096 Q62(iv), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-cc0df6c4b9', 'pharm-drugs-used-in-angina', 'saq', 'A 50-year-old patient has heart failure due to myocardial ischaemia. Which additional drugs would you use for the ischaemic heart disease, and what are their adverse effects?', '[]'::jsonb, 'Antiplatelet drugs - aspirin (gastric irritation and bleeding, bronchospasm) or clopidogrel (bleeding); statins, e.g. atorvastatin (myopathy, raised liver enzymes); nitrates, e.g. glyceryl trinitrate, isosorbide mononitrate (headache, flushing, postural hypotension, tolerance); beta-blockers, e.g. bisoprolol, carvedilol (bradycardia, fatigue, bronchospasm, cold extremities). Rate-limiting calcium channel blockers (verapamil, diltiazem) are avoided because they depress contractility.', '[]'::jsonb, 'Secondary prevention in ischaemic heart disease rests on antiplatelet therapy, a statin, a beta-blocker and an ACE inhibitor, with nitrates for angina. Verapamil and diltiazem are negatively inotropic and worsen systolic heart failure.', 'admin', 'draft', 3, true, '[["aspirin", "clopidogrel", "antiplatelet"], ["statins", "atorvastatin", "simvastatin"], ["nitrates", "glyceryl trinitrate", "isosorbide"], ["beta blockers", "bisoprolol", "carvedilol", "metoprolol"], ["bleeding", "gi bleeding", "myopathy", "headache", "hypotension", "bradycardia"]]'::jsonb, 'saq p.096 Q62(v), JB revision SAQs. Open-ended question; several answers are acceptable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-40aae99763', 'pharm-anti-tb-drugs', 'saq', 'List two antituberculosis drugs that should be avoided in severe hepatic disease.', '[]'::jsonb, 'Pyrazinamide (the most hepatotoxic; avoided first), and isoniazid or rifampicin (also ethionamide). Ethambutol, streptomycin and fluoroquinolones are the non-hepatotoxic alternatives.', '[]'::jsonb, 'Pyrazinamide, isoniazid and rifampicin are all hepatotoxic. In severe or unstable liver disease, regimens use fewer of them (pyrazinamide is dropped first) or none, relying on ethambutol, streptomycin and a fluoroquinolone.', 'admin', 'published', 2, true, '[["pyrazinamide"], ["isoniazid", "rifampicin", "rifampin", "ethionamide"]]'::jsonb, 'saq p.096 Q63a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-ee25cf11a9', 'pharm-anti-tb-drugs', 'saq', 'List 2 drugs that are used in the intensive phase of treatment of multidrug-resistant tuberculosis (MDR-TB) in Kenya.', '[]'::jsonb, 'Older injectable-based regimen (any 2): kanamycin (or amikacin, capreomycin), levofloxacin or moxifloxacin, prothionamide (or ethionamide), cycloserine, pyrazinamide. Current all-oral regimens: bedaquiline, linezolid, levofloxacin or moxifloxacin, clofazimine, cycloserine (or the BPaLM regimen: bedaquiline, pretomanid, linezolid, moxifloxacin).', '[]'::jsonb, 'MDR-TB is resistant to at least isoniazid and rifampicin. Regimens were built around a fluoroquinolone and an injectable aminoglycoside; because of deafness and nephrotoxicity from the injectables, guidelines now prefer all-oral bedaquiline-based regimens.', 'admin', 'draft', 2, true, '[["kanamycin", "amikacin", "capreomycin", "bedaquiline"], ["levofloxacin", "moxifloxacin", "prothionamide", "ethionamide", "cycloserine", "pyrazinamide", "linezolid", "clofazimine", "pretomanid"]]'::jsonb, 'saq p.096 Q63b, JB revision SAQs. Guideline- and year-dependent; both the older injectable-based and current all-oral drugs are accepted.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-d55c11f388', 'pharm-antiplatelet-drugs', 'saq', 'Clopidogrel, used in ischaemic heart disease, irreversibly blocks which platelet receptor?', '[]'::jsonb, 'P2Y12 receptor', '["P2Y12", "ADP receptor", "P2Y12 ADP receptor", "platelet ADP receptor", "purinergic P2Y12 receptor"]'::jsonb, 'Clopidogrel is a thienopyridine prodrug activated by CYP2C19. Its active metabolite irreversibly blocks the P2Y12 ADP receptor, preventing ADP-induced activation of glycoprotein IIb/IIIa and platelet aggregation for the life of the platelet.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.096 Q64a, JB revision SAQs. Reworded from ''Briefly discuss the mechanism of action of clopidogrel in ischaemic heart disease'' (drug name garbled on the page).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-d1a022e8ad', 'pharm-antiplatelet-drugs', 'saq', 'Abciximab, used during percutaneous coronary intervention, blocks which platelet receptor?', '[]'::jsonb, 'Glycoprotein IIb/IIIa', '["GP IIb/IIIa", "GPIIb/IIIa", "glycoprotein IIb/IIIa receptor", "integrin alpha IIb beta 3", "fibrinogen receptor", "IIb/IIIa receptor"]'::jsonb, 'Abciximab is the Fab fragment of a chimeric monoclonal antibody against the glycoprotein IIb/IIIa receptor. This receptor binds fibrinogen and is the final common pathway of platelet aggregation, so blocking it inhibits aggregation whatever the stimulus.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.096 Q64c, JB revision SAQs. Reworded from ''Briefly discuss the mechanism of action of abciximab in ischaemic heart disease''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-7893221a48', 'pharm-drugs-used-in-angina', 'saq', 'Briefly discuss the mechanism of action of metoprolol when used in the treatment of ischaemic heart disease.', '[]'::jsonb, 'Metoprolol is a cardioselective beta-1 adrenoceptor antagonist. It reduces heart rate, myocardial contractility and blood pressure, so myocardial oxygen demand falls; the slower rate lengthens diastole and improves coronary (subendocardial) perfusion. After myocardial infarction it also reduces arrhythmias, infarct size and mortality.', '[]'::jsonb, 'Angina is an imbalance between oxygen supply and demand. Beta-blockers act on the demand side (rate, contractility, wall tension), unlike nitrates, which mainly reduce preload. They are contraindicated in vasospastic angina, where unopposed alpha tone worsens spasm.', 'admin', 'published', 2, true, '[["beta-1 blocker", "beta-1 antagonist", "cardioselective", "beta blocker"], ["reduces heart rate", "negative chronotropic"], ["reduces contractility", "negative inotropic"], ["reduces oxygen demand", "decreases myocardial oxygen consumption"], ["prolongs diastole", "improves coronary perfusion", "antiarrhythmic"]]'::jsonb, 'saq p.096 Q64d, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-5c7d5dce64', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'saq', 'List 3 therapeutic products used in the treatment of disseminated intravascular coagulation (DIC).', '[]'::jsonb, 'Fresh frozen plasma (replaces clotting factors); platelet concentrates; cryoprecipitate or fibrinogen concentrate (replaces fibrinogen). Also: red cell transfusion; heparin in thrombosis-predominant DIC; antithrombin concentrate. The underlying cause must be treated.', '[]'::jsonb, 'In DIC widespread activation of coagulation consumes clotting factors, fibrinogen and platelets, so bleeding follows. Replacement therapy supports the patient while the trigger (sepsis, obstetric catastrophe, malignancy) is treated. Heparin is reserved for cases where thrombosis dominates the picture.', 'admin', 'published', 3, true, '[["fresh frozen plasma", "ffp"], ["platelets", "platelet concentrate"], ["cryoprecipitate", "fibrinogen"], ["heparin", "antithrombin", "red cells", "blood transfusion"]]'::jsonb, 'saq p.096 Q65, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-e2a1f0a905', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'saq', 'Give 3 clinical indications of cryoprecipitate.', '[]'::jsonb, 'Any 3 of: hypofibrinogenaemia with bleeding (DIC, massive transfusion, obstetric haemorrhage, congenital afibrinogenaemia); haemophilia A when factor VIII concentrate is not available; von Willebrand disease when concentrate or desmopressin is unsuitable; factor XIII deficiency; uraemic bleeding; reversal of thrombolytic therapy.', '[]'::jsonb, 'Cryoprecipitate is the cold-insoluble fraction of plasma, rich in fibrinogen, factor VIII, von Willebrand factor, factor XIII and fibronectin. Its main modern use is fibrinogen replacement; virally inactivated concentrates are preferred for haemophilia and von Willebrand disease.', 'admin', 'published', 3, true, '[["hypofibrinogenaemia", "fibrinogen deficiency", "low fibrinogen", "dic", "massive transfusion"], ["haemophilia a", "hemophilia a", "factor viii deficiency"], ["von willebrand disease", "vwd"], ["factor xiii deficiency"], ["uraemic bleeding", "thrombolytic reversal"]]'::jsonb, 'saq p.096 Q66, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-20f4616fd8', 'pharm-direct-acting-cholinomimetics', 'saq', 'Name 4 choline esters and for each describe its degree of susceptibility to hydrolysis by cholinesterase.', '[]'::jsonb, 'Acetylcholine: very susceptible (hydrolysed in seconds by acetylcholinesterase and plasma cholinesterase). Methacholine: slightly susceptible (about a third as fast; resistant to plasma cholinesterase). Carbachol: resistant (negligible hydrolysis). Bethanechol: resistant (negligible hydrolysis).', '[]'::jsonb, 'The beta-methyl group of methacholine reduces hydrolysis and nicotinic activity; replacing the acetyl group with a carbamoyl group (carbachol, bethanechol) makes the ester resistant to cholinesterase, giving a longer action. Bethanechol has both changes: long acting and purely muscarinic.', 'admin', 'published', 4, true, '[["acetylcholine", "very susceptible", "rapidly hydrolysed"], ["methacholine", "less susceptible", "slightly susceptible"], ["carbachol", "resistant"], ["bethanechol", "resistant"]]'::jsonb, 'saq p.096 list2 Q1, JB revision SAQs. The page says ''susceptibility to the action of acetylcholine''; acetylcholinesterase is clearly meant.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-ddac88d64b', 'pharm-indirect-acting-cholinomimetics', 'saq', 'Give 5 examples of indirect-acting cholinomimetics.', '[]'::jsonb, 'Any 5 of: neostigmine; physostigmine; pyridostigmine; edrophonium; rivastigmine; donepezil; galantamine; echothiophate (ecothiopate); organophosphate insecticides (malathion, parathion); carbaryl.', '[]'::jsonb, 'Indirect cholinomimetics inhibit acetylcholinesterase, so acetylcholine accumulates at muscarinic and nicotinic synapses. Uses follow from this: myasthenia gravis and reversal of neuromuscular block (neostigmine, pyridostigmine), glaucoma, and Alzheimer''s disease (donepezil, rivastigmine).', 'admin', 'published', 5, true, '[["neostigmine"], ["physostigmine"], ["pyridostigmine"], ["edrophonium"], ["rivastigmine"], ["donepezil"], ["galantamine", "tacrine"], ["echothiophate", "ecothiopate", "malathion", "parathion", "organophosphates", "carbaryl"]]'::jsonb, 'saq p.096 list2 Q2, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-2d8002e58f', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'saq', 'State the mechanism of action of the 2 main drugs used in the treatment of organophosphate poisoning.', '[]'::jsonb, 'Atropine: competitive antagonist at muscarinic receptors; reverses the muscarinic effects of excess acetylcholine (bronchorrhoea, bronchospasm, bradycardia, salivation, miosis) and some central effects; it has no effect at the neuromuscular junction. Pralidoxime (an oxime; also obidoxime): cholinesterase reactivator - its oxime group binds the phosphorus of the organophosphate attached to the enzyme''s serine and removes it, regenerating active acetylcholinesterase, provided it is given before the enzyme ''ages''; it reverses nicotinic effects (muscle weakness, fasciculation).', '[]'::jsonb, 'The two drugs are complementary: atropine blocks the muscarinic receptor but does nothing for paralysis, while pralidoxime restores the enzyme at the neuromuscular junction but crosses the blood-brain barrier poorly. Diazepam is added for convulsions.', 'admin', 'published', 4, true, '[["atropine"], ["muscarinic antagonist", "blocks muscarinic receptors", "competitive antagonist"], ["pralidoxime", "oxime", "obidoxime"], ["reactivates cholinesterase", "regenerates acetylcholinesterase", "enzyme reactivator"], ["before ageing", "aging", "nicotinic effects"]]'::jsonb, 'saq p.096 list2 Q3, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-2a8e2b10b8', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Name the neurotransmitters for cholinergic, adrenergic and non-adrenergic non-cholinergic (NANC) transmission.', '[]'::jsonb, 'Cholinergic: acetylcholine. Adrenergic: noradrenaline (norepinephrine); adrenaline from the adrenal medulla; dopamine at some sites. NANC: nitric oxide, ATP, vasoactive intestinal peptide, neuropeptide Y, substance P, serotonin, GABA.', '[]'::jsonb, 'Acetylcholine is the transmitter at all autonomic ganglia, all parasympathetic and a few sympathetic (sweat gland) postganglionic endings; noradrenaline at most sympathetic endings. NANC transmitters are often co-released: nitric oxide mediates penile erection and gut relaxation.', 'admin', 'published', 3, true, '[["acetylcholine", "ach"], ["noradrenaline", "norepinephrine", "adrenaline", "dopamine"], ["nitric oxide", "no", "atp", "vip", "vasoactive intestinal peptide", "neuropeptide y", "substance p"]]'::jsonb, 'saq p.096 list2 Q4, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-17e61f8d99', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Classify anticonvulsant drugs according to their chemical groups, giving examples in each group.', '[]'::jsonb, '1. Hydantoins: phenytoin, fosphenytoin. 2. Barbiturates and deoxybarbiturates: phenobarbital, primidone. 3. Iminostilbenes: carbamazepine, oxcarbazepine. 4. Succinimides: ethosuximide, methsuximide. 5. Aliphatic carboxylic acids: sodium valproate. 6. Benzodiazepines: diazepam, clonazepam, lorazepam, clobazam. 7. Oxazolidinediones: trimethadione. 8. Phenyltriazine: lamotrigine. 9. GABA analogues: gabapentin, pregabalin, vigabatrin, tiagabine. 10. Newer agents: levetiracetam, topiramate, zonisamide, lacosamide, felbamate.', '[]'::jsonb, 'The older drugs share a ring structure related to the barbiturates (hydantoins, succinimides, oxazolidinediones), which is the basis of the chemical classification. Clinically the mechanism-based classification is more useful because it predicts which seizure types respond.', 'admin', 'published', 5, true, '[["hydantoins", "phenytoin", "fosphenytoin"], ["barbiturates", "phenobarbital", "phenobarbitone", "primidone"], ["iminostilbenes", "carbamazepine", "oxcarbazepine"], ["succinimides", "ethosuximide"], ["valproate", "valproic acid", "carboxylic acid"], ["benzodiazepines", "diazepam", "clonazepam", "lorazepam"], ["oxazolidinediones", "trimethadione"], ["lamotrigine", "gabapentin", "vigabatrin", "levetiracetam", "topiramate"]]'::jsonb, 'saq p.096 list2 Q5, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-b994c4cab9', 'pharm-iminostilbenes-succinimides-lamotrigine', 'saq', 'Succinimides such as ethosuximide act by blocking which type of ion channel in thalamic neurones?', '[]'::jsonb, 'T-type calcium channels', '["T-type Ca2+ channels", "T type calcium channel", "low-threshold calcium channels", "T-type voltage-gated calcium channels", "calcium channels (T-type)"]'::jsonb, 'Absence seizures arise from rhythmic 3 Hz thalamocortical discharges driven by low-threshold T-type calcium currents. Ethosuximide reduces this current, so it is effective only in absence seizures and not in tonic-clonic or focal seizures.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.096 list2 Q6a, JB revision SAQs. Reworded from ''Succinimides: describe their mechanism of action''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-2283262b7e', 'pharm-iminostilbenes-succinimides-lamotrigine', 'saq', 'Succinimides (ethosuximide): describe their pharmacokinetics, indications and adverse effects.', '[]'::jsonb, 'Pharmacokinetics: completely absorbed orally; not bound to plasma proteins; metabolised in the liver (CYP3A4) to inactive metabolites, about 20% excreted unchanged in urine; long half-life (about 40-60 hours in adults, 30 in children). Indication: absence (petit mal) seizures - drug of choice when absences occur alone. Adverse effects: nausea, vomiting, anorexia and abdominal pain; drowsiness, dizziness, headache; hiccups; rash, including Stevens-Johnson syndrome; rarely blood dyscrasias and a lupus-like syndrome.', '[]'::jsonb, 'Ethosuximide has a narrow spectrum: it does not protect against tonic-clonic seizures, so valproate is preferred when absences coexist with them. Its long half-life allows once or twice daily dosing.', 'admin', 'published', 4, true, '[["well absorbed", "complete absorption"], ["not protein bound"], ["hepatic metabolism", "long half-life", "40-60 hours"], ["absence seizures", "petit mal"], ["nausea", "vomiting", "gi upset", "abdominal pain"], ["drowsiness", "dizziness", "headache", "hiccups"], ["rash", "stevens-johnson", "blood dyscrasias"]]'::jsonb, 'saq p.096 list2 Q6b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-641ceec19d', 'pharm-aminoglycosides', 'saq', 'List 5 aminoglycosides.', '[]'::jsonb, 'Any 5 of: gentamicin; amikacin; streptomycin; tobramycin; kanamycin; neomycin; netilmicin; paromomycin; framycetin.', '[]'::jsonb, 'Aminoglycosides are bactericidal: they bind the 30S ribosomal subunit, causing misreading of mRNA. They need oxygen-dependent transport into bacteria, so they are inactive against anaerobes, and being polar they are not absorbed orally. All share nephrotoxicity and ototoxicity.', 'admin', 'published', 5, true, '[["gentamicin"], ["amikacin"], ["streptomycin"], ["tobramycin"], ["kanamycin"], ["neomycin"], ["netilmicin"], ["paromomycin", "framycetin", "spectinomycin"]]'::jsonb, 'saq p.096 list2 Q8, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-4010d0d23c', 'pharm-anti-tb-drugs', 'saq', 'List 4 examples of second-line antimycobacterial (antituberculosis) drugs.', '[]'::jsonb, 'Any 4 of: fluoroquinolones (levofloxacin, moxifloxacin); injectable agents (amikacin, kanamycin, capreomycin); ethionamide or prothionamide; cycloserine or terizidone; para-aminosalicylic acid (PAS); bedaquiline; linezolid; clofazimine; delamanid; thioacetazone.', '[]'::jsonb, 'Second-line drugs are less effective, more toxic or more expensive than rifampicin, isoniazid, pyrazinamide and ethambutol and are reserved for drug-resistant tuberculosis or intolerance. Bedaquiline, which inhibits mycobacterial ATP synthase, and linezolid now form the core of MDR-TB treatment.', 'admin', 'published', 4, true, '[["levofloxacin", "moxifloxacin", "fluoroquinolones", "ofloxacin"], ["amikacin", "kanamycin", "capreomycin"], ["ethionamide", "prothionamide"], ["cycloserine", "terizidone"], ["pas", "para-aminosalicylic acid"], ["bedaquiline"], ["linezolid"], ["clofazimine", "delamanid", "thioacetazone"]]'::jsonb, 'saq p.096 list2 Q10, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-733ec393c3', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'saq', 'Give four different pharmacological actions of quinine.', '[]'::jsonb, 'Any 4 of: antimalarial - rapidly acting blood schizonticide (and gametocytocide for P. vivax and P. malariae); skeletal muscle - prolongs the refractory period and reduces motor end-plate excitability (relieves nocturnal cramps, worsens myasthenia); heart - quinidine-like depression of conduction and contractility with QT prolongation, and hypotension; pancreas - stimulates insulin release, causing hypoglycaemia; uterus - mild oxytocic effect; weak antipyretic and analgesic; local anaesthetic and irritant, bitter taste; toxic effects on hearing and vision (cinchonism).', '[]'::jsonb, 'Quinine is a general protoplasmic poison with actions well beyond malaria. Its stimulation of insulin release and its cardiac effects are the reasons intravenous quinine is given as a slow infusion in dextrose, never as a bolus.', 'admin', 'published', 4, true, '[["antimalarial", "blood schizonticide", "schizonticidal"], ["skeletal muscle", "muscle cramps", "curare-like", "neuromuscular"], ["cardiac depressant", "quinidine-like", "qt prolongation", "hypotension"], ["insulin release", "hypoglycaemia", "hypoglycemia"], ["oxytocic", "uterine contraction"], ["antipyretic", "analgesic", "local anaesthetic", "cinchonism"]]'::jsonb, 'saq p.096 list2 Q11, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-527429fd85', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'saq', 'Discuss the mechanism of action of sucralfate in the treatment of peptic ulcer disease.', '[]'::jsonb, 'Sucralfate is a complex of aluminium hydroxide and sulphated sucrose. In acid (pH below 4) it polymerises into a sticky, negatively charged gel that binds selectively to positively charged proteins in the ulcer base, forming a physical barrier against acid, pepsin and bile for about 6 hours. It also stimulates mucosal prostaglandin, mucus and bicarbonate production and binds epidermal growth factor. It does not neutralise acid appreciably.', '[]'::jsonb, 'Because it needs acid for activation, sucralfate should not be given with antacids, H2 blockers or proton pump inhibitors. It is hardly absorbed; constipation is the main side effect, and it binds other drugs (phenytoin, digoxin, quinolones, tetracyclines) in the gut.', 'admin', 'published', 2, true, '[["polymerises in acid", "needs acid", "viscous gel", "paste"], ["binds ulcer base", "adheres to ulcer", "coats ulcer", "protective barrier"], ["protects against acid and pepsin", "barrier to pepsin"], ["stimulates prostaglandin", "mucus", "bicarbonate"]]'::jsonb, 'saq p.096 list2 Q12, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-fac169718e', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'saq', 'List one adverse effect of cimetidine in each of the following systems: gastrointestinal, endocrine, haemopoietic, CNS.', '[]'::jsonb, 'Gastrointestinal: diarrhoea (or constipation, nausea, raised transaminases). Endocrine: gynaecomastia (also galactorrhoea, impotence, reduced sperm count). Haemopoietic: neutropenia, thrombocytopenia (rarely agranulocytosis, aplastic anaemia). CNS: confusion (also dizziness, headache, hallucinations, delirium, especially in the elderly and in renal failure).', '[]'::jsonb, 'Cimetidine binds androgen receptors and inhibits oestradiol metabolism, hence its endocrine effects, which ranitidine and famotidine lack. It also inhibits several cytochrome P450 enzymes, raising levels of warfarin, phenytoin and theophylline.', 'admin', 'published', 4, true, '[["diarrhoea", "diarrhea", "constipation", "nausea"], ["gynaecomastia", "gynecomastia", "impotence", "galactorrhoea"], ["neutropenia", "thrombocytopenia", "agranulocytosis", "leucopenia"], ["confusion", "dizziness", "headache", "hallucinations", "delirium"]]'::jsonb, 'saq p.096 list2 Q13, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-a045c91391', 'pharm-inhalational-anesthetic-agents', 'saq', 'List four factors that affect the speed of induction of anaesthesia with inhalational anaesthetics.', '[]'::jsonb, 'Any 4 of: solubility of the agent in blood (blood:gas partition coefficient - low solubility gives faster induction); inspired concentration of the anaesthetic (concentration effect, second-gas effect); alveolar ventilation (higher ventilation is faster); cardiac output or pulmonary blood flow (higher output slows induction); alveolar-to-venous partial pressure gradient (tissue uptake); ventilation-perfusion mismatch.', '[]'::jsonb, 'Induction depends on how fast the alveolar partial pressure approaches the inspired one. A poorly soluble agent (nitrous oxide, desflurane, sevoflurane) is removed less by blood, so alveolar and brain partial pressures rise quickly; a high cardiac output carries more agent away and slows induction.', 'admin', 'published', 4, true, '[["blood:gas partition coefficient", "blood gas solubility", "solubility in blood"], ["inspired concentration", "concentration effect", "second gas effect"], ["alveolar ventilation", "ventilation rate"], ["cardiac output", "pulmonary blood flow"], ["arteriovenous gradient", "alveolar-venous gradient", "tissue uptake"]]'::jsonb, 'saq p.096 list2 Q14, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-f58ce0cf02', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'saq', 'Classify the diuretics according to their mechanism (site) of action and give an example in each class.', '[]'::jsonb, '1. Carbonic anhydrase inhibitors (proximal tubule): acetazolamide. 2. Osmotic diuretics (proximal tubule and descending limb): mannitol. 3. Loop diuretics (thick ascending limb; inhibit the Na+/K+/2Cl- cotransporter): furosemide, bumetanide. 4. Thiazides and thiazide-like diuretics (distal convoluted tubule; inhibit the Na+/Cl- cotransporter): hydrochlorothiazide, chlortalidone, indapamide. 5. Potassium-sparing diuretics (collecting duct): aldosterone antagonists (spironolactone, eplerenone) and epithelial sodium channel blockers (amiloride, triamterene). 6. ADH antagonists (aquaretics): tolvaptan, demeclocycline.', '[]'::jsonb, 'The further along the nephron a diuretic acts, the less sodium remains to be affected, so loop diuretics (25% of filtered sodium) are the most powerful and potassium-sparing agents (2%) the weakest. Site of action also predicts electrolyte effects, such as hypokalaemia with loop and thiazide drugs.', 'admin', 'published', 5, true, '[["carbonic anhydrase inhibitors", "acetazolamide"], ["osmotic", "mannitol"], ["loop diuretics", "furosemide", "bumetanide", "na-k-2cl"], ["thiazides", "hydrochlorothiazide", "chlorthalidone", "indapamide", "na-cl cotransporter"], ["potassium-sparing", "spironolactone", "amiloride", "triamterene", "eplerenone"], ["tolvaptan", "adh antagonists", "vaptans"]]'::jsonb, 'saq p.096 list2 Q15, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbon-monoxide-cyanide-acid-and-alkal-1fe735bcd9', 'pharm-carbon-monoxide-cyanide-acid-and-alkali-poisoning', 'saq', 'Concisely describe 6 methods of treating cyanide poisoning.', '[]'::jsonb, '1. Remove from exposure, decontaminate, and give 100% oxygen with ventilatory support. 2. Amyl nitrite by inhalation - forms methaemoglobin. 3. Sodium nitrite intravenously - oxidises haemoglobin to methaemoglobin, which binds cyanide as cyanmethaemoglobin, freeing cytochrome oxidase. 4. Sodium thiosulphate intravenously - sulphur donor for rhodanese, converting cyanide to thiocyanate, which is excreted in urine. 5. Hydroxocobalamin intravenously - binds cyanide to form cyanocobalamin (vitamin B12). 6. Dicobalt edetate intravenously - chelates cyanide directly. (Also 4-dimethylaminophenol; activated charcoal after ingestion; correction of acidosis.)', '[]'::jsonb, 'Cyanide binds ferric iron in cytochrome oxidase and stops cellular respiration. Antidotes either provide an alternative ferric target (nitrite-induced methaemoglobin), bind cyanide directly (cobalt compounds) or speed its detoxification to thiocyanate (thiosulphate).', 'admin', 'published', 6, true, '[["oxygen", "100% oxygen"], ["amyl nitrite"], ["sodium nitrite", "methaemoglobin", "methemoglobin"], ["sodium thiosulphate", "sodium thiosulfate", "thiocyanate", "rhodanese"], ["hydroxocobalamin", "cyanocobalamin"], ["dicobalt edetate", "cobalt edetate"], ["activated charcoal", "decontamination", "4-dmap"]]'::jsonb, 'saq p.097 PP2 Q1, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-27fb44523e', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Describe the mechanism of action of sodium nitroprusside, diazoxide and minoxidil.', '[]'::jsonb, 'Sodium nitroprusside: releases nitric oxide, which activates guanylyl cyclase, raising cGMP and relaxing both arteriolar and venous smooth muscle. Diazoxide: opens ATP-sensitive potassium channels, hyperpolarising arteriolar smooth muscle (and beta cells, inhibiting insulin release). Minoxidil: a prodrug converted to minoxidil sulphate, which opens ATP-sensitive potassium channels, hyperpolarising and relaxing arteriolar smooth muscle.', '[]'::jsonb, 'Nitroprusside dilates arteries and veins and acts within seconds, suiting hypertensive emergencies; its metabolism releases cyanide. Diazoxide and minoxidil are pure arteriolar dilators that provoke reflex tachycardia and fluid retention, so they are combined with a beta-blocker and a diuretic.', 'admin', 'published', 3, true, '[["nitric oxide", "no donor", "releases no"], ["guanylyl cyclase", "cgmp"], ["opens potassium channels", "k-atp channel opener", "potassium channel opener", "katp"], ["hyperpolarisation", "hyperpolarization"], ["arteriolar dilation", "arterioles", "arterial and venous"], ["minoxidil sulphate", "prodrug", "inhibits insulin release"]]'::jsonb, 'saq p.097 PP2 Q2, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-endocrine-pharmacology-bfab7487ad', 'pharm-introduction-to-endocrine-pharmacology-lh-fsh-chorionic-gonadotr', 'saq', 'Name 2 pharmacologically active metabolites of testosterone.', '[]'::jsonb, 'Dihydrotestosterone (DHT), formed by 5-alpha-reductase; oestradiol, formed by aromatase.', '[]'::jsonb, 'Dihydrotestosterone binds the androgen receptor more strongly than testosterone and mediates prostate growth, male-pattern baldness and virilisation of the external genitalia; finasteride blocks its formation. Aromatisation to oestradiol accounts for epiphyseal closure and gynaecomastia.', 'admin', 'published', 2, true, '[["dihydrotestosterone", "dht", "5-alpha-dihydrotestosterone"], ["oestradiol", "estradiol", "oestrogen"]]'::jsonb, 'saq p.097 PP2 Q3, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-f7caa72275', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'Describe the pharmacology of the radio-isotope iodine-131, including its mechanism of action in thyrotoxicosis.', '[]'::jsonb, 'Given orally as sodium iodide (I-131) solution or capsule; rapidly absorbed and concentrated in the thyroid by the sodium-iodide symporter and incorporated into thyroglobulin. It emits beta particles, which penetrate only 0.5-2 mm and destroy follicular cells with little damage to surrounding tissue, and gamma rays, used for imaging. Physical half-life 8 days. The effect appears in 1-2 months and is maximal by 3-4 months. Uses: Graves'' disease, toxic nodular goitre, thyroid cancer ablation. Main adverse effect: hypothyroidism. Contraindicated in pregnancy and breastfeeding.', '[]'::jsonb, 'The gland''s ability to concentrate iodide makes this a targeted radiotherapy, a non-surgical ''thyroidectomy''. Most patients eventually become hypothyroid and need lifelong levothyroxine. It crosses the placenta and would destroy the fetal thyroid.', 'admin', 'published', 3, true, '[["oral", "sodium iodide"], ["concentrated in thyroid", "taken up by thyroid", "sodium-iodide symporter"], ["beta particles", "beta emission", "beta radiation"], ["destroys follicular cells", "destruction of thyroid tissue"], ["half-life 8 days", "8 days"], ["hypothyroidism"], ["pregnancy", "breastfeeding", "contraindicated"]]'::jsonb, 'saq p.097 PP2 Q4, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-d038d16811', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Name 3 antagonists (inhibitors) of adrenocortical hormone synthesis.', '[]'::jsonb, 'Any 3 of: metyrapone (inhibits 11-beta-hydroxylase); ketoconazole (inhibits several cytochrome P450 steroidogenic enzymes); aminoglutethimide (inhibits conversion of cholesterol to pregnenolone); mitotane (adrenocorticolytic); trilostane (inhibits 3-beta-hydroxysteroid dehydrogenase); etomidate (inhibits 11-beta-hydroxylase); osilodrostat.', '[]'::jsonb, 'These drugs are used to control Cushing''s syndrome before surgery or when surgery fails, and metyrapone is also a test of pituitary ACTH reserve. Etomidate''s inhibition of 11-beta-hydroxylase is the reason infusions of it increased mortality in intensive care.', 'admin', 'published', 3, true, '[["metyrapone"], ["ketoconazole"], ["aminoglutethimide"], ["mitotane"], ["trilostane"], ["etomidate", "osilodrostat"]]'::jsonb, 'saq p.097 PP2 Q5, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-1fd95a734b', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'Discuss the pharmacokinetics of furosemide.', '[]'::jsonb, 'Oral bioavailability averages about 50% but is very variable (10-90%) and is reduced in heart failure with gut oedema; onset within 30-60 minutes orally and 5 minutes intravenously; duration about 6 hours orally and 2 hours intravenously. It is over 95% bound to albumin, so it is not filtered but is secreted into the proximal tubule by the organic anion transporter to reach its luminal site of action in the thick ascending limb. It is excreted largely unchanged in urine, with some glucuronidation. Half-life about 1.5 hours, prolonged in renal failure; NSAIDs and probenecid reduce its secretion and effect.', '[]'::jsonb, 'Because furosemide must be secreted into the tubule to work, renal impairment and competing organic anions blunt its effect, and higher doses are needed. Its short action leaves time for sodium retention between doses.', 'admin', 'published', 3, true, '[["bioavailability", "variable absorption", "50%"], ["onset", "duration", "6 hours"], ["highly protein bound", "95%", "albumin"], ["tubular secretion", "organic anion transporter", "secreted in proximal tubule"], ["excreted unchanged", "renal excretion"], ["half-life", "1.5 hours"]]'::jsonb, 'saq p.097 PP2 Q11, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-a41bedd037', 'pharm-lipid-lowering-agents', 'saq', 'Classify lipid-lowering agents, indicate their mechanism of action and give 2 adverse effects of each group.', '[]'::jsonb, '1. Statins (HMG-CoA reductase inhibitors: atorvastatin, simvastatin): reduce hepatic cholesterol synthesis and up-regulate LDL receptors; myopathy/rhabdomyolysis, raised transaminases. 2. Fibrates (gemfibrozil, fenofibrate): PPAR-alpha agonists that increase lipoprotein lipase activity and lower triglycerides; myopathy, gallstones, GI upset. 3. Bile acid sequestrants (cholestyramine, colestipol): bind bile acids in the gut, increasing conversion of cholesterol to bile acids; constipation and bloating, reduced absorption of fat-soluble vitamins and drugs. 4. Nicotinic acid (niacin): inhibits lipolysis in adipose tissue and hepatic VLDL production, raises HDL; flushing, hyperglycaemia, hyperuricaemia, hepatotoxicity. 5. Cholesterol absorption inhibitor (ezetimibe): blocks the NPC1L1 transporter; diarrhoea, raised transaminases. 6. PCSK9 inhibitors (evolocumab, alirocumab): prevent LDL receptor degradation; injection-site reactions. Also omega-3 fatty acids.', '[]'::jsonb, 'Statins are the most effective at lowering LDL and reducing cardiovascular events; fibrates are the drugs for severe hypertriglyceridaemia. Combining a statin with gemfibrozil greatly increases the risk of rhabdomyolysis.', 'admin', 'published', 5, true, '[["statins", "hmg-coa reductase inhibitors", "atorvastatin", "simvastatin"], ["fibrates", "gemfibrozil", "fenofibrate", "ppar-alpha", "lipoprotein lipase"], ["bile acid sequestrants", "cholestyramine", "colestipol", "resins"], ["nicotinic acid", "niacin"], ["ezetimibe", "cholesterol absorption inhibitor", "npc1l1"], ["pcsk9 inhibitors", "evolocumab"], ["myopathy", "rhabdomyolysis", "raised transaminases"], ["flushing", "constipation", "gallstones"]]'::jsonb, 'saq p.097 PP2 Q12, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-779a0c930a', 'pharm-antiplatelet-drugs', 'saq', 'List the antiplatelet agents.', '[]'::jsonb, '1. Cyclo-oxygenase inhibitor: aspirin. 2. ADP (P2Y12) receptor antagonists: clopidogrel, prasugrel, ticlopidine, ticagrelor. 3. Glycoprotein IIb/IIIa antagonists: abciximab, eptifibatide, tirofiban. 4. Phosphodiesterase inhibitors: dipyridamole, cilostazol. 5. Others: epoprostenol (prostacyclin), vorapaxar (PAR-1 thrombin receptor antagonist).', '[]'::jsonb, 'Platelet aggregation can be blocked at several points: thromboxane A2 synthesis (aspirin), the ADP receptor, the final common fibrinogen receptor glycoprotein IIb/IIIa, or by raising platelet cAMP. Antiplatelet drugs are most useful in arterial thrombosis, where clots are platelet rich.', 'admin', 'published', 5, true, '[["aspirin"], ["clopidogrel", "prasugrel", "ticagrelor", "ticlopidine"], ["abciximab", "eptifibatide", "tirofiban", "glycoprotein iib/iiia inhibitors"], ["dipyridamole", "cilostazol"], ["epoprostenol", "prostacyclin", "vorapaxar"]]'::jsonb, 'saq p.097 PP2 Q14, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-5008bb381c', 'pharm-anti-tb-drugs', 'saq', 'Write short notes on the pharmacology of isoniazid.', '[]'::jsonb, 'Mechanism: a prodrug activated by mycobacterial catalase-peroxidase (KatG); the product inhibits InhA (enoyl-ACP reductase) and so mycolic acid synthesis in the cell wall; bactericidal to dividing bacilli. Resistance: mutations in katG or inhA. Pharmacokinetics: well absorbed orally, widely distributed including the CSF and caseous tissue; metabolised in the liver by N-acetyltransferase 2 (genetically determined fast and slow acetylators); excreted in urine. Uses: treatment of tuberculosis in combination; preventive therapy for latent TB alone. Adverse effects: peripheral neuropathy (pyridoxine deficiency; prevented with vitamin B6), hepatitis, rash, lupus-like syndrome, seizures in overdose, sideroblastic anaemia. Interactions: inhibits metabolism of phenytoin and carbamazepine.', '[]'::jsonb, 'Slow acetylators have higher drug levels and more neuropathy, while hepatotoxicity increases with age and alcohol. Isoniazid is specific for mycobacteria because only they make mycolic acids and possess the activating enzyme.', 'admin', 'published', 5, true, '[["prodrug", "katg", "catalase-peroxidase"], ["mycolic acid", "inhibits mycolic acid synthesis", "inha"], ["bactericidal"], ["acetylation", "n-acetyltransferase", "slow acetylators", "fast acetylators"], ["peripheral neuropathy", "pyridoxine", "vitamin b6"], ["hepatitis", "hepatotoxicity"], ["preventive therapy", "latent tb", "tuberculosis"], ["enzyme inhibitor", "phenytoin"]]'::jsonb, 'saq p.097 PP2 Q15b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-2b392cda10', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'saq', 'List 10 common adverse effects of NSAIDs.', '[]'::jsonb, 'Any 10 of: dyspepsia, nausea; gastric erosions and peptic ulceration; gastrointestinal bleeding and perforation; renal impairment (acute kidney injury); sodium and water retention with oedema, hypertension and worsening heart failure; hyperkalaemia; analgesic nephropathy (papillary necrosis, interstitial nephritis); bronchospasm in aspirin-sensitive asthma; rash, urticaria and other hypersensitivity reactions; prolonged bleeding time (antiplatelet effect); raised liver enzymes and hepatotoxicity; headache, dizziness, tinnitus; increased risk of thrombotic cardiovascular events; premature closure of the ductus arteriosus and delayed labour; blood dyscrasias.', '[]'::jsonb, 'Nearly all NSAID adverse effects result from loss of protective prostaglandins: PGE2 and PGI2 in gastric mucosa, vasodilator prostaglandins that maintain renal blood flow, and platelet thromboxane. The elderly, and patients with heart failure or renal disease, are at greatest risk.', 'admin', 'published', 5, true, '[["dyspepsia", "nausea", "gastritis"], ["peptic ulcer", "gastric ulcer", "ulceration"], ["gi bleeding", "gastrointestinal bleeding", "perforation"], ["renal impairment", "acute kidney injury", "nephrotoxicity"], ["fluid retention", "oedema", "hypertension", "heart failure"], ["hyperkalaemia"], ["bronchospasm", "asthma"], ["rash", "hypersensitivity", "urticaria"], ["bleeding", "antiplatelet"], ["hepatotoxicity", "raised liver enzymes"], ["headache", "dizziness", "tinnitus"], ["cardiovascular events", "myocardial infarction"], ["premature closure of ductus", "delayed labour"]]'::jsonb, 'saq p.097 PP2 Q17, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-73a300344f', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List six examples of loop diuretics and describe their mechanism of action.', '[]'::jsonb, 'Examples: furosemide (frusemide), bumetanide, torasemide (torsemide), ethacrynic acid, piretanide, azosemide. Mechanism: secreted into the proximal tubule, they act from the lumen to inhibit the Na+/K+/2Cl- cotransporter (NKCC2) in the thick ascending limb of the loop of Henle. Up to 25% of filtered sodium is excreted; the medullary concentration gradient is reduced, impairing urine concentration; loss of the lumen-positive potential increases calcium and magnesium excretion. They also cause prostaglandin-mediated venodilatation.', '[]'::jsonb, 'They are called high-ceiling diuretics because increasing the dose keeps increasing diuresis, and they work even at low glomerular filtration rates. Ethacrynic acid is the only one that is not a sulphonamide derivative, so it is used in sulpha-allergic patients.', 'admin', 'published', 4, true, '[["furosemide", "frusemide"], ["bumetanide"], ["torasemide", "torsemide"], ["ethacrynic acid", "piretanide", "azosemide"], ["na+/k+/2cl-", "nkcc2", "na-k-2cl cotransporter"], ["thick ascending limb", "loop of henle"], ["calcium and magnesium loss", "high ceiling", "venodilatation"]]'::jsonb, 'saq p.097 PP3 Q2, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-ab683cc691', 'pharm-preanesthetic-agent', 'saq', 'Classify drugs given for pre-anaesthetic medication, giving one example for each group.', '[]'::jsonb, '1. Anxiolytics/sedatives (benzodiazepines): diazepam, midazolam, lorazepam. 2. Opioid analgesics: morphine, pethidine, fentanyl. 3. Antimuscarinics (reduce secretions and vagal reflexes): atropine, glycopyrronium, hyoscine. 4. Antiemetics: metoclopramide, ondansetron, promethazine. 5. Drugs reducing gastric acidity and volume: ranitidine, omeprazole, sodium citrate. 6. Others: antihistamines (promethazine), alpha-2 agonists (clonidine), antibiotic prophylaxis.', '[]'::jsonb, 'Premedication aims to relieve anxiety, provide amnesia and analgesia, dry secretions, prevent vagal bradycardia and reduce the risk of vomiting and acid aspiration. Routine heavy premedication has declined; oral benzodiazepines and targeted antiemetics are now typical.', 'admin', 'published', 5, true, '[["benzodiazepines", "diazepam", "midazolam", "lorazepam", "anxiolytics", "sedatives"], ["opioids", "morphine", "pethidine", "fentanyl"], ["antimuscarinics", "anticholinergics", "atropine", "glycopyrrolate", "glycopyrronium", "hyoscine"], ["antiemetics", "metoclopramide", "ondansetron"], ["h2 blockers", "ranitidine", "omeprazole", "sodium citrate", "antacids"], ["promethazine", "clonidine"]]'::jsonb, 'saq p.097 PP3 Q3, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-6465aac390', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'saq', 'Classify the NSAIDs (non-opioid analgesics), with examples.', '[]'::jsonb, 'Non-selective COX inhibitors: 1. salicylates - aspirin, diflunisal; 2. propionic acid derivatives - ibuprofen, naproxen, ketoprofen; 3. acetic acid derivatives - indomethacin, sulindac (indoles), diclofenac, ketorolac; 4. enolic acids (oxicams) - piroxicam, tenoxicam, meloxicam; 5. fenamates (anthranilic acids) - mefenamic acid; 6. pyrazolones - phenylbutazone, metamizole; 7. non-acidic - nabumetone. Preferential COX-2 inhibitors: meloxicam, nimesulide, etodolac. Selective COX-2 inhibitors (coxibs): celecoxib, etoricoxib, parecoxib. Para-aminophenol derivative (analgesic-antipyretic with weak anti-inflammatory action): paracetamol.', '[]'::jsonb, 'NSAIDs are grouped by chemical structure and by COX selectivity. Structure matters little clinically, but selectivity does: COX-2 selective drugs spare the stomach and platelets at the cost of more thrombotic cardiovascular events.', 'admin', 'published', 5, true, '[["salicylates", "aspirin"], ["propionic acid", "ibuprofen", "naproxen", "ketoprofen"], ["acetic acid", "indomethacin", "diclofenac", "ketorolac", "sulindac"], ["oxicams", "piroxicam", "meloxicam", "enolic acids"], ["fenamates", "mefenamic acid"], ["pyrazolones", "phenylbutazone"], ["coxibs", "celecoxib", "etoricoxib", "cox-2 selective"], ["paracetamol", "para-aminophenol"]]'::jsonb, 'saq p.097 PP3 Q4b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-f24361f443', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'Classify the drugs used in the treatment of acute and chronic gout.', '[]'::jsonb, 'Acute attack: 1. NSAIDs (indomethacin, naproxen, diclofenac; not aspirin); 2. colchicine; 3. corticosteroids (oral prednisolone or intra-articular). Chronic gout (urate-lowering therapy): 4. xanthine oxidase inhibitors, which reduce uric acid synthesis - allopurinol, febuxostat; 5. uricosuric drugs, which increase renal urate excretion - probenecid, sulfinpyrazone, benzbromarone; 6. uricase preparations, which convert uric acid to allantoin - rasburicase, pegloticase. Low-dose colchicine or an NSAID is given as prophylaxis when urate-lowering therapy is started.', '[]'::jsonb, 'Acute treatment suppresses the inflammatory response to urate crystals; chronic treatment lowers serum urate. Urate-lowering drugs should not be started during an attack, since changing urate levels can prolong or precipitate attacks, and low-dose aspirin retains urate.', 'admin', 'published', 5, true, '[["nsaids", "indomethacin", "naproxen", "diclofenac"], ["colchicine"], ["corticosteroids", "prednisolone"], ["xanthine oxidase inhibitors", "allopurinol", "febuxostat"], ["uricosurics", "probenecid", "sulfinpyrazone", "benzbromarone"], ["rasburicase", "pegloticase", "uricase"]]'::jsonb, 'saq p.097 PP3 Q5, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-4b5f64f63a', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Briefly describe the drug treatment of status epilepticus.', '[]'::jsonb, '1. General: secure the airway, give oxygen, check glucose and give intravenous glucose (with thiamine in alcoholics or the malnourished). 2. First line: a benzodiazepine - intravenous lorazepam or diazepam (rectal diazepam or buccal/intramuscular midazolam if there is no venous access), repeated once after 5-10 minutes. 3. Second line: intravenous phenytoin (or fosphenytoin) infusion with ECG monitoring; alternatives are phenobarbital, sodium valproate or levetiracetam. 4. Refractory status: general anaesthesia with thiopental, propofol or midazolam infusion, with ventilation in intensive care.', '[]'::jsonb, 'Benzodiazepines act fastest because they enhance GABA and enter the brain quickly, but diazepam redistributes within minutes, so a longer-acting drug such as phenytoin must follow. Phenytoin is infused slowly because rapid injection causes hypotension and arrhythmias.', 'admin', 'published', 4, true, '[["airway", "oxygen", "glucose", "thiamine"], ["lorazepam", "diazepam", "midazolam", "benzodiazepine"], ["phenytoin", "fosphenytoin"], ["phenobarbital", "valproate", "levetiracetam"], ["thiopental", "propofol", "general anaesthesia", "midazolam infusion", "icu"]]'::jsonb, 'saq p.098 PP3 Q8b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-6b22dd09a7', 'pharm-alkylating-agents', 'saq', 'List 10 adverse effects of alkylating agents.', '[]'::jsonb, 'Any 10 of: bone marrow suppression (leucopenia, thrombocytopenia, anaemia); nausea and vomiting; alopecia; mucositis and oral ulceration; immunosuppression and infections; infertility (amenorrhoea, azoospermia); teratogenicity; secondary malignancies, especially acute myeloid leukaemia; haemorrhagic cystitis (cyclophosphamide, ifosfamide - prevented by mesna); pulmonary fibrosis (busulfan, carmustine); skin hyperpigmentation (busulfan); nephrotoxicity and neurotoxicity (ifosfamide, cisplatin); SIADH (cyclophosphamide); hepatic veno-occlusive disease (busulfan); hyperuricaemia (tumour lysis).', '[]'::jsonb, 'Alkylating agents damage DNA in all dividing cells, so marrow, gut epithelium, hair follicles and gonads suffer most, and the surviving cells carry mutations that cause later leukaemias. Acrolein, a metabolite of cyclophosphamide, irritates the bladder; mesna inactivates it.', 'admin', 'published', 5, true, '[["bone marrow suppression", "myelosuppression", "leucopenia", "thrombocytopenia"], ["nausea", "vomiting"], ["alopecia", "hair loss"], ["mucositis", "oral ulcers"], ["infections", "immunosuppression"], ["infertility", "amenorrhoea", "azoospermia", "sterility"], ["teratogenic", "teratogenicity"], ["secondary leukaemia", "secondary malignancy", "carcinogenic"], ["haemorrhagic cystitis", "hemorrhagic cystitis"], ["pulmonary fibrosis"], ["hyperpigmentation"], ["nephrotoxicity", "neurotoxicity"], ["siadh", "hyperuricaemia", "veno-occlusive disease"]]'::jsonb, 'saq p.098 PP3 Q12, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-ec722f1d72', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Classify anticonvulsant agents according to the types of epilepsy in which they are indicated and contraindicated.', '[]'::jsonb, 'Focal (partial) seizures with or without secondary generalisation: carbamazepine, lamotrigine, levetiracetam, oxcarbazepine, phenytoin, valproate. Generalised tonic-clonic seizures: sodium valproate, lamotrigine, levetiracetam, carbamazepine, phenytoin, phenobarbital. Absence seizures: ethosuximide, sodium valproate (lamotrigine). Myoclonic seizures: sodium valproate, levetiracetam, clonazepam, topiramate. Atonic/tonic seizures: valproate, lamotrigine. Status epilepticus: lorazepam or diazepam, then phenytoin. Contraindicated: carbamazepine, phenytoin, vigabatrin, gabapentin and tiagabine worsen absence and myoclonic seizures; ethosuximide is ineffective in tonic-clonic seizures; valproate is avoided in women of childbearing potential and in liver disease.', '[]'::jsonb, 'Choice follows seizure type: sodium channel blockers suit focal seizures, drugs acting on T-type calcium channels suit absences, and broad-spectrum drugs (valproate, lamotrigine, levetiracetam) suit generalised epilepsies. Using a narrow-spectrum drug in the wrong epilepsy can aggravate it.', 'admin', 'published', 5, true, '[["focal", "partial seizures", "carbamazepine", "lamotrigine", "levetiracetam"], ["tonic-clonic", "generalised", "valproate"], ["absence", "ethosuximide"], ["myoclonic", "clonazepam", "levetiracetam"], ["status epilepticus", "lorazepam", "diazepam"], ["carbamazepine worsens absence", "phenytoin worsens absence", "worsen myoclonic", "avoid carbamazepine"], ["valproate in pregnancy", "women of childbearing age", "teratogenic"]]'::jsonb, 'saq p.098 PP3 Q14, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-9eab407330', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'saq', 'Outline the synthesis, storage, release and disposition of acetylcholine. For each process, name a drug or agent which interferes with it.', '[]'::jsonb, '1. Choline uptake into the nerve terminal by a sodium-dependent carrier (rate-limiting) - blocked by hemicholinium. 2. Synthesis from choline and acetyl-CoA by choline acetyltransferase. 3. Storage in vesicles by the vesicular acetylcholine transporter - blocked by vesamicol. 4. Release by calcium-dependent exocytosis when an action potential arrives - blocked by botulinum toxin (and by magnesium and aminoglycosides); black widow spider venom (latrotoxin) causes massive release. 5. Action on nicotinic and muscarinic receptors - blocked by tubocurarine and atropine respectively. 6. Disposition: rapid hydrolysis by acetylcholinesterase to choline and acetate, with choline taken up again - inhibited by neostigmine, physostigmine and organophosphates.', '[]'::jsonb, 'Unlike noradrenaline, acetylcholine''s action is ended by enzymatic destruction, not reuptake of the transmitter; only choline is recycled. Clinically the useful targets are release (botulinum toxin), the receptors and cholinesterase.', 'admin', 'published', 5, true, '[["choline uptake", "hemicholinium"], ["choline acetyltransferase", "acetyl-coa"], ["vesicles", "vesamicol", "storage"], ["exocytosis", "calcium", "botulinum toxin", "latrotoxin"], ["acetylcholinesterase", "hydrolysis", "neostigmine", "physostigmine", "organophosphates"], ["choline reuptake", "recycled"]]'::jsonb, 'saq p.098 PP3 Q15, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-d5dbaba7dc', 'pharm-antiarrhythmic-drugs', 'saq', 'Classify anti-arrhythmic drugs according to Vaughan-Williams, giving examples in each class and the main mechanism of action of each class.', '[]'::jsonb, 'Class I - sodium channel blockers (slow phase 0 depolarisation): IA quinidine, procainamide, disopyramide (prolong the action potential); IB lidocaine, mexiletine, phenytoin (shorten it); IC flecainide, propafenone (no effect on duration). Class II - beta-blockers (reduce sympathetic drive, slow SA and AV nodes): propranolol, metoprolol, esmolol. Class III - potassium channel blockers (prolong repolarisation and refractory period): amiodarone, sotalol, dofetilide, ibutilide. Class IV - calcium channel blockers (slow AV nodal conduction): verapamil, diltiazem. Unclassified: adenosine, digoxin, magnesium, atropine.', '[]'::jsonb, 'The classification follows the phase of the cardiac action potential affected. It is imperfect: amiodarone has actions of all four classes and sotalol of classes II and III. All anti-arrhythmics can themselves cause arrhythmias.', 'admin', 'published', 5, true, '[["class i", "sodium channel blockers", "quinidine", "procainamide", "lidocaine", "lignocaine", "flecainide"], ["class ii", "beta blockers", "propranolol", "metoprolol", "esmolol"], ["class iii", "potassium channel blockers", "amiodarone", "sotalol"], ["class iv", "calcium channel blockers", "verapamil", "diltiazem"], ["adenosine", "digoxin", "magnesium"], ["prolong repolarisation", "slow av conduction", "phase 0"]]'::jsonb, 'saq p.098 PP4 Q1, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-708f3079ab', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Give 3 adverse effects of minoxidil.', '[]'::jsonb, 'Any 3 of: hypertrichosis (excess hair growth); reflex tachycardia and palpitations (may provoke angina); sodium and water retention with oedema and weight gain; pericardial effusion; headache and flushing; ECG T-wave changes.', '[]'::jsonb, 'As a potent arteriolar dilator, minoxidil triggers baroreflex tachycardia and renin-driven fluid retention, so it is always given with a beta-blocker and a loop diuretic. Its potassium-channel opening action on hair follicles causes hypertrichosis.', 'admin', 'published', 3, true, '[["hypertrichosis", "hirsutism", "hair growth"], ["reflex tachycardia", "tachycardia", "palpitations", "angina"], ["fluid retention", "oedema", "sodium and water retention", "weight gain"], ["pericardial effusion"], ["headache", "flushing"]]'::jsonb, 'saq p.098 PP4 Q2a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-d23dae8c5b', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'Give 3 adverse effects of captopril.', '[]'::jsonb, 'Any 3 of: dry persistent cough; first-dose hypotension; hyperkalaemia; acute renal failure (in bilateral renal artery stenosis); angioedema; taste disturbance (dysgeusia); skin rash; proteinuria; neutropenia; fetotoxicity (contraindicated in pregnancy).', '[]'::jsonb, 'Cough and angioedema are due to bradykinin accumulation, hyperkalaemia to reduced aldosterone, and renal failure to loss of angiotensin II-mediated efferent arteriolar tone. Taste disturbance, rash, proteinuria and neutropenia are attributed to captopril''s sulphydryl group.', 'admin', 'published', 3, true, '[["cough", "dry cough"], ["hypotension", "first-dose hypotension"], ["hyperkalaemia", "hyperkalemia"], ["renal failure", "renal impairment"], ["angioedema"], ["taste disturbance", "dysgeusia", "loss of taste"], ["rash"], ["proteinuria", "neutropenia"], ["teratogenic", "fetotoxic"]]'::jsonb, 'saq p.098 PP4 Q2b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-2960ce102d', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'saq', 'Give 3 adverse effects of alpha-methyldopa.', '[]'::jsonb, 'Any 3 of: sedation and drowsiness; depression; dry mouth; postural hypotension; positive direct Coombs test and haemolytic anaemia; hepatitis (drug-induced liver injury); drug fever; fluid retention; hyperprolactinaemia (gynaecomastia, galactorrhoea); impotence; nasal congestion; rebound hypertension on withdrawal (less than with clonidine).', '[]'::jsonb, 'Central alpha-2 stimulation explains the sedation, dry mouth and depression. Up to 20% of patients develop a positive Coombs test through IgG autoantibodies against red cells, but frank haemolysis is rare.', 'admin', 'published', 3, true, '[["sedation", "drowsiness"], ["depression"], ["dry mouth"], ["postural hypotension"], ["positive coombs test", "haemolytic anaemia", "hemolytic anemia"], ["hepatitis", "hepatotoxicity"], ["fever"], ["fluid retention", "oedema"], ["gynaecomastia", "galactorrhoea", "hyperprolactinaemia", "impotence"]]'::jsonb, 'saq p.098 PP4 Q2c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-0e399a6371', 'pharm-adrenoceptor-blockers', 'saq', 'Prazosin lowers blood pressure by selectively blocking which receptor?', '[]'::jsonb, 'Alpha-1 adrenoceptor', '["alpha-1 receptor", "α1 adrenoceptor", "alpha 1 adrenergic receptor", "α1 receptor", "alpha-1", "alpha1 adrenoceptors", "postsynaptic alpha-1 receptor"]'::jsonb, 'Prazosin competitively blocks postsynaptic alpha-1 receptors on arterioles and veins, reducing peripheral resistance and venous return. Because presynaptic alpha-2 receptors are spared, noradrenaline release stays under feedback control and there is little reflex tachycardia. First-dose hypotension is its main hazard.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.098 PP4 Q3a, JB revision SAQs. Reworded from ''Describe the mechanism of action of prazosin''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-977ebafbb2', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Describe the mechanism of action of prednisolone.', '[]'::jsonb, 'Prednisolone is a glucocorticoid. It diffuses into the cell and binds the cytoplasmic glucocorticoid receptor, which releases heat-shock proteins, dimerises and moves to the nucleus. There it binds glucocorticoid response elements to increase transcription of anti-inflammatory proteins (transactivation), e.g. annexin-1 (lipocortin), which inhibits phospholipase A2, and it represses transcription factors such as NF-kB and AP-1 (transrepression), reducing synthesis of COX-2, cytokines (IL-1, IL-2, TNF-alpha), adhesion molecules and inducible nitric oxide synthase.', '[]'::jsonb, 'Because the effects require altered gene transcription and protein synthesis, they take hours to appear even after intravenous dosing. Inhibiting phospholipase A2 blocks both prostaglandin and leukotriene pathways, which is one reason steroids are broader anti-inflammatory agents than NSAIDs.', 'admin', 'published', 3, true, '[["glucocorticoid receptor", "intracellular receptor", "cytoplasmic receptor"], ["nucleus", "translocates", "gene transcription", "glucocorticoid response elements"], ["annexin", "lipocortin", "phospholipase a2"], ["nf-kb", "transrepression", "ap-1"], ["reduces cytokines", "cox-2", "interleukins", "tnf"]]'::jsonb, 'saq p.098 PP4 Q3e, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-19691755b2', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'Write short notes on the pharmacokinetics of digoxin.', '[]'::jsonb, 'Oral bioavailability about 70% (tablets), with onset in 1-2 hours; about 25% protein bound; very large volume of distribution (about 6-7 L/kg) because of binding to skeletal muscle and heart, so it is not removed by dialysis and needs a loading dose for rapid effect; excreted mainly unchanged by the kidneys (glomerular filtration and P-glycoprotein-mediated tubular secretion), so the dose is reduced in renal impairment and in the elderly; half-life 36-40 hours; narrow therapeutic range (about 0.8-2 ng/ml). Quinidine, verapamil and amiodarone raise its levels.', '[]'::jsonb, 'The long half-life means steady state takes about a week without a loading dose. Dosing should be based on lean body mass and renal function; drugs that inhibit P-glycoprotein reduce digoxin clearance and precipitate toxicity.', 'admin', 'published', 4, true, '[["bioavailability", "70%"], ["large volume of distribution", "tissue binding", "skeletal muscle"], ["low protein binding", "25%"], ["renal excretion", "excreted unchanged", "kidney"], ["half-life", "36 hours", "40 hours"], ["narrow therapeutic index", "narrow therapeutic range"], ["loading dose", "p-glycoprotein", "renal impairment"]]'::jsonb, 'saq p.098 PP4 Q5a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-446eb61924', 'pharm-antidepressants-and-lithium', 'saq', 'Classify antidepressants, with examples.', '[]'::jsonb, '1. Tricyclic antidepressants: amitriptyline, imipramine, clomipramine, nortriptyline. 2. Selective serotonin reuptake inhibitors (SSRIs): fluoxetine, sertraline, paroxetine, citalopram, escitalopram. 3. Serotonin-noradrenaline reuptake inhibitors (SNRIs): venlafaxine, duloxetine. 4. Monoamine oxidase inhibitors: irreversible non-selective - phenelzine, tranylcypromine; reversible MAO-A selective - moclobemide. 5. Atypical agents: mirtazapine (alpha-2 antagonist), trazodone (5-HT2 antagonist and reuptake inhibitor), bupropion (noradrenaline-dopamine reuptake inhibitor), reboxetine (noradrenaline reuptake inhibitor), mianserin, agomelatine.', '[]'::jsonb, 'All these drugs increase synaptic monoamines, by blocking reuptake, blocking breakdown or blocking inhibitory autoreceptors, yet the clinical effect takes 2 to 4 weeks. SSRIs are first line because they are much safer in overdose than tricyclics and MAO inhibitors.', 'admin', 'published', 5, true, '[["tricyclic antidepressants", "tcas", "amitriptyline", "imipramine", "clomipramine", "nortriptyline"], ["ssris", "fluoxetine", "sertraline", "paroxetine", "citalopram"], ["snris", "venlafaxine", "duloxetine"], ["mao inhibitors", "maois", "phenelzine", "tranylcypromine", "moclobemide"], ["mirtazapine", "trazodone", "bupropion", "reboxetine", "atypical"]]'::jsonb, 'saq p.098 PP4 Q6, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-905938b0c1', 'pharm-antidepressants-and-lithium', 'saq', 'Describe the mechanism of action of amitriptyline.', '[]'::jsonb, 'Amitriptyline is a tricyclic antidepressant that blocks the neuronal reuptake transporters for noradrenaline (NET) and serotonin (SERT), increasing their concentrations in the synaptic cleft; with long-term use receptors adapt (down-regulation of beta and 5-HT2 receptors), which parallels the delayed clinical effect. It also blocks muscarinic, histamine H1 and alpha-1 adrenergic receptors and cardiac sodium channels, which accounts for its adverse effects.', '[]'::jsonb, 'Reuptake inhibition occurs within hours, but mood improves only after weeks, implying that slow adaptive changes are what matter. The ''dirty'' receptor profile explains dry mouth and constipation (muscarinic), sedation (H1), postural hypotension (alpha-1) and arrhythmias in overdose.', 'admin', 'published', 2, true, '[["blocks reuptake", "reuptake inhibitor", "inhibits reuptake"], ["noradrenaline", "norepinephrine", "net"], ["serotonin", "5-ht", "sert"], ["muscarinic", "histamine h1", "alpha-1", "receptor blockade"], ["down-regulation", "adaptive changes", "delayed effect"]]'::jsonb, 'saq p.098 PP4 Q7, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-caf8eaf0a2', 'pharm-antidepressants-and-lithium', 'saq', 'List 4 adverse effects of tricyclic antidepressants.', '[]'::jsonb, 'Any 4 of: antimuscarinic effects - dry mouth, blurred vision, constipation, urinary retention; sedation; postural hypotension; tachycardia, arrhythmias and heart block (dangerous in overdose); weight gain; lowering of the seizure threshold; sexual dysfunction; confusion in the elderly; precipitation of mania.', '[]'::jsonb, 'Each effect maps to a receptor: muscarinic blockade (dry mouth, constipation, retention), H1 blockade (sedation, weight gain), alpha-1 blockade (postural hypotension) and a quinidine-like sodium channel block (arrhythmias), which makes overdose lethal; sodium bicarbonate is the treatment.', 'admin', 'published', 4, true, '[["dry mouth", "blurred vision", "antimuscarinic", "anticholinergic"], ["constipation", "urinary retention"], ["sedation", "drowsiness"], ["postural hypotension"], ["arrhythmias", "tachycardia", "cardiotoxicity", "qt prolongation"], ["weight gain"], ["seizures", "lowered seizure threshold"], ["sexual dysfunction", "confusion"]]'::jsonb, 'saq p.102 2012/13 Q2e, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--1369e40794', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'saq', 'Classify penicillins, giving examples in each class.', '[]'::jsonb, '1. Natural penicillins (narrow spectrum, beta-lactamase sensitive): benzylpenicillin (penicillin G), phenoxymethylpenicillin (penicillin V); depot forms - procaine and benzathine penicillin. 2. Antistaphylococcal (beta-lactamase resistant) penicillins: flucloxacillin, cloxacillin, methicillin, nafcillin. 3. Aminopenicillins (extended spectrum): ampicillin, amoxicillin. 4. Antipseudomonal penicillins: carboxypenicillins (carbenicillin, ticarcillin) and ureidopenicillins (piperacillin, mezlocillin). 5. Combinations with beta-lactamase inhibitors: amoxicillin-clavulanate, ampicillin-sulbactam, piperacillin-tazobactam.', '[]'::jsonb, 'The side chain determines the properties: bulky side chains protect the beta-lactam ring from staphylococcal penicillinase, while amino, carboxyl and ureido groups improve penetration through Gram-negative porins and so widen the spectrum.', 'admin', 'published', 5, true, '[["natural penicillins", "benzylpenicillin", "penicillin g", "penicillin v", "benzathine penicillin"], ["antistaphylococcal", "flucloxacillin", "cloxacillin", "methicillin", "nafcillin"], ["aminopenicillins", "ampicillin", "amoxicillin"], ["antipseudomonal", "carbenicillin", "ticarcillin", "piperacillin", "ureidopenicillins", "carboxypenicillins"], ["clavulanate", "sulbactam", "tazobactam", "beta-lactamase inhibitors"]]'::jsonb, 'saq p.098 PP4 Q8, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--9dd3a55f50', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'saq', 'Write brief notes on the routes of administration and pharmacokinetics of ampicillin.', '[]'::jsonb, 'Routes: oral (acid stable), intramuscular and intravenous. Absorption: oral bioavailability is only about 40% and is reduced by food, so it is taken on an empty stomach (amoxicillin is better absorbed). Distribution: low protein binding (about 20%); distributes widely in body fluids, crosses the placenta and penetrates inflamed meninges. Elimination: excreted mostly unchanged in urine by tubular secretion (blocked by probenecid), with significant biliary excretion and enterohepatic circulation; half-life about 1 hour, prolonged in renal failure.', '[]'::jsonb, 'Unabsorbed ampicillin disturbs the gut flora and causes diarrhoea, one reason amoxicillin replaced it for oral use. High biliary concentrations made it useful in typhoid carriers and biliary infection; the short half-life requires six-hourly dosing.', 'admin', 'published', 3, true, '[["oral", "intramuscular", "intravenous"], ["bioavailability 40%", "incomplete absorption", "reduced by food", "empty stomach"], ["low protein binding", "widely distributed", "crosses inflamed meninges"], ["renal excretion", "tubular secretion", "excreted unchanged", "probenecid"], ["biliary excretion", "enterohepatic"], ["half-life 1 hour"]]'::jsonb, 'saq p.098 PP4 Q9, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-7e260e584e', 'pharm-adrenoceptor-blockers', 'saq', 'Classify adrenergic receptor blockers, giving 2 examples of each class.', '[]'::jsonb, 'Alpha-blockers: non-selective - phenoxybenzamine (irreversible), phentolamine (reversible); alpha-1 selective - prazosin, doxazosin, terazosin, tamsulosin; alpha-2 selective - yohimbine. Beta-blockers: non-selective (beta-1 and beta-2) - propranolol, timolol, nadolol, sotalol; cardioselective (beta-1) - atenolol, metoprolol, bisoprolol, esmolol; with intrinsic sympathomimetic activity - pindolol, acebutolol, oxprenolol; with additional vasodilator action - labetalol and carvedilol (alpha and beta blockade), nebivolol (nitric oxide release).', '[]'::jsonb, 'Selectivity determines use and side effects: alpha-1 selective drugs avoid the tachycardia of non-selective alpha blockade, and beta-1 selective drugs are safer (not safe) in airways and peripheral vascular disease. Labetalol and carvedilol add vasodilatation by alpha-1 blockade.', 'admin', 'published', 5, true, '[["phenoxybenzamine", "phentolamine", "non-selective alpha"], ["prazosin", "doxazosin", "terazosin", "tamsulosin", "alpha-1 selective"], ["yohimbine", "alpha-2"], ["propranolol", "timolol", "nadolol", "sotalol", "non-selective beta"], ["atenolol", "metoprolol", "bisoprolol", "esmolol", "cardioselective"], ["pindolol", "acebutolol", "oxprenolol", "intrinsic sympathomimetic activity"], ["labetalol", "carvedilol", "nebivolol"]]'::jsonb, 'saq p.098 PP4 Q10a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-da2159a827', 'pharm-adrenoceptor-blockers', 'saq', 'What are the general contraindications to the use of beta-adrenoceptor blockers?', '[]'::jsonb, 'Any 3 of: bronchial asthma and severe COPD (bronchospasm); second- or third-degree heart block and sick sinus syndrome; severe bradycardia; acute or decompensated heart failure and cardiogenic shock; severe peripheral vascular disease and Raynaud''s phenomenon; Prinzmetal (vasospastic) angina; untreated phaeochromocytoma (without an alpha-blocker); with intravenous verapamil; caution in insulin-treated diabetes (mask hypoglycaemia).', '[]'::jsonb, 'Contraindications mirror the receptor blockade: beta-2 block causes bronchospasm and vasoconstriction, beta-1 block slows the nodes and depresses contractility. In phaeochromocytoma, beta blockade alone leaves alpha vasoconstriction unopposed and causes a hypertensive crisis.', 'admin', 'published', 3, true, '[["asthma", "copd", "bronchospasm"], ["heart block", "sick sinus syndrome"], ["bradycardia"], ["acute heart failure", "decompensated heart failure", "cardiogenic shock"], ["peripheral vascular disease", "raynaud''s"], ["prinzmetal angina", "vasospastic angina"], ["phaeochromocytoma", "pheochromocytoma"], ["diabetes", "hypoglycaemia", "verapamil"]]'::jsonb, 'saq p.098 PP4 Q10b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-604d68a654', 'pharm-adrenoceptor-blockers', 'saq', 'With respect to beta-adrenoceptor antagonists, what do you understand by: cardioselectivity, quinidine-like effect, negative inotropic effect, and intrinsic sympathomimetic activity?', '[]'::jsonb, 'Cardioselectivity: greater affinity for beta-1 (cardiac) than beta-2 receptors, e.g. atenolol, metoprolol, bisoprolol; relative and lost at high doses. Quinidine-like (membrane-stabilising, local anaesthetic) effect: blockade of sodium channels at high concentrations, unrelated to beta blockade, e.g. propranolol; relevant in overdose. Negative inotropic effect: reduction in the force of myocardial contraction through blockade of cardiac beta-1 receptors; may precipitate heart failure. Intrinsic sympathomimetic activity: partial agonist activity - the drug weakly stimulates beta receptors while blocking the effect of catecholamines, e.g. pindolol, acebutolol, oxprenolol; causes less resting bradycardia.', '[]'::jsonb, 'These properties distinguish individual beta-blockers. Cardioselectivity reduces bronchospasm and metabolic effects; partial agonists cause less bradycardia but are less protective after myocardial infarction; membrane stabilisation matters only in overdose and with topical eye use.', 'admin', 'published', 4, true, '[["beta-1 selective", "cardioselective", "atenolol", "metoprolol", "bisoprolol"], ["membrane stabilising", "membrane-stabilizing", "sodium channel block", "local anaesthetic effect"], ["reduced contractility", "decreased force of contraction", "heart failure"], ["partial agonist", "pindolol", "acebutolol", "oxprenolol"], ["less bradycardia"]]'::jsonb, 'saq p.098 PP4 Q11, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-e1c6164c54', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'saq', 'Write short notes on the stages of anaesthesia.', '[]'::jsonb, 'Guedel''s stages (described for ether): Stage I - analgesia: from induction to loss of consciousness; analgesia without amnesia. Stage II - excitement (delirium): from loss of consciousness to the onset of regular breathing; irregular respiration, struggling, vomiting, laryngospasm, dilated pupils. Stage III - surgical anaesthesia: regular breathing to respiratory arrest, divided into four planes with progressive loss of reflexes, muscle relaxation and shallower breathing. Stage IV - medullary paralysis: depression of the respiratory and vasomotor centres, apnoea, circulatory collapse and death unless supported.', '[]'::jsonb, 'Stage II is dangerous and is passed quickly by using intravenous induction agents. With modern balanced anaesthesia, premedication and muscle relaxants, the classical signs are obscured, and depth is judged by blood pressure, heart rate, movement and monitoring.', 'admin', 'published', 4, true, '[["stage i", "analgesia"], ["stage ii", "excitement", "delirium"], ["stage iii", "surgical anaesthesia", "four planes"], ["stage iv", "medullary paralysis", "medullary depression", "respiratory arrest"], ["guedel", "ether"]]'::jsonb, 'saq p.099 PP5 Q7a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-65be088ce9', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'Discuss the advantages and disadvantages of using ACE inhibitors as antihypertensive drugs.', '[]'::jsonb, 'Advantages: effective and well tolerated with once-daily dosing (most); no reflex tachycardia, postural hypotension, sedation or sexual dysfunction; no adverse effect on lipids, glucose or uric acid; reduce mortality in heart failure and after myocardial infarction and regress left ventricular hypertrophy; slow diabetic and other proteinuric nephropathy; counter thiazide-induced hypokalaemia. Disadvantages: dry cough; angioedema; first-dose hypotension; hyperkalaemia (especially with potassium-sparing diuretics or renal impairment); acute renal failure in bilateral renal artery stenosis; contraindicated in pregnancy (fetal renal damage); less effective as monotherapy in black patients; rash and taste disturbance.', '[]'::jsonb, 'ACE inhibitors lower pressure by reducing angiotensin II and aldosterone and raising bradykinin, with organ-protective benefits beyond blood pressure. The same mechanisms cause cough and angioedema (bradykinin), hyperkalaemia (aldosterone) and renal failure when filtration depends on efferent tone.', 'admin', 'published', 4, true, '[["no reflex tachycardia", "well tolerated", "no metabolic effects"], ["heart failure", "post-myocardial infarction", "reduce mortality", "ventricular hypertrophy"], ["diabetic nephropathy", "renoprotective", "reduce proteinuria"], ["cough"], ["angioedema"], ["hyperkalaemia", "hyperkalemia"], ["renal artery stenosis", "renal failure"], ["pregnancy", "teratogenic", "fetotoxic"], ["first-dose hypotension", "less effective in black patients"]]'::jsonb, 'saq p.099 PP5 Q8, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-heavy-metal-poisoning-bad747c731', 'pharm-heavy-metal-poisoning', 'saq', 'List 5 heavy metals that cause poisoning.', '[]'::jsonb, 'Any 5 of: lead; mercury; arsenic; iron; cadmium; copper; thallium; gold; antimony; chromium.', '[]'::jsonb, 'Heavy metals bind sulphydryl and other groups on enzymes and are treated with chelators: dimercaprol (arsenic, mercury, lead), calcium disodium edetate and succimer (lead), penicillamine (copper) and desferrioxamine (iron). Lead, mercury and arsenic are the commonest causes of chronic occupational and environmental poisoning.', 'admin', 'published', 5, true, '[["lead"], ["mercury"], ["arsenic"], ["iron"], ["cadmium"], ["copper"], ["thallium"], ["gold", "antimony", "chromium", "bismuth"]]'::jsonb, 'saq p.102 2012/13 Q1a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-46750d8217', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'Describe the renin-angiotensin-aldosterone system (RAAS).', '[]'::jsonb, 'Renin is released from the juxtaglomerular cells of the kidney in response to reduced renal perfusion pressure, reduced sodium delivery to the macula densa and sympathetic (beta-1) stimulation. Renin cleaves angiotensinogen (from the liver) to the decapeptide angiotensin I. Angiotensin-converting enzyme (ACE), mainly in pulmonary endothelium, converts this to the octapeptide angiotensin II (ACE also inactivates bradykinin). Angiotensin II acts on AT1 receptors to cause vasoconstriction, aldosterone secretion from the adrenal cortex, ADH release, thirst and sympathetic activation. Aldosterone increases sodium and water reabsorption and potassium excretion in the collecting duct. The result is a rise in blood pressure and volume, which inhibits further renin release.', '[]'::jsonb, 'The system defends blood pressure and volume, but is harmfully over-active in hypertension and heart failure. Every step can be blocked: beta-blockers and aliskiren (renin), ACE inhibitors, angiotensin receptor blockers and aldosterone antagonists.', 'admin', 'published', 4, true, '[["renin", "juxtaglomerular"], ["angiotensinogen", "angiotensin i"], ["ace", "angiotensin-converting enzyme", "lungs"], ["angiotensin ii", "at1 receptor"], ["vasoconstriction"], ["aldosterone", "sodium retention", "sodium and water retention"], ["negative feedback", "bradykinin", "adh"]]'::jsonb, 'saq p.102 2012/13 Q1b(i), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-c7ba85aad5', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'Give examples of drugs acting on the renin-angiotensin-aldosterone system, with the indications of each.', '[]'::jsonb, '1. ACE inhibitors (captopril, enalapril, lisinopril, ramipril): hypertension, heart failure, post-myocardial infarction, diabetic nephropathy. 2. Angiotensin II (AT1) receptor blockers (losartan, valsartan, candesartan): the same indications, especially when ACE inhibitors cause cough. 3. Direct renin inhibitor (aliskiren): hypertension. 4. Aldosterone (mineralocorticoid receptor) antagonists (spironolactone, eplerenone): heart failure, resistant hypertension, primary hyperaldosteronism, oedema and ascites of cirrhosis. 5. Beta-blockers reduce renin release (hypertension). 6. Neprilysin inhibitor with ARB (sacubitril-valsartan): heart failure.', '[]'::jsonb, 'Blocking the system lowers blood pressure, reduces afterload and preload, and prevents the cardiac and renal remodelling driven by angiotensin II and aldosterone, which is why these drugs improve survival in heart failure and slow proteinuric kidney disease.', 'admin', 'published', 4, true, '[["ace inhibitors", "captopril", "enalapril", "lisinopril", "ramipril"], ["arbs", "angiotensin receptor blockers", "losartan", "valsartan", "candesartan"], ["aliskiren", "renin inhibitor"], ["spironolactone", "eplerenone", "aldosterone antagonists"], ["hypertension"], ["heart failure"], ["diabetic nephropathy", "post-myocardial infarction", "ascites", "hyperaldosteronism"]]'::jsonb, 'saq p.102 2012/13 Q1b(iii), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-41deb5bf34', 'pharm-antiretroviral-ii', 'saq', 'List 4 non-nucleoside reverse transcriptase inhibitors.', '[]'::jsonb, 'Any 4 of: nevirapine; efavirenz; etravirine; rilpivirine; delavirdine; doravirine.', '[]'::jsonb, 'NNRTIs bind an allosteric pocket near the active site of HIV-1 reverse transcriptase and need no phosphorylation. They are inactive against HIV-2. Nevirapine, efavirenz and delavirdine are first generation; etravirine, rilpivirine and doravirine are later drugs with higher barriers to resistance.', 'admin', 'published', 4, true, '[["nevirapine"], ["efavirenz"], ["etravirine"], ["rilpivirine"], ["delavirdine"], ["doravirine"]]'::jsonb, 'saq p.102 2012/13 Q2a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-3ac69e7ea7', 'pharm-anti-retrovirals', 'saq', 'List 3 antiretroviral drugs used as a first-line regimen in HIV/hepatitis B virus co-infection.', '[]'::jsonb, 'Tenofovir + lamivudine (or emtricitabine) + efavirenz (older guidelines) or dolutegravir (current guidelines). The regimen must contain two drugs active against hepatitis B: tenofovir with lamivudine or emtricitabine.', '[]'::jsonb, 'Tenofovir and lamivudine (or emtricitabine) suppress both viruses. Lamivudine as the only HBV-active drug selects resistant HBV within a few years, and stopping these drugs can cause a severe hepatitis flare, so tenofovir is kept in every subsequent regimen.', 'admin', 'draft', 3, true, '[["tenofovir", "tdf"], ["lamivudine", "3tc", "emtricitabine", "ftc"], ["efavirenz", "dolutegravir", "efv", "dtg"]]'::jsonb, 'saq p.102 2012/13 Q2b, JB revision SAQs. Guideline-dependent third drug: efavirenz at the time of the paper (2012/13), dolutegravir now.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-7c59e74bd8', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'Give 4 distinct indications of aspirin and the mechanism of action in each.', '[]'::jsonb, '1. Analgesia (mild to moderate pain): inhibition of COX reduces prostaglandins (PGE2, PGI2) that sensitise nociceptors to bradykinin. 2. Antipyretic: reduces PGE2 synthesis in the hypothalamus, resetting the thermoregulatory set-point. 3. Anti-inflammatory (rheumatic fever, rheumatoid arthritis, Kawasaki disease; high dose): reduces prostaglandin-mediated vasodilatation, oedema and pain. 4. Antiplatelet (prevention of myocardial infarction, stroke and TIA; low dose): irreversible acetylation of platelet COX-1 blocks thromboxane A2 synthesis for the life of the platelet. Others: prevention of pre-eclampsia; reduction of colorectal cancer risk.', '[]'::jsonb, 'All four actions come from irreversible acetylation of cyclo-oxygenase, at different sites and doses. Platelets have no nucleus and cannot make new enzyme, so a low dose gives lasting antiplatelet effect while endothelial prostacyclin synthesis recovers.', 'admin', 'published', 4, true, '[["analgesic", "pain", "headache"], ["antipyretic", "fever", "hypothalamus"], ["anti-inflammatory", "rheumatic fever", "rheumatoid arthritis", "kawasaki"], ["antiplatelet", "myocardial infarction", "stroke", "thromboxane a2"], ["cox inhibition", "irreversible acetylation", "prostaglandin synthesis inhibition"], ["pre-eclampsia", "colorectal cancer"]]'::jsonb, 'saq p.102 2012/13 Q2d, JB revision SAQs. Covers the MBChB EOY 2015/2016 Q4e (''Apart from pain, list three other uses of aspirin'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-cab295d95b', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'saq', 'Give 5 indications of ergot alkaloids and name the specific drug used for each.', '[]'::jsonb, 'Any 5 of: acute migraine attack - ergotamine, dihydroergotamine; postpartum haemorrhage (and uterine involution) - ergometrine (ergonovine), methylergometrine; hyperprolactinaemia and suppression of lactation - bromocriptine, cabergoline; Parkinson''s disease - bromocriptine, pergolide, cabergoline; acromegaly - bromocriptine; migraine prophylaxis - methysergide; senile cerebral insufficiency/dementia - co-dergocrine (dihydroergotoxine); carcinoid syndrome - methysergide; diagnosis of variant angina - ergometrine.', '[]'::jsonb, 'Ergot alkaloids are partial agonists or antagonists at alpha-adrenergic, serotonin and dopamine receptors, and different members favour different receptors: vasoconstriction (ergotamine), uterine contraction (ergometrine) and dopamine D2 agonism (bromocriptine). Prolonged use risks ergotism (peripheral ischaemia and gangrene) and fibrotic reactions.', 'admin', 'published', 5, true, '[["migraine", "ergotamine", "dihydroergotamine"], ["postpartum haemorrhage", "pph", "ergometrine", "ergonovine", "methylergometrine"], ["hyperprolactinaemia", "prolactinoma", "suppression of lactation", "bromocriptine", "cabergoline"], ["parkinson''s disease", "pergolide"], ["acromegaly"], ["migraine prophylaxis", "methysergide"], ["dementia", "co-dergocrine", "dihydroergotoxine"]]'::jsonb, 'saq p.102 2012/13 Q3a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-22bb6d69be', 'pharm-adrenoceptor-blockers', 'saq', 'Give 4 mechanisms by which beta-blockers reduce blood pressure (and, in the long term, peripheral vascular resistance).', '[]'::jsonb, 'Any 4 of: reduced cardiac output (lower heart rate and contractility, beta-1 blockade); reduced renin release from the juxtaglomerular cells (beta-1), lowering angiotensin II and aldosterone; reduced central sympathetic outflow (lipid-soluble drugs); blockade of presynaptic beta-2 receptors, reducing noradrenaline release; resetting of baroreceptors; additional vasodilatation with some drugs (alpha-1 blockade by labetalol and carvedilol, nitric oxide release by nebivolol).', '[]'::jsonb, 'The initial fall in pressure is due to reduced cardiac output, with peripheral resistance reflexly raised; over weeks resistance falls, largely because renin release is suppressed. Beta-blockers therefore work best in high-renin hypertension.', 'admin', 'published', 4, true, '[["reduced cardiac output", "decreased heart rate", "reduced contractility"], ["reduced renin release", "inhibits renin", "decreased renin"], ["central", "reduced sympathetic outflow", "cns"], ["presynaptic beta receptors", "reduced noradrenaline release"], ["baroreceptor resetting", "baroreceptors"], ["vasodilation", "nitric oxide", "alpha blockade"]]'::jsonb, 'saq p.102 2012/13 Q3b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-7c83a37c4c', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'saq', 'Describe the pharmacokinetics of quinine and the changes in quinine pharmacokinetics in severe malaria.', '[]'::jsonb, 'Pharmacokinetics: well absorbed orally (over 80%), peak at 1-3 hours; about 70-90% protein bound, mainly to alpha-1-acid glycoprotein; widely distributed; metabolised in the liver by CYP3A4 to 3-hydroxyquinine; about 20% excreted unchanged in urine (more in acid urine); half-life about 11 hours in health. In severe malaria: the volume of distribution contracts and systemic clearance falls in proportion to disease severity; protein binding rises (to over 90%) because alpha-1-acid glycoprotein, an acute-phase protein, increases; the half-life lengthens to about 18 hours. Plasma levels are therefore higher for a given dose, so the maintenance dose is reduced by a third to a half after 48 hours if there is no improvement or in renal failure; a loading dose is given at the start.', '[]'::jsonb, 'Higher total concentrations in severe malaria are partly offset by increased protein binding, which keeps free drug levels safe. As the patient recovers, clearance and volume expand again, so the same dose gives lower levels.', 'admin', 'published', 4, true, '[["well absorbed", "oral absorption"], ["protein bound", "alpha-1-acid glycoprotein"], ["hepatic metabolism", "cyp3a4", "3-hydroxyquinine"], ["half-life 11 hours", "renal excretion 20%"], ["reduced volume of distribution", "vd decreases"], ["reduced clearance", "clearance falls"], ["increased protein binding"], ["longer half-life", "18 hours"], ["dose reduction after 48 hours", "loading dose", "higher plasma levels"]]'::jsonb, 'saq p.102 2012/13 Q3c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-e9df5d2988', 'pharm-sympathomimetics-methylxanthines', 'saq', 'Classify the sympathomimetics used in asthma, with 2 examples in each class.', '[]'::jsonb, '1. Selective beta-2 agonists: short-acting (SABA) - salbutamol, terbutaline, fenoterol; long-acting (LABA) - salmeterol, formoterol; ultra-long-acting - indacaterol, vilanterol. 2. Non-selective beta agonists: isoprenaline, orciprenaline. 3. Mixed alpha and beta agonists: adrenaline, ephedrine.', '[]'::jsonb, 'Beta-2 selectivity and inhalation limit cardiac stimulation. Short-acting drugs relieve acute bronchospasm; long-acting ones are used for maintenance and always with an inhaled corticosteroid in asthma, because alone they increase asthma deaths. Adrenaline is reserved for anaphylaxis.', 'admin', 'published', 3, true, '[["selective beta-2 agonists", "beta-2 selective"], ["short-acting", "salbutamol", "terbutaline", "fenoterol"], ["long-acting", "salmeterol", "formoterol", "indacaterol"], ["non-selective beta", "isoprenaline", "orciprenaline"], ["adrenaline", "ephedrine", "alpha and beta"]]'::jsonb, 'saq p.102 2012/13 Q3d, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-0e09333a44', 'pharm-antivirals', 'saq', 'List 4 adverse effects of ganciclovir.', '[]'::jsonb, 'Any 4 of: bone marrow suppression - neutropenia, thrombocytopenia, anaemia; CNS effects - headache, confusion, seizures; nausea, vomiting and diarrhoea; nephrotoxicity (raised creatinine); fever and rash; abnormal liver function; phlebitis at the infusion site; potential carcinogenicity, teratogenicity and impaired fertility; retinal detachment with intravitreal use.', '[]'::jsonb, 'Ganciclovir is far more toxic to host cells than acyclovir because cellular kinases also phosphorylate it. Dose-limiting myelosuppression is worsened by zidovudine and other marrow-toxic drugs; G-CSF can support the neutrophil count.', 'admin', 'published', 4, true, '[["neutropenia", "bone marrow suppression", "myelosuppression", "leucopenia"], ["thrombocytopenia", "anaemia"], ["headache", "confusion", "seizures", "cns toxicity"], ["nausea", "vomiting", "diarrhoea"], ["nephrotoxicity", "raised creatinine"], ["fever", "rash"], ["teratogenic", "carcinogenic", "infertility"], ["phlebitis", "retinal detachment"]]'::jsonb, 'saq p.102 2012/13 Q4a, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-606bcfc635', 'pharm-drug-agonists-and-antagonists', 'saq', 'Give 4 types of drug antagonism with an example of each.', '[]'::jsonb, '1. Competitive (reversible, surmountable) pharmacological antagonism: the antagonist binds the same receptor site - atropine vs acetylcholine, naloxone vs morphine, propranolol vs adrenaline. 2. Non-competitive or irreversible antagonism: the antagonist binds covalently or at another site so the maximum response falls - phenoxybenzamine at alpha receptors. 3. Physiological (functional) antagonism: two drugs produce opposite effects through different receptors - adrenaline vs histamine on the bronchi, glucagon vs insulin. 4. Chemical antagonism: direct chemical combination - protamine with heparin, chelators (dimercaprol) with heavy metals, antacids with gastric acid. 5. Pharmacokinetic antagonism: one drug reduces the concentration of another - rifampicin inducing metabolism of warfarin, activated charcoal reducing absorption.', '[]'::jsonb, 'Competitive antagonists shift the agonist log dose-response curve to the right in parallel without lowering the maximum; irreversible and non-competitive antagonists depress the maximum. Physiological and chemical antagonism do not involve the agonist''s receptor at all.', 'admin', 'published', 4, true, '[["competitive", "reversible", "atropine", "naloxone", "flumazenil"], ["non-competitive", "irreversible", "phenoxybenzamine"], ["physiological", "functional", "adrenaline and histamine", "insulin and glucagon"], ["chemical", "protamine", "chelating agents", "dimercaprol", "antacids"], ["pharmacokinetic", "enzyme induction", "rifampicin", "activated charcoal"]]'::jsonb, 'saq p.102 2012/13 Q4b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-0cbaddf571', 'pharm-g-proteins-and-second-messengers', 'saq', 'List 3 physiological effects of cyclic AMP (cAMP).', '[]'::jsonb, 'Any 3 of: increased heart rate and force of contraction (beta-1); relaxation of smooth muscle - bronchodilatation, vasodilatation, uterine relaxation (beta-2); glycogenolysis and gluconeogenesis in the liver (glucagon, adrenaline); lipolysis in adipose tissue; increased water reabsorption in the collecting duct (vasopressin V2); increased gastric acid secretion (histamine H2); inhibition of platelet aggregation (prostacyclin); stimulation of hormone secretion and steroidogenesis (ACTH, TSH, LH, FSH); renin release.', '[]'::jsonb, 'cAMP is made by adenylyl cyclase when Gs-coupled receptors are activated and acts mainly through protein kinase A, which phosphorylates enzymes and channels. Phosphodiesterases break it down, so their inhibitors (theophylline, milrinone) reproduce these effects.', 'admin', 'published', 3, true, '[["increased heart rate", "increased contractility", "cardiac stimulation"], ["smooth muscle relaxation", "bronchodilation", "vasodilation"], ["glycogenolysis", "gluconeogenesis"], ["lipolysis"], ["water reabsorption", "vasopressin", "adh"], ["gastric acid secretion"], ["inhibits platelet aggregation"], ["hormone secretion", "steroidogenesis", "renin release"]]'::jsonb, 'saq p.102 2012/13 Q4c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-f004be290b', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'List 5 unrelated adverse effects of corticosteroids.', '[]'::jsonb, 'Any 5 of: suppression of the hypothalamic-pituitary-adrenal axis (adrenal insufficiency on withdrawal); iatrogenic Cushing''s syndrome (moon face, central obesity, striae); hyperglycaemia or diabetes; osteoporosis and fractures, avascular necrosis of the femoral head; increased susceptibility to infection and reactivation of tuberculosis; peptic ulceration; hypertension, sodium and fluid retention, hypokalaemia; proximal myopathy; skin thinning, bruising and poor wound healing; cataracts and glaucoma; growth retardation in children; psychiatric effects (euphoria, depression, psychosis, insomnia).', '[]'::jsonb, 'The adverse effects are exaggerations of the physiological actions of cortisol: catabolic effects on bone, muscle and skin; gluconeogenesis; mineralocorticoid effects; and suppression of immunity and of the adrenal axis. They depend on dose and duration, so the lowest effective dose is used and long courses are tapered.', 'admin', 'published', 5, true, '[["adrenal suppression", "hpa axis suppression", "adrenal insufficiency"], ["cushing''s syndrome", "cushingoid", "moon face", "central obesity"], ["hyperglycaemia", "diabetes"], ["osteoporosis", "fractures", "avascular necrosis"], ["infections", "immunosuppression", "tuberculosis reactivation"], ["peptic ulcer"], ["hypertension", "fluid retention", "hypokalaemia"], ["myopathy", "muscle wasting"], ["skin thinning", "striae", "poor wound healing"], ["cataracts", "glaucoma"], ["growth retardation"], ["psychosis", "mood changes"]]'::jsonb, 'saq p.103 2012/13 Q4d(iv), JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-e7b9b71738', 'pharm-drugs-used-in-angina', 'saq', 'List 3 adverse effects of nitroglycerin (glyceryl trinitrate).', '[]'::jsonb, 'Any 3 of: throbbing headache; flushing; postural hypotension, dizziness and syncope; reflex tachycardia; tolerance with continuous use; methaemoglobinaemia (high doses); severe hypotension with sildenafil and other PDE5 inhibitors.', '[]'::jsonb, 'All are consequences of vasodilatation by nitric oxide: meningeal artery dilatation causes headache, and venous pooling causes postural hypotension with reflex tachycardia. Tolerance develops within a day of continuous exposure, hence nitrate-free intervals.', 'admin', 'published', 3, true, '[["headache"], ["flushing"], ["postural hypotension", "hypotension", "dizziness", "syncope"], ["reflex tachycardia", "tachycardia", "palpitations"], ["tolerance"], ["methaemoglobinaemia", "methemoglobinemia"]]'::jsonb, 'saq p.103 2012/13 Q5b, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-4f2143cb08', 'pharm-anti-fungals', 'saq', 'Classify antifungal drugs, with 2 examples in each class, and indicate the mechanism of action of each class.', '[]'::jsonb, '1. Polyenes (amphotericin B, nystatin): bind ergosterol in the fungal membrane and form pores. 2. Azoles - imidazoles (ketoconazole, clotrimazole, miconazole) and triazoles (fluconazole, itraconazole, voriconazole): inhibit lanosterol 14-alpha-demethylase, blocking ergosterol synthesis. 3. Allylamines (terbinafine, naftifine): inhibit squalene epoxidase. 4. Echinocandins (caspofungin, micafungin, anidulafungin): inhibit beta-1,3-glucan synthase, blocking cell wall synthesis. 5. Antimetabolite (flucytosine): converted to 5-fluorouracil in fungal cells, inhibiting DNA and RNA synthesis. 6. Mitotic inhibitor (griseofulvin): binds microtubules and disrupts the mitotic spindle.', '[]'::jsonb, 'Most antifungals target ergosterol, the fungal counterpart of cholesterol, either binding it (polyenes) or blocking its synthesis (azoles, allylamines). Echinocandins target the cell wall, which human cells lack, and so are the least toxic systemic agents.', 'admin', 'published', 5, true, '[["polyenes", "amphotericin b", "nystatin", "bind ergosterol"], ["azoles", "fluconazole", "ketoconazole", "itraconazole", "clotrimazole", "14-alpha-demethylase"], ["allylamines", "terbinafine", "squalene epoxidase"], ["echinocandins", "caspofungin", "micafungin", "glucan synthase"], ["flucytosine", "5-fluorocytosine"], ["griseofulvin", "microtubules"]]'::jsonb, 'saq p.103 2012/13 Q5c, JB revision SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-d22e830d2d', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Describe the mechanism of action of insulin at its receptor.', '[]'::jsonb, 'Insulin binds the alpha subunits of its receptor, a transmembrane tyrosine kinase (two alpha and two beta subunits). This activates the tyrosine kinase of the beta subunits, which autophosphorylate and then phosphorylate insulin receptor substrates (IRS-1, IRS-2). These activate the PI3-kinase/Akt pathway (metabolic effects: translocation of GLUT4 transporters to the membrane of muscle and fat cells, glycogen, lipid and protein synthesis) and the MAP-kinase pathway (growth and gene expression).', '[]'::jsonb, 'Insulin does not use a classical second messenger; it triggers a phosphorylation cascade. GLUT4 translocation, which is why muscle and fat take up glucose within minutes, is impaired in the insulin resistance of type 2 diabetes.', 'admin', 'published', 3, true, '[["tyrosine kinase receptor", "receptor tyrosine kinase", "tyrosine kinase"], ["alpha subunit", "beta subunit", "autophosphorylation"], ["irs", "insulin receptor substrate"], ["pi3-kinase", "pi3k", "akt"], ["glut4", "glucose transporter", "translocation"], ["map kinase", "growth"]]'::jsonb, 'saq p.104 Q3a, Endocrine pharmacology revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-938393ad68', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'Describe the effects of insulin on hepatocytes, muscle and adipose tissue.', '[]'::jsonb, 'Liver: increases glycogen synthesis (glycogen synthase) and glycolysis; inhibits glycogenolysis and gluconeogenesis; increases triglyceride and VLDL synthesis; inhibits ketogenesis. Muscle: increases glucose uptake (GLUT4), glycogen synthesis and glycolysis; increases amino acid uptake and protein synthesis; inhibits protein breakdown; increases potassium uptake. Adipose tissue: increases glucose uptake (GLUT4) and triglyceride synthesis and storage; activates lipoprotein lipase (uptake of fatty acids from lipoproteins); inhibits hormone-sensitive lipase and so lipolysis.', '[]'::jsonb, 'Insulin is the hormone of the fed state: it stores glucose as glycogen and fat and builds protein, while switching off hepatic glucose and ketone production. Its absence in type 1 diabetes therefore causes hyperglycaemia, lipolysis, ketoacidosis and wasting.', 'admin', 'published', 5, true, '[["glycogen synthesis", "glycogenesis"], ["inhibits gluconeogenesis", "inhibits glycogenolysis"], ["inhibits ketogenesis"], ["glucose uptake", "glut4"], ["protein synthesis", "amino acid uptake"], ["potassium uptake"], ["triglyceride synthesis", "lipogenesis", "fat storage"], ["inhibits lipolysis", "hormone-sensitive lipase"], ["lipoprotein lipase"]]'::jsonb, 'saq p.104 Q5, Endocrine pharmacology revision') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-20dee5f31b', 'pharm-introduction-to-dmards', 'saq', 'Classify the disease-modifying antirheumatic drugs (DMARDs).', '[]'::jsonb, '1. Conventional synthetic DMARDs: methotrexate, sulfasalazine, hydroxychloroquine and chloroquine, leflunomide, azathioprine, ciclosporin, cyclophosphamide, gold salts (sodium aurothiomalate, auranofin), penicillamine. 2. Biologic DMARDs: TNF-alpha inhibitors (infliximab, adalimumab, etanercept, golimumab, certolizumab); IL-6 receptor antagonists (tocilizumab); IL-1 receptor antagonist (anakinra); T-cell co-stimulation blocker (abatacept); anti-CD20 B-cell depleting antibody (rituximab). 3. Targeted synthetic DMARDs: Janus kinase inhibitors (tofacitinib, baricitinib).', '[]'::jsonb, 'DMARDs slow joint destruction in rheumatoid arthritis rather than just relieving symptoms, and take weeks to months to act. Methotrexate is the anchor drug; biologics, which target specific cytokines or cells, are added when conventional agents fail.', 'admin', 'published', 5, true, '[["conventional", "synthetic", "non-biologic"], ["methotrexate", "sulfasalazine", "hydroxychloroquine", "leflunomide", "azathioprine", "gold", "penicillamine"], ["biologic", "biological"], ["tnf inhibitors", "infliximab", "adalimumab", "etanercept"], ["tocilizumab", "anakinra", "abatacept", "rituximab"], ["jak inhibitors", "tofacitinib", "baricitinib", "targeted synthetic"]]'::jsonb, 'saq p.106 Q1, DMARDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-fe93ee06c7', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'saq', 'Describe the mechanism of action of chloroquine and hydroxychloroquine as disease-modifying antirheumatic drugs.', '[]'::jsonb, 'They are weak bases that accumulate in lysosomes and raise lysosomal pH. This impairs antigen processing and MHC class II presentation by macrophages and dendritic cells, inhibits Toll-like receptor (TLR7 and TLR9) signalling, reduces production of cytokines (IL-1, TNF-alpha, IL-6), stabilises lysosomal membranes, and inhibits lymphocyte proliferation, leucocyte chemotaxis and free radical production.', '[]'::jsonb, 'The antirheumatic mechanism is distinct from the antimalarial one (inhibition of haem polymerisation). The drugs are mild DMARDs used in early rheumatoid arthritis and SLE; retinopathy is the important long-term toxicity, requiring eye screening.', 'admin', 'published', 2, true, '[["accumulate in lysosomes", "lysosomes", "raise lysosomal ph", "lysosomotropic"], ["antigen processing", "antigen presentation", "mhc class ii"], ["toll-like receptors", "tlr"], ["reduce cytokines", "il-1", "tnf"], ["stabilise lysosomal membranes", "inhibit chemotaxis", "lymphocyte proliferation"]]'::jsonb, 'saq p.106 Q2(III), DMARDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-0503d843a4', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'saq', 'Leflunomide, through its active metabolite teriflunomide, inhibits which enzyme?', '[]'::jsonb, 'Dihydroorotate dehydrogenase', '["DHODH", "dihydro-orotate dehydrogenase", "mitochondrial dihydroorotate dehydrogenase", "dihydroorotate dehydrogenase (DHODH)"]'::jsonb, 'Dihydroorotate dehydrogenase is a mitochondrial enzyme of de novo pyrimidine synthesis. Activated lymphocytes need to expand their pyrimidine pool about eightfold and cannot rely on salvage, so they arrest in G1. Leflunomide is hepatotoxic and teratogenic, with a very long half-life.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.106 Q2(V), DMARDs SAQs tutorial. Reworded from ''Describe the mechanism of action of leflunomide''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-c0294607dc', 'pharm-biologic-dmards', 'saq', 'Classify the TNF-alpha blocking agents.', '[]'::jsonb, '1. Monoclonal antibodies against TNF-alpha: chimeric (mouse-human) - infliximab; fully human - adalimumab, golimumab; pegylated humanised Fab fragment - certolizumab pegol. 2. Soluble TNF receptor fusion protein (two p75 TNF receptors linked to the Fc of IgG1): etanercept.', '[]'::jsonb, 'All neutralise TNF-alpha, a key cytokine in rheumatoid synovitis. Infliximab is given intravenously with methotrexate to limit antibody formation; the others are subcutaneous. The main risks are reactivation of latent tuberculosis and other infections, so patients are screened first.', 'admin', 'published', 3, true, '[["monoclonal antibodies"], ["infliximab", "chimeric"], ["adalimumab", "golimumab", "fully human"], ["certolizumab", "pegylated fab"], ["etanercept", "receptor fusion protein", "soluble receptor"]]'::jsonb, 'saq p.106 Q5, DMARDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-d6724ada23', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Classify the selective COX-2 inhibitors.', '[]'::jsonb, '1. Highly selective COX-2 inhibitors (coxibs): celecoxib, etoricoxib, parecoxib (injectable prodrug of valdecoxib); withdrawn - rofecoxib, valdecoxib, lumiracoxib. Chemically: sulphonamides (celecoxib, valdecoxib, parecoxib), methylsulphones (rofecoxib, etoricoxib), arylacetic acid (lumiracoxib). 2. Preferential COX-2 inhibitors (lose selectivity at higher doses): meloxicam, nimesulide, etodolac, nabumetone.', '[]'::jsonb, 'COX-2 has a larger active-site pocket than COX-1, which the bulky side groups of coxibs fit. Sparing COX-1 reduces gastric ulceration and leaves platelets unaffected, but unopposed thromboxane increases thrombotic events; renal effects are the same as with other NSAIDs.', 'admin', 'published', 3, true, '[["coxibs", "selective", "highly selective"], ["celecoxib"], ["etoricoxib"], ["parecoxib", "valdecoxib", "rofecoxib", "lumiracoxib"], ["preferential"], ["meloxicam", "nimesulide", "etodolac", "nabumetone"]]'::jsonb, 'saq p.115 Q1, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-63326c18d2', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'With regard to acetaminophen (paracetamol), write short notes on its mechanism of action and indications.', '[]'::jsonb, 'Mechanism: weak inhibitor of prostaglandin synthesis, acting mainly in the central nervous system (inhibition of COX, including the peroxidase site, where peroxide levels are low); it is ineffective in inflamed tissue where peroxides are high, so it is analgesic and antipyretic but has negligible anti-inflammatory activity; other proposed central mechanisms are activation of descending serotonergic pathways and cannabinoid/TRPV1 effects of its metabolite AM404. No antiplatelet effect. Indications: mild to moderate pain (headache, musculoskeletal pain, dysmenorrhoea, osteoarthritis, postoperative pain); fever, especially in children; an alternative when aspirin or NSAIDs are contraindicated.', '[]'::jsonb, 'Paracetamol''s selectivity for the brain explains why it relieves pain and fever without anti-inflammatory, gastric or platelet effects. It is the first-step analgesic on the WHO ladder and the antipyretic of choice in children, in whom aspirin risks Reye''s syndrome.', 'admin', 'published', 3, true, '[["central cox inhibition", "inhibits prostaglandin synthesis in cns", "central action", "cox inhibition"], ["weak anti-inflammatory", "no anti-inflammatory", "peroxides"], ["analgesic", "pain", "headache"], ["antipyretic", "fever"], ["serotonergic", "am404", "descending pathways"], ["alternative to aspirin", "nsaids contraindicated"]]'::jsonb, 'saq p.115 Q2(ii,v), NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-67151a7b29', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'With regard to acetaminophen (paracetamol), write short notes on its pharmacokinetics.', '[]'::jsonb, 'Rapidly and almost completely absorbed from the small intestine (peak in 30-60 minutes; rate depends on gastric emptying); bioavailability about 80-90%; little protein binding; distributed throughout body water, crosses the placenta. Metabolised in the liver: about 90% by glucuronidation and sulphation to inactive conjugates; about 5-10% oxidised by CYP2E1 (and CYP3A4) to the reactive metabolite N-acetyl-p-benzoquinone imine (NAPQI), which is detoxified by conjugation with glutathione. Excreted in urine as conjugates; half-life 2-3 hours.', '[]'::jsonb, 'The minor oxidative pathway is the key to toxicity: in overdose the conjugation pathways saturate, more NAPQI is formed and glutathione runs out. Enzyme inducers and chronic alcohol increase the proportion going down this route.', 'admin', 'published', 3, true, '[["rapid absorption", "well absorbed", "small intestine"], ["low protein binding"], ["glucuronidation", "sulphation", "sulfation", "conjugation"], ["napqi", "n-acetyl-p-benzoquinone imine", "cyp2e1"], ["glutathione"], ["renal excretion", "half-life 2-3 hours", "2 hours"]]'::jsonb, 'saq p.115 Q2(iii), NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-8e31494f12', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'saq', 'With regard to acetaminophen (paracetamol), write short notes on its toxicity.', '[]'::jsonb, 'Therapeutic doses are very safe (occasional rash; rarely blood dyscrasias). Overdose (over about 150 mg/kg or 7.5-10 g in adults) causes dose-dependent centrilobular hepatic necrosis: glucuronide and sulphate pathways saturate, more of the toxic metabolite NAPQI is formed, hepatic glutathione is depleted and NAPQI binds covalently to cell proteins. Course: nausea and vomiting in the first 24 hours, then right upper quadrant pain, raised transaminases and INR at 24-72 hours, with liver failure, encephalopathy and hypoglycaemia at 3-5 days; acute renal tubular necrosis may occur. Risk is higher in chronic alcoholics, malnutrition and with enzyme inducers. Treatment: activated charcoal if early; N-acetylcysteine (replenishes glutathione), guided by the plasma level on the Rumack-Matthew nomogram, most effective within 8-10 hours; methionine is an oral alternative.', '[]'::jsonb, 'The patient may look well for the first day, which is why treatment decisions rest on the timed plasma concentration rather than symptoms. N-acetylcysteine supplies cysteine for glutathione synthesis and is almost completely protective if given within eight hours.', 'admin', 'published', 4, true, '[["hepatotoxicity", "hepatic necrosis", "liver failure", "centrilobular necrosis"], ["napqi", "toxic metabolite"], ["glutathione depletion", "glutathione"], ["n-acetylcysteine", "acetylcysteine", "nac", "methionine"], ["renal tubular necrosis", "nephrotoxicity"], ["alcoholics", "enzyme inducers", "nomogram", "activated charcoal"]]'::jsonb, 'saq p.115 Q2(iv), NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-58ef49338a', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the differences between paracetamol and NSAIDs.', '[]'::jsonb, 'Paracetamol: analgesic and antipyretic with negligible anti-inflammatory action; inhibits prostaglandin synthesis mainly in the CNS; no gastric irritation or ulceration; no effect on platelets or bleeding time; no effect on renal blood flow or uric acid at therapeutic doses; safe in asthma, pregnancy and children; not associated with Reye''s syndrome; main toxicity is hepatic necrosis in overdose. NSAIDs: analgesic, antipyretic and anti-inflammatory; inhibit COX peripherally and centrally; cause gastric ulceration and bleeding, antiplatelet effect, renal impairment and fluid retention, bronchospasm in sensitive asthmatics; aspirin is linked to Reye''s syndrome.', '[]'::jsonb, 'The contrast follows from where each inhibits cyclo-oxygenase: paracetamol works where peroxide levels are low (brain), not in inflamed tissue, the stomach or platelets. It is therefore preferred for simple pain and fever, while NSAIDs are needed when inflammation drives the pain.', 'admin', 'published', 3, true, '[["no anti-inflammatory", "weak anti-inflammatory", "anti-inflammatory"], ["central action", "cns", "peripheral"], ["no gastric irritation", "no gi ulceration", "gastric ulcer"], ["no antiplatelet effect", "platelets", "bleeding"], ["renal", "kidney"], ["safe in asthma", "safe in children", "reye''s syndrome", "pregnancy"], ["hepatotoxicity in overdose"]]'::jsonb, 'saq p.115 Q3, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-70132a5832', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'List the conditions that would necessitate the administration of paracetamol and not aspirin.', '[]'::jsonb, 'Any 4 of: peptic ulcer disease or gastritis; bleeding disorders (haemophilia, thrombocytopenia) or anticoagulant therapy; aspirin-sensitive asthma or aspirin hypersensitivity; children and adolescents with fever or viral illness (risk of Reye''s syndrome); pregnancy (especially the third trimester) and breastfeeding; gout (aspirin retains urate); dengue and other haemorrhagic fevers; renal impairment; before surgery; G6PD deficiency.', '[]'::jsonb, 'Paracetamol lacks the gastric, platelet, bronchial and urate effects of aspirin, so it replaces aspirin wherever those effects would be dangerous. In children with influenza or chickenpox aspirin is linked to Reye''s syndrome (encephalopathy with fatty liver).', 'admin', 'published', 4, true, '[["peptic ulcer", "gastritis", "gi bleeding"], ["bleeding disorders", "haemophilia", "hemophilia", "anticoagulants", "warfarin"], ["asthma", "aspirin hypersensitivity", "aspirin allergy"], ["children", "reye''s syndrome", "viral illness"], ["pregnancy", "breastfeeding"], ["gout", "hyperuricaemia"], ["dengue", "renal impairment", "g6pd deficiency", "surgery"]]'::jsonb, 'saq p.115 Q4, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-db6b0151d4', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the effects (and uses arising from them) of indomethacin other than its anti-inflammatory, analgesic and antipyretic properties.', '[]'::jsonb, 'Closure of a patent ductus arteriosus in premature neonates (by inhibiting PGE2 synthesis); tocolytic effect - suppression of uterine contractions to delay preterm labour, and reduction of amniotic fluid volume in polyhydramnios; inhibition of platelet aggregation; reduced neutrophil motility; reduction of renal blood flow and of renin release (used in Bartter syndrome); reduction of cerebral blood flow.', '[]'::jsonb, 'Prostaglandin E2 keeps the ductus arteriosus open and prostaglandins drive uterine contractions, so a potent COX inhibitor closes the ductus and relaxes the uterus. The same action is a hazard in late pregnancy, when it can close the fetal ductus prematurely.', 'admin', 'published', 2, true, '[["closure of patent ductus arteriosus", "pda closure", "patent ductus arteriosus"], ["tocolytic", "delays labour", "preterm labour", "uterine relaxation", "polyhydramnios"], ["antiplatelet", "inhibits platelet aggregation", "bartter syndrome", "reduces renal blood flow", "neutrophil"]]'::jsonb, 'saq p.115 Q5, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-51976469c6', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the clinical indications of indomethacin.', '[]'::jsonb, 'Any 3 of: acute gouty arthritis; ankylosing spondylitis; rheumatoid arthritis and osteoarthritis (when other NSAIDs fail); closure of patent ductus arteriosus in preterm infants; preterm labour (tocolysis) and polyhydramnios; acute pericarditis and pleurisy; paroxysmal hemicrania and other indomethacin-responsive headaches; Bartter syndrome; dysmenorrhoea.', '[]'::jsonb, 'Indomethacin is one of the most potent COX inhibitors, which makes it effective in very painful inflammatory conditions such as acute gout and ankylosing spondylitis, but its toxicity keeps it from routine use as a simple analgesic or antipyretic.', 'admin', 'published', 3, true, '[["acute gout", "gout"], ["ankylosing spondylitis"], ["rheumatoid arthritis", "osteoarthritis"], ["patent ductus arteriosus", "pda"], ["preterm labour", "tocolysis", "polyhydramnios"], ["pericarditis", "pleurisy"], ["paroxysmal hemicrania", "bartter syndrome", "dysmenorrhoea"]]'::jsonb, 'saq p.115 Q6a, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-ab3ce850a9', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the adverse effects of indomethacin.', '[]'::jsonb, 'Any 3 of: gastrointestinal - dyspepsia, peptic ulceration, bleeding, diarrhoea; CNS - severe frontal headache, dizziness, vertigo, confusion, depression, hallucinations; renal - impaired function, fluid retention, hyperkalaemia; haematological - neutropenia, thrombocytopenia, aplastic anaemia; hypersensitivity - rash, bronchospasm; hepatitis and pancreatitis; in neonates - oliguria, necrotising enterocolitis.', '[]'::jsonb, 'Up to a third to a half of patients have adverse effects, and many stop the drug. Frontal headache and other CNS effects are characteristic of indomethacin among NSAIDs, alongside the usual gastric and renal effects of COX inhibition.', 'admin', 'published', 3, true, '[["peptic ulcer", "gi bleeding", "dyspepsia", "diarrhoea"], ["frontal headache", "headache"], ["dizziness", "vertigo", "confusion", "depression", "hallucinations"], ["renal impairment", "fluid retention", "hyperkalaemia"], ["neutropenia", "thrombocytopenia", "aplastic anaemia"], ["rash", "bronchospasm", "hepatitis", "pancreatitis"]]'::jsonb, 'saq p.115 Q6b, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-d3f7f8c73f', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the contraindications of indomethacin.', '[]'::jsonb, 'Any 3 of: active peptic ulcer or gastrointestinal bleeding; aspirin or NSAID hypersensitivity, including aspirin-sensitive asthma; pregnancy (especially the third trimester) and breastfeeding; renal impairment; severe heart failure; psychiatric illness, epilepsy and parkinsonism (may be aggravated); bleeding disorders; in neonates - active bleeding, thrombocytopenia, necrotising enterocolitis or significant renal impairment.', '[]'::jsonb, 'Besides the general NSAID contraindications, indomethacin''s CNS effects mean it can worsen epilepsy, depression and parkinsonism. In the third trimester it risks premature ductal closure and fetal renal impairment with oligohydramnios.', 'admin', 'published', 3, true, '[["peptic ulcer", "gi bleeding"], ["nsaid hypersensitivity", "aspirin allergy", "asthma"], ["pregnancy", "third trimester", "breastfeeding"], ["renal impairment", "renal failure"], ["heart failure"], ["psychiatric illness", "epilepsy", "parkinsonism", "depression"], ["bleeding disorders", "thrombocytopenia", "necrotising enterocolitis"]]'::jsonb, 'saq p.115 Q6c, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-9a3b0a6c2e', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'Give the drug interactions of indomethacin.', '[]'::jsonb, 'Any 3 of: probenecid raises indomethacin levels (reduced renal and biliary clearance); it antagonises the natriuretic and antihypertensive effects of diuretics (furosemide, thiazides), beta-blockers and ACE inhibitors; with triamterene or ACE inhibitors - hyperkalaemia and acute renal failure; raises lithium levels (reduced renal clearance); raises methotrexate and digoxin levels; increased bleeding with warfarin, heparin and antiplatelet drugs; increased GI ulceration with corticosteroids and other NSAIDs; increased nephrotoxicity with ciclosporin and aminoglycosides (in neonates).', '[]'::jsonb, 'Most of these interactions are shared by all NSAIDs and stem from the loss of renal vasodilator and natriuretic prostaglandins, which blunts diuretics and antihypertensives and reduces the clearance of lithium and methotrexate. The combination with triamterene is a classic cause of acute renal failure.', 'admin', 'published', 3, true, '[["probenecid"], ["diuretics", "furosemide", "thiazides", "antagonises antihypertensives", "beta blockers", "ace inhibitors"], ["triamterene", "hyperkalaemia", "renal failure"], ["lithium"], ["methotrexate", "digoxin"], ["warfarin", "anticoagulants", "bleeding"], ["corticosteroids", "other nsaids", "ciclosporin", "aminoglycosides"]]'::jsonb, 'saq p.116 Q6d, NSAIDs SAQs tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-e79fc747b1', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'saq', 'List 4 drugs used in chemoprophylaxis of malaria.', '[]'::jsonb, 'Any 4 of: atovaquone-proguanil (Malarone); doxycycline; mefloquine; chloroquine (sensitive areas only); proguanil; primaquine; tafenoquine; sulfadoxine-pyrimethamine (intermittent preventive treatment in pregnancy).', '[]'::jsonb, 'Travellers to chloroquine-resistant areas are offered atovaquone-proguanil, doxycycline or mefloquine; chloroquine only works where P. falciparum is still sensitive. Primaquine and tafenoquine kill liver stages. In endemic areas such as Kenya, pregnant women receive intermittent sulfadoxine-pyrimethamine rather than daily prophylaxis.', 'admin', 'published', 4, true, '[["atovaquone", "malarone", "atovaquone-proguanil"], ["doxycycline"], ["mefloquine"], ["chloroquine"], ["proguanil"], ["primaquine"], ["tafenoquine"], ["sulfadoxine", "pyrimethamine", "sp", "fansidar"]]'::jsonb, 'saq p.121 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-5d5bc0fb46', 'pharm-antiretroviral-i', 'saq', 'List 4 non-nucleoside reverse transcriptase inhibitors (NNRTIs).', '[]'::jsonb, 'Any 4 of: nevirapine; efavirenz; etravirine; rilpivirine; delavirdine; doravirine.', '[]'::jsonb, 'NNRTIs bind an allosteric pocket on HIV-1 reverse transcriptase, away from the active site, and need no intracellular phosphorylation. They are inactive against HIV-2. Nevirapine and efavirenz are the first-generation agents; etravirine, rilpivirine and doravirine are newer agents that keep activity against some resistant virus.', 'admin', 'published', 4, true, '[["nevirapine", "nvp"], ["efavirenz", "efv"], ["etravirine"], ["rilpivirine"], ["delavirdine"], ["doravirine"]]'::jsonb, 'saq p.121 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-d300936f2a', 'pharm-antiretroviral-i', 'saq', 'List three antiretroviral drugs used in HIV/hepatitis B co-infection.', '[]'::jsonb, 'Tenofovir (TDF or TAF); lamivudine (3TC); emtricitabine (FTC).', '[]'::jsonb, 'Tenofovir, lamivudine and emtricitabine inhibit the reverse transcriptase activity of the hepatitis B polymerase as well as HIV reverse transcriptase. Co-infected patients therefore receive a regimen containing tenofovir plus lamivudine or emtricitabine; stopping these drugs can cause a hepatitis flare.', 'admin', 'published', 3, true, '[["tenofovir", "tdf", "taf"], ["lamivudine", "3tc"], ["emtricitabine", "ftc"]]'::jsonb, 'saq p.121 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-fbf3675fd2', 'pharm-antidepressants-and-lithium', 'saq', 'Give 4 adverse drug reactions of tricyclic antidepressants.', '[]'::jsonb, 'Any 4 of: antimuscarinic effects (dry mouth, blurred vision, constipation, urinary retention); sedation; postural hypotension; cardiac arrhythmias / QT prolongation; weight gain; lowered seizure threshold; sexual dysfunction; confusion in the elderly.', '[]'::jsonb, 'Tricyclics block muscarinic, H1 and alpha-1 receptors in addition to inhibiting noradrenaline and serotonin reuptake. This explains the atropine-like effects, sedation with weight gain, and postural hypotension. Their quinidine-like sodium channel block makes them dangerously cardiotoxic in overdose.', 'admin', 'published', 4, true, '[["dry mouth", "anticholinergic", "antimuscarinic"], ["blurred vision"], ["constipation"], ["urinary retention"], ["sedation", "drowsiness"], ["postural hypotension", "orthostatic hypotension", "hypotension"], ["arrhythmia", "arrhythmias", "qt prolongation", "cardiotoxicity", "tachycardia"], ["weight gain"], ["seizures", "convulsions", "seizure threshold"], ["sexual dysfunction"]]'::jsonb, 'saq p.121 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-5c23a91578', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'saq', 'List five indications of ergot alkaloids, naming a specific drug for each.', '[]'::jsonb, 'Any 5 of: acute migraine - ergotamine or dihydroergotamine; migraine prophylaxis - methysergide; postpartum haemorrhage - ergometrine (ergonovine) or methylergometrine; hyperprolactinaemia / suppression of lactation - bromocriptine or cabergoline; Parkinson''s disease - bromocriptine; acromegaly - bromocriptine; senile cerebral insufficiency - co-dergocrine (dihydroergotoxine).', '[]'::jsonb, 'Ergot alkaloids act as partial agonists or antagonists at alpha-adrenergic, serotonin and dopamine receptors. Vasoconstriction explains their use in migraine, uterine contraction their use in postpartum haemorrhage, and dopamine D2 agonism (bromocriptine, cabergoline) their use in hyperprolactinaemia, acromegaly and Parkinson''s disease.', 'admin', 'published', 5, true, '[["migraine", "ergotamine", "dihydroergotamine"], ["methysergide", "migraine prophylaxis"], ["postpartum haemorrhage", "pph", "ergometrine", "ergonovine", "methylergometrine"], ["hyperprolactinaemia", "prolactinoma", "cabergoline", "suppress lactation"], ["parkinson", "parkinsonism", "bromocriptine"], ["acromegaly"], ["dementia", "co-dergocrine", "dihydroergotoxine"]]'::jsonb, 'saq p.121 Q5, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-9ed9399eb8', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Give four mechanisms by which beta-blockers reduce peripheral vascular resistance (and so lower blood pressure) in long-term use.', '[]'::jsonb, 'Any 4 of: reduced renin release from the kidney (less angiotensin II and aldosterone); reduced central sympathetic outflow; blockade of presynaptic beta receptors, reducing noradrenaline release; resetting of baroreceptors; additional alpha-1 blockade (labetalol, carvedilol); nitric oxide release (nebivolol); reduced cardiac output with later vascular adaptation.', '[]'::jsonb, 'Acutely, beta-blockers lower cardiac output and peripheral resistance actually rises reflexly. With continued use resistance falls, attributed to suppressed renin release (a beta-1 effect on juxtaglomerular cells), less central sympathetic drive, reduced noradrenaline release from nerve endings and baroreceptor resetting. Some agents also vasodilate directly.', 'admin', 'draft', 4, true, '[["renin", "decrease renin", "reduced renin"], ["central", "sympathetic outflow", "cns"], ["presynaptic", "noradrenaline release", "norepinephrine release"], ["baroreceptor", "baroreceptors"], ["alpha blockade", "alpha-1", "carvedilol", "labetalol"], ["nitric oxide", "nebivolol"], ["cardiac output"]]'::jsonb, 'saq p.121 Q6, Assorted handwritten SAQs. Paper says only ''Four mechanisms by which B-blockers reduce PVR''; wording expanded. The mechanisms are partly theoretical and textbooks differ, so the mark scheme is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-e40ae1d3e8', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'saq', 'List 3 adverse drug reactions of insulin therapy.', '[]'::jsonb, 'Any 3 of: hypoglycaemia; weight gain; lipodystrophy (lipohypertrophy or lipoatrophy) at injection sites; allergic reactions; hypokalaemia; insulin oedema; insulin resistance from antibodies.', '[]'::jsonb, 'Hypoglycaemia is the commonest and most dangerous effect, from too much insulin relative to food or exercise. Insulin is anabolic, causing weight gain, and repeated injection at one site produces lipohypertrophy. It also drives potassium into cells, which matters during treatment of ketoacidosis.', 'admin', 'published', 3, true, '[["hypoglycaemia", "hypoglycemia", "low blood sugar"], ["weight gain"], ["lipodystrophy", "lipohypertrophy", "lipoatrophy"], ["allergy", "allergic", "hypersensitivity"], ["hypokalaemia", "hypokalemia"], ["oedema", "edema"], ["insulin resistance", "antibodies"]]'::jsonb, 'saq p.122 Q1b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-epipodophyllotoxins-camptothecins-anal-4d436d20da', 'pharm-epipodophyllotoxins-camptothecins-analogues', 'saq', 'Give 3 examples of camptothecin analogues.', '[]'::jsonb, 'Topotecan; irinotecan; belotecan (others: rubitecan, exatecan; SN-38 is the active metabolite of irinotecan).', '[]'::jsonb, 'Camptothecins inhibit topoisomerase I, stabilising the enzyme-DNA complex so single-strand breaks cannot be resealed and replication forks collapse. Topotecan is used in ovarian and small-cell lung cancer; irinotecan in colorectal cancer, where it causes severe diarrhoea and neutropenia.', 'admin', 'draft', 3, true, '[["topotecan"], ["irinotecan"], ["belotecan", "rubitecan", "exatecan", "sn-38"]]'::jsonb, 'saq p.122 Q3, Assorted handwritten SAQs. Only topotecan and irinotecan are in standard textbooks; the third example is a less familiar drug, so a marker''s expected answer is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-7b765ad8a5', 'pharm-antivirals', 'saq', 'Which viral enzyme is inhibited by zanamivir?', '[]'::jsonb, 'Neuraminidase', '["Influenza neuraminidase", "Viral neuraminidase", "Sialidase", "Neuraminidase enzyme"]'::jsonb, 'Zanamivir and oseltamivir are sialic acid analogues that block influenza A and B neuraminidase. The enzyme normally cleaves sialic acid so new virions can leave the infected cell; when it is blocked, virions clump at the cell surface and spread is limited.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.122 Q4b, Assorted handwritten SAQs. Reworded from ''What is the mechanism of action of zanamivir'' so that one short answer fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-6f7f2fc4f9', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'saq', 'Describe the mechanism of action of omeprazole.', '[]'::jsonb, 'A prodrug activated in the acidic canaliculus of the parietal cell; the active sulfenamide binds covalently (irreversibly) to the H+/K+ ATPase (proton pump), blocking the final step of acid secretion.', '[]'::jsonb, 'Because omeprazole blocks the final common step, it suppresses acid secretion whatever the stimulus (histamine, gastrin or acetylcholine). Inhibition is irreversible, so the effect outlasts the short plasma half-life and acid returns only as new pumps are synthesised.', 'admin', 'published', 2, true, '[["proton pump", "h+/k+ atpase", "h/k atpase", "hydrogen potassium atpase"], ["irreversible", "irreversibly", "covalent"], ["prodrug", "activated in acid"], ["parietal cell", "parietal cells"]]'::jsonb, 'saq p.123 Q1a, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-412e693009', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'saq', 'Describe the mechanism of action of sucralfate.', '[]'::jsonb, 'In acid it polymerises to a viscous, negatively charged gel that binds positively charged proteins in the ulcer base, forming a physical barrier against acid, pepsin and bile; it also stimulates mucosal prostaglandin, mucus and bicarbonate secretion.', '[]'::jsonb, 'Sucralfate is an aluminium salt of sulfated sucrose that needs an acid pH to become active, so it should not be given together with antacids, H2 blockers or proton pump inhibitors. It is hardly absorbed; constipation is the main adverse effect.', 'admin', 'published', 2, true, '[["barrier", "protective barrier", "coats ulcer", "physical barrier"], ["ulcer base", "binds proteins", "adheres to ulcer"], ["prostaglandin", "prostaglandins", "mucus", "bicarbonate"], ["acid", "acidic ph", "polymerises"]]'::jsonb, 'saq p.123 Q1b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-6199c5dc6a', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'saq', 'Describe the mechanism of action of magnesium hydroxide as used in peptic ulcer disease.', '[]'::jsonb, 'A weak base that reacts with gastric hydrochloric acid to form magnesium chloride and water, raising gastric pH; the higher pH also reduces pepsin activity.', '[]'::jsonb, 'Antacids do not reduce acid secretion; they simply neutralise acid already present. Pepsin is inactive above about pH 4. Unabsorbed magnesium salts are osmotic and cause diarrhoea, which is why magnesium hydroxide is combined with constipating aluminium hydroxide.', 'admin', 'published', 2, true, '[["neutralises acid", "neutralizes acid", "neutralise", "neutralize", "reacts with hcl"], ["raises ph", "increase ph"], ["pepsin"], ["weak base", "antacid"]]'::jsonb, 'saq p.123 Q1c, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-9e7da2ecbd', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'saq', 'List one adverse effect of cimetidine in each of the following: gastrointestinal tract, endocrine system, blood and central nervous system.', '[]'::jsonb, 'GIT: diarrhoea (or constipation, nausea). Endocrine: gynaecomastia (or galactorrhoea, impotence). Blood: thrombocytopenia (or neutropenia, agranulocytosis). CNS: confusion (or hallucinations, headache, dizziness), especially in the elderly.', '[]'::jsonb, 'Cimetidine blocks androgen receptors and inhibits oestradiol metabolism, causing gynaecomastia and impotence in men; other H2 blockers do not. It crosses the blood-brain barrier and causes confusion in elderly or renally impaired patients, and rarely depresses blood counts.', 'admin', 'published', 4, true, '[["diarrhoea", "diarrhea", "constipation", "nausea"], ["gynaecomastia", "gynecomastia", "galactorrhoea", "impotence"], ["thrombocytopenia", "neutropenia", "agranulocytosis", "leucopenia", "bone marrow"], ["confusion", "hallucinations", "headache", "dizziness", "delirium"]]'::jsonb, 'saq p.123 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-29b511aa5a', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'saq', 'Classify diuretics according to their mechanism of action and give one example in each class.', '[]'::jsonb, '1. Carbonic anhydrase inhibitors (proximal tubule): acetazolamide. 2. Osmotic diuretics: mannitol. 3. Loop diuretics (inhibit Na+/K+/2Cl- cotransporter, thick ascending limb): furosemide. 4. Thiazides (inhibit Na+/Cl- cotransporter, distal tubule): hydrochlorothiazide. 5. Potassium-sparing: aldosterone antagonists (spironolactone) and epithelial sodium channel blockers (amiloride).', '[]'::jsonb, 'Each class acts at a different nephron segment, which determines potency and side effects. Loop diuretics are the most powerful because the thick ascending limb reabsorbs about 25% of filtered sodium; potassium-sparing agents act on the collecting duct and are weak but prevent potassium loss.', 'admin', 'published', 5, true, '[["carbonic anhydrase", "acetazolamide"], ["osmotic", "mannitol"], ["loop", "furosemide", "frusemide", "nkcc2"], ["thiazide", "thiazides", "hydrochlorothiazide"], ["potassium sparing", "potassium-sparing", "spironolactone", "amiloride", "aldosterone antagonist"]]'::jsonb, 'saq p.123 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-6166ec413c', 'pharm-antiarrhythmic-drugs', 'saq', 'Classify antiarrhythmic drugs according to Vaughan Williams, giving examples in each class and the mechanism of action of each class.', '[]'::jsonb, 'Class I - sodium channel blockers: Ia quinidine, procainamide; Ib lidocaine, mexiletine; Ic flecainide, propafenone. Class II - beta-blockers: propranolol, esmolol. Class III - potassium channel blockers (prolong repolarisation): amiodarone, sotalol. Class IV - calcium channel blockers: verapamil, diltiazem. Others: adenosine, digoxin, magnesium.', '[]'::jsonb, 'The Vaughan Williams scheme groups drugs by their main electrophysiological action. Class I slows phase 0 depolarisation, class II reduces sympathetic drive to nodal tissue, class III prolongs the action potential and refractory period, and class IV slows conduction through the calcium-dependent SA and AV nodes.', 'admin', 'published', 5, true, '[["sodium channel", "class i", "class 1", "quinidine", "lidocaine", "lignocaine", "flecainide", "procainamide"], ["beta blocker", "beta-blocker", "class ii", "propranolol", "esmolol", "metoprolol"], ["potassium channel", "class iii", "amiodarone", "sotalol"], ["calcium channel", "class iv", "verapamil", "diltiazem"], ["adenosine", "digoxin", "magnesium"]]'::jsonb, 'saq p.126 Q3 (also p.124 Q1), Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-f8d148deb2', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'saq', 'List 4 NSAIDs with COX-2 selective activity.', '[]'::jsonb, 'Any 4 of: celecoxib; etoricoxib; parecoxib; rofecoxib; valdecoxib; lumiracoxib (preferential COX-2 inhibitors: meloxicam, nimesulide, etodolac).', '[]'::jsonb, 'Selective COX-2 inhibitors spare the COX-1 that makes protective gastric prostaglandins and platelet thromboxane, so they cause fewer ulcers and do not impair platelet function. Unopposed thromboxane raises cardiovascular risk, which led to the withdrawal of rofecoxib and valdecoxib.', 'admin', 'published', 4, true, '[["celecoxib"], ["etoricoxib"], ["parecoxib"], ["rofecoxib"], ["valdecoxib"], ["lumiracoxib"], ["meloxicam"], ["nimesulide"], ["etodolac"]]'::jsonb, 'saq p.124 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-8d3259d7a9', 'pharm-oral-antidiabetic-drugs', 'saq', 'What is the mechanism of action of acarbose?', '[]'::jsonb, 'Competitively inhibits intestinal brush-border alpha-glucosidases, delaying the digestion of starch and disaccharides and the absorption of glucose, so the post-prandial rise in blood glucose is reduced.', '[]'::jsonb, 'Acarbose acts in the gut lumen and does not stimulate insulin release, so it does not cause hypoglycaemia on its own. If hypoglycaemia occurs with combined therapy it must be treated with glucose, not sucrose, because sucrose breakdown is blocked.', 'admin', 'published', 2, true, '[["alpha-glucosidase", "alpha glucosidase", "glucosidase"], ["delays carbohydrate digestion", "delays absorption", "carbohydrate absorption", "slows digestion"], ["postprandial", "post-prandial", "after meals"]]'::jsonb, 'saq p.124 Q3a, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-41b457ab6b', 'pharm-oral-antidiabetic-drugs', 'saq', 'List the adverse drug reactions of acarbose.', '[]'::jsonb, 'Flatulence; abdominal bloating and discomfort; diarrhoea (from fermentation of undigested carbohydrate in the colon); rarely raised liver enzymes.', '[]'::jsonb, 'Carbohydrate that escapes digestion reaches the colon, where bacteria ferment it to gas and short-chain fatty acids. The resulting flatulence, bloating and diarrhoea are dose-related, limit adherence, and make the drug unsuitable in inflammatory bowel disease.', 'admin', 'published', 2, true, '[["flatulence", "gas"], ["bloating", "abdominal distension", "abdominal pain", "abdominal discomfort"], ["diarrhoea", "diarrhea"], ["liver enzymes", "hepatotoxicity", "transaminases"]]'::jsonb, 'saq p.124 Q3b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-e1b78e5809', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'saq', 'List 4 clinical indications of metronidazole.', '[]'::jsonb, 'Any 4 of: amoebiasis (intestinal and liver abscess); giardiasis; trichomoniasis; bacterial vaginosis; anaerobic infections (e.g. Bacteroides, abdominal sepsis, brain abscess); Clostridioides difficile colitis; Helicobacter pylori eradication; acute ulcerative gingivitis / dental infections.', '[]'::jsonb, 'Metronidazole is a prodrug whose nitro group is reduced only by anaerobic organisms and certain protozoa, producing radicals that damage DNA. This selective activation explains its spectrum: anaerobic bacteria, Entamoeba, Giardia and Trichomonas, with no activity against aerobes.', 'admin', 'published', 4, true, '[["amoebiasis", "amebiasis", "amoebic", "entamoeba"], ["giardiasis", "giardia"], ["trichomoniasis", "trichomonas"], ["bacterial vaginosis", "gardnerella"], ["anaerobic", "anaerobes", "bacteroides"], ["clostridium difficile", "c. difficile", "pseudomembranous colitis"], ["h. pylori", "helicobacter"], ["gingivitis", "dental"]]'::jsonb, 'saq p.124 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-4ca5a844b5', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'What is the mechanism of action of captopril?', '[]'::jsonb, 'Inhibits angiotensin-converting enzyme, blocking conversion of angiotensin I to angiotensin II (less vasoconstriction and aldosterone release) and preventing the breakdown of bradykinin (vasodilatation).', '[]'::jsonb, 'Less angiotensin II means arteriolar and venous dilatation and less aldosterone-driven sodium retention, so blood pressure, preload and afterload fall. The accumulation of bradykinin adds to the vasodilatation but causes the characteristic dry cough and, rarely, angioedema.', 'admin', 'published', 2, true, '[["ace", "angiotensin converting enzyme", "angiotensin-converting enzyme"], ["angiotensin ii", "angiotensin 2"], ["bradykinin"], ["aldosterone", "vasodilatation", "vasodilation"]]'::jsonb, 'saq p.124 Q5a, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-5cddaa5243', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'What is the mechanism of action of losartan?', '[]'::jsonb, 'Competitive antagonist of angiotensin II at the AT1 receptor, blocking vasoconstriction and aldosterone release; it does not affect bradykinin.', '[]'::jsonb, 'Blocking the AT1 receptor prevents the actions of angiotensin II however it is formed, including by non-ACE pathways such as chymase. Because bradykinin breakdown is unaffected, losartan rarely causes cough, so it is the usual substitute for patients who cannot tolerate ACE inhibitors.', 'admin', 'published', 2, true, '[["at1", "at1 receptor", "angiotensin ii receptor", "angiotensin receptor blocker", "arb"], ["antagonist", "blocks", "blocker"], ["aldosterone", "vasoconstriction", "vasodilation"]]'::jsonb, 'saq p.124 Q5b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-6aba9bc704', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'saq', 'Classify the drugs used in peptic ulcer disease, giving one example in each class.', '[]'::jsonb, '1. Antacids: magnesium hydroxide, aluminium hydroxide. 2. H2-receptor antagonists: cimetidine, ranitidine. 3. Proton pump inhibitors: omeprazole. 4. Mucosal protective agents: sucralfate, bismuth compounds, misoprostol (prostaglandin analogue). 5. Anti-H. pylori antibiotics: clarithromycin, amoxicillin, metronidazole. (Antimuscarinics: pirenzepine.)', '[]'::jsonb, 'Ulcer drugs either reduce acid (neutralise it, or block the H2 receptor or proton pump), strengthen mucosal defence, or eradicate Helicobacter pylori. Eradication with a proton pump inhibitor plus two antibiotics is what prevents relapse in H. pylori-positive ulcers.', 'admin', 'published', 5, true, '[["antacid", "antacids", "magnesium hydroxide", "aluminium hydroxide"], ["h2 antagonist", "h2 blocker", "h2 receptor", "cimetidine", "ranitidine", "famotidine"], ["proton pump inhibitor", "ppi", "omeprazole", "esomeprazole", "pantoprazole"], ["sucralfate", "bismuth", "cytoprotective", "mucosal protective"], ["misoprostol", "prostaglandin analogue"], ["h. pylori", "helicobacter", "clarithromycin", "amoxicillin", "metronidazole"], ["pirenzepine", "antimuscarinic"]]'::jsonb, 'saq p.125 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-ea5180d014', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'saq', 'List five adverse drug reactions of quinine, each in a different body system.', '[]'::jsonb, 'Any 5 of: CNS / special senses - cinchonism (tinnitus, deafness, headache, visual disturbance); GIT - nausea, vomiting; CVS - hypotension, QT prolongation, arrhythmias; endocrine / metabolic - hypoglycaemia (insulin release); blood - haemolysis (G6PD deficiency), blackwater fever, thrombocytopenia; skin - rash, hypersensitivity; uterus - stimulation of contractions.', '[]'::jsonb, 'Quinine has a narrow therapeutic range. Cinchonism (tinnitus, high-tone deafness, headache, nausea) appears at therapeutic levels. It stimulates pancreatic insulin release, causing hypoglycaemia especially in pregnancy and severe malaria, and rapid intravenous injection causes hypotension and arrhythmias, so it is given by slow infusion.', 'admin', 'published', 5, true, '[["cinchonism", "tinnitus", "deafness", "hearing loss"], ["visual", "blurred vision", "blindness"], ["nausea", "vomiting"], ["hypotension", "arrhythmia", "arrhythmias", "qt prolongation"], ["hypoglycaemia", "hypoglycemia"], ["haemolysis", "hemolysis", "blackwater fever", "thrombocytopenia"], ["rash", "hypersensitivity"], ["uterine contraction", "oxytocic"]]'::jsonb, 'saq p.125 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-b1b2b7d78c', 'pharm-aminoglycosides', 'saq', 'List 3 aminoglycosides.', '[]'::jsonb, 'Any 3 of: gentamicin; amikacin; streptomycin; tobramycin; kanamycin; neomycin; netilmicin.', '[]'::jsonb, 'Aminoglycosides are bactericidal inhibitors of protein synthesis that bind the 30S ribosomal subunit and cause misreading of mRNA. They need oxygen-dependent transport into bacteria, so they act on aerobic Gram-negative bacilli and are inactive against anaerobes.', 'admin', 'published', 3, true, '[["gentamicin"], ["amikacin"], ["streptomycin"], ["tobramycin"], ["kanamycin"], ["neomycin"], ["netilmicin"]]'::jsonb, 'saq p.125 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-6ee366ce06', 'pharm-aminoglycosides', 'saq', 'Give two significant adverse drug reactions of aminoglycosides.', '[]'::jsonb, 'Nephrotoxicity (acute tubular necrosis, usually reversible); ototoxicity (cochlear and vestibular, often irreversible). Also neuromuscular blockade.', '[]'::jsonb, 'Aminoglycosides accumulate in proximal tubular cells and in the perilymph of the inner ear, damaging both. Toxicity relates to trough concentration and duration of therapy, which is why once-daily dosing and plasma level monitoring are used, particularly in renal impairment.', 'admin', 'published', 2, true, '[["nephrotoxicity", "nephrotoxic", "kidney damage", "renal toxicity"], ["ototoxicity", "ototoxic", "deafness", "hearing loss", "vestibular"], ["neuromuscular blockade", "neuromuscular block"]]'::jsonb, 'saq p.125 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-b027fdc04b', 'pharm-anti-fungals', 'saq', 'List two organisms that are sensitive to amphotericin B.', '[]'::jsonb, 'Any 2 of: Candida species; Cryptococcus neoformans; Aspergillus; Histoplasma capsulatum; Blastomyces; Coccidioides; Mucor (mucormycosis); Leishmania.', '[]'::jsonb, 'Amphotericin B has the broadest spectrum of any antifungal and is used for life-threatening systemic mycoses such as cryptococcal meningitis, invasive aspergillosis and mucormycosis. Liposomal amphotericin is also a first-line treatment for visceral leishmaniasis, because Leishmania membranes contain ergosterol-like sterols.', 'admin', 'published', 2, true, '[["candida"], ["cryptococcus"], ["aspergillus"], ["histoplasma"], ["blastomyces"], ["coccidioides"], ["mucor", "mucormycosis", "rhizopus"], ["leishmania"]]'::jsonb, 'saq p.125 Q6b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-acd2774f79', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'saq', 'Give 4 mechanisms of action of anticonvulsant drugs.', '[]'::jsonb, 'Any 4 of: blockade of voltage-gated sodium channels (phenytoin, carbamazepine, lamotrigine); enhancement of GABA inhibition (benzodiazepines, barbiturates, vigabatrin, tiagabine); blockade of T-type calcium channels (ethosuximide); reduction of glutamate excitation (topiramate, perampanel, felbamate); binding to synaptic vesicle protein SV2A (levetiracetam); binding to alpha-2-delta calcium channel subunit (gabapentin).', '[]'::jsonb, 'Seizures arise from excessive synchronous neuronal firing, so drugs either limit repetitive firing (sodium channel block), boost inhibition (GABA), or reduce excitation (glutamate, calcium channels). T-type calcium channel block in thalamic neurons is specific to absence seizures.', 'admin', 'published', 4, true, '[["sodium channel", "sodium channels", "na channel"], ["gaba", "gabaergic"], ["calcium channel", "t-type", "calcium channels"], ["glutamate", "nmda", "ampa"], ["sv2a", "synaptic vesicle", "levetiracetam"], ["alpha-2-delta", "gabapentin"]]'::jsonb, 'saq p.126 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-4296d2a268', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'Give 5 unrelated adverse effects of corticosteroids (in different systems).', '[]'::jsonb, 'Any 5 of: hyperglycaemia / diabetes; osteoporosis; Cushingoid features and weight gain; hypertension and fluid retention; increased susceptibility to infection; peptic ulceration; adrenal suppression; skin thinning and poor wound healing; proximal myopathy; cataracts or glaucoma; psychosis or mood change; growth retardation in children.', '[]'::jsonb, 'Adverse effects are exaggerations of physiological glucocorticoid actions: gluconeogenesis, protein catabolism (thin skin, muscle wasting, osteoporosis), mineralocorticoid sodium retention and immunosuppression. Prolonged therapy also suppresses the hypothalamic-pituitary-adrenal axis, so the dose must be tapered rather than stopped abruptly.', 'admin', 'published', 5, true, '[["hyperglycaemia", "hyperglycemia", "diabetes"], ["osteoporosis", "fractures"], ["cushingoid", "cushing", "moon face", "weight gain"], ["hypertension", "fluid retention", "oedema"], ["infection", "infections", "immunosuppression"], ["peptic ulcer", "ulcer"], ["adrenal suppression", "hpa suppression"], ["skin thinning", "striae", "poor wound healing", "bruising"], ["myopathy", "muscle wasting"], ["cataract", "cataracts", "glaucoma"], ["psychosis", "mood", "euphoria", "depression"], ["growth retardation", "growth suppression"]]'::jsonb, 'saq p.126 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-670ecd6856', 'pharm-anti-fungals', 'saq', 'Classify antifungal drugs, giving an example and the mechanism of action of each class.', '[]'::jsonb, '1. Polyenes (amphotericin B, nystatin): bind ergosterol, form membrane pores. 2. Azoles (fluconazole, ketoconazole, itraconazole, clotrimazole): inhibit 14-alpha-demethylase, blocking ergosterol synthesis. 3. Allylamines (terbinafine): inhibit squalene epoxidase. 4. Echinocandins (caspofungin): inhibit beta-1,3-glucan synthase (cell wall). 5. Antimetabolite (flucytosine): converted to 5-fluorouracil, inhibits DNA/RNA synthesis. 6. Griseofulvin: disrupts microtubules / mitosis.', '[]'::jsonb, 'Most antifungals exploit ergosterol, the fungal membrane sterol: polyenes bind it, while azoles and allylamines block different steps in its synthesis. Echinocandins target the cell wall, which human cells lack, and flucytosine and griseofulvin interfere with nucleic acid synthesis and mitosis.', 'admin', 'published', 5, true, '[["polyene", "polyenes", "amphotericin", "nystatin"], ["azole", "azoles", "fluconazole", "ketoconazole", "itraconazole", "clotrimazole"], ["allylamine", "terbinafine", "squalene epoxidase"], ["echinocandin", "echinocandins", "caspofungin", "glucan"], ["flucytosine", "antimetabolite"], ["griseofulvin", "microtubule", "mitosis"], ["ergosterol"]]'::jsonb, 'saq p.126 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--891205e721', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'saq', 'List 2 adverse drug reactions of erythropoietin.', '[]'::jsonb, 'Any 2 of: hypertension; thrombosis (including vascular access / shunt thrombosis); seizures or hypertensive encephalopathy; pure red cell aplasia (antibodies); flu-like symptoms; iron deficiency.', '[]'::jsonb, 'Raising the haematocrit increases blood viscosity and peripheral resistance, producing hypertension and thrombotic events, particularly when haemoglobin is pushed above about 12 g/dL. Rapid erythropoiesis also consumes iron, so iron stores must be adequate for the drug to work.', 'admin', 'published', 2, true, '[["hypertension", "high blood pressure"], ["thrombosis", "thromboembolism", "clotting", "stroke"], ["seizures", "encephalopathy"], ["pure red cell aplasia", "red cell aplasia"], ["flu-like", "headache"], ["iron deficiency"]]'::jsonb, 'saq p.127 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-ba8638bc23', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'saq', 'Give 4 clinical indications of opioids, with an example of an opioid drug used.', '[]'::jsonb, 'Any 4 of: severe acute or cancer pain - morphine; acute pulmonary oedema / left ventricular failure - morphine; cough suppression - codeine, dextromethorphan; diarrhoea - loperamide, diphenoxylate; anaesthesia and pre-medication - fentanyl; opioid dependence (maintenance) - methadone, buprenorphine; myocardial infarction pain - morphine.', '[]'::jsonb, 'Opioid uses follow from mu-receptor effects: analgesia, suppression of the medullary cough centre, and reduced gut motility. In acute pulmonary oedema morphine relieves distress and dilates veins, reducing preload. Long-acting agonists such as methadone prevent withdrawal in opioid dependence.', 'admin', 'published', 4, true, '[["pain", "analgesia", "analgesic"], ["pulmonary oedema", "pulmonary edema", "left ventricular failure"], ["cough", "antitussive", "codeine", "dextromethorphan"], ["diarrhoea", "diarrhea", "loperamide", "diphenoxylate"], ["anaesthesia", "anesthesia", "premedication", "fentanyl"], ["dependence", "addiction", "methadone", "buprenorphine"], ["morphine"]]'::jsonb, 'saq p.131 Q5 (also p.127 Q2), Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-9abfefdbe2', 'pharm-intravenous-anesthetic-agents', 'saq', 'Give 5 examples of intravenous anaesthetics.', '[]'::jsonb, 'Any 5 of: propofol; thiopental (thiopentone); ketamine; etomidate; midazolam (or diazepam); methohexital; fentanyl.', '[]'::jsonb, 'Intravenous agents induce anaesthesia within one arm-brain circulation time and wear off by redistribution from brain to muscle and fat. Propofol, thiopental and etomidate enhance GABA-A receptor activity, whereas ketamine blocks NMDA receptors and gives dissociative anaesthesia with analgesia.', 'admin', 'published', 5, true, '[["propofol"], ["thiopental", "thiopentone"], ["ketamine"], ["etomidate"], ["midazolam", "diazepam"], ["methohexital", "methohexitone"], ["fentanyl"]]'::jsonb, 'saq p.127 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-71d5f25771', 'pharm-major-tranquilizer', 'saq', 'List 3 atypical antipsychotics.', '[]'::jsonb, 'Any 3 of: clozapine; olanzapine; risperidone; quetiapine; aripiprazole; ziprasidone; amisulpride; paliperidone.', '[]'::jsonb, 'Atypical (second-generation) antipsychotics block 5-HT2A receptors as well as dopamine D2 receptors, and dissociate quickly from D2. They cause fewer extrapyramidal effects than typical agents such as haloperidol, but more weight gain, diabetes and dyslipidaemia.', 'admin', 'published', 3, true, '[["clozapine"], ["olanzapine"], ["risperidone"], ["quetiapine"], ["aripiprazole"], ["ziprasidone"], ["amisulpride"], ["paliperidone"]]'::jsonb, 'saq p.127 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-78486797db', 'pharm-major-tranquilizer', 'saq', 'Give three adverse effects of chlorpromazine.', '[]'::jsonb, 'Any 3 of: extrapyramidal effects (acute dystonia, parkinsonism, akathisia, tardive dyskinesia); sedation; postural hypotension; antimuscarinic effects (dry mouth, constipation, urinary retention, blurred vision); hyperprolactinaemia (galactorrhoea, gynaecomastia); cholestatic jaundice; photosensitivity; weight gain; neuroleptic malignant syndrome; lowered seizure threshold.', '[]'::jsonb, 'Chlorpromazine blocks many receptors: D2 (extrapyramidal effects and raised prolactin), H1 (sedation), alpha-1 (postural hypotension) and muscarinic (dry mouth, constipation). It also causes idiosyncratic cholestatic jaundice and photosensitivity, and long-term dopamine blockade can produce irreversible tardive dyskinesia.', 'admin', 'published', 3, true, '[["extrapyramidal", "dystonia", "parkinsonism", "akathisia", "tardive dyskinesia"], ["sedation", "drowsiness"], ["postural hypotension", "orthostatic hypotension", "hypotension"], ["dry mouth", "anticholinergic", "antimuscarinic", "constipation", "urinary retention"], ["hyperprolactinaemia", "galactorrhoea", "gynaecomastia"], ["jaundice", "cholestatic"], ["photosensitivity"], ["weight gain"], ["neuroleptic malignant syndrome"], ["seizures"]]'::jsonb, 'saq p.127 Q5, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-615c9a77d3', 'pharm-preanesthetic-agent', 'saq', 'List 5 drugs used in pre-anaesthesia (pre-anaesthetic medication).', '[]'::jsonb, 'Any 5 of: benzodiazepines - diazepam, midazolam, lorazepam (anxiolysis, amnesia); opioids - morphine, pethidine, fentanyl (analgesia); antimuscarinics - atropine, glycopyrrolate, hyoscine (dry secretions, prevent bradycardia); antiemetics - metoclopramide, ondansetron; acid reducers - ranitidine, omeprazole; antihistamine - promethazine.', '[]'::jsonb, 'Premedication aims to relieve anxiety, give amnesia and analgesia, dry airway secretions, block vagal reflexes, and reduce the risk of vomiting and acid aspiration. Each drug class is chosen for one of these aims, and a smoother induction with a lower anaesthetic dose follows.', 'admin', 'published', 5, true, '[["diazepam", "midazolam", "lorazepam", "benzodiazepine"], ["morphine", "pethidine", "fentanyl", "opioid"], ["atropine", "glycopyrrolate", "hyoscine", "antimuscarinic"], ["metoclopramide", "ondansetron", "antiemetic"], ["ranitidine", "omeprazole", "h2 blocker", "antacid"], ["promethazine", "antihistamine"]]'::jsonb, 'saq p.127 Q6, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-a4e73965fb', 'pharm-adrenoceptor-blockers', 'saq', 'Name two selective (beta-1 selective) beta-blockers.', '[]'::jsonb, 'Any 2 of: atenolol; metoprolol; bisoprolol; esmolol; nebivolol; acebutolol; betaxolol.', '[]'::jsonb, 'Cardioselective blockers have higher affinity for beta-1 receptors in the heart than for beta-2 receptors in bronchi and blood vessels, so they cause less bronchospasm and peripheral vasoconstriction than propranolol. Selectivity is relative and is lost at high doses, so caution in asthma remains.', 'admin', 'published', 2, true, '[["atenolol"], ["metoprolol"], ["bisoprolol"], ["esmolol"], ["nebivolol"], ["acebutolol"], ["betaxolol"]]'::jsonb, 'saq p.127 Q7, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-937fcd6a21', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'saq', 'Classify antihypertensive drugs and give an example in each class.', '[]'::jsonb, '1. Diuretics: hydrochlorothiazide. 2. ACE inhibitors: enalapril; angiotensin receptor blockers: losartan. 3. Calcium channel blockers: amlodipine, nifedipine. 4. Beta-blockers: atenolol; alpha-blockers: prazosin. 5. Centrally acting sympatholytics: methyldopa, clonidine. 6. Direct vasodilators: hydralazine, minoxidil, sodium nitroprusside. 7. Adrenergic neurone blockers: reserpine, guanethidine.', '[]'::jsonb, 'Blood pressure is cardiac output times peripheral resistance, so drugs act by reducing blood volume (diuretics), blocking the renin-angiotensin system, relaxing vascular smooth muscle (calcium channel blockers, vasodilators) or reducing sympathetic drive centrally or at adrenoceptors.', 'admin', 'published', 5, true, '[["diuretic", "diuretics", "thiazide", "hydrochlorothiazide"], ["ace inhibitor", "ace inhibitors", "enalapril", "captopril", "arb", "losartan"], ["calcium channel blocker", "calcium channel blockers", "amlodipine", "nifedipine"], ["beta blocker", "beta-blocker", "beta blockers", "atenolol", "propranolol"], ["alpha blocker", "prazosin"], ["centrally acting", "methyldopa", "clonidine"], ["vasodilator", "vasodilators", "hydralazine", "minoxidil", "nitroprusside"], ["reserpine", "guanethidine", "adrenergic neurone"]]'::jsonb, 'saq p.128 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-769496db6a', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'saq', 'What is the mechanism of action of cardiac glycosides such as digoxin?', '[]'::jsonb, 'Inhibit the Na+/K+ ATPase of the cardiac cell membrane; intracellular sodium rises, which reduces calcium extrusion by the Na+/Ca2+ exchanger, so intracellular (and sarcoplasmic reticulum) calcium increases and contractility rises (positive inotropy). They also increase vagal tone, slowing AV conduction.', '[]'::jsonb, 'The inotropic effect is indirect: the sodium pump is blocked, and the resulting rise in cell sodium leaves more calcium available for each contraction. The separate vagal action slows the ventricular rate in atrial fibrillation. Hypokalaemia increases digoxin binding to the pump and so its toxicity.', 'admin', 'published', 2, true, '[["na+/k+ atpase", "na/k atpase", "sodium potassium atpase", "sodium pump"], ["intracellular calcium", "calcium", "na+/ca2+ exchanger", "sodium calcium exchanger"], ["positive inotropic", "contractility", "inotropy"], ["vagal", "av conduction", "av node"]]'::jsonb, 'saq p.128 Q3b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-33b27f8999', 'pharm-prostaglandins', 'saq', 'Give five clinical indications of prostaglandins (and their analogues).', '[]'::jsonb, 'Any 5 of: induction of labour / cervical ripening - dinoprostone (PGE2), misoprostol; termination of pregnancy - misoprostol, gemeprost; postpartum haemorrhage - carboprost (PGF2-alpha), misoprostol; prevention of NSAID-induced peptic ulcer - misoprostol (PGE1); keeping the ductus arteriosus open - alprostadil (PGE1); erectile dysfunction - alprostadil; open-angle glaucoma - latanoprost (PGF2-alpha); pulmonary hypertension - epoprostenol (PGI2), iloprost.', '[]'::jsonb, 'Uses follow from prostaglandin physiology: PGE and PGF contract the uterus; PGE protects gastric mucosa and relaxes vascular and ductal smooth muscle; PGF2-alpha analogues increase uveoscleral outflow of aqueous humour; and prostacyclin dilates pulmonary vessels and inhibits platelets.', 'admin', 'published', 5, true, '[["induction of labour", "labour", "cervical ripening", "dinoprostone"], ["abortion", "termination of pregnancy", "gemeprost"], ["postpartum haemorrhage", "pph", "carboprost"], ["peptic ulcer", "nsaid ulcer", "misoprostol"], ["ductus arteriosus", "patent ductus", "alprostadil"], ["erectile dysfunction", "impotence"], ["glaucoma", "latanoprost"], ["pulmonary hypertension", "epoprostenol", "iloprost", "prostacyclin"]]'::jsonb, 'saq p.128 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-0ccbd4f6f9', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'saq', 'Give examples of drugs acting on the renin-angiotensin-aldosterone system and the indications of each.', '[]'::jsonb, 'ACE inhibitors (captopril, enalapril, lisinopril): hypertension, heart failure, after myocardial infarction, diabetic nephropathy. Angiotensin II receptor blockers (losartan, valsartan): the same indications, used when ACE inhibitors cause cough. Direct renin inhibitor (aliskiren): hypertension. Aldosterone antagonists (spironolactone, eplerenone): heart failure, resistant hypertension, primary hyperaldosteronism, ascites / oedema of cirrhosis.', '[]'::jsonb, 'Blocking the system at any level lowers blood pressure and reduces the harmful remodelling that angiotensin II and aldosterone cause in the heart and kidney. This is why these drugs improve survival in heart failure and slow diabetic kidney disease, beyond simply lowering pressure.', 'admin', 'published', 4, true, '[["ace inhibitor", "ace inhibitors", "captopril", "enalapril", "lisinopril"], ["arb", "angiotensin receptor blocker", "losartan", "valsartan"], ["aliskiren", "renin inhibitor"], ["spironolactone", "eplerenone", "aldosterone antagonist"], ["hypertension"], ["heart failure"], ["diabetic nephropathy", "nephropathy", "myocardial infarction"]]'::jsonb, 'saq p.129 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-c5d9ccba9e', 'pharm-lipid-lowering-agents', 'saq', 'Classify lipid-lowering agents, giving two examples in each class.', '[]'::jsonb, '1. HMG-CoA reductase inhibitors (statins): atorvastatin, simvastatin. 2. Fibrates (PPAR-alpha agonists): gemfibrozil, fenofibrate. 3. Bile acid sequestrants (resins): cholestyramine, colestipol. 4. Cholesterol absorption inhibitor: ezetimibe. 5. Nicotinic acid (niacin) and derivatives: niacin, acipimox. 6. PCSK9 inhibitors: evolocumab, alirocumab. (Also omega-3 fatty acids.)', '[]'::jsonb, 'Statins lower LDL most by blocking hepatic cholesterol synthesis and up-regulating LDL receptors. Fibrates mainly lower triglycerides by activating lipoprotein lipase. Resins and ezetimibe act in the gut on bile acids and cholesterol absorption, and niacin is the best at raising HDL.', 'admin', 'published', 5, true, '[["statin", "statins", "hmg-coa reductase", "atorvastatin", "simvastatin", "rosuvastatin"], ["fibrate", "fibrates", "gemfibrozil", "fenofibrate"], ["bile acid sequestrant", "resin", "resins", "cholestyramine", "colestipol"], ["ezetimibe", "cholesterol absorption"], ["nicotinic acid", "niacin"], ["pcsk9", "evolocumab", "alirocumab"], ["omega-3", "fish oil"]]'::jsonb, 'saq p.130 Q3 (also p.129 Q4), Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-7b0b413eab', 'pharm-oral-antidiabetic-drugs', 'saq', 'Classify oral hypoglycaemic drugs, with an example of each class.', '[]'::jsonb, '1. Sulfonylureas: glibenclamide, gliclazide, glimepiride. 2. Meglitinides: repaglinide, nateglinide. 3. Biguanides: metformin. 4. Thiazolidinediones: pioglitazone. 5. Alpha-glucosidase inhibitors: acarbose. 6. DPP-4 inhibitors: sitagliptin. 7. SGLT2 inhibitors: dapagliflozin, empagliflozin.', '[]'::jsonb, 'The classes work at different sites: sulfonylureas and meglitinides make the pancreas release insulin; metformin and glitazones improve the response of liver, muscle and fat to insulin; acarbose slows carbohydrate absorption; gliptins prolong incretin action; and SGLT2 inhibitors cause glucose loss in urine.', 'admin', 'published', 5, true, '[["sulfonylurea", "sulfonylureas", "sulphonylureas", "glibenclamide", "gliclazide", "glimepiride"], ["meglitinide", "meglitinides", "repaglinide", "nateglinide"], ["biguanide", "biguanides", "metformin"], ["thiazolidinedione", "thiazolidinediones", "glitazone", "pioglitazone"], ["alpha-glucosidase", "acarbose"], ["dpp-4", "sitagliptin", "gliptin", "gliptins"], ["sglt2", "dapagliflozin", "empagliflozin"]]'::jsonb, 'saq p.130 Q1a, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-f2051c576f', 'pharm-oral-antidiabetic-drugs', 'saq', 'What is the mechanism of action of glibenclamide?', '[]'::jsonb, 'Binds the sulfonylurea receptor (SUR1) and closes ATP-sensitive potassium channels on pancreatic beta cells; the membrane depolarises, voltage-gated calcium channels open, and calcium entry triggers insulin release.', '[]'::jsonb, 'Sulfonylureas mimic the effect of a raised ATP level in the beta cell, so insulin is released whatever the glucose concentration. That is why hypoglycaemia and weight gain are the main adverse effects, and why they need functioning beta cells and do not work in type 1 diabetes.', 'admin', 'published', 2, true, '[["atp-sensitive potassium", "katp", "potassium channel", "potassium channels", "sur1"], ["beta cell", "beta cells", "pancreas"], ["depolarisation", "depolarization", "calcium influx", "calcium"], ["insulin release", "insulin secretion"]]'::jsonb, 'saq p.130 Q1b, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-8c84180ed4', 'pharm-antiretroviral-i', 'saq', 'List 5 adverse effects of nucleoside reverse transcriptase inhibitors that are related to mitochondrial toxicity.', '[]'::jsonb, 'Any 5 of: lactic acidosis; hepatic steatosis (fatty liver) with hepatomegaly; peripheral neuropathy; pancreatitis; lipoatrophy / lipodystrophy; myopathy; cardiomyopathy; bone marrow suppression (anaemia, neutropenia).', '[]'::jsonb, 'NRTIs also inhibit human mitochondrial DNA polymerase gamma, depleting mitochondrial DNA and impairing oxidative phosphorylation. Tissues that depend on mitochondria suffer: nerve, liver, pancreas, muscle and fat. Stavudine, didanosine and zidovudine are the worst offenders; lamivudine, abacavir and tenofovir cause little.', 'admin', 'published', 5, true, '[["lactic acidosis"], ["hepatic steatosis", "fatty liver", "steatosis", "hepatomegaly"], ["peripheral neuropathy", "neuropathy"], ["pancreatitis"], ["lipoatrophy", "lipodystrophy"], ["myopathy"], ["cardiomyopathy"], ["anaemia", "anemia", "bone marrow suppression", "neutropenia"]]'::jsonb, 'saq p.130 Q2, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-4d24c4becc', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'saq', 'List 5 adverse drug reactions of diuretics.', '[]'::jsonb, 'Any 5 of: hypokalaemia; hyponatraemia; dehydration / hypovolaemia and hypotension; hyperuricaemia (gout); hyperglycaemia; hyperlipidaemia; metabolic alkalosis; hypomagnesaemia; ototoxicity (loop diuretics); hypercalcaemia (thiazides) or hypocalcaemia (loop); hyperkalaemia and gynaecomastia (spironolactone).', '[]'::jsonb, 'Loop and thiazide diuretics deliver more sodium to the collecting duct, where it is exchanged for potassium and hydrogen ions, causing hypokalaemic alkalosis. Volume contraction increases proximal urate reabsorption, and thiazides also impair glucose tolerance. Potassium-sparing drugs carry the opposite risk, hyperkalaemia.', 'admin', 'published', 5, true, '[["hypokalaemia", "hypokalemia"], ["hyponatraemia", "hyponatremia"], ["dehydration", "hypovolaemia", "hypotension", "volume depletion"], ["hyperuricaemia", "hyperuricemia", "gout"], ["hyperglycaemia", "hyperglycemia"], ["hyperlipidaemia", "hyperlipidemia"], ["alkalosis"], ["hypomagnesaemia", "hypomagnesemia"], ["ototoxicity", "deafness"], ["hypercalcaemia", "hypocalcaemia"], ["hyperkalaemia", "hyperkalemia", "gynaecomastia"]]'::jsonb, 'saq p.130 Q4, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-d973e3fdbc', 'pharm-antiplatelet-drugs', 'saq', 'List antiplatelet agents (at least four), with their class.', '[]'::jsonb, 'COX inhibitor: aspirin. ADP (P2Y12) receptor antagonists: clopidogrel, prasugrel, ticagrelor, ticlopidine. Glycoprotein IIb/IIIa inhibitors: abciximab, eptifibatide, tirofiban. Phosphodiesterase inhibitors: dipyridamole, cilostazol.', '[]'::jsonb, 'Each class blocks a different step of platelet activation. Aspirin irreversibly stops thromboxane A2 synthesis, P2Y12 antagonists block ADP-induced activation, dipyridamole raises cyclic AMP, and the IIb/IIIa inhibitors block the final common pathway, fibrinogen cross-linking of platelets.', 'admin', 'published', 4, true, '[["aspirin"], ["clopidogrel", "prasugrel", "ticagrelor", "ticlopidine"], ["abciximab", "eptifibatide", "tirofiban"], ["dipyridamole", "cilostazol"]]'::jsonb, 'saq p.130 Q5, Assorted handwritten SAQs. Paper gives no number; set at four.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-139f645e72', 'pharm-oral-antidiabetic-drugs', 'saq', 'What is the mechanism of action of metformin?', '[]'::jsonb, 'Activates AMP-activated protein kinase (AMPK); reduces hepatic gluconeogenesis (hepatic glucose output), increases insulin sensitivity and peripheral glucose uptake in muscle, and reduces intestinal glucose absorption. It does not stimulate insulin secretion.', '[]'::jsonb, 'Metformin''s main action is to reduce glucose output from the liver. Because it does not release insulin it is ''euglycaemic'': it rarely causes hypoglycaemia and does not cause weight gain. Its rare serious toxicity is lactic acidosis, mainly in renal impairment.', 'admin', 'published', 2, true, '[["ampk", "amp kinase", "amp-activated protein kinase"], ["gluconeogenesis", "hepatic glucose output", "hepatic glucose production"], ["insulin sensitivity", "glucose uptake", "peripheral uptake"], ["glucose absorption"]]'::jsonb, 'saq p.131 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-2af805b566', 'pharm-log-dose-responses', 'saq', 'What is the clinical usefulness of the therapeutic index?', '[]'::jsonb, 'It is a measure of a drug''s safety margin. Drugs with a narrow (low) therapeutic index (e.g. digoxin, lithium, warfarin, phenytoin, theophylline, aminoglycosides) need careful dose individualisation and plasma level / effect monitoring, and are most at risk from drug interactions; a wide index allows safer, more flexible dosing.', '[]'::jsonb, 'Knowing the therapeutic index tells the prescriber how much room for error there is. For narrow-index drugs, small changes in dose, clearance or interacting drugs can cause toxicity or treatment failure, so therapeutic drug monitoring and careful titration are needed.', 'admin', 'published', 2, true, '[["safety", "margin of safety", "safe"], ["narrow", "low therapeutic index", "narrow therapeutic"], ["monitoring", "tdm", "drug level", "plasma level"], ["dose", "dosing", "dose adjustment"]]'::jsonb, 'saq p.131 Q3, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-98de8b1cc4', 'pharm-antihelminthics-ii-ectoparasites', 'saq', 'What is the mechanism of action of praziquantel?', '[]'::jsonb, 'Increases the permeability of the worm''s cell membranes (tegument) to calcium; calcium influx causes sustained muscle contraction and spastic paralysis, and damages the tegument (vacuolisation), exposing antigens to host immune attack.', '[]'::jsonb, 'Paralysed worms lose their grip on vessel walls or gut mucosa and are swept away, and the damaged tegument lets host antibodies and phagocytes attack. Praziquantel is the drug of choice for schistosomiasis and most other trematode and cestode infections.', 'admin', 'published', 2, true, '[["calcium", "calcium permeability", "calcium influx"], ["paralysis", "spastic paralysis", "contraction", "contracture"], ["tegument", "vacuolisation", "vacuolization", "immune attack"]]'::jsonb, 'saq p.131 Q7, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-8610e704d8', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'saq', 'Classify the agents used in the management of Parkinson''s disease, giving examples in each case.', '[]'::jsonb, '1. Dopamine precursor: levodopa (with a peripheral decarboxylase inhibitor: carbidopa, benserazide). 2. Dopamine agonists: bromocriptine, pramipexole, ropinirole. 3. MAO-B inhibitors: selegiline, rasagiline. 4. COMT inhibitors: entacapone, tolcapone. 5. Dopamine releaser: amantadine. 6. Central antimuscarinics: benzhexol (trihexyphenidyl), benztropine.', '[]'::jsonb, 'Parkinson''s disease is a striatal dopamine deficiency with relative cholinergic excess. Treatment either replaces dopamine (levodopa), mimics it (agonists), slows its breakdown (MAO-B and COMT inhibitors), releases it (amantadine) or restores the balance by blocking muscarinic receptors.', 'admin', 'published', 5, true, '[["levodopa", "l-dopa", "carbidopa", "benserazide", "dopamine precursor"], ["dopamine agonist", "dopamine agonists", "bromocriptine", "pramipexole", "ropinirole"], ["mao-b", "selegiline", "rasagiline"], ["comt", "entacapone", "tolcapone"], ["amantadine"], ["anticholinergic", "antimuscarinic", "benzhexol", "trihexyphenidyl", "benztropine"]]'::jsonb, 'saq p.132 Q1, Assorted handwritten SAQs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-cc45453403', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'saq', 'Give three first-generation retinoids used in the management of acne.', '[]'::jsonb, 'Tretinoin (all-trans retinoic acid, topical); isotretinoin (13-cis retinoic acid, oral or topical); retinol / retinaldehyde (topical).', '[]'::jsonb, 'First-generation retinoids are the non-aromatic, natural vitamin A compounds. They normalise follicular keratinisation, so comedones do not form, and oral isotretinoin also shrinks sebaceous glands. Adapalene and tazarotene, also used in acne, are third-generation; isotretinoin is highly teratogenic.', 'admin', 'draft', 3, true, '[["tretinoin", "all-trans retinoic acid"], ["isotretinoin", "13-cis retinoic acid"], ["retinol", "retinaldehyde", "retinal"]]'::jsonb, 'saq p.132 Q3, Assorted handwritten SAQs. Only tretinoin and isotretinoin are established first-generation acne treatments; the third item (retinol) follows the student''s pencilled answer and common teaching, and its use in acne is weak. Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-c63107937a', 'pharm-introduction-to-pharmacokinetics', 'saq', 'What is pharmacokinetics?', '[]'::jsonb, 'The study of the movement of drugs through the body over time, i.e. what the body does to the drug: absorption, distribution, metabolism and excretion.', '[]'::jsonb, 'Pharmacokinetics describes how drug concentration changes with time and so determines dose, route and dosing interval. It is contrasted with pharmacodynamics, which is what the drug does to the body: its mechanism of action and its effects.', 'admin', 'published', 2, true, '[["what the body does", "body does to the drug", "movement of drug", "time course"], ["absorption", "distribution", "metabolism", "excretion", "adme"]]'::jsonb, 'saq p.134 Q1, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-e06ec7fb5d', 'pharm-introduction-to-pharmacokinetics', 'saq', 'What are the processes in pharmacokinetics?', '[]'::jsonb, 'Absorption; distribution; metabolism (biotransformation); excretion. (Liberation of the drug from its dosage form is sometimes added: LADME.)', '[]'::jsonb, 'A drug is absorbed from its site of administration, distributed by the blood to tissues, chemically altered mainly in the liver, and removed mainly by the kidneys. Metabolism and excretion together are called elimination and determine clearance and half-life.', 'admin', 'published', 4, true, '[["absorption"], ["distribution"], ["metabolism", "biotransformation"], ["excretion", "elimination"]]'::jsonb, 'saq p.134 Q2, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-0fda49136e', 'pharm-absorption', 'saq', 'Define absorption.', '[]'::jsonb, 'The passage (transfer) of a drug from its site of administration into the systemic circulation (blood), across biological membranes.', '[]'::jsonb, 'Absorption applies to every route except intravenous, where the drug is placed directly in the blood. Its rate determines how quickly the effect begins, and its extent contributes to bioavailability, the fraction of the dose reaching the systemic circulation unchanged.', 'admin', 'published', 2, true, '[["site of administration"], ["blood", "circulation", "bloodstream", "plasma"], ["membranes", "membrane"]]'::jsonb, 'saq p.134 Q3, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-42baf86538', 'pharm-absorption', 'saq', 'What are the mechanisms by which drugs are absorbed (transported) across membranes? Describe them briefly.', '[]'::jsonb, 'Passive diffusion: non-ionised, lipid-soluble drug moves down its concentration gradient, no energy or carrier. Filtration / bulk flow through aqueous pores or capillary gaps. Facilitated diffusion: carrier-mediated, down the gradient, no energy. Active transport: carrier-mediated, against the gradient, needs energy, saturable. Endocytosis / pinocytosis: uptake in membrane vesicles. Ion-pair transport of ionised drugs.', '[]'::jsonb, 'Most drugs cross membranes by passive diffusion of their non-ionised, lipid-soluble form, so pKa and local pH matter. Carrier-mediated processes are saturable and subject to competition, which explains some drug interactions; active transport alone can move a drug against its gradient.', 'admin', 'published', 4, true, '[["passive diffusion", "simple diffusion"], ["filtration", "bulk flow", "aqueous pores"], ["facilitated diffusion", "carrier mediated"], ["active transport"], ["endocytosis", "pinocytosis"], ["ion-pair", "ion pair"]]'::jsonb, 'saq p.134 Q4, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-2d3492860a', 'pharm-absorption', 'saq', 'What are the factors that affect drug absorption?', '[]'::jsonb, 'Drug factors: lipid solubility (lipid-water partition coefficient), degree of ionisation (pKa and pH), molecular size, particle size and formulation / physical state, concentration at the site. Patient / site factors: surface area, blood flow to the site, gastric emptying time and intestinal motility, pH, presence of food or other drugs, first-pass metabolism, thickness and integrity of the membrane, route of administration.', '[]'::jsonb, 'Absorption is fastest for small, lipid-soluble, non-ionised molecules presented in solution to a large, well-perfused surface, which is why the small intestine absorbs most oral drugs. Food and other drugs can bind a drug: tetracyclines, for example, chelate calcium in milk.', 'admin', 'published', 5, true, '[["lipid solubility", "partition coefficient"], ["ionisation", "ionization", "pka", "ph"], ["molecular size", "particle size", "formulation", "dosage form"], ["surface area"], ["blood flow"], ["gastric emptying", "motility"], ["food", "drug interactions"], ["first pass", "first-pass"], ["concentration"], ["route"]]'::jsonb, 'saq p.135 Q5, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-ec728ff642', 'pharm-transport-and-distribution', 'saq', 'Define drug distribution.', '[]'::jsonb, 'The reversible transfer of a drug from the blood (systemic circulation) to the tissues and body fluid compartments, and between one location in the body and another.', '[]'::jsonb, 'Distribution is reversible: drug moves back into plasma as plasma levels fall, in contrast to elimination, which is an irreversible loss. Its extent is expressed as the apparent volume of distribution, which is large for lipid-soluble, tissue-bound drugs.', 'admin', 'published', 2, true, '[["reversible"], ["blood", "circulation", "plasma"], ["tissues", "tissue", "one location to another", "compartments"]]'::jsonb, 'saq p.136 Q6, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-4d94f5dddb', 'pharm-transport-and-distribution', 'saq', 'What are the factors that affect drug distribution?', '[]'::jsonb, 'Lipid solubility; degree of ionisation (pKa, pH); molecular size; plasma protein binding; tissue (cellular) binding; regional blood flow / vascularity; capillary permeability and special barriers (blood-brain barrier, placenta); transport mechanisms (e.g. P-glycoprotein); disease states, age, pregnancy and body composition; drug interactions (displacement).', '[]'::jsonb, 'Only free, non-ionised, lipid-soluble drug leaves the capillaries readily. Well-perfused organs (brain, heart, kidney, liver) receive drug first, with later redistribution to muscle and fat. Tight junctions and efflux pumps at the blood-brain barrier keep out polar drugs.', 'admin', 'published', 5, true, '[["lipid solubility"], ["ionisation", "ionization", "ph"], ["molecular size"], ["protein binding", "plasma protein", "plasma proteins"], ["tissue binding", "cellular binding"], ["blood flow", "vascularity", "perfusion"], ["blood brain barrier", "blood-brain barrier", "placenta", "barriers", "capillary permeability"], ["transporters", "p-glycoprotein", "transport mechanisms"], ["disease", "drug interactions", "age", "pregnancy"]]'::jsonb, 'saq p.136 Q7, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-19ae8d68f0', 'pharm-transport-and-distribution', 'saq', 'Which plasma protein is the main binding protein for acidic drugs such as warfarin, phenytoin and NSAIDs?', '[]'::jsonb, 'Albumin', '["Serum albumin", "Plasma albumin", "Human serum albumin"]'::jsonb, 'Albumin is the most abundant plasma protein and carries mainly acidic and neutral drugs at its two principal binding sites. Basic drugs bind mostly to alpha-1 acid glycoprotein and lipoproteins. Only unbound drug is active, distributed and eliminated.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.138 Q9b, Feb pharmacokinetics tutorial. The student''s notes on the scan have the two answers reversed (albumin under basic drugs); the pharmacologically correct pairing is used. Drug examples added so one answer fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-08dcdd824e', 'pharm-transport-and-distribution', 'saq', 'Which plasma protein is the main binding protein for basic drugs such as lidocaine, propranolol and quinidine?', '[]'::jsonb, 'Alpha-1 acid glycoprotein', '["Alpha1-acid glycoprotein", "α1-acid glycoprotein", "Alpha 1 acid glycoprotein", "Acid glycoprotein", "Orosomucoid", "AAG", "AGP"]'::jsonb, 'Alpha-1 acid glycoprotein (orosomucoid) binds basic drugs; lipoproteins also contribute. It is an acute-phase protein, so its level rises in inflammation, trauma, myocardial infarction and malignancy, lowering the free fraction of basic drugs. Albumin, by contrast, binds mainly acidic drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.138 Q9a, Feb pharmacokinetics tutorial. The student''s notes on the scan have the two answers reversed; the pharmacologically correct pairing is used. Drug examples added so one answer fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-66436aecde', 'pharm-transport-and-distribution', 'saq', 'What are the properties of albumin as a drug-binding protein?', '[]'::jsonb, 'Most abundant plasma protein (made in the liver); binds mainly acidic and neutral drugs (also some basic drugs); high capacity; binding is reversible and saturable; two main binding sites - site I (warfarin site: warfarin, sulfonamides, sulfonylureas, phenytoin, bilirubin) and site II (diazepam site: benzodiazepines, ibuprofen, fatty acids); drugs and endogenous ligands such as bilirubin compete and can displace one another; bound drug is inactive and acts as a reservoir.', '[]'::jsonb, 'Albumin has a large binding capacity, so it carries many drugs and endogenous substances. Because binding sites are shared, one drug can displace another or displace bilirubin; sulfonamides displacing bilirubin in the newborn cause kernicterus. Low albumin raises the free fraction of highly bound drugs.', 'admin', 'draft', 3, true, '[["most abundant", "abundant"], ["acidic", "acidic drugs"], ["two binding sites", "site i", "site ii", "binding sites", "warfarin site", "diazepam site"], ["reversible", "saturable"], ["competition", "displacement", "displace"], ["bilirubin", "fatty acids", "endogenous"], ["high capacity", "reservoir"]]'::jsonb, 'saq p.138 Q10, Feb pharmacokinetics tutorial. Open-ended tutorial question; the model answer is a standard textbook summary rather than the tutor''s own list.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-e083eb4394', 'pharm-effects-of-disease-on-drug-disposition', 'saq', 'What disease states affect the plasma protein binding of drugs?', '[]'::jsonb, 'Reduced albumin (less binding, higher free fraction): liver disease / hepatic failure, nephrotic syndrome and renal failure (uraemia also alters binding), malnutrition, burns, protein-losing enteropathy, pregnancy, old age. Hyperbilirubinaemia: bilirubin competes for albumin sites. Raised alpha-1 acid glycoprotein (more binding of basic drugs): inflammatory states, trauma, surgery, burns, infection, myocardial infarction, rheumatoid arthritis, Crohn''s disease, malignancy.', '[]'::jsonb, 'Conditions that lower albumin (reduced synthesis in liver disease and malnutrition, or loss in nephrotic syndrome and burns) increase the free fraction of acidic drugs such as phenytoin. Acute-phase rises in alpha-1 acid glycoprotein do the opposite for basic drugs such as lidocaine and quinine.', 'admin', 'published', 4, true, '[["liver disease", "hepatic failure", "cirrhosis"], ["nephrotic syndrome", "renal failure", "uraemia", "kidney disease"], ["malnutrition", "hypoalbuminaemia", "hypoalbuminemia"], ["burns", "trauma", "surgery"], ["inflammation", "inflammatory", "infection", "myocardial infarction", "rheumatoid", "crohn"], ["hyperbilirubinaemia", "bilirubin", "jaundice"], ["pregnancy"]]'::jsonb, 'saq p.139 Q11, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-5c85203eff', 'pharm-transport-and-distribution', 'saq', 'What are the effects of tissue binding of drugs?', '[]'::jsonb, 'Any 3 of: increases the apparent volume of distribution and lowers plasma concentration; creates a tissue reservoir that prolongs half-life and duration of action; slows metabolism and excretion (bound drug is not available for elimination); can cause local toxicity where the drug accumulates (aminoglycosides in kidney and inner ear, tetracyclines in bone and teeth, chloroquine in retina); can be useful therapeutically (bisphosphonates binding bone in osteoporosis).', '[]'::jsonb, 'Drug held in tissue is hidden from the liver and kidney, so it is eliminated slowly and leaches back into plasma, prolonging its effect. Accumulation explains organ-specific toxicity, as with aminoglycosides in renal cortex and cochlea, and benefit when the binding site is the target.', 'admin', 'published', 3, true, '[["volume of distribution", "vd"], ["half-life", "half life", "duration of action", "reservoir", "prolongs"], ["decreases metabolism", "slows elimination", "slows excretion", "delays elimination"], ["toxicity", "accumulation", "toxic"], ["bisphosphonates", "bone", "therapeutic"]]'::jsonb, 'saq p.139 Q12, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-ec9f1788c9', 'pharm-excretion', 'saq', 'What are the routes of drug elimination (excretion)?', '[]'::jsonb, 'Renal (urine) - the main route; biliary / faecal; pulmonary (exhaled air, for gases and volatile drugs); breast milk; sweat; saliva; tears; hair and skin.', '[]'::jsonb, 'The kidney excretes water-soluble drugs and metabolites; large conjugates leave in bile and may be reabsorbed (enterohepatic circulation). Lungs excrete volatile anaesthetics and alcohol. Minor routes matter clinically: breast milk exposes the infant, and hair and saliva are used for drug testing.', 'admin', 'published', 5, true, '[["urine", "renal", "kidney"], ["bile", "biliary", "faeces", "feces", "faecal"], ["lungs", "exhaled air", "exhalation", "pulmonary", "breath"], ["breast milk", "milk"], ["sweat"], ["saliva"], ["tears"], ["hair", "skin"]]'::jsonb, 'saq p.140 Q13, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-7a6e7179e1', 'pharm-time-course-of-drug-action', 'saq', 'What are the two types of kinetics of drug elimination (metabolism)? Explain each.', '[]'::jsonb, 'First-order (linear) kinetics: a constant fraction (proportion) of drug is eliminated per unit time; the rate is proportional to plasma concentration; half-life is constant; applies to most drugs at therapeutic doses. Zero-order (saturation, non-linear) kinetics: a constant amount of drug is eliminated per unit time, regardless of concentration, because the enzymes are saturated; half-life is not constant; examples: ethanol, phenytoin, high-dose aspirin.', '[]'::jsonb, 'With first-order kinetics, doubling the dose doubles the steady-state concentration. Once the eliminating enzymes are saturated, elimination becomes zero-order and a small dose increase causes a disproportionate rise in plasma level, which is why phenytoin doses are adjusted in small steps.', 'admin', 'published', 4, true, '[["first order", "first-order", "linear"], ["constant fraction", "proportional to concentration", "constant proportion", "depends on concentration"], ["zero order", "zero-order", "saturation", "non-linear"], ["constant amount", "independent of concentration", "saturated"], ["ethanol", "alcohol", "phenytoin", "aspirin"], ["half-life constant", "constant half-life"]]'::jsonb, 'saq p.140 Q14-15, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-807c9eb71e', 'pharm-biotransformation', 'saq', 'What are the phases of drug metabolism?', '[]'::jsonb, 'Phase I (functionalisation / non-synthetic): introduces or unmasks a polar group (-OH, -NH2, -SH) by oxidation, reduction or hydrolysis, mainly by cytochrome P450 enzymes. Phase II (conjugation / synthetic): couples the drug or its phase I metabolite to an endogenous substance (glucuronic acid, sulfate, acetate, glycine, glutathione, methyl group) to form a polar, usually inactive, readily excreted product.', '[]'::jsonb, 'Metabolism converts lipid-soluble drugs into polar compounds that the kidney can excrete instead of reabsorbing. The phases are not always sequential: isoniazid is acetylated (phase II) before it is hydrolysed, and some drugs undergo only one phase.', 'admin', 'published', 2, true, '[["phase i", "phase 1", "functionalisation", "functionalization", "non-synthetic"], ["phase ii", "phase 2", "conjugation", "synthetic"], ["oxidation", "reduction", "hydrolysis"], ["glucuronidation", "sulfation", "acetylation"]]'::jsonb, 'saq p.140 Q16, Feb pharmacokinetics tutorial. The student''s notes list hydroxylation under phase II; hydroxylation is a phase I oxidation and was left out of the phase II answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-0a87b1372a', 'pharm-biotransformation', 'saq', 'Give two examples of reactions in each phase of drug metabolism (phase I and phase II).', '[]'::jsonb, 'Phase I: oxidation (hydroxylation, dealkylation, deamination), reduction, hydrolysis. Phase II: glucuronidation, sulfation, acetylation, methylation, glycine (amino acid) conjugation, glutathione conjugation.', '[]'::jsonb, 'Phase I reactions are mostly oxidations carried out by microsomal cytochrome P450 enzymes. Phase II reactions are carried out by transferases; glucuronidation by UDP-glucuronosyltransferase is the commonest and is deficient in neonates, which underlies grey baby syndrome with chloramphenicol.', 'admin', 'published', 4, true, '[["oxidation", "hydroxylation", "dealkylation"], ["reduction", "hydrolysis"], ["glucuronidation", "glucuronide", "glucuronic acid"], ["sulfation", "sulphation", "acetylation", "methylation", "glycine conjugation", "glutathione conjugation"]]'::jsonb, 'saq p.141 Q17, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-3eb12fc064', 'pharm-genetic-medicine', 'saq', 'Give examples of genetic variability in drug metabolism or response.', '[]'::jsonb, 'Any 3 of: acetylator status (NAT2) - slow acetylators get toxicity from isoniazid (neuropathy), hydralazine and procainamide (lupus), sulfonamides; CYP2D6 polymorphism - poor metabolisers get no analgesia from codeine, ultra-rapid metabolisers get morphine toxicity; pseudocholinesterase deficiency - prolonged apnoea after suxamethonium; G6PD deficiency - haemolysis with primaquine, sulfonamides, dapsone; TPMT deficiency - myelosuppression with azathioprine / mercaptopurine; CYP2C9 / VKORC1 variants - warfarin sensitivity; malignant hyperthermia with halothane and suxamethonium.', '[]'::jsonb, 'Inherited differences in drug-metabolising enzymes produce distinct groups of patients. Slow acetylators accumulate isoniazid and hydralazine; CYP2D6 poor metabolisers cannot convert codeine to morphine; and atypical plasma cholinesterase leaves suxamethonium unhydrolysed, prolonging paralysis and apnoea after an ordinary dose.', 'admin', 'published', 3, true, '[["acetylator", "acetylation", "nat2", "isoniazid", "hydralazine"], ["cyp2d6", "codeine", "poor metaboliser", "ultra-rapid"], ["pseudocholinesterase", "butyrylcholinesterase", "suxamethonium", "succinylcholine"], ["g6pd", "primaquine", "haemolysis"], ["tpmt", "azathioprine", "mercaptopurine"], ["warfarin", "cyp2c9", "vkorc1"], ["malignant hyperthermia"]]'::jsonb, 'saq p.141 Q18, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-55b010190d', 'pharm-biotransformation', 'saq', 'List examples of enzyme inducers (at least four).', '[]'::jsonb, 'Any 4 of: rifampicin; carbamazepine; phenytoin; phenobarbital (barbiturates); griseofulvin; chronic alcohol; St John''s wort; tobacco smoke; efavirenz / nevirapine.', '[]'::jsonb, 'Inducers increase the synthesis of cytochrome P450 enzymes by activating nuclear receptors such as PXR and CAR. The effect takes one to two weeks to develop and to wear off. Rifampicin is the most potent, causing failure of oral contraceptives, warfarin and antiretrovirals.', 'admin', 'published', 4, true, '[["rifampicin", "rifampin"], ["carbamazepine"], ["phenytoin"], ["phenobarbital", "phenobarbitone", "barbiturates"], ["griseofulvin"], ["alcohol", "chronic alcohol", "ethanol"], ["st john''s wort", "st johns wort"], ["smoking", "tobacco"], ["efavirenz", "nevirapine"]]'::jsonb, 'saq p.141 Q19, Feb pharmacokinetics tutorial. The student''s mnemonic (SCRAP GP) lists sulphonylureas as inducers; this is a popular mnemonic entry but not well supported, so it was left out of the model answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-56295dd785', 'pharm-drug-interactions', 'saq', 'What are the consequences of enzyme induction for co-administered drugs?', '[]'::jsonb, 'Metabolism of the co-administered drug increases, so its plasma concentration and half-life fall and its effect is reduced: therapeutic failure (e.g. oral contraceptive failure, loss of warfarin anticoagulation, transplant rejection with ciclosporin); higher doses are needed. Prodrugs are activated faster and toxic metabolites may increase (e.g. paracetamol hepatotoxicity). Stopping the inducer can cause toxicity if the dose is not reduced.', '[]'::jsonb, 'More enzyme means faster clearance of any drug that is a substrate, so levels fall and treatment may fail unless the dose is raised. The exception is when the metabolite is the active or toxic species: induction then increases effect or toxicity.', 'admin', 'published', 3, true, '[["increased metabolism", "faster metabolism", "increased clearance"], ["decreased plasma concentration", "lower plasma level", "reduced half-life", "shorter half-life", "decreased half-life"], ["therapeutic failure", "reduced effect", "treatment failure", "contraceptive failure"], ["increase dose", "dose adjustment"], ["toxic metabolite", "toxic metabolites", "prodrug", "paracetamol"]]'::jsonb, 'saq p.141 Q19b, Feb pharmacokinetics tutorial. The student''s notes on the scan say induction ''increases T1/2''; this is wrong (half-life is shortened) and was corrected.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-905e82cc15', 'pharm-biotransformation', 'saq', 'List examples of enzyme inhibitors (at least four).', '[]'::jsonb, 'Any 4 of: cimetidine; ketoconazole, fluconazole, itraconazole; erythromycin, clarithromycin; ciprofloxacin; isoniazid; chloramphenicol; sodium valproate; ritonavir (protease inhibitors); omeprazole; metronidazole; sulfonamides; amiodarone; verapamil, diltiazem; grapefruit juice; acute alcohol; fluoxetine.', '[]'::jsonb, 'Inhibitors compete for, or inactivate, cytochrome P450 enzymes. Unlike induction, the effect begins within a day or two. Substrate levels rise, causing toxicity with narrow-index drugs such as warfarin, theophylline and phenytoin; ritonavir''s inhibition is used deliberately to boost other protease inhibitors.', 'admin', 'published', 4, true, '[["cimetidine"], ["ketoconazole", "fluconazole", "itraconazole", "azoles"], ["erythromycin", "clarithromycin", "macrolides"], ["ciprofloxacin"], ["isoniazid"], ["chloramphenicol"], ["valproate", "sodium valproate"], ["ritonavir", "protease inhibitors"], ["omeprazole"], ["metronidazole"], ["sulfonamides", "sulphonamides"], ["amiodarone", "verapamil", "diltiazem"], ["grapefruit", "grapefruit juice"], ["alcohol"]]'::jsonb, 'saq p.142 Q20, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-171f6b1d07', 'pharm-biotransformation', 'saq', 'Which cytochrome P450 enzyme is not inducible by drugs?', '[]'::jsonb, 'CYP2D6', '["2D6", "CYP 2D6", "Cytochrome P450 2D6", "CYP450 2D6", "P450 2D6"]'::jsonb, 'CYP2D6 metabolises about a quarter of drugs (codeine, many antidepressants, beta-blockers) but, unlike CYP3A4, CYP2C9 or CYP1A2, is not appreciably induced by rifampicin or anticonvulsants. Variation in its activity comes instead from genetic polymorphism (poor to ultra-rapid metabolisers) and from inhibitors such as fluoxetine and quinidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'saq p.142 Q21, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-31f912f21a', 'pharm-excretion', 'saq', 'List the processes involved in the renal excretion of drugs.', '[]'::jsonb, 'Glomerular filtration (free, unbound drug); active tubular secretion (proximal tubule, carriers for organic acids and bases); passive tubular reabsorption (of lipid-soluble, non-ionised drug). Net excretion = filtration + secretion - reabsorption.', '[]'::jsonb, 'Only unbound drug is filtered, but secretion can clear even protein-bound drug and is a site of competition (probenecid and penicillin). Reabsorption depends on ionisation, so alkalinising the urine traps weak acids such as aspirin in the tubule and speeds their excretion.', 'admin', 'published', 3, true, '[["glomerular filtration", "filtration"], ["tubular secretion", "active secretion", "secretion"], ["tubular reabsorption", "reabsorption", "passive reabsorption"]]'::jsonb, 'saq p.142 Q22, Feb pharmacokinetics tutorial') on conflict (id) do nothing;
